const RowsUniqueSelectorResolverContext = struct {
    source: ?table_reads.TableReadSource,

    fn resolver(self: *@This()) ?relational_rows_api.UniqueSelectorResolver {
        if (self.source == null) return null;
        return .{
            .ptr = self,
            .resolve = resolve,
            .resolve_temporal = resolveTemporal,
            .resolve_temporal_overlap = resolveTemporalOverlap,
            .resolve_primary = resolvePrimary,
            .lookup_primary = lookupPrimary,
        };
    }

    fn resolve(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        constraint_name: []const u8,
        encoded_value: []const u8,
    ) !?[]u8 {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        const source = self.source orelse return error.UnsupportedOperation;
        return source.relationalUniqueOwnerLookup(alloc, table_name, constraint_name, encoded_value, .read_index) catch |err| switch (err) {
            error.NotFound => null,
            else => err,
        };
    }

    fn resolveTemporal(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        constraint_name: []const u8,
        encoded_value: []const u8,
        encoded_point: []const u8,
    ) !?[]u8 {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        const source = self.source orelse return error.UnsupportedOperation;
        return source.relationalTemporalUniqueOwnerLookup(alloc, table_name, constraint_name, encoded_value, encoded_point, .read_index) catch |err| switch (err) {
            error.NotFound => null,
            else => err,
        };
    }

    fn resolveTemporalOverlap(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        constraint_name: []const u8,
        encoded_value: []const u8,
        encoded_start: []const u8,
        encoded_end: []const u8,
    ) !?[]u8 {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        const source = self.source orelse return error.UnsupportedOperation;
        return source.relationalTemporalUniqueOverlapOwnerLookup(alloc, table_name, constraint_name, encoded_value, encoded_start, encoded_end, .read_index) catch |err| switch (err) {
            error.NotFound => null,
            else => err,
        };
    }

    fn resolvePrimary(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        physical_key: []const u8,
    ) !bool {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        const source = self.source orelse return error.UnsupportedOperation;
        var lookup = (try source.lookup(alloc, table_name, physical_key, .{}, .read_index)) orelse return false;
        lookup.deinit(alloc);
        return true;
    }

    fn lookupPrimary(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        physical_key: []const u8,
    ) !?relational_rows_api.ResolvedPrimaryRow {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        const source = self.source orelse return error.UnsupportedOperation;
        const lookup = (try source.lookup(alloc, table_name, physical_key, .{}, .read_index)) orelse return null;
        return .{
            .json = lookup.json,
            .version = lookup.version,
        };
    }
};

const RowsSequenceDefaultResolverContext = struct {
    source: StatusSource,

    fn resolver(self: *@This()) relational_rows_api.SequenceDefaultResolver {
        return .{
            .ptr = self,
            .next_value_json_alloc = nextValueJsonAlloc,
        };
    }

    fn nextValueJsonAlloc(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        request: relational_rows_api.SequenceDefaultRequest,
    ) ![]u8 {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        const database_name = if (request.database.len != 0) request.database else tables_api.default_database_name;
        const namespace_name = if (request.schema.len != 0) request.schema else tables_api.default_namespace_name;
        const value = try self.source.allocateSequenceValue(alloc, database_name, namespace_name, request.sequence);
        return try std.fmt.allocPrint(alloc, "{d}", .{value});
    }
};

const RowsScalarSubqueryDefaultResolverContext = struct {
    source: StatusSource,
    table_reads: table_reads.TableReadSource,

    fn resolver(self: *@This()) relational_rows_api.ScalarSubqueryDefaultResolver {
        return .{
            .ptr = self,
            .value_json_alloc = valueJsonAlloc,
        };
    }

    fn valueJsonAlloc(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        request: relational_rows_api.ScalarSubqueryDefaultRequest,
    ) ![]u8 {
        const self: *@This() = @ptrCast(@alignCast(ptr));
        var plan = try relational_rows_api.scalarSubqueryDefaultPlanFromQueryJsonAlloc(alloc, request.query_json);
        defer plan.deinit(alloc);

        const schema = try runtimeSchemaForScalarSubqueryDefaultAlloc(alloc, self.source, plan.table_name);
        defer runtime_schema_mod.freeSchema(alloc, schema);

        var result = (try self.table_reads.rowsQueryPlan(
            alloc,
            plan.table_name,
            schema,
            .{ .query = plan.query },
            .read_index,
        )) orelse return error.TableNotFound;
        defer result.deinit(alloc);

        if (result.rows.len > 1) return error.InvalidRowsRequest;
        if (result.rows.len == 0) return try alloc.dupe(u8, "null");
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, result.rows[0], .{}) catch return error.InvalidRowsRequest;
        defer parsed.deinit();
        const value = scalarDefaultJsonValueAtPath(parsed.value, plan.output_field) orelse return try alloc.dupe(u8, "null");
        return try std.json.Stringify.valueAlloc(alloc, value.*, .{});
    }
};

fn runtimeSchemaForScalarSubqueryDefaultAlloc(
    alloc: std.mem.Allocator,
    source: StatusSource,
    table_name: []const u8,
) !runtime_schema_mod.TableSchema {
    var snapshot = (try source.adminSnapshot()) orelse return error.TableNotFound;
    defer source.freeAdminSnapshot(&snapshot);
    const table = tables_api.findTableByName(&snapshot, table_name) orelse return error.TableNotFound;
    if (table.schema_json.len == 0) return error.InvalidRowsRequest;
    var parsed_schema = schema_mod.parseValidatedTableSchema(alloc, table.schema_json) catch return error.InvalidRowsRequest;
    defer parsed_schema.deinit(alloc);
    const derived_schema = schema_mod.deriveRuntimeTableSchema(alloc, parsed_schema) catch return error.InvalidRowsRequest;
    if (derived_schema.storage_mode != .relational or derived_schema.primary_key == null) {
        runtime_schema_mod.freeSchema(alloc, derived_schema);
        return error.InvalidRowsRequest;
    }
    return derived_schema;
}

fn scalarDefaultJsonValueAtPath(root: std.json.Value, path: []const u8) ?*const std.json.Value {
    if (root != .object) return null;
    var current: *const std.json.Value = &root;
    var parts = std.mem.splitScalar(u8, path, '.');
    while (parts.next()) |part| {
        if (part.len == 0 or current.* != .object) return null;
        current = current.object.getPtr(part) orelse return null;
    }
    return current;
}

