    fn makeServiceVTable(comptime T: type) VTable {
        const Gen = struct {
            fn cast(ptr: *anyopaque) *T {
                return @ptrCast(@alignCast(ptr));
            }

            fn status(ptr: *anyopaque) anyerror!metadata_api.MetadataStatus {
                return try cast(ptr).status();
            }

            fn adminSnapshot(ptr: *anyopaque) anyerror!metadata_api.AdminSnapshot {
                return try cast(ptr).adminSnapshot();
            }

            fn cachedAdminSnapshot(ptr: *anyopaque) anyerror!?metadata_api.AdminSnapshot {
                return try cast(ptr).adminSnapshot();
            }

            fn ensureLinearizableRead(ptr: *anyopaque) anyerror!void {
                return try cast(ptr).ensureLinearizableRead();
            }

            fn freeAdminSnapshot(ptr: *anyopaque, snapshot: *metadata_api.AdminSnapshot) void {
                cast(ptr).freeAdminSnapshot(snapshot);
            }

            fn createTable(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, req: tables_api.CreateTableRequest) anyerror!void {
                return try createTableOnService(cast(ptr), alloc, table_name, req);
            }

            fn createCatalogTable(ptr: *anyopaque, alloc: std.mem.Allocator, target: catalog_resources.TableTarget, req: tables_api.CreateTableRequest) anyerror!void {
                return try createCatalogTableOnService(cast(ptr), alloc, target, req);
            }

            fn replaceTableDefinition(ptr: *anyopaque, expected: metadata_table_manager.TableRecord, replacement: metadata_table_manager.TableRecord) anyerror!void {
                return try replaceTableDefinitionOnService(cast(ptr), expected, replacement);
            }

            fn restoreTable(
                ptr: *anyopaque,
                alloc: std.mem.Allocator,
                table_name: []const u8,
                location_uri: []const u8,
                connection: []const u8,
                artifact_backup_id: []const u8,
                manifest: *const backups_api.TableBackupManifest,
            ) anyerror!void {
                return try persistRestoreTableIntent(cast(ptr), alloc, table_name, location_uri, connection, artifact_backup_id, manifest);
            }

            fn dropTable(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8) anyerror!void {
                return try dropTableOnService(cast(ptr), alloc, table_name);
            }

            fn dropCatalogTable(ptr: *anyopaque, alloc: std.mem.Allocator, target: catalog_resources.TableTarget) anyerror!void {
                return try dropCatalogTableOnService(cast(ptr), alloc, target);
            }

            fn updateSchema(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, schema_json: []const u8) anyerror!void {
                _ = try updateSchemaOnService(cast(ptr), alloc, table_name, schema_json);
            }

            fn updateSchemaVersioned(ptr: *anyopaque, alloc: std.mem.Allocator, table_name: []const u8, schema_json: []const u8) anyerror!u32 {
                return try updateSchemaOnService(cast(ptr), alloc, table_name, schema_json);
            }

            fn applyRelationalSqlDdlPlanWithSession(
                ptr: *anyopaque,
                alloc: std.mem.Allocator,
                plan: *sql_adapter.DurableSqlPlan,
                session: catalog_resources.SqlCatalogSession,
            ) anyerror!tables_api.AppliedRelationalSqlDdlRecord {
                return try api_http_server.applyRelationalSqlDdlPlanOnServiceWithSession(cast(ptr), alloc, plan, session);
            }

            fn compareAndSwapTableSchema(
                ptr: *anyopaque,
                request: metadata_table_manager.TableSchemaCompareAndSwapRequest,
            ) anyerror!void {
                const svc = cast(ptr);
                if (comptime @hasDecl(T, "compareAndSwapTableSchema")) {
                    return try svc.compareAndSwapTableSchema(request);
                }
                return error.UnsupportedOperation;
            }

            fn upsertTableEmptyingJob(ptr: *anyopaque, record: metadata_table_manager.TableEmptyingJobRecord) anyerror!void {
                const svc = cast(ptr);
                if (comptime @hasDecl(T, "upsertTableEmptyingJob")) {
                    return try svc.upsertTableEmptyingJob(record);
                }
                return error.UnsupportedOperation;
            }

            fn upsertTable(ptr: *anyopaque, record: metadata_table_manager.TableRecord) anyerror!void {
                const svc = cast(ptr);
                if (comptime @hasDecl(T, "upsertTable")) {
                    return try svc.upsertTable(record);
                }
                return error.UnsupportedOperation;
            }

            fn upsertSequence(ptr: *anyopaque, record: metadata_table_manager.SequenceRecord) anyerror!void {
                const svc = cast(ptr);
                if (comptime @hasDecl(T, "upsertSequence")) {
                    return try svc.upsertSequence(record);
                }
                return error.UnsupportedOperation;
            }

