    ) ApiHttpServer {
        return ApiHttpServer.initWithRequestAllocator(
            owner_alloc,
            platform.allocator.processAllocator(std.heap.smp_allocator),
            cfg,
            source,
            table_read_source,
            table_write_source,
        );
    }

