    pub fn runSessionMaintenanceOnce(self: *ApiHttpServer) !void {
        self.retryPendingTransactionRecovery(32) catch |err| {
            std.log.warn("failed to advance stable transaction recovery err={s}", .{@errorName(err)});
        };
        try self.maybeCleanupExpiredSessions();
        try self.maybeRenewOwnedSessionLeases();
        // Durable named-index cancellation is correctness work, not a client
        // polling obligation. Advance at most one queued pass per supervisor
        // tick; the repair-job FIFO and BackendRuntime maintenance queue keep
        // this O(1), bounded, and fair with other maintenance.
        self.resumePendingDurableRepairCancellationOnce() catch |err| {
            std.log.warn("failed to resume durable table repair cancellation err={s}", .{@errorName(err)});
        };
        self.join_job_store.cleanupExpiredJoinJobs();
        _ = try self.runSchemaRewriteCatalogCatchupOnce();
        _ = try self.runTableEmptyingCatalogCatchupOnce();
    }

    pub fn runSchemaRewriteCatalogCatchupOnce(self: *ApiHttpServer) !usize {
        const runtime = self.cfg.backend_runtime orelse return 0;
        const write_source = self.table_writes orelse return 0;
        var snapshot = (try self.source.adminSnapshot()) orelse return 0;
        defer self.source.freeAdminSnapshot(&snapshot);

        var scheduled_table_ids = std.ArrayListUnmanaged(u64).empty;
        defer scheduled_table_ids.deinit(self.alloc);

        var scheduled: usize = 0;
        for (snapshot.schema_rewrite_jobs) |job| {
            if (!schemaRewriteJobNeedsCatalogCatchup(job)) continue;
            if (schemaRewriteGenerationHasInvalidJob(&snapshot, job)) continue;
            if (schemaRewriteCatchupAlreadyScheduled(scheduled_table_ids.items, job.table_id)) continue;
            const table = schemaRewriteSnapshotTableById(&snapshot, job.table_id) orelse continue;
            if (!try self.submitSchemaRewriteWakeForTable(runtime, write_source, table)) continue;
            try scheduled_table_ids.append(self.alloc, job.table_id);
            scheduled += 1;
        }
        return scheduled;
    }

    pub fn runTableEmptyingCatalogCatchupOnce(self: *ApiHttpServer) !usize {
        const runtime = self.cfg.backend_runtime orelse return 0;
        const write_source = self.table_writes orelse return 0;
        var snapshot = (try self.source.adminSnapshot()) orelse return 0;
        defer self.source.freeAdminSnapshot(&snapshot);

        var scheduled_table_ids = std.ArrayListUnmanaged(u64).empty;
        defer scheduled_table_ids.deinit(self.alloc);

        const catalog = self.catalogSource();
        var scheduled: usize = 0;
        for (snapshot.table_emptying_jobs) |job| {
            if (!tableEmptyingJobNeedsCatalogCatchup(job)) continue;
            if (schemaRewriteCatchupAlreadyScheduled(scheduled_table_ids.items, job.table_id)) continue;
            const table = schemaRewriteSnapshotTableById(&snapshot, job.table_id) orelse continue;
            const repaired = catalog_jobs.repairMissingTableEmptyingBarrierJobsForTableIdAlloc(self.alloc, catalog, job.table_id) catch |err| switch (err) {
                error.UnsupportedOperation => 0,
                error.TableNotFound => 0,
                else => return err,
            };
            if (std.mem.eql(u8, job.state, metadata_table_manager.table_emptying_invalid) and repaired == 0) continue;
            if (!try self.submitTableEmptyingWakeForTable(runtime, write_source, table)) continue;
            try scheduled_table_ids.append(self.alloc, job.table_id);
            scheduled += 1;
        }
        return scheduled;
    }

    fn retryPendingTransactionRecovery(self: *ApiHttpServer, limit: usize) !void {
        const source = self.table_writes orelse return;
        const pending = try self.txn_sessions.listPendingRecoveryIds(self.alloc, limit);
        defer self.alloc.free(pending);
        const local_node_id = self.localSessionNodeId();
        const now_ns = platform_time.realtimeNs();
        for (pending) |txn_id| {
            var recovery = (self.txn_sessions.claimPendingRecovery(self.alloc, txn_id, local_node_id, now_ns) catch |err| {
                std.log.warn("stable transaction recovery claim deferred txn_id={x} err={s}", .{ txn_id, @errorName(err) });
                continue;
            }) orelse continue;
            defer recovery.deinit(self.alloc);
            switch (recovery) {
                .acknowledge => |acknowledgement| {
                    const acknowledged = source.acknowledgeTransactionCommit(
                        self.alloc,
                        acknowledgement.txn_id,
                        acknowledgement.coordinator_group_id,
                        acknowledgement.coordinator_table_name,
                    ) catch |err| {
                        std.log.warn("stable transaction coordinator acknowledgement maintenance deferred txn_id={x} err={s}", .{ acknowledgement.txn_id, @errorName(err) });
                        continue;
                    };
                    if (acknowledged == null) continue;
                    _ = (self.txn_sessions.markTerminalCoordinatorAcknowledged(self.alloc, acknowledgement.txn_id) catch |err| {
                        std.log.warn("stable transaction acknowledgement receipt persistence deferred txn_id={x} err={s}", .{ acknowledgement.txn_id, @errorName(err) });
                        continue;
                    }) orelse continue;
                },
                .commit => |*commit| {
                    const distributed_tables = commit.request.distributedTables(self.alloc) catch |err| {
                        std.log.err("invalid sealed stable transaction during recovery txn_id={x} err={s}", .{ txn_id, @errorName(err) });
                        _ = self.txn_sessions.remove(self.alloc, txn_id);
                        continue;
                    };
                    defer if (distributed_tables.len > 0) self.alloc.free(distributed_tables);
                    const outcome = (source.commitTransactionWithId(
                        self.alloc,
                        txn_id,
                        commit.begin_timestamp,
                        distributed_tables,
                        // Proposal-only delivery is insufficient for recovery:
                        // a new leader may discard it before apply. Upgrade
                        // only the weakest level, preserving stronger caller
                        // visibility contracts without extra hot-path work.
                        if (commit.sync_level == .propose) .write else commit.sync_level,
                    ) catch |err| switch (err) {
                        error.InvalidBatchRequest,
                        error.InvalidArgument,
                        error.InvalidGraphEdges,
                        error.UnsupportedTransformOperation,
                        error.TopologyChanged,
                        error.DecisionConflict,
                        error.DocIdentityNamespaceMismatch,
                        error.UnsupportedOperation,
                        error.TableNotFound,
                        error.UnknownGroup,
                        => {
                            _ = self.txn_sessions.remove(self.alloc, txn_id);
                            continue;
                        },
                        else => {
                            std.log.warn("stable transaction commit recovery deferred txn_id={x} err={s}", .{ txn_id, @errorName(err) });
                            continue;
                        },
                    }) orelse continue;
                    switch (outcome) {
                        .conflict => {
                            // A replayed transaction ID can only conflict when
                            // the coordinator durably chose abort.
                            _ = self.txn_sessions.remove(self.alloc, txn_id);
                        },
                        .committed => |committed| {
                            const status: transactions_api.TerminalCommitStatus = if (committed.propagation_pending)
                                .committed_recovery_pending
                            else if (committed.visibility_pending)
                                .committed_visibility_pending
                            else
                                .committed;
                            _ = (self.txn_sessions.recordTerminalCommit(
                                self.alloc,
                                txn_id,
                                status,
                                committed.coordinator_group_id,
                                committed.coordinator_table_name,
                            ) catch |err| {
                                std.log.warn("stable transaction terminal handoff persistence deferred txn_id={x} err={s}", .{ txn_id, @errorName(err) });
                                continue;
                            }) orelse continue;
                            // Pending is a durable decision, not a completed
                            // API/storage handoff. Retain the coordinator's
                            // self-participant so topology stays fenced while
                            // maintenance replays phase two under this ID.
                            if (status == .committed) {
                                if (committed.coordinator_group_id) |group_id| {
                                    const table_name = committed.coordinator_table_name orelse continue;
                                    const acknowledged = source.acknowledgeTransactionCommit(self.alloc, txn_id, group_id, table_name) catch |err| {
                                        std.log.warn("stable transaction recovered coordinator acknowledgement deferred txn_id={x} err={s}", .{ txn_id, @errorName(err) });
                                        continue;
                                    };
                                    if (acknowledged == null) continue;
                                    _ = (self.txn_sessions.markTerminalCoordinatorAcknowledged(self.alloc, txn_id) catch |err| {
                                        std.log.warn("stable transaction recovered acknowledgement receipt persistence deferred txn_id={x} err={s}", .{ txn_id, @errorName(err) });
                                        continue;
                                    }) orelse continue;
                                }
                            }
                        },
                    }
                },
            }
        }
    }

    fn resumePendingDurableRepairCancellationOnce(self: *ApiHttpServer) !void {
        if (self.table_writes == null) return;
        const encoded = (try self.repair_job_store.nextPendingDurableCancelAlloc(self.alloc)) orelse return;
        defer self.alloc.free(encoded);
        var parsed = try std.json.parseFromSlice(repair_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true });
        defer parsed.deinit();
        try self.continueDurableRepairCancellation(parsed.value.table_name, encoded);
    }

    const SessionMaintenanceWork = struct {
        server: *ApiHttpServer,

        fn run(ptr: *anyopaque) anyerror!void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try self.server.runSessionMaintenanceOnce();
        }

        fn deinit(ptr: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.server.session_maintenance_in_flight.store(false, .release);
            self.server.alloc.destroy(self);
        }
    };

    pub fn scheduleSessionMaintenance(self: *ApiHttpServer) !void {
        // The data runtime can complete many rounds per second. Rate-limit
        // submission before allocating work so an idle server does not churn
        // cleanup jobs. The worker's per-task clocks retain the configured
        // cleanup and lease-renewal cadence.
        const now_ns = platform_time.monotonicNs();
        const min_schedule_interval_ns = std.time.ns_per_s;
        const previous_ns = self.last_session_maintenance_schedule_ns.load(.acquire);
        if (previous_ns != 0 and now_ns -| previous_ns < min_schedule_interval_ns) return;
        if (self.last_session_maintenance_schedule_ns.cmpxchgStrong(previous_ns, now_ns, .acq_rel, .acquire) != null) return;
        const runtime = self.cfg.backend_runtime orelse return self.runSessionMaintenanceOnce();
        if (runtime.threaded_jobs == null or self.session_maintenance_owner_id == 0) return self.runSessionMaintenanceOnce();
        if (self.session_maintenance_in_flight.cmpxchgStrong(false, true, .acq_rel, .acquire) != null) return;
        const work = self.alloc.create(SessionMaintenanceWork) catch |err| {
            self.session_maintenance_in_flight.store(false, .release);
            return err;
        };
        work.* = .{ .server = self };
        runtime.durable_jobs.submit(.{
            .owner_id = self.session_maintenance_owner_id,
            .class = .cleanup,
            .ptr = work,
            .run = SessionMaintenanceWork.run,
            .deinit = SessionMaintenanceWork.deinit,
        }) catch |err| {
            self.alloc.destroy(work);
            self.session_maintenance_in_flight.store(false, .release);
            return err;
        };
    }

    const ClusterBackupMaintenanceWork = struct {
        server: *ApiHttpServer,
        target: ?*ClusterBackupMaintenanceTarget,

        fn waitUntilDue(self: *@This(), io: std.Io) bool {
            while (!self.server.backup_maintenance_closing.load(.acquire)) {
                const target = self.target orelse return false;
                const now_ns = platform_time.monotonicNs();
                if (now_ns >= target.next_run_monotonic_ns) return true;
                const remaining_ns = target.next_run_monotonic_ns - now_ns;
                io.sleep(
                    std.Io.Duration.fromNanoseconds(
                        @min(remaining_ns, std.time.ns_per_s),
                    ),
                    .awake,
                ) catch return false;
            }
            return false;
        }

        fn run(ptr: *anyopaque) anyerror!void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const io = self.server.sharedApiIo() orelse
                return error.BackgroundRuntimeUnavailable;
            while (self.waitUntilDue(io)) {
                const target = self.target orelse break;
                var location = backups_api.openBackupLocationWithOptions(
                    self.server.owner_alloc,
                    target.location_uri,
                    .{
                        .secret_store = self.server.cfg.secret_store,
                        .node_config = self.server.cfg.node_config,
                        .connection = target.connection,
                        .required_capability = "backup.write",
                        .io = io,
                    },
                ) catch |err| {
                    std.log.warn("cluster backup maintenance location open deferred class={s}", .{@errorName(err)});
                    self.rotateToNextTarget();
                    continue;
                };
                const now_unix_ns: u64 = @intCast(
                    std.Io.Timestamp.now(io, .real).toNanoseconds(),
                );
                _ = backups_api.reclaimStaleClusterBackupAttempts(
                    self.server.owner_alloc,
                    io,
                    &location,
                    now_unix_ns,
                ) catch |err| {
                    std.log.warn("cluster backup stale-attempt maintenance deferred class={s}", .{@errorName(err)});
                };
                location.deinit(self.server.owner_alloc);
                self.rotateToNextTarget();
            }
        }

        fn rotateToNextTarget(self: *@This()) void {
            const target = self.target orelse return;
            const now_ns = platform_time.monotonicNs();
            platform_sync.lockYielding(&self.server.backup_maintenance_mutex);
            if (now_ns -| target.last_scheduled_monotonic_ns >=
                backup_maintenance_target_retention_ns)
            {
                self.server.backup_maintenance_queue.completeActive(target);
                self.target = self.server.backup_maintenance_queue.activateNext();
                self.server.backup_maintenance_mutex.unlock();
                target.destroy(self.server.owner_alloc);
                return;
            }
            target.next_run_monotonic_ns = now_ns +| 30 * std.time.ns_per_s;
            self.server.backup_maintenance_queue.rotateActive(target);
            self.target = self.server.backup_maintenance_queue.activateNext().?;
            self.server.backup_maintenance_mutex.unlock();
        }

        fn deinit(ptr: *anyopaque) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const server = self.server;
            if (self.target) |target| {
                platform_sync.lockYielding(&server.backup_maintenance_mutex);
                server.backup_maintenance_queue.completeActive(target);
                server.backup_maintenance_mutex.unlock();
                target.destroy(server.owner_alloc);
            }
            server.owner_alloc.destroy(self);
        }
    };

    fn submitNextClusterBackupMaintenance(self: *ApiHttpServer) !void {
        if (self.backup_maintenance_closing.load(.acquire))
            return error.BackupMaintenanceUnavailable;
        const runtime = self.cfg.backend_runtime orelse
            return error.BackupMaintenanceUnavailable;
        if (runtime.threaded_jobs == null or self.backup_maintenance_owner_id == 0)
            return error.BackupMaintenanceUnavailable;

        platform_sync.lockYielding(&self.backup_maintenance_mutex);
        if (self.backup_maintenance_closing.load(.acquire)) {
            self.backup_maintenance_mutex.unlock();
            return error.BackupMaintenanceUnavailable;
        }
        const target = self.backup_maintenance_queue.activateNext() orelse {
            self.backup_maintenance_mutex.unlock();
            return;
        };
        const work = self.owner_alloc.create(ClusterBackupMaintenanceWork) catch |err| {
            self.backup_maintenance_queue.requeueActive(target);
            self.backup_maintenance_mutex.unlock();
            return err;
        };
        work.* = .{ .server = self, .target = target };
        // Keep the scheduler mutex through durable-lane admission. Server
        // shutdown sets `closing` and closes this owner before draining the
        // queue; serializing submission here guarantees closeOwner either sees
        // the job or causes submit to fail and requeue it before queue teardown.
        runtime.durable_jobs.submit(.{
            .owner_id = self.backup_maintenance_owner_id,
            .class = .cleanup,
            .ptr = work,
            .run = ClusterBackupMaintenanceWork.run,
            .deinit = ClusterBackupMaintenanceWork.deinit,
        }) catch |err| {
            self.backup_maintenance_queue.requeueActive(target);
            self.backup_maintenance_mutex.unlock();
            self.owner_alloc.destroy(work);
            return err;
        };
        self.backup_maintenance_mutex.unlock();
    }

    /// Register a repository with the periodic bounded maintenance supervisor.
    /// The FIFO retains distinct locations and rotates them without steady-state
    /// allocation; stale work therefore progresses even without later requests.
    fn scheduleClusterBackupMaintenance(
        self: *ApiHttpServer,
        location_uri: []const u8,
        connection: []const u8,
    ) !void {
        if (self.backup_maintenance_closing.load(.acquire))
            return error.BackupMaintenanceUnavailable;
        const runtime = self.cfg.backend_runtime orelse return;
        if (runtime.threaded_jobs == null or self.backup_maintenance_owner_id == 0)
            return;

        platform_sync.lockYielding(&self.backup_maintenance_mutex);
        if (self.backup_maintenance_closing.load(.acquire)) {
            self.backup_maintenance_mutex.unlock();
            return error.BackupMaintenanceUnavailable;
        }
        const enqueue_result = self.backup_maintenance_queue.enqueue(
            self.owner_alloc,
            location_uri,
            connection,
            platform_time.monotonicNs(),
        );
        self.backup_maintenance_mutex.unlock();
        _ = enqueue_result catch |err| {
            // Preserve progress for already queued repositories even when this
            // caller receives explicit bounded-queue backpressure.
            self.submitNextClusterBackupMaintenance() catch {};
            return err;
        };
        try self.submitNextClusterBackupMaintenance();
    }

    pub fn storageMaintenanceExclusiveActive(self: *const ApiHttpServer) bool {
        const coordinator = self.cfg.storage_maintenance orelse return false;
        return coordinator.isExclusiveActive();
    }

    fn localTableRuntimeStatuses(
        self: *ApiHttpServer,
        table_name: []const u8,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        return try self.localTableRuntimeStatusesWithSnapshot(table_name, null);
    }

    fn localTableRuntimeStatusesWithSnapshot(
        self: *ApiHttpServer,
        table_name: []const u8,
        snapshot: ?*const metadata_api.AdminSnapshot,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        return try self.localTableRuntimeStatusesWithSnapshotIndex(table_name, snapshot, null);
    }

    fn localTableRuntimeStatusesWithSnapshotIndex(
        self: *ApiHttpServer,
        table_name: []const u8,
        snapshot: ?*const metadata_api.AdminSnapshot,
        snapshot_index: ?*const RuntimeStatusSnapshotIndex,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        var items = std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus).empty;
        var item_indexes = std.AutoHashMapUnmanaged(u64, usize).empty;
        defer item_indexes.deinit(self.alloc);
        errdefer {
            for (items.items) |*item| item.deinit(self.alloc);
            items.deinit(self.alloc);
        }

        var read_needs_refresh = false;
        var read_statuses_present = false;
        if (self.table_reads) |source| {
            if (try source.localRuntimeStatuses(self.alloc, table_name)) |statuses| {
                var owned = statuses;
                if (owned.items.len == 0) {
                    owned.deinit(self.alloc);
                } else {
                    read_statuses_present = true;
                    errdefer owned.deinit(self.alloc);
                    read_needs_refresh = runtimeStatusesNeedWriterRefresh(owned.items);
                    try self.appendLocalRuntimeStatuses(table_name, snapshot, snapshot_index, &items, &item_indexes, &owned);
                }
            }
        }
        if (snapshot) |admin_snapshot| {
            if (snapshot_index) |index| {
                try self.appendRemoteRuntimeStatusesFromIndex(&items, &item_indexes, table_name, index);
            } else {
                try self.appendRemoteRuntimeStatusesFromSnapshot(&items, &item_indexes, table_name, admin_snapshot);
            }
        }
        const should_query_writes = if (snapshot == null)
            self.table_reads == null or !read_statuses_present or read_needs_refresh
        else
            items.items.len == 0 or !read_statuses_present or read_needs_refresh;
        if (should_query_writes and self.table_writes != null) {
            // Local write-source statuses are a best-effort refresh: a shard
            // that is not hosted locally must not fail the status request.
            const write_statuses = self.table_writes.?.localRuntimeStatuses(self.alloc, table_name) catch |err| blk: {
                std.log.warn("index status local write-source runtime statuses unavailable table={s} err={s}", .{ table_name, @errorName(err) });
                break :blk null;
            };
            if (write_statuses) |statuses| {
                var owned = statuses;
                errdefer owned.deinit(self.alloc);
                try self.appendLocalRuntimeStatuses(table_name, snapshot, snapshot_index, &items, &item_indexes, &owned);
            }
        }
        if (items.items.len == 0) {
            items.deinit(self.alloc);
            return null;
        }
        return .{ .items = try items.toOwnedSlice(self.alloc) };
    }

    fn localCatalogTableRuntimeStatusesWithSnapshot(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        snapshot: ?*const metadata_api.AdminSnapshot,
    ) !?runtime_status.LocalTableRuntimeStatuses {
        const catalog_table_name = try catalog_resources.tableResourceNameAlloc(self.alloc, target.database_name, target.namespace_name, target.table_name);
        defer self.alloc.free(catalog_table_name);

        var items = std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus).empty;
        var item_indexes = std.AutoHashMapUnmanaged(u64, usize).empty;
        defer item_indexes.deinit(self.alloc);
        errdefer {
            for (items.items) |*item| item.deinit(self.alloc);
            items.deinit(self.alloc);
        }

        if (self.table_reads) |source| {
            if (try source.localRuntimeStatusesCatalog(self.alloc, target)) |statuses| {
                var owned = statuses;
                errdefer owned.deinit(self.alloc);
                try self.appendLocalRuntimeStatuses(catalog_table_name, snapshot, null, &items, &item_indexes, &owned);
            }
        }
        if (snapshot) |admin_snapshot| {
            try self.appendRemoteRuntimeStatusesFromSnapshot(&items, &item_indexes, catalog_table_name, admin_snapshot);
        }
        if (items.items.len == 0 and !self.snapshotHasProjectedTableGroups(catalog_table_name, snapshot)) {
            if (self.table_writes) |source| {
                if (try source.localRuntimeStatusesCatalog(self.alloc, target)) |statuses| {
                    var owned = statuses;
                    errdefer owned.deinit(self.alloc);
                    try self.appendLocalRuntimeStatuses(catalog_table_name, snapshot, null, &items, &item_indexes, &owned);
                }
            }
        }
        if (items.items.len == 0) {
            items.deinit(self.alloc);
            return null;
        }
        return .{ .items = try items.toOwnedSlice(self.alloc) };
    }

    fn snapshotHasProjectedTableGroups(
        self: *ApiHttpServer,
        table_name: []const u8,
        maybe_snapshot: ?*const metadata_api.AdminSnapshot,
    ) bool {
        _ = self;
        const snapshot = maybe_snapshot orelse return false;
        const table = tables_api.findTableByName(snapshot, table_name) orelse return false;
        return tableHasAnyGroup(snapshot, table.table_id);
    }

    fn appendLocalRuntimeStatuses(
        self: *ApiHttpServer,
        table_name: []const u8,
        snapshot: ?*const metadata_api.AdminSnapshot,
        snapshot_index: ?*const RuntimeStatusSnapshotIndex,
        items: *std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus),
        item_indexes: *std.AutoHashMapUnmanaged(u64, usize),
        owned: *runtime_status.LocalTableRuntimeStatuses,
    ) !void {
        try items.ensureUnusedCapacity(self.alloc, owned.items.len);
        const additional_indexes = std.math.cast(u32, owned.items.len) orelse return error.TooManyRuntimeStatuses;
        try item_indexes.ensureUnusedCapacity(self.alloc, additional_indexes);
        for (owned.items) |item| {
            const allowed = if (snapshot_index) |index|
                index.statusAllowed(
                    table_name,
                    item,
                    if (self.cfg.session_router) |router| router.localNodeId() else 0,
                )
            else
                self.localRuntimeStatusAllowedBySnapshot(table_name, snapshot, item);
            if (!allowed) {
                var discard = item;
                discard.deinit(self.alloc);
                continue;
            }
            var candidate = item;
            try upsertRuntimeStatus(self.alloc, items, item_indexes, &candidate);
        }
        if (owned.items.len > 0) self.alloc.free(owned.items);
        owned.items = &.{};
    }

    fn statusAdminSnapshot(self: *ApiHttpServer) !?metadata_api.AdminSnapshot {
        return (try self.source.cachedAdminSnapshot()) orelse try self.source.adminSnapshot();
    }

    fn appendRemoteRuntimeStatusesFromSnapshot(
        self: *ApiHttpServer,
        items: *std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus),
        item_indexes: *std.AutoHashMapUnmanaged(u64, usize),
        table_name: []const u8,
        snapshot: *const metadata_api.AdminSnapshot,
    ) !void {
        const table = tables_api.findTableByName(snapshot, table_name) orelse return;
        for (snapshot.stores) |store| {
            for (store.runtime_statuses) |remote| {
                if (remote.table_id != 0 and remote.table_id != table.table_id) continue;
                if (remote.table_name.len != 0 and !std.mem.eql(u8, remote.table_name, table_name)) continue;
                if (!tableHasGroup(snapshot, table.table_id, remote.group_id)) continue;
                if (!storeOwnsRuntimeGroup(snapshot, store, remote.group_id)) continue;

                var status = try localRuntimeStatusFromRemoteReport(self.alloc, remote);
                var consumed = false;
                errdefer if (!consumed) status.deinit(self.alloc);
                try upsertRuntimeStatus(self.alloc, items, item_indexes, &status);
                consumed = true;
            }
        }
    }

    fn appendRemoteRuntimeStatusesFromIndex(
        self: *ApiHttpServer,
        items: *std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus),
        item_indexes: *std.AutoHashMapUnmanaged(u64, usize),
        table_name: []const u8,
        snapshot_index: *const RuntimeStatusSnapshotIndex,
    ) !void {
        const table_id = snapshot_index.tableId(table_name) orelse return;
        for (snapshot_index.reportsForTable(table_id)) |report| {
            var status = try localRuntimeStatusFromRemoteReport(self.alloc, report.*);
            var consumed = false;
            errdefer if (!consumed) status.deinit(self.alloc);
            try upsertRuntimeStatus(self.alloc, items, item_indexes, &status);
            consumed = true;
        }
    }

    fn upsertRuntimeStatus(
        alloc: std.mem.Allocator,
        items: *std.ArrayListUnmanaged(runtime_status.LocalTableRuntimeStatus),
        item_indexes: *std.AutoHashMapUnmanaged(u64, usize),
        status: *runtime_status.LocalTableRuntimeStatus,
    ) !void {
        if (item_indexes.get(status.group_id)) |existing_index| {
            const existing = &items.items[existing_index];
            if (!runtimeStatusPreferred(status.*, existing.*)) {
                status.deinit(alloc);
                return;
            }
            existing.deinit(alloc);
            existing.* = status.*;
            status.* = undefined;
            return;
        }
        try items.ensureUnusedCapacity(alloc, 1);
        try item_indexes.ensureUnusedCapacity(alloc, 1);
        const index = items.items.len;
        items.appendAssumeCapacity(status.*);
        item_indexes.putAssumeCapacity(status.group_id, index);
        status.* = undefined;
    }

    fn runtimeStatusPreferred(candidate: runtime_status.LocalTableRuntimeStatus, existing: runtime_status.LocalTableRuntimeStatus) bool {
        const candidate_meta = candidate.metadata;
        const existing_meta = existing.metadata;
        if (candidate_meta.topology_generation != 0 and existing_meta.topology_generation != 0 and
            candidate_meta.topology_generation != existing_meta.topology_generation)
            return candidate_meta.topology_generation > existing_meta.topology_generation;
        if (candidate_meta.lsm_root_generation != 0 and existing_meta.lsm_root_generation != 0 and
            candidate_meta.lsm_root_generation != existing_meta.lsm_root_generation)
            return candidate_meta.lsm_root_generation > existing_meta.lsm_root_generation;
        const candidate_quarantined = candidate_meta.source == .rebuild_state_quarantine;
        const existing_quarantined = existing_meta.source == .rebuild_state_quarantine;
        if (candidate_quarantined != existing_quarantined) return candidate_quarantined;
        const same_producer = candidate_meta.store_id != 0 and candidate_meta.store_id == existing_meta.store_id and
            candidate_meta.node_id != 0 and candidate_meta.node_id == existing_meta.node_id;
        if (same_producer and candidate_meta.status_generation != existing_meta.status_generation)
            return candidate_meta.status_generation > existing_meta.status_generation;
        const candidate_freshness = runtimeStatusFreshnessRank(candidate_meta.freshness);
        const existing_freshness = runtimeStatusFreshnessRank(existing_meta.freshness);
        if (candidate_freshness != existing_freshness) return candidate_freshness > existing_freshness;
        const candidate_source = runtimeStatusSourceRank(candidate_meta.source);
        const existing_source = runtimeStatusSourceRank(existing_meta.source);
        if (candidate_source != existing_source) return candidate_source > existing_source;
        return candidate_meta.updated_at_ns > existing_meta.updated_at_ns;
    }

    fn runtimeStatusFreshnessRank(freshness: runtime_status.RuntimeStatusFreshness) u8 {
        return switch (freshness) {
            .fresh => 80,
            .catching_up => 70,
            .opening => 60,
            .stale => 50,
            .remote_unknown => 40,
            .unknown => 30,
            .failed => 20,
            .missing => 10,
        };
    }

    fn runtimeStatusSourceRank(source: runtime_status.RuntimeStatusSource) u8 {
        return switch (source) {
            // Quarantine precedence is enforced before freshness. Keep it
            // highest here as the deterministic tie-break for equal facts.
            .rebuild_state_quarantine => 80,
            .live_writer_publish => 70,
            .startup_catch_up => 60,
            .background_refresh => 50,
            .remote_store => 40,
            .cached_snapshot => 30,
            .synthetic_config => 20,
            .unknown => 10,
        };
    }

    fn localRuntimeStatusAllowedBySnapshot(
        self: *ApiHttpServer,
        table_name: []const u8,
        maybe_snapshot: ?*const metadata_api.AdminSnapshot,
        status: runtime_status.LocalTableRuntimeStatus,
    ) bool {
        const snapshot = maybe_snapshot orelse return true;
        const table = tables_api.findTableByName(snapshot, table_name) orelse return true;
        if (tableHasAnyGroup(snapshot, table.table_id) and !tableHasGroup(snapshot, table.table_id, status.group_id)) return false;

        const local_node_id = if (status.metadata.node_id != 0)
            status.metadata.node_id
        else if (self.cfg.session_router) |router|
            router.localNodeId()
        else
            0;
        const local_store_id = status.metadata.store_id;

        var saw_group_placement = false;
        for (snapshot.placement_intents) |intent| {
            if (intent.record.group_id != status.group_id) continue;
            saw_group_placement = true;
            if (local_store_id != 0 and intent.store_id == local_store_id) return true;
            if (local_node_id != 0 and intent.record.local_node_id == local_node_id) return true;
            if (local_node_id != 0) {
                for (intent.peer_node_ids) |peer_node_id| {
                    if (peer_node_id == local_node_id) return true;
                }
            }
        }
        if (local_node_id == 0 and local_store_id == 0) return !saw_group_placement or snapshot.stores.len <= 1;
        return !saw_group_placement;
    }

    fn localRuntimeStatusFromRemoteReport(
        alloc: std.mem.Allocator,
        report: metadata_table_manager.RuntimeGroupStatusReport,
    ) !runtime_status.LocalTableRuntimeStatus {
        const indexes = try alloc.alloc(db_mod.types.DBIndexStats, report.indexes.len);
        var initialized: usize = 0;
        errdefer {
            for (indexes[0..initialized]) |item| {
                alloc.free(item.name);
                if (item.load_error) |value| alloc.free(value);
            }
            if (indexes.len > 0) alloc.free(indexes);
        }
        for (report.indexes, 0..) |index, i| {
            const kind = parseRemoteIndexKind(index.kind);
            const dense_catch_up_active = kind == .dense_vector and report.async_dense_catch_up_active;
            const name = try alloc.dupe(u8, index.name);
            errdefer alloc.free(name);
            const load_error = if (index.load_error) |value| try alloc.dupe(u8, value) else null;
            errdefer if (load_error) |value| alloc.free(value);
            indexes[i] = .{
                .name = name,
                .kind = kind,
                .load_error = load_error,
                .doc_count = index.doc_count,
                .term_count = index.term_count,
                .edge_count = index.edge_count,
                .node_count = index.node_count,
                .root_node = index.root_node,
                .coverage_produced_count = index.coverage_produced_count,
                .coverage_skipped_count = index.coverage_skipped_count,
                .coverage_terminal_failed_count = index.coverage_terminal_failed_count,
                .coverage_generation = index.coverage_generation,
                .coverage_config_hash = index.coverage_config_hash,
                .coverage_identity_ready = index.coverage_identity_ready,
                .coverage_summary_ready = index.coverage_summary_ready,
                .backfill_active = index.backfill_active,
                .backfill_progress = @as(f64, @floatFromInt(index.backfill_progress_millis)) / 1000.0,
                .replay_applied_sequence = index.replay_applied_sequence,
                .replay_target_sequence = index.replay_target_sequence,
                .replay_catch_up_required = index.replay_catch_up_required,
                .catch_up_active = dense_catch_up_active,
                .catch_up_phase = if (dense_catch_up_active) .replay else .idle,
                .catch_up_applied_sequence = index.replay_applied_sequence,
                .catch_up_target_sequence = index.replay_target_sequence,
            };
            initialized += 1;
        }
        return .{
            .group_id = report.group_id,
            .disk_bytes = report.disk_bytes,
            .disk_bytes_known = report.disk_bytes_known,
            .created_at_millis = report.created_at_millis,
            .metadata = .{
                .updated_at_ns = report.updated_at_ns,
                .source = parseRemoteRuntimeSource(report.source),
                .freshness = parseRemoteRuntimeFreshness(report.freshness),
                .topology_generation = report.topology_generation,
                .lsm_root_generation = report.lsm_root_generation,
                .status_generation = report.status_generation,
                .store_id = report.store_id,
                .node_id = report.node_id,
            },
            .stats = .{
                .source_doc_count = report.doc_identity.live_ordinals,
                .doc_count = report.doc_count,
                .index_count = report.index_count,
                .indexes = indexes,
                .enrichment = enrichmentStatsFromRemoteReport(report.enrichment),
                .async_indexing = .{
                    .startup = .{ .active = report.async_startup_active },
                    .dense_catch_up = .{ .active = report.async_dense_catch_up_active },
                    .bulk_coalescing = .{ .active_session = report.async_bulk_coalescing_active },
                },
                .doc_identity = docIdentityStatsFromRemoteReport(report.doc_identity),
                .doc_set_planning = docSetPlanningStatsFromRemoteReport(report.doc_set_planning),
            },
        };
    }

    fn enrichmentStatsFromRemoteReport(
        report: metadata_table_manager.RuntimeEnrichmentStatusReport,
    ) db_mod.types.EnrichmentStats {
        var stats: db_mod.types.EnrichmentStats = .{};
        inline for (std.meta.fields(metadata_table_manager.RuntimeEnrichmentStatusReport)) |field| {
            @field(stats, field.name) = @field(report, field.name);
        }
        return stats;
    }

    fn docIdentityStatsFromRemoteReport(
