            .ordinal_list_count = report.ordinal_list_count,
            .ordinal_bitmap_count = report.ordinal_bitmap_count,
            .doc_key_list_docs = report.doc_key_list_docs,
            .ordinal_list_docs = report.ordinal_list_docs,
            .ordinal_bitmap_docs = report.ordinal_bitmap_docs,
            .missing_ordinal_coverage_count = report.missing_ordinal_coverage_count,
            .bitmap_promotion_count = report.bitmap_promotion_count,
            .unsupported_filter_shape_count = report.unsupported_filter_shape_count,
            .stale_identity_generation_rejection_count = report.stale_identity_generation_rejection_count,
        };
    }

    fn parseRemoteIndexKind(kind: []const u8) db_mod.types.IndexKind {
        if (std.mem.eql(u8, kind, "full_text")) return .full_text;
        if (std.mem.eql(u8, kind, "sparse_vector")) return .sparse_vector;
        if (std.mem.eql(u8, kind, "graph")) return .graph;
        if (std.mem.eql(u8, kind, "algebraic")) return .algebraic;
        return .dense_vector;
    }

    fn parseRemoteRuntimeFreshness(freshness: []const u8) runtime_status.RuntimeStatusFreshness {
        inline for (@typeInfo(runtime_status.RuntimeStatusFreshness).@"enum".fields) |field| {
            if (std.mem.eql(u8, freshness, field.name)) return @enumFromInt(field.value);
        }
        return .remote_unknown;
    }

    fn parseRemoteRuntimeSource(source: []const u8) runtime_status.RuntimeStatusSource {
        if (std.mem.eql(u8, source, "rebuild_state_quarantine")) return .rebuild_state_quarantine;
        return .remote_store;
    }

    fn tableHasGroup(snapshot: *const metadata_api.AdminSnapshot, table_id: u64, group_id: u64) bool {
        for (snapshot.ranges) |range| {
            if (range.table_id == table_id and range.group_id == group_id) return true;
        }
        return false;
    }

    fn tableHasAnyGroup(snapshot: *const metadata_api.AdminSnapshot, table_id: u64) bool {
        for (snapshot.ranges) |range| {
            if (range.table_id == table_id) return true;
        }
        return false;
    }

    fn storeOwnsRuntimeGroup(
        snapshot: *const metadata_api.AdminSnapshot,
        store: metadata_table_manager.StoreRecord,
        group_id: u64,
    ) bool {
        var saw_group_placement = false;
        for (snapshot.placement_intents) |intent| {
            if (intent.record.group_id != group_id) continue;
            saw_group_placement = true;
            if (intent.store_id != 0 and intent.store_id == store.store_id) return true;
            if (intent.record.local_node_id == store.node_id) return true;
            for (intent.peer_node_ids) |peer_node_id| {
                if (peer_node_id == store.node_id) return true;
            }
        }
        return !saw_group_placement;
    }

    pub fn bestEffortSingleTableStorageStatus(
        self: *ApiHttpServer,
        table_name: []const u8,
    ) !?tables_api.TableStorageStatus {
        return try self.bestEffortSingleTableStorageStatusWithSnapshot(table_name, null);
    }

    fn bestEffortSingleTableStorageStatusWithSnapshot(
        self: *ApiHttpServer,
        table_name: []const u8,
        snapshot: ?*const metadata_api.AdminSnapshot,
    ) !?tables_api.TableStorageStatus {
        return try self.bestEffortSingleTableStorageStatusWithSnapshotIndex(table_name, snapshot, null);
    }

    fn bestEffortSingleTableStorageStatusWithSnapshotIndex(
        self: *ApiHttpServer,
        table_name: []const u8,
        snapshot: ?*const metadata_api.AdminSnapshot,
        snapshot_index: ?*const RuntimeStatusSnapshotIndex,
    ) !?tables_api.TableStorageStatus {
        const table_id = if (snapshot) |value|
            if (snapshot_index) |index|
                index.tableId(table_name) orelse return null
            else
                (tables_api.findTableByName(value, table_name) orelse return null).table_id
        else
            null;
        var expected_group_count: usize = 0;
        if (snapshot) |value| {
            if (snapshot_index) |index| {
                expected_group_count = index.groupIdsForTable(table_id.?).len;
            } else {
                for (value.ranges) |range| {
                    if (range.table_id == table_id.?) expected_group_count += 1;
                }
            }
            if (expected_group_count == 0) return null;
        }

        var local_statuses = (try self.localTableRuntimeStatusesWithSnapshotIndex(
            table_name,
            snapshot,
            snapshot_index,
        )) orelse return null;
        defer local_statuses.deinit(self.alloc);

        var doc_count: u64 = 0;
        var saw_fresh_doc_count = false;
        var fresh_group_count: usize = 0;
        var disk_usage: u64 = 0;
        var disk_usage_complete = snapshot != null;

        var status_by_group = std.AutoHashMapUnmanaged(u64, *const runtime_status.LocalTableRuntimeStatus).empty;
        defer status_by_group.deinit(self.alloc);
        if (snapshot != null) {
            try status_by_group.ensureTotalCapacity(
                self.alloc,
                std.math.cast(u32, local_statuses.items.len) orelse return error.TooManyRuntimeStatuses,
            );
            for (local_statuses.items) |*item| {
                status_by_group.putAssumeCapacity(item.group_id, item);
            }
        }
        if (snapshot) |value| {
            if (snapshot_index) |index| {
                for (index.groupIdsForTable(table_id.?)) |group_id| {
                    const item = status_by_group.get(group_id) orelse {
                        disk_usage_complete = false;
                        continue;
                    };
                    doc_count +|= @max(item.stats.source_doc_count, item.stats.doc_count);
                    if (!runtime_status.statusRuntimeFresh(item.*)) {
                        disk_usage_complete = false;
                        continue;
                    }
                    fresh_group_count += 1;
                    if (!item.disk_bytes_known) {
                        disk_usage_complete = false;
                        continue;
                    }
                    disk_usage +|= item.disk_bytes;
                }
            } else {
                for (value.ranges) |range| {
                    if (range.table_id != table_id.?) continue;
                    const item = status_by_group.get(range.group_id) orelse {
                        disk_usage_complete = false;
                        continue;
                    };
                    // Derived visibility may trail a weak-sync primary write. The
                    // identity-backed source count is the O(1) authority; retain
                    // the derived count as a compatibility floor.
                    doc_count +|= @max(item.stats.source_doc_count, item.stats.doc_count);
                    if (!runtime_status.statusRuntimeFresh(item.*)) {
                        disk_usage_complete = false;
                        continue;
                    }
                    fresh_group_count += 1;
                    if (!item.disk_bytes_known) {
                        disk_usage_complete = false;
                        continue;
                    }
                    disk_usage +|= item.disk_bytes;
                }
            }
        } else {
            for (local_statuses.items) |item| {
                doc_count +|= @max(item.stats.source_doc_count, item.stats.doc_count);
                saw_fresh_doc_count = saw_fresh_doc_count or runtime_status.statusRuntimeFresh(item);
            }
        }
        // A nonzero cached count proves the table is non-empty even if the
        // observation has since gone stale. A zero from an opening/catching-up
        // placeholder proves nothing: omit this optional status rather than
        // advertising a populated table as empty during structural work.
        const complete_fresh_doc_count = if (snapshot != null)
            fresh_group_count == expected_group_count
        else
            saw_fresh_doc_count;
        if (doc_count == 0 and !complete_fresh_doc_count) return null;
        return .{
            .table_name = table_name,
            .empty = doc_count == 0,
            .disk_usage = if (disk_usage_complete and fresh_group_count == expected_group_count)
                disk_usage
            else
                null,
            // This endpoint is catalog/status observability and must remain
            // available while structural maintenance owns the writer. The
            // runtime-status cache is published from the live DB and already
            // carries LSM stats; opening a direct read here waits behind schema
            // backfill and turns a supposedly best-effort field into an
            // unbounded GET /tables stall.
            .lsm = liveLsmStorageStatusFromRuntimeStatuses(local_statuses.items),
        };
    }

    fn liveLsmStorageStatusFromRuntimeStatuses(
        statuses: []const runtime_status.LocalTableRuntimeStatus,
    ) ?tables_api.LsmStorageStatus {
        var saw_lsm_stats = false;
        var aggregate = runtime_status.LsmStorageStats{};
        for (statuses) |status| {
            const stats = status.lsm_storage_stats orelse continue;
            saw_lsm_stats = true;
            lsm_backend.Backend.accumulateMaintenanceStats(&aggregate.maintenance, stats.maintenance);
            lsm_backend.Backend.accumulateWriteStats(&aggregate.write, stats.write);
            aggregate.maintenance_score = @max(aggregate.maintenance_score, stats.maintenance_score);
            aggregate.maintenance_debt_hint = @max(aggregate.maintenance_debt_hint, stats.maintenance_debt_hint);
        }
        if (!saw_lsm_stats) return null;
        return tables_api.lsmStorageStatusFromStats(aggregate);
    }

    fn bestEffortObservedDynamicFieldCapabilitySets(
        self: *ApiHttpServer,
        table_name: []const u8,
    ) ![]table_reads.ObservedDynamicFieldCapabilitySet {
        const source = self.table_reads orelse return &.{};
        return (try source.observedDynamicFieldCapabilitySets(self.alloc, table_name)) orelse &.{};
    }

    fn indexHasDenseVisibilityFacts(item: db_mod.types.DBIndexStats) bool {
        return item.doc_count > 0 or item.term_count > 0 or item.edge_count > 0 or item.node_count > 0 or item.root_node > 0;
    }

    fn runtimeStatusNeedsDenseVisibilityRefresh(status: runtime_status.LocalTableRuntimeStatus) bool {
        if (status.stats.repair_degraded or status.stats.repair_issue_count != 0) return false;
        const synthetic_or_stale = status.metadata.source == .synthetic_config or status.metadata.freshness == .stale;
        const has_primary_facts = status.stats.doc_identity.live_ordinals != 0 or status.stats.doc_count != 0;
        for (status.stats.indexes) |item| {
            if (item.kind != .dense_vector) continue;
            if (synthetic_or_stale) return true;
            if (indexHasDenseVisibilityFacts(item)) continue;
            if (item.replay_applied_sequence != 0 or item.replay_target_sequence != 0) continue;
            if (has_primary_facts) return true;
            return status.metadata.source == .live_writer_publish;
        }
        return false;
    }

    fn runtimeStatusNeedsWriterRefresh(status: runtime_status.LocalTableRuntimeStatus) bool {
        if (runtimeStatusNeedsDenseVisibilityRefresh(status)) return true;
        if (runtime_status.statusHasRuntimeFacts(status)) return false;
        if (status.metadata.source == .live_writer_publish) return false;
        return status.stats.indexes.len != 0;
    }

    fn runtimeStatusesNeedWriterRefresh(statuses: []const runtime_status.LocalTableRuntimeStatus) bool {
        for (statuses) |status| {
            if (runtimeStatusNeedsWriterRefresh(status)) return true;
        }
        return false;
    }

    fn freeObservedDynamicFieldCapabilitySets(
        self: *ApiHttpServer,
        sets: []table_reads.ObservedDynamicFieldCapabilitySet,
    ) void {
        for (sets) |*set| set.deinit(self.alloc);
        if (sets.len > 0) self.alloc.free(sets);
    }

    pub fn bestEffortSingleTableStorageStatuses(
        self: *ApiHttpServer,
        table_name: []const u8,
        snapshot: ?*const metadata_api.AdminSnapshot,
        storage_status_buf: *[1]tables_api.TableStorageStatus,
    ) !?[]const tables_api.TableStorageStatus {
        const status = (try self.bestEffortSingleTableStorageStatusWithSnapshot(table_name, snapshot)) orelse return null;
        storage_status_buf[0] = status;
        return storage_status_buf[0..];
    }

    fn catalogSource(self: *ApiHttpServer) table_catalog.CatalogSource {
        return .{
            .ptr = self,
            .vtable = &.{
                .admin_snapshot = apiHttpServerCatalogAdminSnapshot,
                .free_admin_snapshot = apiHttpServerCatalogFreeAdminSnapshot,
                .upsert_table_emptying_job = apiHttpServerCatalogUpsertTableEmptyingJob,
                .upsert_table = apiHttpServerCatalogUpsertTable,
                .apply_table_catalog_update_with_schema_rewrite_jobs = apiHttpServerCatalogApplyTableCatalogUpdateWithSchemaRewriteJobs,
                .apply_table_catalog_batch_update_with_schema_rewrite_jobs = apiHttpServerCatalogApplyTableCatalogBatchUpdateWithSchemaRewriteJobs,
                .apply_table_catalog_drop_with_schema_rewrite_jobs = apiHttpServerCatalogApplyTableCatalogDropWithSchemaRewriteJobs,
                .promote_table_emptying_barrier = apiHttpServerCatalogPromoteTableEmptyingBarrier,
                .reset_identity_allocators_for_table_emptying_barrier = apiHttpServerCatalogResetIdentityAllocatorsForTableEmptyingBarrier,
                .supports_identity_allocator_reset_for_table_emptying_barrier = apiHttpServerCatalogSupportsIdentityAllocatorResetForTableEmptyingBarrier,
                .compare_and_swap_table_schema = apiHttpServerCatalogCompareAndSwapTableSchema,
            },
        };
    }

    fn hostedWriteRoutesVisible(self: *ApiHttpServer, table_name: []const u8) !?bool {
        const router = self.cfg.session_router orelse return null;
        var snapshot = (try self.source.adminSnapshot()) orelse return null;
        defer self.source.freeAdminSnapshot(&snapshot);

        const table = tables_api.findTableByName(&snapshot, table_name) orelse return false;
        const ranges = try metadata_admin.listTableRanges(self.alloc, &snapshot, table.table_id);
        defer metadata_admin.freeRangeRefs(self.alloc, ranges);
        if (ranges.len == 0) return false;

        const catalog = self.catalogSource();
        for (ranges) |range| {
            var route = (try table_router.resolveGroupRoute(
                self.alloc,
                catalog,
                router,
                range.group_id,
                .prefer_leader,
            )) orelse return false;
            route.deinit(self.alloc);
        }
        return true;
    }

    pub fn cleanupExpiredSessions(self: *ApiHttpServer, cutoff_ns: u64) !usize {
        return try self.txn_sessions.cleanupExpired(self.alloc, cutoff_ns);
    }

    pub fn applyRelationalSqlDdl(self: *ApiHttpServer, sql: []const u8) !tables_api.AppliedRelationalSqlDdlRecord {
        var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(self.alloc, catalog_resources.SqlCatalogSession.default());
        defer session.deinit(self.alloc);
        return try self.applyRelationalSqlDdlWithSession(sql, &session);
    }

    pub fn applyRelationalSqlDdlInTransactionSession(
        self: *ApiHttpServer,
        txn_id: db_mod.types.TxnId,
        sql: []const u8,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        var state = (try self.txn_sessions.getSqlCatalogSessionState(self.alloc, txn_id)) orelse return error.TxnNotFound;
        defer state.deinit(self.alloc);

        var session = try state.toOwnedSqlCatalogSessionAlloc(self.alloc);
        defer session.deinit(self.alloc);

        var applied = try self.applyRelationalSqlDdlWithSession(sql, &session);
        errdefer applied.deinit(self.alloc);

        var updated = try transactions_api.SqlCatalogSessionState.fromOwnedSqlCatalogSessionAlloc(self.alloc, session);
        defer updated.deinit(self.alloc);
        _ = (try self.txn_sessions.updateSqlCatalogSessionState(self.alloc, txn_id, updated)) orelse return error.TxnNotFound;
        return applied;
    }

    pub fn sqlCatalogSessionForAuthenticatedIdentityDatabaseAlloc(
        self: *ApiHttpServer,
        identity: ?*const AuthenticatedIdentity,
        database_name: []const u8,
    ) !sql_adapter.OwnedSqlCatalogSession {
        var database_settings: []usermgr.RoleSetting = &.{};
        defer {
            for (database_settings) |*setting| setting.deinit(self.alloc);
            if (database_settings.len > 0) self.alloc.free(database_settings);
        }

        var runtime_settings: []usermgr.RoleSetting = &.{};
        var owns_runtime_settings = false;
        defer if (owns_runtime_settings) {
            for (runtime_settings) |*setting| setting.deinit(self.alloc);
            if (runtime_settings.len > 0) self.alloc.free(runtime_settings);
        };

        if (identity) |active_identity| {
            if (self.cfg.user_manager) |manager| {
                if (manager.hasUser(active_identity.username)) {
                    runtime_settings = try manager.getEffectiveRoleRuntimeSettingsForDatabase(active_identity.username, database_name);
                    owns_runtime_settings = true;
                } else {
                    runtime_settings = active_identity.role_runtime_settings;
                }
            } else {
                runtime_settings = active_identity.role_runtime_settings;
            }
        }

        if (self.source.adminSnapshot()) |maybe_snapshot| {
            if (maybe_snapshot) |*snapshot| {
                defer self.source.freeAdminSnapshot(snapshot);
                if (tables_api.findDatabaseByName(snapshot, database_name)) |database| {
                    database_settings = try sqlDatabaseSettingsFromJsonAlloc(self.alloc, database.settings_json);
                }
            }
        } else |err| switch (err) {
            error.UnsupportedOperation => {},
            else => return err,
        }

        return try ownedSqlCatalogSessionFromSettingLayersAlloc(self.alloc, database_name, database_settings, runtime_settings);
    }

    fn ensureSqlNotificationSessionId(self: *ApiHttpServer, session: *sql_adapter.OwnedSqlCatalogSession) u64 {
        if (session.notification_session_id == 0) {
            session.notification_session_id = self.sql_notification_runtime.allocateSessionId();
        }
        return session.notification_session_id;
    }

    fn ensureSqlProtocolSessionId(self: *ApiHttpServer, session: *sql_adapter.OwnedSqlCatalogSession) u64 {
        return self.ensureSqlNotificationSessionId(session);
    }

    fn enforceSqlStatementTimeout(_: *ApiHttpServer, statement_timeout_ns: ?u64, statement_start_ns: u64) !void {
        if (sql_adapter.sqlStatementTimeoutExpired(statement_timeout_ns, statement_start_ns, platform_time.monotonicNs())) return error.StatementTimeout;
    }

    fn parsedSqlTransactionBoundaryClearsLocalSession(parsed_sql: *const sql_adapter.ParsedSql) bool {
        return sql_transactions.parsedSqlTransactionBoundaryClearsLocalSession(parsed_sql);
    }

    fn parsedSqlTransactionBoundaryStartsSession(parsed_sql: *const sql_adapter.ParsedSql) bool {
        return sql_transactions.parsedSqlTransactionBoundaryStartsSession(parsed_sql);
    }

    fn publicSqlTransactionStatus(_: *ApiHttpServer, session: *const sql_adapter.OwnedSqlCatalogSession) PublicSqlTransactionStatus {
        if (session.sql_transaction_failed) return .failed_transaction;
        if (sql_transactions.transactionIsActive(session)) return .in_transaction;
        return .idle;
    }

    fn markPublicSqlTransactionFailedIfActive(_: *ApiHttpServer, session: *sql_adapter.OwnedSqlCatalogSession) void {
        sql_transactions.markTransactionFailedIfActive(session);
    }

    fn publicSqlReadOnlyActive(_: *ApiHttpServer, session: *const sql_adapter.OwnedSqlCatalogSession) !bool {
        return try sql_transactions.readOnlyActive(session);
    }

    fn sessionCatalogPlanAllowedInReadOnly(_: *ApiHttpServer, session: *sql_adapter.OwnedSqlCatalogSession, plan: sql_adapter.SessionCatalogPlan) !bool {
        return try sql_sessions.sessionCatalogPlanAllowedInReadOnly(session, plan);
    }

    fn transactionControlPlanAllowedInReadOnly(_: *ApiHttpServer, plan: sql_adapter.TransactionControlPlan) !bool {
        return try sql_transactions.transactionControlPlanAllowedInReadOnly(plan);
    }

    fn applyTransactionModePlanToSession(self: *ApiHttpServer, session: *sql_adapter.OwnedSqlCatalogSession, plan: sql_adapter.TransactionModePlan) !bool {
        return try sql_transactions.applyTransactionModePlanToSession(self.alloc, session, plan);
    }

    fn applyTransactionBoundaryPlanToSession(
        self: *ApiHttpServer,
        session: *sql_adapter.OwnedSqlCatalogSession,
        plan: sql_adapter.TransactionBoundaryPlan,
    ) !void {
        switch (plan.action) {
            .begin => {
                session.in_sql_transaction = true;
                session.sql_transaction_failed = false;
            },
            .commit, .rollback => {
                if (session.notification_session_id != 0) {
                    try self.sql_cursor_runtime.closeTransactionPortals(session.notification_session_id);
                    self.sql_savepoint_runtime.clear(session.notification_session_id);
                }
                try session.clearTransactionLocalState(self.alloc);
            },
        }
    }

    pub fn applyRelationalSqlDdlWithSession(self: *ApiHttpServer, sql: []const u8, session: *sql_adapter.OwnedSqlCatalogSession) !tables_api.AppliedRelationalSqlDdlRecord {
        var parsed_sql = try sql_adapter.ParsedSql.initAlloc(self.alloc, sql);
        defer parsed_sql.deinit(self.alloc);
        return try self.applyRelationalParsedSqlDdlWithSession(&parsed_sql, session);
    }

    pub const SqlStatementExecutionTiming = struct {
        timeout_ns: ?u64,
        start_ns: u64,
    };

    pub const RelationalDdlPlanExecutionContext = struct {
        parsed_sql: ?*const sql_adapter.ParsedSql = null,
        function_bindings: sql_adapter.SqlFunctionBindings = .{},
        statement_timing: ?SqlStatementExecutionTiming = null,
    };

    pub fn applyRelationalParsedSqlDdlWithSession(self: *ApiHttpServer, parsed_sql: *const sql_adapter.ParsedSql, session: *sql_adapter.OwnedSqlCatalogSession) !tables_api.AppliedRelationalSqlDdlRecord {
        const statement_start_ns = platform_time.monotonicNs();
        const statement_timeout_ns = try sql_adapter.sqlStatementTimeoutNsFromSession(session.session());
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
        const routine_bindings = try self.sql_routine_runtime.listExpressionRoutineBindingsAlloc(self.alloc);
        defer sql_routines.freeExpressionRoutineBindings(self.alloc, routine_bindings);
        const function_bindings: sql_adapter.SqlFunctionBindings = .{
            .routine_expressions = routine_bindings,
        };
        var logical_plan = sql_adapter.planParsedSqlWithSessionAlloc(self.alloc, parsed_sql, .{
            .catalog = self.catalogSource().sqlSource(),
            .session = session.session(),
            .function_bindings = function_bindings,
        }) catch |err| switch (err) {
            error.UnsupportedSqlShape => {
                if (try self.publicSqlReadOnlyActive(session)) return error.SqlReadOnlyTransaction;
                return err;
            },
            else => return err,
        };
        defer logical_plan.deinit(self.alloc);
        var execution_plan = try takePublicSqlPlannedExecutionPlanFromLogical(&logical_plan);
        defer execution_plan.deinit(self.alloc);
        return try self.applySqlDdlExecutionPlanWithSession(&execution_plan, session, .{
            .parsed_sql = parsed_sql,
            .function_bindings = function_bindings,
            .statement_timing = .{
                .timeout_ns = statement_timeout_ns,
                .start_ns = statement_start_ns,
            },
        });
    }

    fn applySqlDdlExecutionPlanWithSession(
        self: *ApiHttpServer,
        plan: *PublicSqlPlannedExecutionPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        return switch (plan.*) {
            .logical => |*logical_plan| try self.applyLogicalSqlPlanWithSession(logical_plan, session, context),
            .durable => |*durable_plan| blk: {
                const timing = try self.sqlStatementExecutionTimingForContext(session, context);
                try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
                if (try self.publicSqlReadOnlyActive(session)) {
                    switch (durable_plan.*) {
                        .bulk_io => |bulk| if (bulk.direction == .from) return error.SqlReadOnlyTransaction,
                        else => return error.SqlReadOnlyTransaction,
                    }
                }
                break :blk try self.applyDurableSqlPlanWithSession(durable_plan, session, context, timing);
            },
        };
    }

    fn applyLogicalSqlPlanWithSession(
        self: *ApiHttpServer,
        logical_plan: *sql_adapter.LogicalSqlPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        switch (logical_plan.*) {
            .table_ddl, .catalog_ddl, .extension, .auth, .maintenance, .bulk_io => return error.UnsupportedSqlShape,
            .other_ddl => |plan| return try self.applyOtherDdlLogicalPlanWithSession(plan, session, context),
            .session => |plan| return try self.applySessionLogicalPlanWithSession(plan, session, context),
            .transaction => |plan| return try self.applyTransactionLogicalPlanWithSession(plan, session, context),
            .prepared_statement => |plan| return try self.applyPreparedStatementLogicalPlanWithSession(plan, session, context),
            .notification => |plan| return try self.applyNotificationLogicalPlanWithSession(plan, session, context),
            .routine => |plan| return try self.applyRoutineLogicalPlanWithSession(plan, session, context),
            .cursor => |plan| return try self.applyCursorLogicalPlanWithSession(plan, session, context),
            .read, .write, .catalog_read, .catalog_write => return error.UnsupportedSqlShape,
        }
    }

    fn sqlStatementExecutionTimingForContext(
        self: *ApiHttpServer,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !SqlStatementExecutionTiming {
        _ = self;
        return context.statement_timing orelse SqlStatementExecutionTiming{
            .timeout_ns = try sql_adapter.sqlStatementTimeoutNsFromSession(session.session()),
            .start_ns = platform_time.monotonicNs(),
        };
    }

    fn emptyAppliedSqlDdlRecordWithTiming(
        self: *ApiHttpServer,
        timing: SqlStatementExecutionTiming,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        var applied = try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(self.alloc);
        errdefer applied.deinit(self.alloc);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        return applied;
    }

    fn applyOtherDdlLogicalPlanWithSession(
        self: *ApiHttpServer,
        plan: sql_adapter.OtherDdlLogicalPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        if (try self.publicSqlReadOnlyActive(session)) {
            switch (plan) {
                .adapter_noop => {},
                .moved => return error.SqlReadOnlyTransaction,
            }
        }
        switch (plan) {
            .adapter_noop => |noop| switch (noop.reason) {
                .transaction_control => {
                    if (context.parsed_sql) |parsed_sql| {
                        if (parsedSqlTransactionBoundaryClearsLocalSession(parsed_sql)) {
                            if (session.notification_session_id != 0) {
                                try self.sql_cursor_runtime.closeTransactionPortals(session.notification_session_id);
                                self.sql_savepoint_runtime.clear(session.notification_session_id);
                            }
                            try session.clearTransactionLocalState(self.alloc);
                            var applied = try self.emptyAppliedSqlDdlRecordWithTiming(timing);
                            applied.noop = true;
                            return applied;
                        }
                        if (parsedSqlTransactionBoundaryStartsSession(parsed_sql)) {
                            session.in_sql_transaction = true;
                            session.sql_transaction_failed = false;
                            var applied = try self.emptyAppliedSqlDdlRecordWithTiming(timing);
                            applied.noop = true;
                            return applied;
                        }
                    }
                    return error.UnsupportedSqlShape;
                },
                .extension => return try extension_sql_adapter.executeRelationalSqlExtensionNoopAlloc(self.alloc),
                else => return error.UnsupportedSqlShape,
            },
            .moved => return error.UnsupportedSqlShape,
        }
    }

    fn applySessionLogicalPlanWithSession(
        self: *ApiHttpServer,
        plan: sql_adapter.SessionCatalogPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        if (try self.publicSqlReadOnlyActive(session)) {
            if (!try self.sessionCatalogPlanAllowedInReadOnly(session, plan)) return error.SqlReadOnlyTransaction;
        }

        const notification_session_id = session.notification_session_id;
        const clear_prepared_statements = switch (plan) {
            .discard_all => true,
            else => false,
        };
        var updated = try sql_adapter.applyOwnedSessionCatalogPlanAlloc(self.alloc, session.*, plan);
        errdefer updated.deinit(self.alloc);
        updated.notification_session_id = notification_session_id;
        updated.request_read_only = session.request_read_only;
        if (clear_prepared_statements and notification_session_id != 0) {
            try self.sql_prepared_statement_runtime.apply(.{ .deallocate = .{ .all = true } }, notification_session_id);
            try self.sql_cursor_runtime.close(notification_session_id, .{ .all = true });
            self.sql_notification_runtime.clearSession(notification_session_id);
            self.sql_savepoint_runtime.clear(notification_session_id);
        }
        session.deinit(self.alloc);
        session.* = updated;
        var applied = try self.emptyAppliedSqlDdlRecordWithTiming(timing);
        applied.noop = true;
        return applied;
    }

    fn applyTransactionLogicalPlanWithSession(
        self: *ApiHttpServer,
        plan: sql_adapter.TransactionLogicalPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);

        switch (plan) {
            .boundary => |boundary| {
                try self.applyTransactionBoundaryPlanToSession(session, boundary);
                var applied = try self.emptyAppliedSqlDdlRecordWithTiming(timing);
                applied.noop = true;
                return applied;
            },
            .control => |control| {
                if (try self.publicSqlReadOnlyActive(session)) {
                    if (!try self.transactionControlPlanAllowedInReadOnly(control)) return error.SqlReadOnlyTransaction;
                }
                switch (control) {
                    .transaction_mode => |transaction_mode| {
                        const applied_mode = try self.applyTransactionModePlanToSession(session, transaction_mode);
                        var applied = try self.emptyAppliedSqlDdlRecordWithTiming(timing);
                        applied.noop = applied_mode;
                        return applied;
                    },
                    else => return error.UnsupportedSqlShape,
                }
            },
            .prepared => |prepared| {
                if (try self.publicSqlReadOnlyActive(session)) return error.SqlReadOnlyTransaction;
                _ = try self.applyPreparedTransactionPlan(prepared, sqlDdlTimestampNs());
                if (prepared.action == .prepare) {
                    if (session.notification_session_id != 0) {
                        try self.sql_cursor_runtime.closeTransactionPortals(session.notification_session_id);
                        self.sql_savepoint_runtime.clear(session.notification_session_id);
                    }
                    try session.clearTransactionLocalState(self.alloc);
                }
                return try self.emptyAppliedSqlDdlRecordWithTiming(timing);
            },
            .savepoint => |savepoint| {
                if (!session.in_sql_transaction) return error.InvalidSqlSession;
                const session_id = self.ensureSqlProtocolSessionId(session);
                try self.sql_savepoint_runtime.apply(session_id, savepoint, session);
                session.in_sql_transaction = true;
                var applied = try self.emptyAppliedSqlDdlRecordWithTiming(timing);
                applied.noop = true;
                return applied;
            },
        }
    }

    fn applyPreparedStatementLogicalPlanWithSession(
        self: *ApiHttpServer,
        plan: sql_adapter.PreparedStatementPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        if (try self.publicSqlReadOnlyActive(session)) {
            const session_id = session.notification_session_id;
            if (!try self.sql_prepared_statement_runtime.planAllowedInReadOnly(session_id, plan)) return error.SqlReadOnlyTransaction;
        }
        const session_id = self.ensureSqlProtocolSessionId(session);
        try self.sql_prepared_statement_runtime.apply(plan, session_id);
        var applied = try self.emptyAppliedSqlDdlRecordWithTiming(timing);
        applied.noop = true;
        return applied;
    }

    fn applyNotificationLogicalPlanWithSession(
        self: *ApiHttpServer,
        plan: sql_adapter.NotificationChannelPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        if (try self.publicSqlReadOnlyActive(session)) {
            if (!self.sql_notification_runtime.planAllowedInReadOnly(plan)) return error.SqlReadOnlyTransaction;
        }
        const session_id = self.ensureSqlNotificationSessionId(session);
        _ = try self.sql_notification_runtime.apply(plan, session_id, sqlDdlTimestampNs());
        return try self.emptyAppliedSqlDdlRecordWithTiming(timing);
    }

    fn applyRoutineLogicalPlanWithSession(
        self: *ApiHttpServer,
        plan: sql_adapter.RoutineLogicalPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        if (try self.publicSqlReadOnlyActive(session)) return error.SqlReadOnlyTransaction;

        switch (plan) {
            .function_catalog, .trigger_catalog => return error.UnsupportedSqlShape,
            .procedure_call => |procedure_call| {
                try self.sql_routine_runtime.executeProcedureRoutineArgs(procedure_call.routine_name, procedure_call.argument_count);
            },
        }
        return try self.emptyAppliedSqlDdlRecordWithTiming(timing);
    }

    fn applyDurableRoutineSqlPlanWithSession(
        self: *ApiHttpServer,
        plan: *sql_adapter.RoutineLogicalPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
        timing: SqlStatementExecutionTiming,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        if (plan.* == .trigger_catalog) {
            var applied = try self.applyTriggerCatalogPlanWithUpdatePolicyFallback(plan.trigger_catalog, session, context, timing);
            errdefer applied.deinit(self.alloc);
            try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
            return applied;
        }
        var applied = relational_sql_ddl.applyRoutineLogicalPlanWithSessionAlloc(self.alloc, self, plan, session.session()) catch |err| switch (err) {
            error.TriggerNotFound => switch (plan.*) {
                .trigger_catalog => |trigger_plan| switch (trigger_plan) {
                    .drop => |drop| return try self.applyUpdatePolicyDropTriggerPlan(drop, session, context, timing),
                    .create => return err,
                },
                else => return err,
            },
            else => return err,
        };
        errdefer applied.deinit(self.alloc);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        return applied;
    }

    pub fn applyAuthorizationLogicalPlanWithSessionAlloc(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        plan: sql_adapter.AuthorizationLogicalPlan,
        session: catalog_resources.SqlCatalogSession,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        if (self.cfg.user_manager) |manager| {
            var catalog = try auth_sql_adapter.authCatalogForPlanWithSessionAlloc(alloc, self.catalogSource(), plan, session);
            defer catalog.deinit(alloc);
            if (try auth_sql_adapter.executeRelationalSqlAuthPlanOnUserManagerWithCatalog(manager, alloc, plan, catalog.value)) |applied_value| {
                return applied_value;
            }
        }
        return error.UnsupportedSqlShape;
    }

    pub fn applyRoutineLogicalPlanWithSessionAlloc(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        plan: *sql_adapter.RoutineLogicalPlan,
        session: catalog_resources.SqlCatalogSession,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        switch (plan.*) {
            .function_catalog => |*function_plan| {
                try self.resolveRoutineSettingsFromCurrentInPlace(function_plan, session);
                try self.sql_routine_runtime.apply(function_plan.*);
                return try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(alloc);
            },
            .trigger_catalog => |trigger_plan| {
                try self.sql_routine_runtime.applyTriggerCatalogPlan(trigger_plan);
                var applied = try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(alloc);
                errdefer applied.deinit(alloc);
                applied.noop = true;
                return applied;
            },
            .procedure_call => return error.UnsupportedSqlShape,
        }
    }

    fn applyCursorLogicalPlanWithSession(
        self: *ApiHttpServer,
        plan: sql_adapter.CursorPortalPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        const timing = try self.sqlStatementExecutionTimingForContext(session, context);
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        switch (plan) {
            .fetch => return error.UnsupportedSqlShape,
            .declare, .move, .close => {},
        }
        const parsed_sql = context.parsed_sql orelse return error.UnsupportedSqlShape;
        var plan_copy = plan;
        var outcome = try self.executePublicSqlCursorLogicalPlanWithSession(&plan_copy, parsed_sql, session, &.{}, null);
        switch (outcome) {
            .response => |*response| {
                response.deinit(self.alloc);
                return error.UnsupportedSqlShape;
            },
            .result => |*result| switch (result.result) {
                .ddl => |*ddl| {
                    const applied = ddl.applied;
                    ddl.* = undefined;
                    outcome = undefined;
                    try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
                    return applied;
                },
                else => {
                    result.deinit(self.alloc);
                    return error.UnsupportedSqlShape;
                },
            },
        }
    }

    fn applyDurableSqlPlanWithSession(
        self: *ApiHttpServer,
        durable_plan: *sql_adapter.DurableSqlPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
        timing: SqlStatementExecutionTiming,
    ) !tables_api.AppliedRelationalSqlDdlRecord {
        try self.rejectUnsupportedDocumentSqlViewMappingForDurablePlan(durable_plan.*, session.session());
        switch (durable_plan.*) {
            .table_ddl => |*table_plan| {
                if (try self.applyRoutineTriggerDropBeforeUpdatePolicyFallback(table_plan, timing)) |applied| {
                    return applied;
                }
                var applied = try self.source.applyRelationalSqlDdlPlanWithSessionAndFunctionBindings(self.alloc, durable_plan, session.session(), context.function_bindings);
                errdefer applied.deinit(self.alloc);
                try self.scheduleSchemaRewriteRuntimeHintForAppliedDdl(applied);
                try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
                return applied;
            },
            .auth => |auth_plan| {
                var applied = try relational_sql_ddl.applyAuthorizationLogicalPlanWithSessionAlloc(self.alloc, self, auth_plan, session.session());
                errdefer applied.deinit(self.alloc);
                try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
                return applied;
            },
            .routine => |*routine| return try self.applyDurableRoutineSqlPlanWithSession(routine, session, context, timing),
            .maintenance => {
                var applied = try self.source.applyRelationalSqlDdlPlanWithSessionAndFunctionBindings(self.alloc, durable_plan, session.session(), context.function_bindings);
                errdefer applied.deinit(self.alloc);
                try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
                return applied;
            },
            .bulk_io => return error.UnsupportedSqlShape,
            .extension => {
                var applied = try self.source.applyRelationalSqlDdlPlanWithSessionAndFunctionBindings(self.alloc, durable_plan, session.session(), context.function_bindings);
                errdefer applied.deinit(self.alloc);
                try self.refreshSqlExtensionQueryFunctions();
                try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
                return applied;
            },
            else => {
                var applied = try self.source.applyRelationalSqlDdlPlanWithSessionAndFunctionBindings(self.alloc, durable_plan, session.session(), context.function_bindings);
                errdefer applied.deinit(self.alloc);
                try self.scheduleSchemaRewriteRuntimeHintForAppliedDdl(applied);
                try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
                return applied;
            },
        }
    }

    fn applyRoutineTriggerDropBeforeUpdatePolicyFallback(
        self: *ApiHttpServer,
        plan: *const sql_adapter.TableDdlLogicalPlan,
        timing: SqlStatementExecutionTiming,
    ) !?tables_api.AppliedRelationalSqlDdlRecord {
        const drop_update_policy = switch (plan.*) {
            .alter_table => |alter| blk: {
                if (alter.operations.len != 1) return null;
                break :blk switch (alter.operations[0]) {
                    .drop_update_policy => |drop| .{
                        .table_name = alter.table_name,
                        .drop = drop,
                    },
                    else => return null,
                };
            },
            else => return null,
        };
        const trigger_plan = sql_adapter.TriggerCatalogPlan{ .drop = .{
            .trigger_name = drop_update_policy.drop.trigger_name,
            .table_name = drop_update_policy.table_name,
            .if_exists = drop_update_policy.drop.if_exists,
            .cascade = false,
        } };
        self.sql_routine_runtime.applyTriggerCatalogPlan(trigger_plan) catch |err| switch (err) {
            error.TriggerNotFound => return null,
            else => return err,
        };
        var applied = try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(self.alloc);
        errdefer applied.deinit(self.alloc);
        applied.noop = true;
        try self.enforceSqlStatementTimeout(timing.timeout_ns, timing.start_ns);
        return applied;
    }

    fn applyTriggerCatalogPlanWithUpdatePolicyFallback(
        self: *ApiHttpServer,
        plan: sql_adapter.TriggerCatalogPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
        timing: SqlStatementExecutionTiming,
    ) anyerror!tables_api.AppliedRelationalSqlDdlRecord {
        self.sql_routine_runtime.applyTriggerCatalogPlan(plan) catch |err| switch (err) {
            error.TriggerNotFound => switch (plan) {
                .drop => |drop| return try self.applyUpdatePolicyDropTriggerPlan(drop, session, context, timing),
                .create => return err,
            },
            else => return err,
        };
        var applied = try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(self.alloc);
        applied.noop = true;
        return applied;
    }

    fn applyUpdatePolicyDropTriggerPlan(
        self: *ApiHttpServer,
        drop: sql_adapter.DropRoutineTriggerPlan,
        session: *sql_adapter.OwnedSqlCatalogSession,
        context: RelationalDdlPlanExecutionContext,
        timing: SqlStatementExecutionTiming,
    ) anyerror!tables_api.AppliedRelationalSqlDdlRecord {
        var durable_plan = try sql_adapter.durablePlanForDropUpdatePolicyTriggerAlloc(self.alloc, drop);
        defer durable_plan.deinit(self.alloc);
        return try self.applyDurableSqlPlanWithSession(&durable_plan, session, .{
            .function_bindings = context.function_bindings,
            .statement_timing = timing,
        }, timing);
    }

    fn rejectUnsupportedDocumentSqlViewMappingForDurablePlan(
        self: *ApiHttpServer,
        plan: sql_adapter.DurableSqlPlan,
        session: catalog_resources.SqlCatalogSession,
    ) !void {
        const create_view = switch (plan) {
            .table_ddl => |table_plan| switch (table_plan) {
                .view_catalog => |view_plan| switch (view_plan) {
                    .create => |create| create,
                    else => return,
                },
                else => return,
            },
            else => return,
        };
        const schema = sql_adapter.runtimeSchemaForCatalogTableWithSessionAlloc(
            self.alloc,
            self.catalogSource().sqlSource(),
            create_view.source_table_name,
            session,
        ) catch |err| switch (err) {
            error.TableNotFound, error.InvalidSqlCatalog => return,
            else => return err,
        };
        defer runtime_schema_mod.freeSchema(self.alloc, schema);
        if (schema.storage_mode == .document) return error.DocumentSqlViewMappingUnsupported;
    }

    pub const PublicSqlRequest = struct {
        sql: []const u8,
        session_id: ?u64 = null,
        database: ?[]const u8 = null,
        namespace: ?[]const u8 = null,
        read_only: ?bool = null,
        params: []const sql_adapter.SqlValue = &.{},
        stdin_payload: ?[]const u8 = null,
    };

    const PublicSqlJsonRequest = struct {
        sql: []const u8,
        session_id: ?u64 = null,
        database: ?[]const u8 = null,
        namespace: ?[]const u8 = null,
        read_only: ?bool = null,
        params: ?[]const std.json.Value = null,
        stdin_payload: ?[]const u8 = null,
    };

    pub const OwnedPublicSqlParams = struct {
        values: []sql_adapter.SqlValue = &.{},

        pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            for (self.values) |value| freePublicSqlParam(alloc, value);
            if (self.values.len > 0) alloc.free(self.values);
            self.* = .{};
        }
    };

    pub fn publicSqlParamsFromJsonAlloc(alloc: std.mem.Allocator, params: ?[]const std.json.Value) !OwnedPublicSqlParams {
        const items = params orelse return .{};
        if (items.len == 0) return .{};
        const values = try alloc.alloc(sql_adapter.SqlValue, items.len);
        var initialized: usize = 0;
        errdefer {
            for (values[0..initialized]) |value| freePublicSqlParam(alloc, value);
            alloc.free(values);
        }
        for (items, 0..) |item, i| {
            values[i] = try publicSqlParamFromJsonAlloc(alloc, item);
            initialized += 1;
        }
        return .{ .values = values };
    }

    pub fn freePublicSqlParam(alloc: std.mem.Allocator, value: sql_adapter.SqlValue) void {
        switch (value) {
            .string => |text| alloc.free(@constCast(text)),
            .json => |json| alloc.free(@constCast(json)),
            .null, .bool, .integer, .float => {},
        }
    }

    fn publicSqlParamFromJsonAlloc(alloc: std.mem.Allocator, value: std.json.Value) !sql_adapter.SqlValue {
        return switch (value) {
            .null => .null,
            .bool => |flag| .{ .bool = flag },
            .integer => |number| .{ .integer = number },
            .float => |number| .{ .float = number },
            .number_string => |number| .{ .json = try alloc.dupe(u8, number) },
            .string => |text| .{ .string = try alloc.dupe(u8, text) },
            .array, .object => .{ .json = try std.json.Stringify.valueAlloc(alloc, value, .{}) },
        };
    }

