    fn ownedSqlCatalogSessionForPublicRequestAlloc(self: *ApiHttpServer, request: PublicSqlRequest) !sql_adapter.OwnedSqlCatalogSession {
        return try self.ownedSqlCatalogSessionForPublicSessionRequestAlloc(.{
            .session_id = request.session_id,
            .database = request.database,
            .namespace = request.namespace,
            .read_only = request.read_only,
        });
    }

    fn ownedSqlCatalogSessionForPublicParsedSqlRequestAlloc(self: *ApiHttpServer, request: PublicParsedSqlRequest) !sql_adapter.OwnedSqlCatalogSession {
        return try self.ownedSqlCatalogSessionForPublicSessionRequestAlloc(.{
            .session_id = request.session_id,
            .database = request.database,
            .namespace = request.namespace,
            .read_only = request.read_only,
        });
    }

    fn ownedSqlCatalogSessionForPublicSessionRequestAlloc(self: *ApiHttpServer, request: PublicSqlSessionRequest) !sql_adapter.OwnedSqlCatalogSession {
        var session = try self.sql_catalog_session_runtime.loadAlloc(request.session_id);
        errdefer session.deinit(self.alloc);
        if (request.database) |database| {
            if (!catalogApiIdentifierValid(database)) return error.InvalidSqlRequest;
            if (session.request_database_name_base == null) {
                session.request_database_name_base = try self.alloc.dupe(u8, session.current_database_name);
            }
            self.alloc.free(session.current_database_name);
            session.current_database_name = try self.alloc.dupe(u8, database);
        }
        if (request.namespace) |namespace| {
            if (!catalogApiIdentifierValid(namespace)) return error.InvalidSqlRequest;
            if (session.request_search_path_base == null) {
                session.request_search_path_base = try session.cloneSearchPathAlloc(self.alloc);
            }
            for (session.search_path) |name| self.alloc.free(@constCast(name));
            if (session.search_path.len > 0) self.alloc.free(session.search_path);
            const search_path = try self.alloc.alloc([]const u8, 1);
            errdefer self.alloc.free(search_path);
            search_path[0] = try self.alloc.dupe(u8, namespace);
            session.search_path = search_path;
        }
        session.request_read_only = request.read_only orelse false;
        return session;
    }

    fn savePublicSqlSession(self: *ApiHttpServer, session: sql_adapter.OwnedSqlCatalogSession) !void {
        try self.sql_catalog_session_runtime.save(session);
    }

    fn encodePublicSqlReadResultAlloc(
        self: *ApiHttpServer,
        session_id: u64,
        statement_kind: []const u8,
        transaction_status: PublicSqlTransactionStatus,
        read: PublicSqlResult.Read,
    ) ![]u8 {
        const result_body = switch (read.result) {
            .query => |query| try relational_rows_api.encodeRowsQueryResponseWithSchemaAlloc(self.alloc, query, read.columns),
            .document_query => |query| try relational_rows_api.encodeRowsQueryResponseWithSchemaAlloc(self.alloc, query, read.columns),
            .set_operation => |query| try relational_rows_api.encodeRowsQueryResponseWithSchemaAlloc(self.alloc, query, read.columns),
            .recursive_cte => |query| try relational_rows_api.encodeRowsQueryResponseWithSchemaAlloc(self.alloc, query, read.columns),
            .aggregate => |aggregate| try relational_rows_api.encodeRowsAggregateResponseWithSchemaAlloc(self.alloc, aggregate, read.columns),
            .window => |window| try relational_rows_api.encodeRowsWindowResponseWithSchemaAlloc(self.alloc, window, read.columns),
            .join => |join| try relational_rows_api.encodeRowsJoinResponseWithSchemaAlloc(self.alloc, join, read.columns),
            .lateral => |lateral| try relational_rows_api.encodeRowsJoinResponseWithSchemaAlloc(self.alloc, lateral, read.columns),
        };
        defer self.alloc.free(result_body);

        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.print(
            "{{\"kind\":\"read\",\"session_id\":{d},\"statement_kind\":{f},\"transaction_status\":{f},\"result\":",
            .{ session_id, std.json.fmt(statement_kind, .{}), std.json.fmt(@tagName(transaction_status), .{}) },
        );
        try writer.writeAll(result_body);
        try writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    fn encodePublicSqlRowsBatchResultAlloc(
        self: *ApiHttpServer,
