    fn encodePublicSqlBulkIoResultAlloc(
        self: *ApiHttpServer,
        session_id: u64,
        statement_kind: []const u8,
        transaction_status: PublicSqlTransactionStatus,
        result: PublicSqlResult.BulkIo,
    ) ![]u8 {
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.print(
            "{{\"kind\":\"bulk_io\",\"session_id\":{d},\"statement_kind\":{f},\"transaction_status\":{f},\"result\":{{\"operation\":{f},\"stream\":{f}",
            .{
                session_id,
                std.json.fmt(statement_kind, .{}),
                std.json.fmt(@tagName(transaction_status), .{}),
                std.json.fmt(@tagName(result.operation), .{}),
                std.json.fmt(@tagName(result.stream), .{}),
            },
        );
        if (result.row_count) |row_count| try writer.print(",\"row_count\":{d}", .{row_count});
        if (result.payload) |payload| try writer.print(",\"payload\":{f}", .{std.json.fmt(payload, .{})});
        try writer.writeAll("}}");
        return try out.toOwnedSlice();
    }

    fn encodePublicSqlResultAlloc(self: *ApiHttpServer, result: PublicSqlResult) ![]u8 {
        return switch (result.result) {
            .ddl => |ddl| blk: {
                var response = try jsonResponse(self.alloc, PublicSqlResponse{
                    .kind = "ddl",
                    .session_id = result.session_id,
                    .statement_kind = result.statement_kind,
                    .transaction_status = result.transaction_status,
                    .noop = ddl.applied.noop,
                    .applied = ddl.applied,
                });
                defer response.deinit(self.alloc);
                break :blk try self.alloc.dupe(u8, response.body);
            },
            .read => |read| try self.encodePublicSqlReadResultAlloc(result.session_id, result.statement_kind, result.transaction_status, read),
            .rows_batch => |rows_batch| try self.encodePublicSqlRowsBatchResultAlloc(result.session_id, result.statement_kind, result.transaction_status, rows_batch),
            .mutation_source => |mutation_source| try self.encodePublicSqlRowsMutationSourceResultAlloc(result.session_id, result.statement_kind, result.transaction_status, mutation_source),
            .bulk_io => |bulk_io| try self.encodePublicSqlBulkIoResultAlloc(result.session_id, result.statement_kind, result.transaction_status, bulk_io),
        };
    }

    fn publicSqlDdlCommandTag(parsed_sql: *const sql_adapter.ParsedSql) []const u8 {
        const tokens = parsed_sql.items();
        const raw = parsed_sql.raw_statement;
        if (raw.token_start >= raw.token_end or raw.token_end > tokens.len) return "DDL";
        const first = tokens[raw.token_start];
        if (first.matchesKeywordTag(.create)) return publicSqlCreateDdlCommandTag(tokens[raw.token_start + 1 .. raw.token_end]);
        if (first.matchesKeywordTag(.alter)) return publicSqlDdlObjectCommandTag("ALTER", tokens[raw.token_start + 1 .. raw.token_end]);
        if (first.matchesKeywordTag(.drop)) return publicSqlDdlObjectCommandTag("DROP", tokens[raw.token_start + 1 .. raw.token_end]);
        if (first.matchesKeywordTag(.truncate)) return "TRUNCATE";
        if (first.matchesKeywordTag(.grant)) return "GRANT";
        if (first.matchesKeywordTag(.revoke)) return "REVOKE";
        if (first.matchesKeywordTag(.set)) return "SET";
        if (first.matchesKeywordTag(.show)) return "SHOW";
        if (first.matchesKeywordTag(.reset)) return "RESET";
        if (first.matchesKeywordTag(.discard)) return "DISCARD";
        if (first.matchesKeywordTag(.begin)) return "BEGIN";
        if (first.matchesKeyword("start") and raw.token_start + 1 < raw.token_end and tokens[raw.token_start + 1].matchesKeyword("transaction")) return "BEGIN";
        if (first.matchesKeywordTag(.commit)) return "COMMIT";
        if (first.matchesKeywordTag(.rollback)) return "ROLLBACK";
        if (first.matchesKeywordTag(.listen)) return "LISTEN";
        if (first.matchesKeywordTag(.notify)) return "NOTIFY";
        if (first.matchesKeywordTag(.unlisten)) return "UNLISTEN";
        if (first.matchesKeywordTag(.prepare)) return "PREPARE";
        if (first.matchesKeywordTag(.execute)) return "EXECUTE";
        if (first.matchesKeywordTag(.deallocate)) return "DEALLOCATE";
        if (first.matchesKeywordTag(.call)) return "CALL";
        return "DDL";
    }

    fn publicSqlStatementKindForLogicalPlan(plan: sql_adapter.LogicalSqlPlan) []const u8 {
        return switch (plan) {
            .read => |kind| @tagName(kind),
            .write => |kind| @tagName(kind),
            .catalog_read => "read",
            .catalog_write => "write",
            .table_ddl, .catalog_ddl, .other_ddl => "ddl",
            .session => "session",
            .transaction => "transaction",
            .prepared_statement => "prepared_statement",
            .cursor => "cursor",
            .notification => "notification",
            .routine => "routine",
            .auth => "auth",
            .extension => "extension",
            .maintenance => "maintenance",
            .bulk_io => "bulk_io",
        };
    }

    fn publicSqlStatementKindForDurablePlan(plan: sql_adapter.DurableSqlPlan) []const u8 {
        return switch (plan) {
            .table_ddl, .catalog_ddl => "ddl",
            .extension => "extension",
            .auth => "auth",
            .routine => "routine",
            .maintenance => "maintenance",
            .bulk_io => "bulk_io",
        };
    }

    fn publicSqlLogicalPlanUsesDurableExecution(plan: sql_adapter.LogicalSqlPlan) bool {
        return switch (plan) {
            .table_ddl, .catalog_ddl, .extension, .auth, .maintenance, .bulk_io => true,
            .routine => |routine| switch (routine) {
                .function_catalog, .trigger_catalog => true,
                .procedure_call => false,
            },
            else => false,
        };
    }

    fn takePublicSqlPlannedExecutionPlanFromLogical(logical_plan: *sql_adapter.LogicalSqlPlan) !PublicSqlPlannedExecutionPlan {
        if (publicSqlLogicalPlanUsesDurableExecution(logical_plan.*)) {
            return .{ .durable = try sql_adapter.takeDurableSqlPlanFromLogical(logical_plan) };
        }
        var plan = logical_plan.*;
        switch (plan) {
            .catalog_write => |*write| {
                write.options.unique_resolver = null;
                write.options.default_context.sequence_resolver = null;
                write.options.default_context.scalar_subquery_resolver = null;
            },
            else => {},
        }
        logical_plan.* = .{ .other_ddl = .{ .moved = {} } };
        return .{ .logical = plan };
    }

    fn publicSqlCreateDdlCommandTag(tokens: []const sql_adapter.Token) []const u8 {
        var index: usize = 0;
        while (index < tokens.len and publicSqlCreateDdlModifier(tokens[index])) : (index += 1) {}
        if (index >= tokens.len) return "CREATE";
        if (tokens[index].matchesKeywordTag(.index)) return "CREATE INDEX";
        return publicSqlDdlObjectCommandTag("CREATE", tokens[index..]);
    }

    fn publicSqlCreateDdlModifier(token: sql_adapter.Token) bool {
        return token.matchesKeywordTag(.unique) or
            token.matchesKeywordTag(.@"or") or
            token.matchesKeywordTag(.replace) or
            token.matchesKeyword("temporary") or
            token.matchesKeyword("temp") or
            token.matchesKeyword("unlogged") or
            token.matchesKeyword("concurrently");
    }

    fn publicSqlDdlObjectCommandTag(comptime verb: []const u8, tokens: []const sql_adapter.Token) []const u8 {
        for (tokens) |token| {
            if (publicSqlDdlObjectModifier(token)) continue;
            if (token.matchesKeywordTag(.table)) return verb ++ " TABLE";
            if (token.matchesKeywordTag(.index)) return verb ++ " INDEX";
            if (token.matchesKeywordTag(.database)) return verb ++ " DATABASE";
            if (token.matchesKeywordTag(.schema)) return verb ++ " SCHEMA";
            if (token.matchesKeyword("tablespace")) return verb ++ " TABLESPACE";
            if (token.matchesKeywordTag(.extension)) return verb ++ " EXTENSION";
            if (token.matchesKeyword("role")) return verb ++ " ROLE";
            if (token.matchesKeywordTag(.function)) return verb ++ " FUNCTION";
            if (token.matchesKeywordTag(.procedure)) return verb ++ " PROCEDURE";
            if (token.matchesKeywordTag(.trigger)) return verb ++ " TRIGGER";
            if (token.matchesKeywordTag(.view)) return verb ++ " VIEW";
            if (token.matchesKeywordTag(.policy)) return verb ++ " POLICY";
            return verb;
        }
        return verb;
    }

    fn publicSqlDdlObjectModifier(token: sql_adapter.Token) bool {
        return token.matchesKeywordTag(.@"if") or
            token.matchesKeywordTag(.not) or
            token.matchesKeywordTag(.exists) or
            token.matchesKeywordTag(.only) or
            token.matchesKeyword("concurrently") or
            token.matchesKeywordTag(.@"or") or
            token.matchesKeywordTag(.replace) or
            token.matchesKeyword("temporary") or
            token.matchesKeyword("temp") or
            token.matchesKeyword("unlogged");
    }

    fn applyLoweredPublicSqlRowsBatch(
        self: *ApiHttpServer,
        table_name: []const u8,
        schema: runtime_schema_mod.TableSchema,
        rows_batch: *relational_rows_api.OwnedRowsBatchRequest,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !?http_common.HttpResponse {
        const target = catalog_resources.TableTarget{
            .database_name = tables_api.default_database_name,
            .namespace_name = catalog_resources.default_namespace_name,
            .table_name = table_name,
        };
        return try self.applyLoweredPublicSqlRowsBatchForTarget(target, table_name, schema, rows_batch, authenticated_identity);
    }

    fn applyLoweredPublicSqlRowsBatchForTarget(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        native_table_name: []const u8,
        schema: runtime_schema_mod.TableSchema,
        rows_batch: *relational_rows_api.OwnedRowsBatchRequest,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !?http_common.HttpResponse {
        const source = self.table_writes orelse return try textResponse(self.alloc, 404, "not found");

        self.applyLoweredPublicSqlRowsBatchBeforeTriggers(target.table_name, schema, rows_batch) catch |err| switch (err) {
            error.InvalidRowsRequest, error.RoutineBodyNotExecutable, error.RoutineNotFound => return try textResponse(self.alloc, 400, "invalid sql write"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 501, "unsupported sql statement"),
            else => return err,
        };

        if (rows_batch.writes.len == 0 and rows_batch.deletes.len == 0 and rows_batch.transforms.len == 0 and rows_batch.predicates.len == 0) return null;

        const resource_name = try catalog_resources.tableResourceNameAlloc(self.alloc, target.database_name, target.namespace_name, target.table_name);
        defer self.alloc.free(resource_name);
        self.requireRowsBatchSatisfiesEffectiveFilterForDatabase(target.database_name, resource_name, target, rows_batch.*, authenticated_identity) catch |err| switch (err) {
            error.PermissionDenied => return try textResponse(self.alloc, 403, "row filter rejected sql write"),
            else => return err,
        };

        var committed_via_txn = false;
        if (schema.storage_mode == .relational) {
            const txn_writes = try self.alloc.alloc(db_mod.types.TransactionWrite, rows_batch.writes.len);
            defer self.alloc.free(txn_writes);
            for (rows_batch.writes, 0..) |write, i| {
                txn_writes[i] = .{ .key = write.key, .value = write.value };
            }
            const txn_tables = [_]distributed_txn.TableCommitRequest{.{
                .table_name = native_table_name,
                .writes = txn_writes,
                .deletes = rows_batch.deletes,
                .transforms = rows_batch.transforms,
                .predicates = rows_batch.predicates,
            }};
            if (source.commitTransaction(self.alloc, txn_tables[0..], rows_batch.req.sync_level) catch |err| switch (err) {
                error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return try textResponse(self.alloc, 400, "invalid sql write"),
                error.VersionConflict, error.IntentConflict, error.DecisionConflict, error.TxnNotFound, error.InvalidTxnRecord => return try textResponse(self.alloc, 409, "version conflict"),
                error.TopologyChanged => return try textResponse(self.alloc, 503, "topology changed"),
                error.LeaderUnavailable, error.WriteUnavailable => return try textResponse(self.alloc, 503, "write unavailable"),
                error.TableNotFound, error.UnknownGroup => {
                    std.log.err("public sql write transaction not found table={s} target={s}.{s}.{s} err={}", .{ native_table_name, target.database_name, target.namespace_name, target.table_name, err });
                    return try textResponse(self.alloc, 404, "not found");
                },
                error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "doc identity unavailable"),
                error.EnrichmentRetryInProgress => return try textResponse(self.alloc, 429, "table backpressured"),
                error.UnsupportedOperation => null,
                else => {
                    std.log.err("public sql write transaction failed table={s} target={s}.{s}.{s} err={}", .{ native_table_name, target.database_name, target.namespace_name, target.table_name, err });
                    return try textResponse(self.alloc, 500, "sql write failed");
                },
            }) |outcome| {
                defer outcome.deinit(self.alloc);
                switch (outcome) {
                    .committed => committed_via_txn = true,
                    .conflict => return try textResponse(self.alloc, 409, "version conflict"),
                }
            }
        }

        if (!committed_via_txn) {
            _ = (source.batch(self.alloc, native_table_name, rows_batch.req) catch |err| switch (err) {
                error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return try textResponse(self.alloc, 400, "invalid sql write"),
                error.VersionConflict, error.IntentConflict => return try textResponse(self.alloc, 409, "version conflict"),
                error.LeaderUnavailable, error.WriteUnavailable => return try textResponse(self.alloc, 503, "write unavailable"),
                error.TableNotFound => {
                    std.log.err("public sql write batch not found table={s} target={s}.{s}.{s} err={}", .{ native_table_name, target.database_name, target.namespace_name, target.table_name, err });
                    return try textResponse(self.alloc, 404, "not found");
                },
                error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "doc identity unavailable"),
                error.EnrichmentRetryInProgress => return try textResponse(self.alloc, 429, "table backpressured"),
                else => {
                    std.log.err("public sql write batch failed table={s} target={s}.{s}.{s} err={}", .{ native_table_name, target.database_name, target.namespace_name, target.table_name, err });
                    return try textResponse(self.alloc, 500, "sql write failed");
                },
            }) orelse return try textResponse(self.alloc, 404, "not found");
        }
        return null;
    }

    fn publicSqlRowsBatchRowCount(rows_batch: relational_rows_api.OwnedRowsBatchRequest) usize {
        return @as(usize, @intCast(rows_batch.inserted)) +
            @as(usize, @intCast(rows_batch.deleted)) +
            @as(usize, @intCast(rows_batch.transformed));
    }

    fn publicSqlRowsBatchAuditFailureName(response: http_common.HttpResponse) []const u8 {
        if (response.status == 403 and std.mem.eql(u8, response.body, "row filter rejected sql write")) return "PermissionDenied";
        if (response.status == 409 and std.mem.eql(u8, response.body, "version conflict")) return "VersionConflict";
        return "PublicSqlRowsBatchFailed";
    }

    fn applyLoweredPublicSqlDocumentMergeRowsBatchWithAudit(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        schema: runtime_schema_mod.TableSchema,
        rows_batch: *relational_rows_api.OwnedRowsBatchRequest,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !?http_common.HttpResponse {
        const native_table_name = try catalog_resources.storageTableNameForTargetAlloc(self.alloc, target);
        defer self.alloc.free(native_table_name);
        if (try self.applyLoweredPublicSqlRowsBatchForTarget(target, native_table_name, schema, rows_batch, authenticated_identity)) |failure| {
            const outcome: PublicSqlAuditOutcome = if (failure.status == 403) .denied else .failed;
            self.recordPublicSqlAuditOutcome(
                .merge,
                .rows_batch,
                target,
                0,
                authenticated_identity,
                outcome,
                publicSqlRowsBatchAuditFailureName(failure),
            );
            return failure;
        }
        self.recordPublicSqlAuditOutcome(
            .merge,
            .rows_batch,
            target,
            publicSqlRowsBatchRowCount(rows_batch.*),
            authenticated_identity,
            .applied,
            null,
        );
        return null;
    }

    fn takePublicSqlRowsBatchFromDocumentBatch(document_batch: *sql_adapter.OwnedDocumentBatchRequest) relational_rows_api.OwnedRowsBatchRequest {
        const rows_batch = relational_rows_api.OwnedRowsBatchRequest{
            .writes = document_batch.writes,
            .deletes = document_batch.deletes,
            .transforms = document_batch.transforms,
            .predicates = document_batch.predicates,
            .returning_rows = document_batch.returning_rows,
            .returning_version_keys = document_batch.returning_version_keys,
            .returning_version_prewrite = document_batch.returning_version_prewrite,
            .returning_version_outputs = document_batch.returning_version_outputs,
            .req = document_batch.req,
            .inserted = document_batch.inserted,
            .deleted = document_batch.deleted,
            .transformed = document_batch.transformed,
        };
        document_batch.writes = &.{};
        document_batch.deletes = &.{};
        document_batch.transforms = &.{};
        document_batch.predicates = &.{};
        document_batch.returning_rows = &.{};
        document_batch.returning_version_keys = &.{};
        document_batch.returning_version_prewrite = &.{};
        document_batch.returning_version_outputs = &.{};
        document_batch.req = .{};
        document_batch.inserted = 0;
        document_batch.deleted = 0;
        document_batch.transformed = 0;
        return rows_batch;
    }

    fn finalizePublicSqlDocumentReturningVersions(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        rows_batch: *relational_rows_api.OwnedRowsBatchRequest,
    ) !void {
        if (rows_batch.returning_version_keys.len == 0) return;
        if (rows_batch.returning_version_keys.len != rows_batch.returning_rows.len or
            rows_batch.returning_version_prewrite.len != rows_batch.returning_rows.len or
            rows_batch.returning_version_outputs.len == 0)
        {
            return error.InvalidRowsRequest;
        }

        const read_source = self.effectivePublicTableReads() orelse return error.TableNotFound;
        const native_table_name = try catalog_resources.storageTableNameForTargetAlloc(self.alloc, .{
            .database_name = target.database_name,
            .namespace_name = target.namespace_name,
            .table_name = target.table_name,
        });
        defer self.alloc.free(native_table_name);

        for (rows_batch.returning_rows, 0..) |row_json, i| {
            const version = if (rows_batch.returning_version_prewrite[i] != 0)
                rows_batch.returning_version_prewrite[i]
            else blk: {
                var lookup = (try read_source.lookup(self.alloc, native_table_name, rows_batch.returning_version_keys[i], .{}, .read_index)) orelse return error.InvalidRowsRequest;
                defer lookup.deinit(self.alloc);
                break :blk lookup.version;
            };

            var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, row_json, .{ .allocate = .alloc_always }) catch return error.InvalidRowsRequest;
            defer parsed.deinit();
            if (parsed.value != .object) return error.InvalidRowsRequest;
            for (rows_batch.returning_version_outputs) |output| {
                if (parsed.value.object.getPtr(output)) |slot| {
                    json_helpers.deinitJsonValue(self.alloc, slot);
                    slot.* = .{ .integer = @intCast(version) };
                } else {
                    const owned_output = try self.alloc.dupe(u8, output);
                    errdefer self.alloc.free(owned_output);
                    try parsed.value.object.put(self.alloc, owned_output, .{ .integer = @intCast(version) });
                }
            }
            const finalized = try std.json.Stringify.valueAlloc(self.alloc, parsed.value, .{});
            self.alloc.free(@constCast(rows_batch.returning_rows[i]));
            rows_batch.returning_rows[i] = finalized;
        }
    }

    fn applyLoweredPublicSqlRowsBatchBeforeTriggers(
        self: *ApiHttpServer,
        table_name: []const u8,
        schema: runtime_schema_mod.TableSchema,
        rows_batch: *relational_rows_api.OwnedRowsBatchRequest,
    ) !void {
        var insert_trigger = try self.rowsBatchTriggerForEventAlloc(table_name, .insert);
        defer if (insert_trigger) |*trigger| trigger.deinit(self.alloc);
        var update_trigger = try self.rowsBatchTriggerForEventAlloc(table_name, .update);
        defer if (update_trigger) |*trigger| trigger.deinit(self.alloc);
        var delete_trigger = try self.rowsBatchTriggerForEventAlloc(table_name, .delete);
        defer if (delete_trigger) |*trigger| trigger.deinit(self.alloc);

        if (update_trigger != null and rows_batch.transforms.len != 0) return error.UnsupportedOperation;
        if (delete_trigger != null and rows_batch.deletes.len != 0) return error.UnsupportedOperation;
        if (insert_trigger == null or rows_batch.writes.len == 0) return;
        if (rows_batch.transforms.len != 0 or rows_batch.deletes.len != 0 or rows_batch.relational_identity_rewrites.len != 0) return error.UnsupportedOperation;
        if (rows_batch.predicates.len != rows_batch.writes.len) return error.UnsupportedOperation;
        if (rows_batch.returning_rows.len != 0 and rows_batch.returning_rows.len != rows_batch.writes.len) return error.UnsupportedOperation;

        try self.applyLoweredPublicSqlRowsBatchBeforeInsertTrigger(table_name, schema, insert_trigger.?, rows_batch);
    }

    fn applyLoweredPublicSqlRowsBatchBeforeInsertTrigger(
        self: *ApiHttpServer,
        table_name: []const u8,
        schema: runtime_schema_mod.TableSchema,
        insert_trigger: RowsBatchTrigger,
        rows_batch: *relational_rows_api.OwnedRowsBatchRequest,
    ) !void {
        _ = table_name;
        var writes = std.ArrayListUnmanaged(db_mod.types.BatchWrite).empty;
        var predicates = std.ArrayListUnmanaged(db_mod.types.TransactionVersionPredicate).empty;
        var returning_rows = std.ArrayListUnmanaged([]const u8).empty;
        errdefer {
            for (writes.items) |write| {
                self.alloc.free(@constCast(write.key));
                self.alloc.free(@constCast(write.value));
            }
            writes.deinit(self.alloc);
            for (predicates.items) |predicate| self.alloc.free(@constCast(predicate.key));
            predicates.deinit(self.alloc);
            for (returning_rows.items) |row| self.alloc.free(@constCast(row));
            returning_rows.deinit(self.alloc);
        }

        for (rows_batch.writes, 0..) |write, i| {
            const triggered_row = try self.sql_routine_runtime.executeTriggerRoutineAlloc(self.alloc, insert_trigger.function_name, write.value, null);
            defer self.alloc.free(triggered_row);
            var parsed_triggered = std.json.parseFromSlice(std.json.Value, self.alloc, triggered_row, .{ .allocate = .alloc_always }) catch return error.InvalidRowsRequest;
            defer parsed_triggered.deinit();
            if (parsed_triggered.value == .null) continue;
            if (parsed_triggered.value != .object) return error.InvalidRowsRequest;

            const key = try relational_rows_api.physicalPrimaryKeyFromRowJsonAlloc(self.alloc, schema, triggered_row);
            var key_transferred = false;
            errdefer if (!key_transferred) self.alloc.free(key);
            const value = try self.alloc.dupe(u8, triggered_row);
            var value_transferred = false;
            errdefer if (!value_transferred) self.alloc.free(value);
            try writes.append(self.alloc, .{ .key = key, .value = value });
            key_transferred = true;
            value_transferred = true;

            const predicate_key = try self.alloc.dupe(u8, key);
            var predicate_key_transferred = false;
            errdefer if (!predicate_key_transferred) self.alloc.free(predicate_key);
            try predicates.append(self.alloc, .{
                .key = predicate_key,
                .expected_version = rows_batch.predicates[i].expected_version,
            });
            predicate_key_transferred = true;

            if (rows_batch.returning_rows.len != 0) {
                const returning_row = try self.alloc.dupe(u8, rows_batch.returning_rows[i]);
                var returning_row_transferred = false;
                errdefer if (!returning_row_transferred) self.alloc.free(returning_row);
                try returning_rows.append(self.alloc, returning_row);
                returning_row_transferred = true;
            }
        }

        const writes_slice = try writes.toOwnedSlice(self.alloc);
        errdefer {
            for (writes_slice) |write| {
                self.alloc.free(@constCast(write.key));
                self.alloc.free(@constCast(write.value));
            }
            if (writes_slice.len > 0) self.alloc.free(writes_slice);
        }
        const predicates_slice = try predicates.toOwnedSlice(self.alloc);
        errdefer {
            for (predicates_slice) |predicate| self.alloc.free(@constCast(predicate.key));
            if (predicates_slice.len > 0) self.alloc.free(predicates_slice);
        }
        const returning_rows_slice = try returning_rows.toOwnedSlice(self.alloc);
        errdefer {
            for (returning_rows_slice) |row| self.alloc.free(@constCast(row));
            if (returning_rows_slice.len > 0) self.alloc.free(returning_rows_slice);
        }

        var triggered_req = relational_rows_api.OwnedRowsBatchRequest{
            .writes = writes_slice,
            .predicates = predicates_slice,
            .returning_rows = returning_rows_slice,
            .req = .{
                .writes = writes_slice,
                .predicates = predicates_slice,
                .timestamp_ns = rows_batch.req.timestamp_ns,
                .sync_level = rows_batch.req.sync_level,
            },
            .inserted = @intCast(writes_slice.len),
        };
        errdefer triggered_req.deinit(self.alloc);
        rows_batch.deinit(self.alloc);
        rows_batch.* = triggered_req;
    }

    fn applyLoweredPublicSqlInsertSource(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        native_target_table: []const u8,
        target_schema: runtime_schema_mod.TableSchema,
        lowered: *sql_adapter.LoweredInsertSource,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !union(enum) {
        failure: http_common.HttpResponse,
        result: db_mod.types.RelationalRowsMutationSourceResult,
    } {
        const read_source = self.effectivePublicTableReads() orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };

        var source_target = try self.publicSqlSideTableTargetForWriteAlloc(target, lowered.insert_source.req.source_table, session);
        defer source_target.deinit(self.alloc);
        const source = source_target.target();
        const native_source_table = try catalog_resources.storageTableNameForTargetAlloc(self.alloc, source);
        defer self.alloc.free(native_source_table);

        self.enforceAuthenticatedIdentitySqlTablePermission(authenticated_identity, source, .read) catch |err| switch (err) {
            error.PermissionDenied => return .{ .failure = try textResponse(self.alloc, 403, "forbidden") },
            else => return err,
        };

        const source_schema = self.runtimeSchemaForCatalogRows(source) catch |err| switch (err) {
            error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.InvalidRowsRequest => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            else => return err,
        };
        defer runtime_schema_mod.freeSchema(self.alloc, source_schema);

        var filter = self.rowsAuthFilterPlanForTarget(source, authenticated_identity, source_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (filter) |*value| value.deinit(self.alloc);
        if (filter) |active| {
            for (@constCast(lowered.ctes)) |*cte| try self.applyRowsAuthFilterToQuery(source_schema, active, &cte.query);
            if (lowered.literal_source_rows.len == 0) {
                if (lowered.insert_source.req.source.source_cte.len == 0) try self.applyRowsAuthFilterToQuery(source_schema, active, &lowered.insert_source.req.source);
            } else {
                for (@constCast(lowered.insert_source.req.source.scalar_subqueries)) |*projection| {
                    try self.applyRowsAuthFilterToQuery(source_schema, active, &projection.query);
                }
            }
        }

        const planned_ctes = relational_rows_api.planRowsCteOutputsAlloc(self.alloc, source_schema, lowered.ctes) catch |err| switch (err) {
            error.InvalidRowsRequest => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            else => return err,
        };
        defer relational_rows_api.freeRowsPlannedCtes(self.alloc, planned_ctes);
        const effective_source_schema = relational_rows_api.rowsPlannedQuerySourceSchema(source_schema, planned_ctes, lowered.insert_source.req.source) orelse return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") };

        var unique_resolver_ctx = RowsUniqueSelectorResolverContext{ .source = self.table_reads };
        var sequence_resolver_ctx = RowsSequenceDefaultResolverContext{ .source = self.source };
        var scalar_default_resolver_ctx = RowsScalarSubqueryDefaultResolverContext{ .source = self.source, .table_reads = read_source };
        const default_context = relational_rows_api.DefaultValueContext{
            .sequence_resolver = sequence_resolver_ctx.resolver(),
            .scalar_subquery_resolver = scalar_default_resolver_ctx.resolver(),
        };
        var matched_len: usize = 0;
        var rows_batch: relational_rows_api.OwnedRowsBatchRequest = if (lowered.literal_source_rows.len != 0) literal_blk: {
            if (lowered.ctes.len != 0) return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") };
            matched_len = lowered.literal_source_rows.len;
            break :literal_blk self.buildPublicSqlLiteralInsertSourceRowsBatchAlloc(
                read_source,
                native_target_table,
                target_schema,
                native_source_table,
                effective_source_schema,
                lowered.insert_source.req,
                lowered.literal_source_rows,
                lowered.literal_source_row_scalar_subqueries,
                unique_resolver_ctx.resolver(),
                default_context,
            ) catch |err| switch (err) {
                error.UnsupportedRowsSelector => return .{ .failure = try textResponse(self.alloc, 400, "unsupported rows selector") },
                error.RowSelectorNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
                error.UniqueOwnerTopologyUnavailable, error.TopologyChanged, error.DocIdentityNamespaceMismatch => return .{ .failure = try textResponse(self.alloc, 503, "unique owner unavailable") },
                error.InvalidRowsRequest, error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation, error.SequenceNotFound, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.RelationalRowsCteMaterializationRejected => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
                error.RelationalRowsCteSpillRequired => return .{ .failure = try textResponse(self.alloc, 429, "sql write backpressured") },
                error.UnsupportedOperation, error.UnsupportedRowsQuery, error.UnsupportedSqlShape => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
                error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
                error.LeaderUnavailable, error.ReadUnavailable => return .{ .failure = try textResponse(self.alloc, 503, "read unavailable") },
                else => {
                    std.log.err("public sql literal insert source plan failed table={s}.{s}.{s} source={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, source.database_name, source.namespace_name, source.table_name, err });
                    return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
                },
            };
        } else table_blk: {
            var source_result = (self.publicSqlRowsQueryPlanForTargetAlloc(
                read_source,
                source,
                native_source_table,
                source_schema,
                .{ .ctes = lowered.ctes, .query = lowered.insert_source.req.source },
            ) catch |err| switch (err) {
                error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.RelationalRowsCteMaterializationRejected => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
                error.RelationalRowsCteSpillRequired => return .{ .failure = try textResponse(self.alloc, 429, "sql write backpressured") },
                error.UnsupportedOperation, error.UnsupportedRowsQuery => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
                error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
                error.TopologyChanged => return .{ .failure = try textResponse(self.alloc, 503, "topology changed") },
                error.LeaderUnavailable, error.ReadUnavailable => return .{ .failure = try textResponse(self.alloc, 503, "read unavailable") },
                else => {
                    std.log.err("public sql insert source read failed table={s}.{s}.{s} source={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, source.database_name, source.namespace_name, source.table_name, err });
                    return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
                },
            }) orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
            defer source_result.deinit(self.alloc);
            matched_len = source_result.rows.len;
            break :table_blk relational_rows_api.buildRowsInsertSourceBatchWithSchemasAndDefaultContextAlloc(
                self.alloc,
                native_target_table,
                target_schema,
                effective_source_schema,
                lowered.insert_source.req,
                source_result.rows,
                unique_resolver_ctx.resolver(),
                default_context,
            ) catch |err| switch (err) {
                error.UnsupportedRowsSelector => return .{ .failure = try textResponse(self.alloc, 400, "unsupported rows selector") },
                error.RowSelectorNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
                error.UniqueOwnerTopologyUnavailable, error.TopologyChanged, error.DocIdentityNamespaceMismatch => return .{ .failure = try textResponse(self.alloc, 503, "unique owner unavailable") },
                error.InvalidRowsRequest, error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation, error.SequenceNotFound => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
                else => {
                    std.log.err("public sql insert source plan failed table={s}.{s}.{s} source={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, source.database_name, source.namespace_name, source.table_name, err });
                    return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
                },
            };
        };
        defer rows_batch.deinit(self.alloc);
        rows_batch.req.sync_level = lowered.sync_level;

        if (try self.applyLoweredPublicSqlRowsBatchForTarget(target, native_target_table, target_schema, &rows_batch, authenticated_identity)) |failure| return .{ .failure = failure };
        return .{ .result = try rowsInsertSourceMutationResultAlloc(self.alloc, matched_len, rows_batch) };
    }

    fn buildPublicSqlLiteralInsertSourceRowsBatchAlloc(
        self: *ApiHttpServer,
        read_source: table_reads.TableReadSource,
        target_table_name: []const u8,
        target_schema: runtime_schema_mod.TableSchema,
        source_table_name: []const u8,
        source_schema: runtime_schema_mod.TableSchema,
        req: db_mod.types.RelationalRowsInsertSourceRequest,
        literal_source_rows: []const []const u8,
        literal_source_row_scalar_subqueries: []const []const db_mod.types.RelationalRowsScalarSubqueryProjection,
        unique_resolver: ?relational_rows_api.UniqueSelectorResolver,
        default_context: relational_rows_api.DefaultValueContext,
    ) !relational_rows_api.OwnedRowsBatchRequest {
        if (literal_source_rows.len == 0) return error.InvalidRowsRequest;
        if (req.source.source_cte.len != 0) return error.InvalidRowsRequest;
        if (literal_source_row_scalar_subqueries.len != 0 and literal_source_row_scalar_subqueries.len != literal_source_rows.len) return error.InvalidRowsRequest;

        const materialized_rows = try self.literalInsertSourceRowsWithScalarSubqueriesAlloc(
            read_source,
            source_table_name,
            source_schema,
            req.source.scalar_subqueries,
            literal_source_row_scalar_subqueries,
            literal_source_rows,
        );
        defer freeStringSlice(self.alloc, materialized_rows);

        return try relational_rows_api.buildRowsInsertSourceBatchWithSchemasAndDefaultContextAlloc(
            self.alloc,
            target_table_name,
            target_schema,
            source_schema,
            req,
            materialized_rows,
            unique_resolver,
            default_context,
        );
    }

    fn literalInsertSourceRowsWithScalarSubqueriesAlloc(
        self: *ApiHttpServer,
        read_source: table_reads.TableReadSource,
        source_table_name: []const u8,
        source_schema: runtime_schema_mod.TableSchema,
        scalar_subqueries: []const db_mod.types.RelationalRowsScalarSubqueryProjection,
        row_scalar_subqueries: []const []const db_mod.types.RelationalRowsScalarSubqueryProjection,
        literal_source_rows: []const []const u8,
    ) ![]const []const u8 {
        const rows = try self.alloc.alloc([]const u8, literal_source_rows.len);
        var initialized: usize = 0;
        errdefer {
            for (rows[0..initialized]) |row| self.alloc.free(row);
            self.alloc.free(rows);
        }

        for (literal_source_rows, 0..) |row_json, i| {
            const effective_scalar_subqueries = if (row_scalar_subqueries.len != 0 and row_scalar_subqueries[i].len != 0) row_scalar_subqueries[i] else scalar_subqueries;
            rows[i] = if (!httpHiddenScalarSubqueriesPresent(effective_scalar_subqueries))
                try self.alloc.dupe(u8, row_json)
            else
                try self.publicSqlRowJsonWithHiddenScalarSubqueriesAlloc(read_source, source_table_name, source_schema, row_json, effective_scalar_subqueries);
            initialized += 1;
        }
        return rows;
    }

    const HttpLiteralScalarSubqueryValue = struct {
        output: []const u8,
        value_json: []const u8,
    };

    fn httpHiddenScalarSubqueriesPresent(scalar_subqueries: []const db_mod.types.RelationalRowsScalarSubqueryProjection) bool {
        for (scalar_subqueries) |projection| {
            if (projection.hidden) return true;
        }
        return false;
    }

    fn publicSqlRowJsonWithHiddenScalarSubqueriesAlloc(
        self: *ApiHttpServer,
        read_source: table_reads.TableReadSource,
        source_table_name: []const u8,
        source_schema: runtime_schema_mod.TableSchema,
        row_json: []const u8,
        scalar_subqueries: []const db_mod.types.RelationalRowsScalarSubqueryProjection,
    ) ![]const u8 {
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, row_json, .{}) catch return error.InvalidRowsRequest;
        defer parsed.deinit();
        if (parsed.value != .object) return error.InvalidRowsRequest;

        var scalar_values = std.ArrayListUnmanaged(HttpLiteralScalarSubqueryValue).empty;
        defer {
            for (scalar_values.items) |value| self.alloc.free(value.value_json);
            scalar_values.deinit(self.alloc);
        }

        for (scalar_subqueries) |projection| {
            if (!projection.hidden) continue;
            const value_json = try self.publicSqlScalarSubqueryProjectionValueJsonAlloc(read_source, source_table_name, source_schema, parsed.value, projection);
            errdefer self.alloc.free(value_json);
            try scalar_values.append(self.alloc, .{
                .output = projection.output,
                .value_json = value_json,
            });
        }
        return try httpRowJsonWithHiddenScalarValuesFromParsedAlloc(self.alloc, parsed.value, scalar_values.items);
    }

    fn publicSqlScalarSubqueryProjectionValueJsonAlloc(
        self: *ApiHttpServer,
        read_source: table_reads.TableReadSource,
        source_table_name: []const u8,
        source_schema: runtime_schema_mod.TableSchema,
        outer_row: std.json.Value,
        projection: db_mod.types.RelationalRowsScalarSubqueryProjection,
    ) ![]const u8 {
        var query = projection.query;
        var correlated_predicates: []runtime_schema_mod.RelationalCheck = &.{};
        defer httpFreeOwnedRelationalChecks(self.alloc, correlated_predicates);
        var combined_predicates: []runtime_schema_mod.RelationalCheck = &.{};
        defer if (combined_predicates.len > 0) self.alloc.free(combined_predicates);
        if (projection.correlations.len != 0) {
            correlated_predicates = try httpLateralCorrelationPredicatesAlloc(self.alloc, outer_row, projection.correlations);
            if (correlated_predicates.len != projection.correlations.len) return try self.alloc.dupe(u8, "null");
            combined_predicates = try httpCombinedBorrowedAndOwnedRelationalChecksAlloc(self.alloc, projection.query.predicates, correlated_predicates);
            query.predicates = combined_predicates;
        }
        var result = (try read_source.rowsQueryPlan(
            self.alloc,
            source_table_name,
            source_schema,
            .{ .query = query },
            .read_index,
        )) orelse return error.TableNotFound;
        defer result.deinit(self.alloc);
        if (result.rows.len > 1) return error.InvalidRowsRequest;
        if (result.rows.len == 0) return try self.alloc.dupe(u8, "null");

        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, result.rows[0], .{}) catch return error.InvalidRowsRequest;
        defer parsed.deinit();
        const value = httpJsonValueAtPath(parsed.value, projection.output_field) orelse return try self.alloc.dupe(u8, "null");
        return try std.json.Stringify.valueAlloc(self.alloc, value.*, .{});
    }

    fn httpLateralCorrelationPredicatesAlloc(
        alloc: std.mem.Allocator,
        left_row: std.json.Value,
        correlations: []const db_mod.types.RelationalRowsLateralCorrelation,
    ) ![]runtime_schema_mod.RelationalCheck {
        const predicates = try alloc.alloc(runtime_schema_mod.RelationalCheck, correlations.len);
        var initialized: usize = 0;
        errdefer {
            httpFreeOwnedRelationalCheckContents(alloc, predicates[0..initialized]);
            alloc.free(predicates);
        }
        for (correlations) |correlation| {
            const selected = httpJsonValueAtPath(left_row, correlation.left_field) orelse break;
            if (selected.* == .null) break;
            const value_json = switch (selected.*) {
                .bool, .integer, .float, .string => try std.json.Stringify.valueAlloc(alloc, selected.*, .{}),
                else => return error.InvalidRowsRequest,
            };
            var value_transferred = false;
            errdefer if (!value_transferred) alloc.free(value_json);
            const name = try alloc.dupe(u8, "");
            var name_transferred = false;
            errdefer if (!name_transferred) alloc.free(name);
            const field = try alloc.dupe(u8, correlation.right_field);
            var field_transferred = false;
            errdefer if (!field_transferred) alloc.free(field);
            predicates[initialized] = .{
                .name = name,
                .field = field,
                .op = correlation.op,
                .value_json = value_json,
            };
            initialized += 1;
            name_transferred = true;
            field_transferred = true;
            value_transferred = true;
        }
        if (initialized != correlations.len) {
            httpFreeOwnedRelationalCheckContents(alloc, predicates[0..initialized]);
            alloc.free(predicates);
            return &.{};
        }
        return predicates;
    }

    fn httpCombinedBorrowedAndOwnedRelationalChecksAlloc(
        alloc: std.mem.Allocator,
        borrowed: []const runtime_schema_mod.RelationalCheck,
        owned: []const runtime_schema_mod.RelationalCheck,
    ) ![]runtime_schema_mod.RelationalCheck {
        const combined = try alloc.alloc(runtime_schema_mod.RelationalCheck, borrowed.len + owned.len);
        @memcpy(combined[0..borrowed.len], borrowed);
        @memcpy(combined[borrowed.len..], owned);
        return combined;
    }

    fn httpFreeOwnedRelationalChecks(alloc: std.mem.Allocator, checks: []const runtime_schema_mod.RelationalCheck) void {
        httpFreeOwnedRelationalCheckContents(alloc, checks);
        if (checks.len > 0) alloc.free(checks);
    }

    fn httpFreeOwnedRelationalCheckContents(alloc: std.mem.Allocator, checks: []const runtime_schema_mod.RelationalCheck) void {
        for (checks) |check| {
            if (check.name.len > 0) alloc.free(@constCast(check.name));
            if (check.field.len > 0) alloc.free(@constCast(check.field));
            if (check.value_json) |value_json| if (value_json.len > 0) alloc.free(@constCast(value_json));
        }
    }

    fn httpRowJsonWithHiddenScalarValuesAlloc(
        alloc: std.mem.Allocator,
        row_json: []const u8,
        scalar_values: []const HttpLiteralScalarSubqueryValue,
    ) ![]const u8 {
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, row_json, .{}) catch return error.InvalidRowsRequest;
        defer parsed.deinit();
        if (parsed.value != .object) return error.InvalidRowsRequest;
        return try httpRowJsonWithHiddenScalarValuesFromParsedAlloc(alloc, parsed.value, scalar_values);
    }

    fn httpRowJsonWithHiddenScalarValuesFromParsedAlloc(
        alloc: std.mem.Allocator,
        row_value: std.json.Value,
        scalar_values: []const HttpLiteralScalarSubqueryValue,
    ) ![]const u8 {
        if (row_value != .object) return error.InvalidRowsRequest;
        var out: std.Io.Writer.Allocating = .init(alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('{');
        var first = true;
        for (row_value.object.keys(), row_value.object.values()) |field, value| {
            for (scalar_values) |scalar_value| {
                if (std.mem.eql(u8, field, scalar_value.output)) return error.InvalidRowsRequest;
            }
            if (!first) try writer.writeByte(',');
            first = false;
            try writer.print("{f}:", .{std.json.fmt(field, .{})});
            try std.json.Stringify.value(value, .{}, writer);
        }
        for (scalar_values) |scalar_value| {
            if (!first) try writer.writeByte(',');
            first = false;
            try writer.print("{f}:{s}", .{ std.json.fmt(scalar_value.output, .{}), scalar_value.value_json });
        }
        try writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    fn httpJsonValueAtPath(root: std.json.Value, path: []const u8) ?*const std.json.Value {
        if (root != .object) return null;
        var current: *const std.json.Value = &root;
        var parts = std.mem.splitScalar(u8, path, '.');
        while (parts.next()) |part| {
            if (part.len == 0 or current.* != .object) return null;
            current = current.object.getPtr(part) orelse return null;
        }
        return current;
    }

    fn nextSqlMutationTxnId() db_mod.types.TxnId {
        const nonce = sql_mutation_txn_id_nonce.fetchAdd(1, .monotonic);
        var txn_id: db_mod.types.TxnId = undefined;
        std.mem.writeInt(u64, txn_id[0..8], platform_time.realtimeNs(), .big);
        std.mem.writeInt(u64, txn_id[8..16], nonce, .big);
        return txn_id;
    }

    fn sqlMutationRowClaimAlloc(self: *ApiHttpServer, session: *sql_adapter.OwnedSqlCatalogSession) !db_mod.types.RowClaimRequest {
        const session_id = self.ensureSqlProtocolSessionId(session);
        return .{
            .mode = .for_update,
            .wait_policy = .wait,
            .skip_locked = false,
            .lease_ms = 30_000,
            .owner_id = try std.fmt.allocPrint(self.alloc, "sql:{d}", .{session_id}),
            .txn_id = nextSqlMutationTxnId(),
        };
    }

    fn ensureNoPublicSqlMutationSourceTrigger(
        self: *ApiHttpServer,
        table_name: []const u8,
        kind: db_mod.types.RelationalRowsMutationKind,
    ) !void {
        const event: sql_routines.TriggerEvent = switch (kind) {
            .update => .update,
            .delete => .delete,
        };
        var trigger = try self.rowsBatchTriggerForEventAlloc(table_name, event);
        defer if (trigger) |*value| value.deinit(self.alloc);
        if (trigger != null) return error.UnsupportedOperation;
    }

    fn publicSqlUnsupportedTruncateSourceDiagnostic(
        truncate_source: sql_adapter.LoweredMutationSource,
    ) sql_adapter.diagnostics.SqlDiagnosticEnvelope {
        const missing_native_model: []const u8 = if (truncate_source.additional_table_names.len != 0)
            "catalog-owned multi-table truncate generation barrier"
        else if (truncate_source.truncate_cascade)
            "catalog-owned truncate cascade expansion and generation barrier"
        else if (truncate_source.restart_identity)
            "catalog-owned identity allocator reset for truncate"
        else
            "catalog-owned table-emptying generation barrier";
        return sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(.plan, .unsupported_sql_statement).withMissingNativeModel(missing_native_model);
    }

    fn publicSqlTableEmptyingRequiresCatalogBarrier(truncate_source: sql_adapter.LoweredMutationSource) bool {
        _ = truncate_source;
        return true;
    }

    const OwnedPublicSqlTableTarget = struct {
        database_name: []u8,
        namespace_name: []u8,
        table_name: []u8,

        fn target(self: OwnedPublicSqlTableTarget) catalog_resources.TableTarget {
            return .{
                .database_name = self.database_name,
                .namespace_name = self.namespace_name,
                .table_name = self.table_name,
            };
        }

        fn deinit(self: *OwnedPublicSqlTableTarget, alloc: std.mem.Allocator) void {
            alloc.free(self.database_name);
            alloc.free(self.namespace_name);
            alloc.free(self.table_name);
            self.* = .{
                .database_name = &.{},
                .namespace_name = &.{},
                .table_name = &.{},
            };
        }
    };

    fn publicSqlOwnedTargetFromCatalogRecordAlloc(
        self: *ApiHttpServer,
        table: *const metadata_table_manager.TableRecord,
    ) !OwnedPublicSqlTableTarget {
        const database_name = try self.alloc.dupe(u8, table.database_name);
        errdefer self.alloc.free(database_name);
        const namespace_name = try self.alloc.dupe(u8, table.namespace_name);
        errdefer self.alloc.free(namespace_name);
        const table_name = try self.alloc.dupe(u8, table.name);
        errdefer self.alloc.free(table_name);
        return .{
            .database_name = database_name,
            .namespace_name = namespace_name,
            .table_name = table_name,
        };
    }

    fn publicSqlOwnedTargetFromTargetAlloc(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
    ) !OwnedPublicSqlTableTarget {
        const database_name = try self.alloc.dupe(u8, target.database_name);
        errdefer self.alloc.free(database_name);
        const namespace_name = try self.alloc.dupe(u8, target.namespace_name);
        errdefer self.alloc.free(namespace_name);
        const table_name = try self.alloc.dupe(u8, target.table_name);
        errdefer self.alloc.free(table_name);
        return .{
            .database_name = database_name,
            .namespace_name = namespace_name,
            .table_name = table_name,
        };
    }

    fn publicSqlExistingTableTargetForSessionAlloc(
        self: *ApiHttpServer,
        table_name: []const u8,
        session: catalog_resources.SqlCatalogSession,
    ) !OwnedPublicSqlTableTarget {
        var snapshot = (try self.source.adminSnapshot()) orelse return error.TableNotFound;
        defer self.source.freeAdminSnapshot(&snapshot);

        const parsed_target = try session.tableTargetFromObjectName(table_name);
        if (std.mem.indexOfScalar(u8, table_name, '.') != null) {
            const table = tables_api.findTableByQualifiedName(&snapshot, parsed_target.database_name, parsed_target.namespace_name, parsed_target.table_name) orelse return error.TableNotFound;
            return try self.publicSqlOwnedTargetFromCatalogRecordAlloc(table);
        }

        const default_search_path: []const []const u8 = &.{catalog_resources.default_namespace_name};
        const search_path = if (session.search_path.len == 0) default_search_path else session.search_path;
        for (search_path) |namespace_name| {
            const table = tables_api.findTableByQualifiedName(&snapshot, session.currentDatabase(), namespace_name, table_name) orelse continue;
            return try self.publicSqlOwnedTargetFromCatalogRecordAlloc(table);
        }
        return error.TableNotFound;
    }

    fn publicSqlSideTableTargetForWriteAlloc(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        source_table_name: []const u8,
        session: catalog_resources.SqlCatalogSession,
    ) !OwnedPublicSqlTableTarget {
        if (source_table_name.len == 0) return try self.publicSqlOwnedTargetFromTargetAlloc(target);
        return try self.publicSqlExistingTableTargetForSessionAlloc(source_table_name, session);
    }

    fn publicSqlTableTargetsEqual(a: catalog_resources.TableTarget, b: catalog_resources.TableTarget) bool {
        return std.mem.eql(u8, a.database_name, b.database_name) and
            std.mem.eql(u8, a.namespace_name, b.namespace_name) and
            std.mem.eql(u8, a.table_name, b.table_name);
    }

    fn publicSqlRowsQueryPlanForTargetAlloc(
        self: *ApiHttpServer,
        read_source: table_reads.TableReadSource,
        target: catalog_resources.TableTarget,
        native_table_name: []const u8,
        schema: runtime_schema_mod.TableSchema,
        plan: db_mod.types.RelationalRowsQueryPlan,
    ) !?db_mod.types.RelationalRowsQueryResult {
        if (read_source.rowsQueryPlanCatalog(self.alloc, target, schema, plan, .read_index)) |result| {
            return result;
        } else |err| switch (err) {
            error.UnsupportedOperation => {},
            else => return err,
        }
        return try read_source.rowsQueryPlan(self.alloc, native_table_name, schema, plan, .read_index);
    }

    fn publicSqlAuditTargetForSession(session: catalog_resources.SqlCatalogSession, table_name: []const u8) catalog_resources.TableTarget {
        return .{
            .database_name = session.currentDatabase(),
            .namespace_name = session.primarySearchPathNamespace(),
            .table_name = table_name,
        };
    }

    fn recordPublicSqlAuditOutcome(
        self: *ApiHttpServer,
        statement_kind: sql_adapter.SqlWriteStatementKind,
        native_route: PublicSqlNativeRoute,
        target: catalog_resources.TableTarget,
        row_count: usize,
        authenticated_identity: ?AuthenticatedIdentity,
        outcome: PublicSqlAuditOutcome,
        error_name: ?[]const u8,
    ) void {
        const subject = if (authenticated_identity) |identity| identity.username else null;
        const record = PublicSqlAuditRecord{
            .timestamp_ns = sqlDdlTimestampNs(),
            .outcome = outcome,
            .statement_kind = statement_kind,
            .native_route = native_route,
            .target = target,
            .required_resource_type = .table,
            .required_permission = .write,
            .authenticated_subject = subject,
            .row_count = row_count,
            .error_name = error_name,
        };
        if (self.cfg.public_sql_audit_sink) |sink| {
            sink.recordEvent(record) catch |audit_err| {
                std.log.warn("failed to record public SQL audit err={s} outcome={s} statement={s} table={s}.{s}.{s}", .{
                    @errorName(audit_err),
                    @tagName(outcome),
                    @tagName(statement_kind),
                    target.database_name,
                    target.namespace_name,
                    target.table_name,
                });
            };
            return;
        }
        std.log.info("public sql {s} statement={s} table={s}.{s}.{s} rows={d} subject={s} route={s} err={s}", .{
            @tagName(outcome),
            @tagName(statement_kind),
            target.database_name,
            target.namespace_name,
            target.table_name,
            row_count,
            subject orelse "",
            @tagName(native_route),
            error_name orelse "",
        });
    }

    const PublicSqlTableEmptyingAdmission = struct {
        applied: tables_api.AppliedRelationalSqlDdlRecord,
        scheduled_jobs: usize,
    };

    fn schedulePublicSqlTableEmptyingJobsWithSession(
        self: *ApiHttpServer,
        target_table_name: []const u8,
        lowered: sql_adapter.LoweredMutationSource,
        session: catalog_resources.SqlCatalogSession,
    ) !PublicSqlTableEmptyingAdmission {
        const catalog = self.catalogSource();
        var admission = try catalog_jobs.scheduleTableEmptyingBarrierForTargetsOnServiceWithSessionAlloc(
            self.alloc,
            catalog,
            target_table_name,
            lowered.additional_table_names,
            lowered.restart_identity,
            lowered.truncate_cascade,
            session,
        );
        defer admission.deinitAffectedTables(self.alloc);
        try self.scheduleTableEmptyingRuntimeHintsForTables(admission.affected_tables);
        return .{
            .applied = admission.applied,
            .scheduled_jobs = admission.scheduled_jobs,
        };
    }

    fn publicSqlReadRequestRowClaimMissingNativeModel(
        request: db_mod.types.RelationalRowsQueryRequest,
        source_kind: []const u8,
    ) ?[]const u8 {
        if (request.row_claim == null) return null;
        if (request.source_cte.len != 0) return "lockable base-row source for CTE row claim";
        if (request.distinct_on.len != 0 or request.distinct_on_expressions.len != 0) return "lockable base-row source for DISTINCT ON row claim";
        if (std.mem.eql(u8, source_kind, "base")) return null;
        return if (std.mem.eql(u8, source_kind, "aggregate"))
            "lockable base-row source for aggregate row claim"
        else if (std.mem.eql(u8, source_kind, "join"))
            "lockable base-row source for join row claim"
        else if (std.mem.eql(u8, source_kind, "lateral"))
            "lockable base-row source for lateral row claim"
        else if (std.mem.eql(u8, source_kind, "window"))
            "lockable base-row source for window row claim"
        else if (std.mem.eql(u8, source_kind, "set operation"))
            "lockable base-row source for set-operation row claim"
        else if (std.mem.eql(u8, source_kind, "recursive CTE"))
            "lockable base-row source for recursive CTE row claim"
        else
            "lockable base-row source for derived row claim";
    }

    fn publicSqlReadCtesRowClaimMissingNativeModel(ctes: []const db_mod.types.RelationalRowsCte) ?[]const u8 {
        for (ctes) |cte| {
            if (publicSqlReadRequestRowClaimMissingNativeModel(cte.query, "CTE")) |_| {
                return "lockable base-row source for materialized CTE row claim";
            }
        }
        return null;
    }

    fn publicSqlQueryPlanRowClaimMissingNativeModel(plan: db_mod.types.RelationalRowsQueryPlan) ?[]const u8 {
        if (publicSqlReadCtesRowClaimMissingNativeModel(plan.ctes)) |model| return model;
        return publicSqlReadRequestRowClaimMissingNativeModel(plan.query, "base");
    }

    fn publicSqlReadPlanRowClaimMissingNativeModel(plan: *const sql_adapter.LoweredReadPlan) ?[]const u8 {
        return switch (plan.*) {
            .query => |query| publicSqlQueryPlanRowClaimMissingNativeModel(query.plan),
            .aggregate => |aggregate| blk: {
                if (publicSqlReadCtesRowClaimMissingNativeModel(aggregate.plan.ctes)) |model| break :blk model;
                break :blk publicSqlReadRequestRowClaimMissingNativeModel(aggregate.plan.aggregate.source, "aggregate");
            },
            .join => |join| blk: {
                if (publicSqlReadCtesRowClaimMissingNativeModel(join.ctes)) |model| break :blk model;
                if (publicSqlReadRequestRowClaimMissingNativeModel(join.join.left, "join")) |model| break :blk model;
                break :blk publicSqlReadRequestRowClaimMissingNativeModel(join.join.right, "join");
            },
            .lateral => |lateral| blk: {
                if (publicSqlReadCtesRowClaimMissingNativeModel(lateral.plan.ctes)) |model| break :blk model;
                if (publicSqlReadRequestRowClaimMissingNativeModel(lateral.plan.lateral.left, "lateral")) |model| break :blk model;
                break :blk publicSqlReadRequestRowClaimMissingNativeModel(lateral.plan.lateral.right, "lateral");
            },
            .window => |window| blk: {
                if (publicSqlReadCtesRowClaimMissingNativeModel(window.plan.ctes)) |model| break :blk model;
                break :blk publicSqlReadRequestRowClaimMissingNativeModel(window.plan.window.source, "window");
            },
            .set_operation => |set_operation| blk: {
                if (publicSqlQueryPlanRowClaimMissingNativeModel(set_operation.left.plan)) |model| break :blk model;
                if (publicSqlQueryPlanRowClaimMissingNativeModel(set_operation.right.plan)) |model| break :blk model;
                break :blk null;
            },
            .recursive_cte => |recursive_cte| blk: {
                if (publicSqlQueryPlanRowClaimMissingNativeModel(recursive_cte.anchor.plan)) |model| break :blk model;
                if (publicSqlReadRequestRowClaimMissingNativeModel(recursive_cte.final_query, "recursive CTE")) |model| break :blk model;
                break :blk null;
            },
            .document_query, .document_aggregate => null,
        };
    }

    fn publicSqlReadUnsupportedRowClaimDiagnostic(
        lowered: *const sql_adapter.LoweredReadPlan,
        phase: sql_adapter.diagnostics.SqlDiagnosticPhase,
    ) ?sql_adapter.diagnostics.SqlDiagnosticEnvelope {
        const missing_native_model = publicSqlReadPlanRowClaimMissingNativeModel(lowered) orelse return null;
        return sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(phase, .unsupported_sql_statement).withMissingNativeModel(missing_native_model);
    }

    fn publicSqlGeneratedReadRowClaimMissingNativeModel(
        parsed_sql: *const sql_adapter.ParsedSql,
    ) ?[]const u8 {
        const tokens = parsed_sql.items();
        const generated_statement = parsed_sql.generated_statement orelse return publicSqlTokenReadRowClaimMissingNativeModel(tokens);
        const generated_ast = generated_statement.ast orelse {
            if (generated_statement.kind() == .read) return null;
            return publicSqlTokenReadRowClaimMissingNativeModel(tokens);
        };
        const read = switch (generated_ast) {
            .read => |read| read,
            else => if (generated_statement.kind() == .read) return null else return publicSqlTokenReadRowClaimMissingNativeModel(tokens),
        };
        for (read.cte_items) |cte| {
            if (cte.body_row_lock_tokens != null) return "lockable base-row source for materialized CTE row claim";
        }
        if (read.row_lock_tokens == null) return null;
        const inferred_kind = publicSqlGeneratedReadKindForRowClaimDiagnostic(tokens, read);
        const parsed_kind = parsed_sql.readStatementKindIncludingGeneratedAst() orelse return null;
        const diagnostic_kind = if (parsed_kind == .query and inferred_kind != .query) inferred_kind else parsed_kind;
        return switch (diagnostic_kind) {
            .query => null,
            .aggregate => "lockable base-row source for aggregate row claim",
            .join => "lockable base-row source for join row claim",
            .lateral => "lockable base-row source for lateral row claim",
            .window => "lockable base-row source for window row claim",
            .set_operation => "lockable base-row source for set-operation row claim",
            .recursive_cte => "lockable base-row source for recursive CTE row claim",
        };
    }

    fn publicSqlTokenReadRowClaimMissingNativeModel(tokens: []const sql_adapter.Token) ?[]const u8 {
        if (!publicSqlTokensContainRowClaim(tokens)) return null;
        if (tokens.len > 0 and tokens[0].matchesKeywordTag(.with)) {
            return "lockable base-row source for materialized CTE row claim";
        }
        if (publicSqlTokensContainKeyword(tokens, .over) or publicSqlTokensContainKeyword(tokens, .window)) {
            return "lockable base-row source for window row claim";
        }
        if (publicSqlTokensContainKeyword(tokens, .lateral)) return "lockable base-row source for lateral row claim";
        if (publicSqlTokensContainKeyword(tokens, .join)) return "lockable base-row source for join row claim";
        if (publicSqlTokensContainKeyword(tokens, .group) or
            publicSqlTokensContainKeyword(tokens, .having) or
            publicSqlTokensContainAggregateFunction(tokens))
        {
            return "lockable base-row source for aggregate row claim";
        }
        return null;
    }

    fn publicSqlTokensContainKeyword(tokens: []const sql_adapter.Token, keyword: sql_adapter.TokenKeyword) bool {
        for (tokens) |token| {
            if (token.matchesKeywordTag(keyword)) return true;
        }
        return false;
    }

    fn publicSqlTokensContainAggregateFunction(tokens: []const sql_adapter.Token) bool {
        for (tokens) |token| {
            if (token.matchesKeywordTag(.count) or
                token.matchesKeywordTag(.sum) or
                token.matchesKeywordTag(.avg) or
                token.matchesKeywordTag(.min) or
                token.matchesKeywordTag(.max))
            {
                return true;
            }
        }
        return false;
    }

    fn publicSqlTokensContainRowClaim(tokens: []const sql_adapter.Token) bool {
        var index: usize = 0;
        while (index < tokens.len) : (index += 1) {
            if (!tokens[index].matchesKeywordTag(.@"for")) continue;
            var next = index + 1;
            while (next < tokens.len and tokens[next].kind == .semicolon) : (next += 1) {}
            if (next >= tokens.len) return false;
            if (tokens[next].matchesKeywordTag(.update) or tokens[next].matchesKeywordTag(.share)) return true;
            if (tokens[next].matchesKeywordTag(.no) and next + 2 < tokens.len and
                tokens[next + 1].matchesKeywordTag(.key) and tokens[next + 2].matchesKeywordTag(.update))
            {
                return true;
            }
            if (tokens[next].matchesKeywordTag(.key) and next + 1 < tokens.len and tokens[next + 1].matchesKeywordTag(.share)) return true;
        }
        return false;
    }

    fn publicSqlGeneratedReadKindForRowClaimDiagnostic(
        tokens: []const sql_adapter.Token,
        read: *const sql_adapter.generated_parser.GeneratedSqlReadAst,
    ) sql_adapter.SqlReadStatementKind {
        if (read.set_operation_tokens != null) return .set_operation;
        if (read.kind == .lateral) return .lateral;
        if (read.source_tokens) |source| {
            if (publicSqlGeneratedReadRangeContainsKeyword(tokens, source, .lateral)) return .lateral;
        }
        if (read.kind == .window or read.window_tokens != null) return .window;
        if (read.projection_tokens) |projection| {
            if (publicSqlGeneratedReadRangeContainsKeyword(tokens, projection, .over)) return .window;
        }
        if (read.kind == .aggregate or
            (read.distinct_tokens != null and read.distinct_on_items.count == 0) or
            read.group_tokens != null or
            read.having_tokens != null or
            (if (read.projection_tokens) |projection| publicSqlGeneratedReadRangeHasAggregateFunction(tokens, projection) else false))
        {
            return .aggregate;
        }
        if (read.kind == .join or read.join_tokens != null) return .join;
        if (read.source_tokens) |source| {
            if (publicSqlGeneratedReadRangeContainsKeyword(tokens, source, .join)) return .join;
        }
        return .query;
    }

    fn publicSqlGeneratedReadRangeContainsKeyword(
        tokens: []const sql_adapter.Token,
        range: sql_adapter.generated_parser.GeneratedSqlTokenRange,
        keyword: sql_adapter.TokenKeyword,
    ) bool {
        if (range.end > tokens.len or range.start > range.end) return false;
        var index = range.start;
        while (index < range.end) : (index += 1) {
            if (tokens[index].matchesKeywordTag(keyword)) return true;
        }
        return false;
    }

    fn publicSqlGeneratedReadRangeHasAggregateFunction(
        tokens: []const sql_adapter.Token,
        range: sql_adapter.generated_parser.GeneratedSqlTokenRange,
    ) bool {
        if (range.end > tokens.len or range.start > range.end) return false;
        var index = range.start;
        while (index < range.end) : (index += 1) {
            const token = tokens[index];
            if (token.matchesKeywordTag(.count) or
                token.matchesKeywordTag(.sum) or
                token.matchesKeywordTag(.avg) or
                token.matchesKeywordTag(.min) or
                token.matchesKeywordTag(.max))
            {
                return true;
            }
        }
        return false;
    }

    fn publicSqlReadStatementKindForCatalogRead(
        read_catalog: *const sql_adapter.CatalogLogicalReadPlan,
        parsed_sql: *const sql_adapter.ParsedSql,
    ) !?sql_adapter.SqlReadStatementKind {
        const parsed_kind = parsed_sql.readStatementKindIncludingGeneratedAst();
        const target_binding = read_catalog.target_binding orelse return null;
        if (parsed_sql.generatedStatementKind() == .read) {
            if (parsed_kind) |kind| return kind;
            return switch (target_binding) {
                .document => parsed_sql.generatedReadStatementKind() orelse parsed_sql.readStatementKind() orelse error.UnsupportedSqlShape,
                else => error.UnsupportedSqlShape,
            };
        }
        if (read_catalog.statement.readKind()) |kind| return kind;
        switch (target_binding) {
            .document => {},
            else => return null,
        }
        return parsed_kind;
    }

    fn publicSqlWriteStatementKindForCatalogWrite(
        write_catalog: *const sql_adapter.CatalogLogicalWritePlan,
        parsed_sql: *const sql_adapter.ParsedSql,
    ) !?sql_adapter.SqlWriteStatementKind {
        const parsed_kind = parsed_sql.writeStatementKindIncludingGeneratedAst();
        if (parsed_sql.generatedStatementKind() == .dml) return parsed_kind orelse error.UnsupportedSqlShape;
        return write_catalog.statement.writeKind() orelse parsed_kind;
    }

    fn publicSqlGeneratedReadRowClaimDiagnostic(
        parsed_sql: *const sql_adapter.ParsedSql,
        phase: sql_adapter.diagnostics.SqlDiagnosticPhase,
    ) ?sql_adapter.diagnostics.SqlDiagnosticEnvelope {
        const missing_native_model = publicSqlGeneratedReadRowClaimMissingNativeModel(parsed_sql) orelse return null;
        return sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(phase, .unsupported_sql_statement).withMissingNativeModel(missing_native_model);
    }

    fn publicSqlGeneratedExpressionUnsupportedSubqueryPredicateMissingNativeModel(
        expression: sql_adapter.generated_parser.GeneratedSqlExpressionAst,
    ) ?[]const u8 {
        switch (expression.kind) {
            .exists_subquery, .not_exists_subquery => return "semijoin execution for EXISTS subquery predicate",
            .quantified_comparison => if (expression.right_expression_kind == .subquery) return "quantified comparison execution for read-subquery predicate",
            else => {},
        }
        switch (expression.kind) {
            .logical_or, .logical_and => {
                for (expression.boolean_condition_items.expressions) |condition| {
                    if (publicSqlGeneratedExpressionUnsupportedSubqueryPredicateMissingNativeModel(condition)) |model| return model;
                }
            },
            .logical_not => if (expression.right_expression) |right| {
                if (publicSqlGeneratedExpressionUnsupportedSubqueryPredicateMissingNativeModel(right.*)) |model| return model;
            },
            .grouped => if (expression.inner_expression) |inner| {
                if (publicSqlGeneratedExpressionUnsupportedSubqueryPredicateMissingNativeModel(inner.*)) |model| return model;
            },
            else => {},
        }
        if (expression.left_expression) |left| {
            if (publicSqlGeneratedExpressionUnsupportedSubqueryPredicateMissingNativeModel(left.*)) |model| return model;
        }
        if (expression.right_expression) |right| {
            if (publicSqlGeneratedExpressionUnsupportedSubqueryPredicateMissingNativeModel(right.*)) |model| return model;
        }
        return null;
    }

    fn publicSqlGeneratedExpressionHasAntflyNativeSearchFunction(
        tokens: []const sql_adapter.Token,
        expression: sql_adapter.generated_parser.GeneratedSqlExpressionAst,
    ) bool {
        if (expression.kind == .function_call) {
            if (expression.function_name_tokens) |name_tokens| {
                if (publicSqlGeneratedFunctionNameRangeIsAntflyNativeSearch(tokens, name_tokens)) return true;
            }
        }
        switch (expression.kind) {
            .logical_or, .logical_and => {
                for (expression.boolean_condition_items.expressions) |condition| {
                    if (publicSqlGeneratedExpressionHasAntflyNativeSearchFunction(tokens, condition)) return true;
                }
            },
            .logical_not => if (expression.right_expression) |right| {
                if (publicSqlGeneratedExpressionHasAntflyNativeSearchFunction(tokens, right.*)) return true;
            },
            .grouped => if (expression.inner_expression) |inner| {
                if (publicSqlGeneratedExpressionHasAntflyNativeSearchFunction(tokens, inner.*)) return true;
            },
            else => {},
        }
        if (expression.left_expression) |left| {
            if (publicSqlGeneratedExpressionHasAntflyNativeSearchFunction(tokens, left.*)) return true;
        }
        if (expression.right_expression) |right| {
            if (publicSqlGeneratedExpressionHasAntflyNativeSearchFunction(tokens, right.*)) return true;
        }
        return false;
    }

    fn publicSqlTokenMatchesNativeAntflySearchMember(token: sql_adapter.Token) bool {
        return token.matchesKeywordTag(.full_text_search) or
            token.matchesKeywordTag(.semantic_search) or
            token.matchesKeywordTag(.vector_search) or
            token.matchesKeywordTag(.hybrid_search) or
            token.matchesKeywordTag(.graph_traverse) or
            token.matchesKeywordTag(.graph_neighbors) or
            token.matchesKeywordTag(.graph_shortest_path) or
            token.matchesKeywordTag(.graph_k_shortest_paths) or
            token.matchesKeywordTag(.graph_match) or
            token.matchesKeywordTag(.graph_metric) or
            token.matchesKeywordTag(.graph_metric_rerank);
    }

    fn publicSqlTokenMatchesQualifiedNativeAntflySearchFunction(token: sql_adapter.Token) bool {
        return token.matchesQualifiedKeywordTag("antfly", .full_text_search) or
            token.matchesQualifiedKeywordTag("antfly", .semantic_search) or
            token.matchesQualifiedKeywordTag("antfly", .vector_search) or
            token.matchesQualifiedKeywordTag("antfly", .hybrid_search) or
            token.matchesQualifiedKeywordTag("antfly", .graph_traverse) or
            token.matchesQualifiedKeywordTag("antfly", .graph_neighbors) or
            token.matchesQualifiedKeywordTag("antfly", .graph_shortest_path) or
            token.matchesQualifiedKeywordTag("antfly", .graph_k_shortest_paths) or
            token.matchesQualifiedKeywordTag("antfly", .graph_match) or
            token.matchesQualifiedKeywordTag("antfly", .graph_metric) or
            token.matchesQualifiedKeywordTag("antfly", .graph_metric_rerank);
    }

    fn publicSqlGeneratedFunctionNameRangeIsAntflyNativeSearch(
        tokens: []const sql_adapter.Token,
        range: sql_adapter.generated_parser.GeneratedSqlTokenRange,
    ) bool {
        if (range.end > tokens.len or range.start >= range.end) return false;
        if (range.end == range.start + 1) {
            return publicSqlTokenMatchesQualifiedNativeAntflySearchFunction(tokens[range.start]);
        }
        var saw_antfly = false;
        for (tokens[range.start..range.end]) |token| {
            if (!saw_antfly and std.ascii.eqlIgnoreCase(token.text, "antfly")) {
                saw_antfly = true;
                continue;
            }
            if (saw_antfly and publicSqlTokenMatchesNativeAntflySearchMember(token)) return true;
        }
        return false;
    }

    fn publicSqlTokensHaveAntflyNativeSearchFunction(tokens: []const sql_adapter.Token) bool {
        var saw_antfly = false;
        for (tokens) |token| {
            if (publicSqlTokenMatchesQualifiedNativeAntflySearchFunction(token)) return true;
            if (!saw_antfly and std.ascii.eqlIgnoreCase(token.text, "antfly")) {
                saw_antfly = true;
                continue;
            }
            if (saw_antfly and publicSqlTokenMatchesNativeAntflySearchMember(token)) return true;
        }
        return false;
    }

    fn publicSqlGeneratedReadHasAntflyNativeSearchPredicate(
        tokens: []const sql_adapter.Token,
        read: sql_adapter.generated_parser.GeneratedSqlReadAst,
    ) bool {
        if (read.where_tokens) |where_tokens| {
            if (publicSqlGeneratedRangeHasAntflyNativeSearchFunction(tokens, where_tokens) or
                publicSqlGeneratedExpressionHasAntflyNativeSearchFunction(tokens, read.where_expression)) return true;
        }
        if (read.having_tokens) |having_tokens| {
            if (publicSqlGeneratedRangeHasAntflyNativeSearchFunction(tokens, having_tokens) or
                publicSqlGeneratedExpressionHasAntflyNativeSearchFunction(tokens, read.having_expression)) return true;
        }
        if (read.set_operation.right_where_tokens) |where_tokens| {
            if (publicSqlGeneratedRangeHasAntflyNativeSearchFunction(tokens, where_tokens) or
                publicSqlGeneratedExpressionHasAntflyNativeSearchFunction(tokens, read.set_operation.right_where_expression)) return true;
        }
        for (read.join_items) |join| {
            if (join.predicate_tokens) |predicate_tokens| {
                if (publicSqlGeneratedRangeHasAntflyNativeSearchFunction(tokens, predicate_tokens) or
                    publicSqlGeneratedExpressionHasAntflyNativeSearchFunction(tokens, join.predicate_expression)) return true;
            }
        }
        return false;
    }

    fn publicSqlGeneratedRangeHasAntflyNativeSearchFunction(
        tokens: []const sql_adapter.Token,
        range: sql_adapter.generated_parser.GeneratedSqlTokenRange,
    ) bool {
        if (range.end > tokens.len or range.start > range.end) return false;
        var saw_antfly = false;
        for (tokens[range.start..range.end]) |token| {
            if (publicSqlTokenMatchesQualifiedNativeAntflySearchFunction(token)) return true;
            if (!saw_antfly and std.ascii.eqlIgnoreCase(token.text, "antfly")) {
                saw_antfly = true;
                continue;
            }
            if (saw_antfly and publicSqlTokenMatchesNativeAntflySearchMember(token)) return true;
        }
        return false;
    }

    fn publicSqlGeneratedReadSourceTableNameAlloc(
        alloc: std.mem.Allocator,
        tokens: []const sql_adapter.Token,
        read: sql_adapter.generated_parser.GeneratedSqlReadAst,
    ) !?[]const u8 {
        const table_tokens = read.source_table_tokens orelse return null;
        if (table_tokens.end > tokens.len or table_tokens.start >= table_tokens.end or table_tokens.end != table_tokens.start + 1) return null;
        const table_token = tokens[table_tokens.start];
        if (table_token.kind != .identifier) return null;
        return try sql_adapter.normalizeSqlObjectIdentifierAlloc(alloc, table_token.text);
    }

    fn publicSqlGeneratedDocumentNativeSearchPredicateDiagnostic(
        parsed_sql: *const sql_adapter.ParsedSql,
        schema: runtime_schema_mod.TableSchema,
        phase: sql_adapter.diagnostics.SqlDiagnosticPhase,
    ) ?sql_adapter.diagnostics.SqlDiagnosticEnvelope {
        if (schema.storage_mode != .document) return null;
        const generated_statement = parsed_sql.generated_statement orelse return null;
        const generated_ast = generated_statement.ast orelse return null;
        switch (generated_ast) {
            .read => |read| {
                if (!publicSqlGeneratedReadHasAntflyNativeSearchPredicate(parsed_sql.items(), read.*) and
                    !publicSqlTokensHaveAntflyNativeSearchFunction(parsed_sql.items())) return null;
            },
            else => return null,
        }
        return sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(phase, .invalid_sql_request)
            .withMessage("document_sql_native_search_requires_table_function")
            .withMissingNativeModel("document SQL read shape");
    }

    fn publicSqlGeneratedDocumentNativeSearchPredicateDiagnosticFromCatalog(
        self: *ApiHttpServer,
        parsed_sql: *const sql_adapter.ParsedSql,
        session: catalog_resources.SqlCatalogSession,
        phase: sql_adapter.diagnostics.SqlDiagnosticPhase,
    ) !?sql_adapter.diagnostics.SqlDiagnosticEnvelope {
        const generated_statement = parsed_sql.generated_statement orelse return null;
        const generated_ast = generated_statement.ast orelse return null;
        const read = switch (generated_ast) {
            .read => |read| blk: {
                if (!publicSqlGeneratedReadHasAntflyNativeSearchPredicate(parsed_sql.items(), read.*) and
                    !publicSqlTokensHaveAntflyNativeSearchFunction(parsed_sql.items())) return null;
                break :blk read.*;
            },
            else => return null,
        };

        var table_name: []const u8 = undefined;
        var table_name_owned = false;
        if (sql_adapter.readSourceTableNamesFromParsedSqlAlloc(self.alloc, parsed_sql)) |maybe_tables| {
            var tables = maybe_tables orelse return null;
            defer tables.deinit(self.alloc);
            table_name = try self.alloc.dupe(u8, tables.left);
            table_name_owned = true;
        } else |err| switch (err) {
            error.UnsupportedSqlShape => {
                table_name = (try publicSqlGeneratedReadSourceTableNameAlloc(self.alloc, parsed_sql.items(), read)) orelse return null;
                table_name_owned = true;
            },
            else => return err,
        }
        defer if (table_name_owned) self.alloc.free(table_name);

        const schema = sql_adapter.runtimeSchemaForCatalogTableWithSessionAlloc(self.alloc, self.catalogSource().sqlSource(), table_name, session) catch |err| switch (err) {
            error.InvalidSqlCatalog, error.TableNotFound => return null,
            else => return err,
        };
        defer runtime_schema_mod.freeSchema(self.alloc, schema);
        if (schema.storage_mode != .document) return null;
        return sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(phase, .invalid_sql_request)
            .withMessage("document_sql_native_search_requires_table_function")
            .withMissingNativeModel("document SQL read shape");
    }

    fn publicSqlDocumentUnsupportedReadDiagnosticFromCatalog(
        self: *ApiHttpServer,
        parsed_sql: *const sql_adapter.ParsedSql,
        session: catalog_resources.SqlCatalogSession,
        phase: sql_adapter.diagnostics.SqlDiagnosticPhase,
    ) !?sql_adapter.diagnostics.SqlDiagnosticEnvelope {
        var saw_window = false;
        for (parsed_sql.items()) |token| {
            if (token.matchesKeywordTag(.window)) {
                saw_window = true;
                break;
            }
        }
        if (!saw_window) return null;

        var table_name: []const u8 = undefined;
        var table_name_owned = false;
        if (sql_adapter.readSourceTableNamesFromParsedSqlAlloc(self.alloc, parsed_sql)) |maybe_tables| {
            var tables = maybe_tables orelse return null;
            defer tables.deinit(self.alloc);
            table_name = try self.alloc.dupe(u8, tables.left);
            table_name_owned = true;
        } else |err| switch (err) {
            error.UnsupportedSqlShape => {
                const generated_statement = parsed_sql.generated_statement orelse return null;
                const generated_ast = generated_statement.ast orelse return null;
                const read = switch (generated_ast) {
                    .read => |read| read.*,
                    else => return null,
                };
                table_name = (try publicSqlGeneratedReadSourceTableNameAlloc(self.alloc, parsed_sql.items(), read)) orelse return null;
                table_name_owned = true;
            },
            else => return err,
        }
        defer if (table_name_owned) self.alloc.free(table_name);

        const schema = sql_adapter.runtimeSchemaForCatalogTableWithSessionAlloc(self.alloc, self.catalogSource().sqlSource(), table_name, session) catch |err| switch (err) {
            error.InvalidSqlCatalog, error.TableNotFound => return null,
            else => return err,
        };
        defer runtime_schema_mod.freeSchema(self.alloc, schema);
        if (schema.storage_mode != .document) return null;
        return sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(phase, .invalid_sql_request)
            .withMessage("document_sql_window_unsupported")
            .withMissingNativeModel("document SQL read shape");
    }

    fn publicSqlGeneratedReadUnsupportedSubqueryPredicateMissingNativeModel(
        read: sql_adapter.generated_parser.GeneratedSqlReadAst,
    ) ?[]const u8 {
        if (read.where_tokens != null) {
            if (publicSqlGeneratedExpressionUnsupportedSubqueryPredicateMissingNativeModel(read.where_expression)) |model| return model;
        }
        if (read.having_tokens != null) {
            if (publicSqlGeneratedExpressionUnsupportedSubqueryPredicateMissingNativeModel(read.having_expression)) |model| return model;
        }
        if (read.set_operation.right_where_tokens != null) {
            if (publicSqlGeneratedExpressionUnsupportedSubqueryPredicateMissingNativeModel(read.set_operation.right_where_expression)) |model| return model;
        }
        for (read.join_items) |join| {
            if (join.predicate_tokens != null) {
                if (publicSqlGeneratedExpressionUnsupportedSubqueryPredicateMissingNativeModel(join.predicate_expression)) |model| return model;
            }
        }
        return null;
    }

    fn publicSqlUnsupportedGeneratedSubqueryPredicateDiagnostic(
        parsed_sql: *const sql_adapter.ParsedSql,
        phase: sql_adapter.diagnostics.SqlDiagnosticPhase,
    ) ?sql_adapter.diagnostics.SqlDiagnosticEnvelope {
        const generated_statement = parsed_sql.generated_statement orelse return null;
        const generated_ast = generated_statement.ast orelse return null;
        const missing_native_model = switch (generated_ast) {
            .read => |read| publicSqlGeneratedReadUnsupportedSubqueryPredicateMissingNativeModel(read.*),
            else => null,
        } orelse return null;
        return sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(phase, .unsupported_sql_statement).withMissingNativeModel(missing_native_model);
    }

    fn applyLoweredPublicSqlMutationSource(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        native_target_table: []const u8,
        target_schema: runtime_schema_mod.TableSchema,
        lowered: *sql_adapter.LoweredMutationSource,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !union(enum) {
        failure: http_common.HttpResponse,
        result: db_mod.types.RelationalRowsMutationSourceResult,
    } {
        const source = self.table_writes orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        self.ensureNoPublicSqlMutationSourceTrigger(target.table_name, lowered.mutation.req.kind) catch |err| switch (err) {
            error.RoutineNotFound => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.UnsupportedOperation => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            else => return err,
        };

        var filter = self.rowsAuthFilterPlanForTarget(target, authenticated_identity, target_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (filter) |*value| value.deinit(self.alloc);
        if (filter) |active| {
            try self.applyRowsAuthFilterToQuery(target_schema, active, &lowered.mutation.req.source);
        }

        const result = (source.mutateRowsFromSourceAutocommit(
            self.alloc,
            native_target_table,
            target_schema,
            lowered.mutation.req,
            lowered.sync_level,
        ) catch |err| switch (err) {
            error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.UnsupportedOperation => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            error.VersionConflict, error.IntentConflict, error.DecisionConflict, error.TxnNotFound, error.InvalidTxnRecord => return .{ .failure = try textResponse(self.alloc, 409, "version conflict") },
            error.TopologyChanged => return .{ .failure = try textResponse(self.alloc, 503, "topology changed") },
            error.LeaderUnavailable, error.WriteUnavailable => return .{ .failure = try textResponse(self.alloc, 503, "write unavailable") },
            error.TableNotFound, error.UnknownGroup => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.DocIdentityNamespaceMismatch => return .{ .failure = try textResponse(self.alloc, 503, "doc identity unavailable") },
            error.EnrichmentRetryInProgress => return .{ .failure = try textResponse(self.alloc, 429, "table backpressured") },
            else => {
                std.log.err("public sql mutation source failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        }) orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        return .{ .result = result };
    }

    fn applyLoweredPublicSqlTableEmptying(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        native_target_table: []const u8,
        target_schema: runtime_schema_mod.TableSchema,
        lowered: *sql_adapter.LoweredMutationSource,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
        parsed_sql: *const sql_adapter.ParsedSql,
    ) !union(enum) {
        failure: http_common.HttpResponse,
        result: db_mod.types.RelationalRowsMutationSourceResult,
        accepted: tables_api.AppliedRelationalSqlDdlRecord,
    } {
        const audit_target = target;
        const needs_catalog_barrier = publicSqlTableEmptyingRequiresCatalogBarrier(lowered.*);
        const audit_route: PublicSqlNativeRoute = if (needs_catalog_barrier) .table_emptying_barrier else .mutation_source;

        self.ensureNoPublicSqlMutationSourceTrigger(target.table_name, lowered.mutation.req.kind) catch |err| switch (err) {
            error.RoutineNotFound => {
                self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") };
            },
            error.UnsupportedOperation => {
                self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") };
            },
            else => return err,
        };

        var filter = self.rowsAuthFilterPlanForTarget(target, authenticated_identity, target_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => {
                self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .denied, @errorName(err));
                return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") };
            },
            else => return err,
        };
        defer if (filter) |*value| value.deinit(self.alloc);
        if (needs_catalog_barrier and filter != null) {
            self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .denied, "RowFilterPushdownRequired");
            return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") };
        }
        if (filter) |active| {
            try self.applyRowsAuthFilterToQuery(target_schema, active, &lowered.mutation.req.source);
        }

        if (needs_catalog_barrier) {
            const admission = self.schedulePublicSqlTableEmptyingJobsWithSession(target.table_name, lowered.*, session) catch |err| switch (err) {
                error.UnsupportedOperation => {
                    self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                    return .{ .failure = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, publicSqlUnsupportedTruncateSourceDiagnostic(lowered.*)) };
                },
                error.InvalidArgument, error.InvalidQueryRequest => {
                    self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                    return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") };
                },
                error.TableNotFound => {
                    self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                    return .{ .failure = try textResponse(self.alloc, 404, "not found") };
                },
                else => {
                    self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                    std.log.err("public sql table emptying admission failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                    return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
                },
            };
            self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, admission.scheduled_jobs, authenticated_identity, .applied, null);
            return .{ .accepted = admission.applied };
        }

        const source = self.table_writes orelse {
            self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, "TableWriteSourceUnavailable");
            return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        };
        const result = (source.tableEmptying(self.alloc, .{
            .primary_table_name = native_target_table,
            .additional_table_names = lowered.additional_table_names,
            .schema = target_schema,
            .mutation = lowered.mutation.req,
            .sync_level = lowered.sync_level,
            .restart_identity = lowered.restart_identity,
            .cascade = lowered.truncate_cascade,
        }) catch |err| switch (err) {
            error.UnsupportedOperation, error.UnsupportedQueryRequest => {
                self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                return .{ .failure = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, publicSqlUnsupportedTruncateSourceDiagnostic(lowered.*)) };
            },
            error.InvalidArgument, error.InvalidQueryRequest => {
                self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") };
            },
            error.VersionConflict, error.IntentConflict, error.DecisionConflict, error.TxnNotFound, error.InvalidTxnRecord => {
                self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                return .{ .failure = try textResponse(self.alloc, 409, "version conflict") };
            },
            error.TopologyChanged => {
                self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                return .{ .failure = try textResponse(self.alloc, 503, "topology changed") };
            },
            error.LeaderUnavailable, error.WriteUnavailable => {
                self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                return .{ .failure = try textResponse(self.alloc, 503, "write unavailable") };
            },
            error.TableNotFound, error.UnknownGroup => {
                self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                return .{ .failure = try textResponse(self.alloc, 404, "not found") };
            },
            error.DocIdentityNamespaceMismatch => {
                self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                return .{ .failure = try textResponse(self.alloc, 503, "doc identity unavailable") };
            },
            error.EnrichmentRetryInProgress => {
                self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                return .{ .failure = try textResponse(self.alloc, 429, "table backpressured") };
            },
            else => {
                self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                std.log.err("public sql table emptying failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        }) orelse {
            self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, 0, authenticated_identity, .failed, "TableNotFound");
            return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        };
        self.recordPublicSqlAuditOutcome(.truncate, audit_route, audit_target, @intCast(result.matched), authenticated_identity, .applied, null);
        return .{ .result = result };
    }

    fn joinedMutationTargetQuery(req: *db_mod.types.RelationalRowsJoinedMutationSourceRequest) *db_mod.types.RelationalRowsQueryRequest {
        return switch (req.target_side) {
            .left => &req.join.left,
            .right => &req.join.right,
        };
    }

    fn joinedMutationSourceQuery(req: *db_mod.types.RelationalRowsJoinedMutationSourceRequest) *db_mod.types.RelationalRowsQueryRequest {
        return switch (req.target_side) {
            .left => &req.join.right,
            .right => &req.join.left,
        };
    }

    fn applyLoweredPublicSqlJoinedMutationSource(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        native_target_table: []const u8,
        target_schema: runtime_schema_mod.TableSchema,
        lowered: *sql_adapter.LoweredJoinedMutationSource,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !union(enum) {
        failure: http_common.HttpResponse,
        result: db_mod.types.RelationalRowsMutationSourceResult,
    } {
        const read_source = self.effectivePublicTableReads() orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        const write_source = self.table_writes orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        self.ensureNoPublicSqlMutationSourceTrigger(target.table_name, lowered.mutation.req.kind) catch |err| switch (err) {
            error.RoutineNotFound => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.UnsupportedOperation => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            else => return err,
        };

        var source_target = try self.publicSqlSideTableTargetForWriteAlloc(target, lowered.source_table_name, session);
        defer source_target.deinit(self.alloc);
        const source = source_target.target();
        const native_source_table = try catalog_resources.storageTableNameForTargetAlloc(self.alloc, source);
        defer self.alloc.free(native_source_table);

        self.enforceAuthenticatedIdentitySqlTablePermission(authenticated_identity, source, .read) catch |err| switch (err) {
            error.PermissionDenied => return .{ .failure = try textResponse(self.alloc, 403, "forbidden") },
            else => return err,
        };

        const same_source_target = publicSqlTableTargetsEqual(source, target);
        const source_schema = if (same_source_target)
            target_schema
        else
            self.runtimeSchemaForCatalogRows(source) catch |err| switch (err) {
                error.InvalidRowsRequest, error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
                else => return err,
            };
        defer if (!same_source_target) runtime_schema_mod.freeSchema(self.alloc, source_schema);

        var target_filter = self.rowsAuthFilterPlanForTarget(target, authenticated_identity, target_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (target_filter) |*value| value.deinit(self.alloc);
        if (target_filter) |active| {
            try self.applyRowsAuthFilterToQuery(target_schema, active, joinedMutationTargetQuery(&lowered.mutation.req));
        }

        var source_filter = self.rowsAuthFilterPlanForTarget(source, authenticated_identity, source_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (source_filter) |*value| value.deinit(self.alloc);
        if (source_filter) |active| {
            for (@constCast(lowered.mutation.req.ctes)) |*cte| try self.applyRowsAuthFilterToQuery(source_schema, active, &cte.query);
            try self.applyRowsAuthFilterToQuery(source_schema, active, joinedMutationSourceQuery(&lowered.mutation.req));
        }

        var source_result = (self.publicSqlRowsQueryPlanForTargetAlloc(
            read_source,
            source,
            native_source_table,
            source_schema,
            .{ .ctes = lowered.mutation.req.ctes, .query = joinedMutationSourceQuery(&lowered.mutation.req).* },
        ) catch |err| switch (err) {
            error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.RelationalRowsCteMaterializationRejected => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.RelationalRowsCteSpillRequired => return .{ .failure = try textResponse(self.alloc, 429, "sql write backpressured") },
            error.UnsupportedOperation, error.UnsupportedRowsQuery => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.TopologyChanged => return .{ .failure = try textResponse(self.alloc, 503, "topology changed") },
            error.LeaderUnavailable, error.ReadUnavailable => return .{ .failure = try textResponse(self.alloc, 503, "read unavailable") },
            else => {
                std.log.err("public sql joined mutation source read failed table={s}.{s}.{s} source={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, source.database_name, source.namespace_name, source.table_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        }) orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        defer source_result.deinit(self.alloc);

        const result = (write_source.mutateRowsJoinedFromSourceRowsAutocommit(
            self.alloc,
            native_target_table,
            target_schema,
            source_schema,
            lowered.mutation.req,
            source_result.rows,
            lowered.sync_level,
        ) catch |err| switch (err) {
            error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.UnsupportedOperation => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            error.VersionConflict, error.IntentConflict, error.DecisionConflict, error.TxnNotFound, error.InvalidTxnRecord => return .{ .failure = try textResponse(self.alloc, 409, "version conflict") },
            error.TopologyChanged => return .{ .failure = try textResponse(self.alloc, 503, "topology changed") },
            error.LeaderUnavailable, error.WriteUnavailable => return .{ .failure = try textResponse(self.alloc, 503, "write unavailable") },
            error.TableNotFound, error.UnknownGroup => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.DocIdentityNamespaceMismatch => return .{ .failure = try textResponse(self.alloc, 503, "doc identity unavailable") },
            error.EnrichmentRetryInProgress => return .{ .failure = try textResponse(self.alloc, 429, "table backpressured") },
            else => {
                std.log.err("public sql joined mutation source failed table={s}.{s}.{s} source={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, source.database_name, source.namespace_name, source.table_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        }) orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        return .{ .result = result };
    }

    fn applyLoweredPublicSqlRecursiveJoinedMutationSource(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        native_target_table: []const u8,
        target_schema: runtime_schema_mod.TableSchema,
        lowered: sql_adapter.LoweredRecursiveJoinedMutationSource,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !union(enum) {
        failure: http_common.HttpResponse,
        result: db_mod.types.RelationalRowsMutationSourceResult,
    } {
        const read_source = self.effectivePublicTableReads() orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        const write_source = self.table_writes orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        self.ensureNoPublicSqlMutationSourceTrigger(target.table_name, lowered.mutation.mutation.req.kind) catch |err| switch (err) {
            error.RoutineNotFound => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.UnsupportedOperation => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            else => return err,
        };

        var target_filter = self.rowsAuthFilterPlanForTarget(target, authenticated_identity, target_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (target_filter) |*value| value.deinit(self.alloc);
        if (target_filter != null) return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") };

        var routed_lowered = lowered;
        routed_lowered.mutation.target_table_name = native_target_table;
        const result = (table_writes.mutateRowsJoinedFromRecursiveCtePlanAutocommitWithSessionAlloc(
            self.alloc,
            read_source,
            write_source,
            self.catalogSource(),
            session,
            target.table_name,
            target_schema,
            target_schema,
            routed_lowered,
            .read_index,
        ) catch |err| switch (err) {
            error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.RelationalRowsCteMaterializationRejected => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.RelationalRowsCteSpillRequired => return .{ .failure = try textResponse(self.alloc, 429, "sql write backpressured") },
            error.UnsupportedOperation, error.UnsupportedRowsQuery => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            error.VersionConflict, error.IntentConflict, error.DecisionConflict, error.TxnNotFound, error.InvalidTxnRecord => return .{ .failure = try textResponse(self.alloc, 409, "version conflict") },
            error.TopologyChanged => return .{ .failure = try textResponse(self.alloc, 503, "topology changed") },
            error.LeaderUnavailable, error.ReadUnavailable, error.WriteUnavailable => return .{ .failure = try textResponse(self.alloc, 503, "write unavailable") },
            error.TableNotFound, error.UnknownGroup => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.DocIdentityNamespaceMismatch => return .{ .failure = try textResponse(self.alloc, 503, "doc identity unavailable") },
            error.EnrichmentRetryInProgress => return .{ .failure = try textResponse(self.alloc, 429, "table backpressured") },
            else => {
                std.log.err("public sql recursive joined mutation source failed table={s}.{s}.{s} cte={s} err={}", .{ target.database_name, target.namespace_name, target.table_name, lowered.recursive.cte_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        }) orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        return .{ .result = result };
    }

    fn applyLoweredPublicSqlMergeMutation(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        native_target_table: []const u8,
        target_schema: runtime_schema_mod.TableSchema,
        lowered: *sql_adapter.LoweredMergeMutationPlan,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !union(enum) {
        failure: http_common.HttpResponse,
        batch: relational_rows_api.OwnedRowsBatchRequest,
    } {
        const read_source = self.effectivePublicTableReads() orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        if (lowered.data_modifying_ctes.len != 0) {
            return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") };
        }

        var source_target = try self.publicSqlSideTableTargetForWriteAlloc(target, lowered.source_table_name, session);
        defer source_target.deinit(self.alloc);
        const source = source_target.target();
        const native_source_table = try catalog_resources.storageTableNameForTargetAlloc(self.alloc, source);
        defer self.alloc.free(native_source_table);

        self.enforceAuthenticatedIdentitySqlTablePermission(authenticated_identity, source, .read) catch |err| switch (err) {
            error.PermissionDenied => return .{ .failure = try textResponse(self.alloc, 403, "forbidden") },
            else => return err,
        };

        const same_source_target = publicSqlTableTargetsEqual(source, target);
        const source_schema = if (same_source_target)
            target_schema
        else
            self.runtimeSchemaForCatalogRows(source) catch |err| switch (err) {
                error.InvalidRowsRequest, error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
                else => return err,
            };
        defer if (!same_source_target) runtime_schema_mod.freeSchema(self.alloc, source_schema);

        var target_query: relational_rows_api.OwnedRowsQueryRequest = .{ .select_all = true };
        defer self.deinitRowsAuthFilterQueryAdditions(&target_query);
        var target_filter = self.rowsAuthFilterPlanForTarget(target, authenticated_identity, target_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (target_filter) |*value| value.deinit(self.alloc);
        if (target_filter) |active| {
            try self.applyRowsAuthFilterToQuery(target_schema, active, &target_query);
        }

        var source_filter = self.rowsAuthFilterPlanForTarget(source, authenticated_identity, source_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (source_filter) |*value| value.deinit(self.alloc);
        if (source_filter) |active| {
            for (@constCast(lowered.ctes)) |*cte| {
                try self.applyRowsAuthFilterToQuery(source_schema, active, &cte.query);
            }
            if (lowered.source.source_cte.len == 0) {
                try self.applyRowsAuthFilterToQuery(source_schema, active, &lowered.source);
            }
        }

        var sequence_resolver_ctx = RowsSequenceDefaultResolverContext{ .source = self.source };
        var scalar_default_resolver_ctx = RowsScalarSubqueryDefaultResolverContext{ .source = self.source, .table_reads = read_source };
        var batch = (table_reads.rowsMergeMutationBatchFromRoutedScansWithSchemasAndDefaultContextAlloc(
            self.alloc,
            read_source,
            native_target_table,
            native_source_table,
            target_schema,
            source_schema,
            lowered.*,
            target_query,
            &.{},
            lowered.source,
            &.{},
            .read_index,
            .{
                .sequence_resolver = sequence_resolver_ctx.resolver(),
                .scalar_subquery_resolver = scalar_default_resolver_ctx.resolver(),
            },
        ) catch |err| switch (err) {
            error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation, error.SequenceNotFound => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.RelationalRowsCteMaterializationRejected => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.RelationalRowsCteSpillRequired => return .{ .failure = try textResponse(self.alloc, 429, "sql write backpressured") },
            error.UnsupportedOperation, error.UnsupportedRowsQuery, error.UnsupportedSqlShape => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.TopologyChanged => return .{ .failure = try textResponse(self.alloc, 503, "topology changed") },
            error.LeaderUnavailable, error.ReadUnavailable => return .{ .failure = try textResponse(self.alloc, 503, "read unavailable") },
            else => {
                std.log.err("public sql merge plan failed table={s}.{s}.{s} source={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, source.database_name, source.namespace_name, source.table_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        }) orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        errdefer batch.deinit(self.alloc);

        if (try self.applyLoweredPublicSqlRowsBatchForTarget(target, native_target_table, target_schema, &batch, authenticated_identity)) |failure| return .{ .failure = failure };
        return .{ .batch = batch };
    }

    fn applyLoweredPublicSqlRecursiveMergeMutation(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        native_target_table: []const u8,
        target_schema: runtime_schema_mod.TableSchema,
        lowered: sql_adapter.LoweredRecursiveMergeMutation,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !union(enum) {
        failure: http_common.HttpResponse,
        batch: relational_rows_api.OwnedRowsBatchRequest,
    } {
        const read_source = self.effectivePublicTableReads() orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };

        var target_filter = self.rowsAuthFilterPlanForTarget(target, authenticated_identity, target_schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") },
            else => return err,
        };
        defer if (target_filter) |*value| value.deinit(self.alloc);
        if (target_filter != null) return .{ .failure = try textResponse(self.alloc, 403, "row filter pushdown required") };

        var sequence_resolver_ctx = RowsSequenceDefaultResolverContext{ .source = self.source };
        var scalar_default_resolver_ctx = RowsScalarSubqueryDefaultResolverContext{ .source = self.source, .table_reads = read_source };
        var routed_lowered = lowered;
        routed_lowered.merge.target_table_name = native_target_table;
        var batch = (table_reads.rowsRecursiveMergeMutationBatchFromRoutedScansWithSchemasAndSessionAndDefaultContextAlloc(
            self.alloc,
            read_source,
            self.catalogSource().sqlSource(),
            session,
            target.table_name,
            target.table_name,
            target_schema,
            target_schema,
            routed_lowered,
            .{ .select_all = true },
            &.{},
            .read_index,
            .{
                .sequence_resolver = sequence_resolver_ctx.resolver(),
                .scalar_subquery_resolver = scalar_default_resolver_ctx.resolver(),
            },
        ) catch |err| switch (err) {
            error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation, error.SequenceNotFound, error.RelationalRowsCteMaterializationRejected => return .{ .failure = try textResponse(self.alloc, 400, "invalid sql write") },
            error.RelationalRowsCteSpillRequired => return .{ .failure = try textResponse(self.alloc, 429, "sql write backpressured") },
            error.UnsupportedOperation, error.UnsupportedRowsQuery, error.UnsupportedSqlShape => return .{ .failure = try textResponse(self.alloc, 501, "unsupported sql statement") },
            error.TableNotFound => return .{ .failure = try textResponse(self.alloc, 404, "not found") },
            error.TopologyChanged => return .{ .failure = try textResponse(self.alloc, 503, "topology changed") },
            error.LeaderUnavailable, error.ReadUnavailable => return .{ .failure = try textResponse(self.alloc, 503, "read unavailable") },
            else => {
                std.log.err("public sql recursive merge plan failed table={s}.{s}.{s} cte={s} err={}", .{ target.database_name, target.namespace_name, target.table_name, lowered.recursive.cte_name, err });
                return .{ .failure = try textResponse(self.alloc, 500, "sql write failed") };
            },
        }) orelse return .{ .failure = try textResponse(self.alloc, 404, "not found") };
        errdefer batch.deinit(self.alloc);

        if (try self.applyLoweredPublicSqlRowsBatchForTarget(target, native_target_table, target_schema, &batch, authenticated_identity)) |failure| return .{ .failure = failure };
        return .{ .batch = batch };
    }

    fn handlePublicSqlWrite(
        self: *ApiHttpServer,
        logical_plan: *sql_adapter.LogicalSqlPlan,
        parsed_sql: *const sql_adapter.ParsedSql,
        params: []const sql_adapter.SqlValue,
        session: *sql_adapter.OwnedSqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !PublicSqlResultOrResponse {
        const statement_start_ns = platform_time.monotonicNs();
        const statement_timeout_ns = try sql_adapter.sqlStatementTimeoutNsFromSession(session.session());
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
        if (try self.publicSqlReadOnlyActive(session)) {
            return .{ .response = try self.publicSqlDiagnosticResponse(400, sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(.execute, .read_only_transaction).withMessage("cannot execute write statement in a read-only transaction")) };
        }

        const write_catalog = switch (logical_plan.*) {
            .catalog_write => |*catalog_write| catalog_write,
            else => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) },
        };
        const statement_kind = (publicSqlWriteStatementKindForCatalogWrite(write_catalog, parsed_sql) catch return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) }) orelse return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) };
        switch (statement_kind) {
            .insert, .insert_source, .update, .update_source, .update_joined_source, .delete, .delete_source, .delete_joined_source, .truncate, .merge => {},
        }
        const target_binding = write_catalog.target_binding orelse return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.bind, .table_not_found)) };
        const target = target_binding.target();
        const audit_target = catalog_resources.TableTarget{
            .database_name = target.database_name,
            .namespace_name = target.namespace_name,
            .table_name = target.table_name,
        };
        const native_target_table = try catalog_resources.storageTableNameForTargetAlloc(self.alloc, audit_target);
        defer self.alloc.free(native_target_table);
        const target_table = try self.alloc.dupe(u8, target.table_name);
        defer self.alloc.free(target_table);
        const schema = try clonePublicSqlRuntimeSchemaAlloc(self.alloc, target_binding.schema());
        defer runtime_schema_mod.freeSchema(self.alloc, schema);
        var unique_resolver_ctx = RowsUniqueSelectorResolverContext{ .source = self.table_reads };
        var sequence_resolver_ctx = RowsSequenceDefaultResolverContext{ .source = self.source };
        const default_read_source = self.effectivePublicTableReads() orelse return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.bind, .table_not_found)) };
        var scalar_default_resolver_ctx = RowsScalarSubqueryDefaultResolverContext{ .source = self.source, .table_reads = default_read_source };
        write_catalog.options.unique_resolver = unique_resolver_ctx.resolver();
        write_catalog.options.default_context.sequence_resolver = sequence_resolver_ctx.resolver();
        write_catalog.options.default_context.scalar_subquery_resolver = scalar_default_resolver_ctx.resolver();

        const routine_bindings = try self.sql_routine_runtime.listExpressionRoutineBindingsAlloc(self.alloc);
        defer sql_routines.freeExpressionRoutineBindings(self.alloc, routine_bindings);
        const function_bindings: sql_adapter.SqlFunctionBindings = .{
            .routine_expressions = routine_bindings,
        };

        var lowered = sql_adapter.lowerWritePlanWithLogicalPlanAndFunctionBindingsAlloc(
            self.alloc,
            parsed_sql,
            logical_plan,
            schema,
            params,
            function_bindings,
        ) catch |err| switch (err) {
            error.InvalidSqlCatalog, error.TableNotFound => {
                std.log.err("public sql write lower not found table={s} err={}", .{ target_table, err });
                return .{ .response = try self.publicSqlDiagnosticResponse(404, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) };
            },
            error.DocumentSqlWriteUnsupported => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.plan, .document_sql_write_unsupported)) },
            error.DocumentSqlWriteJoinMissingCardinalityProof,
            error.DocumentSqlWriteJoinMissingExactProducer,
            error.DocumentSqlWriteJoinMissingIndexProof,
            error.DocumentSqlWriteJoinOrderedIndexProof,
            error.DocumentSqlWriteJoinPartialIndexProof,
            error.DocumentSqlWriteJoinStaleIndexProof,
            error.DocumentSqlMergeRequiresNativeProducer,
            error.DocumentSqlWriteSourceAssignmentAlias,
            error.DocumentSqlWriteSourceAssignmentAmbiguousReference,
            error.DocumentSqlWriteSourceAssignmentGeneratedField,
            error.DocumentSqlWriteSourceAssignmentMissingField,
            error.DocumentSqlWriteSourceAssignmentReservedField,
            error.DocumentSqlWriteSourceAssignmentTargetGeneratedField,
            error.DocumentSqlWriteSourceAssignmentTargetReservedField,
            error.DocumentSqlWriteSourceAssignmentTypeMismatch,
            => return .{ .response = try self.publicSqlDiagnosticResponse(400, sql_adapter.diagnostics.knownErrorDiagnostic(.plan, err).?) },
            error.MissingSqlParameter => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.UnsupportedRowsSelector, error.RowSelectorNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
            error.UnsupportedSqlShape, error.UnsupportedRowsQuery, error.UnsupportedOperation => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) },
            error.UniqueOwnerTopologyUnavailable, error.TopologyChanged, error.DocIdentityNamespaceMismatch => return .{ .response = try self.publicSqlDiagnosticResponse(503, .init(.plan, .unique_owner_unavailable)) },
            else => return err,
        };
        var lowered_owned = true;
        defer if (lowered_owned) lowered.deinit(self.alloc);
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

        if (lowered == .insert_source) {
            const returning_columns = self.publicSqlInsertSourceRequestReturningColumnsAlloc(schema, lowered.insert_source.insert_source.req) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
                else => return err,
            };
            var returning_columns_owned = true;
            defer if (returning_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, returning_columns);
            const insert_source_result = switch (try self.applyLoweredPublicSqlInsertSource(audit_target, native_target_table, schema, &lowered.insert_source, session.session(), authenticated_identity)) {
                .failure => |failure| return .{ .response = failure },
                .result => |result| result,
            };
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            returning_columns_owned = false;
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .mutation_source = .{
                    .result = insert_source_result,
                    .columns = returning_columns,
                } },
            } };
        }

        if (lowered == .update_source or lowered == .delete_source) {
            const mutation_source = switch (lowered) {
                .update_source => |*update_source| update_source,
                .delete_source => |*delete_source| delete_source,
                else => unreachable,
            };
            const returning_columns = self.publicSqlMutationRequestReturningColumnsAlloc(schema, mutation_source.mutation.req) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
                else => return err,
            };
            var returning_columns_owned = true;
            defer if (returning_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, returning_columns);
            const mutation_source_result = switch (try self.applyLoweredPublicSqlMutationSource(audit_target, native_target_table, schema, mutation_source, authenticated_identity)) {
                .failure => |failure| return .{ .response = failure },
                .result => |result| result,
            };
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            returning_columns_owned = false;
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .mutation_source = .{
                    .result = mutation_source_result,
                    .columns = returning_columns,
                } },
            } };
        }

        if (lowered == .truncate_source) {
            var accepted_applied: ?tables_api.AppliedRelationalSqlDdlRecord = null;
            const truncate_result = switch (try self.applyLoweredPublicSqlTableEmptying(audit_target, native_target_table, schema, &lowered.truncate_source, session.session(), authenticated_identity, parsed_sql)) {
                .failure => |failure| return .{ .response = failure },
                .result => |result| result,
                .accepted => |applied| blk: {
                    accepted_applied = applied;
                    break :blk null;
                },
            };
            errdefer if (accepted_applied) |*applied| applied.deinit(self.alloc);
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            if (accepted_applied) |applied| {
                return .{ .result = .{
                    .session_id = self.ensureSqlProtocolSessionId(session),
                    .statement_kind = @tagName(statement_kind),
                    .result = .{ .ddl = .{
                        .applied = applied,
                        .command_tag = publicSqlDdlCommandTag(parsed_sql),
                    } },
                } };
            }

            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .mutation_source = .{ .result = truncate_result.? } },
            } };
        }

        if (lowered == .update_joined_source or lowered == .delete_joined_source) {
            const joined_mutation_source = switch (lowered) {
                .update_joined_source => |*update_joined_source| update_joined_source,
                .delete_joined_source => |*delete_joined_source| delete_joined_source,
                else => unreachable,
            };
            const owned_source_schema = self.publicSqlSourceSchemaForWriteAlloc(target_table, joined_mutation_source.source_table_name, session.session()) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) },
                else => return err,
            };
            defer if (owned_source_schema) |source_schema| runtime_schema_mod.freeSchema(self.alloc, source_schema);
            const joined_source_schema = owned_source_schema orelse schema;
            const returning_columns = self.publicSqlJoinedMutationRequestReturningColumnsAlloc(schema, joined_source_schema, joined_mutation_source.mutation.req) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
                else => return err,
            };
            var returning_columns_owned = true;
            defer if (returning_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, returning_columns);
            const joined_mutation_result = switch (try self.applyLoweredPublicSqlJoinedMutationSource(audit_target, native_target_table, schema, joined_mutation_source, session.session(), authenticated_identity)) {
                .failure => |failure| return .{ .response = failure },
                .result => |result| result,
            };
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            returning_columns_owned = false;
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .mutation_source = .{
                    .result = joined_mutation_result,
                    .columns = returning_columns,
                } },
            } };
        }

        if (lowered == .recursive_update_joined_source or lowered == .recursive_delete_joined_source) {
            const recursive_joined_mutation_source = switch (lowered) {
                .recursive_update_joined_source => |recursive_update_joined_source| recursive_update_joined_source,
                .recursive_delete_joined_source => |recursive_delete_joined_source| recursive_delete_joined_source,
                else => unreachable,
            };
            var recursive_source_schema = schema;
            recursive_source_schema.relational_columns = recursive_joined_mutation_source.recursive.output_columns;
            const returning_columns = self.publicSqlJoinedMutationRequestReturningColumnsAlloc(schema, recursive_source_schema, recursive_joined_mutation_source.mutation.mutation.req) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
                else => return err,
            };
            var returning_columns_owned = true;
            defer if (returning_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, returning_columns);
            const recursive_joined_mutation_result = switch (try self.applyLoweredPublicSqlRecursiveJoinedMutationSource(audit_target, native_target_table, schema, recursive_joined_mutation_source, session.session(), authenticated_identity)) {
                .failure => |failure| return .{ .response = failure },
                .result => |result| result,
            };
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            returning_columns_owned = false;
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .mutation_source = .{
                    .result = recursive_joined_mutation_result,
                    .columns = returning_columns,
                } },
            } };
        }

        if (lowered == .merge_mutation) {
            const owned_source_schema = self.publicSqlSourceSchemaForWriteAlloc(target_table, lowered.merge_mutation.source_table_name, session.session()) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) },
                else => return err,
            };
            defer if (owned_source_schema) |source_schema| runtime_schema_mod.freeSchema(self.alloc, source_schema);
            const merge_source_schema = owned_source_schema orelse schema;
            const returning_columns = self.publicSqlReturningColumnsAlloc(schema, merge_source_schema, lowered.merge_mutation.returning) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
                else => return err,
            };
            var returning_columns_owned = true;
            defer if (returning_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, returning_columns);
            const merge_batch = switch (try self.applyLoweredPublicSqlMergeMutation(audit_target, native_target_table, schema, &lowered.merge_mutation, session.session(), authenticated_identity)) {
                .failure => |failure| return .{ .response = failure },
                .batch => |batch| batch,
            };
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            returning_columns_owned = false;
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .rows_batch = .{
                    .result = merge_batch,
                    .columns = returning_columns,
                } },
            } };
        }

        if (lowered == .recursive_merge_mutation) {
            var recursive_source_schema = schema;
            recursive_source_schema.relational_columns = lowered.recursive_merge_mutation.recursive.output_columns;
            const returning_columns = self.publicSqlReturningColumnsAlloc(schema, recursive_source_schema, lowered.recursive_merge_mutation.merge.returning) catch |err| switch (err) {
                error.InvalidSqlCatalog, error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
                else => return err,
            };
            var returning_columns_owned = true;
            defer if (returning_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, returning_columns);
            const merge_batch = switch (try self.applyLoweredPublicSqlRecursiveMergeMutation(audit_target, native_target_table, schema, lowered.recursive_merge_mutation, session.session(), authenticated_identity)) {
                .failure => |failure| return .{ .response = failure },
                .batch => |batch| batch,
            };
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            returning_columns_owned = false;
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .rows_batch = .{
                    .result = merge_batch,
                    .columns = returning_columns,
                } },
            } };
        }

        if (lowered == .document_write or lowered == .document_conflict_write or lowered == .document_source_insert or lowered == .document_producer_mutation or lowered == .document_joined_mutation or lowered == .document_merge_mutation) {
            var document_batch = switch (lowered) {
                .document_write => |*document_write| blk: {
                    const batch = document_write.batch;
                    document_write.batch = .{};
                    break :blk batch;
                },
                .document_conflict_write, .document_source_insert, .document_producer_mutation, .document_joined_mutation, .document_merge_mutation => blk: {
                    const read_source = self.effectivePublicTableReads() orelse return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.bind, .table_not_found)) };
                    const native_table_name = try catalog_resources.storageTableNameForTargetAlloc(self.alloc, .{
                        .database_name = target.database_name,
                        .namespace_name = target.namespace_name,
                        .table_name = target.table_name,
                    });
                    defer self.alloc.free(native_table_name);
                    var adapter = table_read_document_sql.RuntimeSourceAdapter{
                        .source = read_source,
                        .target = .{
                            .database_name = target.database_name,
                            .namespace_name = target.namespace_name,
                            .table_name = target.table_name,
                        },
                        .native_table_name = native_table_name,
                        .public_table_name = target.table_name,
                    };
                    break :blk switch (lowered) {
                        .document_conflict_write => |document_write| sql_adapter.document_runtime.materializeDocumentConflictWriteBatchAlloc(
                            self.alloc,
                            adapter.runtimeSource(),
                            document_write,
                            .read_index,
                        ),
                        .document_source_insert => |document_write| sql_adapter.document_runtime.materializeDocumentSourceInsertBatchAlloc(
                            self.alloc,
                            adapter.runtimeSource(),
                            document_write,
                            .read_index,
                        ),
                        .document_producer_mutation => |document_mutation| sql_adapter.document_runtime.materializeProducerMutationBatchAlloc(
                            self.alloc,
                            adapter.runtimeSource(),
                            document_mutation,
                            .read_index,
                        ),
                        .document_joined_mutation => |document_mutation| sql_adapter.document_runtime.materializeJoinedMutationBatchAlloc(
                            self.alloc,
                            adapter.runtimeSource(),
                            document_mutation,
                            .read_index,
                        ),
                        .document_merge_mutation => |document_mutation| sql_adapter.document_runtime.materializeDocumentMergeMutationBatchAlloc(
                            self.alloc,
                            adapter.runtimeSource(),
                            document_mutation,
                            .read_index,
                        ),
                        else => unreachable,
                    } catch |err| {
                        if (lowered == .document_merge_mutation) {
                            self.recordPublicSqlAuditOutcome(.merge, .rows_batch, audit_target, 0, authenticated_identity, .failed, @errorName(err));
                        }
                        switch (err) {
                            error.DocumentSqlWriteDuplicateSource,
                            error.DocumentSqlBoundedScanRowCapExceeded,
                            error.DocumentSqlBoundedScanByteCapExceeded,
                            error.DocumentSqlIndexUnavailable,
                            => return .{ .response = try self.publicSqlDiagnosticResponse(400, (sql_adapter.diagnostics.knownErrorDiagnostic(.execute, err) orelse .init(.execute, .invalid_sql_request))) },
                            error.DocumentSqlWriteUnsupported => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.execute, .document_sql_write_unsupported)) },
                            error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.execute, .invalid_sql_request)) },
                            error.UnsupportedSqlShape, error.UnsupportedRowsQuery, error.UnsupportedOperation => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.execute, .unsupported_sql_statement)) },
                            error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.execute, .table_not_found)) },
                            error.TopologyChanged => return .{ .response = try self.publicSqlDiagnosticResponse(503, .init(.execute, .topology_changed)) },
                            error.LeaderUnavailable, error.ReadUnavailable => return .{ .response = try self.publicSqlDiagnosticResponse(503, .init(.execute, .read_unavailable)) },
                            else => return err,
                        }
                    };
                },
                else => unreachable,
            };
            defer document_batch.deinit(self.alloc);

            var rows_batch = takePublicSqlRowsBatchFromDocumentBatch(&document_batch);
            var rows_batch_owned = true;
            defer if (rows_batch_owned) rows_batch.deinit(self.alloc);
            if (lowered == .document_merge_mutation) {
                if (try self.applyLoweredPublicSqlDocumentMergeRowsBatchWithAudit(audit_target, schema, &rows_batch, authenticated_identity)) |failure| return .{ .response = failure };
            } else if (try self.applyLoweredPublicSqlRowsBatchForTarget(audit_target, native_target_table, schema, &rows_batch, authenticated_identity)) |failure| return .{ .response = failure };
            self.finalizePublicSqlDocumentReturningVersions(audit_target, &rows_batch) catch |err| switch (err) {
                error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.execute, .invalid_sql_request)) },
                error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.execute, .table_not_found)) },
                error.TopologyChanged => return .{ .response = try self.publicSqlDiagnosticResponse(503, .init(.execute, .topology_changed)) },
                error.LeaderUnavailable, error.ReadUnavailable => return .{ .response = try self.publicSqlDiagnosticResponse(503, .init(.execute, .read_unavailable)) },
                else => return err,
            };
            try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

            const owned_rows_batch = rows_batch;
            rows_batch_owned = false;
            return .{ .result = .{
                .session_id = self.ensureSqlProtocolSessionId(session),
                .statement_kind = @tagName(statement_kind),
                .result = .{ .rows_batch = .{
                    .result = owned_rows_batch,
                } },
            } };
        }

        const returning_projection = switch (lowered) {
            .insert => |*insert| insert.returning,
            .update => |*update| update.returning,
            .delete => |*delete| delete.returning,
            else => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) },
        };
        const returning_columns = self.publicSqlReturningColumnsAlloc(schema, null, returning_projection) catch |err| switch (err) {
            error.InvalidSqlCatalog, error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_write)) },
            else => return err,
        };
        var returning_columns_owned = true;
        defer if (returning_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, returning_columns);
        const rows_batch = switch (lowered) {
            .insert => |*insert| &insert.batch,
            .update => |*update| &update.batch,
            .delete => |*delete| &delete.batch,
            else => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) },
        };
        if (try self.applyLoweredPublicSqlRowsBatchForTarget(audit_target, native_target_table, schema, rows_batch, authenticated_identity)) |failure| return .{ .response = failure };
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

        const owned_rows_batch = rows_batch.*;
        switch (lowered) {
            .insert => |*insert| {
                self.alloc.free(insert.table_name);
                insert.returning.deinit(self.alloc);
                insert.returning = .{};
            },
            .update => |*update| {
                self.alloc.free(update.table_name);
                update.returning.deinit(self.alloc);
                update.returning = .{};
            },
            .delete => |*delete| {
                self.alloc.free(delete.table_name);
                delete.returning.deinit(self.alloc);
                delete.returning = .{};
            },
            else => unreachable,
        }
        lowered_owned = false;
        returning_columns_owned = false;
        return .{ .result = .{
            .session_id = self.ensureSqlProtocolSessionId(session),
            .statement_kind = @tagName(statement_kind),
            .result = .{ .rows_batch = .{
                .result = owned_rows_batch,
                .columns = returning_columns,
            } },
        } };
    }

    fn handlePublicSqlRead(
        self: *ApiHttpServer,
        logical_plan: *sql_adapter.LogicalSqlPlan,
        parsed_sql: *const sql_adapter.ParsedSql,
        params: []const sql_adapter.SqlValue,
        session: *sql_adapter.OwnedSqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !PublicSqlResultOrResponse {
        const statement_start_ns = platform_time.monotonicNs();
        const statement_timeout_ns = try sql_adapter.sqlStatementTimeoutNsFromSession(session.session());
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

        const read_catalog = switch (logical_plan.*) {
            .catalog_read => |*catalog_read| catalog_read,
            else => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) },
        };
        const target_binding = read_catalog.target_binding orelse return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.bind, .unsupported_sql_statement)) };
        const statement_kind = (publicSqlReadStatementKindForCatalogRead(read_catalog, parsed_sql) catch return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) }) orelse {
            if (publicSqlGeneratedDocumentNativeSearchPredicateDiagnostic(parsed_sql, target_binding.schema(), .plan)) |diagnostic| {
                return .{ .response = try self.publicSqlDiagnosticResponse(400, diagnostic) };
            }
            if (publicSqlGeneratedReadRowClaimDiagnostic(parsed_sql, .plan)) |diagnostic| {
                return .{ .response = try self.publicSqlDiagnosticResponse(501, diagnostic) };
            }
            if (publicSqlUnsupportedGeneratedSubqueryPredicateDiagnostic(parsed_sql, .plan)) |diagnostic| {
                return .{ .response = try self.publicSqlDiagnosticResponse(501, diagnostic) };
            }
            return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) };
        };
        if (try self.handlePublicSqlQueryFunctionRead(parsed_sql, session, authenticated_identity, statement_kind)) |response| return response;
        const read_source = self.effectivePublicTableReads() orelse return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.bind, .table_not_found)) };

        const target = target_binding.target();
        const target_table_name = try self.alloc.dupe(u8, target.table_name);
        defer self.alloc.free(target_table_name);
        const source_table_name: []const u8 = if (read_catalog.source_binding) |binding|
            try self.alloc.dupe(u8, binding.target().table_name)
        else
            try self.alloc.dupe(u8, target.table_name);
        defer self.alloc.free(source_table_name);
        const schema = try clonePublicSqlRuntimeSchemaAlloc(self.alloc, target_binding.schema());
        defer runtime_schema_mod.freeSchema(self.alloc, schema);

        const routine_bindings = try self.sql_routine_runtime.listExpressionRoutineBindingsAlloc(self.alloc);
        defer sql_routines.freeExpressionRoutineBindings(self.alloc, routine_bindings);
        const function_bindings: sql_adapter.SqlFunctionBindings = .{
            .routine_expressions = routine_bindings,
        };

        var lowered = sql_adapter.lowerReadPlanWithLogicalPlanAndFunctionBindingsAlloc(
            self.alloc,
            parsed_sql,
            logical_plan,
            schema,
            params,
            function_bindings,
        ) catch |err| {
            if (documentSqlReadErrorMessage(err)) |message| return .{ .response = try self.publicSqlDiagnosticResponse(400, sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(.plan, .invalid_sql_request).withMessage(message).withMissingNativeModel("document SQL read shape")) };
            switch (err) {
                error.InvalidSqlCatalog, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) },
                error.MissingSqlParameter => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
                error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
                error.UnsupportedSqlShape, error.UnsupportedRowsQuery, error.UnsupportedOperation => {
                    if (publicSqlGeneratedDocumentNativeSearchPredicateDiagnostic(parsed_sql, schema, .plan)) |diagnostic| {
                        return .{ .response = try self.publicSqlDiagnosticResponse(400, diagnostic) };
                    }
                    if (publicSqlGeneratedReadRowClaimDiagnostic(parsed_sql, .plan)) |diagnostic| {
                        return .{ .response = try self.publicSqlDiagnosticResponse(501, diagnostic) };
                    }
                    if (publicSqlUnsupportedGeneratedSubqueryPredicateDiagnostic(parsed_sql, .plan)) |diagnostic| {
                        return .{ .response = try self.publicSqlDiagnosticResponse(501, diagnostic) };
                    }
                    return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) };
                },
                else => return err,
            }
        };
        defer lowered.deinit(self.alloc);
        if (publicSqlReadUnsupportedRowClaimDiagnostic(&lowered, .plan)) |diagnostic| {
            return .{ .response = try self.publicSqlDiagnosticResponse(501, diagnostic) };
        }
        self.applyPublicSqlDocumentReadRowFilter(&lowered, session.session(), authenticated_identity) catch |err| switch (err) {
            error.InvalidQueryRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

        const result_columns = self.publicSqlReadResultColumnsAlloc(
            target_table_name,
            schema,
            source_table_name,
            lowered,
            session.session(),
        ) catch |err| switch (err) {
            error.InvalidRowsRequest, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        var result_columns_owned = true;
        defer if (result_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, result_columns);

        const result = (table_reads.executeLoweredSqlReadPlanWithSessionAlloc(
            self.alloc,
            read_source,
            self.catalogSource().sqlSource(),
            session.session(),
            target_table_name,
            schema,
            lowered,
            .read_index,
        ) catch |err| {
            if (documentSqlReadErrorMessage(err)) |message| return .{ .response = try self.publicSqlDiagnosticResponse(400, sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(.execute, .invalid_sql_request).withMessage(message).withMissingNativeModel("document SQL read execution")) };
            switch (err) {
                error.InvalidSqlCatalog, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) },
                error.UnsupportedQueryRequest => {
                    if (publicSqlReadUnsupportedRowClaimDiagnostic(&lowered, .execute)) |diagnostic| {
                        return .{ .response = try self.publicSqlDiagnosticResponse(501, diagnostic) };
                    }
                    return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.execute, .invalid_sql_request)) };
                },
                error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.RelationalRowsCteMaterializationRejected => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.execute, .invalid_sql_request)) },
                error.RelationalRowsCteSpillRequired => return .{ .response = try self.publicSqlDiagnosticResponse(429, .init(.execute, .sql_read_backpressured)) },
                error.SystemVersionedHistoryPruned => return .{ .response = try self.publicSqlDiagnosticResponse(410, .init(.execute, .system_versioned_history_pruned)) },
                error.UnsupportedSqlShape, error.UnsupportedRowsQuery, error.UnsupportedOperation => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.execute, .unsupported_sql_statement)) },
                error.TopologyChanged => return .{ .response = try self.publicSqlDiagnosticResponse(503, .init(.execute, .topology_changed)) },
                error.LeaderUnavailable, error.ReadUnavailable => return .{ .response = try self.publicSqlDiagnosticResponse(503, .init(.execute, .read_unavailable)) },
                else => return err,
            }
        }) orelse return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.execute, .table_not_found)) };
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

        result_columns_owned = false;
        return .{ .result = .{
            .session_id = self.ensureSqlProtocolSessionId(session),
            .statement_kind = @tagName(statement_kind),
            .result = .{ .read = .{
                .result = result,
                .columns = result_columns,
            } },
        } };
    }

    fn executePublicSqlCursorLogicalPlanWithSession(
        self: *ApiHttpServer,
        cursor_plan: *sql_adapter.CursorPortalPlan,
        parsed_sql: *const sql_adapter.ParsedSql,
        session: *sql_adapter.OwnedSqlCatalogSession,
        params: []const sql_adapter.SqlValue,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !PublicSqlResultOrResponse {
        const statement_start_ns = platform_time.monotonicNs();
        const statement_timeout_ns = try sql_adapter.sqlStatementTimeoutNsFromSession(session.session());
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
        const session_id = self.ensureSqlProtocolSessionId(session);

        switch (cursor_plan.*) {
            .declare => |*declare_plan| {
                if (declare_plan.binary) {
                    return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) };
                }
                if (try self.publicSqlReadOnlyActive(session)) {
                    if (declare_plan.statement_kind != .read) {
                        return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .read_only_transaction)) };
                    }
                }
                if (declare_plan.statement_kind != .read) {
                    return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) };
                }
                const subject = &(declare_plan.subject_parsed_sql orelse {
                    return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) };
                });

                if (try self.handlePublicSqlPostgresCompatibilityRead(subject, session, params)) |read_outcome_value| {
                    var read_outcome = read_outcome_value;
                    errdefer read_outcome.deinit(self.alloc);
                    if (try self.declarePublicSqlReadCursorFromOutcome(session_id, declare_plan.*, parsed_sql, &read_outcome)) |outcome| return outcome;
                } else {
                    var planned_or_response = self.planPublicParsedSqlExecutionAlloc(subject, session, authenticated_identity) catch |err| switch (err) {
                        error.SqlReadOnlyTransaction => return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .read_only_transaction)) },
                        error.PermissionDenied => return .{ .response = try self.publicSqlParsedDiagnosticResponse(403, parsed_sql, .init(.bind, .permission_denied)) },
                        error.InvalidSqlCatalog, error.TableNotFound => return .{ .response = try self.publicSqlParsedDiagnosticResponse(404, parsed_sql, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) },
                        error.UnsupportedSqlShape => return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) },
                        else => return err,
                    };
                    var planned_owned = true;
                    defer if (planned_owned) planned_or_response.deinit(self.alloc);
                    switch (planned_or_response) {
                        .response => |*response| {
                            const out = response.*;
                            planned_owned = false;
                            return .{ .response = out };
                        },
                        .planned => |*planned| {
                            var read_outcome = switch (planned.plan) {
                                .logical => |*logical_plan| switch (logical_plan.*) {
                                    .catalog_read => try self.handlePublicSqlRead(logical_plan, subject, params, session, authenticated_identity),
                                    else => return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) },
                                },
                                .durable => return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) },
                            };
                            errdefer read_outcome.deinit(self.alloc);
                            if (try self.declarePublicSqlReadCursorFromOutcome(session_id, declare_plan.*, parsed_sql, &read_outcome)) |outcome| return outcome;
                        },
                    }
                }

                var applied = try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(self.alloc);
                errdefer applied.deinit(self.alloc);
                applied.noop = true;
                try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
                return .{ .result = .{
                    .session_id = session_id,
                    .statement_kind = "cursor",
                    .transaction_status = self.publicSqlTransactionStatus(session),
                    .result = .{ .ddl = .{
                        .applied = applied,
                        .command_tag = "DECLARE CURSOR",
                    } },
                } };
            },
            .fetch => |fetch_plan| {
                var cursor_read = self.sql_cursor_runtime.fetch(session_id, fetch_plan) catch |err| switch (err) {
                    error.CursorPortalNotFound, error.InvalidSqlSession => return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .invalid_sql_request)) },
                    else => return err,
                };
                errdefer cursor_read.deinit(self.alloc);
                try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
                const cursor_rows = cursor_read.rows;
                cursor_read.rows = &.{};
                const cursor_columns = cursor_read.columns;
                cursor_read.columns = &.{};
                return .{ .result = .{
                    .session_id = session_id,
                    .statement_kind = "cursor",
                    .transaction_status = self.publicSqlTransactionStatus(session),
                    .result = .{ .read = .{
                        .result = .{ .query = .{ .rows = cursor_rows, .total = cursor_read.total } },
                        .columns = cursor_columns,
                    } },
                } };
            },
            .move => |move_plan| {
                _ = self.sql_cursor_runtime.move(session_id, move_plan) catch |err| switch (err) {
                    error.CursorPortalNotFound, error.InvalidSqlSession => return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .invalid_sql_request)) },
                    else => return err,
                };
                var applied = try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(self.alloc);
                errdefer applied.deinit(self.alloc);
                applied.noop = true;
                try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
                return .{ .result = .{
                    .session_id = session_id,
                    .statement_kind = "cursor",
                    .transaction_status = self.publicSqlTransactionStatus(session),
                    .result = .{ .ddl = .{
                        .applied = applied,
                        .command_tag = "MOVE",
                    } },
                } };
            },
            .close => |close_plan| {
                self.sql_cursor_runtime.close(session_id, close_plan) catch |err| switch (err) {
                    error.CursorPortalNotFound, error.InvalidSqlSession => return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .invalid_sql_request)) },
                    else => return err,
                };
                var applied = try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(self.alloc);
                errdefer applied.deinit(self.alloc);
                applied.noop = true;
                try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);
                return .{ .result = .{
                    .session_id = session_id,
                    .statement_kind = "cursor",
                    .transaction_status = self.publicSqlTransactionStatus(session),
                    .result = .{ .ddl = .{
                        .applied = applied,
                        .command_tag = "CLOSE CURSOR",
                    } },
                } };
            },
        }
    }

    fn executePublicSqlPreparedStatementLogicalPlanWithSession(
        self: *ApiHttpServer,
        prepared_plan: *sql_adapter.PreparedStatementPlan,
        parsed_sql: *const sql_adapter.ParsedSql,
        session: *sql_adapter.OwnedSqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !PublicSqlResultOrResponse {
        switch (prepared_plan.*) {
            .execute => |execute_plan| {
                const session_id = session.notification_session_id;
                if (session_id == 0) {
                    return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .prepared_statement_not_found)) };
                }
                const executable = self.sql_prepared_statement_runtime.executableForExecute(session_id, execute_plan) catch |err| switch (err) {
                    error.PreparedStatementNotFound,
                    error.PreparedStatementArgumentMismatch,
                    => return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, (sql_adapter.diagnostics.knownErrorDiagnostic(.execute, err) orelse .init(.execute, .invalid_sql_request))) },
                };
                if (try self.publicSqlReadOnlyActive(session)) {
                    if (executable.statement_kind != .read) {
                        return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .read_only_transaction)) };
                    }
                }
                const subject = executable.parsed_sql;
                if (try self.handlePublicSqlPostgresCompatibilityRead(subject, session, execute_plan.arguments)) |outcome_value| {
                    var outcome = outcome_value;
                    errdefer outcome.deinit(self.alloc);
                    switch (outcome) {
                        .result => |*result| result.transaction_status = self.publicSqlTransactionStatus(session),
                        .response => {},
                    }
                    return outcome;
                }

                var planned_or_response = self.planPublicParsedSqlExecutionAlloc(subject, session, authenticated_identity) catch |err| switch (err) {
                    error.DocumentSqlViewMappingUnsupported => return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, subject, .init(.plan, .document_sql_view_mapping_unsupported)) },
                    error.SqlReadOnlyTransaction => return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .read_only_transaction)) },
                    error.UnsupportedSqlShape => return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, subject, .init(.plan, .unsupported_sql_statement)) },
                    error.StatementTimeout => return .{ .response = try self.publicSqlParsedDiagnosticResponse(408, parsed_sql, .init(.execute, .statement_timeout)) },
                    error.PermissionDenied => return .{ .response = try self.publicSqlParsedDiagnosticResponse(403, subject, .init(.bind, .permission_denied)) },
                    error.InvalidSqlSession,
                    error.PreparedStatementAlreadyExists,
                    error.PreparedStatementNotFound,
                    error.PreparedStatementArgumentMismatch,
                    error.InvalidSqlCatalog,
                    error.SavepointNotFound,
                    error.InvalidRoleSetting,
                    error.RoleSettingNotFound,
                    => return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, subject, (sql_adapter.diagnostics.knownErrorDiagnostic(.execute, err) orelse .init(.execute, .invalid_sql_request))) },
                    else => return err,
                };
                var planned_owned = true;
                defer if (planned_owned) planned_or_response.deinit(self.alloc);

                switch (planned_or_response) {
                    .response => |*response| {
                        const out = response.*;
                        planned_owned = false;
                        return .{ .response = out };
                    },
                    .planned => |*planned| {
                        return switch (planned.plan) {
                            .logical => |*logical_plan| switch (logical_plan.*) {
                                .catalog_write => try self.handlePublicSqlWrite(logical_plan, subject, execute_plan.arguments, session, authenticated_identity),
                                .catalog_read => try self.handlePublicSqlRead(logical_plan, subject, execute_plan.arguments, session, authenticated_identity),
                                .read, .write => .{ .response = try self.publicSqlParsedDiagnosticResponse(501, subject, .init(.plan, .unsupported_sql_statement)) },
                                else => ddl_blk: {
                                    const statement_kind = publicSqlStatementKindForLogicalPlan(logical_plan.*);
                                    var applied = ApiHttpServer.applyLogicalSqlPlanWithSession(self, logical_plan, session, .{ .parsed_sql = subject }) catch |err| switch (err) {
                                        error.SqlReadOnlyTransaction => return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .read_only_transaction)) },
                                        error.UnsupportedSqlShape => return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, subject, .init(.plan, .unsupported_sql_statement)) },
                                        error.StatementTimeout => return .{ .response = try self.publicSqlParsedDiagnosticResponse(408, parsed_sql, .init(.execute, .statement_timeout)) },
                                        error.InvalidSqlSession,
                                        error.PreparedStatementAlreadyExists,
                                        error.PreparedStatementNotFound,
                                        error.PreparedStatementArgumentMismatch,
                                        error.InvalidSqlCatalog,
                                        error.SavepointNotFound,
                                        error.InvalidRoleSetting,
                                        error.RoleSettingNotFound,
                                        => return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, subject, (sql_adapter.diagnostics.knownErrorDiagnostic(.execute, err) orelse .init(.execute, .invalid_sql_request))) },
                                        else => return err,
                                    };
                                    errdefer applied.deinit(self.alloc);
                                    break :ddl_blk .{ .result = .{
                                        .session_id = self.ensureSqlProtocolSessionId(session),
                                        .statement_kind = statement_kind,
                                        .transaction_status = self.publicSqlTransactionStatus(session),
                                        .result = .{ .ddl = .{
                                            .applied = applied,
                                            .command_tag = publicSqlDdlCommandTag(subject),
                                        } },
                                    } };
                                },
                            },
                            .durable => |*durable_plan| try self.executePublicSqlDurablePlannedExecutionOrDiagnostic(
                                durable_plan,
                                subject,
                                parsed_sql,
                                session,
                                authenticated_identity,
                                null,
                            ),
                        };
                    },
                }
            },
            .prepare, .deallocate => {
                const statement_kind = publicSqlStatementKindForLogicalPlan(.{ .prepared_statement = prepared_plan.* });
                var applied = ApiHttpServer.applyPreparedStatementLogicalPlanWithSession(self, prepared_plan.*, session, .{ .parsed_sql = parsed_sql }) catch |err| switch (err) {
                    error.SqlReadOnlyTransaction => return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .read_only_transaction)) },
                    error.PreparedStatementAlreadyExists,
                    error.PreparedStatementNotFound,
                    error.PreparedStatementArgumentMismatch,
                    error.InvalidSqlSession,
                    => return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, (sql_adapter.diagnostics.knownErrorDiagnostic(.execute, err) orelse .init(.execute, .invalid_sql_request))) },
                    else => return err,
                };
                errdefer applied.deinit(self.alloc);
                return .{ .result = .{
                    .session_id = self.ensureSqlProtocolSessionId(session),
                    .statement_kind = statement_kind,
                    .transaction_status = self.publicSqlTransactionStatus(session),
                    .result = .{ .ddl = .{
                        .applied = applied,
                        .command_tag = publicSqlDdlCommandTag(parsed_sql),
                    } },
                } };
            },
        }
    }

    fn declarePublicSqlReadCursorFromOutcome(
        self: *ApiHttpServer,
        session_id: u64,
        declare_plan: sql_adapter.DeclareCursorPortalPlan,
        parsed_sql: *const sql_adapter.ParsedSql,
        read_outcome: *PublicSqlResultOrResponse,
    ) !?PublicSqlResultOrResponse {
        switch (read_outcome.*) {
            .response => |*response| {
                const out = response.*;
                read_outcome.* = undefined;
                return .{ .response = out };
            },
            .result => |*result| switch (result.result) {
                .read => |*read| {
                    const taken = table_reads.takeLoweredSqlReadRows(&read.result);
                    var rows = taken.rows;
                    self.sql_cursor_runtime.declareReadPortal(session_id, declare_plan, &rows, &read.columns) catch |err| switch (err) {
                        error.CursorPortalAlreadyExists, error.InvalidSqlSession => {
                            for (rows) |row| self.alloc.free(@constCast(row));
                            if (rows.len > 0) self.alloc.free(rows);
                            read_outcome.deinit(self.alloc);
                            return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .invalid_sql_request)) };
                        },
                        else => {
                            for (rows) |row| self.alloc.free(@constCast(row));
                            if (rows.len > 0) self.alloc.free(rows);
                            return err;
                        },
                    };
                    read_outcome.deinit(self.alloc);
                    return null;
                },
                else => {
                    read_outcome.deinit(self.alloc);
                    return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) };
                },
            },
        }
    }

    fn clonePublicSqlRuntimeSchemaAlloc(alloc: std.mem.Allocator, schema: runtime_schema_mod.TableSchema) !runtime_schema_mod.TableSchema {
        const serialized = try runtime_schema_mod.serializeSchema(alloc, schema);
        defer alloc.free(serialized);
        return try runtime_schema_mod.deserializeSchema(alloc, serialized);
    }

    fn describePublicSqlReadColumnsAlloc(
        self: *ApiHttpServer,
        parsed_sql: *const sql_adapter.ParsedSql,
        params: []const sql_adapter.SqlValue,
        session: *sql_adapter.OwnedSqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !PublicSqlDescribeResultOrResponse {
        const statement_start_ns = platform_time.monotonicNs();
        const statement_timeout_ns = try sql_adapter.sqlStatementTimeoutNsFromSession(session.session());
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

        _ = self.effectivePublicTableReads() orelse return .{ .response = try self.publicSqlDiagnosticResponse(404, .init(.bind, .table_not_found)) };

        var authorization_options = try self.sqlBoundAuthorizationOptionsForIdentityAlloc(authenticated_identity);
        defer authorization_options.deinit(self.alloc);
        var logical_plan = sql_adapter.planParsedSqlWithSessionAlloc(self.alloc, parsed_sql, .{
            .catalog = self.catalogSource().sqlSource(),
            .session = session.session(),
            .authorization = authorization_options.value,
        }) catch |err| switch (err) {
            error.InvalidSqlCatalog, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) },
            error.PermissionDenied => return .{ .response = try self.publicSqlDiagnosticResponse(403, .init(.bind, .permission_denied)) },
            error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.bind, .unsupported_sql_statement)) },
            else => return err,
        };
        defer logical_plan.deinit(self.alloc);
        self.enforcePublicSqlLogicalPlanAuthorization(&logical_plan, session.session(), authenticated_identity) catch
            return .{ .response = try self.publicSqlDiagnosticResponse(403, .init(.bind, .permission_denied)) };
        const read_catalog = switch (logical_plan) {
            .catalog_read => |*catalog_read| catalog_read,
            else => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.bind, .unsupported_sql_statement)) },
        };
        const target_binding = read_catalog.target_binding orelse return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.bind, .unsupported_sql_statement)) };
        const statement_kind = (publicSqlReadStatementKindForCatalogRead(read_catalog, parsed_sql) catch return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) }) orelse {
            if (publicSqlGeneratedDocumentNativeSearchPredicateDiagnostic(parsed_sql, target_binding.schema(), .plan)) |diagnostic| {
                return .{ .response = try self.publicSqlDiagnosticResponse(400, diagnostic) };
            }
            if (publicSqlGeneratedReadRowClaimDiagnostic(parsed_sql, .plan)) |diagnostic| {
                return .{ .response = try self.publicSqlDiagnosticResponse(501, diagnostic) };
            }
            if (publicSqlUnsupportedGeneratedSubqueryPredicateDiagnostic(parsed_sql, .plan)) |diagnostic| {
                return .{ .response = try self.publicSqlDiagnosticResponse(501, diagnostic) };
            }
            return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) };
        };
        const target = target_binding.target();
        const target_table_name = try self.alloc.dupe(u8, target.table_name);
        defer self.alloc.free(target_table_name);
        const source_table_name: []const u8 = if (read_catalog.source_binding) |binding|
            try self.alloc.dupe(u8, binding.target().table_name)
        else
            try self.alloc.dupe(u8, target.table_name);
        defer self.alloc.free(source_table_name);
        const schema = try clonePublicSqlRuntimeSchemaAlloc(self.alloc, target_binding.schema());
        defer runtime_schema_mod.freeSchema(self.alloc, schema);

        const routine_bindings = try self.sql_routine_runtime.listExpressionRoutineBindingsAlloc(self.alloc);
        defer sql_routines.freeExpressionRoutineBindings(self.alloc, routine_bindings);
        const function_bindings: sql_adapter.SqlFunctionBindings = .{
            .routine_expressions = routine_bindings,
        };

        var lowered = sql_adapter.lowerReadPlanWithLogicalPlanAndFunctionBindingsAlloc(
            self.alloc,
            parsed_sql,
            &logical_plan,
            schema,
            params,
            function_bindings,
        ) catch |err| {
            if (documentSqlReadErrorMessage(err)) |message| return .{ .response = try self.publicSqlDiagnosticResponse(400, sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(.plan, .invalid_sql_request).withMessage(message).withMissingNativeModel("document SQL read shape")) };
            switch (err) {
                error.InvalidSqlCatalog, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(404, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) },
                error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
                error.UnsupportedSqlShape, error.UnsupportedRowsQuery, error.UnsupportedOperation => {
                    if (publicSqlGeneratedDocumentNativeSearchPredicateDiagnostic(parsed_sql, schema, .plan)) |diagnostic| {
                        return .{ .response = try self.publicSqlDiagnosticResponse(400, diagnostic) };
                    }
                    if (publicSqlGeneratedReadRowClaimDiagnostic(parsed_sql, .plan)) |diagnostic| {
                        return .{ .response = try self.publicSqlDiagnosticResponse(501, diagnostic) };
                    }
                    if (publicSqlUnsupportedGeneratedSubqueryPredicateDiagnostic(parsed_sql, .plan)) |diagnostic| {
                        return .{ .response = try self.publicSqlDiagnosticResponse(501, diagnostic) };
                    }
                    return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.plan, .unsupported_sql_statement)) };
                },
                else => return err,
            }
        };
        defer lowered.deinit(self.alloc);
        if (publicSqlReadUnsupportedRowClaimDiagnostic(&lowered, .plan)) |diagnostic| {
            return .{ .response = try self.publicSqlDiagnosticResponse(501, diagnostic) };
        }
        self.applyPublicSqlDocumentReadRowFilter(&lowered, session.session(), authenticated_identity) catch |err| switch (err) {
            error.InvalidQueryRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        try self.enforceSqlStatementTimeout(statement_timeout_ns, statement_start_ns);

        const result_columns = self.publicSqlReadResultColumnsAlloc(
            target_table_name,
            schema,
            source_table_name,
            lowered,
            session.session(),
        ) catch |err| switch (err) {
            error.InvalidRowsRequest, error.TableNotFound => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        var result_columns_owned = true;
        defer if (result_columns_owned) relational_rows_api.freeRowsOutputColumns(self.alloc, result_columns);

        result_columns_owned = false;
        return .{ .result = .{
            .session_id = self.ensureSqlProtocolSessionId(session),
            .statement_kind = @tagName(statement_kind),
            .has_row_description = true,
            .columns = result_columns,
        } };
    }

    fn applyPublicSqlDocumentReadRowFilter(
        self: *ApiHttpServer,
        lowered: *sql_adapter.LoweredReadPlan,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !void {
        switch (lowered.*) {
            .document_query => |*document_plan| {
                const row_filter_json = try self.resolvePublicSqlDocumentReadRowFilterJsonAlloc(session, authenticated_identity, document_plan.table_name);
                defer if (row_filter_json) |value| self.alloc.free(value);
                if (row_filter_json) |value| try sql_adapter.applyDocumentReadPlanFilterConstraintAlloc(self.alloc, document_plan, value);
            },
            .document_aggregate => |*aggregate_plan| {
                const row_filter_json = try self.resolvePublicSqlDocumentReadRowFilterJsonAlloc(session, authenticated_identity, aggregate_plan.table_name);
                defer if (row_filter_json) |value| self.alloc.free(value);
                if (row_filter_json) |value| try sql_adapter.applyDocumentAggregatePlanFilterConstraintAlloc(self.alloc, aggregate_plan, value);
            },
            else => {},
        }
    }

    fn clonePublicSqlReadColumnsAlloc(self: *ApiHttpServer, columns: []const runtime_schema_mod.RelationalColumn) ![]const runtime_schema_mod.RelationalColumn {
        var owned: std.ArrayListUnmanaged(runtime_schema_mod.RelationalColumn) = .empty;
        errdefer {
            for (owned.items) |column| {
                self.alloc.free(column.name);
                self.alloc.free(column.path);
                if (column.collation) |collation| self.alloc.free(collation);
            }
            owned.deinit(self.alloc);
        }
        for (columns) |column| {
            const name = try self.alloc.dupe(u8, column.name);
            errdefer self.alloc.free(name);
            const path = try self.alloc.dupe(u8, column.path);
            errdefer self.alloc.free(path);
            const collation = if (column.collation) |value| try self.alloc.dupe(u8, value) else null;
            errdefer if (collation) |value| self.alloc.free(value);
            var cloned = column;
            cloned.name = name;
            cloned.path = path;
            cloned.collation = collation;
            try owned.append(self.alloc, cloned);
        }
        return try owned.toOwnedSlice(self.alloc);
    }

    fn publicSqlReadResultColumnsAlloc(
        self: *ApiHttpServer,
        default_table_name: []const u8,
        default_schema: runtime_schema_mod.TableSchema,
        source_table_name: []const u8,
        lowered: sql_adapter.LoweredReadPlan,
        session: catalog_resources.SqlCatalogSession,
    ) ![]const runtime_schema_mod.RelationalColumn {
        switch (lowered) {
            .query => |query| {
                const owned_schema = try self.publicSqlCatalogSchemaUnlessDefaultAlloc(default_table_name, default_schema, query.table_name, session);
                defer if (owned_schema) |schema| runtime_schema_mod.freeSchema(self.alloc, schema);
                const runtime_schema = owned_schema orelse default_schema;
                return try relational_rows_api.rowsReadPlanOutputColumnsAlloc(self.alloc, runtime_schema, .{ .query = query.plan });
            },
            .document_query, .document_aggregate => return &.{},
            .set_operation => |set_operation| return try self.clonePublicSqlReadColumnsAlloc(set_operation.output_columns),
            .recursive_cte => |recursive_cte| return try self.clonePublicSqlReadColumnsAlloc(recursive_cte.output_columns),
            .aggregate => |aggregate| {
                const owned_schema = try self.publicSqlCatalogSchemaUnlessDefaultAlloc(default_table_name, default_schema, aggregate.table_name, session);
                defer if (owned_schema) |schema| runtime_schema_mod.freeSchema(self.alloc, schema);
                const runtime_schema = owned_schema orelse default_schema;
                return try relational_rows_api.rowsReadPlanOutputColumnsAlloc(self.alloc, runtime_schema, .{ .aggregate = aggregate.plan });
            },
            .window => |window| {
                const owned_schema = try self.publicSqlCatalogSchemaUnlessDefaultAlloc(default_table_name, default_schema, window.table_name, session);
                defer if (owned_schema) |schema| runtime_schema_mod.freeSchema(self.alloc, schema);
                const runtime_schema = owned_schema orelse default_schema;
                return try relational_rows_api.rowsReadPlanOutputColumnsAlloc(self.alloc, runtime_schema, .{ .window = window.plan });
            },
            .join => |join| {
                const owned_source_schema = try self.publicSqlCatalogSchemaUnlessDefaultAlloc(default_table_name, default_schema, source_table_name, session);
                defer if (owned_source_schema) |schema| runtime_schema_mod.freeSchema(self.alloc, schema);
                const source_schema = owned_source_schema orelse default_schema;
                return try relational_rows_api.rowsReadPlanOutputColumnsWithSchemasAlloc(self.alloc, default_schema, default_schema, source_schema, .{ .join = join.asPlan() });
            },
            .lateral => |lateral| {
                const owned_source_schema = try self.publicSqlCatalogSchemaUnlessDefaultAlloc(default_table_name, default_schema, source_table_name, session);
                defer if (owned_source_schema) |schema| runtime_schema_mod.freeSchema(self.alloc, schema);
                const source_schema = owned_source_schema orelse default_schema;
                return try relational_rows_api.rowsReadPlanOutputColumnsWithSchemasAlloc(self.alloc, default_schema, default_schema, source_schema, .{ .lateral = lateral.plan });
            },
        }
    }

