    fn publicSqlPostgresCompatibilityColumnsAlloc(
        self: *ApiHttpServer,
        names: []const []const u8,
    ) ![]const runtime_schema_mod.RelationalColumn {
        const columns = try self.alloc.alloc(runtime_schema_mod.RelationalColumn, names.len);
        var initialized: usize = 0;
        errdefer {
            for (columns[0..initialized]) |column| {
                self.alloc.free(column.name);
                self.alloc.free(column.path);
            }
            self.alloc.free(columns);
        }
        for (names, 0..) |name, i| {
            const owned_name = try self.alloc.dupe(u8, name);
            errdefer self.alloc.free(owned_name);
            const owned_path = try self.alloc.dupe(u8, name);
            errdefer self.alloc.free(owned_path);
            columns[i] = .{
                .name = owned_name,
                .path = owned_path,
                .field_type = .text,
                .nullable = false,
            };
            initialized += 1;
        }
        return columns;
    }

    fn publicSqlPostgresCompatibilityRowAlloc(
        self: *ApiHttpServer,
        columns: []const []const u8,
        values: []const []const u8,
    ) ![]const u8 {
        std.debug.assert(columns.len == values.len);
        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        try out.writer.writeByte('{');
        for (columns, values, 0..) |column, value, i| {
            if (i != 0) try out.writer.writeByte(',');
            try out.writer.print("{f}:{f}", .{ std.json.fmt(column, .{}), std.json.fmt(value, .{}) });
        }
        try out.writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    pub fn handlePublicSqlRequestResult(self: *ApiHttpServer, request: PublicSqlRequest, authenticated_identity: ?AuthenticatedIdentity) !PublicSqlResultOrResponse {
        return try self.executePublicSqlRequestResult(request, authenticated_identity);
    }

    pub fn executePublicSqlRequestResult(self: *ApiHttpServer, request: PublicSqlRequest, authenticated_identity: ?AuthenticatedIdentity) !PublicSqlResultOrResponse {
        if (std.mem.trim(u8, request.sql, " \t\r\n").len == 0) return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.parse, .invalid_sql_request)) };

        var session = self.ownedSqlCatalogSessionForPublicRequestAlloc(request) catch |err| switch (err) {
            error.InvalidSqlRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        defer session.deinit(self.alloc);

        var parsed_sql = sql_adapter.ParsedSql.initAlloc(self.alloc, request.sql) catch |err| switch (err) {
            error.UnsupportedSqlShape => {
                self.markPublicSqlTransactionFailedIfActive(&session);
                try self.savePublicSqlSession(session);
                return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.parse, .unsupported_sql_statement)) };
            },
            error.UnexpectedToken => {
                self.markPublicSqlTransactionFailedIfActive(&session);
                try self.savePublicSqlSession(session);
                return .{ .response = try self.publicSqlParseErrorDiagnosticResponse(400, request.sql) };
            },
            else => return err,
        };
        defer parsed_sql.deinit(self.alloc);

        var outcome = try self.executePublicParsedSqlRequestResult(.{
            .parsed_sql = &parsed_sql,
            .params = request.params,
            .session = &session,
            .authenticated_identity = authenticated_identity,
            .stdin_payload = request.stdin_payload,
        });
        errdefer outcome.deinit(self.alloc);
        try self.savePublicSqlSession(session);
        return outcome;
    }

    pub const PublicParsedSqlExecutionRequest = struct {
        parsed_sql: *const sql_adapter.ParsedSql,
        params: []const sql_adapter.SqlValue = &.{},
        session: *sql_adapter.OwnedSqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity = null,
        stdin_payload: ?[]const u8 = null,
    };

    pub const PublicParsedSqlRequest = struct {
        parsed_sql: *const sql_adapter.ParsedSql,
        session_id: ?u64 = null,
        database: ?[]const u8 = null,
        namespace: ?[]const u8 = null,
        read_only: ?bool = null,
        params: []const sql_adapter.SqlValue = &.{},
        stdin_payload: ?[]const u8 = null,
    };

    const PublicSqlPlannedExecutionPlan = union(enum) {
        logical: sql_adapter.LogicalSqlPlan,
        durable: sql_adapter.DurableSqlPlan,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            switch (self.*) {
                .logical => |*plan| plan.deinit(alloc),
                .durable => |*plan| plan.deinit(alloc),
            }
            self.* = undefined;
        }

        fn statementKindName(self: *const @This()) []const u8 {
            return switch (self.*) {
                .logical => |plan| publicSqlStatementKindForLogicalPlan(plan),
                .durable => |plan| publicSqlStatementKindForDurablePlan(plan),
            };
        }
    };

    const PublicSqlPlannedExecution = struct {
        plan: PublicSqlPlannedExecutionPlan,
        row_claim_owner_id: ?[]const u8 = null,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            self.plan.deinit(alloc);
            if (self.row_claim_owner_id) |owner_id| alloc.free(@constCast(owner_id));
            self.* = undefined;
        }
    };

    const PublicSqlPlannedExecutionOrResponse = union(enum) {
        planned: PublicSqlPlannedExecution,
        response: http_common.HttpResponse,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            switch (self.*) {
                .planned => |*planned| planned.deinit(alloc),
                .response => |*response| response.deinit(alloc),
            }
            self.* = undefined;
        }
    };

    const OwnedSqlBoundAuthorizationOptions = struct {
        value: sql_adapter.BoundSqlAuthorizationOptions = .{},
        grants: []sql_adapter.BoundSqlAuthorizationGrant = &.{},

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            if (self.grants.len > 0) alloc.free(self.grants);
            self.* = undefined;
        }
    };

    const PlannedBulkSqlExecution = struct {
        durable_plan: sql_adapter.DurableSqlPlan,
        execution_plan: sql_adapter.BulkSqlIoExecutionPlan,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            self.durable_plan.deinit(alloc);
            self.* = undefined;
        }
    };

    fn sqlAuthorizationPermissionFromUserPermission(permission: usermgr.PermissionType) sql_adapter.BoundSqlAuthorizationPermission {
        return switch (permission) {
            .read => .read,
            .write => .write,
            .admin => .admin,
        };
    }

    fn sqlAuthorizationResourceKindFromUserResource(resource_type: usermgr.ResourceType) ?sql_adapter.BoundSqlAuthorizationResourceKind {
        return switch (resource_type) {
            .table => .table,
            .database => .database,
            .@"*" => .all,
            .namespace, .tablespace, .user => null,
        };
    }

    fn sqlBoundAuthorizationOptionsForIdentityAlloc(
        self: *ApiHttpServer,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !OwnedSqlBoundAuthorizationOptions {
        const identity = authenticated_identity orelse return .{};
        var out = OwnedSqlBoundAuthorizationOptions{};
        errdefer out.deinit(self.alloc);

        out.value.principal_name = identity.username;
        if (identity.permissions.len == 0) {
            out.value.unrestricted = true;
            return out;
        }

        var grants = std.ArrayListUnmanaged(sql_adapter.BoundSqlAuthorizationGrant).empty;
        errdefer grants.deinit(self.alloc);
        for (identity.permissions) |permission| {
            const resource_kind = sqlAuthorizationResourceKindFromUserResource(permission.resource_type) orelse continue;
            try grants.append(self.alloc, .{
                .resource_kind = resource_kind,
                .resource = permission.resource,
                .permission = sqlAuthorizationPermissionFromUserPermission(permission.type),
            });
        }
        out.grants = try grants.toOwnedSlice(self.alloc);
        out.value.grants = out.grants;
        out.value.grants_evaluated = true;
        return out;
    }

    fn sqlBoundAuthorizationOptionsForIdentityPtrAlloc(
        self: *ApiHttpServer,
        authenticated_identity: ?*const AuthenticatedIdentity,
    ) !OwnedSqlBoundAuthorizationOptions {
        if (authenticated_identity) |identity| return try self.sqlBoundAuthorizationOptionsForIdentityAlloc(identity.*);
        return .{};
    }

    fn authenticatedIdentityAllowsSqlDatabaseAdmin(
        self: *ApiHttpServer,
        authenticated_identity: ?AuthenticatedIdentity,
        session: catalog_resources.SqlCatalogSession,
    ) bool {
        if (!self.cfg.auth_enabled and self.cfg.trusted_principal_secret == null) return true;
        const identity = authenticated_identity orelse return false;
        if (identity.permissions.len == 0) return true;
        return permissionsAllow(identity.permissions, .@"*", "*", .admin) or
            permissionsAllow(identity.permissions, .database, session.currentDatabase(), .admin);
    }

    fn enforceAuthenticatedIdentitySqlTablePermission(
        self: *ApiHttpServer,
        authenticated_identity: ?AuthenticatedIdentity,
        target: catalog_resources.TableTarget,
        permission_type: usermgr.PermissionType,
    ) !void {
        const identity = authenticated_identity orelse return;
        if (identity.permissions.len == 0) return;

        const resource_name = try catalog_resources.tableResourceNameAlloc(self.alloc, target.database_name, target.namespace_name, target.table_name);
        defer self.alloc.free(resource_name);
        if (permissionsAllow(identity.permissions, .table, resource_name, permission_type) or
            permissionsAllow(identity.permissions, .database, target.database_name, permission_type))
        {
            return;
        }
        return error.PermissionDenied;
    }

    fn enforceAntflyQueryFunctionReadPermissionBeforeCatalogPlanning(
        self: *ApiHttpServer,
        parsed_sql: *const sql_adapter.ParsedSql,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !void {
        const query_table_name = sql_adapter.antflyQueryFunctionReadTableNameAlloc(self.alloc, parsed_sql) catch |err| switch (err) {
            error.UnsupportedSqlShape => if (sql_adapter.parsedSqlHasGeneratedAntflyReadSource(parsed_sql)) return err else return,
            else => return err,
        };
        defer self.alloc.free(query_table_name);
        const target = session.tableTargetFromObjectName(query_table_name) catch |err| switch (err) {
            error.UnsupportedSqlShape => return,
        };
        try self.enforceAuthenticatedIdentitySqlTablePermission(authenticated_identity, target, .read);
    }

    fn publicSqlLogicalPlanRequiresDatabaseAdmin(logical_plan: sql_adapter.LogicalSqlPlan) bool {
        return switch (logical_plan) {
            .table_ddl, .catalog_ddl, .extension, .routine, .auth, .maintenance => true,
            else => false,
        };
    }

    fn parsedSqlReadOnlyBulkIoAllowed(parsed_sql: *const sql_adapter.ParsedSql) bool {
        const tokens = parsed_sql.items();
        const raw = parsed_sql.raw_statement;
        if (raw.token_start >= raw.token_end or raw.token_end > tokens.len) return false;
        if (!tokens[raw.token_start].matchesKeywordTag(.copy)) return false;
        for (tokens[raw.token_start + 1 .. raw.token_end]) |token| {
            if (token.matchesKeywordTag(.to)) return true;
            if (token.matchesKeywordTag(.from)) return false;
        }
        return false;
    }

    fn enforcePublicSqlLogicalPlanAuthorization(
        self: *ApiHttpServer,
        logical_plan: *sql_adapter.LogicalSqlPlan,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !void {
        try sql_adapter.enforceLogicalSqlPlanAuthorization(logical_plan);
        if (publicSqlLogicalPlanRequiresDatabaseAdmin(logical_plan.*) and
            !self.authenticatedIdentityAllowsSqlDatabaseAdmin(authenticated_identity, session))
        {
            return error.PermissionDenied;
        }
    }

    fn planPublicParsedSqlExecutionAlloc(
        self: *ApiHttpServer,
        parsed_sql: *const sql_adapter.ParsedSql,
        session: *sql_adapter.OwnedSqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !PublicSqlPlannedExecutionOrResponse {
        const write_statement_kind = parsed_sql.writeStatementKindIncludingGeneratedAst();
        const is_read_statement = switch (parsed_sql.statement) {
            .read => true,
            else => false,
        };
        if (is_read_statement) {
            try self.enforceAntflyQueryFunctionReadPermissionBeforeCatalogPlanning(parsed_sql, session.session(), authenticated_identity);
        }
        var unique_resolver_ctx = RowsUniqueSelectorResolverContext{ .source = self.table_reads };
        var sequence_resolver_ctx = RowsSequenceDefaultResolverContext{ .source = self.source };
        var scalar_default_resolver_ctx: RowsScalarSubqueryDefaultResolverContext = undefined;
        var write_options: sql_adapter.LowerWritePlanOptions = .{};
        var row_claim_owner_id: ?[]const u8 = null;
        defer if (row_claim_owner_id) |owner_id| self.alloc.free(@constCast(owner_id));
        if (write_statement_kind) |statement_kind| {
            if (try self.publicSqlReadOnlyActive(session)) {
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, sql_adapter.diagnostics.SqlDiagnosticEnvelope.init(.execute, .read_only_transaction).withMessage("cannot execute write statement in a read-only transaction")) };
            }
            switch (statement_kind) {
                .insert, .insert_source, .update, .update_source, .update_joined_source, .delete, .delete_source, .delete_joined_source, .truncate, .merge => {},
            }

            const sync_level = sql_adapter.sqlSyncLevelFromSession(session.session()) catch |err| switch (err) {
                error.InvalidRoleSetting => return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.bind, .invalid_role_setting)) },
            };
            const default_read_source = self.effectivePublicTableReads() orelse return .{ .response = try self.publicSqlParsedDiagnosticResponse(404, parsed_sql, .init(.bind, .table_not_found)) };
            scalar_default_resolver_ctx = .{ .source = self.source, .table_reads = default_read_source };
            const row_claim: ?db_mod.types.RowClaimRequest = switch (statement_kind) {
                .update, .update_source, .update_joined_source, .delete, .delete_source, .delete_joined_source, .truncate => try self.sqlMutationRowClaimAlloc(session),
                else => null,
            };
            row_claim_owner_id = if (row_claim) |claim| claim.owner_id else null;
            write_options = .{
                .unique_resolver = unique_resolver_ctx.resolver(),
                .default_context = .{
                    .sequence_resolver = sequence_resolver_ctx.resolver(),
                    .scalar_subquery_resolver = scalar_default_resolver_ctx.resolver(),
                },
                .row_claim = row_claim,
                .sync_level = sync_level,
            };
        }

        const routine_bindings = try self.sql_routine_runtime.listExpressionRoutineBindingsAlloc(self.alloc);
        defer sql_routines.freeExpressionRoutineBindings(self.alloc, routine_bindings);
        const function_bindings: sql_adapter.SqlFunctionBindings = .{
            .routine_expressions = routine_bindings,
        };
        var authorization_options = try self.sqlBoundAuthorizationOptionsForIdentityAlloc(authenticated_identity);
        defer authorization_options.deinit(self.alloc);

        var logical_plan = sql_adapter.planParsedSqlWithSessionAlloc(self.alloc, parsed_sql, .{
            .catalog = self.catalogSource().sqlSource(),
            .session = session.session(),
            .write_options = write_options,
            .function_bindings = function_bindings,
            .authorization = authorization_options.value,
        }) catch |err| switch (err) {
            error.InvalidSqlCatalog, error.TableNotFound => {
                if (write_statement_kind != null) std.log.err("public sql write bind not found err={}", .{err});
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(404, parsed_sql, (sql_adapter.diagnostics.knownErrorDiagnostic(.bind, err) orelse .init(.bind, .invalid_sql_catalog))) };
            },
            error.InvalidRowsRequest, error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.UnsupportedRowsSelector, error.RowSelectorNotFound => {
                if (write_statement_kind != null) return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.bind, .invalid_sql_write)) };
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.bind, .invalid_sql_request)) };
            },
            error.PermissionDenied => return .{ .response = try self.publicSqlParsedDiagnosticResponse(403, parsed_sql, .init(.bind, .permission_denied)) },
            error.UnsupportedSqlShape, error.UnsupportedRowsQuery, error.UnsupportedOperation => {
                if (try self.publicSqlDocumentUnsupportedReadDiagnosticFromCatalog(parsed_sql, session.session(), .plan)) |diagnostic| {
                    return .{ .response = try self.publicSqlDiagnosticResponse(400, diagnostic) };
                }
                if (try self.publicSqlGeneratedDocumentNativeSearchPredicateDiagnosticFromCatalog(parsed_sql, session.session(), .plan)) |diagnostic| {
                    return .{ .response = try self.publicSqlDiagnosticResponse(400, diagnostic) };
                }
                if (publicSqlGeneratedReadRowClaimDiagnostic(parsed_sql, .plan)) |diagnostic| {
                    return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, diagnostic) };
                }
                if (publicSqlUnsupportedGeneratedSubqueryPredicateDiagnostic(parsed_sql, .plan)) |diagnostic| {
                    return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, diagnostic) };
                }
                if (write_statement_kind == null and
                    !is_read_statement and
                    try self.publicSqlReadOnlyActive(session) and
                    !parsedSqlReadOnlyBulkIoAllowed(parsed_sql))
                {
                    return error.SqlReadOnlyTransaction;
                }
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) };
            },
            error.UniqueOwnerTopologyUnavailable, error.TopologyChanged, error.DocIdentityNamespaceMismatch => return .{ .response = try self.publicSqlParsedDiagnosticResponse(503, parsed_sql, .init(.plan, .unique_owner_unavailable)) },
            else => return err,
        };
        defer logical_plan.deinit(self.alloc);
        self.enforcePublicSqlLogicalPlanAuthorization(&logical_plan, session.session(), authenticated_identity) catch
            return .{ .response = try self.publicSqlParsedDiagnosticResponse(403, parsed_sql, .init(.bind, .permission_denied)) };
        var execution_plan = try takePublicSqlPlannedExecutionPlanFromLogical(&logical_plan);
        errdefer execution_plan.deinit(self.alloc);
        const owner_id = row_claim_owner_id;
        row_claim_owner_id = null;
        return .{ .planned = .{
            .plan = execution_plan,
            .row_claim_owner_id = owner_id,
        } };
    }

    fn executePublicSqlDurablePlannedExecution(
        self: *ApiHttpServer,
        durable_plan: *sql_adapter.DurableSqlPlan,
        parsed_sql: *const sql_adapter.ParsedSql,
        session: *sql_adapter.OwnedSqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
        stdin_payload: ?[]const u8,
    ) !PublicSqlResultOrResponse {
        switch (durable_plan.*) {
            .bulk_io => return try ApiHttpServer.executePublicBulkSqlDurablePlanWithSession(self, durable_plan, session, authenticated_identity, stdin_payload),
            else => {
                if (try self.publicSqlReadOnlyActive(session)) return error.SqlReadOnlyTransaction;
                const context = RelationalDdlPlanExecutionContext{ .parsed_sql = parsed_sql };
                const timing = try self.sqlStatementExecutionTimingForContext(session, context);
                const statement_kind = publicSqlStatementKindForDurablePlan(durable_plan.*);
                var applied = try self.applyDurableSqlPlanWithSession(durable_plan, session, context, timing);
                errdefer applied.deinit(self.alloc);
                const session_id = self.ensureSqlProtocolSessionId(session);
                return .{ .result = .{
                    .session_id = session_id,
                    .statement_kind = statement_kind,
                    .transaction_status = self.publicSqlTransactionStatus(session),
                    .result = .{ .ddl = .{
                        .applied = applied,
                        .command_tag = publicSqlDdlCommandTag(parsed_sql),
                    } },
                } };
            },
        }
    }

    fn executePublicSqlDurablePlannedExecutionOrDiagnostic(
        self: *ApiHttpServer,
        durable_plan: *sql_adapter.DurableSqlPlan,
        subject_parsed_sql: *const sql_adapter.ParsedSql,
        execute_sql: *const sql_adapter.ParsedSql,
        session: *sql_adapter.OwnedSqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity,
        stdin_payload: ?[]const u8,
    ) !PublicSqlResultOrResponse {
        return self.executePublicSqlDurablePlannedExecution(durable_plan, subject_parsed_sql, session, authenticated_identity, stdin_payload) catch |err| switch (err) {
            error.DocumentSqlViewMappingUnsupported => .{ .response = try self.publicSqlParsedDiagnosticResponse(400, subject_parsed_sql, .init(.plan, .document_sql_view_mapping_unsupported)) },
            error.SqlReadOnlyTransaction => .{ .response = try self.publicSqlParsedDiagnosticResponse(400, execute_sql, .init(.execute, .read_only_transaction)) },
            error.PermissionDenied, error.Unauthorized => .{ .response = try self.publicSqlParsedDiagnosticResponse(403, subject_parsed_sql, .init(.bind, .permission_denied)) },
            error.TableNotFound, error.InvalidSqlCatalog => .{ .response = try self.publicSqlParsedDiagnosticResponse(404, subject_parsed_sql, .init(.bind, .invalid_sql_catalog)) },
            error.InvalidRowsRequest, error.InvalidArgument, error.UnsupportedRowsSelector => .{ .response = try self.publicSqlParsedDiagnosticResponse(400, subject_parsed_sql, .init(.bind, .invalid_sql_request)) },
            error.UnsupportedSqlShape, error.UnsupportedOperation => .{ .response = try self.publicSqlParsedDiagnosticResponse(501, subject_parsed_sql, .init(.plan, .unsupported_sql_statement)) },
            error.StatementTimeout => .{ .response = try self.publicSqlParsedDiagnosticResponse(408, execute_sql, .init(.execute, .statement_timeout)) },
            error.InvalidSqlSession,
            error.PreparedStatementAlreadyExists,
            error.PreparedStatementNotFound,
            error.PreparedStatementArgumentMismatch,
            error.SavepointNotFound,
            error.InvalidRoleSetting,
            error.RoleSettingNotFound,
            => .{ .response = try self.publicSqlParsedDiagnosticResponse(400, subject_parsed_sql, (sql_adapter.diagnostics.knownErrorDiagnostic(.execute, err) orelse .init(.execute, .invalid_sql_request))) },
            else => return err,
        };
    }

    pub fn executePublicParsedSqlRequestResult(self: *ApiHttpServer, request: PublicParsedSqlExecutionRequest) !PublicSqlResultOrResponse {
        const parsed_sql = request.parsed_sql;
        const session = request.session;

        if (session.sql_transaction_failed and !parsedSqlTransactionBoundaryClearsLocalSession(parsed_sql)) {
            return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .current_transaction_aborted)) };
        }
        if (try self.handlePublicSqlPostgresCompatibilityRead(parsed_sql, session, request.params)) |outcome_value| {
            var outcome = outcome_value;
            errdefer outcome.deinit(self.alloc);
            switch (outcome) {
                .result => |*result| result.transaction_status = self.publicSqlTransactionStatus(session),
                .response => self.markPublicSqlTransactionFailedIfActive(session),
            }
            return outcome;
        }
        const maybe_read_kind = parsed_sql.readStatementKindIncludingGeneratedAst();
        if (maybe_read_kind) |read_kind| {
            if (try self.handlePublicSqlQueryFunctionRead(parsed_sql, session, request.authenticated_identity, read_kind)) |outcome_value| {
                var outcome = outcome_value;
                errdefer outcome.deinit(self.alloc);
                switch (outcome) {
                    .result => |*result| result.transaction_status = self.publicSqlTransactionStatus(session),
                    .response => self.markPublicSqlTransactionFailedIfActive(session),
                }
                return outcome;
            }
        }
        var planned_or_response = self.planPublicParsedSqlExecutionAlloc(parsed_sql, session, request.authenticated_identity) catch |err| switch (err) {
            error.DocumentSqlViewMappingUnsupported => {
                self.markPublicSqlTransactionFailedIfActive(session);
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.plan, .document_sql_view_mapping_unsupported)) };
            },
            error.SqlReadOnlyTransaction => {
                self.markPublicSqlTransactionFailedIfActive(session);
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .read_only_transaction)) };
            },
            error.UnsupportedSqlShape => {
                self.markPublicSqlTransactionFailedIfActive(session);
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) };
            },
            error.StatementTimeout => {
                self.markPublicSqlTransactionFailedIfActive(session);
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(408, parsed_sql, .init(.execute, .statement_timeout)) };
            },
            error.PermissionDenied => {
                self.markPublicSqlTransactionFailedIfActive(session);
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(403, parsed_sql, .init(.bind, .permission_denied)) };
            },
            error.InvalidSqlSession,
            error.PreparedStatementAlreadyExists,
            error.PreparedStatementNotFound,
            error.PreparedStatementArgumentMismatch,
            error.InvalidSqlCatalog,
            error.SavepointNotFound,
            error.InvalidRoleSetting,
            error.RoleSettingNotFound,
            => {
                self.markPublicSqlTransactionFailedIfActive(session);
                return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, (sql_adapter.diagnostics.knownErrorDiagnostic(.execute, err) orelse .init(.execute, .invalid_sql_request))) };
            },
            else => return err,
        };
        var planned_or_response_owned = true;
        defer if (planned_or_response_owned) planned_or_response.deinit(self.alloc);

        switch (planned_or_response) {
            .response => |*response| {
                self.markPublicSqlTransactionFailedIfActive(session);
                const out = response.*;
                planned_or_response_owned = false;
                return .{ .response = out };
            },
            .planned => |*planned| {
                var outcome: PublicSqlResultOrResponse = switch (planned.plan) {
                    .logical => |*logical_plan| switch (logical_plan.*) {
                        .catalog_write => try self.handlePublicSqlWrite(logical_plan, parsed_sql, request.params, session, request.authenticated_identity),
                        .catalog_read => try self.handlePublicSqlRead(logical_plan, parsed_sql, request.params, session, request.authenticated_identity),
                        .prepared_statement => |*prepared_plan| try self.executePublicSqlPreparedStatementLogicalPlanWithSession(prepared_plan, parsed_sql, session, request.authenticated_identity),
                        .cursor => |*cursor_plan| try self.executePublicSqlCursorLogicalPlanWithSession(cursor_plan, parsed_sql, session, request.params, request.authenticated_identity),
                        .read, .write => .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) },
                        else => ddl_blk: {
                            const statement_kind = publicSqlStatementKindForLogicalPlan(logical_plan.*);
                            var applied = ApiHttpServer.applyLogicalSqlPlanWithSession(self, logical_plan, session, .{ .parsed_sql = parsed_sql }) catch |err| switch (err) {
                                error.DocumentSqlViewMappingUnsupported => {
                                    self.markPublicSqlTransactionFailedIfActive(session);
                                    return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.plan, .document_sql_view_mapping_unsupported)) };
                                },
                                error.SqlReadOnlyTransaction => {
                                    self.markPublicSqlTransactionFailedIfActive(session);
                                    return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, .init(.execute, .read_only_transaction)) };
                                },
                                error.UnsupportedSqlShape => {
                                    self.markPublicSqlTransactionFailedIfActive(session);
                                    return .{ .response = try self.publicSqlParsedDiagnosticResponse(501, parsed_sql, .init(.plan, .unsupported_sql_statement)) };
                                },
                                error.StatementTimeout => {
                                    self.markPublicSqlTransactionFailedIfActive(session);
                                    return .{ .response = try self.publicSqlParsedDiagnosticResponse(408, parsed_sql, .init(.execute, .statement_timeout)) };
                                },
                                error.InvalidSqlSession,
                                error.PreparedStatementAlreadyExists,
                                error.PreparedStatementNotFound,
                                error.PreparedStatementArgumentMismatch,
                                error.InvalidSqlCatalog,
                                error.SavepointNotFound,
                                error.InvalidRoleSetting,
                                error.RoleSettingNotFound,
                                => {
                                    self.markPublicSqlTransactionFailedIfActive(session);
                                    return .{ .response = try self.publicSqlParsedDiagnosticResponse(400, parsed_sql, (sql_adapter.diagnostics.knownErrorDiagnostic(.execute, err) orelse .init(.execute, .invalid_sql_request))) };
                                },
                                else => return err,
                            };
                            errdefer applied.deinit(self.alloc);
                            const session_id = self.ensureSqlProtocolSessionId(session);
                            break :ddl_blk .{ .result = .{
                                .session_id = session_id,
                                .statement_kind = statement_kind,
                                .transaction_status = self.publicSqlTransactionStatus(session),
                                .result = .{ .ddl = .{
                                    .applied = applied,
                                    .command_tag = publicSqlDdlCommandTag(parsed_sql),
                                } },
                            } };
                        },
                    },
                    .durable => |*durable_plan| try self.executePublicSqlDurablePlannedExecutionOrDiagnostic(
                        durable_plan,
                        parsed_sql,
                        parsed_sql,
                        session,
                        request.authenticated_identity,
                        request.stdin_payload,
                    ),
                };
                errdefer outcome.deinit(self.alloc);
                switch (outcome) {
                    .response => self.markPublicSqlTransactionFailedIfActive(session),
                    .result => |*result| result.transaction_status = self.publicSqlTransactionStatus(session),
                }
                return outcome;
            },
        }
    }

    pub fn executePublicParsedSqlExternalRequestResult(self: *ApiHttpServer, request: PublicParsedSqlRequest, authenticated_identity: ?AuthenticatedIdentity) !PublicSqlResultOrResponse {
        var session = self.ownedSqlCatalogSessionForPublicParsedSqlRequestAlloc(request) catch |err| switch (err) {
            error.InvalidSqlRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        defer session.deinit(self.alloc);

        var outcome = try self.executePublicParsedSqlRequestResult(.{
            .parsed_sql = request.parsed_sql,
            .params = request.params,
            .session = &session,
            .authenticated_identity = authenticated_identity,
            .stdin_payload = request.stdin_payload,
        });
        errdefer outcome.deinit(self.alloc);
        try self.savePublicSqlSession(session);
        return outcome;
    }

    pub const PublicParsedSqlDescribeRequest = struct {
        parsed_sql: *const sql_adapter.ParsedSql,
        params: []const sql_adapter.SqlValue = &.{},
        session: *sql_adapter.OwnedSqlCatalogSession,
        authenticated_identity: ?AuthenticatedIdentity = null,
    };

    pub fn handlePublicParsedSqlDescribeRequestResult(self: *ApiHttpServer, request: PublicParsedSqlDescribeRequest) !PublicSqlDescribeResultOrResponse {
        const parsed_sql = request.parsed_sql;
        const session = request.session;
        if (try self.describePublicSqlPostgresCompatibilityReadAlloc(parsed_sql, session)) |result_value| {
            var result = result_value;
            errdefer result.deinit(self.alloc);
            result.transaction_status = self.publicSqlTransactionStatus(session);
            return .{ .result = result };
        }
        if (switch (parsed_sql.statement) {
            .read => true,
            else => false,
        }) {
            var outcome = try self.describePublicSqlReadColumnsAlloc(parsed_sql, request.params, session, request.authenticated_identity);
            errdefer outcome.deinit(self.alloc);
            switch (outcome) {
                .result => |*result| result.transaction_status = self.publicSqlTransactionStatus(session),
                .response => {},
            }
            return outcome;
        }

        const statement_kind: []const u8 = switch (parsed_sql.statement) {
            .write => |statement| @tagName(statement.kind),
            else => blk: {
                var planned_or_response = try self.planPublicParsedSqlExecutionAlloc(parsed_sql, session, request.authenticated_identity);
                var planned_or_response_owned = true;
                defer if (planned_or_response_owned) planned_or_response.deinit(self.alloc);
                switch (planned_or_response) {
                    .response => |*response| {
                        const out = response.*;
                        planned_or_response_owned = false;
                        return .{ .response = out };
                    },
                    .planned => |planned| break :blk planned.plan.statementKindName(),
                }
            },
        };
        const session_id = self.ensureSqlProtocolSessionId(session);
        return .{ .result = .{
            .session_id = session_id,
            .statement_kind = statement_kind,
            .transaction_status = self.publicSqlTransactionStatus(session),
            .has_row_description = false,
        } };
    }

    pub fn handlePublicParsedSqlExternalDescribeRequestResult(self: *ApiHttpServer, request: PublicParsedSqlRequest, authenticated_identity: ?AuthenticatedIdentity) !PublicSqlDescribeResultOrResponse {
        var session = self.ownedSqlCatalogSessionForPublicParsedSqlRequestAlloc(request) catch |err| switch (err) {
            error.InvalidSqlRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        defer session.deinit(self.alloc);

        var outcome = try self.handlePublicParsedSqlDescribeRequestResult(.{
            .parsed_sql = request.parsed_sql,
            .params = request.params,
            .session = &session,
            .authenticated_identity = authenticated_identity,
        });
        errdefer outcome.deinit(self.alloc);
        try self.savePublicSqlSession(session);
        return outcome;
    }

    pub fn handlePublicSqlDescribeRequestResult(self: *ApiHttpServer, request: PublicSqlRequest, authenticated_identity: ?AuthenticatedIdentity) !PublicSqlDescribeResultOrResponse {
        if (std.mem.trim(u8, request.sql, " \t\r\n").len == 0) return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.parse, .invalid_sql_request)) };

        var session = self.ownedSqlCatalogSessionForPublicRequestAlloc(request) catch |err| switch (err) {
            error.InvalidSqlRequest => return .{ .response = try self.publicSqlDiagnosticResponse(400, .init(.bind, .invalid_sql_request)) },
            else => return err,
        };
        defer session.deinit(self.alloc);

        var parsed_sql = sql_adapter.ParsedSql.initAlloc(self.alloc, request.sql) catch |err| switch (err) {
            error.UnsupportedSqlShape => return .{ .response = try self.publicSqlDiagnosticResponse(501, .init(.parse, .unsupported_sql_statement)) },
            error.UnexpectedToken => return .{ .response = try self.publicSqlParseErrorDiagnosticResponse(400, request.sql) },
            else => return err,
        };
        defer parsed_sql.deinit(self.alloc);
        var outcome = try self.handlePublicParsedSqlDescribeRequestResult(.{
            .parsed_sql = &parsed_sql,
            .params = request.params,
            .session = &session,
            .authenticated_identity = authenticated_identity,
        });
        errdefer outcome.deinit(self.alloc);
        try self.savePublicSqlSession(session);
        return outcome;
    }

    fn applyPreparedTransactionPlan(
        self: *ApiHttpServer,
        plan: sql_adapter.PreparedTransactionPlan,
        timestamp_ns: u64,
    ) !sql_adapter.PreparedTransactionCoordinatorResult {
        return self.source.applyPreparedTransactionPlan(self.alloc, plan, timestamp_ns) catch |err| switch (err) {
            error.UnsupportedOperation => {
                const opened = self.opened_session_store orelse return err;
                return try sql_adapter.executePreparedTransactionRecoveryPlan(self.alloc, opened.docstore, plan, timestamp_ns);
            },
            else => return err,
        };
    }

    fn resolveRoutineSettingsFromCurrentInPlace(
        self: *ApiHttpServer,
        plan: *sql_adapter.FunctionCatalogPlan,
        session: catalog_resources.SqlCatalogSession,
    ) !void {
        switch (plan.*) {
            .create => |*create| try self.resolveCreateRoutineSettingsFromCurrentInPlace(create, session),
            .drop => {},
        }
    }

    fn resolveCreateRoutineSettingsFromCurrentInPlace(
        self: *ApiHttpServer,
        create: *sql_adapter.CreateRoutinePlan,
        session: catalog_resources.SqlCatalogSession,
    ) !void {
        if (create.settings.len == 0) return;
        const settings = @constCast(create.settings);
        for (settings) |*setting| {
            if (!setting.from_current) continue;
            if (setting.values.len != 0) return error.InvalidRoleSetting;
            const values = try self.currentRoutineSettingValuesAlloc(session, setting.name);
            setting.values = values;
            setting.from_current = false;
        }
    }

    fn currentRoutineSettingValuesAlloc(
        self: *ApiHttpServer,
        session: catalog_resources.SqlCatalogSession,
        name: []const u8,
    ) ![]const []const u8 {
        if (std.ascii.eqlIgnoreCase(name, "search_path")) {
            const default_search_path: []const []const u8 = &.{catalog_resources.default_namespace_name};
            const source = if (session.search_path.len == 0)
                default_search_path
            else
                session.search_path;
            return try cloneStringSliceConstAlloc(self.alloc, source);
        }

        const value = session.settingValue(name) orelse return error.RoleSettingNotFound;
        try sql_adapter.validateSqlDatabaseSettingValue(name, value);
        const values = try self.alloc.alloc([]const u8, 1);
        errdefer self.alloc.free(values);
        values[0] = try self.alloc.dupe(u8, value);
        return values;
    }

    fn cloneStringSliceConstAlloc(
        alloc: std.mem.Allocator,
        values: []const []const u8,
    ) ![]const []const u8 {
        const out = try alloc.alloc([]const u8, values.len);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |value| alloc.free(@constCast(value));
            alloc.free(out);
        }
        for (values, 0..) |value, i| {
            out[i] = try alloc.dupe(u8, value);
            initialized += 1;
        }
        return out;
    }

    fn schemaRewriteWakeOwnerId(self: *ApiHttpServer, runtime: *db_mod.background_runtime.BackendRuntime) !u64 {
        if (self.schema_rewrite_wake_owner_id == 0) {
            self.schema_rewrite_wake_owner_id = try runtime.allocOwnerId();
        }
        return self.schema_rewrite_wake_owner_id;
    }

    fn tableEmptyingWakeOwnerId(self: *ApiHttpServer, runtime: *db_mod.background_runtime.BackendRuntime) !u64 {
        if (self.table_emptying_wake_owner_id == 0) {
            self.table_emptying_wake_owner_id = try runtime.allocOwnerId();
        }
        return self.table_emptying_wake_owner_id;
    }

    fn submitSchemaRewriteWakeForTable(
        self: *ApiHttpServer,
        runtime: *db_mod.background_runtime.BackendRuntime,
        write_source: table_writes.TableWriteSource,
        table: metadata_table_manager.TableRecord,
    ) !bool {
        if (!try self.maintenance_wake_registry.tryAcquire(self.alloc, table.table_id)) return false;
        var acquired = true;
        errdefer if (acquired) self.maintenance_wake_registry.release(table.table_id);
        try SchemaRewriteWakeJob.submitWithPromotionAndRegistry(
            runtime,
            try self.schemaRewriteWakeOwnerId(runtime),
            write_source,
            table.name,
            self.catalogSource(),
            table,
            &self.maintenance_wake_registry,
            table.table_id,
        );
        acquired = false;
        return true;
    }

    fn submitTableEmptyingWakeForTable(
        self: *ApiHttpServer,
        runtime: *db_mod.background_runtime.BackendRuntime,
        write_source: table_writes.TableWriteSource,
        table: metadata_table_manager.TableRecord,
    ) !bool {
        if (!try self.maintenance_wake_registry.tryAcquire(self.alloc, table.table_id)) return false;
        var acquired = true;
        errdefer if (acquired) self.maintenance_wake_registry.release(table.table_id);
        try TableEmptyingWakeJob.submitWithCatalogAndRegistry(
            runtime,
            try self.tableEmptyingWakeOwnerId(runtime),
            write_source,
            self.catalogSource(),
            table.name,
            &self.maintenance_wake_registry,
            table.table_id,
        );
        acquired = false;
        return true;
    }

    fn scheduleSchemaRewriteRuntimeHintForAppliedDdl(
        self: *ApiHttpServer,
        applied: tables_api.AppliedRelationalSqlDdlRecord,
    ) !void {
        if (!catalog_jobs.appliedDdlHasSchemaRewriteWork(applied)) return;
        const runtime = self.cfg.backend_runtime orelse return;
        const write_source = self.table_writes orelse return;
        _ = try self.submitSchemaRewriteWakeForTable(runtime, write_source, applied.table);
    }

    fn scheduleTableEmptyingRuntimeHintsForTables(
        self: *ApiHttpServer,
        tables: []const metadata_table_manager.TableRecord,
    ) !void {
        const runtime = self.cfg.backend_runtime orelse return;
        const write_source = self.table_writes orelse return;
        for (tables) |table| {
            _ = try self.submitTableEmptyingWakeForTable(runtime, write_source, table);
        }
    }

    fn refreshSqlExtensionQueryFunctions(self: *ApiHttpServer) !void {
        var snapshot = (try self.source.adminSnapshot()) orelse {
            try self.sql_routine_runtime.replaceNativeQueryFunctionBindings(&.{});
            return;
        };
        defer self.source.freeAdminSnapshot(&snapshot);
        const bindings = try extension_domain.listReadyNativeQueryFunctionBindingsAlloc(self.alloc, snapshot.installed_extensions, snapshot.extension_members);
        defer extension_domain.freeQueryFunctionBindings(self.alloc, bindings);
        try self.sql_routine_runtime.replaceNativeQueryFunctionBindings(bindings);
    }

    pub fn lowerRelationalSqlReadPlanWithRoutineBindingsAlloc(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        sql: []const u8,
        schema: runtime_schema_mod.TableSchema,
        params: []const sql_adapter.SqlValue,
        catalog: ?table_catalog.CatalogSource,
    ) !sql_adapter.LoweredReadPlan {
        return try self.lowerRelationalSqlReadPlanWithRoutineBindingsAndSessionAlloc(
            alloc,
            sql,
            schema,
            params,
            catalog,
            catalog_resources.SqlCatalogSession.default(),
        );
    }

    pub fn lowerRelationalSqlReadPlanWithRoutineBindingsAndSessionAlloc(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        sql: []const u8,
        schema: runtime_schema_mod.TableSchema,
        params: []const sql_adapter.SqlValue,
        catalog: ?table_catalog.CatalogSource,
        session: catalog_resources.SqlCatalogSession,
    ) !sql_adapter.LoweredReadPlan {
        const routine_bindings = try self.sql_routine_runtime.listExpressionRoutineBindingsAlloc(alloc);
        defer sql_routines.freeExpressionRoutineBindings(alloc, routine_bindings);
        const function_bindings: sql_adapter.SqlFunctionBindings = .{
            .routine_expressions = routine_bindings,
        };
        var parsed_sql = try sql_adapter.ParsedSql.initAlloc(alloc, sql);
        defer parsed_sql.deinit(alloc);
        if (catalog) |source_catalog| {
            var logical_plan = try sql_adapter.planParsedSqlWithSessionAlloc(alloc, &parsed_sql, .{
                .catalog = source_catalog.sqlSource(),
                .session = session,
                .function_bindings = function_bindings,
            });
            defer logical_plan.deinit(alloc);
            return try sql_adapter.lowerReadPlanWithLogicalPlanAndFunctionBindingsAlloc(alloc, &parsed_sql, &logical_plan, schema, params, function_bindings);
        }
        return try sql_adapter.lowerReadPlanWithFunctionBindingsParsedSqlAlloc(alloc, &parsed_sql, schema, params, function_bindings);
    }

    fn planBulkSqlExecutionWithSessionAlloc(
        self: *ApiHttpServer,
        parsed_sql: *const sql_adapter.ParsedSql,
        session: catalog_resources.SqlCatalogSession,
        authenticated_identity: ?*const AuthenticatedIdentity,
    ) !PlannedBulkSqlExecution {
        var authorization_options = try self.sqlBoundAuthorizationOptionsForIdentityPtrAlloc(authenticated_identity);
        defer authorization_options.deinit(self.alloc);

        var planned_statement = try sql_adapter.planDurableDdlSqlWithSessionAuthorizationEvidenceAlloc(self.alloc, parsed_sql, .{
            .catalog = self.catalogSource().sqlSource(),
            .session = session,
            .authorization = authorization_options.value,
        });
        errdefer planned_statement.deinit(self.alloc);
        const bulk_plan = switch (planned_statement.durable_plan) {
            .bulk_io => |plan| plan,
            else => return error.UnsupportedSqlShape,
        };
        const execution_plan = try sql_adapter.bulkSqlIoExecutionPlanFromDdlPlan(bulk_plan);

        sql_adapter.enforceBoundSqlAuthorization(planned_statement.authorization) catch |err| {
            if (err == error.PermissionDenied) {
                const target = try session.tableTargetFromObjectName(execution_plan.table_name);
                self.recordSqlBulkIoDeniedAudit(execution_plan, target, authenticated_identity, err);
            }
            return err;
        };
        planned_statement.authorization.deinit(self.alloc);
        planned_statement.authorization = .{};

        return .{
            .durable_plan = planned_statement.durable_plan,
            .execution_plan = execution_plan,
        };
    }

