    fn executePublicTableBatch(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        req: db_mod.types.BatchRequest,
    ) public_table_http.TableApi.ExecuteBatchError!void {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        const source = self.table_writes orelse return error.NotFound;
        self.validateTableWritesAgainstSchema(table_name, req.writes) catch |err| switch (err) {
            error.InvalidBatchRequest => return error.InvalidBatchRequest,
            error.TableNotFound => return error.NotFound,
            else => {
                std.log.err("public table batch schema validation failed table={s} err={}", .{ table_name, err });
                return error.InternalFailure;
            },
        };
        comptime {
            std.debug.assert(@sizeOf(db_mod.types.BatchWrite) == @sizeOf(db_mod.types.TransactionWrite));
            std.debug.assert(@alignOf(db_mod.types.BatchWrite) == @alignOf(db_mod.types.TransactionWrite));
        }
        const txn_writes: []const db_mod.types.TransactionWrite = @ptrCast(req.writes);
        const tables = [_]distributed_txn.TableCommitRequest{.{
            .table_name = table_name,
            .writes = txn_writes,
            .deletes = req.deletes,
            .transforms = req.transforms,
            .predicates = req.predicates,
        }};
        const outcome = (source.commitBatch(alloc, &tables, req.sync_level) catch |err| switch (err) {
            error.InvalidBatchRequest,
            error.InvalidArgument,
            error.InvalidGraphEdges,
            error.UnsupportedTransformOperation,
            error.ForeignKeyViolation,
            error.UniqueConstraintViolation,
            => return error.InvalidBatchRequest,
            error.TableNotFound, error.UnknownGroup => return error.NotFound,
            error.TopologyChanged,
            error.DecisionConflict,
            error.TxnNotFound,
            error.InvalidTxnRecord,
            => return error.Conflict,
            error.CommitVisibilityNotSatisfied,
            error.CommitPropagationIncomplete,
            => return error.CommittedPending,
            error.AbortDecisionNotDurable,
            error.TransactionBeginFailed,
            => return error.WriteUnavailable,
            error.CommitDecisionUnknown => return error.OutcomeUnknown,
            error.UnsupportedOperation => return error.MethodNotAllowed,
            error.DocIdentityNamespaceMismatch => return error.DocIdentityUnavailable,
            error.EnrichmentRetryInProgress,
            error.ResourceBudgetExceeded,
            error.PersistentDescriptorAdmissionExhausted,
            error.TextMergeBackpressureTimeout,
            error.TextMergeBackpressureUnavailable,
            error.TextMergeRuntimeShutdown,
            => return error.Backpressured,
            error.DenseRepairBackpressure => return error.DenseRepairBackpressure,
            error.LeaderUnavailable, error.WriteUnavailable => return error.WriteUnavailable,
            error.RaftBatchWriteOutcomeUnknown => return error.WriteOutcomeUnknown,
            // The public batch path is atomic: multi-group writes use 2PC and
            // the single-group fast path is one Raft command. Preserve the
            // conservative do-not-retry signal if a legacy adapter reports a
            // partial outcome, without advertising a partial public commit.
            error.RaftBatchWritePartialOutcome => return error.WriteOutcomeUnknown,
            error.HAReadOnlyStandby => return error.HAReadOnlyStandby,
            error.HAPromotedStandbyRequiresPrimaryOpen => return error.HAPromotedStandbyRequiresPrimaryOpen,
            error.HAFencedPrimary => return error.HAFencedPrimary,
            else => {
                std.log.err("public table batch failed table={s} err={}", .{ table_name, err });
                return error.InternalFailure;
            },
        }) orelse return error.NotFound;
        switch (outcome) {
            .committed => |committed| if (committed.propagation_pending or committed.visibility_pending) return error.CommittedPending,
            .conflict => return error.Conflict,
        }
    }

    fn executePublicTableQueryRequest(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        body: []const u8,
        row_filter_json: ?[]const u8,
    ) public_table_http.TableApi.ExecuteQueryError![]u8 {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        const source = self.table_reads orelse return error.NotFound;
        return self.executePublicTableQueryDispatchWithReadinessRetry(alloc, source, table_name, body, row_filter_json, null, null) catch |err| switch (err) {
            error.InvalidQueryRequest => return error.InvalidQueryRequest,
            error.InvalidFilterQueryRequest => return error.InvalidFilterQueryRequest,
            error.InvalidExclusionQueryRequest => return error.InvalidExclusionQueryRequest,
            error.UnsupportedFilterQueryRequest => return error.UnsupportedFilterQueryRequest,
            error.UnsupportedExclusionQueryRequest => return error.UnsupportedExclusionQueryRequest,
            error.Timeout => return error.ReadUnavailable,
            error.IdentityReadGenerationChanged => return error.ReadUnavailable,
            error.DocIdentityNamespaceMismatch => return error.DocIdentityUnavailable,
            error.IndexRebuilding => return error.IndexRebuilding,
            error.HAReadRequiresPrimary, error.ReadRequiresPrimary => return error.ReadRequiresPrimary,
            error.LeaderUnavailable => return error.LeaderUnavailable,
            error.HAReadWaitForApply,
            error.HAReadWaitForMetadata,
            error.ReadUnavailable,
            => return error.ReadUnavailable,
            error.PersistentDescriptorAdmissionExhausted,
            error.StorageReadTemporarilyUnavailable,
            => return error.StorageReadTemporarilyUnavailable,
            error.ModelNotFound => return error.ModelNotFound,
            error.UnsupportedExactSort => return error.UnsupportedExactSort,
            error.QueryCandidateBudgetExceeded => return error.QueryCandidateBudgetExceeded,
            error.QueryEmbeddingInputTooLarge => return error.QueryEmbeddingInputTooLarge,
            error.QueryEmbeddingOverloaded => return error.QueryEmbeddingOverloaded,
            error.EmbedRateLimited => return error.EmbedRateLimited,
            error.EmbedTransientFailure => return error.EmbedTransientFailure,
            error.EmbedUpstreamFailure => return error.EmbedUpstreamFailure,
            error.InvalidManifest => return error.InvalidManifest,
            error.InvalidTableFile => return error.InvalidTableFile,
            error.TableBlockChecksumMismatch => return error.TableBlockChecksumMismatch,
            error.CorruptInput => return error.CorruptInput,
            error.UnsupportedVersion => return error.UnsupportedVersion,
            error.Corrupted => return error.Corrupted,
            else => {
                std.log.err("public table query execution failed table={s} err={}", .{ table_name, err });
                return error.InternalFailure;
            },
        };
    }

    fn executePublicTableQueryDispatch(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        source: table_reads.TableReadSource,
        table_name: []const u8,
        body: []const u8,
        row_filter_json: ?[]const u8,
    ) ![]u8 {
        const execution_deadline_ns = try query_contract.queryExecutionDeadlineNsFromBody(alloc, body);
        return try self.executePublicTableQueryDispatchWithIdentity(
            alloc,
            source,
            table_name,
            body,
            row_filter_json,
            null,
            execution_deadline_ns,
            null,
        );
    }

    fn executePublicTableQueryDispatchWithReadinessRetry(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        source: table_reads.TableReadSource,
        table_name: []const u8,
        body: []const u8,
        row_filter_json: ?[]const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        cancellation: ?*const std.atomic.Value(bool),
    ) ![]u8 {
        const retry_timeout_ns: u64 = if (self.table_writes != null) 5 * std.time.ns_per_s else 0;
        const retry_poll_ns = 50 * std.time.ns_per_ms;
        const start_ns = platform_time.monotonicNs();
        const request_deadline_ns = query_contract.queryExecutionDeadlineNsFromBody(alloc, body) catch return error.InvalidQueryRequest;
        while (true) {
            try ensureRequestActive(cancellation);
            if (retryDeadlineExpired(request_deadline_ns, platform_time.monotonicNs())) return error.Timeout;
            return self.executePublicTableQueryDispatchWithIdentity(
                alloc,
                source,
                table_name,
                body,
                row_filter_json,
                authenticated_identity,
                request_deadline_ns,
                cancellation,
            ) catch |err| switch (err) {
                error.DocIdentityNamespaceMismatch,
                error.IdentityReadGenerationChanged,
                error.StorageReadTemporarilyUnavailable,
                => {
                    const now_ns = platform_time.monotonicNs();
                    if (retryDeadlineExpired(request_deadline_ns, now_ns)) return error.Timeout;
                    if (retry_timeout_ns == 0) return err;
                    const sleep_ns = boundedRetrySleepNs(request_deadline_ns, now_ns, start_ns, retry_timeout_ns, retry_poll_ns) orelse return err;
                    if (sleep_ns == 0) return error.Timeout;
                    try sleepNsCancellable(sleep_ns, cancellation);
                    continue;
                },
                error.Timeout => return error.Timeout,
                error.InvalidQueryRequest => return err,
                else => return err,
            };
        }
    }

    fn executePublicCatalogTableQueryDispatchWithReadinessRetry(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        source: table_reads.TableReadSource,
        target: catalog_resources.TableTarget,
        body: []const u8,
        row_filter_json: ?[]const u8,
        authenticated_identity: ?AuthenticatedIdentity,
    ) ![]u8 {
        const retry_timeout_ns: u64 = if (self.table_writes != null) 5 * std.time.ns_per_s else 0;
        const retry_poll_ns = 50 * std.time.ns_per_ms;
        const start_ns = platform_time.monotonicNs();
        const request_deadline_ns = query_contract.queryExecutionDeadlineNsFromBody(alloc, body) catch return error.InvalidQueryRequest;
        while (true) {
            if (retryDeadlineExpired(request_deadline_ns, platform_time.monotonicNs())) return error.Timeout;
            return self.executePublicCatalogTableQueryDispatchWithIdentity(
                alloc,
                source,
                target,
                body,
                row_filter_json,
                authenticated_identity,
                request_deadline_ns,
            ) catch |err| switch (err) {
                error.DocIdentityNamespaceMismatch => {
                    const now_ns = platform_time.monotonicNs();
                    if (retryDeadlineExpired(request_deadline_ns, now_ns)) return error.Timeout;
                    if (retry_timeout_ns == 0) return err;
                    const sleep_ns = boundedRetrySleepNs(request_deadline_ns, now_ns, start_ns, retry_timeout_ns, retry_poll_ns) orelse return err;
                    if (sleep_ns == 0) return error.Timeout;
                    sleepNs(sleep_ns);
                    continue;
                },
                error.Timeout => return error.Timeout,
                error.InvalidQueryRequest => return err,
                else => return err,
            };
        }
    }

    fn executePublicTableQueryDispatchWithIdentity(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        source: table_reads.TableReadSource,
        table_name: []const u8,
        body: []const u8,
        row_filter_json: ?[]const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        request_deadline_ns: ?u64,
        cancellation: ?*const std.atomic.Value(bool),
    ) ![]u8 {
        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);
        if (try shouldDispatchPlainPublicSearch(alloc, body)) {
            var result = self.executePlainPublicTableQuery(
                alloc,
                source,
                table_name,
                body,
                row_filter_json,
                authenticated_identity,
                request_deadline_ns,
                queryEmbeddingSecurityScope(authenticated_identity),
                cancellation,
            ) catch |err| switch (err) {
                error.InvalidQueryRequest,
                error.InvalidFilterQueryRequest,
                error.InvalidExclusionQueryRequest,
                error.UnsupportedFilterQueryRequest,
                error.UnsupportedExclusionQueryRequest,
                => return err,
                error.UnsupportedQueryRequest => return unsupportedPublicTableQueryDispatchError(alloc, body),
                error.UnsupportedExactSort => return error.UnsupportedExactSort,
                error.TableNotFound, error.NotFound => return error.NotFound,
                error.IdentityReadGenerationChanged => return error.IdentityReadGenerationChanged,
                error.ModelNotFound => return error.ModelNotFound,
                error.QueryCandidateBudgetExceeded => return error.QueryCandidateBudgetExceeded,
                error.QueryEmbeddingInputTooLarge,
                error.QueryEmbeddingOverloaded,
                error.EmbedRateLimited,
                error.EmbedTransientFailure,
                error.EmbedUpstreamFailure,
                => return err,
                error.DocIdentityNamespaceMismatch => return error.DocIdentityNamespaceMismatch,
                error.IndexRebuilding => return error.IndexRebuilding,
                error.HAReadRequiresPrimary, error.ReadRequiresPrimary => return error.ReadRequiresPrimary,
                error.LeaderUnavailable => return error.LeaderUnavailable,
                error.HAReadWaitForApply,
                error.HAReadWaitForMetadata,
                error.ReadUnavailable,
                => return error.ReadUnavailable,
                error.PersistentDescriptorAdmissionExhausted,
                error.StorageReadTemporarilyUnavailable,
                => return error.StorageReadTemporarilyUnavailable,
                error.Timeout => return error.Timeout,
                error.Cancelled => return error.Cancelled,
                error.InvalidManifest,
                error.InvalidTableFile,
                error.TableBlockChecksumMismatch,
                error.CorruptInput,
                error.UnsupportedVersion,
                error.Corrupted,
                => return err,
                else => {
                    std.log.err("public table query execution failed table={s} err={}", .{ table_name, err });
                    return error.InternalFailure;
                },
            };
            defer result.deinit(alloc);
            return try alloc.dupe(u8, result.json);
        }

        var contract_req = metadata_openapi.server.parseQueryTableBody(alloc, body) catch return error.InvalidQueryRequest;
        defer contract_req.deinit();

        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);
        if (self.executeForeignPublicTableQueryIfAny(alloc, source, table_name, body, row_filter_json, authenticated_identity, request_deadline_ns, cancellation) catch |err| switch (err) {
            error.InvalidQueryRequest => return error.InvalidQueryRequest,
            error.UnsupportedQueryRequest => return unsupportedPublicTableQueryDispatchError(alloc, body),
            error.UnsupportedExactSort => return error.UnsupportedExactSort,
            error.ModelNotFound => return error.ModelNotFound,
            error.QueryCandidateBudgetExceeded => return error.QueryCandidateBudgetExceeded,
            error.QueryEmbeddingInputTooLarge,
            error.QueryEmbeddingOverloaded,
            error.EmbedRateLimited,
            error.EmbedTransientFailure,
            error.EmbedUpstreamFailure,
            => return err,
            error.IdentityReadGenerationChanged => return error.IdentityReadGenerationChanged,
            error.DocIdentityNamespaceMismatch => return error.DocIdentityNamespaceMismatch,
            error.IndexRebuilding => return error.IndexRebuilding,
            error.TableNotFound, error.NotFound => return error.NotFound,
            error.HAReadRequiresPrimary, error.ReadRequiresPrimary => return error.ReadRequiresPrimary,
            error.HAReadWaitForApply,
            error.HAReadWaitForMetadata,
            error.ReadUnavailable,
            => return error.ReadUnavailable,
            error.PersistentDescriptorAdmissionExhausted,
            error.StorageReadTemporarilyUnavailable,
            => return error.StorageReadTemporarilyUnavailable,
            error.Timeout => return error.Timeout,
            error.LeaderUnavailable => return error.LeaderUnavailable,
            error.Cancelled => return error.Cancelled,
            error.InvalidManifest,
            error.InvalidTableFile,
            error.TableBlockChecksumMismatch,
            error.CorruptInput,
            error.UnsupportedVersion,
            error.Corrupted,
            => return err,
            else => {
                std.log.err("foreign public table query execution failed table={s} err={}", .{ table_name, err });
                return error.InternalFailure;
            },
        }) |json| {
            return json;
        }

        const join_req = distributed_join.parseSupportedJoinRequestWithSecrets(alloc, body, self.cfg.secret_store) catch |err| switch (err) {
            error.InvalidQueryRequest, error.UnsupportedQueryRequest => return error.InvalidQueryRequest,
            else => {
                std.log.err("public table join parse failed table={s} err={}", .{ table_name, err });
                return error.InternalFailure;
            },
        };
        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);
        if (join_req) |owned_join| {
            var parsed_join = owned_join;
            defer parsed_join.deinit(alloc);
            if (authenticated_identity) |identity| {
                try self.applyAuthenticatedIdentityToJoinRequestForDatabase(alloc, identity, tables_api.default_database_name, &parsed_join.join);
            }
            const join_ctx = self.joinContext().withExecutionDeadline(request_deadline_ns).withCancellation(cancellation);
            return distributed_join.executeSupportedJoinedPublicTableQueryRequest(join_ctx, &self.join_job_store, alloc, source, table_name, body, row_filter_json, parsed_join.join, parsed_join.foreign_sources);
        }

        var result = self.executePlainPublicTableQuery(
            alloc,
            source,
            table_name,
            body,
            row_filter_json,
            authenticated_identity,
            request_deadline_ns,
            queryEmbeddingSecurityScope(authenticated_identity),
            cancellation,
        ) catch |err| switch (err) {
            error.InvalidQueryRequest,
            error.InvalidFilterQueryRequest,
            error.InvalidExclusionQueryRequest,
            error.UnsupportedFilterQueryRequest,
            error.UnsupportedExclusionQueryRequest,
            => return err,
            error.UnsupportedQueryRequest => return unsupportedPublicTableQueryDispatchError(alloc, body),
            error.UnsupportedExactSort => return error.UnsupportedExactSort,
            error.TableNotFound => return error.NotFound,
            error.IdentityReadGenerationChanged => return error.IdentityReadGenerationChanged,
            error.ModelNotFound => return error.ModelNotFound,
            error.QueryCandidateBudgetExceeded => return error.QueryCandidateBudgetExceeded,
            error.QueryEmbeddingInputTooLarge,
            error.QueryEmbeddingOverloaded,
            error.EmbedRateLimited,
            error.EmbedTransientFailure,
            error.EmbedUpstreamFailure,
            => return err,
            error.DocIdentityNamespaceMismatch => return error.DocIdentityNamespaceMismatch,
            error.IndexRebuilding => return error.IndexRebuilding,
            error.HAReadRequiresPrimary, error.ReadRequiresPrimary => return error.ReadRequiresPrimary,
            error.LeaderUnavailable => return error.LeaderUnavailable,
            error.HAReadWaitForApply,
            error.HAReadWaitForMetadata,
            error.ReadUnavailable,
            => return error.ReadUnavailable,
            error.PersistentDescriptorAdmissionExhausted,
            error.StorageReadTemporarilyUnavailable,
            => return error.StorageReadTemporarilyUnavailable,
            error.Timeout => return error.Timeout,
            error.Cancelled => return error.Cancelled,
            error.InvalidManifest,
            error.InvalidTableFile,
            error.TableBlockChecksumMismatch,
            error.CorruptInput,
            error.UnsupportedVersion,
            error.Corrupted,
            => return err,
            else => {
                std.log.err("public table query execution failed table={s} err={}", .{ table_name, err });
                return error.InternalFailure;
            },
        };
        defer result.deinit(alloc);
        return try alloc.dupe(u8, result.json);
    }

    fn executePublicCatalogTableQueryDispatchWithIdentity(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        source: table_reads.TableReadSource,
        target: catalog_resources.TableTarget,
        body: []const u8,
        row_filter_json: ?[]const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        request_deadline_ns: ?u64,
    ) ![]u8 {
        if (try shouldDispatchPlainPublicSearch(alloc, body)) {
            var result = self.executePlainPublicCatalogTableQuery(
                alloc,
                source,
                target,
                body,
                row_filter_json,
                request_deadline_ns,
            ) catch |err| switch (err) {
                error.InvalidQueryRequest, error.UnsupportedQueryRequest => return error.InvalidQueryRequest,
                error.TableNotFound => return error.TableNotFound,
                error.DocIdentityNamespaceMismatch => return error.DocIdentityNamespaceMismatch,
                error.LeaderUnavailable, error.ReadUnavailable => return err,
                error.Timeout => return error.Timeout,
                else => {
                    std.log.err("public catalog table query execution failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                    return error.InternalFailure;
                },
            };
            defer result.deinit(alloc);
            return try alloc.dupe(u8, result.json);
        }

        var contract_req = metadata_openapi.server.parseQueryTableBody(alloc, body) catch return error.InvalidQueryRequest;
        defer contract_req.deinit();

        if (self.executeForeignPublicCatalogTableQueryIfAny(alloc, source, target, body, row_filter_json, authenticated_identity, request_deadline_ns) catch |err| switch (err) {
            error.InvalidQueryRequest, error.UnsupportedQueryRequest => return error.InvalidQueryRequest,
            error.DocIdentityNamespaceMismatch => return error.DocIdentityNamespaceMismatch,
            error.LeaderUnavailable, error.ReadUnavailable => return err,
            else => {
                std.log.err("foreign public catalog table query execution failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                return error.InternalFailure;
            },
        }) |json| {
            return json;
        }

        const join_req = distributed_join.parseSupportedJoinRequestWithSecrets(alloc, body, self.cfg.secret_store) catch |err| switch (err) {
            error.InvalidQueryRequest, error.UnsupportedQueryRequest => return error.InvalidQueryRequest,
            else => {
                std.log.err("public catalog table join parse failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                return error.InternalFailure;
            },
        };
        if (join_req) |owned_join| {
            var parsed_join = owned_join;
            defer parsed_join.deinit(alloc);
            if (authenticated_identity) |identity| {
                try self.applyAuthenticatedIdentityToJoinRequestForDatabase(alloc, identity, target.database_name, &parsed_join.join);
            }
            const catalog_table_name = try catalog_resources.tableResourceNameAlloc(alloc, target.database_name, target.namespace_name, target.table_name);
            defer alloc.free(catalog_table_name);
            return distributed_join.executeSupportedJoinedPublicTableQueryRequest(self.joinContext(), &self.join_job_store, alloc, source, catalog_table_name, body, row_filter_json, parsed_join.join, parsed_join.foreign_sources);
        }

        var result = self.executePlainPublicCatalogTableQuery(
            alloc,
            source,
            target,
            body,
            row_filter_json,
            request_deadline_ns,
        ) catch |err| switch (err) {
            error.InvalidQueryRequest, error.UnsupportedQueryRequest => return error.InvalidQueryRequest,
            error.TableNotFound => return error.NotFound,
            error.DocIdentityNamespaceMismatch => return error.DocIdentityNamespaceMismatch,
            error.LeaderUnavailable, error.ReadUnavailable => return err,
            error.Timeout => return error.Timeout,
            else => {
                std.log.err("public catalog table query execution failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                return error.InternalFailure;
            },
        };
        defer result.deinit(alloc);
        return try alloc.dupe(u8, result.json);
    }

    fn shouldDispatchPlainPublicSearch(alloc: std.mem.Allocator, body: []const u8) !bool {
        if (std.mem.indexOf(u8, body, "\"join\"") == null and
            std.mem.indexOf(u8, body, "\"foreign_sources\"") == null and
            (std.mem.indexOf(u8, body, "\"full_text_search\"") != null or
                std.mem.indexOf(u8, body, "\"semantic_search\"") != null or
                std.mem.indexOf(u8, body, "\"embeddings\"") != null or
                std.mem.indexOf(u8, body, "\"filter_query\"") != null or
                std.mem.indexOf(u8, body, "\"exclusion_query\"") != null))
        {
            return true;
        }

        var parsed = std.json.parseFromSlice(std.json.Value, alloc, body, .{}) catch return false;
        defer parsed.deinit();
        const object = switch (parsed.value) {
            .object => |object| object,
            else => return false,
        };
        if (jsonObjectHasNonNullField(object, "join")) return false;
        if (jsonObjectHasNonNullField(object, "foreign_sources")) return false;
        return public_search_request.looksLikePublicSearchRequest(parsed.value) or
            jsonObjectHasNonNullField(object, "full_text_search") or
            jsonObjectHasNonNullField(object, "semantic_search") or
            jsonObjectHasNonNullField(object, "embeddings") or
            jsonObjectHasNonNullField(object, "filter_query") or
            jsonObjectHasNonNullField(object, "exclusion_query");
    }

    fn jsonObjectHasNonNullField(object: std.json.ObjectMap, key: []const u8) bool {
        const value = object.get(key) orelse return false;
        return value != .null;
    }

    fn executeForeignPublicTableQueryIfAny(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        source: table_reads.TableReadSource,
        table_name: []const u8,
        body: []const u8,
        row_filter_json: ?[]const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        request_deadline_ns: ?u64,
        cancellation: ?*const std.atomic.Value(bool),
    ) anyerror!?[]u8 {
        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);
        var parsed_request = parsePublicTableQueryBody(alloc, body) catch return error.InvalidQueryRequest;
        defer parsed_request.deinit();
        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);
        const request = &parsed_request.value;
        if (row_filter_json) |value| {
            try injectRowFilterIntoOpenApiQueryRequest(alloc, request, value);
        }

        var foreign_sources = foreign_sources_api.postgresSourceMapFromMetadataOpenApiResolvedWithSecrets(alloc, request.foreign_sources, self.cfg.secret_store) catch |err| switch (err) {
            error.UnsupportedSourceKind => return error.UnsupportedQueryRequest,
            else => return err,
        };
        defer foreign_sources.deinit(alloc);
        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);

        const foreign_source = foreign_sources.get(table_name) orelse return null;
        return try self.executeForeignPublicTableQueryWithSource(
            alloc,
            source,
            table_name,
            body,
            row_filter_json,
            authenticated_identity,
            tables_api.default_database_name,
            request,
            foreign_source,
            request_deadline_ns,
            cancellation,
        );
    }

    fn executeForeignPublicCatalogTableQueryIfAny(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        source: table_reads.TableReadSource,
        target: catalog_resources.TableTarget,
        body: []const u8,
        row_filter_json: ?[]const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        request_deadline_ns: ?u64,
    ) anyerror!?[]u8 {
        try ensureRequestDeadline(request_deadline_ns);
        var parsed_request = metadata_openapi.server.parseQueryTableBody(alloc, body) catch return error.InvalidQueryRequest;
        defer parsed_request.deinit();
        const request = &parsed_request.value;
        if (row_filter_json) |value| {
            try injectRowFilterIntoOpenApiQueryRequest(alloc, request, value);
        }

        var foreign_sources = foreign_sources_api.postgresSourceMapFromMetadataOpenApiResolvedWithSecrets(alloc, request.foreign_sources, self.cfg.secret_store) catch |err| switch (err) {
            error.UnsupportedSourceKind => return error.UnsupportedQueryRequest,
            else => return err,
        };
        defer foreign_sources.deinit(alloc);

        const foreign_source = try foreignPostgresSourceForCatalogTargetAlloc(alloc, foreign_sources, target) orelse return null;
        const catalog_table_name = try catalog_resources.tableResourceNameAlloc(alloc, target.database_name, target.namespace_name, target.table_name);
        defer alloc.free(catalog_table_name);
        return try self.executeForeignPublicTableQueryWithSource(
            alloc,
            source,
            catalog_table_name,
            body,
            row_filter_json,
            authenticated_identity,
            target.database_name,
            request,
            foreign_source,
            request_deadline_ns,
            null,
        );
    }

    fn executeForeignPublicTableQueryWithSource(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        source: table_reads.TableReadSource,
        table_name: []const u8,
        body: []const u8,
        row_filter_json: ?[]const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        database_name: []const u8,
        request: anytype,
        foreign_source: foreign_mod.PostgresConfig,
        request_deadline_ns: ?u64,
        cancellation: ?*const std.atomic.Value(bool),
    ) anyerror![]u8 {
        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);
        try validateSupportedForeignPublicQueryRequest(request);

        if (request.join != null) {
            var parsed_join = (try distributed_join.parseSupportedJoinRequestWithSecrets(alloc, body, self.cfg.secret_store)) orelse return error.InvalidQueryRequest;
            defer parsed_join.deinit(alloc);
            if (authenticated_identity) |identity| {
                try self.applyAuthenticatedIdentityToJoinRequestForDatabase(alloc, identity, database_name, &parsed_join.join);
            }
            return try self.executeSupportedJoinedForeignPublicTableQueryRequest(
                alloc,
                source,
                table_name,
                body,
                row_filter_json,
                foreign_source,
                parsed_join.join,
                parsed_join.foreign_sources,
                request_deadline_ns,
                cancellation,
            );
        }

        return try self.encodeForeignPublicTableQueryResponseAlloc(alloc, table_name, request.*, foreign_source, request_deadline_ns, cancellation);
    }

    fn foreignPostgresSourceForCatalogTargetAlloc(
        alloc: std.mem.Allocator,
        foreign_sources: foreign_mod.PostgresSourceMap,
        target: catalog_resources.TableTarget,
    ) !?foreign_mod.PostgresConfig {
        const qualified = try catalog_resources.tableResourceNameAlloc(alloc, target.database_name, target.namespace_name, target.table_name);
        defer alloc.free(qualified);
        for (foreign_sources.entries) |entry| {
            if (std.mem.eql(u8, entry.name, qualified)) return entry.config;
            if (foreignSourceNameMatchesCatalogTarget(entry.name, target)) return entry.config;
        }
        return null;
    }

    fn foreignSourceNameMatchesCatalogTarget(name: []const u8, target: catalog_resources.TableTarget) bool {
        var dots: [2]usize = undefined;
        var dot_count: usize = 0;
        for (name, 0..) |ch, i| {
            if (ch != '.') continue;
            if (dot_count >= dots.len) return false;
            dots[dot_count] = i;
            dot_count += 1;
        }
        return switch (dot_count) {
            0 => catalog_resources.tableIsDefaultPublic(target) and std.mem.eql(u8, name, target.table_name),
            1 => std.mem.eql(u8, name[0..dots[0]], target.namespace_name) and
                std.mem.eql(u8, name[dots[0] + 1 ..], target.table_name),
            2 => std.mem.eql(u8, name[0..dots[0]], target.database_name) and
                std.mem.eql(u8, name[dots[0] + 1 .. dots[1]], target.namespace_name) and
                std.mem.eql(u8, name[dots[1] + 1 ..], target.table_name),
            else => false,
        };
    }

    fn encodeForeignPublicTableQueryResponseAlloc(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        request: anytype,
        foreign_source: foreign_mod.PostgresConfig,
        request_deadline_ns: ?u64,
        cancellation: ?*const std.atomic.Value(bool),
    ) ![]u8 {
        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);
        const registry = try self.ensureForeignRegistry();
        const started_ns = platform_time.monotonicNs();
        const limit = try foreignQueryLimit(request.limit);
        const offset = try foreignQueryOffset(request.offset);
        const aggregations_json = if (request.aggregations) |aggregations|
            try std.json.Stringify.valueAlloc(alloc, aggregations, .{})
        else
            null;
        defer if (aggregations_json) |json| alloc.free(json);
        const aggregation_requests = if (aggregations_json) |json|
            try query_api.parseAggregationRequestsJson(alloc, json)
        else
            &.{};
        defer query_api.freeAggregationRequests(alloc, aggregation_requests);
        try ensureRequestDeadline(request_deadline_ns);

        const raw_filter_query_json = if (request.filter_query) |query|
            try stringifyJsonValueAlloc(alloc, query)
        else
            null;
        defer if (raw_filter_query_json) |query| alloc.free(query);
        const filter_query_json = try foreign_sources_api.buildEffectiveFilterQueryJsonAlloc(
            alloc,
            foreign_source,
            raw_filter_query_json,
            request.filter_prefix,
        );
        defer if (filter_query_json) |query| alloc.free(query);

        const foreign_order_by = try cloneForeignSortFieldsAlloc(alloc, request.order_by);
        defer freeForeignSortFields(alloc, foreign_order_by);

        var params = try foreign_source.toQueryParams(alloc, .{
            .fields = if (request.fields) |fields| fields else &.{},
            .filter_query_json = filter_query_json,
            .limit = limit,
            .offset = offset,
            .order_by = foreign_order_by,
        });
        defer params.deinit(alloc);
        params.execution_deadline_ns = request_deadline_ns;
        params.cancellation = cancellation;
        try ensureRequestDeadline(request_deadline_ns);

        const source_config = try foreign_source.toSourceConfig(alloc);
        var foreign_query_source = try registry.create(alloc, source_config);
        defer foreign_query_source.deinit(alloc);
        try ensureRequestDeadline(request_deadline_ns);

        var query_result = try foreign_query_source.query(alloc, params);
        defer query_result.deinit(alloc);
        try ensureRequestDeadline(request_deadline_ns);
        const aggregation_results: []db_mod.aggregations.SearchAggregationResult = if (aggregation_requests.len > 0) blk: {
            var aggregate_params = try foreign_sources_api.buildPostgresAggregateParamsAlloc(
                alloc,
                foreign_source,
                aggregation_requests,
                filter_query_json,
            );
            defer aggregate_params.deinit(alloc);
            aggregate_params.execution_deadline_ns = request_deadline_ns;
            aggregate_params.cancellation = cancellation;
            var aggregate_result = foreign_query_source.aggregate(alloc, aggregate_params) catch |err| switch (err) {
                error.UnsupportedAggregate => return error.UnsupportedQueryRequest,
                else => return err,
            };
            defer aggregate_result.deinit(alloc);
            try ensureRequestActive(cancellation);
            try ensureRequestDeadline(request_deadline_ns);
            break :blk try foreign_sources_api.foreignAggregateResultsToSearchResultsAlloc(alloc, aggregation_requests, aggregate_result);
        } else @constCast(@as([]const db_mod.aggregations.SearchAggregationResult, &.{}));
        var response_meta: query_api.QueryResponseMeta = .{
            .aggregation_results = aggregation_results,
        };
        defer response_meta.deinit(alloc);

        const result_hits = if (request.count == true)
            try alloc.alloc(db_mod.types.SearchHit, 0)
        else
            try buildForeignSearchHitsAlloc(alloc, foreign_source, query_result.rows, request_deadline_ns, cancellation);
        var result: db_mod.types.SearchResult = .{
            .alloc = alloc,
            .hits = result_hits,
            .total_hits = @intCast(@min(query_result.total, std.math.maxInt(u32))),
        };
        defer result.deinit();
        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);

        const response_req: db_mod.types.SearchRequest = .{
            .count_only = request.count == true,
            .profile = request.profile == true,
            .aggregations_json = if (aggregations_json) |json| try alloc.dupe(u8, json) else &.{},
        };
        defer if (response_req.aggregations_json.len > 0) alloc.free(response_req.aggregations_json);
        response_meta.took_ms = @intCast(@divTrunc(platform_time.monotonicNs() - started_ns, std.time.ns_per_ms));

        var response = try query_api.encodeQueryResponses(alloc, table_name, .{
            .count_only = response_req.count_only,
            .profile = response_req.profile,
            .limit = @intCast(limit orelse 10),
            .offset = @intCast(offset),
            .aggregations_json = response_req.aggregations_json,
        }, response_meta, result);
        defer response.deinit(alloc);
        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);
        const response_json = try alloc.dupe(u8, response.json);
        errdefer alloc.free(response_json);
        try ensureRequestDeadline(request_deadline_ns);
        return response_json;
    }

    fn executeSupportedJoinedForeignPublicTableQueryRequest(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        source: table_reads.TableReadSource,
        table_name: []const u8,
        body: []const u8,
        row_filter_json: ?[]const u8,
        foreign_source: foreign_mod.PostgresConfig,
        join: SupportedJoinRequest,
        foreign_sources: foreign_mod.PostgresSourceMap,
        request_deadline_ns: ?u64,
        cancellation: ?*const std.atomic.Value(bool),
    ) anyerror![]u8 {
        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);
        var contract_request = parsePublicTableQueryBody(alloc, body) catch return error.InvalidQueryRequest;
        defer contract_request.deinit();
        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);
        const requested_left_fields = contract_request.value.fields orelse &.{};
        if (contract_request.value.count == true) return error.InvalidQueryRequest;
        const rewrite = try distributed_join.rewriteJoinedBaseQueryBodyAlloc(alloc, contract_request.value, join.left_field);
        const appended_left_field = rewrite.appended_left_field;
        const primary_body = rewrite.body;
        defer alloc.free(primary_body);

        var primary_request = try parsePublicTableQueryBody(alloc, primary_body);
        defer primary_request.deinit();
        if (row_filter_json) |value| {
            try injectRowFilterIntoOpenApiQueryRequest(alloc, &primary_request.value, value);
        }
        const primary_json = try self.encodeForeignPublicTableQueryResponseAlloc(alloc, table_name, primary_request.value, foreign_source, request_deadline_ns, cancellation);
        defer alloc.free(primary_json);

        var owned_response = try parseOwnedJsonValueAlloc(alloc, primary_json);
        defer ApiHttpServer.deinitJsonValue(alloc, &owned_response);
        const hits_ptr = try distributed_join.queryHitsArrayPtr(&owned_response);
        if (hits_ptr.items.len == 0) {
            const empty_response = try alloc.dupe(u8, primary_json);
            errdefer alloc.free(empty_response);
            try ensureRequestActive(cancellation);
            try ensureRequestDeadline(request_deadline_ns);
            return empty_response;
        }

        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);
        const ctx = self.joinContext().withExecutionDeadline(request_deadline_ns).withCancellation(cancellation);
        const plan = try distributed_join.planSupportedJoinExecution(ctx, alloc, table_name, join, hits_ptr.items, foreign_sources);
        var right_result = try distributed_join.executeSupportedRightJoinQueryCoordinatorOnly(ctx, &self.join_job_store, alloc, source, join, hits_ptr.items, plan, foreign_sources);
        defer right_result.deinit(alloc);
        const stats = try distributed_join.applyJoinedRightHitsToResponseWithContext(
            ctx,
            alloc,
            &owned_response,
            hits_ptr.items,
            join,
            right_result.hits,
            requested_left_fields,
            appended_left_field,
        );
        try distributed_join.maybeAttachJoinProfile(alloc, &owned_response, stats, plan, right_result.strategy_used, right_result.distributed_execution, right_result.groups_queried);
        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);
        const response_json = try distributed_join.stringifyJsonValueAlloc(alloc, owned_response);
        errdefer alloc.free(response_json);
        try ensureRequestActive(cancellation);
        try ensureRequestDeadline(request_deadline_ns);
        return response_json;
    }

    fn validateSupportedForeignPublicQueryRequest(request: anytype) !void {
        if (request.full_text_search != null) return error.UnsupportedQueryRequest;
        if (request.semantic_search != null) return error.UnsupportedQueryRequest;
        if (request.embedding_template != null) return error.UnsupportedQueryRequest;
        if (request.indexes != null) return error.UnsupportedQueryRequest;
        if (request.exclusion_query != null) return error.UnsupportedQueryRequest;
        if (request.embeddings != null) return error.UnsupportedQueryRequest;
        if (request.distance_under != null) return error.UnsupportedQueryRequest;
        if (request.distance_over != null) return error.UnsupportedQueryRequest;
        if (request.merge_config != null) return error.UnsupportedQueryRequest;
        if (request.reranker != null) return error.UnsupportedQueryRequest;
        if (request.analyses != null) return error.UnsupportedQueryRequest;
        if (request.graph_searches != null) return error.UnsupportedQueryRequest;
        if (request.expand_strategy != null) return error.UnsupportedQueryRequest;
        if (request.document_renderer != null) return error.UnsupportedQueryRequest;
        if (request.pruner != null) return error.UnsupportedQueryRequest;
        if (request.search_after != null) return error.UnsupportedQueryRequest;
        if (request.search_before != null) return error.UnsupportedQueryRequest;
    }

    fn foreignQueryLimit(limit: ?i64) !?usize {
        const raw = limit orelse 10;
        if (raw <= 0) return 10;
        return std.math.cast(usize, raw) orelse error.InvalidQueryRequest;
    }

    fn foreignQueryOffset(offset: ?i64) !usize {
        const raw = offset orelse 0;
        if (raw < 0) return error.InvalidQueryRequest;
        return std.math.cast(usize, raw) orelse error.InvalidQueryRequest;
    }

    fn cloneForeignSortFieldsAlloc(alloc: std.mem.Allocator, order_by: anytype) ![]foreign_mod.SortField {
        const fields = order_by orelse return &.{};
        if (fields.len == 0) return &.{};

        const out = try alloc.alloc(foreign_mod.SortField, fields.len);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |*item| item.deinit(alloc);
            alloc.free(out);
        }
        for (fields, 0..) |field, idx| {
            out[idx] = .{
                .field = try alloc.dupe(u8, field.field),
                .desc = field.desc orelse false,
            };
            initialized += 1;
        }
        return out;
    }

    fn freeForeignSortFields(alloc: std.mem.Allocator, fields: []foreign_mod.SortField) void {
        for (fields) |*field| field.deinit(alloc);
        if (fields.len > 0) alloc.free(fields);
    }

    fn buildForeignSearchHitsAlloc(
        alloc: std.mem.Allocator,
        foreign_source: foreign_mod.PostgresConfig,
        rows: []const std.json.Value,
        execution_deadline_ns: ?u64,
        cancellation: ?*const std.atomic.Value(bool),
    ) ![]db_mod.types.SearchHit {
        if (rows.len == 0) return &.{};

        const hits = try alloc.alloc(db_mod.types.SearchHit, rows.len);
        var initialized: usize = 0;
        errdefer {
            for (hits[0..initialized]) |*hit| hit.deinit(alloc);
            alloc.free(hits);
        }

        var rows_until_deadline_check: u8 = 1;
        for (rows, 0..) |row, idx| {
            rows_until_deadline_check -|= 1;
            if (rows_until_deadline_check == 0) {
                rows_until_deadline_check = 64;
                try ensureRequestActive(cancellation);
                try ensureRequestDeadline(execution_deadline_ns);
            }
            if (row != .object) return error.InvalidQueryRequest;
            const id = if (try foreign_sources_api.deriveSearchIdAlloc(alloc, foreign_source, row)) |value|
                value
            else
                try std.fmt.allocPrint(alloc, "{d}", .{idx});
            errdefer alloc.free(id);

            const stored_data = try stringifyJsonValueAlloc(alloc, row);
            errdefer alloc.free(stored_data);

            hits[idx] = .{
                .id = id,
                .score = 1,
                .stored_data = stored_data,
            };
            initialized += 1;
        }
        return hits;
    }

    fn executePlainPublicTableQuery(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        source: table_reads.TableReadSource,
        table_name: []const u8,
        body: []const u8,
        row_filter_json: ?[]const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        request_deadline_ns: ?u64,
        query_embedding_security_scope: QueryEmbeddingSecurityScope,
        cancellation: ?*const std.atomic.Value(bool),
    ) !query_api.QueryResponse {
        try ensureRequestActive(cancellation);
        var semantic_resolver = self.semanticStatusResolver(query_embedding_security_scope.domain, query_embedding_security_scope.value);
        semantic_resolver.query_embedding_deadline_ns = request_deadline_ns;
        semantic_resolver.query_cancellation = cancellation;
        var query_req = query_api.parsePublicQueryRequestWithDeadline(
            alloc,
            semantic_resolver.iface(),
            table_name,
            body,
            request_deadline_ns,
        ) catch |err| {
            const normalized = normalizePublicQueryParseError(err);
            if (normalized == error.InvalidQueryRequest or
                normalized == error.InvalidFilterQueryRequest or
                normalized == error.InvalidExclusionQueryRequest or
                normalized == error.UnsupportedFilterQueryRequest or
                normalized == error.UnsupportedExclusionQueryRequest)
            {
                std.log.warn("public table query parse failed table={s} err={}", .{ table_name, err });
            } else {
                std.log.debug("public table query embedding failed table={s} err={}", .{ table_name, normalized });
            }
            return normalized;
        };
        defer query_req.deinit(alloc);
        if (request_deadline_ns) |deadline| {
            query_req.req.execution_deadline_ns = deadline;
            if (retryDeadlineExpired(deadline, platform_time.monotonicNs())) return error.Timeout;
        }
        query_req.req.cancellation = cancellation;
        self.maybeRouteQueryToReadSchema(table_name, &query_req.req) catch |err| switch (err) {
            error.TableNotFound => return error.TableNotFound,
            error.InvalidSchemaUpdateRequest, error.InvalidTableIndexMetadata => return error.InvalidQueryRequest,
            else => return err,
        };
        if (row_filter_json) |value| {
            injectRowFilterIntoSearchRequest(alloc, &query_req.req, value) catch return error.InvalidQueryRequest;
        }
        if (authenticated_identity) |*identity| {
            attachGraphTableReadAuthorizer(&query_req.req, identity);
        }
        return (queryWithTransientReadRetry(
            alloc,
            source,
            table_name,
            query_req.req,
            .read_index,
        ) catch |err| switch (err) {
            // Public filter syntax is validated and attributed during request
            // normalization. A later InvalidArgument can originate from any
            // execution lane, so do not guess based on which optional fields
            // happen to be present.
            error.InvalidArgument => return error.InvalidQueryRequest,
            else => return err,
        }) orelse error.TableNotFound;
    }

    pub fn attachGraphTableReadAuthorizer(
        req: *db_mod.types.SearchRequest,
        identity: *const AuthenticatedIdentity,
    ) void {
        req.graph_table_read_authorizer = .{
            .ctx = identity,
            .authorize_table = authorizeGraphTargetTableRead,
        };
    }

    fn authorizeGraphTargetTableRead(
        ctx: ?*const anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) anyerror!db_mod.types.GraphTableReadAuthorization {
        const identity: *const AuthenticatedIdentity = @ptrCast(@alignCast(ctx orelse {
            return .{ .allowed = false };
        }));
        if (!permissionsAllow(identity.permissions, .table, table_name, .read)) {
            return .{ .allowed = false };
        }
        return .{
            .allowed = true,
            .filter_query_json = try resolveEffectiveRowFilterJson(alloc, identity.*, table_name),
        };
    }

    fn queryWithTransientReadRetry(
        alloc: std.mem.Allocator,
        source: table_reads.TableReadSource,
        table_name: []const u8,
        req: db_mod.types.SearchRequest,
        consistency: raft_mod.ReadConsistency,
    ) !?query_api.QueryResponse {
        const retry_timeout_ns = 5 * std.time.ns_per_s;
        const retry_poll_ns = 25 * std.time.ns_per_ms;
        const start_ns = platform_time.monotonicNs();
        var attempts: u32 = 0;
        while (true) : (attempts += 1) {
            try ensureRequestActive(req.cancellation);
            if (retryDeadlineExpired(req.execution_deadline_ns, platform_time.monotonicNs())) return error.Timeout;
            return source.query(alloc, table_name, req, consistency) catch |err| switch (err) {
                // FileNotFound surfaces when a read-only replica open races
                // with the writer reclaiming obsolete LSM runs; reopening
                // picks up a fresh manifest. TableReadChurn: the read cache
                // gave up opening a table that was being invalidated faster
                // than an open completes.
                error.EndOfStream,
                error.FileNotFound,
                error.TableReadChurn,
                error.IdentityReadGenerationChanged,
                => {
                    if (err == error.IdentityReadGenerationChanged and req.identity_read_generation != null) return err;
                    std.log.warn("public table query read failed table={s} err={} attempt={d}", .{ table_name, err, attempts + 1 });
                    const now_ns = platform_time.monotonicNs();
                    if (retryDeadlineExpired(req.execution_deadline_ns, now_ns)) return error.Timeout;
                    const sleep_ns = boundedRetrySleepNs(req.execution_deadline_ns, now_ns, start_ns, retry_timeout_ns, retry_poll_ns) orelse return err;
                    if (sleep_ns == 0) return error.Timeout;
                    try sleepNsCancellable(sleep_ns, req.cancellation);
                    continue;
                },
                error.Timeout, error.Cancelled => return err,
                else => {
                    std.log.warn("public table query read failed table={s} err={}", .{ table_name, err });
                    return err;
                },
            };
        }
    }

    fn executePlainPublicCatalogTableQuery(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        source: table_reads.TableReadSource,
        target: catalog_resources.TableTarget,
        body: []const u8,
        row_filter_json: ?[]const u8,
        request_deadline_ns: ?u64,
    ) !query_api.QueryResponse {
        var semantic_resolver = SemanticStatusResolver{
            .source = self.source,
            .antfly_provider = self.antfly_provider,
            .remote_content = self.cfg.remote_content,
            .inference_api_key = self.cfg.inference_api_key,
        };
        var query_req = query_api.parsePublicQueryRequest(alloc, semantic_resolver.iface(), target.table_name, body) catch |err| {
            std.log.warn("public catalog table query parse failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
            return error.InvalidQueryRequest;
        };
        defer query_req.deinit(alloc);
        if (request_deadline_ns) |deadline| {
            query_req.req.execution_deadline_ns = deadline;
            if (retryDeadlineExpired(deadline, platform_time.monotonicNs())) return error.Timeout;
        }
        self.maybeRouteCatalogQueryToReadSchema(target, &query_req.req) catch |err| switch (err) {
            error.TableNotFound => return error.TableNotFound,
            error.InvalidSchemaUpdateRequest, error.InvalidTableIndexMetadata => return error.InvalidQueryRequest,
            else => return err,
        };
        if (row_filter_json) |value| {
            injectRowFilterIntoSearchRequest(alloc, &query_req.req, value) catch return error.InvalidQueryRequest;
        }
        return (source.queryCatalog(alloc, target, query_req.req, .read_index) catch |err| {
            std.log.warn("public catalog table query read failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
            return err;
        }) orelse error.TableNotFound;
    }

    fn stringifyJsonValueAlloc(alloc: std.mem.Allocator, value: std.json.Value) ![]u8 {
        return try json_helpers.stringifyJsonValueAlloc(alloc, value);
    }

    fn cloneJsonValue(alloc: std.mem.Allocator, value: std.json.Value) !std.json.Value {
        return try json_helpers.cloneJsonValue(alloc, value);
    }

    fn deinitJsonValue(alloc: std.mem.Allocator, value: *std.json.Value) void {
        json_helpers.deinitJsonValue(alloc, value);
    }

    fn putOwnedJsonField(alloc: std.mem.Allocator, object: *std.json.ObjectMap, key: []const u8, value: std.json.Value) !void {
        try object.put(alloc, try alloc.dupe(u8, key), value);
    }

    fn buildOwnedSearchRequestFromQueryValue(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        query_value: std.json.Value,
        execution_deadline_ns: ?u64,
        cancellation: ?*const std.atomic.Value(bool),
    ) !query_api.OwnedQueryRequest {
        try ensureRequestActive(cancellation);
        const query_body = try stringifyJsonValueAlloc(alloc, query_value);
        defer alloc.free(query_body);
        var semantic_resolver = self.semanticStatusResolver(.internal, "");
        semantic_resolver.query_embedding_deadline_ns = execution_deadline_ns;
        semantic_resolver.query_cancellation = cancellation;
        var owned = try query_api.parsePublicQueryRequestWithDeadline(
            alloc,
            semantic_resolver.iface(),
            table_name,
            query_body,
            execution_deadline_ns,
        );
        errdefer owned.deinit(alloc);
        owned.req.cancellation = cancellation;
        try ensureRequestActive(cancellation);
        try self.maybeRouteQueryToReadSchema(table_name, &owned.req);
        try self.validatePublicQuerySortCapabilities(table_name, owned.req);
        return owned;
    }

    fn executePublicTableQueryView(
        _: *anyopaque,
        _: std.mem.Allocator,
        _: []const u8,
        _: public_table_http.TableApi.TableQueryView,
    ) public_table_http.TableApi.ExecuteQueryViewError![]u8 {
        return error.NotFound;
    }

    fn executePublicTableBackup(
        ptr: *anyopaque,
        _: std.mem.Allocator,
        table_name: []const u8,
        backup_id: []const u8,
        format: backups_api.BackupFormat,
        location_uri: []const u8,
        connection: []const u8,
        location: *backups_api.BackupLocation,
    ) public_table_http.TableApi.ExecuteBackupError!void {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        self.source.ensureLinearizableRead() catch |err| {
            std.log.warn("table backup metadata read barrier failed phase=admission class={s}", .{@errorName(err)});
            return metadataAccessFailure(err);
        };
        var fallback_io: ?std.Io.Threaded = if (self.sharedApiIo() == null)
            std.Io.Threaded.init(std.heap.page_allocator, .{})
        else
            null;
        defer if (fallback_io) |*owned| owned.deinit();
        const io = self.sharedApiIo() orelse fallback_io.?.io();
        self.backupOwnedTable(io, table_name, location, location_uri, backup_id, format, connection) catch |err| switch (err) {
            error.NotLeader,
            error.ProposalDropped,
            error.LeaderTransferInProgress,
            error.MetadataLinearizableReadTimeout,
            error.ReconcileLeaseNotHeld,
            => return error.NotLeader,
            error.BackupAlreadyExists => return error.BackupAlreadyExists,
            error.BackupManifestTooLarge => return error.BackupManifestTooLarge,
            error.TableNotFound => return error.NotFound,
            error.UnsupportedOperation => return error.MethodNotAllowed,
            error.UnsupportedBackupMigrationState => return error.UnsupportedBackupMigrationState,
            error.UnsupportedMultiRangeTable => return error.UnsupportedMultiRangeTable,
            else => {
                if (metadata_authority.isRetryableError(err)) return error.NotLeader;
                std.log.err("table backup failed phase=execution class={s}", .{@errorName(err)});
                return error.InternalFailure;
            },
        };
    }

    fn executePublicTableRestore(
        ptr: *anyopaque,
        _: std.mem.Allocator,
        table_name: []const u8,
        backup_id: []const u8,
        location_uri: []const u8,
        connection: []const u8,
        location: *backups_api.BackupLocation,
    ) public_table_http.TableApi.ExecuteRestoreError!void {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        if (!self.cfg.deployment_mode.isStandalone()) {
            var manifest = backups_api.readManifestFromLocation(self.alloc, location, backup_id) catch |err| switch (err) {
                error.BackupManifestTooLarge => return error.BackupManifestTooLarge,
                else => if (backups_api.isArtifactIntegrityError(err))
                    return error.BackupIntegrityFailure
                else if (err == error.FileNotFound or
                    backups_api.isInvalidBackupManifestError(err))
                    return error.InvalidBackupRequest
                else
                    return error.InternalFailure,
            };
            defer manifest.deinit(self.alloc);
            backups_api.validateRestoreManifest(self.alloc, &manifest, backup_id) catch |err| {
                if (backups_api.isArtifactIntegrityError(err)) return error.BackupIntegrityFailure;
                return error.InvalidBackupRequest;
            };
            self.admitExternalRestoreArtifactIntegrity(
                self.sharedApiIo() orelse return error.InternalFailure,
                location,
                &manifest,
                null,
            ) catch |err| {
                if (backups_api.isArtifactIntegrityError(err)) return error.BackupIntegrityFailure;
                if (backups_api.isInvalidBackupManifestError(err))
                    return error.InvalidBackupRequest;
                return error.InternalFailure;
            };
            if (!std.mem.eql(u8, manifest.table_name, table_name))
                return error.InvalidBackupRequest;

            if (self.restoreMetadataTableWithRetry(self.alloc, table_name, location_uri, connection, backup_id, &manifest) catch |err| switch (err) {
                error.NotLeader, error.ProposalDropped, error.LeaderTransferInProgress => return error.NotLeader,
                error.UnsupportedOperation => false,
                error.InvalidBackupRequest => {
                    if (self.tableExists(table_name) catch |table_exists_err| return metadataAccessFailure(table_exists_err)) return error.TableAlreadyExists;
                    return error.InvalidBackupRequest;
                },
                else => {
                    if (metadata_authority.isRetryableError(err)) return error.NotLeader;
                    return mapExecuteRestoreError(err);
                },
            }) {
                return;
            }
        }

        const outcome = self.restoreOwnedTableWithRetry(table_name, location, location_uri, backup_id) catch |err| switch (err) {
            error.NotLeader, error.ProposalDropped, error.LeaderTransferInProgress => return error.NotLeader,
            error.UnsupportedOperation => return error.MethodNotAllowed,
            error.InvalidBackupRequest => {
                if (self.tableExists(table_name) catch |table_exists_err| return metadataAccessFailure(table_exists_err)) return error.TableAlreadyExists;
                return error.InvalidBackupRequest;
            },
            else => {
                if (metadata_authority.isRetryableError(err)) return error.NotLeader;
                return mapExecuteRestoreError(err);
            },
        };
        if (outcome == .committed_durable) return error.RestoreDurabilityConfirmed;
    }

    fn relationalIndexRepairRecordsForStatus(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        target: catalog_resources.TableTarget,
    ) !?[]table_writes.RelationalIndexRepairJobRecord {
        const source = self.table_writes orelse return null;
        return (source.relationalIndexRepairJobListCatalog(alloc, target) catch |err| switch (err) {
            error.UnsupportedOperation => return null,
            error.TableNotFound => return null,
            error.UnknownGroup => return null,
            error.ReadOnly => return null,
            error.HAReadOnlyStandby => return null,
            error.LsmRootWriterAlreadyOpen => return null,
            else => return err,
        }) orelse null;
    }

    fn mapExecuteRestoreError(err: anyerror) public_table_http.TableApi.ExecuteRestoreError {
        if (backups_api.isArtifactIntegrityError(err)) return error.BackupIntegrityFailure;
        if (metadata_authority.isRetryableError(err)) return error.NotLeader;
        return switch (err) {
            error.TableAlreadyExists => error.TableAlreadyExists,
            error.UnsupportedBackupMigrationState => error.UnsupportedBackupMigrationState,
            error.UnsupportedMultiRangeTable => error.UnsupportedMultiRangeTable,
            error.UnsupportedBackupFormat => error.UnsupportedBackupFormat,
            error.RestoreDurabilityPending, error.GenerationDurabilityUncertain => error.RestoreDurabilityPending,
            error.RestoreDurabilityConfirmed => error.RestoreDurabilityConfirmed,
            error.BackupManifestTooLarge => error.BackupManifestTooLarge,
            error.InvalidBackupRequest => error.InvalidBackupRequest,
            else => error.InternalFailure,
        };
    }

    fn executePublicTableListIndexes(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
    ) public_table_http.TableApi.ExecuteListIndexesError![]u8 {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        var snapshot = (self.statusAdminSnapshot() catch return error.InternalFailure) orelse return error.NotFound;
        defer self.source.freeAdminSnapshot(&snapshot);
        if (tables_api.findTableByName(&snapshot, table_name) == null) return error.NotFound;
        var local_statuses = self.localTableRuntimeStatusesWithSnapshot(table_name, &snapshot) catch return error.InternalFailure;
        defer if (local_statuses) |*status| status.deinit(self.alloc);
        const table = tables_api.findTableByName(&snapshot, table_name) orelse return error.NotFound;
        const target: catalog_resources.TableTarget = .{
            .database_name = table.database_name,
            .namespace_name = table.namespace_name,
            .table_name = table.name,
        };
        const repair_records = self.relationalIndexRepairRecordsForStatus(alloc, target) catch return error.InternalFailure;
        defer if (repair_records) |records| table_writes.freeRelationalIndexRepairJobRecords(alloc, records);
        return indexes_api.encodeIndexListForTableWithRepairRecords(
            alloc,
            &snapshot,
            table,
            if (local_statuses) |*status| status else null,
            repair_records orelse &.{},
        ) catch return error.InternalFailure;
    }

    fn executePublicTableGetIndex(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        index_name: []const u8,
    ) public_table_http.TableApi.ExecuteGetIndexError![]u8 {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        var snapshot = if (self.source.vtable.cached_admin_snapshot != null)
            (self.source.cachedAdminSnapshot() catch return error.InternalFailure) orelse return error.NotFound
        else
            (self.source.adminSnapshot() catch return error.InternalFailure) orelse return error.NotFound;
        defer self.source.freeAdminSnapshot(&snapshot);
        return (try self.encodePublicTableIndexFromSnapshot(alloc, &snapshot, table_name, index_name)) orelse error.NotFound;
    }

    fn encodePublicTableIndexFromSnapshot(
        self: *ApiHttpServer,
        alloc: std.mem.Allocator,
        snapshot: *metadata_api.AdminSnapshot,
        table_name: []const u8,
        index_name: []const u8,
    ) public_table_http.TableApi.ExecuteGetIndexError!?[]u8 {
        const table = tables_api.findTableByName(snapshot, table_name) orelse return null;
        const existence_probe = (indexes_api.encodeSingleIndexForTableWithSnapshotAndRepairRecords(
            alloc,
            snapshot,
            table,
            index_name,
            null,
            &.{},
        ) catch return error.InternalFailure) orelse return null;
        alloc.free(existence_probe);

        var local_statuses = self.localTableRuntimeStatusesWithSnapshot(table_name, snapshot) catch return error.InternalFailure;
        defer if (local_statuses) |*status| status.deinit(self.alloc);
        const target: catalog_resources.TableTarget = .{
            .database_name = table.database_name,
            .namespace_name = table.namespace_name,
            .table_name = table.name,
        };
        const repair_records = self.relationalIndexRepairRecordsForStatus(alloc, target) catch return error.InternalFailure;
        defer if (repair_records) |records| table_writes.freeRelationalIndexRepairJobRecords(alloc, records);
        return (indexes_api.encodeSingleIndexForTableWithSnapshotAndRepairRecords(
            alloc,
            snapshot,
            table,
            index_name,
            if (local_statuses) |*status| status else null,
            repair_records orelse &.{},
        ) catch return error.InternalFailure) orelse null;
    }

    fn executePublicListArtifactEnrichments(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
