    fn executePublicClusterBackup(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        req: backups_api.ClusterBackupRequest,
        location: *backups_api.BackupLocation,
    ) cluster_api_http.ClusterApi.ExecuteBackupError![]u8 {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        const op_alloc = self.alloc;
        var fallback_io: ?std.Io.Threaded = if (self.sharedApiIo() == null)
            std.Io.Threaded.init(std.heap.page_allocator, .{})
        else
            null;
        defer if (fallback_io) |*owned| owned.deinit();
        const backup_io = self.sharedApiIo() orelse fallback_io.?.io();
        var trace: ClusterBackupExecutionTrace = .{};
        errdefer |err| trace.logFailure(err);

        self.source.ensureLinearizableRead() catch |err| {
            if (metadata_authority.isRetryableError(err)) return error.NotLeader;
            std.log.warn("cluster backup metadata read barrier failed err={s}", .{@errorName(err)});
            return trace.internal(err);
        };
        trace.enter(.manifest_probe);
        if (backups_api.clusterManifestExistsAtLocationWithIo(alloc, backup_io, location, req.backup_id) catch |err| return trace.internal(err))
            return error.BackupAlreadyExists;
        const connection = req.connection orelse return error.InvalidRequest;

        trace.enter(.table_selection);
        const table_names: [][]u8 = if (req.table_names) |values|
            cloneTableNamesAlloc(op_alloc, values) catch |err| return trace.internal(err)
        else blk: {
            var snapshot = (self.source.adminSnapshot() catch |err| {
                if (metadataAccessFailure(err) == error.NotLeader)
                    return error.NotLeader;
                return trace.internal(err);
            }) orelse
                break :blk op_alloc.alloc([]u8, 0) catch |err| return trace.internal(err);
            defer self.source.freeAdminSnapshot(&snapshot);
            break :blk tableNamesFromAdminSnapshotAlloc(op_alloc, &snapshot) catch |err| return trace.internal(err);
        };
        defer freeOwnedTableNames(op_alloc, table_names);
        if (table_names.len > restore_jobs.max_cluster_tables_per_job or
            table_names.len > backups_api.max_cluster_backup_attempt_tables)
        {
            return error.InvalidRequest;
        }
        // An aggregate manifest is a restorable commit record. An empty
        // selection has no commit to publish and is rejected before creating
        // any table artifact.
        if (table_names.len == 0) return error.NoTables;
        const statuses = op_alloc.alloc(backups_api.ClusterTableBackupStatus, table_names.len) catch |err|
            return trace.internal(err);
        const status_names = op_alloc.alloc([]u8, table_names.len) catch {
            op_alloc.free(statuses);
            return trace.internal(error.OutOfMemory);
        };
        var status_name_count: usize = 0;
        defer {
            for (status_names[0..status_name_count]) |name| op_alloc.free(name);
            op_alloc.free(status_names);
            op_alloc.free(statuses);
        }
        var cluster_tables = std.ArrayListUnmanaged(backups_api.ClusterTableBackupEntry).empty;
        defer {
            for (cluster_tables.items) |*entry| entry.deinit(op_alloc);
            cluster_tables.deinit(op_alloc);
        }
        trace.enter(.attempt_prepare);
        const attempt_id = self.backupGenerationIdAlloc() catch |err| return trace.internal(err);
        defer op_alloc.free(attempt_id);
        const attempt_tables = op_alloc.alloc(backups_api.ClusterBackupAttemptTable, table_names.len) catch |err|
            return trace.internal(err);
        var initialized_attempt_tables: usize = 0;
        defer {
            for (attempt_tables[0..initialized_attempt_tables]) |table| {
                op_alloc.free(@constCast(table.table_backup_id));
                op_alloc.free(@constCast(table.artifact_backup_id));
            }
            op_alloc.free(attempt_tables);
        }
        for (table_names, 0..) |table_name, i| {
            const table_backup_id = std.fmt.allocPrint(op_alloc, "{s}-t-{d}", .{
                attempt_id,
                i,
            }) catch |err| return trace.internal(err);
            errdefer op_alloc.free(table_backup_id);
            const artifact_backup_id = std.fmt.allocPrint(op_alloc, "{s}-a-{d}", .{
                attempt_id,
                i,
            }) catch |err| return trace.internal(err);
            errdefer op_alloc.free(artifact_backup_id);
            attempt_tables[i] = .{
                .name = table_name,
                .table_backup_id = table_backup_id,
                .artifact_backup_id = artifact_backup_id,
            };
            initialized_attempt_tables += 1;
        }
        const now_unix_ns: u64 = @intCast(std.Io.Timestamp.now(backup_io, .real).toNanoseconds());
        const attempt_marker: backups_api.ClusterBackupAttemptMarker = .{
            .attempt_id = attempt_id,
            .cluster_backup_id = req.backup_id,
            .created_at_unix_ns = now_unix_ns,
            .format = req.format,
            .tables = attempt_tables,
        };
        // Publish the immutable journal before acquiring the admission fence.
        // This ordering guarantees that a process crash can never leave an
        // undiscoverable reservation: every production reservation has an
        // attempt marker that the bounded stale reclaimer can later retire.
        trace.enter(.attempt_marker);
        backups_api.writeClusterBackupAttemptMarker(
            op_alloc,
            backup_io,
            location,
            &attempt_marker,
        ) catch |err| return trace.internal(err);
        // Admission must establish the durable journal before this repository
        // becomes visible to asynchronous maintenance. On a new filesystem
        // repository, scheduling first lets the reclaimer and publisher race
        // while creating the control tree. Existing repositories remain safe
        // because marker and reclamation operations use the same per-attempt
        // publication lock.
        trace.enter(.maintenance_schedule);
        self.scheduleClusterBackupMaintenance(req.location, connection) catch |err| {
            if (err == error.BackupMaintenanceQueueFull) {
                backups_api.deleteClusterBackupAttemptMarker(
                    op_alloc,
                    backup_io,
                    location,
                    &attempt_marker,
                ) catch |cleanup_err| return trace.internal(cleanup_err);
                return error.BackupRepositoryBusy;
            }
            // Exact same-ID lease recovery remains available if opportunistic
            // global cleanup cannot be queued.
            std.log.warn("cluster backup stale-attempt maintenance scheduling deferred class={s}", .{@errorName(err)});
        };
        // The repository lease is the authoritative pre-execution conflict
        // check. One exact expired-owner recovery is bounded independently of
        // repository size; a live operation reports contention explicitly.
        trace.enter(.mutation_lease);
        acquireClusterBackupMutationLease(
            op_alloc,
            backup_io,
            location,
            req.backup_id,
            attempt_id,
        ) catch |err| switch (err) {
            error.BackupRepositoryBusy => {
                backups_api.deleteClusterBackupAttemptMarker(
                    op_alloc,
                    backup_io,
                    location,
                    &attempt_marker,
                ) catch |cleanup_err| {
                    std.log.warn("cluster backup duplicate marker cleanup deferred phase=admission class={s}", .{@errorName(cleanup_err)});
                };
                return error.BackupRepositoryBusy;
            },
            // An unknown conditional-write outcome may have acquired the
            // reservation. Retain the marker so recovery can resolve it.
            else => return trace.internal(err),
        };
        var cluster_committed = false;
        var cluster_cleanup_safe = true;
        errdefer if (!cluster_committed) {
            if (cluster_cleanup_safe) {
                self.cleanupClusterBackupAttempt(
                    backup_io,
                    location,
                    &attempt_marker,
                ) catch |cleanup_err| {
                    std.log.err("cluster backup cleanup failed phase=rollback class={s}", .{@errorName(cleanup_err)});
                };
            } else {
                std.log.err("cluster backup publication outcome ambiguous phase=commit; retaining fenced attempt", .{});
            }
        };
        // Publishing the head is the attempt-start linearization point. It is
        // deliberately after exclusive admission but before table artifacts:
        // rejected contenders never perturb global health ordering, while
        // every attempt that can produce side effects is visible to restore.
        // Cleanup conditionally retires an ambiguous or failed publication.
        trace.enter(.attempt_head);
        backups_api.writeClusterBackupAttemptHead(
            op_alloc,
            backup_io,
            location,
            attempt_id,
        ) catch |err| return trace.internal(err);
        const initial_lease_expiration =
            @as(u64, @intCast(std.Io.Timestamp.now(backup_io, .real).toNanoseconds())) +|
            backups_api.backup_attempt_lease_duration_ns;
        var lease_heartbeat: ClusterBackupMutationLeaseHeartbeat = .{
            .alloc = op_alloc,
            .io = backup_io,
            .location = location,
            .backup_id = req.backup_id,
            .attempt_id = attempt_id,
            .expires_at_unix_ns = .init(initial_lease_expiration),
        };
        // Refresh once synchronously so the tracked expiration exactly matches
        // the stored lease, then keep it alive across long shard snapshots.
        trace.enter(.lease_heartbeat);
        lease_heartbeat.ensureOwned() catch |err| return trace.internal(err);
        var lease_future = std.Io.async(
            backup_io,
            ClusterBackupMutationLeaseHeartbeat.run,
            .{&lease_heartbeat},
        );
        var lease_future_running = true;
        defer if (lease_future_running) {
            lease_heartbeat.stop_event.set(backup_io);
            lease_future.await(backup_io);
        };
        var extension_snapshot_opt = self.source.adminSnapshot() catch |err| switch (err) {
            error.NotLeader, error.ProposalDropped, error.LeaderTransferInProgress => return error.NotLeader,
            else => if (metadata_authority.isRetryableError(err)) return error.NotLeader else null,
        };
        defer if (extension_snapshot_opt) |*snapshot| self.source.freeAdminSnapshot(snapshot);
        const extension_snapshot: ?*const metadata_api.AdminSnapshot = if (extension_snapshot_opt) |*snapshot| snapshot else null;

        trace.enter(.table_snapshots);
        for (table_names, attempt_tables, 0..) |table_name, attempt_table, i| {
            if (lease_heartbeat.lost.load(.acquire))
                return trace.internal(error.BackupAttemptLeaseLost);
            const status_name = op_alloc.dupe(u8, table_name) catch |err| return trace.internal(err);
            status_names[status_name_count] = status_name;
            status_name_count += 1;
            statuses[i] = .{ .name = status_name, .status = "failed", .@"error" = null };

            self.backupOwnedTableWithArtifactId(
                backup_io,
                table_name,
                location,
                req.location,
                attempt_table.table_backup_id,
                attempt_table.artifact_backup_id,
                req.format,
                connection,
            ) catch |err| {
                statuses[i].@"error" = switch (err) {
                    // Once table execution begins, the request may already have
                    // published artifacts for an earlier table. Never return
                    // the retry-marked 503 from this phase: replaying the POST
                    // would duplicate side effects. Return a sanitized
                    // per-table outcome without publishing an incomplete
                    // aggregate manifest. After cleanup completes, the caller
                    // can safely retry the same backup id.
                    error.NotLeader,
                    error.ProposalDropped,
                    error.LeaderTransferInProgress,
                    error.MetadataLinearizableReadTimeout,
                    error.ReconcileLeaseNotHeld,
                    => "metadata leader unavailable",
                    error.TableNotFound => "not found",
                    error.UnsupportedOperation => "method not allowed",
                    error.UnsupportedMultiRangeTable => "backup does not support multi-range tables",
                    error.UnsupportedBackupMigrationState => "backup does not support active schema migration",
                    error.BackupManifestTooLarge => backups_api.manifest_too_large_message,
                    else => blk: {
                        std.log.warn("cluster backup table snapshot failed table={s} class={s}", .{
                            table_name,
                            @errorName(err),
                        });
                        break :blk "backup failed";
                    },
                };
                continue;
            };
            statuses[i].status = "completed";
            var entry_name_owned: ?[]u8 = op_alloc.dupe(u8, table_name) catch {
                return trace.internal(error.OutOfMemory);
            };
            var table_backup_id_owned: ?[]u8 = op_alloc.dupe(u8, attempt_table.table_backup_id) catch |err|
                return trace.internal(err);
            errdefer if (entry_name_owned) |entry_name| op_alloc.free(entry_name);
            errdefer if (table_backup_id_owned) |owned_backup_id| op_alloc.free(owned_backup_id);
            cluster_tables.append(op_alloc, .{
                .name = entry_name_owned.?,
                .table_backup_id = table_backup_id_owned.?,
            }) catch |err| return trace.internal(err);
            entry_name_owned = null;
            table_backup_id_owned = null;
        }

        // Per-table manifests and payloads must be durable before this final
        // publication. If any requested table failed, return its sanitized
        // status without exposing a partial aggregate as a restore candidate.
        if (cluster_tables.items.len == table_names.len) {
            trace.enter(.aggregate_publish);
            // Close the last renewal/publication race. If another process took
            // an expired lease, this conditional renewal fences publication.
            lease_heartbeat.ensureOwned() catch |err| return trace.internal(err);
            const installed_extensions = if (extension_snapshot) |snapshot| snapshot.installed_extensions else &.{};
            const extension_members = if (extension_snapshot) |snapshot| snapshot.extension_members else &.{};
            const extension_dependencies = if (extension_snapshot) |snapshot| snapshot.extension_dependencies else &.{};
            var manifest = backups_api.createClusterManifestWithExtensions(
                op_alloc,
                req.backup_id,
                req.location,
                cluster_tables.items,
                installed_extensions,
                extension_members,
                extension_dependencies,
            ) catch |err| return trace.internal(err);
            defer manifest.deinit(op_alloc);
            cluster_cleanup_safe = false;
            backups_api.writeClusterManifestToLocationWithIo(op_alloc, backup_io, location, &manifest) catch |err| {
                cluster_cleanup_safe = switch (err) {
                    error.BackupAlreadyExists, error.BackupManifestTooLarge => true,
                    else => false,
                };
                return switch (err) {
                    error.BackupAlreadyExists => error.BackupAlreadyExists,
                    error.BackupManifestTooLarge => error.BackupManifestTooLarge,
                    else => trace.internal(err),
                };
            };
            if (!(backups_api.commitClusterBackupAttemptHeadIfOwned(
                op_alloc,
                backup_io,
                location,
                attempt_id,
            ) catch |err| blk: {
                // The immutable aggregate above is the commit point. Preserve
                // success after an ambiguous terminal-head update: active-head
                // admission validates the same marker, manifest, and artifact
                // identities and maintenance never treats a present commit as
                // an unpublished attempt.
                std.log.warn("cluster backup committed head update deferred class={s}", .{@errorName(err)});
                break :blk false;
            })) {
                std.log.warn("cluster backup committed with superseded attempt head", .{});
            }
            // The immutable aggregate is now the commit record. Stop renewal
            // before conditionally releasing the repository-global mutation
            // lease; a cleanup failure is safe because the lease expires and
            // exact recovery recognizes the committed marker.
            lease_heartbeat.stop_event.set(backup_io);
            lease_future.await(backup_io);
            lease_future_running = false;
            if (!(backups_api.cleanupClusterReservationIfOwnedAtLocation(
                op_alloc,
                backup_io,
                location,
                req.backup_id,
                attempt_id,
            ) catch |err| blk: {
                std.log.warn("cluster backup committed lease release deferred class={s}", .{@errorName(err)});
                break :blk false;
            })) {
                std.log.warn("cluster backup committed with lease already fenced", .{});
            }
            cluster_committed = true;
        } else {
            trace.enter(.partial_cleanup);
            // A partial aggregate is not a restore candidate. Reclaim every
            // completed table attempt before releasing the cluster reservation
            // so a retry cannot overlap cleanup.
            lease_heartbeat.stop_event.set(backup_io);
            lease_future.await(backup_io);
            lease_future_running = false;
            self.cleanupClusterBackupAttempt(backup_io, location, &attempt_marker) catch |err|
                return trace.internal(err);
            cluster_committed = true;
        }

        trace.enter(.response_encode);
        return backups_api.encodeClusterBackupResponse(alloc, req.backup_id, statuses) catch |err|
            return trace.internal(err);
    }

    fn executePublicClusterRestore(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        req: backups_api.ClusterRestoreRequest,
        location: *backups_api.BackupLocation,
        restore_mode: []const u8,
    ) cluster_api_http.ClusterApi.ExecuteRestoreError!cluster_api_http.ClusterApi.RestoreExecution {
        return .{
            .status = 200,
            .body = try executePublicClusterRestoreWithCancellation(ptr, alloc, req, location, restore_mode, null, null, &.{}, &.{}),
        };
    }

    const RestoreCancellation = struct { job_id: u64, attempt_id: u64 };

    fn mapClusterRestoreRepositoryError(
        err: anyerror,
    ) cluster_api_http.ClusterApi.ExecuteRestoreError {
        if (err == error.BackupRepositoryBusy)
            return error.BackupRepositoryBusy;
        if (err == error.BackupManifestTooLarge)
            return error.BackupManifestTooLarge;
        if (backups_api.isArtifactIntegrityError(err))
            return error.BackupIntegrityFailure;
        if (err == error.FileNotFound or
            backups_api.isInvalidBackupManifestError(err))
            return error.InvalidRequest;
        // Repository contention, allocation failures, credential refresh, and
        // storage transport errors are server-side availability failures. A
        // 400 would incorrectly make them permanent and suppress safe retries.
        return error.InternalFailure;
    }

    fn executePublicClusterRestoreWithCancellation(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        req: backups_api.ClusterRestoreRequest,
        location: *backups_api.BackupLocation,
        restore_mode: []const u8,
        cancellation: ?RestoreCancellation,
        active_table_index: ?u16,
        durability_pending_table_ranges: []const restore_jobs.TableIndexRange,
        published_table_ranges: []const restore_jobs.TableIndexRange,
    ) cluster_api_http.ClusterApi.ExecuteRestoreError![]u8 {
        const self: *ApiHttpServer = @ptrCast(@alignCast(ptr));
        const op_alloc = self.alloc;
        const restore_connection = req.connection orelse return error.InvalidRequest;
        if (restore_connection.len == 0 or restore_connection.len > 256) return error.InvalidRequest;
        const restore_io = self.sharedApiIo() orelse return error.InternalFailure;

        try self.ensureRestoreActive(cancellation);

        // Restore treats the backup repository as immutable input. Every
        // selected manifest and artifact is size-bounded and integrity-checked
        // before publication, so unrelated backup writers cannot invalidate
        // the read. Keeping coordination in Antfly's durable restore job state
        // preserves restore.read least privilege and supports read-only/WORM
        // archives instead of writing lease sidecars into the source.
        var verification_cache: backups_api.ArtifactVerificationCache = .{};
        defer verification_cache.deinit(op_alloc);
        var manifest = backups_api.readClusterManifestForRestoreAdmissionWithCache(
            op_alloc,
            restore_io,
            location,
            req.backup_id,
            &verification_cache,
        ) catch |err| {
            const mapped = mapClusterRestoreRepositoryError(err);
            if (mapped == error.InternalFailure) {
                std.log.err(
                    "cluster restore admission failed phase=repository class={s}",
                    .{@errorName(err)},
                );
            }
            return mapped;
        };
        defer manifest.deinit(op_alloc);

        preflightClusterRestoreExtensions(self, &manifest) catch |err| switch (err) {
            error.NotLeader, error.ProposalDropped, error.LeaderTransferInProgress => return error.NotLeader,
            else => {
                if (metadata_authority.isRetryableError(err)) return error.NotLeader;
                return error.InvalidRequest;
            },
        };

        var owned_table_names: ?[][]u8 = null;
        defer if (owned_table_names) |names| freeOwnedTableNames(op_alloc, names);
        const table_names: []const []const u8 = if (req.table_names) |values|
            values
        else blk: {
            const names = tableNamesFromClusterManifestAlloc(op_alloc, &manifest) catch return error.InternalFailure;
            owned_table_names = names;
            break :blk names;
        };
        if (table_names.len > restore_jobs.max_cluster_tables_per_job) return error.InvalidRequest;

        if (std.mem.eql(u8, restore_mode, "fail_if_exists")) {
            for (table_names, 0..) |table_name, table_index| {
                if (restoreTableAttempted(active_table_index, durability_pending_table_ranges, published_table_ranges, @intCast(table_index))) continue;
                try self.ensureRestoreActive(cancellation);
                if (self.tableExists(table_name) catch |err| return metadataAccessFailure(err)) {
                    return error.TableAlreadyExists;
                }
            }
        }

        const statuses = op_alloc.alloc(backups_api.ClusterTableRestoreStatus, table_names.len) catch return error.InternalFailure;
        const status_names = op_alloc.alloc([]u8, table_names.len) catch {
            op_alloc.free(statuses);
            return error.InternalFailure;
        };
        var status_name_count: usize = 0;
        defer {
            for (status_names[0..status_name_count]) |name| op_alloc.free(name);
            op_alloc.free(status_names);
            op_alloc.free(statuses);
        }
        for (table_names, 0..) |table_name, i| {
            const status_name = op_alloc.dupe(u8, table_name) catch return error.InternalFailure;
            status_names[status_name_count] = status_name;
            status_name_count += 1;
            statuses[i] = .{ .name = status_name, .status = "failed", .@"error" = null };

            if (backups_api.findClusterTable(&manifest, table_name) == null) {
                statuses[i].@"error" = "backup does not include table";
                continue;
            }

            const exists = self.tableExists(table_name) catch |err| return metadataAccessFailure(err);
            const started = restoreTableAttempted(active_table_index, durability_pending_table_ranges, published_table_ranges, @intCast(i));
            const published = restore_jobs.containsTableIndex(published_table_ranges, @intCast(i));
            if (!started and !published and std.mem.eql(u8, restore_mode, "skip_if_exists") and exists) {
                statuses[i].status = "skipped";
                continue;
            }
        }

        const is_overwrite = std.mem.eql(u8, restore_mode, "overwrite");
        for (table_names, 0..) |table_name, i| {
            try self.ensureRestoreActive(cancellation);
            if (statuses[i].@"error" != null or std.mem.eql(u8, statuses[i].status, "skipped")) continue;

            const cluster_table = backups_api.findClusterTable(&manifest, table_name).?;
            const table_backup_id = cluster_table.table_backup_id;
            const artifact_backup_id = cluster_table.artifact_backup_id orelse table_backup_id;

            // published_table_ranges is a durable publication checkpoint. On a
            // resumed attempt, do not republish or reject the table merely
            // because it now exists; wait for the already-published replica
            // restore intent to drain instead.
            if (restore_jobs.containsTableIndex(published_table_ranges, @intCast(i))) {
                if (!self.cfg.deployment_mode.isStandalone()) {
                    self.waitForDistributedRestoreCompletion(table_name, req.location, table_backup_id, artifact_backup_id, cancellation) catch |err| switch (err) {
                        error.NotLeader => return error.NotLeader,
                        error.Cancelled => return error.Cancelled,
                        else => {
                            std.log.err("cluster restore completion wait failed phase=distributed class={s}", .{@errorName(err)});
                            return error.InternalFailure;
                        },
                    };
                }
                self.checkpointRestoreTableCompleted(cancellation, @intCast(i)) catch |err| {
                    if (err == error.RestoreJobFenced or metadata_authority.isRetryableError(err)) return error.NotLeader;
                    return error.InternalFailure;
                };
                statuses[i].status = "committed";
                continue;
            }

            if (!restoreTableAttempted(active_table_index, durability_pending_table_ranges, published_table_ranges, @intCast(i))) {
                self.checkpointRestoreTableStarted(cancellation, @intCast(i)) catch |err| {
                    if (err == error.RestoreJobFenced or metadata_authority.isRetryableError(err)) return error.NotLeader;
                    return error.InternalFailure;
                };
            }

            // Overwrite publication is local and generation-aware. New-table
            // restores may delegate to metadata in distributed deployments.
            if (!is_overwrite and !self.cfg.deployment_mode.isStandalone()) {
                var table_manifest = backups_api.readManifestFromLocationWithArtifactBackupId(
                    op_alloc,
                    location,
                    table_backup_id,
                    artifact_backup_id,
                ) catch |err| {
                    switch (mapClusterRestoreRepositoryError(err)) {
                        error.BackupManifestTooLarge => return error.BackupManifestTooLarge,
                        error.InternalFailure => {
                            std.log.err(
                                "cluster restore manifest read failed phase=table class={s}",
                                .{@errorName(err)},
                            );
                            return error.InternalFailure;
                        },
                        error.BackupIntegrityFailure => {
                            statuses[i].@"error" = backups_api.integrity_failure_message;
                            continue;
                        },
                        error.InvalidRequest => {
                            statuses[i].@"error" = "invalid table backup manifest";
                            continue;
                        },
                        else => unreachable,
                    }
                };
                defer table_manifest.deinit(op_alloc);
                if (!std.mem.eql(u8, table_manifest.table_name, table_name)) {
                    statuses[i].@"error" = "table backup manifest does not match table";
                    continue;
                }
                self.admitExternalRestoreArtifactIntegrity(
                    restore_io,
                    location,
                    &table_manifest,
                    &verification_cache,
                ) catch |err| {
                    switch (mapClusterRestoreRepositoryError(err)) {
                        error.BackupManifestTooLarge => return error.BackupManifestTooLarge,
                        error.InternalFailure => {
                            std.log.err(
                                "cluster restore integrity admission failed phase=table class={s}",
                                .{@errorName(err)},
                            );
                            return error.InternalFailure;
                        },
                        error.BackupIntegrityFailure => {
                            statuses[i].@"error" = backups_api.integrity_failure_message;
                            continue;
                        },
                        error.InvalidRequest => {
                            statuses[i].@"error" = "unable to bind portable backup artifact integrity";
                            continue;
                        },
                        else => unreachable,
                    }
                };

                const restored_via_metadata = self.restoreMetadataTableWithRetry(
                    alloc,
                    table_name,
                    req.location,
                    restore_connection,
                    artifact_backup_id,
                    &table_manifest,
                ) catch |err| switch (err) {
                    error.NotLeader, error.ProposalDropped, error.LeaderTransferInProgress => return error.NotLeader,
                    error.UnsupportedOperation => false,
                    else => {
                        if (metadata_authority.isRetryableError(err)) return error.NotLeader;
                        self.checkpointRestoreTableAborted(cancellation, @intCast(i)) catch |checkpoint_err| {
                            if (checkpoint_err == error.RestoreJobFenced or metadata_authority.isRetryableError(checkpoint_err)) return error.NotLeader;
                            return error.InternalFailure;
                        };
                        std.log.err("cluster restore failed phase=metadata class={s}", .{@errorName(err)});
                        statuses[i].@"error" = switch (err) {
                            error.UnsupportedBackupFormat => "restore does not support this backup layout",
                            error.UnsupportedMultiRangeTable => "restore does not support multi-range tables",
                            error.UnsupportedBackupMigrationState => "restore does not support active schema migration",
                            error.TableAlreadyExists => "table already exists",
                            error.TableNotFound => "not found",
                            error.InvalidBackupRequest => "invalid restore request",
                            error.BackupManifestTooLarge => backups_api.manifest_too_large_message,
                            else => if (backups_api.isArtifactIntegrityError(err))
                                backups_api.integrity_failure_message
                            else
                                return error.InternalFailure,
                        };
                        continue;
                    },
                };
                if (restored_via_metadata) {
                    self.checkpointRestoreTablePublished(cancellation, @intCast(i)) catch |err| {
                        if (err == error.RestoreJobFenced or metadata_authority.isRetryableError(err)) return error.NotLeader;
                        return error.InternalFailure;
                    };
                    self.waitForDistributedRestoreCompletion(table_name, req.location, table_backup_id, artifact_backup_id, cancellation) catch |err| switch (err) {
                        error.NotLeader => return error.NotLeader,
                        error.Cancelled => return error.Cancelled,
                        else => {
                            std.log.err("cluster restore completion wait failed phase=distributed class={s}", .{@errorName(err)});
                            return error.InternalFailure;
                        },
                    };
                    self.checkpointRestoreTableCompleted(cancellation, @intCast(i)) catch |err| {
                        if (err == error.RestoreJobFenced or metadata_authority.isRetryableError(err)) return error.NotLeader;
                        return error.InternalFailure;
                    };
                    statuses[i].status = "committed";
                    continue;
                }
            }

            const replace_existing = is_overwrite and (self.tableExists(table_name) catch |err| return metadataAccessFailure(err));
            const outcome = self.restoreOwnedTableWithRetryAndLifecycle(table_name, location, req.location, table_backup_id, artifact_backup_id, false, replace_existing, &verification_cache) catch |err| {
                if (metadata_authority.isRetryableError(err)) return error.NotLeader;
                std.log.err("cluster restore failed phase=materialization class={s}", .{@errorName(err)});
                statuses[i].@"error" = switch (err) {
                    error.UnsupportedOperation => "method not allowed",
                    error.UnsupportedBackupFormat => "restore does not support this backup layout",
                    error.UnsupportedMultiRangeTable => "restore does not support multi-range tables",
                    error.UnsupportedBackupMigrationState => "restore does not support active schema migration",
                    error.RestoreDurabilityPending, error.GenerationDurabilityUncertain => null,
                    error.TableAlreadyExists => "table already exists",
                    error.TableNotFound => "not found",
                    error.InvalidBackupRequest => "invalid restore request",
                    error.BackupManifestTooLarge => backups_api.manifest_too_large_message,
                    else => if (backups_api.isArtifactIntegrityError(err))
                        backups_api.integrity_failure_message
                    else
                        return error.InternalFailure,
                };
                if (err == error.RestoreDurabilityPending or err == error.GenerationDurabilityUncertain) {
                    self.checkpointRestoreTableDurabilityPending(cancellation, @intCast(i)) catch |checkpoint_err| {
                        if (checkpoint_err == error.RestoreJobFenced or metadata_authority.isRetryableError(checkpoint_err)) return error.NotLeader;
                        return error.InternalFailure;
                    };
                    statuses[i].status = "durability_pending";
                } else {
                    self.checkpointRestoreTableAborted(cancellation, @intCast(i)) catch |checkpoint_err| {
                        if (checkpoint_err == error.RestoreJobFenced or metadata_authority.isRetryableError(checkpoint_err)) return error.NotLeader;
                        return error.InternalFailure;
                    };
                }
                continue;
            };
            statuses[i].status = switch (outcome) {
                .committed_durable => "committed",
            };
            self.checkpointRestoreTablePublished(cancellation, @intCast(i)) catch |err| {
                if (err == error.RestoreJobFenced or metadata_authority.isRetryableError(err)) return error.NotLeader;
                return error.InternalFailure;
            };
            self.checkpointRestoreTableCompleted(cancellation, @intCast(i)) catch |err| {
                if (err == error.RestoreJobFenced or metadata_authority.isRetryableError(err)) return error.NotLeader;
                return error.InternalFailure;
            };
        }

        if (req.table_names == null and clusterRestoreStatusesComplete(statuses)) {
            try self.ensureRestoreActive(cancellation);
            self.source.restoreExtensions(
                alloc,
                manifest.installed_extensions,
                manifest.extension_members,
                manifest.extension_dependencies,
            ) catch |err| switch (err) {
                error.NotLeader, error.ProposalDropped, error.LeaderTransferInProgress => return error.NotLeader,
                error.UnsupportedOperation => {},
                else => {
                    if (metadata_authority.isRetryableError(err)) return error.NotLeader;
                    std.log.err("cluster restore extension metadata restore failed err={}", .{err});
                    return error.InternalFailure;
                },
            };
        }

        return backups_api.encodeClusterRestoreResponse(alloc, statuses) catch return error.InternalFailure;
    }

    fn checkpointRestoreTablePublished(self: *ApiHttpServer, cancellation: ?RestoreCancellation, table_index: u16) !void {
        const token = cancellation orelse return;
        const encoded = try self.restore_job_store.recordTablePublished(self.alloc, token.job_id, token.attempt_id, table_index);
        self.alloc.free(encoded);
    }

    fn checkpointRestoreTableStarted(self: *ApiHttpServer, cancellation: ?RestoreCancellation, table_index: u16) !void {
        const token = cancellation orelse return;
        const encoded = try self.restore_job_store.recordTableStarted(self.alloc, token.job_id, token.attempt_id, table_index);
        self.alloc.free(encoded);
    }

    fn checkpointRestoreTableDurabilityPending(self: *ApiHttpServer, cancellation: ?RestoreCancellation, table_index: u16) !void {
        const token = cancellation orelse return;
        const encoded = try self.restore_job_store.recordTableDurabilityPending(self.alloc, token.job_id, token.attempt_id, table_index);
        self.alloc.free(encoded);
    }

    fn checkpointRestoreTableAborted(self: *ApiHttpServer, cancellation: ?RestoreCancellation, table_index: u16) !void {
        const token = cancellation orelse return;
        const encoded = try self.restore_job_store.recordTableAborted(self.alloc, token.job_id, token.attempt_id, table_index);
        self.alloc.free(encoded);
    }

    fn checkpointRestoreTableCompleted(self: *ApiHttpServer, cancellation: ?RestoreCancellation, table_index: u16) !void {
        const token = cancellation orelse return;
        const encoded = try self.restore_job_store.recordTableCompleted(self.alloc, token.job_id, token.attempt_id, table_index);
        self.alloc.free(encoded);
    }

    fn ensureRestoreActive(self: *ApiHttpServer, cancellation: ?RestoreCancellation) error{ NotLeader, Cancelled, InternalFailure }!void {
        if (!self.restoreExecutionPermitted()) return error.NotLeader;
        const token = cancellation orelse return;
        const attempt_state = self.restore_job_store.attemptState(self.alloc, token.job_id, token.attempt_id) catch
            return error.InternalFailure;
        switch (attempt_state) {
            .active => {},
            .cancelled => return error.Cancelled,
            .fenced => return error.NotLeader,
        }
    }

    fn restoreExecutionPermitted(self: *ApiHttpServer) bool {
        if (self.restore_dispatch_paused.load(.acquire)) return false;
        const guard = self.cfg.restore_execution_guard orelse return true;
        const term = self.restore_leadership_term.load(.acquire);
        return term != 0 and guard.is_current(guard.ptr, term);
    }

    pub fn handlePublicTableBatch(self: *ApiHttpServer, table_name: []const u8, body: []const u8) !http_common.HttpResponse {
        var resp = try public_table_http.handleTableBatch(self.alloc, table_name, body, self.tableApi());
        defer resp.deinit(self.alloc);
        var response = switch (resp.status) {
            201 => blk: {
                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const parsed = try parseJsonResponseBody(metadata_openapi.BatchResponse, arena_impl.allocator(), resp.body);
                break :blk try jsonResponseWithStatus(self.alloc, 201, parsed);
            },
            else => if (resp.json)
                try jsonBodyResponseWithStatus(self.alloc, resp.status, resp.body)
            else
                try textResponse(self.alloc, resp.status, resp.body),
        };
        if (resp.retry_after_seconds) |seconds| {
            response.headers = try self.alloc.alloc(http_common.Header, 1);
            errdefer {
                self.alloc.free(response.headers);
                response.headers = &.{};
                response.deinit(self.alloc);
            }
            const value = try std.fmt.allocPrint(self.alloc, "{d}", .{seconds});
            defer self.alloc.free(value);
            response.headers[0] = try ownedHeader(self.alloc, "Retry-After", value);
        }
        return response;
    }

    pub fn handlePublicCatalogTableBatch(self: *ApiHttpServer, target: catalog_resources.TableTarget, body: []const u8) !http_common.HttpResponse {
        var batch_req = batch_api.parseBatchRequest(self.alloc, body) catch |err| switch (err) {
            error.ValueTooLong => return try textResponse(self.alloc, 413, "value too large"),
            else => return err,
        };
        defer batch_req.deinit(self.alloc);
        const source = self.table_writes orelse return try textResponse(self.alloc, 404, "not found");
        self.validateCatalogTableWritesAgainstSchema(target, batch_req.req.writes) catch |err| switch (err) {
            error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return try textResponse(self.alloc, 400, "invalid batch request"),
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            else => {
                std.log.err("public catalog table batch schema validation failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                return try textResponse(self.alloc, 500, "batch failed");
            },
        };
        _ = (source.batchCatalog(self.alloc, target, batch_req.req) catch |err| switch (err) {
            error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return try textResponse(self.alloc, 400, "invalid batch request"),
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.LeaderUnavailable, error.WriteUnavailable => return try textResponse(self.alloc, 503, "write unavailable"),
            error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "doc identity unavailable"),
            error.EnrichmentRetryInProgress => return try textResponse(self.alloc, 429, "table backpressured"),
            else => {
                std.log.err("public catalog table batch failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                return try textResponse(self.alloc, 500, "batch failed");
            },
        }) orelse return try textResponse(self.alloc, 404, "not found");

        const response_body = try batch_api.encodeBatchResponse(self.alloc, batch_req.result());
        defer self.alloc.free(response_body);
        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_impl.deinit();
        const parsed = try parseJsonResponseBody(metadata_openapi.BatchResponse, arena_impl.allocator(), response_body);
        return try jsonResponseWithStatus(self.alloc, 201, parsed);
    }

    pub fn handlePublicTableRowsBatch(
        self: *ApiHttpServer,
        table_name: []const u8,
        body: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !http_common.HttpResponse {
        const source = self.table_writes orelse return try textResponse(self.alloc, 404, "not found");
        const schema = self.runtimeSchemaForPublicRows(table_name) catch |err| switch (err) {
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.InvalidRowsRequest => return try textResponse(self.alloc, 400, "invalid rows request"),
            else => return err,
        };
        defer runtime_schema_mod.freeSchema(self.alloc, schema);

        var unique_resolver_ctx = RowsUniqueSelectorResolverContext{ .source = self.table_reads };
        const unique_resolver = unique_resolver_ctx.resolver();
        const triggered_body = (try self.rowsBatchBodyAfterBeforeTriggersAlloc(table_name, body, schema, unique_resolver)) orelse body;
        defer if (triggered_body.ptr != body.ptr) self.alloc.free(triggered_body);

        var sequence_resolver_ctx = RowsSequenceDefaultResolverContext{ .source = self.source };
        const default_read_source = self.effectivePublicTableReads() orelse return try textResponse(self.alloc, 404, "not found");
        var scalar_default_resolver_ctx = RowsScalarSubqueryDefaultResolverContext{ .source = self.source, .table_reads = default_read_source };
        var rows_req = relational_rows_api.parseRowsBatchRequestWithResolverAndDefaultContext(self.alloc, table_name, triggered_body, schema, unique_resolver, .{
            .sequence_resolver = sequence_resolver_ctx.resolver(),
            .scalar_subquery_resolver = scalar_default_resolver_ctx.resolver(),
        }) catch |err| switch (err) {
            error.UnsupportedRowsSelector => return try textResponse(self.alloc, 400, "unsupported rows selector"),
            error.RowSelectorNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.SequenceNotFound => return try textResponse(self.alloc, 400, "invalid rows request"),
            error.UniqueOwnerTopologyUnavailable, error.TopologyChanged, error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "unique owner unavailable"),
            else => return try textResponse(self.alloc, 400, "invalid rows request"),
        };
        defer rows_req.deinit(self.alloc);

        if (rows_req.writes.len == 0 and rows_req.deletes.len == 0 and rows_req.transforms.len == 0 and rows_req.predicates.len == 0) {
            const response_body = try relational_rows_api.encodeRowsBatchResponseAlloc(self.alloc, rows_req);
            defer self.alloc.free(response_body);
            return try jsonBodyResponseWithStatus(self.alloc, 201, response_body);
        }

        self.requireRowsBatchSatisfiesEffectiveFilterForDatabase(tables_api.default_database_name, table_name, null, rows_req, authenticated_identity) catch |err| switch (err) {
            error.PermissionDenied => return try textResponse(self.alloc, 403, "row filter rejected rows batch"),
            else => return err,
        };

        var committed_via_txn = false;
        if (schema.storage_mode == .relational) {
            const txn_writes = try self.alloc.alloc(db_mod.types.TransactionWrite, rows_req.writes.len);
            defer self.alloc.free(txn_writes);
            for (rows_req.writes, 0..) |write, i| {
                txn_writes[i] = .{ .key = write.key, .value = write.value };
            }
            const txn_tables = [_]distributed_txn.TableCommitRequest{.{
                .table_name = table_name,
                .writes = txn_writes,
                .deletes = rows_req.deletes,
                .transforms = rows_req.transforms,
                .predicates = rows_req.predicates,
            }};
            if (source.commitTransaction(self.alloc, txn_tables[0..], rows_req.req.sync_level) catch |err| switch (err) {
                error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return try textResponse(self.alloc, 400, "invalid rows request"),
                error.VersionConflict, error.IntentConflict, error.DecisionConflict, error.TxnNotFound, error.InvalidTxnRecord => return try textResponse(self.alloc, 409, "version conflict"),
                error.TopologyChanged => return try textResponse(self.alloc, 503, "topology changed"),
                error.LeaderUnavailable, error.WriteUnavailable => return try textResponse(self.alloc, 503, "write unavailable"),
                error.TableNotFound, error.UnknownGroup => return try textResponse(self.alloc, 404, "not found"),
                error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "doc identity unavailable"),
                error.EnrichmentRetryInProgress => return try textResponse(self.alloc, 429, "table backpressured"),
                error.UnsupportedOperation => null,
                else => {
                    std.log.err("public table rows transaction failed table={s} err={}", .{ table_name, err });
                    return try textResponse(self.alloc, 500, "rows batch failed");
                },
            }) |outcome| {
                defer outcome.deinit(self.alloc);
                switch (outcome) {
                    .committed => committed_via_txn = true,
                    .conflict => return try textResponse(self.alloc, 409, "version conflict"),
                }
            }
        }

        if (!committed_via_txn) {
            _ = (source.batch(self.alloc, table_name, rows_req.req) catch |err| switch (err) {
                error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return try textResponse(self.alloc, 400, "invalid rows request"),
                error.VersionConflict, error.IntentConflict => return try textResponse(self.alloc, 409, "version conflict"),
                error.LeaderUnavailable, error.WriteUnavailable => return try textResponse(self.alloc, 503, "write unavailable"),
                error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
                error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "doc identity unavailable"),
                error.EnrichmentRetryInProgress => return try textResponse(self.alloc, 429, "table backpressured"),
                else => {
                    std.log.err("public table rows batch failed table={s} err={}", .{ table_name, err });
                    return try textResponse(self.alloc, 500, "rows batch failed");
                },
            }) orelse return try textResponse(self.alloc, 404, "not found");
        }

        const response_body = try relational_rows_api.encodeRowsBatchResponseAlloc(self.alloc, rows_req);
        defer self.alloc.free(response_body);
        return try jsonBodyResponseWithStatus(self.alloc, 201, response_body);
    }

    pub fn handlePublicCatalogTableRowsBatch(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        body: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !http_common.HttpResponse {
        const source = self.table_writes orelse return try textResponse(self.alloc, 404, "not found");
        const schema = self.runtimeSchemaForCatalogRows(target) catch |err| switch (err) {
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.InvalidRowsRequest => return try textResponse(self.alloc, 400, "invalid rows request"),
            else => return err,
        };
        defer runtime_schema_mod.freeSchema(self.alloc, schema);

        var unique_resolver_ctx = RowsUniqueSelectorResolverContext{ .source = self.table_reads };
        const unique_resolver = unique_resolver_ctx.resolver();
        const triggered_body = (try self.rowsBatchBodyAfterBeforeTriggersAlloc(target.table_name, body, schema, unique_resolver)) orelse body;
        defer if (triggered_body.ptr != body.ptr) self.alloc.free(triggered_body);

        var sequence_resolver_ctx = RowsSequenceDefaultResolverContext{ .source = self.source };
        const default_read_source = self.effectivePublicTableReads() orelse return try textResponse(self.alloc, 404, "not found");
        var scalar_default_resolver_ctx = RowsScalarSubqueryDefaultResolverContext{ .source = self.source, .table_reads = default_read_source };
        var rows_req = relational_rows_api.parseRowsBatchRequestWithResolverAndDefaultContext(self.alloc, target.table_name, triggered_body, schema, unique_resolver, .{
            .sequence_resolver = sequence_resolver_ctx.resolver(),
            .scalar_subquery_resolver = scalar_default_resolver_ctx.resolver(),
        }) catch |err| switch (err) {
            error.UnsupportedRowsSelector => return try textResponse(self.alloc, 400, "unsupported rows selector"),
            error.RowSelectorNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.SequenceNotFound => return try textResponse(self.alloc, 400, "invalid rows request"),
            error.UniqueOwnerTopologyUnavailable, error.TopologyChanged, error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "unique owner unavailable"),
            else => return try textResponse(self.alloc, 400, "invalid rows request"),
        };
        defer rows_req.deinit(self.alloc);

        if (rows_req.writes.len == 0 and rows_req.deletes.len == 0 and rows_req.transforms.len == 0 and rows_req.predicates.len == 0) {
            const response_body = try relational_rows_api.encodeRowsBatchResponseAlloc(self.alloc, rows_req);
            defer self.alloc.free(response_body);
            return try jsonBodyResponseWithStatus(self.alloc, 201, response_body);
        }

        const resource_name = try catalog_resources.tableResourceNameAlloc(self.alloc, target.database_name, target.namespace_name, target.table_name);
        defer self.alloc.free(resource_name);
        self.requireRowsBatchSatisfiesEffectiveFilterForDatabase(target.database_name, resource_name, target, rows_req, authenticated_identity) catch |err| switch (err) {
            error.PermissionDenied => return try textResponse(self.alloc, 403, "row filter rejected rows batch"),
            else => return err,
        };

        _ = (source.batchCatalog(self.alloc, target, rows_req.req) catch |err| switch (err) {
            error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return try textResponse(self.alloc, 400, "invalid rows request"),
            error.VersionConflict, error.IntentConflict => return try textResponse(self.alloc, 409, "version conflict"),
            error.LeaderUnavailable, error.WriteUnavailable => return try textResponse(self.alloc, 503, "write unavailable"),
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "doc identity unavailable"),
            error.EnrichmentRetryInProgress => return try textResponse(self.alloc, 429, "table backpressured"),
            else => {
                std.log.err("public catalog table rows batch failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                return try textResponse(self.alloc, 500, "rows batch failed");
            },
        }) orelse return try textResponse(self.alloc, 404, "not found");

        const response_body = try relational_rows_api.encodeRowsBatchResponseAlloc(self.alloc, rows_req);
        defer self.alloc.free(response_body);
        return try jsonBodyResponseWithStatus(self.alloc, 201, response_body);
    }

    const RowsBatchTrigger = struct {
        function_name: []u8,
        hook: sql_adapter.RoutineExecutionHook,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            alloc.free(self.function_name);
            self.* = undefined;
        }
    };

    fn rowsBatchTriggerForEventAlloc(
        self: *ApiHttpServer,
        table_name: []const u8,
        event: sql_routines.TriggerEvent,
    ) !?RowsBatchTrigger {
        const function_name = (try self.sql_routine_runtime.triggerFunctionForTableEventAlloc(self.alloc, table_name, event)) orelse return null;
        errdefer self.alloc.free(function_name);
        const hook = (try self.sql_routine_runtime.triggerHookForTableEvent(table_name, event)) orelse return error.RoutineNotFound;
        return .{ .function_name = function_name, .hook = hook };
    }

    fn rowsBatchBodyAfterBeforeTriggersAlloc(
        self: *ApiHttpServer,
        table_name: []const u8,
        body: []const u8,
        schema: runtime_schema_mod.TableSchema,
        unique_resolver: ?relational_rows_api.UniqueSelectorResolver,
    ) !?[]u8 {
        var insert_trigger = try self.rowsBatchTriggerForEventAlloc(table_name, .insert);
        defer if (insert_trigger) |*trigger| trigger.deinit(self.alloc);
        var update_trigger = try self.rowsBatchTriggerForEventAlloc(table_name, .update);
        defer if (update_trigger) |*trigger| trigger.deinit(self.alloc);
        var delete_trigger = try self.rowsBatchTriggerForEventAlloc(table_name, .delete);
        defer if (delete_trigger) |*trigger| trigger.deinit(self.alloc);
        if (insert_trigger == null and update_trigger == null and delete_trigger == null) return null;

        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, body, .{ .allocate = .alloc_always }) catch return error.InvalidRowsRequest;
        defer parsed.deinit();
        if (parsed.value != .object) return error.InvalidRowsRequest;
        const operations = parsed.value.object.get("operations") orelse return error.InvalidRowsRequest;
        if (operations != .array) return error.InvalidRowsRequest;

        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('{');
        var first_field = true;
        for (parsed.value.object.keys(), parsed.value.object.values()) |key, value| {
            if (!first_field) try writer.writeByte(',');
            first_field = false;
            try writer.print("{f}:", .{std.json.fmt(key, .{})});
            if (std.mem.eql(u8, key, "operations")) {
                try self.writeRowsBatchOperationsAfterBeforeTriggers(
                    writer,
                    table_name,
                    schema,
                    unique_resolver,
                    insert_trigger,
                    update_trigger,
                    delete_trigger,
                    operations.array.items,
                );
            } else {
                try std.json.Stringify.value(value, .{}, writer);
            }
        }
        try writer.writeByte('}');
        return try out.toOwnedSlice();
    }

    fn writeRowsBatchOperationsAfterBeforeTriggers(
        self: *ApiHttpServer,
        writer: *std.Io.Writer,
        table_name: []const u8,
        schema: runtime_schema_mod.TableSchema,
        unique_resolver: ?relational_rows_api.UniqueSelectorResolver,
        insert_trigger: ?RowsBatchTrigger,
        update_trigger: ?RowsBatchTrigger,
        delete_trigger: ?RowsBatchTrigger,
        operations: []const std.json.Value,
    ) !void {
        try writer.writeByte('[');
        var first_operation = true;
        for (operations) |operation| {
            if (operation != .object) return error.InvalidRowsRequest;
            const op_text = operation.object.get("op") orelse return error.InvalidRowsRequest;
            if (op_text != .string) return error.InvalidRowsRequest;
            if (std.mem.eql(u8, op_text.string, "insert") or std.mem.eql(u8, op_text.string, "upsert")) {
                const trigger = insert_trigger orelse {
                    try writeRowsBatchOperationJson(writer, operation, &first_operation);
                    continue;
                };
                const row = operation.object.get("row") orelse return error.InvalidRowsRequest;
                if (row != .object) return error.InvalidRowsRequest;
                const row_json = try std.json.Stringify.valueAlloc(self.alloc, row, .{});
                defer self.alloc.free(row_json);
                const triggered_row = try self.sql_routine_runtime.executeTriggerRoutineAlloc(self.alloc, trigger.function_name, row_json, null);
                defer self.alloc.free(triggered_row);
                var parsed_triggered = std.json.parseFromSlice(std.json.Value, self.alloc, triggered_row, .{ .allocate = .alloc_always }) catch return error.InvalidRowsRequest;
                defer parsed_triggered.deinit();
                if (parsed_triggered.value == .null) continue;
                if (parsed_triggered.value != .object) return error.InvalidRowsRequest;
                try writeRowsBatchComma(writer, &first_operation);
                try self.writeRowsBatchOperationWithTriggeredRow(writer, operation.object, parsed_triggered.value);
                continue;
            }

            if (std.mem.eql(u8, op_text.string, "update")) {
                const trigger = update_trigger orelse {
                    try writeRowsBatchOperationJson(writer, operation, &first_operation);
                    continue;
                };
                var old_row = try self.rowsBatchOldRowForOperationAlloc(table_name, schema, unique_resolver, operation);
                defer old_row.deinit(self.alloc);
                switch (trigger.hook) {
                    .trigger_return_new => {
                        const triggered_row = try self.sql_routine_runtime.executeTriggerRoutineAlloc(self.alloc, trigger.function_name, old_row.json, old_row.json);
                        defer self.alloc.free(triggered_row);
                        if (std.mem.eql(u8, triggered_row, "null")) continue;
                        try writeRowsBatchOperationJson(writer, operation, &first_operation);
                    },
                    .trigger_return_old, .trigger_return_null => continue,
                    else => return error.RoutineBodyNotExecutable,
                }
                continue;
            }

            if (std.mem.eql(u8, op_text.string, "delete")) {
                const trigger = delete_trigger orelse {
                    try writeRowsBatchOperationJson(writer, operation, &first_operation);
                    continue;
                };
                var old_row = try self.rowsBatchOldRowForOperationAlloc(table_name, schema, unique_resolver, operation);
                defer old_row.deinit(self.alloc);
                switch (trigger.hook) {
                    .trigger_return_old => {
                        const triggered_row = try self.sql_routine_runtime.executeTriggerRoutineAlloc(self.alloc, trigger.function_name, null, old_row.json);
                        defer self.alloc.free(triggered_row);
                        if (std.mem.eql(u8, triggered_row, "null")) continue;
                        try writeRowsBatchOperationJson(writer, operation, &first_operation);
                    },
                    .trigger_return_null => continue,
                    else => return error.RoutineBodyNotExecutable,
                }
                continue;
            }

            try writeRowsBatchOperationJson(writer, operation, &first_operation);
        }
        try writer.writeByte(']');
    }

    fn writeRowsBatchComma(writer: *std.Io.Writer, first_operation: *bool) !void {
        if (!first_operation.*) try writer.writeByte(',');
        first_operation.* = false;
    }

    fn writeRowsBatchOperationJson(
        writer: *std.Io.Writer,
        operation: std.json.Value,
        first_operation: *bool,
    ) !void {
        try writeRowsBatchComma(writer, first_operation);
        try std.json.Stringify.value(operation, .{}, writer);
    }

    fn writeRowsBatchOperationWithTriggeredRow(
        _: *ApiHttpServer,
        writer: *std.Io.Writer,
        operation: std.json.ObjectMap,
        triggered_row: std.json.Value,
    ) !void {
        try writer.writeByte('{');
        var first_field = true;
        for (operation.keys(), operation.values()) |key, value| {
            if (!first_field) try writer.writeByte(',');
            first_field = false;
            try writer.print("{f}:", .{std.json.fmt(key, .{})});
            if (std.mem.eql(u8, key, "row")) {
                try std.json.Stringify.value(triggered_row, .{}, writer);
            } else {
                try std.json.Stringify.value(value, .{}, writer);
            }
        }
        try writer.writeByte('}');
    }

    fn rowsBatchOldRowForOperationAlloc(
        self: *ApiHttpServer,
        table_name: []const u8,
        schema: runtime_schema_mod.TableSchema,
        unique_resolver: ?relational_rows_api.UniqueSelectorResolver,
        operation: std.json.Value,
    ) !relational_rows_api.ResolvedPrimaryRow {
        const resolver = unique_resolver orelse return error.UnsupportedRowsSelector;
        const where_value = operation.object.get("where") orelse return error.InvalidRowsRequest;
        const key = (try relational_rows_api.physicalPrimaryKeyFromWhereAlloc(self.alloc, table_name, schema, where_value, unique_resolver, false)) orelse return error.RowSelectorNotFound;
        defer self.alloc.free(key);
        return (try resolver.lookupPrimary(self.alloc, table_name, key)) orelse return error.RowSelectorNotFound;
    }

    pub fn handlePublicTableRowsMutationSource(
        self: *ApiHttpServer,
        table_name: []const u8,
        body: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !http_common.HttpResponse {
        const source = self.table_writes orelse return try textResponse(self.alloc, 404, "not found");
        const schema = self.runtimeSchemaForPublicRows(table_name) catch |err| switch (err) {
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.InvalidRowsRequest => return try textResponse(self.alloc, 400, "invalid rows mutation source request"),
            else => return err,
        };
        defer runtime_schema_mod.freeSchema(self.alloc, schema);

        const request_kind = rowsMutationSourceRequestKind(self.alloc, body) catch return try textResponse(self.alloc, 400, "invalid rows mutation source request");
        if (request_kind == .insert) {
            return try self.handlePublicTableRowsInsertSource(table_name, body, authenticated_identity, source, schema);
        }

        var rows_req = relational_rows_api.parseRowsMutationSourceRequest(self.alloc, body, schema) catch return try textResponse(self.alloc, 400, "invalid rows mutation source request");
        defer rows_req.deinit(self.alloc);

        var filter = self.rowsAuthFilterPlanForIdentity(table_name, authenticated_identity, schema) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return try textResponse(self.alloc, 403, "row filter pushdown required"),
            else => return err,
        };
        defer if (filter) |*value| value.deinit(self.alloc);
        if (filter) |active| {
            try self.applyRowsAuthFilterToQuery(schema, active, &rows_req.req.source);
        }

        var result = (source.mutateRowsFromSource(self.alloc, table_name, schema, rows_req.req) catch |err| switch (err) {
            error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest => return try textResponse(self.alloc, 400, "invalid rows mutation source request"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 501, "rows mutation source unavailable"),
            error.VersionConflict, error.IntentConflict, error.DecisionConflict, error.TxnNotFound, error.InvalidTxnRecord => return try textResponse(self.alloc, 409, "version conflict"),
            error.TopologyChanged => return try textResponse(self.alloc, 503, "topology changed"),
            error.LeaderUnavailable, error.WriteUnavailable => return try textResponse(self.alloc, 503, "write unavailable"),
            error.TableNotFound, error.UnknownGroup => return try textResponse(self.alloc, 404, "not found"),
            error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "doc identity unavailable"),
            error.EnrichmentRetryInProgress => return try textResponse(self.alloc, 429, "table backpressured"),
            else => {
                std.log.err("public table rows mutation source failed table={s} err={}", .{ table_name, err });
                return try textResponse(self.alloc, 500, "rows mutation source failed");
            },
        }) orelse return try textResponse(self.alloc, 404, "not found");
        defer result.deinit(self.alloc);

        if (result.staged > 0) {
            self.stageRowsMutationSourceSessionParticipant(table_name, rows_req.req.source.row_claim, result) catch |err| switch (err) {
                error.SessionLeaseLost => return try textResponse(self.alloc, 409, "version conflict"),
                else => return err,
            };
        }

        const response_body = try relational_rows_api.encodeRowsMutationSourceResponseAlloc(self.alloc, result);
        defer self.alloc.free(response_body);
        return try jsonBodyResponseWithStatus(self.alloc, 200, response_body);
    }

    fn handlePublicTableRowsInsertSource(
        self: *ApiHttpServer,
        table_name: []const u8,
        body: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        write_source: table_writes.TableWriteSource,
        target_schema: runtime_schema_mod.TableSchema,
    ) !http_common.HttpResponse {
        const read_source = self.effectivePublicTableReads() orelse return try textResponse(self.alloc, 404, "not found");
        const source_table_hint = rowsInsertSourceTableNameAlloc(self.alloc, body) catch return try textResponse(self.alloc, 400, "invalid rows mutation source request");
        defer if (source_table_hint.len > 0) self.alloc.free(source_table_hint);
        const source_table_name = rowsPlanEffectiveSideTable(table_name, source_table_hint);
        ensureRowsPlanTableReadable(authenticated_identity, source_table_name) catch |err| switch (err) {
            error.PermissionDenied => return try textResponse(self.alloc, 403, "forbidden"),
        };

        const source_schema = self.runtimeSchemaForPublicRows(source_table_name) catch |err| switch (err) {
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.InvalidRowsRequest => return try textResponse(self.alloc, 400, "invalid rows mutation source request"),
            else => return err,
        };
        defer runtime_schema_mod.freeSchema(self.alloc, source_schema);

        var rows_req = relational_rows_api.parseRowsInsertSourceRequestWithSchemas(self.alloc, body, target_schema, source_schema) catch |err| switch (err) {
            error.UnsupportedRowsSelector => return try textResponse(self.alloc, 400, "unsupported rows selector"),
            else => return try textResponse(self.alloc, 400, "invalid rows mutation source request"),
        };
        defer rows_req.deinit(self.alloc);

        self.applyRowsQueryRequestRowFilterForDatabase(tables_api.default_database_name, source_table_name, authenticated_identity, source_schema, &rows_req.req.source) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return try textResponse(self.alloc, 403, "row filter pushdown required"),
            else => return err,
        };

        var source_result = (read_source.rowsQueryPlan(self.alloc, source_table_name, source_schema, .{ .query = rows_req.req.source }, .read_index) catch |err| switch (err) {
            error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.RelationalRowsCteMaterializationRejected => return try textResponse(self.alloc, 400, "invalid rows mutation source request"),
            error.RelationalRowsCteSpillRequired => return try textResponse(self.alloc, 429, "rows mutation source backpressured"),
            error.UnsupportedOperation, error.UnsupportedRowsQuery => return try textResponse(self.alloc, 501, "rows mutation source unavailable"),
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.TopologyChanged => return try textResponse(self.alloc, 503, "topology changed"),
            error.LeaderUnavailable, error.ReadUnavailable => return try textResponse(self.alloc, 503, "read unavailable"),
            else => {
                std.log.err("public table rows insert source read failed table={s} source={s} err={}", .{ table_name, source_table_name, err });
                return try textResponse(self.alloc, 500, "rows mutation source failed");
            },
        }) orelse return try textResponse(self.alloc, 404, "not found");
        defer source_result.deinit(self.alloc);

        var unique_resolver_ctx = RowsUniqueSelectorResolverContext{ .source = self.table_reads };
        var sequence_resolver_ctx = RowsSequenceDefaultResolverContext{ .source = self.source };
        var scalar_default_resolver_ctx = RowsScalarSubqueryDefaultResolverContext{ .source = self.source, .table_reads = read_source };
        var rows_batch = relational_rows_api.buildRowsInsertSourceBatchWithSchemasAndDefaultContextAlloc(
            self.alloc,
            table_name,
            target_schema,
            source_schema,
            rows_req.req,
            source_result.rows,
            unique_resolver_ctx.resolver(),
            .{
                .sequence_resolver = sequence_resolver_ctx.resolver(),
                .scalar_subquery_resolver = scalar_default_resolver_ctx.resolver(),
            },
        ) catch |err| switch (err) {
            error.UnsupportedRowsSelector => return try textResponse(self.alloc, 400, "unsupported rows selector"),
            error.RowSelectorNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.UniqueOwnerTopologyUnavailable, error.TopologyChanged, error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "unique owner unavailable"),
            error.InvalidRowsRequest, error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation, error.SequenceNotFound => return try textResponse(self.alloc, 400, "invalid rows mutation source request"),
            else => {
                std.log.err("public table rows insert source plan failed table={s} source={s} err={}", .{ table_name, source_table_name, err });
                return try textResponse(self.alloc, 500, "rows mutation source failed");
            },
        };
        defer rows_batch.deinit(self.alloc);

        self.requireRowsBatchSatisfiesEffectiveFilterForDatabase(tables_api.default_database_name, table_name, null, rows_batch, authenticated_identity) catch |err| switch (err) {
            error.PermissionDenied => return try textResponse(self.alloc, 403, "row filter rejected rows mutation source"),
            else => return err,
        };

        if (rows_batch.writes.len != 0 or rows_batch.deletes.len != 0 or rows_batch.transforms.len != 0 or rows_batch.predicates.len != 0) {
            var committed_via_txn = false;
            if (target_schema.storage_mode == .relational) {
                const txn_writes = try self.alloc.alloc(db_mod.types.TransactionWrite, rows_batch.writes.len);
                defer self.alloc.free(txn_writes);
                for (rows_batch.writes, 0..) |write, i| {
                    txn_writes[i] = .{ .key = write.key, .value = write.value };
                }
                const txn_tables = [_]distributed_txn.TableCommitRequest{.{
                    .table_name = table_name,
                    .writes = txn_writes,
                    .deletes = rows_batch.deletes,
                    .transforms = rows_batch.transforms,
                    .predicates = rows_batch.predicates,
                }};
                if (write_source.commitTransaction(self.alloc, txn_tables[0..], rows_batch.req.sync_level) catch |err| switch (err) {
                    error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return try textResponse(self.alloc, 400, "invalid rows mutation source request"),
                    error.VersionConflict, error.IntentConflict, error.DecisionConflict, error.TxnNotFound, error.InvalidTxnRecord => return try textResponse(self.alloc, 409, "version conflict"),
                    error.TopologyChanged => return try textResponse(self.alloc, 503, "topology changed"),
                    error.LeaderUnavailable, error.WriteUnavailable => return try textResponse(self.alloc, 503, "write unavailable"),
                    error.TableNotFound, error.UnknownGroup => return try textResponse(self.alloc, 404, "not found"),
                    error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "doc identity unavailable"),
                    error.EnrichmentRetryInProgress => return try textResponse(self.alloc, 429, "table backpressured"),
                    error.UnsupportedOperation => null,
                    else => {
                        std.log.err("public table rows insert source transaction failed table={s} err={}", .{ table_name, err });
                        return try textResponse(self.alloc, 500, "rows mutation source failed");
                    },
                }) |outcome| {
                    defer outcome.deinit(self.alloc);
                    switch (outcome) {
                        .committed => committed_via_txn = true,
                        .conflict => return try textResponse(self.alloc, 409, "version conflict"),
                    }
                }
            }

            if (!committed_via_txn) {
                _ = (write_source.batch(self.alloc, table_name, rows_batch.req) catch |err| switch (err) {
                    error.InvalidBatchRequest, error.ForeignKeyViolation, error.UniqueConstraintViolation => return try textResponse(self.alloc, 400, "invalid rows mutation source request"),
                    error.VersionConflict, error.IntentConflict => return try textResponse(self.alloc, 409, "version conflict"),
                    error.LeaderUnavailable, error.WriteUnavailable => return try textResponse(self.alloc, 503, "write unavailable"),
                    error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
                    error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "doc identity unavailable"),
                    error.EnrichmentRetryInProgress => return try textResponse(self.alloc, 429, "table backpressured"),
                    else => {
                        std.log.err("public table rows insert source batch failed table={s} err={}", .{ table_name, err });
                        return try textResponse(self.alloc, 500, "rows mutation source failed");
                    },
                }) orelse return try textResponse(self.alloc, 404, "not found");
            }
        }

        var result = rowsInsertSourceMutationResultAlloc(self.alloc, source_result.rows.len, rows_batch) catch |err| switch (err) {
            error.ResourceBudgetExceeded => return try textResponse(self.alloc, 400, "invalid rows mutation source request"),
            else => return err,
        };
        defer result.deinit(self.alloc);
        const response_body = try relational_rows_api.encodeRowsMutationSourceResponseAlloc(self.alloc, result);
        defer self.alloc.free(response_body);
        return try jsonBodyResponseWithStatus(self.alloc, 200, response_body);
    }

    const RowsMutationSourceRequestKind = enum {
        insert,
        update,
        delete,
    };

    fn rowsMutationSourceRequestKind(alloc: std.mem.Allocator, body: []const u8) !RowsMutationSourceRequestKind {
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, body, .{ .allocate = .alloc_always }) catch return error.InvalidRowsRequest;
        defer parsed.deinit();
        if (parsed.value != .object) return error.InvalidRowsRequest;
        const op = parsed.value.object.get("op") orelse return error.InvalidRowsRequest;
        if (op != .string) return error.InvalidRowsRequest;
        if (std.mem.eql(u8, op.string, "insert")) return .insert;
        if (std.mem.eql(u8, op.string, "update")) return .update;
        if (std.mem.eql(u8, op.string, "delete")) return .delete;
        return error.InvalidRowsRequest;
    }

    fn rowsInsertSourceTableNameAlloc(alloc: std.mem.Allocator, body: []const u8) ![]const u8 {
        var parsed = std.json.parseFromSlice(std.json.Value, alloc, body, .{ .allocate = .alloc_always }) catch return error.InvalidRowsRequest;
        defer parsed.deinit();
        if (parsed.value != .object) return error.InvalidRowsRequest;
        const value = parsed.value.object.get("source_table") orelse return "";
        if (value != .string) return error.InvalidRowsRequest;
        if (value.string.len == 0) return "";
        return try alloc.dupe(u8, value.string);
    }

    fn rowsInsertSourceMutationResultAlloc(
        alloc: std.mem.Allocator,
        matched_len: usize,
        rows_batch: relational_rows_api.OwnedRowsBatchRequest,
    ) !db_mod.types.RelationalRowsMutationSourceResult {
        const matched = std.math.cast(u32, matched_len) orelse return error.ResourceBudgetExceeded;
        const staged = std.math.add(u32, rows_batch.inserted, rows_batch.transformed) catch return error.ResourceBudgetExceeded;
        const returning_rows = try alloc.alloc([]const u8, rows_batch.returning_rows.len);
        var initialized: usize = 0;
        errdefer {
            for (returning_rows[0..initialized]) |row| alloc.free(@constCast(row));
            alloc.free(returning_rows);
        }
        for (rows_batch.returning_rows, 0..) |row, i| {
            returning_rows[i] = try alloc.dupe(u8, row);
            initialized += 1;
        }
        return .{
            .matched = matched,
            .staged = staged,
            .returning_rows = returning_rows,
        };
    }

    fn stageRowsMutationSourceSessionParticipant(
        self: *ApiHttpServer,
        table_name: []const u8,
        row_claim: ?db_mod.types.RowClaimRequest,
        result: db_mod.types.RelationalRowsMutationSourceResult,
    ) !void {
        const claim = row_claim orelse return;
        const txn_id = claim.txn_id orelse return;
        if (result.participant_predicates.len == 0 and
            result.participant_preimages.len == 0 and
            result.participant_writes.len == 0 and
            result.participant_deletes.len == 0 and
            result.participant_transforms.len == 0) return;
        const owned_table_name = try self.alloc.dupe(u8, table_name);
        var req = transactions_api.OwnedTransactionCommitRequest{};
        req.tables = self.alloc.alloc(transactions_api.TableCommitRequest, 1) catch |err| {
            self.alloc.free(owned_table_name);
            return err;
        };
        req.tables[0] = .{
            .table_name = owned_table_name,
        };
        defer req.deinit(self.alloc);
        try cloneRowsMutationSourceParticipantPreimages(self.alloc, &req.tables[0], result.participant_preimages);
        try cloneRowsMutationSourceParticipantWrites(self.alloc, &req.tables[0].batch, result.participant_writes);
        try cloneRowsMutationSourceParticipantDeletes(self.alloc, &req.tables[0].batch, result.participant_deletes);
        try cloneRowsMutationSourceParticipantTransforms(self.alloc, &req.tables[0].batch, result.participant_transforms);
        req.tables[0].batch.req = .{
            .writes = req.tables[0].batch.writes,
            .deletes = req.tables[0].batch.deletes,
            .transforms = req.tables[0].batch.transforms,
        };
        try req.tables[0].predicates.ensureUnusedCapacity(self.alloc, result.participant_predicates.len);
        for (result.participant_predicates) |predicate| {
            const owned_key = try self.alloc.dupe(u8, predicate.key);
            req.tables[0].predicates.appendAssumeCapacity(.{
                .key = owned_key,
                .expected_version = predicate.expected_version,
            });
        }
        _ = try self.txn_sessions.stage(self.alloc, txn_id, &req) orelse return;
    }

    fn cloneRowsMutationSourceParticipantPreimages(
        alloc: std.mem.Allocator,
        table: *transactions_api.TableCommitRequest,
        preimages: []const db_mod.types.TransactionWrite,
    ) !void {
        if (preimages.len == 0) return;
        table.preimages = try alloc.alloc(db_mod.types.TransactionWrite, preimages.len);
        var count: usize = 0;
        errdefer {
            for (table.preimages[0..count]) |preimage| {
                alloc.free(@constCast(preimage.key));
                alloc.free(@constCast(preimage.value));
            }
            alloc.free(table.preimages);
            table.preimages = &.{};
        }
        for (preimages) |preimage| {
            table.preimages[count] = .{
                .key = try alloc.dupe(u8, preimage.key),
                .value = try alloc.dupe(u8, preimage.value),
            };
            count += 1;
        }
    }

    fn cloneRowsMutationSourceParticipantWrites(
        alloc: std.mem.Allocator,
        batch: *batch_api.OwnedBatchRequest,
        writes: []const db_mod.types.TransactionWrite,
    ) !void {
        if (writes.len == 0) return;
        batch.writes = try alloc.alloc(db_mod.types.BatchWrite, writes.len);
        var count: usize = 0;
        errdefer {
            for (batch.writes[0..count]) |write| {
                alloc.free(@constCast(write.key));
                alloc.free(@constCast(write.value));
            }
            alloc.free(batch.writes);
            batch.writes = &.{};
        }
        for (writes) |write| {
            batch.writes[count] = .{
                .key = try alloc.dupe(u8, write.key),
                .value = try alloc.dupe(u8, write.value),
            };
            count += 1;
        }
    }

    fn cloneRowsMutationSourceParticipantDeletes(
        alloc: std.mem.Allocator,
        batch: *batch_api.OwnedBatchRequest,
        deletes: []const []const u8,
    ) !void {
        if (deletes.len == 0) return;
        batch.deletes = try alloc.alloc([]const u8, deletes.len);
        var count: usize = 0;
        errdefer {
            for (batch.deletes[0..count]) |key| alloc.free(@constCast(key));
            alloc.free(batch.deletes);
            batch.deletes = &.{};
        }
        for (deletes) |key| {
            batch.deletes[count] = try alloc.dupe(u8, key);
            count += 1;
        }
    }

    fn cloneRowsMutationSourceParticipantTransforms(
        alloc: std.mem.Allocator,
        batch: *batch_api.OwnedBatchRequest,
        transforms: []const db_mod.types.DocumentTransform,
    ) !void {
        if (transforms.len == 0) return;
        batch.transforms = try alloc.alloc(db_mod.types.DocumentTransform, transforms.len);
        var count: usize = 0;
        errdefer {
            for (batch.transforms[0..count]) |transform| freeRowsMutationSourceParticipantTransform(alloc, transform);
            alloc.free(batch.transforms);
            batch.transforms = &.{};
        }
        for (transforms) |transform| {
            batch.transforms[count] = try cloneRowsMutationSourceParticipantTransform(alloc, transform);
            count += 1;
        }
    }

    fn cloneRowsMutationSourceParticipantTransform(
        alloc: std.mem.Allocator,
        transform: db_mod.types.DocumentTransform,
    ) !db_mod.types.DocumentTransform {
        const operations = try alloc.alloc(db_mod.types.TransformOp, transform.operations.len);
        var op_count: usize = 0;
        errdefer {
            for (operations[0..op_count]) |op| {
                alloc.free(@constCast(op.path));
                if (op.value_json) |value_json| alloc.free(@constCast(value_json));
            }
            if (operations.len > 0) alloc.free(operations);
        }
        for (transform.operations) |op| {
            operations[op_count] = .{
                .op = op.op,
                .path = try alloc.dupe(u8, op.path),
                .value_json = if (op.value_json) |value_json| try alloc.dupe(u8, value_json) else null,
            };
            op_count += 1;
        }
        return .{
            .key = try alloc.dupe(u8, transform.key),
            .operations = operations,
            .upsert = transform.upsert,
        };
    }

    fn freeRowsMutationSourceParticipantTransform(
        alloc: std.mem.Allocator,
        transform: db_mod.types.DocumentTransform,
    ) void {
        alloc.free(@constCast(transform.key));
        for (transform.operations) |op| {
            alloc.free(@constCast(op.path));
            if (op.value_json) |value_json| alloc.free(@constCast(value_json));
        }
        if (transform.operations.len > 0) alloc.free(transform.operations);
    }

    pub fn handlePublicTableRowsGet(
        self: *ApiHttpServer,
        table_name: []const u8,
        body: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !http_common.HttpResponse {
        const source = self.table_reads orelse return try textResponse(self.alloc, 404, "not found");
        const schema = self.runtimeSchemaForPublicRows(table_name) catch |err| switch (err) {
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.InvalidRowsRequest => return try textResponse(self.alloc, 400, "invalid rows request"),
            else => return err,
        };
        defer runtime_schema_mod.freeSchema(self.alloc, schema);

        var unique_resolver_ctx = RowsUniqueSelectorResolverContext{ .source = self.table_reads };
        const unique_resolver = unique_resolver_ctx.resolver();
        var rows_req = relational_rows_api.parseRowsGetRequestWithResolver(self.alloc, table_name, body, schema, unique_resolver) catch |err| switch (err) {
            error.UnsupportedRowsSelector => return try textResponse(self.alloc, 400, "unsupported rows selector"),
            error.UniqueOwnerTopologyUnavailable, error.TopologyChanged, error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "unique owner unavailable"),
            else => return try textResponse(self.alloc, 400, "invalid rows request"),
        };
        defer rows_req.deinit(self.alloc);

        var results = try self.alloc.alloc(relational_rows_api.RowLookupResult, rows_req.keys.len);
        defer self.alloc.free(results);
        var initialized: usize = 0;
        defer {
            for (results[0..initialized]) |row| {
                if (row.row_json) |json| self.alloc.free(json);
            }
        }

        const row_filter_json = try self.resolveEffectiveRowFilterJsonForDatabase(self.alloc, authenticated_identity, tables_api.default_database_name, table_name);
        defer if (row_filter_json) |value| self.alloc.free(value);

        for (rows_req.keys, 0..) |maybe_key, i| {
            results[i] = .{
                .identity_json = rows_req.identities_json[i],
                .physical_key = maybe_key,
                .found = false,
            };
            initialized += 1;
            const key = maybe_key orelse continue;
            var lookup = (source.lookup(self.alloc, table_name, key, .{}, .read_index) catch |err| switch (err) {
                error.LeaderUnavailable, error.ReadUnavailable => return try textResponse(self.alloc, 503, "read unavailable"),
                else => return err,
            }) orelse continue;
            defer lookup.deinit(self.alloc);
            if (row_filter_json) |value| {
                if (!(try self.docJsonMatchesRowFilter(key, lookup.json, value))) continue;
            }
            results[i].found = true;
            results[i].row_json = try self.alloc.dupe(u8, lookup.json);
            results[i].version = lookup.version;
        }

        const response_body = try relational_rows_api.encodeRowsGetResponseAlloc(self.alloc, results, rows_req.include_physical_key);
        defer self.alloc.free(response_body);
        return try jsonBodyResponseWithStatus(self.alloc, 200, response_body);
    }

    pub fn handlePublicTableRowsPlan(
        self: *ApiHttpServer,
        table_name: []const u8,
        body: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !http_common.HttpResponse {
        const operation = relational_rows_api.detectRowsPlanOperationWithoutSchema(self.alloc, body) catch return try textResponse(self.alloc, 400, "invalid rows request");
        return switch (operation) {
            .query => try self.handlePublicTableRowsQuery(table_name, body, authenticated_identity),
            .aggregate => try self.handlePublicTableRowsAggregate(table_name, body, authenticated_identity),
            .window => try self.handlePublicTableRowsWindow(table_name, body, authenticated_identity),
            .join => try self.handlePublicTableRowsJoin(table_name, body, authenticated_identity),
            .lateral => try self.handlePublicTableRowsLateral(table_name, body, authenticated_identity),
        };
    }

    fn openPublicExternalLakeRowsSourceAlloc(
        self: *ApiHttpServer,
        schema: runtime_schema_mod.TableSchema,
    ) !table_reads.OpenedExternalObjectStorageLakeRowsSource {
        return try self.openPublicExternalLakeRowsSourceWithOptionsAlloc(
            schema,
            self.externalLakeRowsSourceOptions(),
        );
    }

    fn openPublicExternalLakeRowsSourceWithOptionsAlloc(
        self: *ApiHttpServer,
        schema: runtime_schema_mod.TableSchema,
        lake_options: table_reads.ExternalObjectStorageLakeRowsSourceOptions,
    ) !table_reads.OpenedExternalObjectStorageLakeRowsSource {
        const external_base_source = schema.external_base_source orelse return error.InvalidRowsRequest;
        const external_binding_api = @import("../serverless/external_source/catalog_binding.zig");
        const binding = external_binding_api.bindingFromRuntimeExternalBaseSource(external_base_source);
        self.external_lake_configured_resolver.configure(self.cfg.node_config, self.cfg.secret_store);
        const resolver = self.cfg.external_lake_object_store_resolver orelse self.external_lake_configured_resolver.resolver();
        const opened_store = try resolver.openParquetPrefixAlloc(self.alloc, binding, lake_options);
        return try table_reads.OpenedExternalObjectStorageLakeRowsSource.initWithOpenedStoreAlloc(
            self.alloc,
            schema,
            opened_store,
            lake_options,
        );
    }

    const OwnedExternalLakeSidecarRequestContext = struct {
        base: table_reads.PinnedExternalLakeSidecarContext,
        owned_candidates: serverless_query.LakeOwnedSidecarCandidateSets = .{ .sets = &.{} },
        has_owned_candidates: bool = false,
        generated_candidate_sets: []serverless_query.LakeRowsSidecarCandidateSet = &.{},
        combined_candidate_sets: []serverless_query.LakeRowsSidecarCandidateSet = &.{},
        generated_desired_sidecars: []serverless_query.LakeSidecarDesired = &.{},
        combined_desired_sidecars: []serverless_query.LakeSidecarDesired = &.{},

        fn context(self: *const @This()) table_reads.PinnedExternalLakeSidecarContext {
            return .{
                .sidecars = self.base.sidecars,
                .desired_sidecars = if (self.combined_desired_sidecars.len != 0)
                    self.combined_desired_sidecars
                else if (self.generated_desired_sidecars.len != 0)
                    self.generated_desired_sidecars
                else
                    self.base.desired_sidecars,
                .sidecar_policy = self.base.sidecar_policy,
                .candidates = if (self.combined_candidate_sets.len != 0)
                    self.combined_candidate_sets
                else if (self.generated_candidate_sets.len != 0)
                    self.generated_candidate_sets
                else
                    self.base.candidates,
            };
        }

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            if (self.combined_desired_sidecars.len > 0) alloc.free(self.combined_desired_sidecars);
            if (self.generated_desired_sidecars.len > 0) alloc.free(self.generated_desired_sidecars);
            if (self.combined_candidate_sets.len > 0) alloc.free(self.combined_candidate_sets);
            if (self.generated_candidate_sets.len > 0) alloc.free(self.generated_candidate_sets);
            if (self.has_owned_candidates) self.owned_candidates.deinit(alloc);
            self.* = undefined;
        }
    };

    fn externalLakeSidecarContextForRowsQueryAlloc(
        self: *ApiHttpServer,
        query: db_mod.types.RelationalRowsQueryRequest,
    ) !OwnedExternalLakeSidecarRequestContext {
        var out = OwnedExternalLakeSidecarRequestContext{ .base = self.cfg.external_lake_sidecar_context };
        errdefer out.deinit(self.alloc);
        const artifacts = self.cfg.external_lake_artifact_store orelse return out;
        if (out.base.sidecars.len == 0) return out;

        out.owned_candidates = try self.textSidecarCandidateSetsForRowsQueryAlloc(artifacts, out.base.sidecars, query);
        out.has_owned_candidates = true;
        if (out.owned_candidates.sets.len == 0) return out;

        out.generated_candidate_sets = try out.owned_candidates.asLakeRowsCandidateSetsAlloc(self.alloc);
        out.generated_desired_sidecars = try serverless_query.lakeRowsDesiredSidecarsFromCandidateSetsAlloc(
            self.alloc,
            out.generated_candidate_sets,
        );
        if (out.base.candidates.len != 0) {
            out.combined_candidate_sets = try concatCandidateSetsAlloc(
                self.alloc,
                out.base.candidates,
                out.generated_candidate_sets,
            );
        }
        if (out.base.desired_sidecars.len != 0) {
            out.combined_desired_sidecars = try concatDesiredSidecarsAlloc(
                self.alloc,
                out.base.desired_sidecars,
                out.generated_desired_sidecars,
            );
        }
        return out;
    }

    fn textSidecarCandidateSetsForRowsQueryAlloc(
        self: *ApiHttpServer,
        artifacts: *serverless_artifacts.ArtifactStore,
        sidecars: []const lake_sidecar_manifest.DeclaredArtifact,
        query: db_mod.types.RelationalRowsQueryRequest,
    ) !serverless_query.LakeOwnedSidecarCandidateSets {
        var sets = std.ArrayListUnmanaged(serverless_query.LakeOwnedSidecarCandidateSet).empty;
        errdefer {
            for (sets.items) |*set| set.deinit(self.alloc);
            sets.deinit(self.alloc);
        }

        for (query.text_patterns) |predicate| {
            var produced = (try self.textSidecarCandidateSetsForRowsTextPatternAlloc(
                artifacts,
                sidecars,
                predicate,
            )) orelse continue;
            defer produced.deinit(self.alloc);
            try appendOwnedCandidateSetsIntersectingDuplicatesAlloc(self.alloc, &sets, produced.sets);
        }

        if (try self.textSidecarCandidateSetsForRowsAccessOrPredicatesAlloc(
            artifacts,
            sidecars,
            query.access_or_predicates,
        )) |produced_or_value| {
            var produced_or = produced_or_value;
            defer produced_or.deinit(self.alloc);
            try appendOwnedCandidateSetsIntersectingDuplicatesAlloc(self.alloc, &sets, produced_or.sets);
        }

        return .{ .sets = try sets.toOwnedSlice(self.alloc) };
    }

    fn externalLakeSidecarContextForRowsAggregateAlloc(
        self: *ApiHttpServer,
        aggregate: db_mod.types.RelationalRowsAggregateRequest,
    ) !OwnedExternalLakeSidecarRequestContext {
        if (aggregate.source.text_patterns.len == 0 and aggregate.source.access_or_predicates.len == 0) {
            return .{ .base = self.cfg.external_lake_sidecar_context };
        }
        return try self.externalLakeSidecarContextForRowsQueryAlloc(aggregate.source);
    }

    fn externalLakeSidecarContextForRowsExplainAlloc(
        self: *ApiHttpServer,
        schema: runtime_schema_mod.TableSchema,
        body: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        table_name: []const u8,
    ) !OwnedExternalLakeSidecarRequestContext {
        if (std.mem.trim(u8, body, " \t\r\n").len == 0) {
            return .{ .base = self.cfg.external_lake_sidecar_context };
        }
        const operation = relational_rows_api.detectRowsPlanOperationWithoutSchema(self.alloc, body) catch return error.InvalidRowsRequest;
        return switch (operation) {
            .query => blk: {
                var plan = relational_rows_api.parseRowsQueryPlanRequest(self.alloc, body, schema) catch return error.InvalidRowsRequest;
                defer plan.deinit(self.alloc);
                try self.applyRowsQueryPlanRowFilter(table_name, authenticated_identity, schema, &plan);
                break :blk try self.externalLakeSidecarContextForRowsQueryAlloc(plan.query);
            },
            .aggregate => blk: {
                var plan = relational_rows_api.parseRowsAggregatePlanRequest(self.alloc, body, schema) catch return error.InvalidRowsRequest;
                defer plan.deinit(self.alloc);
                try self.applyRowsAggregatePlanRowFilter(table_name, authenticated_identity, schema, &plan);
                break :blk try self.externalLakeSidecarContextForRowsAggregateAlloc(plan.aggregate);
            },
            .window, .join, .lateral => .{ .base = self.cfg.external_lake_sidecar_context },
        };
    }

    fn textSidecarCandidatePlanForRowsQueryAlloc(
        alloc: std.mem.Allocator,
        sidecars: []const lake_sidecar_manifest.DeclaredArtifact,
        query: db_mod.types.RelationalRowsQueryRequest,
    ) !?serverless_query.LakeTextSidecarCandidatePlan {
        for (query.text_patterns) |predicate| {
            if (try textSidecarCandidatePlanForRowsTextPatternAlloc(alloc, sidecars, predicate)) |plan| return plan;
        }
        return null;
    }

    fn textSidecarCandidateSetsForRowsAccessOrPredicatesAlloc(
        self: *ApiHttpServer,
        artifacts: *serverless_artifacts.ArtifactStore,
        sidecars: []const lake_sidecar_manifest.DeclaredArtifact,
        groups: []const db_mod.types.RelationalRowsAccessPredicateGroup,
    ) !?serverless_query.LakeOwnedSidecarCandidateSets {
        if (groups.len == 0) return null;

        var union_sets = std.ArrayListUnmanaged(serverless_query.LakeOwnedSidecarCandidateSet).empty;
        errdefer deinitOwnedCandidateSetList(self.alloc, &union_sets);

        for (groups) |group| {
            if (!accessPredicateGroupIsPureText(group)) {
                deinitOwnedCandidateSetList(self.alloc, &union_sets);
                return null;
            }

            var branch_sets = try self.textSidecarCandidateSetsForRowsAccessGroupAlloc(
                artifacts,
                sidecars,
                group,
            );
            defer branch_sets.deinit(self.alloc);
            if (branch_sets.sets.len != 1) {
                deinitOwnedCandidateSetList(self.alloc, &union_sets);
                return null;
            }
            if (union_sets.items.len != 0 and ownedCandidateSetIndexByName(union_sets.items, branch_sets.sets[0].sidecar_name) == null) {
                deinitOwnedCandidateSetList(self.alloc, &union_sets);
                return null;
            }
            try appendOwnedCandidateSetsUnioningDuplicatesAlloc(self.alloc, &union_sets, branch_sets.sets);
        }

        return .{ .sets = try union_sets.toOwnedSlice(self.alloc) };
    }

    fn textSidecarCandidateSetsForRowsAccessGroupAlloc(
        self: *ApiHttpServer,
        artifacts: *serverless_artifacts.ArtifactStore,
        sidecars: []const lake_sidecar_manifest.DeclaredArtifact,
        group: db_mod.types.RelationalRowsAccessPredicateGroup,
    ) !serverless_query.LakeOwnedSidecarCandidateSets {
        var sets = std.ArrayListUnmanaged(serverless_query.LakeOwnedSidecarCandidateSet).empty;
        errdefer deinitOwnedCandidateSetList(self.alloc, &sets);

        for (group.text_patterns) |predicate| {
            var produced = (try self.textSidecarCandidateSetsForRowsTextPatternAlloc(
                artifacts,
                sidecars,
                predicate,
            )) orelse continue;
            defer produced.deinit(self.alloc);
            try appendOwnedCandidateSetsIntersectingDuplicatesAlloc(self.alloc, &sets, produced.sets);
        }

        return .{ .sets = try sets.toOwnedSlice(self.alloc) };
    }

    fn accessPredicateGroupIsPureText(group: db_mod.types.RelationalRowsAccessPredicateGroup) bool {
        return group.text_patterns.len != 0 and
            group.predicates.len == 0 and
            group.array_any.len == 0 and
            group.array_contains.len == 0 and
            group.array_eq.len == 0 and
            group.in_predicates.len == 0 and
            group.json_contains.len == 0 and
            group.json_path_eq.len == 0 and
            group.json_path_exists.len == 0;
    }

    fn textSidecarCandidateSetsForRowsTextPatternAlloc(
        self: *ApiHttpServer,
        artifacts: *serverless_artifacts.ArtifactStore,
        sidecars: []const lake_sidecar_manifest.DeclaredArtifact,
        predicate: db_mod.types.RelationalRowsTextPatternPredicate,
    ) !?serverless_query.LakeOwnedSidecarCandidateSets {
        const queries = textPatternCandidateQueriesFromPattern(predicate) orelse return null;
        const sidecar_names = try textSidecarNamesForFieldAlloc(self.alloc, sidecars, predicate.field);
        if (sidecar_names.len == 0) {
            self.alloc.free(sidecar_names);
            return null;
        }
        defer self.alloc.free(sidecar_names);

        var sets = std.ArrayListUnmanaged(serverless_query.LakeOwnedSidecarCandidateSet).empty;
        errdefer deinitOwnedCandidateSetList(self.alloc, &sets);

        for (queries.slice()) |query| {
            var produced = try serverless_query.lakeTextSidecarCandidateSetsFromArtifactStoreAlloc(
                self.alloc,
                artifacts,
                sidecars,
                .{
                    .request = .{
                        .text = query.text,
                        .operator = query.operator,
                        .limit = std.math.maxInt(usize),
                    },
                    .sidecar_names = sidecar_names,
                },
            );
            defer produced.deinit(self.alloc);
            try appendOwnedCandidateSetsIntersectingDuplicatesAlloc(self.alloc, &sets, produced.sets);
        }

        return .{ .sets = try sets.toOwnedSlice(self.alloc) };
    }

    fn textSidecarCandidatePlanForRowsTextPatternAlloc(
        alloc: std.mem.Allocator,
        sidecars: []const lake_sidecar_manifest.DeclaredArtifact,
        predicate: db_mod.types.RelationalRowsTextPatternPredicate,
    ) !?serverless_query.LakeTextSidecarCandidatePlan {
        const queries = textPatternCandidateQueriesFromPattern(predicate) orelse return null;
        const query = queries.slice()[0];
        const sidecar_names = try textSidecarNamesForFieldAlloc(alloc, sidecars, predicate.field);
        if (sidecar_names.len == 0) {
            alloc.free(sidecar_names);
            return null;
        }
        return .{
            .request = .{
                .text = query.text,
                .operator = query.operator,
                .limit = std.math.maxInt(usize),
            },
            .sidecar_names = sidecar_names,
        };
    }

    const TextPatternCandidateQueries = struct {
        items: [2]TextPatternCandidateQuery = undefined,
        len: usize = 0,

        fn append(self: *@This(), query: TextPatternCandidateQuery) void {
            std.debug.assert(self.len < self.items.len);
            self.items[self.len] = query;
            self.len += 1;
        }

        fn slice(self: *const @This()) []const TextPatternCandidateQuery {
            return self.items[0..self.len];
        }
    };

    const TextPatternCandidateQuery = struct {
        text: []const u8,
        operator: serverless_query.QueryOperator,
    };

    fn textPatternCandidateQueriesFromPattern(predicate: db_mod.types.RelationalRowsTextPatternPredicate) ?TextPatternCandidateQueries {
        if (predicate.negated or predicate.pattern.len == 0) return null;
        if (containsSqlLikeEscape(predicate.pattern)) return null;
        if (!containsSearchableTextByte(predicate.pattern)) return null;
        if (!containsSqlLikeWildcard(predicate.pattern)) {
            var queries = TextPatternCandidateQueries{};
            queries.append(.{ .text = predicate.pattern, .operator = .phrase });
            return queries;
        }
        const prefix = simpleTrailingPercentPrefix(predicate.pattern) orelse return null;
        if (!containsSearchableTextByte(prefix)) return null;
        if (containsWhitespaceOrControl(prefix)) return textPatternCandidateQueriesFromTrailingPrefix(prefix);
        var queries = TextPatternCandidateQueries{};
        queries.append(.{ .text = prefix, .operator = .prefix_any_term });
        return queries;
    }

    fn textPatternCandidateQueriesFromTrailingPrefix(prefix: []const u8) ?TextPatternCandidateQueries {
        var first_token_start: ?usize = null;
        var last_token_start: ?usize = null;
        var last_token_end: ?usize = null;
        var in_token = false;

        for (prefix, 0..) |ch, idx| {
            if (std.ascii.isWhitespace(ch)) {
                in_token = false;
                continue;
            }
            if (std.ascii.isControl(ch)) return null;
            if (!in_token) {
                if (first_token_start == null) first_token_start = idx;
                last_token_start = idx;
                in_token = true;
            }
            last_token_end = idx + 1;
        }

        const first_start = first_token_start orelse return null;
        const last_start = last_token_start orelse return null;
        const last_end = last_token_end orelse return null;

        var queries = TextPatternCandidateQueries{};
        if (last_end == prefix.len) {
            if (last_start > first_start) {
                const complete_terms = std.mem.trim(u8, prefix[0..last_start], " \t\r\n");
                if (containsSearchableTextByte(complete_terms)) {
                    queries.append(.{ .text = complete_terms, .operator = .all_terms });
                }
            }
            const partial_term = prefix[last_start..last_end];
            if (containsSearchableTextByte(partial_term)) {
                queries.append(.{ .text = partial_term, .operator = .prefix_any_term });
            }
        } else {
            const complete_terms = std.mem.trim(u8, prefix, " \t\r\n");
            if (containsSearchableTextByte(complete_terms)) {
                queries.append(.{ .text = complete_terms, .operator = .all_terms });
            }
        }

        return if (queries.len == 0) null else queries;
    }

    fn containsSqlLikeWildcard(pattern: []const u8) bool {
        for (pattern) |ch| {
            if (ch == '%' or ch == '_') return true;
        }
        return false;
    }

    fn containsSqlLikeEscape(pattern: []const u8) bool {
        return std.mem.indexOfScalar(u8, pattern, '\\') != null;
    }

    fn containsSearchableTextByte(pattern: []const u8) bool {
        for (pattern) |ch| {
            if (!std.ascii.isWhitespace(ch) and !std.ascii.isControl(ch)) return true;
        }
        return false;
    }

    fn containsWhitespaceOrControl(pattern: []const u8) bool {
        for (pattern) |ch| {
            if (std.ascii.isWhitespace(ch) or std.ascii.isControl(ch)) return true;
        }
        return false;
    }

    fn simpleTrailingPercentPrefix(pattern: []const u8) ?[]const u8 {
        if (pattern.len < 2 or pattern[pattern.len - 1] != '%') return null;
        for (pattern[0 .. pattern.len - 1]) |ch| {
            if (ch == '%' or ch == '_') return null;
        }
        return pattern[0 .. pattern.len - 1];
    }

    fn textSidecarNamesForFieldAlloc(
        alloc: std.mem.Allocator,
        sidecars: []const lake_sidecar_manifest.DeclaredArtifact,
        field: []const u8,
    ) ![]const []const u8 {
        var matched_name: ?[]const u8 = null;
        for (sidecars) |sidecar| {
            if (sidecar.binding.sidecar_kind != .text) continue;
            if (!stringSliceContains(sidecar.binding.column_bindings, field)) continue;
            if (matched_name != null) return error.AmbiguousLakeSidecarCandidateSource;
            matched_name = sidecar.name;
        }
        const name = matched_name orelse return try alloc.alloc([]const u8, 0);
        const names = try alloc.alloc([]const u8, 1);
        names[0] = name;
        return names;
    }

    fn lakeSidecarCandidatePlanningErrorResponse(
        self: *ApiHttpServer,
        err: anyerror,
    ) !http_common.HttpResponse {
        return switch (err) {
            error.InvalidLakeSidecarCandidateRequest,
            error.MissingLakeSidecarCandidateSource,
            error.AmbiguousLakeSidecarCandidateSource,
            error.InvalidSidecarRowRefKey,
            => try textResponse(self.alloc, 400, "invalid lake sidecar candidate request"),
            error.StaleLakeSidecar,
            error.SidecarSourceBindingMismatch,
            => try textResponse(self.alloc, 409, "lake sidecar snapshot mismatch"),
            error.UnsupportedLakeSidecarCandidateSource,
            => try textResponse(self.alloc, 501, "lake sidecar candidate unavailable"),
            else => err,
        };
    }

    fn appendOwnedCandidateSetsIntersectingDuplicatesAlloc(
        alloc: std.mem.Allocator,
        out: *std.ArrayListUnmanaged(serverless_query.LakeOwnedSidecarCandidateSet),
        incoming: []const serverless_query.LakeOwnedSidecarCandidateSet,
    ) !void {
        for (incoming) |candidate_set| {
            if (ownedCandidateSetIndexByName(out.items, candidate_set.sidecar_name)) |existing_idx| {
                const intersected = try intersectOwnedRowRefsAlloc(
                    alloc,
                    out.items[existing_idx].row_refs,
                    candidate_set.row_refs,
                );
                lake_source_binding_api.freeOwnedRowRefs(alloc, out.items[existing_idx].row_refs);
                out.items[existing_idx].row_refs = intersected;
                continue;
            }
            var cloned = try cloneOwnedCandidateSetAlloc(alloc, candidate_set);
            errdefer cloned.deinit(alloc);
            try out.append(alloc, cloned);
        }
    }

    fn appendOwnedCandidateSetsUnioningDuplicatesAlloc(
        alloc: std.mem.Allocator,
        out: *std.ArrayListUnmanaged(serverless_query.LakeOwnedSidecarCandidateSet),
        incoming: []const serverless_query.LakeOwnedSidecarCandidateSet,
    ) !void {
        for (incoming) |candidate_set| {
            if (ownedCandidateSetIndexByName(out.items, candidate_set.sidecar_name)) |existing_idx| {
                const unioned = try unionOwnedRowRefsAlloc(
                    alloc,
                    out.items[existing_idx].row_refs,
                    candidate_set.row_refs,
                );
                lake_source_binding_api.freeOwnedRowRefs(alloc, out.items[existing_idx].row_refs);
                out.items[existing_idx].row_refs = unioned;
                continue;
            }
            var cloned = try cloneOwnedCandidateSetAlloc(alloc, candidate_set);
            errdefer cloned.deinit(alloc);
            try out.append(alloc, cloned);
        }
    }

    fn deinitOwnedCandidateSetList(
        alloc: std.mem.Allocator,
        list: *std.ArrayListUnmanaged(serverless_query.LakeOwnedSidecarCandidateSet),
    ) void {
        for (list.items) |*set| set.deinit(alloc);
        list.deinit(alloc);
        list.* = .empty;
    }

    fn ownedCandidateSetIndexByName(
        values: []const serverless_query.LakeOwnedSidecarCandidateSet,
        name: []const u8,
    ) ?usize {
        for (values, 0..) |value, idx| {
            if (std.mem.eql(u8, value.sidecar_name, name)) return idx;
        }
        return null;
    }

    fn cloneOwnedCandidateSetAlloc(
        alloc: std.mem.Allocator,
        source: serverless_query.LakeOwnedSidecarCandidateSet,
    ) !serverless_query.LakeOwnedSidecarCandidateSet {
        const sidecar_name = try alloc.dupe(u8, source.sidecar_name);
        errdefer alloc.free(sidecar_name);
        return .{
            .sidecar_name = sidecar_name,
            .row_refs = try cloneRowRefsAlloc(alloc, source.row_refs),
        };
    }

    fn cloneRowRefsAlloc(
        alloc: std.mem.Allocator,
        row_refs: []const rowsource_api.RowRef,
    ) ![]rowsource_api.RowRef {
        const out = try alloc.alloc(rowsource_api.RowRef, row_refs.len);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |row_ref| lake_source_binding_api.freeOwnedRowRef(alloc, row_ref);
            alloc.free(out);
        }
        for (row_refs, 0..) |row_ref, idx| {
            out[idx] = try cloneRowRefAlloc(alloc, row_ref);
            initialized += 1;
        }
        return out;
    }

    fn intersectOwnedRowRefsAlloc(
        alloc: std.mem.Allocator,
        lhs: []const rowsource_api.RowRef,
        rhs: []const rowsource_api.RowRef,
    ) ![]rowsource_api.RowRef {
        var out = std.ArrayListUnmanaged(rowsource_api.RowRef).empty;
        errdefer {
            for (out.items) |row_ref| lake_source_binding_api.freeOwnedRowRef(alloc, row_ref);
            out.deinit(alloc);
        }
        for (lhs) |row_ref| {
            if (!rowRefSliceContains(rhs, row_ref)) continue;
            if (rowRefSliceContains(out.items, row_ref)) continue;
            try out.append(alloc, try cloneRowRefAlloc(alloc, row_ref));
        }
        return try out.toOwnedSlice(alloc);
    }

    fn unionOwnedRowRefsAlloc(
        alloc: std.mem.Allocator,
        lhs: []const rowsource_api.RowRef,
        rhs: []const rowsource_api.RowRef,
    ) ![]rowsource_api.RowRef {
        var out = std.ArrayListUnmanaged(rowsource_api.RowRef).empty;
        errdefer {
            for (out.items) |row_ref| lake_source_binding_api.freeOwnedRowRef(alloc, row_ref);
            out.deinit(alloc);
        }
        for (lhs) |row_ref| {
            if (rowRefSliceContains(out.items, row_ref)) continue;
            try out.append(alloc, try cloneRowRefAlloc(alloc, row_ref));
        }
        for (rhs) |row_ref| {
            if (rowRefSliceContains(out.items, row_ref)) continue;
            try out.append(alloc, try cloneRowRefAlloc(alloc, row_ref));
        }
        return try out.toOwnedSlice(alloc);
    }

    fn cloneRowRefAlloc(
        alloc: std.mem.Allocator,
        row_ref: rowsource_api.RowRef,
    ) !rowsource_api.RowRef {
        const key = try lake_source_binding_api.rowRefKeyAlloc(alloc, row_ref);
        defer alloc.free(key);
        return try lake_source_binding_api.rowRefFromKeyAlloc(alloc, key);
    }

    fn rowRefSliceContains(values: []const rowsource_api.RowRef, needle: rowsource_api.RowRef) bool {
        for (values) |value| {
            if (rowRefsEqual(value, needle)) return true;
        }
        return false;
    }

    fn rowRefsEqual(lhs: rowsource_api.RowRef, rhs: rowsource_api.RowRef) bool {
        if (std.meta.activeTag(lhs) != std.meta.activeTag(rhs)) return false;
        return switch (lhs) {
            .relational_key => |lhs_key| std.mem.eql(u8, lhs_key, rhs.relational_key),
            .serverless => |lhs_ref| std.mem.eql(u8, lhs_ref.fragment_id, rhs.serverless.fragment_id) and
                lhs_ref.row_ordinal == rhs.serverless.row_ordinal,
            .external => |lhs_ref| std.mem.eql(u8, lhs_ref.source_id, rhs.external.source_id) and
                std.mem.eql(u8, lhs_ref.snapshot_id, rhs.external.snapshot_id) and
                std.mem.eql(u8, lhs_ref.file_id, rhs.external.file_id) and
                lhs_ref.row_group_ordinal == rhs.external.row_group_ordinal and
                lhs_ref.row_ordinal == rhs.external.row_ordinal,
        };
    }

    fn concatCandidateSetsAlloc(
        alloc: std.mem.Allocator,
        lhs: []const serverless_query.LakeRowsSidecarCandidateSet,
        rhs: []const serverless_query.LakeRowsSidecarCandidateSet,
    ) ![]serverless_query.LakeRowsSidecarCandidateSet {
        const out = try alloc.alloc(serverless_query.LakeRowsSidecarCandidateSet, lhs.len + rhs.len);
        @memcpy(out[0..lhs.len], lhs);
        @memcpy(out[lhs.len..], rhs);
        return out;
    }

    fn concatDesiredSidecarsAlloc(
        alloc: std.mem.Allocator,
        lhs: []const serverless_query.LakeSidecarDesired,
        rhs: []const serverless_query.LakeSidecarDesired,
    ) ![]serverless_query.LakeSidecarDesired {
        var out = std.ArrayListUnmanaged(serverless_query.LakeSidecarDesired).empty;
        errdefer out.deinit(alloc);
        try out.ensureTotalCapacity(alloc, lhs.len + rhs.len);
        for (lhs) |item| out.appendAssumeCapacity(item);
        for (rhs) |item| {
            if (desiredSidecarsContainName(out.items, item.name)) continue;
            out.appendAssumeCapacity(item);
        }
        return try out.toOwnedSlice(alloc);
    }

    fn desiredSidecarsContainName(values: []const serverless_query.LakeSidecarDesired, name: []const u8) bool {
        for (values) |value| {
            if (std.mem.eql(u8, value.name, name)) return true;
        }
        return false;
    }

    pub fn handlePublicTableRowsSource(
        self: *ApiHttpServer,
        table_name: []const u8,
    ) !http_common.HttpResponse {
        const schema = self.runtimeSchemaForPublicRows(table_name) catch |err| switch (err) {
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.InvalidRowsRequest => return try textResponse(self.alloc, 400, "invalid rows request"),
            else => return err,
        };
        defer runtime_schema_mod.freeSchema(self.alloc, schema);

        var lake_source = self.openPublicExternalLakeRowsSourceAlloc(schema) catch |err| switch (err) {
            error.UnsupportedRowsQuery, error.UnsupportedExternalLakeCredentialRef, error.EmptyExternalSourceSnapshot => return try textResponse(self.alloc, 501, "rows source unavailable"),
            error.ExternalLakeCredentialRefNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.ExternalLakeCredentialScopeMismatch => return try textResponse(self.alloc, 403, "forbidden"),
            error.InvalidRowsRequest => return try textResponse(self.alloc, 404, "not found"),
            error.ExternalLakeSnapshotMismatch => return try textResponse(self.alloc, 409, "external lake snapshot mismatch"),
            else => return err,
        };
        defer lake_source.deinit();

        const state = lake_source.pinnedState();
        const Source = struct {
            kind: []const u8 = "external_lake",
            format: []const u8,
            source_uri: []const u8,
            snapshot_id: []const u8,
            schema_fingerprint: []const u8,
            file_count: usize,
            row_group_count: usize,
            row_count: u64,
            byte_len: u64,
        };
        const Response = struct {
            source: Source,
        };
        return try jsonResponse(self.alloc, Response{ .source = .{
            .format = @tagName(state.format),
            .source_uri = state.source_uri,
            .snapshot_id = state.snapshot_id,
            .schema_fingerprint = state.schema_fingerprint,
            .file_count = state.file_count,
            .row_group_count = state.row_group_count,
            .row_count = state.row_count,
            .byte_len = state.byte_len,
        } });
    }

    pub fn handlePublicTableRowsExplain(
        self: *ApiHttpServer,
        table_name: []const u8,
        body: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !http_common.HttpResponse {
        const schema = self.runtimeSchemaForPublicRows(table_name) catch |err| switch (err) {
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.InvalidRowsRequest => return try textResponse(self.alloc, 400, "invalid rows request"),
            else => return err,
        };
        defer runtime_schema_mod.freeSchema(self.alloc, schema);

        var sidecar_request_context = self.externalLakeSidecarContextForRowsExplainAlloc(schema, body, authenticated_identity, table_name) catch |err| switch (err) {
            error.InvalidRowsRequest => return try textResponse(self.alloc, 400, "invalid rows explain request"),
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return try textResponse(self.alloc, 403, "row filter pushdown required"),
            else => return try self.lakeSidecarCandidatePlanningErrorResponse(err),
        };
        defer sidecar_request_context.deinit(self.alloc);
        var lake_source = self.openPublicExternalLakeRowsSourceWithOptionsAlloc(
            schema,
            self.externalLakeRowsSourceOptionsWithSidecarContext(sidecar_request_context.context()),
        ) catch |err| switch (err) {
            error.UnsupportedRowsQuery, error.UnsupportedExternalLakeCredentialRef, error.EmptyExternalSourceSnapshot => return try textResponse(self.alloc, 501, "rows explain unavailable"),
            error.ExternalLakeCredentialRefNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.ExternalLakeCredentialScopeMismatch => return try textResponse(self.alloc, 403, "forbidden"),
            error.InvalidRowsRequest => return try textResponse(self.alloc, 404, "not found"),
            error.ExternalLakeSnapshotMismatch => return try textResponse(self.alloc, 409, "external lake snapshot mismatch"),
            else => return err,
        };
        defer lake_source.deinit();

        const state = lake_source.pinnedState();
        var explained = self.explainLakeRowsOperationAlloc(schema, body, authenticated_identity, table_name) catch |err| switch (err) {
            error.InvalidRowsRequest => return try textResponse(self.alloc, 400, "invalid rows explain request"),
            error.UnsupportedRowsQuery => return try textResponse(self.alloc, 501, "rows explain unavailable"),
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return try textResponse(self.alloc, 403, "row filter pushdown required"),
            else => return err,
        };
        defer explained.deinit(self.alloc);
        const physical_scan = lake_source.explainProjectedScanSummaryAlloc(self.alloc, schema, explained.physical_columns) catch |err| switch (err) {
            error.InvalidLakeScanPlan,
            error.InvalidRowsRequest,
            error.InvalidLakeRangeRead,
            error.InvalidParquetRowGroupBatch,
            => return try textResponse(self.alloc, 400, "invalid rows explain request"),
            error.ExternalLakeSnapshotMismatch => return try textResponse(self.alloc, 409, "external lake snapshot mismatch"),
            else => return err,
        };
        const sidecar_context = lake_source.sidecarContext();
        const sidecar_artifacts = try lakeSidecarArtifactsAlloc(self.alloc, sidecar_context.sidecars);
        defer if (sidecar_artifacts.len > 0) self.alloc.free(sidecar_artifacts);
        const plan = try serverless_query.explainLakeQuery(.{
            .base_source = externalLakeBaseSourceDescriptor(state),
            .artifacts = sidecar_artifacts,
            .sidecars = sidecar_context.sidecars,
            .desired_sidecars = sidecar_context.desired_sidecars,
            .sidecar_policy = sidecar_context.sidecar_policy,
            .candidate_sets = sidecar_context.candidates,
            .operation = explained.operation,
            .projected_column_count = explained.projected_column_count,
            .range_cache_stats = lake_source.rangeCacheStats(),
        });
        const Source = struct {
            kind: []const u8 = "external_lake",
            format: []const u8,
            source_uri: []const u8,
            snapshot_id: []const u8,
            schema_fingerprint: []const u8,
            file_count: usize,
            row_group_count: usize,
            row_count: u64,
            byte_len: u64,
        };
        const Response = struct {
            source: Source,
            explained_operation: []const u8,
            scan: LakeRowsExplainScan,
            physical_scan: table_reads.ExternalLakePhysicalScanSummary,
            plan: serverless_query.LakeExplainPlan,
        };
        return try jsonResponse(self.alloc, Response{
            .source = .{
                .format = @tagName(state.format),
                .source_uri = state.source_uri,
                .snapshot_id = state.snapshot_id,
                .schema_fingerprint = state.schema_fingerprint,
                .file_count = state.file_count,
                .row_group_count = state.row_group_count,
                .row_count = state.row_count,
                .byte_len = state.byte_len,
            },
            .explained_operation = explained.operation_name,
            .scan = explained.scan,
            .physical_scan = physical_scan,
            .plan = plan,
        });
    }

    const LakeRowsExplainScan = struct {
        projected_column_count: u16 = 0,
        has_predicate: bool = false,
        scanner_limit: ?usize = null,
    };

    const LakeRowsExplainedOperation = struct {
        operation_name: []const u8 = "source",
        operation: serverless_query.LakeExplainOperation = .scan,
        projected_column_count: u16 = 0,
        scan: LakeRowsExplainScan = .{},
        projected_columns: []const []const u8 = &.{},
        physical_columns: []const []const u8 = &.{},

        pub fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            for (self.projected_columns) |column| alloc.free(@constCast(column));
            if (self.projected_columns.len > 0) alloc.free(self.projected_columns);
            for (self.physical_columns) |column| alloc.free(@constCast(column));
            if (self.physical_columns.len > 0) alloc.free(self.physical_columns);
            self.* = undefined;
        }
    };

    fn explainLakeRowsOperationAlloc(
        self: *ApiHttpServer,
        schema: runtime_schema_mod.TableSchema,
        body: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        table_name: []const u8,
    ) !LakeRowsExplainedOperation {
        if (std.mem.trim(u8, body, " \t\r\n").len == 0) return .{};
        const operation = relational_rows_api.detectRowsPlanOperationWithoutSchema(self.alloc, body) catch return error.InvalidRowsRequest;
        return switch (operation) {
            .query => blk: {
                var plan = relational_rows_api.parseRowsQueryPlanRequest(self.alloc, body, schema) catch return error.InvalidRowsRequest;
                defer plan.deinit(self.alloc);
                try self.applyRowsQueryPlanRowFilter(table_name, authenticated_identity, schema, &plan);
                var lake_request = try relational_rows_api.buildLakeRowsScanRequestForRowsQueryAlloc(self.alloc, schema, plan.query);
                defer lake_request.deinit(self.alloc);
                break :blk try lakeRowsExplainedOperationFromScan(self.alloc, "query", .scan, lake_request.request);
            },
            .aggregate => blk: {
                var plan = relational_rows_api.parseRowsAggregatePlanRequest(self.alloc, body, schema) catch return error.InvalidRowsRequest;
                defer plan.deinit(self.alloc);
                try self.applyRowsAggregatePlanRowFilter(table_name, authenticated_identity, schema, &plan);
                var lake_request = try relational_rows_api.buildLakeRowsScanRequestForRowsAggregateAlloc(self.alloc, schema, plan.aggregate);
                defer lake_request.deinit(self.alloc);
                break :blk try lakeRowsExplainedOperationFromScan(self.alloc, "aggregate", .group_by, lake_request.request);
            },
            .window, .join, .lateral => error.UnsupportedRowsQuery,
        };
    }

    fn lakeRowsExplainedOperationFromScan(
        alloc: std.mem.Allocator,
        operation_name: []const u8,
        operation: serverless_query.LakeExplainOperation,
        scan: serverless_query.LakeRowsScanRequest,
    ) !LakeRowsExplainedOperation {
        const projected_column_count = std.math.cast(u16, scan.projected_columns.len) orelse return error.InvalidRowsRequest;
        const projected_columns = try cloneStringSlice(alloc, scan.projected_columns);
        errdefer freeStringSlice(alloc, projected_columns);
        const physical_columns = try clonePhysicalScanColumns(alloc, scan);
        errdefer freeStringSlice(alloc, physical_columns);
        return .{
            .operation_name = operation_name,
            .operation = operation,
            .projected_column_count = projected_column_count,
            .scan = .{
                .projected_column_count = projected_column_count,
                .has_predicate = scan.predicate != null,
                .scanner_limit = scan.limit,
            },
            .projected_columns = projected_columns,
            .physical_columns = physical_columns,
        };
    }

    fn clonePhysicalScanColumns(
        alloc: std.mem.Allocator,
        scan: serverless_query.LakeRowsScanRequest,
    ) ![]const []const u8 {
        const predicate_column = if (scan.predicate) |predicate| predicate.column else null;
        const append_predicate = if (predicate_column) |column|
            !stringSliceContains(scan.projected_columns, column)
        else
            false;
        if (scan.projected_columns.len == 0 and !append_predicate) return &.{};

        const column_count = scan.projected_columns.len + @intFromBool(append_predicate);
        const out = try alloc.alloc([]const u8, column_count);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |value| alloc.free(@constCast(value));
            alloc.free(out);
        }
        for (scan.projected_columns) |value| {
            out[initialized] = try alloc.dupe(u8, value);
            initialized += 1;
        }
        if (append_predicate) {
            out[initialized] = try alloc.dupe(u8, predicate_column.?);
            initialized += 1;
        }
        return out;
    }

    fn lakeSidecarArtifactsAlloc(
        alloc: std.mem.Allocator,
        sidecars: []const lake_sidecar_manifest.DeclaredArtifact,
    ) ![]lake_artifact_ref.ArtifactRef {
        if (sidecars.len == 0) return &.{};
        const artifacts = try alloc.alloc(lake_artifact_ref.ArtifactRef, sidecars.len);
        for (sidecars, 0..) |sidecar, idx| {
            artifacts[idx] = sidecar.artifact;
        }
        return artifacts;
    }

    fn stringSliceContains(values: []const []const u8, needle: []const u8) bool {
        for (values) |value| {
            if (std.mem.eql(u8, value, needle)) return true;
        }
        return false;
    }

    fn cloneStringSlice(alloc: std.mem.Allocator, values: []const []const u8) ![]const []const u8 {
        if (values.len == 0) return &.{};
        const out = try alloc.alloc([]const u8, values.len);
        var initialized: usize = 0;
        errdefer {
            for (out[0..initialized]) |value| alloc.free(@constCast(value));
            alloc.free(out);
        }
        for (values, out) |value, *slot| {
            slot.* = try alloc.dupe(u8, value);
            initialized += 1;
        }
        return out;
    }

    fn freeStringSlice(alloc: std.mem.Allocator, values: []const []const u8) void {
        for (values) |value| alloc.free(@constCast(value));
        if (values.len > 0) alloc.free(values);
    }

    fn externalLakeBaseSourceDescriptor(
        state: table_reads.ExternalLakePinnedSourceState,
    ) lake_base_source.BaseSourceDescriptor {
        const source = lake_base_source.ExternalBaseSource{
            .format = switch (state.format) {
                .parquet => .parquet_prefix,
                .iceberg => .iceberg,
                .lance => .lance,
            },
            .source_uri = state.source_uri,
            .snapshot_id = state.snapshot_id,
            .schema_fingerprint = state.schema_fingerprint,
        };
        return switch (state.format) {
            .parquet => .{ .external_parquet = source },
            .iceberg => .{ .external_iceberg = source },
            .lance => .{ .external_lance = source },
        };
    }

    pub fn handlePublicTableRowsQuery(
        self: *ApiHttpServer,
        table_name: []const u8,
        body: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
    ) !http_common.HttpResponse {
        const schema = self.runtimeSchemaForPublicRows(table_name) catch |err| switch (err) {
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.InvalidRowsRequest => return try textResponse(self.alloc, 400, "invalid rows request"),
            else => return err,
        };
        defer runtime_schema_mod.freeSchema(self.alloc, schema);

        var plan = relational_rows_api.parseRowsQueryPlanRequest(self.alloc, body, schema) catch return try textResponse(self.alloc, 400, "invalid rows query request");
        defer plan.deinit(self.alloc);
        self.applyRowsQueryPlanRowFilter(table_name, authenticated_identity, schema, &plan) catch |err| switch (err) {
            error.UnsupportedRowsFilter, error.InvalidRowsFilter => return try textResponse(self.alloc, 403, "row filter pushdown required"),
            else => return err,
        };
        const result_schema = relational_rows_api.rowsReadPlanOutputColumnsAlloc(self.alloc, schema, .{ .query = plan }) catch return try textResponse(self.alloc, 400, "invalid rows query request");
        defer relational_rows_api.freeRowsOutputColumns(self.alloc, result_schema);

        var sidecar_context = if (schema.external_base_source != null)
            self.externalLakeSidecarContextForRowsQueryAlloc(plan.query) catch |err| return try self.lakeSidecarCandidatePlanningErrorResponse(err)
        else
            OwnedExternalLakeSidecarRequestContext{ .base = self.cfg.external_lake_sidecar_context };
        defer sidecar_context.deinit(self.alloc);
        var lake_source: ?table_reads.OpenedExternalObjectStorageLakeRowsSource = null;
        defer if (lake_source) |*source| source.deinit();
        const source = if (schema.external_base_source != null) blk: {
            lake_source = self.openPublicExternalLakeRowsSourceWithOptionsAlloc(
                schema,
                self.externalLakeRowsSourceOptionsWithSidecarContext(sidecar_context.context()),
            ) catch |err| switch (err) {
                error.UnsupportedRowsQuery, error.UnsupportedExternalLakeCredentialRef, error.EmptyExternalSourceSnapshot => return try textResponse(self.alloc, 501, "rows query plan unavailable"),
                error.ExternalLakeCredentialRefNotFound => return try textResponse(self.alloc, 404, "not found"),
                error.ExternalLakeCredentialScopeMismatch => return try textResponse(self.alloc, 403, "forbidden"),
                error.InvalidRowsRequest => return try textResponse(self.alloc, 404, "not found"),
                error.ExternalLakeSnapshotMismatch => return try textResponse(self.alloc, 409, "external lake snapshot mismatch"),
                else => return err,
            };
            break :blk lake_source.?.source();
        } else self.effectivePublicTableReads() orelse return try textResponse(self.alloc, 404, "not found");

        var result = (source.rowsQueryPlan(self.alloc, table_name, schema, plan, .read_index) catch |err| switch (err) {
            error.InvalidArgument, error.InvalidQueryRequest, error.UnsupportedQueryRequest, error.RelationalRowsCteMaterializationRejected => return try textResponse(self.alloc, 400, "invalid rows query request"),
            error.RelationalIndexUnavailable,
            error.RelationalIndexStale,
            error.RelationalIndexMalformed,
            error.RelationalIndexPlanTooExpensive,
            error.RelationalIndexUnsupportedShape,
            => return try relationalRowsPlannerFallbackErrorResponse(self.alloc, err),
            error.RelationalRowsCteSpillRequired => return try textResponse(self.alloc, 429, "rows query backpressured"),
            error.UnsupportedOperation, error.UnsupportedRowsQuery, error.EmptyExternalSourceSnapshot => return try textResponse(self.alloc, 501, "rows query plan unavailable"),
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.TopologyChanged => return try textResponse(self.alloc, 503, "topology changed"),
            error.LeaderUnavailable, error.ReadUnavailable => return try textResponse(self.alloc, 503, "read unavailable"),
            error.ExternalLakeSnapshotMismatch => return try textResponse(self.alloc, 409, "external lake snapshot mismatch"),
            else => {
                std.log.err("public table rows query failed table={s} err={}", .{ table_name, err });
                return try textResponse(self.alloc, 500, "rows query failed");
            },
        }) orelse return try textResponse(self.alloc, 404, "not found");
        defer result.deinit(self.alloc);
        const response_body = try relational_rows_api.encodeRowsQueryResponseWithSchemaAlloc(self.alloc, result, result_schema);
        defer self.alloc.free(response_body);
        return try jsonBodyResponseWithStatus(self.alloc, 200, response_body);
    }

