    }

    fn applyRowsLateralPlanRowFilterWithSchemas(
        self: *ApiHttpServer,
        cte_table_name: []const u8,
        left_table_name: []const u8,
        right_table_name: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        cte_schema: runtime_schema_mod.TableSchema,
        left_schema: runtime_schema_mod.TableSchema,
        right_schema: runtime_schema_mod.TableSchema,
        plan: *relational_rows_api.OwnedRowsLateralPlan,
    ) !void {
        try ensureRowsPlanTableReadable(authenticated_identity, left_table_name);
        try ensureRowsPlanTableReadable(authenticated_identity, right_table_name);
        try validateRowsPlanCteSideTable(cte_table_name, left_table_name, plan.lateral.left);
        try validateRowsPlanCteSideTable(cte_table_name, right_table_name, plan.lateral.right);

        var cte_filter = try self.rowsAuthFilterPlanForIdentity(cte_table_name, authenticated_identity, cte_schema);
        defer if (cte_filter) |*value| value.deinit(self.alloc);
        if (cte_filter) |active| {
            for (@constCast(plan.ctes)) |*cte| try self.applyRowsAuthFilterToQuery(cte_schema, active, &cte.query);
        }
        if (plan.lateral.left.source_cte.len == 0) {
            var left_filter = try self.rowsAuthFilterPlanForIdentity(left_table_name, authenticated_identity, left_schema);
            defer if (left_filter) |*value| value.deinit(self.alloc);
            if (left_filter) |active| try self.applyRowsAuthFilterToQuery(left_schema, active, &plan.lateral.left);
        }
        if (plan.lateral.right.source_cte.len == 0) {
            var right_filter = try self.rowsAuthFilterPlanForIdentity(right_table_name, authenticated_identity, right_schema);
            defer if (right_filter) |*value| value.deinit(self.alloc);
            if (right_filter) |active| try self.applyRowsAuthFilterToQuery(right_schema, active, &plan.lateral.right);
        }
    }

    fn rowsAuthFilterPlanForIdentity(
        self: *ApiHttpServer,
        table_name: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        schema: runtime_schema_mod.TableSchema,
    ) !?RowsAuthFilterPlan {
        return try self.rowsAuthFilterPlanForIdentityInDatabase(tables_api.default_database_name, table_name, authenticated_identity, schema);
    }

    fn rowsAuthFilterPlanForTarget(
        self: *ApiHttpServer,
        target: catalog_resources.TableTarget,
        authenticated_identity: ?AuthenticatedIdentity,
        schema: runtime_schema_mod.TableSchema,
    ) !?RowsAuthFilterPlan {
        const resource_name = try catalog_resources.tableResourceNameAlloc(self.alloc, target.database_name, target.namespace_name, target.table_name);
        defer self.alloc.free(resource_name);
        return try self.rowsAuthFilterPlanForIdentityInDatabase(target.database_name, resource_name, authenticated_identity, schema);
    }

    fn rowsAuthFilterPlanForIdentityInDatabase(
        self: *ApiHttpServer,
        database_name: []const u8,
        table_name: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        schema: runtime_schema_mod.TableSchema,
    ) !?RowsAuthFilterPlan {
        const row_filter_json = try self.resolveEffectiveRowFilterJsonForDatabase(self.alloc, authenticated_identity, database_name, table_name);
        defer if (row_filter_json) |value| self.alloc.free(value);
        const json = row_filter_json orelse return null;
        var parsed = std.json.parseFromSlice(std.json.Value, self.alloc, json, .{
            .allocate = .alloc_always,
        }) catch return error.InvalidRowsFilter;
        defer parsed.deinit();
        var filter = try self.rowsAuthFilterPlanFromValue(schema, parsed.value);
        errdefer filter.deinit(self.alloc);
        return filter;
    }

    fn applyRowsQueryRequestRowFilterForDatabase(
        self: *ApiHttpServer,
        database_name: []const u8,
        table_name: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        schema: runtime_schema_mod.TableSchema,
        query: *relational_rows_api.OwnedRowsQueryRequest,
    ) !void {
        var filter = try self.rowsAuthFilterPlanForIdentityInDatabase(database_name, table_name, authenticated_identity, schema);
        defer if (filter) |*value| value.deinit(self.alloc);
        const active = filter orelse return;
        try self.applyRowsAuthFilterToQuery(schema, active, query);
    }

    fn rowsAuthFilterPlanFromValue(
        self: *ApiHttpServer,
        schema: runtime_schema_mod.TableSchema,
        value: std.json.Value,
    ) !RowsAuthFilterPlan {
        var filter = RowsAuthFilterBuilder{};
        errdefer filter.deinit(self.alloc);
        try self.appendRowsAuthFilterValue(schema, value, &filter);
        return try filter.toOwnedPlan(self.alloc);
    }

    const RowsAuthFilterBuilder = struct {
        predicates: std.ArrayListUnmanaged(runtime_schema_mod.RelationalCheck) = .empty,
        array_any: std.ArrayListUnmanaged(db_mod.types.RelationalRowsArrayAnyPredicate) = .empty,
        in_predicates: std.ArrayListUnmanaged(db_mod.types.RelationalRowsInPredicate) = .empty,
        json_contains: std.ArrayListUnmanaged(db_mod.types.RelationalRowsJsonContainsPredicate) = .empty,
        expression_predicates: std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionCondition) = .empty,
        access_or_predicates: std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup) = .empty,
        expression_or_predicates: std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup) = .empty,

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            freeRowsAuthPredicates(alloc, self.predicates.items);
            self.predicates.deinit(alloc);
            for (self.array_any.items) |predicate| {
                alloc.free(predicate.field);
                alloc.free(predicate.value_json);
            }
            self.array_any.deinit(alloc);
            for (self.in_predicates.items) |predicate| {
                alloc.free(predicate.field);
                alloc.free(predicate.values_json);
                if (predicate.collation) |collation| alloc.free(collation);
            }
            self.in_predicates.deinit(alloc);
            for (self.json_contains.items) |predicate| {
                alloc.free(predicate.field);
                alloc.free(predicate.value_json);
            }
            self.json_contains.deinit(alloc);
            for (self.expression_predicates.items) |condition| {
                runtime_schema_mod.freeRelationalRowsExpressionCondition(alloc, condition);
            }
            self.expression_predicates.deinit(alloc);
            freeRowsAuthAccessPredicateGroups(alloc, self.access_or_predicates.items);
            self.access_or_predicates.deinit(alloc);
            freeRowsAuthExpressionPredicateGroupsNoSlice(alloc, self.expression_or_predicates.items);
            self.expression_or_predicates.deinit(alloc);
            self.* = undefined;
        }

        fn empty(self: @This()) bool {
            return self.predicates.items.len == 0 and
                self.array_any.items.len == 0 and
                self.in_predicates.items.len == 0 and
                self.json_contains.items.len == 0 and
                self.expression_predicates.items.len == 0 and
                self.access_or_predicates.items.len == 0 and
                self.expression_or_predicates.items.len == 0;
        }

        fn toOwnedPlan(self: *@This(), alloc: std.mem.Allocator) !RowsAuthFilterPlan {
            return .{
                .predicates = try self.predicates.toOwnedSlice(alloc),
                .array_any = try self.array_any.toOwnedSlice(alloc),
                .in_predicates = try self.in_predicates.toOwnedSlice(alloc),
                .json_contains = try self.json_contains.toOwnedSlice(alloc),
                .expression_predicates = try self.expression_predicates.toOwnedSlice(alloc),
                .access_or_predicates = try self.access_or_predicates.toOwnedSlice(alloc),
                .expression_or_predicates = try self.expression_or_predicates.toOwnedSlice(alloc),
            };
        }
    };

    fn appendRowsAuthFilterValue(
        self: *ApiHttpServer,
        schema: runtime_schema_mod.TableSchema,
        value: std.json.Value,
        filter: *RowsAuthFilterBuilder,
    ) anyerror!void {
        if (value != .object) return error.InvalidRowsFilter;
        if (value.object.get("match_all") != null) return;
        if (value.object.get("match_none") != null) return error.UnsupportedRowsFilter;
        if (value.object.get("doc_id") != null) return error.UnsupportedRowsFilter;

        if (value.object.get("disjuncts")) |disjuncts| return try self.appendRowsAuthDisjunctsFilter(schema, disjuncts, filter);

        if (value.object.get("conjuncts")) |conjuncts| {
            if (conjuncts != .array) return error.InvalidRowsFilter;
            for (conjuncts.array.items) |item| try self.appendRowsAuthFilterValue(schema, item, filter);
            return;
        }
        if (value.object.get("bool")) |bool_query| {
            if (bool_query != .object) return error.InvalidRowsFilter;
            if (bool_query.object.get("must_not") != null) return error.UnsupportedRowsFilter;
            var saw_supported = false;
            if (bool_query.object.get("must")) |must| {
                if (must != .array or must.array.items.len == 0) return error.InvalidRowsFilter;
                saw_supported = true;
                for (must.array.items) |item| try self.appendRowsAuthFilterValue(schema, item, filter);
            }
            if (bool_query.object.get("filter")) |must_filter| {
                if (must_filter != .array or must_filter.array.items.len == 0) return error.InvalidRowsFilter;
                saw_supported = true;
                for (must_filter.array.items) |item| try self.appendRowsAuthFilterValue(schema, item, filter);
            }
            if (bool_query.object.get("should")) |should| {
                if (!rowsAuthBoolMinimumShouldMatchIsOne(bool_query.object.get("minimum_should_match"))) return error.UnsupportedRowsFilter;
                saw_supported = true;
                try self.appendRowsAuthDisjunctsFilter(schema, should, filter);
            }
            if (!saw_supported) return error.InvalidRowsFilter;
            return;
        }

        if (value.object.get("term")) |term| return try self.appendRowsAuthTermFilter(schema, term, filter);
        if (value.object.get("terms")) |terms| return try self.appendRowsAuthTermsFilter(schema, terms, filter);
        if (value.object.get("array_any")) |array_any| return try self.appendRowsAuthArrayAnyFilter(schema, array_any, filter);
        if (value.object.get("json_contains")) |json_contains| return try self.appendRowsAuthJsonContainsFilter(schema, json_contains, filter);
        if (value.object.get("expression_where")) |expression_where| return try self.appendRowsAuthExpressionWhereFilter(schema, expression_where, filter);
        if (value.object.get("numeric_range")) |range_query| return try self.appendRowsAuthNumericRangeFilter(schema, range_query, filter);
        if (value.object.get("date_range")) |range_query| return try self.appendRowsAuthDateRangeFilter(schema, range_query, filter);

        if (value.object.get("match") != null or
            value.object.get("prefix") != null or
            value.object.get("wildcard") != null or
            value.object.get("regexp") != null or
            value.object.get("fuzzy") != null)
        {
            return error.UnsupportedRowsFilter;
        }
        return error.InvalidRowsFilter;
    }

    fn rowsAuthBoolMinimumShouldMatchIsOne(value: ?std.json.Value) bool {
        const raw = value orelse return true;
        return switch (raw) {
            .integer => |number| number == 1,
            .number_string => |text| std.mem.eql(u8, text, "1"),
            .string => |text| std.mem.eql(u8, text, "1"),
            else => false,
        };
    }

    fn appendRowsAuthDisjunctsFilter(
        self: *ApiHttpServer,
        schema: runtime_schema_mod.TableSchema,
        disjuncts: std.json.Value,
        filter: *RowsAuthFilterBuilder,
    ) !void {
        if (disjuncts != .array or disjuncts.array.items.len == 0) return error.InvalidRowsFilter;
        var access_groups: std.ArrayListUnmanaged(db_mod.types.RelationalRowsAccessPredicateGroup) = .empty;
        defer {
            freeRowsAuthAccessPredicateGroups(self.alloc, access_groups.items);
            access_groups.deinit(self.alloc);
        }
        var expression_groups: std.ArrayListUnmanaged(db_mod.types.RelationalRowsExpressionPredicateGroup) = .empty;
        defer {
            freeRowsAuthExpressionPredicateGroupsNoSlice(self.alloc, expression_groups.items);
            expression_groups.deinit(self.alloc);
        }

        for (disjuncts.array.items) |item| {
            var branch = RowsAuthFilterBuilder{};
            defer branch.deinit(self.alloc);
            try self.appendRowsAuthFilterValue(schema, item, &branch);
            if (branch.empty() or branch.access_or_predicates.items.len != 0 or branch.expression_or_predicates.items.len != 0) return error.UnsupportedRowsFilter;

            if (rowsAuthBuilderCanUseExpressionGroup(branch)) {
                try expression_groups.append(self.alloc, try rowsAuthExpressionPredicateGroupFromBuilder(self.alloc, &branch));
            } else {
                try access_groups.append(self.alloc, try rowsAuthAccessPredicateGroupFromBuilder(self.alloc, &branch));
            }
        }

        if (access_groups.items.len != 0 and expression_groups.items.len != 0) return error.UnsupportedRowsFilter;
        if (expression_groups.items.len != 0) {
            try filter.expression_or_predicates.appendSlice(self.alloc, expression_groups.items);
            expression_groups.clearRetainingCapacity();
            return;
        }
        try filter.access_or_predicates.appendSlice(self.alloc, access_groups.items);
        access_groups.clearRetainingCapacity();
    }

    fn rowsAuthBuilderCanUseExpressionGroup(builder: RowsAuthFilterBuilder) bool {
        return builder.expression_predicates.items.len != 0 or
            (builder.predicates.items.len != 0 and
                builder.array_any.items.len == 0 and
                builder.in_predicates.items.len == 0 and
                builder.json_contains.items.len == 0);
    }

    fn rowsAuthAccessPredicateGroupFromBuilder(
        alloc: std.mem.Allocator,
        builder: *RowsAuthFilterBuilder,
    ) !db_mod.types.RelationalRowsAccessPredicateGroup {
        return .{
            .predicates = try builder.predicates.toOwnedSlice(alloc),
            .array_any = try builder.array_any.toOwnedSlice(alloc),
            .in_predicates = try builder.in_predicates.toOwnedSlice(alloc),
            .json_contains = try builder.json_contains.toOwnedSlice(alloc),
        };
    }

    fn rowsAuthExpressionPredicateGroupFromBuilder(
        alloc: std.mem.Allocator,
        builder: *RowsAuthFilterBuilder,
    ) !db_mod.types.RelationalRowsExpressionPredicateGroup {
        if (builder.array_any.items.len != 0 or builder.in_predicates.items.len != 0 or builder.json_contains.items.len != 0) return error.UnsupportedRowsFilter;
        const conditions = try alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, builder.predicates.items.len + builder.expression_predicates.items.len);
        var initialized: usize = 0;
        errdefer {
            for (conditions[0..initialized]) |condition| runtime_schema_mod.freeRelationalRowsExpressionCondition(alloc, condition);
            alloc.free(conditions);
        }
        for (builder.predicates.items) |predicate| {
            conditions[initialized] = try rowsAuthExpressionConditionFromPredicateAlloc(alloc, predicate);
            initialized += 1;
        }
        for (builder.expression_predicates.items) |condition| {
            conditions[initialized] = try runtime_schema_mod.cloneRelationalRowsExpressionConditionAlloc(alloc, condition);
            initialized += 1;
        }
        return .{
            .conditions = conditions,
        };
    }

    fn rowsAuthExpressionConditionFromPredicateAlloc(
        alloc: std.mem.Allocator,
        predicate: runtime_schema_mod.RelationalCheck,
    ) !db_mod.types.RelationalRowsExpressionCondition {
        const value_json = predicate.value_json orelse return error.UnsupportedRowsFilter;
        const field = try alloc.dupe(u8, predicate.field);
        var field_transferred = false;
        errdefer if (!field_transferred) alloc.free(field);

        const rhs = try alloc.alloc(db_mod.types.RelationalRowsExpression, 1);
        var rhs_transferred = false;
        errdefer {
            if (!rhs_transferred) alloc.free(rhs);
        }
        rhs[0] = .{
            .kind = .value,
            .value_json = try alloc.dupe(u8, value_json),
        };
        errdefer if (!rhs_transferred) runtime_schema_mod.freeRelationalRowsExpression(alloc, rhs[0]);

        field_transferred = true;
        rhs_transferred = true;
        return .{
            .lhs = .{
                .kind = .field,
                .field = field,
                .field_source = .row,
            },
            .op = predicate.op,
            .rhs = rhs,
        };
    }

    fn appendRowsAuthTermFilter(
        self: *ApiHttpServer,
        schema: runtime_schema_mod.TableSchema,
        term: std.json.Value,
        filter: *RowsAuthFilterBuilder,
    ) !void {
        if (term != .object or term.object.count() != 1) return error.InvalidRowsFilter;
        var it = term.object.iterator();
        const entry = it.next() orelse return error.InvalidRowsFilter;
        if (entry.value_ptr.* != .string) return error.UnsupportedRowsFilter;
        const column = rowsAuthRelationalColumn(schema, entry.key_ptr.*) orelse return error.UnsupportedRowsFilter;
        const value_json = try self.rowsAuthTermValueJson(column, entry.value_ptr.string);
        var value_transferred = false;
        errdefer if (!value_transferred) self.alloc.free(value_json);
        const field = try self.alloc.dupe(u8, entry.key_ptr.*);
        errdefer self.alloc.free(field);
        try filter.predicates.append(self.alloc, .{
            .name = "",
            .field = field,
            .op = .eq,
            .value_json = value_json,
        });
        value_transferred = true;
    }

    fn appendRowsAuthTermsFilter(
        self: *ApiHttpServer,
        schema: runtime_schema_mod.TableSchema,
        terms: std.json.Value,
        filter: *RowsAuthFilterBuilder,
    ) !void {
        if (terms != .object or terms.object.count() != 1) return error.InvalidRowsFilter;
        var it = terms.object.iterator();
        const entry = it.next() orelse return error.InvalidRowsFilter;
        if (entry.value_ptr.* != .array or entry.value_ptr.array.items.len == 0) return error.InvalidRowsFilter;
        const column = rowsAuthRelationalColumn(schema, entry.key_ptr.*) orelse return error.UnsupportedRowsFilter;

        var out: std.Io.Writer.Allocating = .init(self.alloc);
        errdefer out.deinit();
        const writer = &out.writer;
        try writer.writeByte('[');
        for (entry.value_ptr.array.items, 0..) |item, i| {
            if (item != .string) return error.UnsupportedRowsFilter;
            const value_json = try self.rowsAuthTermValueJson(column, item.string);
            defer self.alloc.free(value_json);
            if (i != 0) try writer.writeByte(',');
            try writer.writeAll(value_json);
        }
        try writer.writeByte(']');
        const values_json = try out.toOwnedSlice();
        var values_transferred = false;
        errdefer if (!values_transferred) self.alloc.free(values_json);
        const field = try self.alloc.dupe(u8, entry.key_ptr.*);
        var field_transferred = false;
        errdefer if (!field_transferred) self.alloc.free(field);
        const collation = if (column.collation) |value| try self.alloc.dupe(u8, value) else null;
        var collation_transferred = false;
        errdefer if (!collation_transferred) if (collation) |value| self.alloc.free(value);
        try filter.in_predicates.append(self.alloc, .{
            .field = field,
            .values_json = values_json,
            .collation = collation,
        });
        field_transferred = true;
        values_transferred = true;
        collation_transferred = true;
    }

    fn appendRowsAuthArrayAnyFilter(
        self: *ApiHttpServer,
        schema: runtime_schema_mod.TableSchema,
        array_any: std.json.Value,
        filter: *RowsAuthFilterBuilder,
    ) !void {
        const parsed = try rowsAuthFieldJsonValue(array_any);
        const column = rowsAuthRelationalColumn(schema, parsed.field) orelse return error.UnsupportedRowsFilter;
        if (column.field_type != .array) return error.UnsupportedRowsFilter;
        const field = try self.alloc.dupe(u8, parsed.field);
        errdefer self.alloc.free(field);
        const value_json = try std.json.Stringify.valueAlloc(self.alloc, parsed.value, .{});
        errdefer self.alloc.free(value_json);
        try filter.array_any.append(self.alloc, .{
            .field = field,
            .value_json = value_json,
        });
    }

    fn appendRowsAuthJsonContainsFilter(
        self: *ApiHttpServer,
        schema: runtime_schema_mod.TableSchema,
        json_contains: std.json.Value,
        filter: *RowsAuthFilterBuilder,
    ) !void {
        const parsed = try rowsAuthFieldJsonValue(json_contains);
        const column = rowsAuthRelationalColumn(schema, parsed.field) orelse return error.UnsupportedRowsFilter;
        if (column.field_type != .json) return error.UnsupportedRowsFilter;
        const field = try self.alloc.dupe(u8, parsed.field);
        errdefer self.alloc.free(field);
        const value_json = try std.json.Stringify.valueAlloc(self.alloc, parsed.value, .{});
        errdefer self.alloc.free(value_json);
        try filter.json_contains.append(self.alloc, .{
