    fn cloneRowsAuthPredicate(alloc: std.mem.Allocator, predicate: runtime_schema_mod.RelationalCheck) !runtime_schema_mod.RelationalCheck {
        const field = try alloc.dupe(u8, predicate.field);
        errdefer alloc.free(field);
        const value_json = if (predicate.value_json) |value| try alloc.dupe(u8, value) else null;
        errdefer if (value_json) |value| alloc.free(value);
        const collation = if (predicate.collation) |value| try alloc.dupe(u8, value) else null;
        errdefer if (collation) |value| alloc.free(value);
        return .{
            .name = "",
            .field = field,
            .op = predicate.op,
            .value_json = value_json,
            .collation = collation,
            .validation_state = predicate.validation_state,
        };
    }

    fn cloneRowsAuthExpressionPredicateGroup(
        alloc: std.mem.Allocator,
        group: db_mod.types.RelationalRowsExpressionPredicateGroup,
    ) !db_mod.types.RelationalRowsExpressionPredicateGroup {
        const conditions = try alloc.alloc(db_mod.types.RelationalRowsExpressionCondition, group.conditions.len);
        var initialized: usize = 0;
        errdefer {
            for (conditions[0..initialized]) |condition| runtime_schema_mod.freeRelationalRowsExpressionCondition(alloc, condition);
            alloc.free(conditions);
        }
        for (group.conditions) |condition| {
            conditions[initialized] = try runtime_schema_mod.cloneRelationalRowsExpressionConditionAlloc(alloc, condition);
            initialized += 1;
        }
        return .{ .conditions = conditions };
    }

    fn cloneRowsAuthArrayAnyPredicate(
        alloc: std.mem.Allocator,
        predicate: db_mod.types.RelationalRowsArrayAnyPredicate,
    ) !db_mod.types.RelationalRowsArrayAnyPredicate {
        const field = try alloc.dupe(u8, predicate.field);
        errdefer alloc.free(field);
        return .{
            .field = field,
            .value_json = try alloc.dupe(u8, predicate.value_json),
        };
    }

    fn cloneRowsAuthInPredicate(
        alloc: std.mem.Allocator,
        predicate: db_mod.types.RelationalRowsInPredicate,
    ) !db_mod.types.RelationalRowsInPredicate {
        const field = try alloc.dupe(u8, predicate.field);
        errdefer alloc.free(field);
        const values_json = try alloc.dupe(u8, predicate.values_json);
        errdefer alloc.free(values_json);
        const collation = if (predicate.collation) |value| try alloc.dupe(u8, value) else null;
        errdefer if (collation) |value| alloc.free(value);
        return .{
            .field = field,
            .values_json = values_json,
            .negated = predicate.negated,
            .collation = collation,
        };
    }

    fn cloneRowsAuthJsonContainsPredicate(
        alloc: std.mem.Allocator,
        predicate: db_mod.types.RelationalRowsJsonContainsPredicate,
    ) !db_mod.types.RelationalRowsJsonContainsPredicate {
        const field = try alloc.dupe(u8, predicate.field);
        errdefer alloc.free(field);
        return .{
            .field = field,
            .value_json = try alloc.dupe(u8, predicate.value_json),
        };
    }

    fn cloneRowsAuthAccessPredicateGroup(
        alloc: std.mem.Allocator,
        group: db_mod.types.RelationalRowsAccessPredicateGroup,
    ) !db_mod.types.RelationalRowsAccessPredicateGroup {
        var predicates = try alloc.alloc(runtime_schema_mod.RelationalCheck, group.predicates.len);
        var predicates_initialized: usize = 0;
        errdefer {
            freeRowsAuthPredicates(alloc, predicates[0..predicates_initialized]);
            if (predicates.len > 0) alloc.free(predicates);
        }
        for (group.predicates) |predicate| {
            predicates[predicates_initialized] = try cloneRowsAuthPredicate(alloc, predicate);
            predicates_initialized += 1;
        }

        var array_any = try alloc.alloc(db_mod.types.RelationalRowsArrayAnyPredicate, group.array_any.len);
        var array_any_initialized: usize = 0;
        errdefer {
            freeRowsAuthArrayAnyPredicates(alloc, array_any[0..array_any_initialized]);
            if (array_any.len > 0) alloc.free(array_any);
        }
        for (group.array_any) |predicate| {
            array_any[array_any_initialized] = try cloneRowsAuthArrayAnyPredicate(alloc, predicate);
            array_any_initialized += 1;
        }

        var in_predicates = try alloc.alloc(db_mod.types.RelationalRowsInPredicate, group.in_predicates.len);
        var in_initialized: usize = 0;
        errdefer {
            freeRowsAuthInPredicates(alloc, in_predicates[0..in_initialized]);
            if (in_predicates.len > 0) alloc.free(in_predicates);
        }
        for (group.in_predicates) |predicate| {
            in_predicates[in_initialized] = try cloneRowsAuthInPredicate(alloc, predicate);
            in_initialized += 1;
        }

        var json_contains = try alloc.alloc(db_mod.types.RelationalRowsJsonContainsPredicate, group.json_contains.len);
        var json_initialized: usize = 0;
        errdefer {
            freeRowsAuthJsonContainsPredicates(alloc, json_contains[0..json_initialized]);
            if (json_contains.len > 0) alloc.free(json_contains);
        }
        for (group.json_contains) |predicate| {
            json_contains[json_initialized] = try cloneRowsAuthJsonContainsPredicate(alloc, predicate);
            json_initialized += 1;
        }

        return .{
            .predicates = predicates,
            .array_any = array_any,
            .in_predicates = in_predicates,
            .json_contains = json_contains,
        };
    }

    fn freeRowsAuthPredicates(alloc: std.mem.Allocator, predicates: []const runtime_schema_mod.RelationalCheck) void {
        for (predicates) |predicate| {
            alloc.free(predicate.field);
            if (predicate.value_json) |value_json| alloc.free(value_json);
            if (predicate.collation) |collation| alloc.free(collation);
        }
    }

    fn freeRowsAuthArrayAnyPredicates(alloc: std.mem.Allocator, predicates: []const db_mod.types.RelationalRowsArrayAnyPredicate) void {
        for (predicates) |predicate| {
            alloc.free(predicate.field);
            alloc.free(predicate.value_json);
        }
    }

    fn freeRowsAuthInPredicates(alloc: std.mem.Allocator, predicates: []const db_mod.types.RelationalRowsInPredicate) void {
        for (predicates) |predicate| {
            alloc.free(predicate.field);
            alloc.free(predicate.values_json);
            if (predicate.collation) |collation| alloc.free(collation);
        }
    }

    fn freeRowsAuthJsonContainsPredicates(alloc: std.mem.Allocator, predicates: []const db_mod.types.RelationalRowsJsonContainsPredicate) void {
        for (predicates) |predicate| {
            alloc.free(predicate.field);
            alloc.free(predicate.value_json);
        }
    }

    fn freeRowsAuthAccessPredicateGroups(alloc: std.mem.Allocator, groups: []const db_mod.types.RelationalRowsAccessPredicateGroup) void {
        for (groups) |group| {
            freeRowsAuthPredicates(alloc, group.predicates);
            if (group.predicates.len > 0) alloc.free(group.predicates);
            freeRowsAuthArrayAnyPredicates(alloc, group.array_any);
            if (group.array_any.len > 0) alloc.free(group.array_any);
            freeRowsAuthInPredicates(alloc, group.in_predicates);
            if (group.in_predicates.len > 0) alloc.free(group.in_predicates);
            freeRowsAuthJsonContainsPredicates(alloc, group.json_contains);
            if (group.json_contains.len > 0) alloc.free(group.json_contains);
        }
    }

    fn freeRowsAuthExpressionPredicateGroupsNoSlice(alloc: std.mem.Allocator, groups: []const db_mod.types.RelationalRowsExpressionPredicateGroup) void {
        for (groups) |group| relational_rows_api.freeRowsQueryExpressionConditions(alloc, group.conditions);
    }

    fn runtimeSchemaForPublicRows(self: *ApiHttpServer, table_name: []const u8) !runtime_schema_mod.TableSchema {
        var snapshot = (try self.source.adminSnapshot()) orelse return error.TableNotFound;
        defer self.source.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByName(&snapshot, table_name) orelse return error.TableNotFound;
        if (table.schema_json.len == 0) return error.InvalidRowsRequest;
        var parsed_schema = schema_mod.parseValidatedTableSchema(self.alloc, table.schema_json) catch return error.InvalidRowsRequest;
        defer parsed_schema.deinit(self.alloc);
        const derived_schema = schema_mod.deriveRuntimeTableSchema(self.alloc, parsed_schema) catch return error.InvalidRowsRequest;
        if (derived_schema.storage_mode != .relational or derived_schema.primary_key == null) {
            runtime_schema_mod.freeSchema(self.alloc, derived_schema);
            return error.InvalidRowsRequest;
        }
        return derived_schema;
    }

    fn runtimeSchemaForCatalogRows(self: *ApiHttpServer, target: catalog_resources.TableTarget) !runtime_schema_mod.TableSchema {
        var snapshot = (try self.source.adminSnapshot()) orelse return error.TableNotFound;
        defer self.source.freeAdminSnapshot(&snapshot);
        const table = tables_api.findTableByQualifiedName(&snapshot, target.database_name, target.namespace_name, target.table_name) orelse return error.TableNotFound;
        if (table.schema_json.len == 0) return error.InvalidRowsRequest;
        var parsed_schema = schema_mod.parseValidatedTableSchema(self.alloc, table.schema_json) catch return error.InvalidRowsRequest;
        defer parsed_schema.deinit(self.alloc);
        const derived_schema = schema_mod.deriveRuntimeTableSchema(self.alloc, parsed_schema) catch return error.InvalidRowsRequest;
        if (derived_schema.storage_mode != .relational or derived_schema.primary_key == null) {
            runtime_schema_mod.freeSchema(self.alloc, derived_schema);
            return error.InvalidRowsRequest;
        }
        return derived_schema;
    }

    fn publicQueryDispatchErrorResponse(
        self: *ApiHttpServer,
        table_name: []const u8,
        body: []const u8,
        err: anyerror,
    ) !http_common.HttpResponse {
        return switch (err) {
            error.InvalidQueryRequest => try invalidPublicQueryRequestResponse(self.alloc),
            error.InvalidFilterQueryRequest => try publicFilterQueryErrorResponseForBody(
                self.alloc,
                body,
                "filter_query",
                .invalid,
            ),
            error.InvalidExclusionQueryRequest => try publicFilterQueryErrorResponseForBody(
                self.alloc,
                body,
                "exclusion_query",
                .invalid,
            ),
            error.UnsupportedFilterQueryRequest => try publicFilterQueryErrorResponseForBody(
                self.alloc,
                body,
                "filter_query",
                .unsupported,
            ),
            error.UnsupportedExclusionQueryRequest => try publicFilterQueryErrorResponseForBody(
                self.alloc,
                body,
                "exclusion_query",
                .unsupported,
            ),
            error.UnsupportedExactSort => try unsupportedExactSortResponse(self.alloc),
            error.UnsupportedQueryRequest => try unsupportedPublicQueryResponse(self.alloc, body),
            error.IdentityReadGenerationChanged => try retryableTextResponse(self.alloc, 409, "identity read generation changed"),
            error.QueryCandidateBudgetExceeded => try queryCandidateBudgetExceededResponse(self.alloc),
            error.QueryEmbeddingInputTooLarge => try textResponse(self.alloc, 413, "query embedding input too large"),
            error.QueryEmbeddingOverloaded => try retryableTextResponse(self.alloc, 429, "query embedding overloaded"),
            error.EmbedRateLimited => try retryableTextResponse(self.alloc, 429, "query embedding rate limited"),
            error.EmbedTransientFailure => try retryableTextResponse(self.alloc, 503, "query embedding temporarily unavailable"),
            error.EmbedUpstreamFailure => try textResponse(self.alloc, 502, "query embedding provider failed"),
            error.Timeout => try textResponse(self.alloc, 504, "query timed out"),
            // A peer disconnect is expected control flow. The listener will
            // discard this response when the socket is already gone.
            error.Cancelled => try textResponse(self.alloc, 499, "client closed request"),
            error.NotFound, error.TableNotFound => try textResponse(self.alloc, 404, "not found"),
            error.ModelNotFound => try modelNotFoundResponse(self.alloc),
            error.DocIdentityNamespaceMismatch => try textResponse(self.alloc, 503, "doc identity unavailable"),
            error.IndexRebuilding => try indexRebuildingResponse(self.alloc),
            error.HAReadRequiresPrimary, error.ReadRequiresPrimary => try textResponse(self.alloc, 503, "read requires primary"),
            error.HAReadWaitForApply,
            error.HAReadWaitForMetadata,
            error.ReadUnavailable,
            => try textResponse(self.alloc, 503, "standby read unavailable"),
            error.PersistentDescriptorAdmissionExhausted,
            error.StorageReadTemporarilyUnavailable,
            => try storageReadTemporarilyUnavailableResponse(self.alloc),
            error.InvalidManifest,
            error.InvalidTableFile,
            error.TableBlockChecksumMismatch,
            error.CorruptInput,
            error.UnsupportedVersion,
            error.Corrupted,
            => .{
                .status = 500,
                .content_type = try self.alloc.dupe(u8, "application/json"),
                .body = try public_table_http.tableStorageUnreadableBody(self.alloc, err),
            },
            else => {
                std.log.err("public table query execution failed table={s} err={}", .{ table_name, err });
                return try textResponse(self.alloc, 500, "query failed");
            },
        };
    }

    pub fn handlePublicTableQuery(self: *ApiHttpServer, table_name: []const u8, body: []const u8, authenticated_identity: ?AuthenticatedIdentity) !http_common.HttpResponse {
        return try self.handlePublicTableQueryWithCancellation(table_name, body, authenticated_identity, null);
    }

    fn handlePublicTableQueryWithCancellation(
        self: *ApiHttpServer,
        table_name: []const u8,
        body: []const u8,
        authenticated_identity: ?AuthenticatedIdentity,
        cancellation: ?*const http_common.RequestCancellation,
    ) !http_common.HttpResponse {
        const row_filter_json = try self.resolveEffectiveRowFilterJsonForDatabase(self.alloc, authenticated_identity, tables_api.default_database_name, table_name);
        defer if (row_filter_json) |value| self.alloc.free(value);

        const source = self.table_reads orelse return try textResponse(self.alloc, 404, "not found");
        db_mod.resetLastSortRejectionDiagnostic();
        const response_body = self.executePublicTableQueryDispatchWithReadinessRetry(
            self.alloc,
            source,
            table_name,
            body,
            row_filter_json,
            authenticated_identity,
            if (cancellation) |value| value.signal() else null,
        ) catch |err| return try self.publicQueryDispatchErrorResponse(table_name, body, err);
        defer self.alloc.free(response_body);

        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_impl.deinit();
        const parsed = try parseJsonResponseBody(metadata_openapi.QueryResponses, arena_impl.allocator(), response_body);
        return try jsonResponse(self.alloc, parsed);
    }

    pub fn handlePublicCatalogTableQuery(self: *ApiHttpServer, target: catalog_resources.TableTarget, body: []const u8, authenticated_identity: ?AuthenticatedIdentity) !http_common.HttpResponse {
        const resource_name = try catalog_resources.tableResourceNameAlloc(self.alloc, target.database_name, target.namespace_name, target.table_name);
        defer self.alloc.free(resource_name);
        const row_filter_json = try self.resolveEffectiveRowFilterJsonForDatabase(self.alloc, authenticated_identity, target.database_name, resource_name);
        defer if (row_filter_json) |value| self.alloc.free(value);

        const source = self.table_reads orelse return try textResponse(self.alloc, 404, "not found");
        const response_body = self.executePublicCatalogTableQueryDispatchWithReadinessRetry(
            self.alloc,
            source,
            target,
            body,
            row_filter_json,
            authenticated_identity,
        ) catch |err| switch (err) {
            error.InvalidQueryRequest => return try textResponse(self.alloc, 400, "invalid query request"),
            error.NotFound, error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.DocIdentityNamespaceMismatch => return try textResponse(self.alloc, 503, "doc identity unavailable"),
            error.Timeout => return try textResponse(self.alloc, 504, "query timed out"),
            error.LeaderUnavailable, error.ReadUnavailable => return try textResponse(self.alloc, 503, "read unavailable"),
            else => {
                std.log.err("public catalog table query execution failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                return try textResponse(self.alloc, 500, "query failed");
            },
        };
        defer self.alloc.free(response_body);

        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_impl.deinit();
        const parsed = try parseJsonResponseBody(metadata_openapi.QueryResponses, arena_impl.allocator(), response_body);
        return try jsonResponse(self.alloc, parsed);
    }

