        const doc_key = try decodeRequestPathParamAlloc(self.alloc, encoded_doc_key);
        defer self.alloc.free(doc_key);
        const artifact_name = try decodeRequestPathParamAlloc(self.alloc, encoded_artifact_name);
        defer self.alloc.free(artifact_name);

        if (!(try self.sourceDocumentVisibleToIdentity(table_name, doc_key, authenticated_identity))) {
            return try textResponse(self.alloc, 404, "not found");
        }
        var resp = try public_table_http.handleReprocessDocumentArtifact(self.alloc, table_name, doc_key, artifact_name, self.tableApi());
        defer resp.deinit(self.alloc);
        return switch (resp.status) {
            202 => try jsonBodyResponseWithStatus(self.alloc, 202, resp.body),
            else => try textResponse(self.alloc, resp.status, resp.body),
        };
    }

    pub fn handlePublicReprocessDocumentArtifactRange(self: *ApiHttpServer, table_name: []const u8, encoded_artifact_name: []const u8, body: []const u8) !http_common.HttpResponse {
        const artifact_name = try decodeRequestPathParamAlloc(self.alloc, encoded_artifact_name);
        defer self.alloc.free(artifact_name);

        var resp = try public_table_http.handleReprocessDocumentArtifactRange(self.alloc, table_name, artifact_name, body, self.tableApi());
        defer resp.deinit(self.alloc);
        return switch (resp.status) {
            202 => try jsonBodyResponseWithStatus(self.alloc, 202, resp.body),
            else => try textResponse(self.alloc, resp.status, resp.body),
        };
    }

    const PublicRepairListRequest = struct {
        target: []const u8 = "artifact",
        kind: ?db_mod.types.ArtifactRepairKind = null,
        index: ?[]const u8 = null,
        cursor: ?[]const u8 = null,
        limit: ?u32 = null,
    };

    pub fn handlePublicListArtifactRepairIssues(self: *ApiHttpServer, table_name: []const u8, body: []const u8) !http_common.HttpResponse {
        const source = self.table_writes orelse return try textResponse(self.alloc, 405, "method not allowed");
        var parsed = std.json.parseFromSlice(PublicRepairListRequest, self.alloc, if (body.len > 0) body else "{}", .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 400, "invalid repair list request");
        };
        defer parsed.deinit();
        const target = std.meta.stringToEnum(db_mod.types.RepairTarget, parsed.value.target) orelse return try textResponse(self.alloc, 400, "invalid repair target");
        const raw_limit: u32 = parsed.value.limit orelse 50;
        if (raw_limit == 0) return try textResponse(self.alloc, 400, "invalid limit");
        const limit: u32 = @min(raw_limit, 500);
        var result = (source.listArtifactRepairIssues(self.alloc, table_name, .{
            .target = target,
            .artifact_kind = parsed.value.kind,
            .index_name = parsed.value.index,
            .limit = limit,
            .cursor = parsed.value.cursor,
        }) catch |err| switch (err) {
            error.InvalidArgument => return try textResponse(self.alloc, 400, "invalid cursor"),
            else => {
                std.log.err("artifact repair issue list failed table={s} err={}", .{ table_name, err });
                return try textResponse(self.alloc, 500, "artifact repair issue list failed");
            },
        }) orelse return try textResponse(self.alloc, 404, "not found");
        defer result.deinit(self.alloc);

        const response_body = try std.json.Stringify.valueAlloc(self.alloc, .{
            .table = table_name,
            .target = @tagName(target),
            .limit = limit,
            .scanned = result.scanned,
            .groups_scanned = result.groups_scanned,
            .has_more = result.has_more,
            .next_cursor = result.next_cursor,
            .issues = result.issues,
        }, .{ .emit_null_optional_fields = false });
        defer self.alloc.free(response_body);
        return try jsonBodyResponseWithStatus(self.alloc, 200, response_body);
    }

    const PublicRepairRunRequest = struct {
        target: []const u8 = "artifact",
        kind: ?db_mod.types.ArtifactRepairKind = null,
        index: ?[]const u8 = null,
        cursor: ?[]const u8 = null,
        limit: ?u32 = null,
        force: bool = false,
        control: ?[]const u8 = null,
        repair_id: ?[]const u8 = null,
    };

    pub fn handlePublicRunTableRepair(self: *ApiHttpServer, table_name: []const u8, body: []const u8) !http_common.HttpResponse {
        const source = self.table_writes orelse return try textResponse(self.alloc, 405, "method not allowed");
        var parsed = std.json.parseFromSlice(PublicRepairRunRequest, self.alloc, if (body.len > 0) body else "{}", .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 400, "invalid repair request");
        };
        defer parsed.deinit();
        const body_target = std.meta.stringToEnum(db_mod.types.RepairTarget, parsed.value.target) orelse return try textResponse(self.alloc, 400, "invalid repair target");
        const target = body_target;
        const raw_limit = parsed.value.limit orelse 100;
        if (raw_limit == 0) return try textResponse(self.alloc, 400, "invalid limit");
        const limit: u32 = @min(raw_limit, 1000);
        const control = if (parsed.value.control) |raw|
            std.meta.stringToEnum(db_mod.types.IndexRepairControl, raw) orelse return try textResponse(self.alloc, 400, "invalid repair control")
        else
            null;
        const repair_id = if (parsed.value.repair_id) |raw|
            std.fmt.parseInt(u128, raw, 10) catch return try textResponse(self.alloc, 400, "invalid repair id")
        else
            null;
        var result = (source.repairArtifactIssues(self.alloc, table_name, .{
            .target = target,
            .artifact_kind = parsed.value.kind,
            .index_name = parsed.value.index,
            .limit = limit,
            .cursor = parsed.value.cursor,
            .force = parsed.value.force,
            .control = control,
            .repair_id = repair_id,
        }) catch |err| switch (err) {
            error.InvalidArgument => return try textResponse(self.alloc, 400, "invalid repair request"),
            error.StaleIndexRepairControl => return try textResponse(self.alloc, 409, "repair changed; refresh and retry"),
            else => {
                std.log.err("table repair failed table={s} err={}", .{ table_name, err });
                return try textResponse(self.alloc, 500, "table repair failed");
            },
        }) orelse return try textResponse(self.alloc, 404, "not found");
        defer result.deinit(self.alloc);
        const response_body = try std.json.Stringify.valueAlloc(self.alloc, .{
            .table = table_name,
            .target = @tagName(target),
            .limit = limit,
            .result = result,
        }, .{ .emit_null_optional_fields = false });
        defer self.alloc.free(response_body);
        return try jsonBodyResponseWithStatus(self.alloc, 200, response_body);
    }

    pub fn handlePublicStartTableRepairJob(self: *ApiHttpServer, table_name: []const u8, body: []const u8) !http_common.HttpResponse {
        if (self.table_writes == null) return try textResponse(self.alloc, 405, "method not allowed");
        var parsed = std.json.parseFromSlice(repair_jobs.StartRequest, self.alloc, if (body.len > 0) body else "{}", .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 400, "invalid repair job request");
        };
        defer parsed.deinit();
        if (std.meta.stringToEnum(db_mod.types.RepairTarget, parsed.value.target) == null) return try textResponse(self.alloc, 400, "invalid repair target");
        if (parsed.value.limit == 0) return try textResponse(self.alloc, 400, "invalid limit");

        const encoded = try self.repair_job_store.startJob(self.alloc, table_name, .{
            .target = parsed.value.target,
            .kind = parsed.value.kind,
            .index = parsed.value.index,
            .cursor = parsed.value.cursor,
            .limit = @min(parsed.value.limit, 1000),
            .force = parsed.value.force,
            .advance = parsed.value.advance,
        });
        defer self.alloc.free(encoded);
        if (parsed.value.advance) {
            var parsed_state = std.json.parseFromSlice(repair_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
                return try textResponse(self.alloc, 500, "repair job failed");
            };
            defer parsed_state.deinit();
            return try self.advanceTableRepairJobState(table_name, parsed_state.value);
        }
        return try jsonBodyResponseWithStatus(self.alloc, 202, encoded);
    }

    pub fn handlePublicTableRepairJob(self: *ApiHttpServer, table_name: []const u8, encoded_job_id: []const u8) !http_common.HttpResponse {
        const job_id = parseArtifactReprocessJobId(encoded_job_id) catch return try textResponse(self.alloc, 400, "invalid job id");
        const encoded = (try self.repair_job_store.loadJobAlloc(self.alloc, job_id)) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.alloc.free(encoded);
        var parsed = std.json.parseFromSlice(repair_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 500, "repair job failed");
        };
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.table_name, table_name)) return try textResponse(self.alloc, 404, "not found");
        return try jsonBodyResponseWithStatus(self.alloc, 200, encoded);
    }

    pub fn handlePublicAdvanceTableRepairJob(self: *ApiHttpServer, table_name: []const u8, encoded_job_id: []const u8) !http_common.HttpResponse {
        const job_id = parseArtifactReprocessJobId(encoded_job_id) catch return try textResponse(self.alloc, 400, "invalid job id");
        const encoded = (try self.repair_job_store.loadJobAlloc(self.alloc, job_id)) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.alloc.free(encoded);
        var parsed = std.json.parseFromSlice(repair_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 500, "repair job failed");
        };
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.table_name, table_name)) return try textResponse(self.alloc, 404, "not found");
        return try self.advanceTableRepairJobState(table_name, parsed.value);
    }

    pub fn handlePublicCancelTableRepairJob(self: *ApiHttpServer, table_name: []const u8, encoded_job_id: []const u8) !http_common.HttpResponse {
        const job_id = parseArtifactReprocessJobId(encoded_job_id) catch return try textResponse(self.alloc, 400, "invalid job id");
        const encoded = (try self.repair_job_store.loadJobAlloc(self.alloc, job_id)) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.alloc.free(encoded);
        var parsed = std.json.parseFromSlice(repair_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 500, "repair job failed");
        };
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.table_name, table_name)) return try textResponse(self.alloc, 404, "not found");
        const cancelled = try self.repair_job_store.requestCancel(self.alloc, parsed.value);
        defer self.alloc.free(cancelled);
        var parsed_cancelled = std.json.parseFromSlice(repair_jobs.JobState, self.alloc, cancelled, .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 500, "invalid repair job state");
        };
        defer parsed_cancelled.deinit();
        if (repair_jobs.requiresDurableCancel(parsed_cancelled.value) and
            std.mem.eql(u8, parsed_cancelled.value.phase, repair_jobs.phaseString(.queued)))
        {
            return try self.advanceTableRepairJobState(table_name, parsed_cancelled.value);
        }
        return try jsonBodyResponseWithStatus(self.alloc, if (repair_jobs.isTerminalPhase(parsed_cancelled.value.phase)) 200 else 202, cancelled);
    }

    fn advanceTableRepairJobState(self: *ApiHttpServer, table_name: []const u8, state: repair_jobs.JobState) !http_common.HttpResponse {
        if (repair_jobs.isTerminalPhase(state.phase)) {
            const encoded = try repair_jobs.encodeState(self.alloc, state);
            defer self.alloc.free(encoded);
            return try jsonBodyResponseWithStatus(self.alloc, 200, encoded);
        }

        const begin = try self.repair_job_store.beginAdvance(self.alloc, state);
        defer self.alloc.free(begin.encoded);
        var parsed_running = std.json.parseFromSlice(repair_jobs.JobState, self.alloc, begin.encoded, .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 500, "invalid repair job state");
        };
        defer parsed_running.deinit();
        const running_state = parsed_running.value;
        if (!begin.started) {
            return try jsonBodyResponseWithStatus(self.alloc, if (repair_jobs.isTerminalPhase(running_state.phase)) 200 else 202, begin.encoded);
        }

        const updated = if (try self.submitTableRepairJobPass(table_name, begin.encoded, running_state.job_id)) |submitted|
            submitted
        else
            try self.runTableRepairJobPass(table_name, running_state);
        defer self.alloc.free(updated);
        var parsed_updated = std.json.parseFromSlice(repair_jobs.JobState, self.alloc, updated, .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 500, "invalid repair job state");
        };
        defer parsed_updated.deinit();
        return try jsonBodyResponseWithStatus(self.alloc, if (repair_jobs.isTerminalPhase(parsed_updated.value.phase)) 200 else 202, updated);
    }

    const TableRepairJobPassWork = struct {
        server: *ApiHttpServer,
        table_name: []u8,
        running_encoded: []u8,

        fn run(ptr: *anyopaque) !void {
            const work: *TableRepairJobPassWork = @ptrCast(@alignCast(ptr));
            var parsed = try std.json.parseFromSlice(repair_jobs.JobState, work.server.alloc, work.running_encoded, .{ .ignore_unknown_fields = true });
            defer parsed.deinit();
            const heartbeat = work.server.submitTableRepairJobHeartbeat(parsed.value.job_id, parsed.value.attempt_id) catch null;
            defer if (heartbeat) |hb| hb.stop.store(true, .release);
            const updated = work.server.runTableRepairJobPass(work.table_name, parsed.value) catch |err| {
                // An unexpected worker failure is operational, not evidence
                // that the repair request is invalid. Return it to the durable
                // backoff queue so cancellation and operator work remain
                // restart-safe.
                const recovered = work.server.repair_job_store.recordRetryableFailure(
                    work.server.alloc,
                    parsed.value,
                    @errorName(err),
                ) catch |recovery_err| {
                    std.log.err("failed to recover table repair job state table={s} job_id={d} worker_err={s} recovery_err={s}", .{
                        work.table_name,
                        parsed.value.job_id,
                        @errorName(err),
                        @errorName(recovery_err),
                    });
                    return recovery_err;
                };
                work.server.alloc.free(recovered);
                return err;
            };
            defer work.server.alloc.free(updated);
            work.server.continueDurableRepairCancellation(work.table_name, updated) catch |err| {
                std.log.warn("failed to continue durable table repair cancellation table={s} err={s}", .{ work.table_name, @errorName(err) });
            };
        }

        fn deinit(ptr: *anyopaque) void {
            const work: *TableRepairJobPassWork = @ptrCast(@alignCast(ptr));
            work.server.alloc.free(work.running_encoded);
            work.server.alloc.free(work.table_name);
            work.server.alloc.destroy(work);
        }
    };

    const TableRepairJobHeartbeatWork = struct {
        server: *ApiHttpServer,
        job_id: u64,
        attempt_id: u64,
        stop: std.atomic.Value(bool) = .init(false),

        const interval_ns: u64 = 30 * std.time.ns_per_s;
        const poll_ns: u64 = 100 * std.time.ns_per_ms;

        fn run(ptr: *anyopaque) !void {
            const self: *TableRepairJobHeartbeatWork = @ptrCast(@alignCast(ptr));
            const runtime = self.server.cfg.backend_runtime orelse return;
            const io_impl = runtime.apiIoImpl() orelse runtime.io_impl orelse return;
            var elapsed_ns: u64 = 0;
            while (!self.stop.load(.acquire)) {
                io_impl.io().sleep(std.Io.Duration.fromNanoseconds(@intCast(poll_ns)), .awake) catch {};
                if (self.stop.load(.acquire)) break;
                elapsed_ns +|= poll_ns;
                if (elapsed_ns < interval_ns) continue;
                elapsed_ns = 0;
                self.server.repair_job_store.heartbeatRunning(self.server.alloc, self.job_id, self.attempt_id) catch |err| {
                    std.log.warn("failed to heartbeat table repair job job_id={d} attempt_id={d} err={s}", .{
                        self.job_id,
                        self.attempt_id,
                        @errorName(err),
                    });
                };
            }
        }

        fn deinit(ptr: *anyopaque) void {
            const self: *TableRepairJobHeartbeatWork = @ptrCast(@alignCast(ptr));
            self.server.alloc.destroy(self);
        }
    };

    const TableRepairCancelProbe = struct {
        server: *ApiHttpServer,
        job_id: u64,
        attempt_id: u64,
        cached_requested: std.atomic.Value(bool) = .init(false),
        last_check_ns: std.atomic.Value(u64) = .init(0),

        const check_interval_ns: u64 = 100 * std.time.ns_per_ms;

        fn check(ptr: *anyopaque) bool {
            const self: *TableRepairCancelProbe = @ptrCast(@alignCast(ptr));
            if (self.cached_requested.load(.acquire)) return true;
            const now_ns = platform_time.monotonicNs();
            const last_ns = self.last_check_ns.load(.acquire);
            if (last_ns != 0 and now_ns -| last_ns < check_interval_ns) return false;
            self.last_check_ns.store(now_ns, .release);

            const encoded = self.server.repair_job_store.loadJobAlloc(self.server.alloc, self.job_id) catch return false;
            defer if (encoded) |buf| self.server.alloc.free(buf);
            const body = encoded orelse {
                self.cached_requested.store(true, .release);
                return true;
            };
            var parsed = std.json.parseFromSlice(repair_jobs.JobState, self.server.alloc, body, .{ .ignore_unknown_fields = true }) catch return false;
            defer parsed.deinit();
            const state = parsed.value;
            const requested = state.cancel_requested or
                repair_jobs.isTerminalPhase(state.phase) or
                state.attempt_id != self.attempt_id;
            if (requested) self.cached_requested.store(true, .release);
            return requested;
        }
    };

    fn submitTableRepairJobHeartbeat(self: *ApiHttpServer, job_id: u64, attempt_id: u64) !?*TableRepairJobHeartbeatWork {
        const runtime = self.cfg.backend_runtime orelse return null;
        if (runtime.threaded_jobs == null) return null;
        if (runtime.apiIoImpl() == null and runtime.io_impl == null) return null;
        if (self.repair_job_owner_id == 0) return null;

        const heartbeat = try self.alloc.create(TableRepairJobHeartbeatWork);
        heartbeat.* = .{
            .server = self,
            .job_id = job_id,
            .attempt_id = attempt_id,
        };
        runtime.durable_jobs.submit(.{
            .owner_id = self.repair_job_owner_id,
            .class = .maintenance,
            .ptr = heartbeat,
            .run = TableRepairJobHeartbeatWork.run,
            .deinit = TableRepairJobHeartbeatWork.deinit,
        }) catch |err| {
            self.alloc.destroy(heartbeat);
            return err;
        };
        return heartbeat;
    }

    fn submitTableRepairJobPass(self: *ApiHttpServer, table_name: []const u8, running_encoded: []const u8, job_id: u64) !?[]u8 {
        const runtime = self.cfg.backend_runtime orelse return null;
        if (runtime.threaded_jobs == null) return null;
        if (self.repair_job_owner_id == 0) return null;

        var work_consumed = false;
        const owned_table_name = try self.alloc.dupe(u8, table_name);
        errdefer if (!work_consumed) self.alloc.free(owned_table_name);
        const owned_running_encoded = try self.alloc.dupe(u8, running_encoded);
        errdefer if (!work_consumed) self.alloc.free(owned_running_encoded);
        const work = try self.alloc.create(TableRepairJobPassWork);
        errdefer if (!work_consumed) self.alloc.destroy(work);
        work.* = .{
            .server = self,
            .table_name = owned_table_name,
            .running_encoded = owned_running_encoded,
        };

        runtime.durable_jobs.submit(.{
            .owner_id = self.repair_job_owner_id,
            .class = .maintenance,
            .ptr = work,
            .run = TableRepairJobPassWork.run,
            .deinit = TableRepairJobPassWork.deinit,
        }) catch |err| {
            TableRepairJobPassWork.deinit(work);
            work_consumed = true;
            var parsed = try std.json.parseFromSlice(repair_jobs.JobState, self.alloc, running_encoded, .{ .ignore_unknown_fields = true });
            defer parsed.deinit();
            const queued = try self.repair_job_store.recordRetryableFailure(self.alloc, parsed.value, @errorName(err));
            defer self.alloc.free(queued);
            if (err == error.BackgroundOwnerClosing or err == error.BackgroundOwnerClosed) {
                std.log.warn("table repair job submission deferred during shutdown table={s} job_id={d}", .{ table_name, job_id });
            } else {
                std.log.warn("table repair job submission deferred table={s} job_id={d} err={}", .{ table_name, job_id, err });
            }
            return try self.repair_job_store.loadJobAlloc(self.alloc, job_id) orelse try self.alloc.dupe(u8, queued);
        };
        work_consumed = true;

        return try self.repair_job_store.loadJobAlloc(self.alloc, job_id) orelse try self.alloc.dupe(u8, running_encoded);
    }

    fn continueDurableRepairCancellation(self: *ApiHttpServer, table_name: []const u8, encoded: []const u8) !void {
        var parsed = try std.json.parseFromSlice(repair_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true });
        defer parsed.deinit();
        if (!repair_jobs.requiresDurableCancel(parsed.value) or
            !std.mem.eql(u8, parsed.value.phase, repair_jobs.phaseString(.queued))) return;

        const begin = try self.repair_job_store.beginAdvance(self.alloc, parsed.value);
        defer self.alloc.free(begin.encoded);
        if (!begin.started) return;
        var running = try std.json.parseFromSlice(repair_jobs.JobState, self.alloc, begin.encoded, .{ .ignore_unknown_fields = true });
        defer running.deinit();
        if (try self.submitTableRepairJobPass(table_name, begin.encoded, running.value.job_id)) |submitted| {
            self.alloc.free(submitted);
        } else {
            const updated = try self.runTableRepairJobPass(table_name, running.value);
            self.alloc.free(updated);
        }
    }

    fn runTableRepairJobPass(self: *ApiHttpServer, table_name: []const u8, running_state: repair_jobs.JobState) ![]u8 {
        const source = self.table_writes orelse {
            return try self.repair_job_store.markPhase(self.alloc, running_state, .failed, "method not allowed");
        };
        const target = std.meta.stringToEnum(db_mod.types.RepairTarget, running_state.target) orelse {
            return try self.repair_job_store.markPhase(self.alloc, running_state, .failed, "invalid repair target");
        };
        if (repair_jobs.requiresDurableCancel(running_state)) {
            var cancel_result = (source.repairArtifactIssuesControlled(self.alloc, table_name, .{
                .target = .index,
                .index_name = running_state.index,
                .limit = running_state.limit,
                .cursor = running_state.cursor,
                .control = .pause_automatic,
            }, .{}) catch |err| switch (err) {
                error.InvalidArgument, error.NotFound => {
                    return try self.repair_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
                },
                else => {
                    std.log.warn("durable table repair cancellation deferred table={s} job_id={d} err={s}", .{ table_name, running_state.job_id, @errorName(err) });
                    return try self.repair_job_store.recordRetryableFailure(self.alloc, running_state, @errorName(err));
                },
            }) orelse {
                return try self.repair_job_store.markPhase(self.alloc, running_state, .failed, "method not allowed");
            };
            defer cancel_result.deinit(self.alloc);
            return try self.repair_job_store.recordDurableCancelPass(self.alloc, running_state, cancel_result);
        }
        var cancel_probe = TableRepairCancelProbe{
            .server = self,
            .job_id = running_state.job_id,
            .attempt_id = running_state.attempt_id,
        };
        var result = (source.repairArtifactIssuesControlled(self.alloc, table_name, .{
            .target = target,
            .artifact_kind = running_state.kind,
            .index_name = running_state.index,
            .limit = running_state.limit,
            .cursor = running_state.cursor,
            .force = running_state.force,
            .repair_job_id = running_state.job_id,
            .repair_attempt_id = running_state.attempt_id,
            .repair_job_created_at_ms = running_state.created_at_millis,
        }, .{
            .cancel_check = .{
                .ptr = &cancel_probe,
                .is_requested = TableRepairCancelProbe.check,
            },
        }) catch |err| switch (err) {
            error.Canceled => {
                return try self.repair_job_store.markPhase(self.alloc, running_state, .cancelled, "cancel_requested");
            },
            error.InvalidArgument => {
                return try self.repair_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
            },
            error.NotFound => {
                return try self.repair_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
            },
            else => {
                std.log.warn("public table repair job deferred table={s} job_id={d} err={}", .{ table_name, running_state.job_id, err });
                return try self.repair_job_store.recordRetryableFailure(self.alloc, running_state, @errorName(err));
            },
        }) orelse {
            return try self.repair_job_store.markPhase(self.alloc, running_state, .failed, "method not allowed");
        };
        defer result.deinit(self.alloc);
        return try self.repair_job_store.recordPass(self.alloc, running_state, result);
    }

    pub fn handlePublicStartDocumentArtifactReprocessJob(self: *ApiHttpServer, table_name: []const u8, encoded_artifact_name: []const u8, body: []const u8) !http_common.HttpResponse {
        if (self.table_writes == null) return try textResponse(self.alloc, 405, "method not allowed");
        const artifact_name = try decodeRequestPathParamAlloc(self.alloc, encoded_artifact_name);
        defer self.alloc.free(artifact_name);
        var parsed = std.json.parseFromSlice(artifact_reprocess_jobs.StartRequest, self.alloc, if (body.len > 0) body else "{}", .{}) catch {
            return try textResponse(self.alloc, 400, "invalid request");
        };
        defer parsed.deinit();

        const encoded = try self.artifact_reprocess_job_store.startJob(self.alloc, table_name, artifact_name, parsed.value);
        defer self.alloc.free(encoded);
        if (parsed.value.advance) {
            var parsed_state = std.json.parseFromSlice(artifact_reprocess_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
                return try textResponse(self.alloc, 500, "artifact reprocess job failed");
            };
            defer parsed_state.deinit();
            return try self.advanceDocumentArtifactReprocessJobState(table_name, artifact_name, parsed_state.value);
        }
        return try jsonBodyResponseWithStatus(self.alloc, 202, encoded);
    }

    pub fn handlePublicDocumentArtifactReprocessJob(self: *ApiHttpServer, table_name: []const u8, encoded_artifact_name: []const u8, encoded_job_id: []const u8) !http_common.HttpResponse {
        const artifact_name = try decodeRequestPathParamAlloc(self.alloc, encoded_artifact_name);
        defer self.alloc.free(artifact_name);
        const job_id = parseArtifactReprocessJobId(encoded_job_id) catch return try textResponse(self.alloc, 400, "invalid job id");
        const encoded = (try self.artifact_reprocess_job_store.loadJobAlloc(self.alloc, job_id)) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.alloc.free(encoded);
        var parsed = std.json.parseFromSlice(artifact_reprocess_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 500, "artifact reprocess job failed");
        };
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.table_name, table_name) or !std.mem.eql(u8, parsed.value.artifact_name, artifact_name)) {
            return try textResponse(self.alloc, 404, "not found");
        }
        return try jsonBodyResponseWithStatus(self.alloc, 200, encoded);
    }

    pub fn handlePublicAdvanceDocumentArtifactReprocessJob(self: *ApiHttpServer, table_name: []const u8, encoded_artifact_name: []const u8, encoded_job_id: []const u8) !http_common.HttpResponse {
        const artifact_name = try decodeRequestPathParamAlloc(self.alloc, encoded_artifact_name);
        defer self.alloc.free(artifact_name);
        const job_id = parseArtifactReprocessJobId(encoded_job_id) catch return try textResponse(self.alloc, 400, "invalid job id");
        const encoded = (try self.artifact_reprocess_job_store.loadJobAlloc(self.alloc, job_id)) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.alloc.free(encoded);
        var parsed = std.json.parseFromSlice(artifact_reprocess_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 500, "artifact reprocess job failed");
        };
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.table_name, table_name) or !std.mem.eql(u8, parsed.value.artifact_name, artifact_name)) {
            return try textResponse(self.alloc, 404, "not found");
        }
        return try self.advanceDocumentArtifactReprocessJobState(table_name, artifact_name, parsed.value);
    }

    pub fn handlePublicCancelDocumentArtifactReprocessJob(self: *ApiHttpServer, table_name: []const u8, encoded_artifact_name: []const u8, encoded_job_id: []const u8) !http_common.HttpResponse {
        const artifact_name = try decodeRequestPathParamAlloc(self.alloc, encoded_artifact_name);
        defer self.alloc.free(artifact_name);
        const job_id = parseArtifactReprocessJobId(encoded_job_id) catch return try textResponse(self.alloc, 400, "invalid job id");
        const encoded = (try self.artifact_reprocess_job_store.loadJobAlloc(self.alloc, job_id)) orelse return try textResponse(self.alloc, 404, "not found");
        defer self.alloc.free(encoded);
        var parsed = std.json.parseFromSlice(artifact_reprocess_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 500, "artifact reprocess job failed");
        };
        defer parsed.deinit();
        if (!std.mem.eql(u8, parsed.value.table_name, table_name) or !std.mem.eql(u8, parsed.value.artifact_name, artifact_name)) {
            return try textResponse(self.alloc, 404, "not found");
        }
        if (artifact_reprocess_jobs.isTerminalPhase(parsed.value.phase)) {
            return try jsonBodyResponseWithStatus(self.alloc, 200, encoded);
        }
        const cancelled = try self.artifact_reprocess_job_store.requestCancel(self.alloc, parsed.value);
        defer self.alloc.free(cancelled);
        var parsed_cancelled = std.json.parseFromSlice(artifact_reprocess_jobs.JobState, self.alloc, cancelled, .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 500, "invalid artifact reprocess job state");
        };
        defer parsed_cancelled.deinit();
        return try jsonBodyResponseWithStatus(self.alloc, if (artifact_reprocess_jobs.isTerminalPhase(parsed_cancelled.value.phase)) 200 else 202, cancelled);
    }

    fn advanceDocumentArtifactReprocessJobState(self: *ApiHttpServer, table_name: []const u8, artifact_name: []const u8, state: artifact_reprocess_jobs.JobState) !http_common.HttpResponse {
        if (artifact_reprocess_jobs.isTerminalPhase(state.phase)) {
            const encoded = try artifact_reprocess_jobs.encodeState(self.alloc, state);
            defer self.alloc.free(encoded);
            return try jsonBodyResponseWithStatus(self.alloc, 200, encoded);
        }

        const begin = try self.artifact_reprocess_job_store.beginAdvance(self.alloc, state);
        defer self.alloc.free(begin.encoded);
        var parsed_running = std.json.parseFromSlice(artifact_reprocess_jobs.JobState, self.alloc, begin.encoded, .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 500, "invalid job state");
        };
        defer parsed_running.deinit();
        const running_state = parsed_running.value;
        if (!begin.started) {
            return try jsonBodyResponseWithStatus(self.alloc, if (artifact_reprocess_jobs.isTerminalPhase(running_state.phase)) 200 else 202, begin.encoded);
        }

        const source = self.table_writes orelse {
            const failed = try self.artifact_reprocess_job_store.markPhase(self.alloc, running_state, .failed, "method not allowed");
            defer self.alloc.free(failed);
            return try textResponse(self.alloc, 405, "method not allowed");
        };

        const shard_resumes = try self.alloc.alloc(db_mod.types.DocumentArtifactReprocessShardResume, running_state.shard_cursors.len);
        defer self.alloc.free(shard_resumes);
        for (running_state.shard_cursors, shard_resumes) |cursor, *out_resume| {
            out_resume.* = .{
                .group_id = cursor.group_id,
                .next_key = cursor.next_key,
                .limit = cursor.limit,
            };
        }
        const req = db_mod.types.DocumentArtifactTableReprocessRequest{
            .from_key = if (shard_resumes.len > 0) "" else (running_state.next_key orelse running_state.from_key),
            .to_key = running_state.to_key,
            .limit = running_state.limit,
            .shard_cursors = shard_resumes,
        };
        var result = (source.reprocessDocumentArtifactRange(self.alloc, table_name, artifact_name, req) catch |err| switch (err) {
            error.DocIdentityNamespaceMismatch => {
                const failed = try self.artifact_reprocess_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
                defer self.alloc.free(failed);
                return try textResponse(self.alloc, 503, "doc identity unavailable");
            },
            error.InvalidArgument => {
                const failed = try self.artifact_reprocess_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
                defer self.alloc.free(failed);
                return try textResponse(self.alloc, 400, "invalid request");
            },
            error.NotFound => {
                const failed = try self.artifact_reprocess_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
                defer self.alloc.free(failed);
                return try textResponse(self.alloc, 404, "not found");
            },
            error.LeaderUnavailable, error.WriteUnavailable => {
                const failed = try self.artifact_reprocess_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
                defer self.alloc.free(failed);
                return try textResponse(self.alloc, 503, "write unavailable");
            },
            error.MethodNotAllowed => {
                const failed = try self.artifact_reprocess_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
                defer self.alloc.free(failed);
                return try textResponse(self.alloc, 405, "method not allowed");
            },
            error.InternalFailure => {
                const failed = try self.artifact_reprocess_job_store.markPhase(self.alloc, running_state, .failed, @errorName(err));
                defer self.alloc.free(failed);
                return try textResponse(self.alloc, 500, "artifact reprocess failed");
            },
            else => return err,
        }) orelse return try textResponse(self.alloc, 404, "not found");
        defer result.deinit(self.alloc);

        const updated = try self.artifact_reprocess_job_store.recordPass(self.alloc, running_state, result);
        defer self.alloc.free(updated);
        var parsed_updated = std.json.parseFromSlice(artifact_reprocess_jobs.JobState, self.alloc, updated, .{ .ignore_unknown_fields = true }) catch {
            return try textResponse(self.alloc, 500, "artifact reprocess job failed");
        };
        defer parsed_updated.deinit();
        const status: u16 = if (artifact_reprocess_jobs.isTerminalPhase(parsed_updated.value.phase)) 200 else 202;
        return try jsonBodyResponseWithStatus(self.alloc, status, updated);
    }

    pub fn handlePublicTableBackup(self: *ApiHttpServer, table_name: []const u8, body: []const u8) !http_common.HttpResponse {
        var resp = try public_table_http.handleTableBackup(self.alloc, table_name, body, self.tableApi(), self.cfg.secret_store, self.cfg.node_config, self.sharedApiIo());
        defer resp.deinit(self.alloc);
        return switch (resp.status) {
            201 => blk: {
                const BackupSuccess = struct {
                    backup: []const u8,
                };
                var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
                defer arena_impl.deinit();
                const parsed = try parseJsonResponseBody(BackupSuccess, arena_impl.allocator(), resp.body);
                break :blk try jsonResponseWithStatus(self.alloc, 201, parsed);
            },
            else => try jsonErrorResponse(self.alloc, resp.status, resp.body),
        };
    }

    pub fn handlePublicCatalogTableBackup(self: *ApiHttpServer, target: catalog_resources.TableTarget, body: []const u8) !http_common.HttpResponse {
        const parsed_req = backups_api.parseBackupRequest(self.alloc, body) catch |err| switch (err) {
            else => return try textResponse(self.alloc, 400, "invalid backup request"),
        };
        defer parsed_req.deinit();

        if (parsed_req.value.format) |format| {
            if (format != .native) {
                return try textResponse(self.alloc, 400, "portable table backups are not supported; omit format or use native");
            }
        }

        var location = backups_api.openBackupLocationWithSecrets(self.alloc, parsed_req.value.location, self.cfg.secret_store) catch |err| {
            if (backups_api.backupLocationErrorMessage(err)) |msg| {
                return try textResponse(self.alloc, 400, msg);
            }
            return err;
        };
        defer location.deinit(self.alloc);

        self.backupOwnedCatalogTable(target, &location, parsed_req.value.backup_id) catch |err| switch (err) {
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            error.UnsupportedBackupMigrationState => return try textResponse(self.alloc, 400, "backup does not support active schema migration"),
            error.UnsupportedMultiRangeTable => return try textResponse(self.alloc, 400, "backup does not support multi-range tables"),
            else => {
                std.log.err("public catalog table backup failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                return try textResponse(self.alloc, 500, "backup failed");
            },
        };

        const response_body = try backups_api.encodeBackupSuccess(self.alloc);
        defer self.alloc.free(response_body);
        const BackupSuccess = struct {
            backup: []const u8,
        };
        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_impl.deinit();
        const parsed = try parseJsonResponseBody(BackupSuccess, arena_impl.allocator(), response_body);
        return try jsonResponseWithStatus(self.alloc, 201, parsed);
    }

    pub fn handlePublicTableRestore(
        self: *ApiHttpServer,
        table_name: []const u8,
        body: []const u8,
        idempotency_key: ?[]const u8,
        principal: ?[]const u8,
    ) !http_common.HttpResponse {
        const parsed = backups_api.parseRestoreRequest(self.alloc, body) catch return try jsonErrorResponse(self.alloc, 400, "invalid restore request");
        defer parsed.deinit();
        backups_api.validateBackupId(parsed.value.backup_id) catch return try jsonErrorResponse(self.alloc, 400, "invalid backup id");
        self.ensureAsyncRestoreWorker() catch |err| return try restoreJobStartErrorResponse(self.alloc, err);
        const connection = parsed.value.connection;
        var location = backups_api.openBackupLocationWithOptions(self.alloc, parsed.value.location, .{
            .secret_store = self.cfg.secret_store,
            .node_config = self.cfg.node_config,
            .connection = connection,
            .required_capability = "restore.read",
            .io = self.sharedApiIo(),
        }) catch |err| return try jsonErrorResponse(self.alloc, 400, backups_api.backupLocationErrorMessage(err) orelse "invalid restore location");
        location.deinit(self.alloc);
        const idempotency_namespace = try restoreIdempotencyNamespaceAlloc(self.alloc, principal, .table, table_name);
        defer self.alloc.free(idempotency_namespace);
        const encoded = self.restore_job_store.start(self.alloc, .{
            .scope = .table,
            .table_name = table_name,
            .backup_id = parsed.value.backup_id,
            .location = parsed.value.location,
            .connection = connection,
            .idempotency_namespace = idempotency_namespace,
            .idempotency_key = idempotency_key,
        }) catch |err| return try restoreJobStartErrorResponse(self.alloc, err);
        defer self.alloc.free(encoded);
        var state = try std.json.parseFromSlice(restore_jobs.JobState, self.alloc, encoded, .{ .ignore_unknown_fields = true });
        defer state.deinit();
        if (!restore_jobs.isTerminal(state.value.phase)) self.schedulePendingRestoreJobs() catch |err|
            std.log.err("accepted table restore job scheduling deferred job_id={d} err={s}", .{ state.value.job_id, @errorName(err) });
        return try self.restoreJobResponse(202, encoded);
    }

    pub fn handlePublicCatalogTableRestore(self: *ApiHttpServer, target: catalog_resources.TableTarget, body: []const u8) !http_common.HttpResponse {
        const parsed_req = backups_api.parseRestoreRequest(self.alloc, body) catch |err| switch (err) {
            else => return try textResponse(self.alloc, 400, "invalid restore request"),
        };
        defer parsed_req.deinit();

        var location = backups_api.openBackupLocationWithSecrets(self.alloc, parsed_req.value.location, self.cfg.secret_store) catch |err| {
            if (backups_api.backupLocationErrorMessage(err)) |msg| {
                return try textResponse(self.alloc, 400, msg);
            }
            return err;
        };
        defer location.deinit(self.alloc);

        self.restoreOwnedCatalogTableWithRetry(target, &location, parsed_req.value.location, parsed_req.value.backup_id) catch |err| switch (err) {
            error.TableAlreadyExists => return try textResponse(self.alloc, 400, "restore target already exists"),
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            error.UnsupportedBackupMigrationState => return try textResponse(self.alloc, 400, "restore does not support active schema migration"),
            error.UnsupportedBackupFormat => return try textResponse(self.alloc, 400, "restore does not support this backup layout"),
            error.InvalidBackupRequest => return try textResponse(self.alloc, 400, "invalid restore request"),
            else => {
                std.log.err("public catalog table restore failed table={s}.{s}.{s} err={}", .{ target.database_name, target.namespace_name, target.table_name, err });
                return try textResponse(self.alloc, 500, "restore failed");
            },
        };

        const response_body = try backups_api.encodeRestoreTriggered(self.alloc);
        defer self.alloc.free(response_body);
        const RestoreTriggered = struct {
            restore: []const u8,
        };
        var arena_impl = std.heap.ArenaAllocator.init(self.alloc);
        defer arena_impl.deinit();
        const parsed = try parseJsonResponseBody(RestoreTriggered, arena_impl.allocator(), response_body);
        return try jsonResponseWithStatus(self.alloc, 202, parsed);
    }

    const ForeignKeyIntegrityRequest = struct {
        action: ?[]const u8 = null,
        phase: ?[]const u8 = null,
        constraint_name: ?[]const u8 = null,
        doc_key: ?[]const u8 = null,
        lower_doc_key: ?[]const u8 = null,
        upper_doc_key: ?[]const u8 = null,
        violation_limit: ?usize = null,
        job_id: ?[]const u8 = null,
        worker_id: ?[]const u8 = null,
        lease_ms: ?u64 = null,
        max_work_units: ?usize = null,
        controller: ?[]const u8 = null,
        schedule_id: ?[]const u8 = null,
        action_schedule_action_job_id: ?[]const u8 = null,
        action_schedule_action: ?[]const u8 = null,
        action_job_action: ?[]const u8 = null,
        parent_table: ?[]const u8 = null,
        parent_key: ?[]const u8 = null,
        updated_parent_key: ?[]const u8 = null,
        page_limit: ?usize = null,
    };

    fn parseForeignKeyIntegrityAction(value: ?[]const u8) !table_writes.ForeignKeyIntegrityAction {
        const text = value orelse "validate";
        if (enumTokenEql(text, "plan")) return .plan;
        if (enumTokenEql(text, "validate")) return .validate;
        if (enumTokenEql(text, "dry_run")) return .dry_run;
        if (enumTokenEql(text, "repair")) return .repair;
        if (enumTokenEql(text, "list")) return .list;
        if (enumTokenEql(text, "explain_delete")) return .explain_delete;
        if (enumTokenEql(text, "progress")) return .progress;
        return error.InvalidForeignKeyIntegrityRequest;
    }

    const UniqueIntegrityRequest = struct {
        action: ?[]const u8 = null,
        lower_doc_key: ?[]const u8 = null,
        upper_doc_key: ?[]const u8 = null,
    };

    const max_public_relational_index_repair_work_units: usize = 1024;
    const relational_index_repair_job_status_suffix_prefix = "relational-column-backed-index-repair/jobs/";

    const RelationalColumnBackedIndexRepairRequest = struct {
        worker_id: ?[]const u8 = null,
        job_id: ?[]const u8 = null,
        lease_ms: ?u64 = null,
        max_work_units: ?usize = null,
    };

    fn parseUniqueIntegrityAction(value: ?[]const u8) !table_writes.UniqueConstraintIntegrityAction {
        const text = value orelse "validate";
        if (enumTokenEql(text, "validate")) return .validate;
        if (enumTokenEql(text, "dry_run")) return .dry_run;
        if (enumTokenEql(text, "repair")) return .repair;
        if (enumTokenEql(text, "progress")) return .progress;
        return error.InvalidUniqueIntegrityRequest;
    }

    fn publicRelationalColumnBackedIndexRepairMaxWorkUnits(value: ?usize) !usize {
        const raw = value orelse 1;
        if (raw == 0) return error.InvalidRelationalColumnBackedIndexRepairRequest;
        return @min(raw, max_public_relational_index_repair_work_units);
    }

    fn enumTokenEql(actual: []const u8, expected: []const u8) bool {
        var actual_index: usize = 0;
        var expected_index: usize = 0;
        while (true) {
            while (actual_index < actual.len and enumTokenSeparator(actual[actual_index])) actual_index += 1;
            while (expected_index < expected.len and enumTokenSeparator(expected[expected_index])) expected_index += 1;
            if (actual_index == actual.len or expected_index == expected.len) break;
            if (std.ascii.toLower(actual[actual_index]) != std.ascii.toLower(expected[expected_index])) return false;
            actual_index += 1;
            expected_index += 1;
        }
        while (actual_index < actual.len and enumTokenSeparator(actual[actual_index])) actual_index += 1;
        while (expected_index < expected.len and enumTokenSeparator(expected[expected_index])) expected_index += 1;
        return actual_index == actual.len and expected_index == expected.len;
    }

    fn enumTokenSeparator(ch: u8) bool {
        return ch == ' ' or ch == '_' or ch == '-';
    }

    pub fn handlePublicTableForeignKeyIntegrity(self: *ApiHttpServer, table_name: []const u8, body: []const u8) !http_common.HttpResponse {
        const source = self.table_writes orelse return try textResponse(self.alloc, 404, "not found");
        var parsed = std.json.parseFromSlice(
            ForeignKeyIntegrityRequest,
            self.alloc,
            if (body.len == 0) "{}" else body,
            .{ .ignore_unknown_fields = true },
        ) catch return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
        defer parsed.deinit();

        const action_text = parsed.value.action orelse "validate";
        if (enumTokenEql(action_text, "requeue_action_job")) {
            const job_id = parsed.value.job_id orelse return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            const action_job_action = parsed.value.action_job_action orelse return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            const worker_id = parsed.value.worker_id orelse return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            const constraint_name = parsed.value.constraint_name orelse return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            const parent_table = parsed.value.parent_table orelse return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            const parent_key = parsed.value.parent_key orelse return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            const page_limit = @min(parsed.value.page_limit orelse 1024, 10_000);
            if (job_id.len == 0 or action_job_action.len == 0 or worker_id.len == 0 or constraint_name.len == 0 or parent_table.len == 0 or parent_key.len == 0 or page_limit == 0) {
                return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            }
            if (parsed.value.controller != null or parsed.value.phase != null or parsed.value.doc_key != null) {
                return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            }
            var result = (source.foreignKeyActionJobRequeue(
                self.alloc,
                table_name,
                job_id,
                action_job_action,
                worker_id,
                constraint_name,
                parent_table,
                parent_key,
                parsed.value.updated_parent_key,
                page_limit,
            ) catch |err| switch (err) {
                error.InvalidForeignKeyActionJob, error.InvalidForeignKeyIntegrityRequest => return try textResponse(self.alloc, 400, "invalid foreign key integrity request"),
                error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
                error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
                error.ForeignKeyNotFound => return try textResponse(self.alloc, 404, "foreign key not found"),
                error.ForeignKeyActionJobNotFound => return try textResponse(self.alloc, 404, "foreign key action job not found"),
                error.UnknownGroup => return try textResponse(self.alloc, 404, "not found"),
                error.ReadOnly => return try textResponse(self.alloc, 405, "method not allowed"),
                else => return err,
            }) orelse return try textResponse(self.alloc, 404, "not found");
            defer result.deinit(self.alloc);
            return try jsonResponse(self.alloc, result);
        }
        if (enumTokenEql(action_text, "requeue_action_schedule")) {
            const schedule_id = parsed.value.schedule_id orelse return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            const action_job_id = parsed.value.action_schedule_action_job_id orelse return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            const schedule_action = parsed.value.action_schedule_action orelse parsed.value.action_job_action orelse return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            const worker_id = parsed.value.worker_id orelse return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            const constraint_name = parsed.value.constraint_name orelse return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            const parent_table = parsed.value.parent_table orelse return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            const parent_key = parsed.value.parent_key orelse return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            const page_limit = @min(parsed.value.page_limit orelse 1024, 10_000);
            if (schedule_id.len == 0 or action_job_id.len == 0 or schedule_action.len == 0 or worker_id.len == 0 or constraint_name.len == 0 or parent_table.len == 0 or parent_key.len == 0 or page_limit == 0) {
                return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            }
            if (parsed.value.controller != null or parsed.value.phase != null or parsed.value.doc_key != null or parsed.value.job_id != null) {
                return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            }
            var result = (source.foreignKeyActionScheduleRequeue(
                self.alloc,
                table_name,
                schedule_id,
                action_job_id,
                schedule_action,
                worker_id,
                constraint_name,
                parent_table,
                parent_key,
                parsed.value.updated_parent_key,
                page_limit,
            ) catch |err| switch (err) {
                error.InvalidForeignKeyActionJob, error.InvalidForeignKeyIntegrityRequest => return try textResponse(self.alloc, 400, "invalid foreign key integrity request"),
                error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
                error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
                error.ForeignKeyNotFound => return try textResponse(self.alloc, 404, "foreign key not found"),
                error.ForeignKeyActionScheduleNotFound => return try textResponse(self.alloc, 404, "foreign key action schedule not found"),
                error.UnknownGroup => return try textResponse(self.alloc, 404, "not found"),
                error.ReadOnly => return try textResponse(self.alloc, 405, "method not allowed"),
                else => return err,
            }) orelse return try textResponse(self.alloc, 404, "foreign key action schedule not found");
            defer result.deinit(self.alloc);
            return try jsonResponse(self.alloc, result);
        }

        const action = parseForeignKeyIntegrityAction(parsed.value.action) catch {
            return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
        };
        const violation_limit = @min(parsed.value.violation_limit orelse 100, 10_000);
        if (action == .explain_delete and (parsed.value.doc_key == null or parsed.value.doc_key.?.len == 0)) {
            return try textResponse(self.alloc, 400, "foreign key delete explain requires doc_key");
        }
        const lower_doc_key = if (action == .explain_delete) parsed.value.doc_key.? else parsed.value.lower_doc_key orelse "";
        const upper_doc_key = if (action == .explain_delete) "" else parsed.value.upper_doc_key orelse "";
        if (parsed.value.worker_id) |worker_id| {
            if (worker_id.len == 0) return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            if (parsed.value.controller) |controller| {
                if (!std.mem.eql(u8, controller, "schema")) return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
                if (parsed.value.job_id != null) return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
                var result = (source.foreignKeyIntegritySchemaControllerPass(
                    self.alloc,
                    table_name,
                    action,
                    worker_id,
                    parsed.value.lease_ms orelse 60_000,
                    @max(1, parsed.value.max_work_units orelse 1),
                    parsed.value.constraint_name,
                    lower_doc_key,
                    upper_doc_key,
                    violation_limit,
                ) catch |err| switch (err) {
                    error.InvalidForeignKeyIntegrityRequest => return try textResponse(self.alloc, 400, "invalid foreign key integrity request"),
                    error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
                    error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
                    error.ForeignKeyNotFound => return try textResponse(self.alloc, 404, "foreign key not found"),
                    error.UnknownGroup => return try textResponse(self.alloc, 404, "not found"),
                    error.ReadOnly => return try textResponse(self.alloc, 405, "method not allowed"),
                    else => return err,
                }) orelse return try textResponse(self.alloc, 404, "not found");
                defer result.deinit(self.alloc);
                return try jsonResponse(self.alloc, result);
            }
            if (parsed.value.job_id) |job_id| {
                if (job_id.len == 0) return try textResponse(self.alloc, 400, "invalid foreign key integrity request");
            }
            const generated_job_id = if (parsed.value.job_id == null)
                try table_writes.stableForeignKeyIntegrityJobIdAlloc(self.alloc, table_name, action, parsed.value.constraint_name, lower_doc_key, upper_doc_key)
            else
                null;
            defer if (generated_job_id) |job_id| self.alloc.free(job_id);
            const effective_job_id = parsed.value.job_id orelse generated_job_id.?;
            var result = (source.foreignKeyIntegrityWorkerPass(
                self.alloc,
                table_name,
                action,
                effective_job_id,
                worker_id,
                parsed.value.lease_ms orelse 60_000,
                @max(1, parsed.value.max_work_units orelse 1),
                parsed.value.constraint_name,
                lower_doc_key,
                upper_doc_key,
                violation_limit,
            ) catch |err| switch (err) {
                error.InvalidForeignKeyIntegrityRequest => return try textResponse(self.alloc, 400, "invalid foreign key integrity request"),
                error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
                error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
                error.ForeignKeyNotFound => return try textResponse(self.alloc, 404, "foreign key not found"),
                error.UnknownGroup => return try textResponse(self.alloc, 404, "not found"),
                error.ReadOnly => return try textResponse(self.alloc, 405, "method not allowed"),
                else => return err,
            }) orelse return try textResponse(self.alloc, 404, "not found");
            defer result.deinit(self.alloc);
            return try jsonResponse(self.alloc, result);
        }
        var result = (source.foreignKeyIntegrity(
            self.alloc,
            table_name,
            action,
            parsed.value.constraint_name,
            lower_doc_key,
            upper_doc_key,
            violation_limit,
        ) catch |err| switch (err) {
            error.UnsupportedOperation => return try textResponse(self.alloc, 405, "method not allowed"),
            error.TableNotFound => return try textResponse(self.alloc, 404, "not found"),
            error.ForeignKeyNotFound => return try textResponse(self.alloc, 404, "foreign key not found"),
            error.UnknownGroup => return try textResponse(self.alloc, 404, "not found"),
            error.ReadOnly => return try textResponse(self.alloc, 405, "method not allowed"),
            else => return err,
        }) orelse return try textResponse(self.alloc, 404, "not found");
        defer result.deinit(self.alloc);
        return try jsonResponse(self.alloc, result);
    }

