const ExplicitCatalogPermissionSubroute = struct {
    table_name: []const u8,
    suffix: ?[]const u8 = null,
};

fn matchTableDocumentLookupForPermission(path: []const u8) ?struct { table_name: []const u8 } {
    if (!std.mem.startsWith(u8, path, routes.Routes.tables_prefix)) return null;
    const rest = path[routes.Routes.tables_prefix.len..];
    const marker_index = std.mem.indexOf(u8, rest, routes.Routes.documents_marker) orelse return null;
    if (marker_index == 0) return null;
    const table_name = rest[0..marker_index];
    const key = rest[marker_index + routes.Routes.documents_marker.len ..];
    if (table_name.len == 0 or key.len == 0) return null;
    if (std.mem.indexOfScalar(u8, table_name, '/') != null or std.mem.indexOfScalar(u8, key, '/') != null) return null;
    return .{ .table_name = table_name };
}

fn explicitCatalogPermissionSubroute(table_path: []const u8) ExplicitCatalogPermissionSubroute {
    if (std.mem.indexOfScalar(u8, table_path, '/')) |slash| {
        return .{ .table_name = table_path[0..slash], .suffix = table_path[slash + 1 ..] };
    }
    return .{ .table_name = table_path };
}

fn explicitCatalogTablePermissionType(method: http_common.Method, suffix: ?[]const u8) ?usermgr.PermissionType {
    const value = suffix orelse return switch (method) {
        .GET => .read,
        .POST, .PUT, .DELETE => .admin,
    };
    if (std.mem.eql(u8, value, "query")) return if (method == .POST) .read else null;
    if (std.mem.eql(u8, value, "batch") or std.mem.eql(u8, value, "rows/batch")) return if (method == .POST) .write else null;
    if (std.mem.eql(u8, value, "backup") or std.mem.eql(u8, value, "restore")) return if (method == .POST) .admin else null;
    if (std.mem.eql(u8, value, "relational-column-backed-index-repair")) return if (method == .POST) .admin else null;
    if (std.mem.startsWith(u8, value, "relational-column-backed-index-repair/jobs/")) return if (method == .GET) .admin else null;
    if (std.mem.eql(u8, value, "indexes")) return if (method == .GET) .read else null;
    if (std.mem.startsWith(u8, value, "indexes/")) return switch (method) {
        .GET => .read,
        .POST, .DELETE => .admin,
        else => null,
    };
    if (std.mem.startsWith(u8, value, "documents/")) {
        if (std.mem.endsWith(u8, value, "/reprocess")) return if (method == .POST) .admin else null;
        return if (method == .GET) .read else null;
    }
    if (std.mem.eql(u8, value, "artifacts")) return if (method == .GET) .read else null;
    if (std.mem.startsWith(u8, value, "artifacts/")) {
        if (std.mem.endsWith(u8, value, "/enrichment")) return switch (method) {
            .PUT, .DELETE => .admin,
            else => null,
        };
        if (std.mem.endsWith(u8, value, "/reprocess")) return if (method == .POST) .admin else null;
        if (std.mem.indexOf(u8, value, "/reprocess-jobs/")) |_| {
            if (std.mem.endsWith(u8, value, "/advance") or std.mem.endsWith(u8, value, "/cancel")) return if (method == .POST) .admin else null;
            return if (method == .GET) .read else null;
        }
        if (std.mem.endsWith(u8, value, "/reprocess-jobs")) return if (method == .POST) .admin else null;
    }
    return null;
}

fn databasePermission(alloc: std.mem.Allocator, encoded_database_name: []const u8, permission_type: usermgr.PermissionType) !RequiredPermission {
    return .{
        .resource_type = .database,
        .resource = try http_route_helpers.decodePercentEncodedPathComponentAlloc(alloc, encoded_database_name),
        .permission_type = permission_type,
        .owns_resource = true,
    };
}

fn namespacePermission(alloc: std.mem.Allocator, encoded_database_name: []const u8, encoded_namespace_name: []const u8, permission_type: usermgr.PermissionType) !RequiredPermission {
    const database_name = try http_route_helpers.decodePercentEncodedPathComponentAlloc(alloc, encoded_database_name);
    defer alloc.free(database_name);
    const namespace_name = try http_route_helpers.decodePercentEncodedPathComponentAlloc(alloc, encoded_namespace_name);
    defer alloc.free(namespace_name);
    return .{
        .resource_type = .namespace,
        .resource = try catalog_resources.namespaceResourceNameAlloc(alloc, database_name, namespace_name),
        .permission_type = permission_type,
        .owns_resource = true,
    };
}

fn catalogTablePermission(alloc: std.mem.Allocator, encoded_database_name: []const u8, encoded_namespace_name: []const u8, encoded_table_name: []const u8, permission_type: usermgr.PermissionType) !RequiredPermission {
    const database_name = try http_route_helpers.decodePercentEncodedPathComponentAlloc(alloc, encoded_database_name);
    defer alloc.free(database_name);
    const namespace_name = try http_route_helpers.decodePercentEncodedPathComponentAlloc(alloc, encoded_namespace_name);
    defer alloc.free(namespace_name);
    const table_name = try http_route_helpers.decodePercentEncodedPathComponentAlloc(alloc, encoded_table_name);
    defer alloc.free(table_name);
    return .{
        .resource_type = .table,
        .resource = try catalog_resources.tableResourceNameAlloc(alloc, database_name, namespace_name, table_name),
        .permission_type = permission_type,
        .owns_resource = true,
    };
}

fn tablePermission(alloc: std.mem.Allocator, encoded_table_name: []const u8, permission_type: usermgr.PermissionType) !RequiredPermission {
    return .{
        .resource_type = .table,
        .resource = try http_route_helpers.decodePercentEncodedPathComponentAlloc(alloc, encoded_table_name),
        .permission_type = permission_type,
        .owns_resource = true,
    };
}

fn tableNameForGraphPath(path: []const u8) ?[]const u8 {
    if (!std.mem.startsWith(u8, path, routes.Routes.tables_prefix)) return null;
    const rest = path[routes.Routes.tables_prefix.len..];
    const marker = std.mem.indexOf(u8, rest, "/query/graph/") orelse return null;
    if (marker == 0) return null;
    return rest[0..marker];
}

pub fn permissionsAllow(
    permissions: []const usermgr.Permission,
    resource_type: usermgr.ResourceType,
    resource: []const u8,
    permission_type: usermgr.PermissionType,
) bool {
    for (permissions) |permission| {
        const type_match = permission.resource_type == .@"*" or permission.resource_type == resource_type;
        const resource_match = std.mem.eql(u8, permission.resource, "*") or
            (if (resource_type == .table)
                catalog_resources.tableResourceMatches(permission.resource, resource)
            else
                std.mem.eql(u8, permission.resource, resource));
        if (!type_match or !resource_match) continue;
        if (permission.type == .admin or permission.type == permission_type) return true;
    }
    return false;
}

test "table permissions allow default public qualified resources during migration" {
    const alloc = std.testing.allocator;

    var qualified = try usermgr.Permission.initOwned(alloc, .table, "default.public.docs", .read);
    defer qualified.deinit(alloc);
    var non_default = try usermgr.Permission.initOwned(alloc, .table, "tenant_ops.analytics.docs", .read);
    defer non_default.deinit(alloc);
    var legacy = try usermgr.Permission.initOwned(alloc, .table, "docs", .read);
    defer legacy.deinit(alloc);

    try std.testing.expect(permissionsAllow(&.{qualified}, .table, "docs", .read));
    try std.testing.expect(permissionsAllow(&.{legacy}, .table, "default.public.docs", .read));
    try std.testing.expect(!permissionsAllow(&.{non_default}, .table, "docs", .read));
    try std.testing.expect(!permissionsAllow(&.{legacy}, .table, "tenant_ops.analytics.docs", .read));
}

