test "http relational rows planner fallback error payload matrix" {
    const Case = struct {
        err: anyerror,
        status: u16,
        fallback_class: []const u8,
        retryable: bool,
    };
    const cases = [_]Case{
        .{ .err = error.RelationalIndexUnavailable, .status = 503, .fallback_class = "unavailable", .retryable = true },
        .{ .err = error.RelationalIndexStale, .status = 503, .fallback_class = "stale", .retryable = true },
        .{ .err = error.RelationalIndexMalformed, .status = 500, .fallback_class = "malformed", .retryable = false },
        .{ .err = error.RelationalIndexPlanTooExpensive, .status = 429, .fallback_class = "too-expensive", .retryable = true },
        .{ .err = error.RelationalIndexUnsupportedShape, .status = 422, .fallback_class = "unsupported-shape", .retryable = false },
    };

    for (cases) |case| {
        var response = try relationalRowsPlannerFallbackErrorResponse(std.testing.allocator, case.err);
        defer response.deinit(std.testing.allocator);
        try std.testing.expectEqual(case.status, response.status);
        try std.testing.expectEqualStrings("application/json", response.content_type.?);
        var parsed = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, response.body, .{});
        defer parsed.deinit();
        try std.testing.expectEqualStrings("relational_index_plan_rejected", parsed.value.object.get("error").?.string);
        try std.testing.expectEqualStrings(case.fallback_class, parsed.value.object.get("fallback_class").?.string);
        try std.testing.expectEqual(case.retryable, parsed.value.object.get("retryable").?.bool);
    }
}

fn jsonResponseWithStatusOmitNullOptionals(
    alloc: std.mem.Allocator,
    status: u16,
    value: anytype,
) !http_common.HttpResponse {
    return .{
        .status = status,
        .content_type = try alloc.dupe(u8, "application/json"),
        .body = try std.json.Stringify.valueAlloc(alloc, value, .{ .emit_null_optional_fields = false }),
    };
}

fn jsonResponseOmitNullOptionals(alloc: std.mem.Allocator, value: anytype) !http_common.HttpResponse {
    return try jsonResponseWithStatusOmitNullOptionals(alloc, 200, value);
}

fn parseJsonResponseBody(
    comptime T: type,
    alloc: std.mem.Allocator,
    body: []const u8,
) !T {
    return try std.json.parseFromSliceLeaky(T, alloc, body, .{
        .allocate = .alloc_always,
    });
}

fn isNdjsonContentType(content_type: ?[]const u8) bool {
    const value = content_type orelse return false;
    const media_type = std.mem.trim(u8, if (std.mem.indexOfScalar(u8, value, ';')) |idx| value[0..idx] else value, " \t");
    return std.ascii.eqlIgnoreCase(media_type, "application/x-ndjson");
}

fn queryTableNameAlloc(alloc: std.mem.Allocator, body: []const u8) ![]u8 {
    var parsed = metadata_openapi.server.parseGlobalQueryBody(alloc, body) catch return error.InvalidQueryRequest;
    defer parsed.deinit();
    return try alloc.dupe(u8, parsed.value.table orelse "");
}

fn documentArtifactJobMatches(encoded: []const u8, table_name: []const u8, artifact_name: []const u8) bool {
    var parsed = std.json.parseFromSlice(artifact_reprocess_jobs.JobState, std.heap.page_allocator, encoded, .{ .ignore_unknown_fields = true }) catch return false;
    defer parsed.deinit();
    return std.mem.eql(u8, parsed.value.table_name, table_name) and std.mem.eql(u8, parsed.value.artifact_name, artifact_name);
}

