pub fn apiKeyToOpenApi(
    alloc: std.mem.Allocator,
    api_key: usermgr.ApiKey,
) !usermgr_openapi.ApiKey {
    return .{
        .key_id = api_key.key_id,
        .name = api_key.name,
        .username = api_key.username,
        .permissions = if (api_key.permissions.len > 0) try clonePermissionsToOpenApi(alloc, api_key.permissions) else null,
        .row_filter = if (api_key.row_filter.len > 0) try rowFilterMapToOpenApi(alloc, api_key.row_filter) else null,
        .created_at = try formatTimestampOwned(alloc, api_key.created_at_ns),
        .expires_at = if (api_key.expires_at_ns) |value| try formatTimestampOwned(alloc, value) else null,
    };
}

pub fn createdApiKeyToOpenApi(
    alloc: std.mem.Allocator,
    created: usermgr.CreatedApiKey,
) !usermgr_openapi.ApiKeyWithSecret {
    const base = try apiKeyToOpenApi(alloc, created.key);
    return .{
        .key_id = base.key_id,
        .name = base.name,
        .username = base.username,
        .permissions = base.permissions,
        .row_filter = base.row_filter,
        .created_at = base.created_at,
        .expires_at = base.expires_at,
        .key_secret = created.key_secret,
        .encoded = created.encoded,
    };
}

fn parseGoDurationNs(raw: []const u8) !u64 {
    if (raw.len == 0) return error.InvalidDuration;
    var i: usize = 0;
    var total: u64 = 0;
    while (i < raw.len) {
        const start = i;
        while (i < raw.len and std.ascii.isDigit(raw[i])) : (i += 1) {}
        if (i == start) return error.InvalidDuration;
        const value = try std.fmt.parseUnsigned(u64, raw[start..i], 10);
        const unit: u64 = if (std.mem.startsWith(u8, raw[i..], "ns")) blk: {
            i += 2;
            break :blk @as(u64, 1);
        } else if (std.mem.startsWith(u8, raw[i..], "us")) blk: {
            i += 2;
            break :blk @as(u64, std.time.ns_per_us);
        } else if (std.mem.startsWith(u8, raw[i..], "ms")) blk: {
            i += 2;
            break :blk @as(u64, std.time.ns_per_ms);
        } else if (i < raw.len and raw[i] == 's') blk: {
            i += 1;
            break :blk @as(u64, std.time.ns_per_s);
        } else if (i < raw.len and raw[i] == 'm') blk: {
            i += 1;
            break :blk @as(u64, std.time.ns_per_min);
        } else if (i < raw.len and raw[i] == 'h') blk: {
            i += 1;
            break :blk @as(u64, std.time.ns_per_hour);
        } else if (i < raw.len and raw[i] == 'd') blk: {
            i += 1;
            break :blk @as(u64, 24 * std.time.ns_per_hour);
        } else return error.InvalidDuration;
        total += value * unit;
    }
    return total;
}

fn formatTimestampOwned(alloc: std.mem.Allocator, ns: u64) ![]u8 {
    const epoch_seconds = std.time.epoch.EpochSeconds{
        .secs = @divFloor(ns, std.time.ns_per_s),
    };
    const year_day = epoch_seconds.getEpochDay().calculateYearDay();
    const month_day = year_day.calculateMonthDay();
    const day_seconds = epoch_seconds.getDaySeconds();
    return try std.fmt.allocPrint(alloc, "{d:0>4}-{d:0>2}-{d:0>2}T{d:0>2}:{d:0>2}:{d:0>2}Z", .{
        year_day.year,
        month_day.month.numeric(),
        month_day.day_index + 1,
        day_seconds.getHoursIntoDay(),
        day_seconds.getMinutesIntoHour(),
        day_seconds.getSecondsIntoMinute(),
    });
}

fn nowNs() u64 {
    return platform_time.realtimeNs();
}

pub fn freePermissions(alloc: std.mem.Allocator, permissions: []const usermgr.Permission) void {
    for (permissions) |permission| {
        var owned = permission;
        owned.deinit(alloc);
    }
    alloc.free(@constCast(permissions));
}

fn clonePermissions(alloc: std.mem.Allocator, permissions: []const usermgr.Permission) ![]usermgr.Permission {
    var out = std.ArrayList(usermgr.Permission).empty;
    errdefer {
        for (out.items) |*permission| permission.deinit(alloc);
        out.deinit(alloc);
    }
    for (permissions) |permission| {
        var cloned = try usermgr.Permission.initOwned(
            alloc,
            permission.resource_type,
            permission.resource,
            permission.type,
        );
        var cloned_owned = true;
        errdefer if (cloned_owned) cloned.deinit(alloc);
        try out.append(alloc, cloned);
        cloned_owned = false;
    }
    return try out.toOwnedSlice(alloc);
}

pub fn freeRowFilters(alloc: std.mem.Allocator, row_filters: []const usermgr.RowFilterEntry) void {
    for (row_filters) |entry| {
        var owned = entry;
        owned.deinit(alloc);
    }
    alloc.free(@constCast(row_filters));
}

fn cloneRowFilters(alloc: std.mem.Allocator, row_filters: []const usermgr.RowFilterEntry) ![]usermgr.RowFilterEntry {
    var out = std.ArrayList(usermgr.RowFilterEntry).empty;
    errdefer {
        for (out.items) |*entry| entry.deinit(alloc);
        out.deinit(alloc);
    }
    for (row_filters) |entry| {
        var cloned = try usermgr.RowFilterEntry.initOwned(alloc, entry.table, entry.filter);
        var cloned_owned = true;
        errdefer if (cloned_owned) cloned.deinit(alloc);
        try out.append(alloc, cloned);
        cloned_owned = false;
    }
    return try out.toOwnedSlice(alloc);
}

fn freeRoleSettings(alloc: std.mem.Allocator, settings: []const usermgr.RoleSetting) void {
    for (settings) |setting| {
        var owned = setting;
        owned.deinit(alloc);
    }
    if (settings.len > 0) alloc.free(@constCast(settings));
}

fn cloneRoleSettings(alloc: std.mem.Allocator, settings: []const usermgr.RoleSetting) ![]usermgr.RoleSetting {
    var out = std.ArrayList(usermgr.RoleSetting).empty;
    errdefer {
        for (out.items) |*setting| setting.deinit(alloc);
        out.deinit(alloc);
    }
    for (settings) |setting| {
        try out.append(alloc, try usermgr.RoleSetting.initOwned(alloc, setting.name, setting.value));
    }
    return try out.toOwnedSlice(alloc);
}

fn cloneAuthenticatedIdentity(
    alloc: std.mem.Allocator,
    username: []const u8,
    permissions: []const usermgr.Permission,
    row_filter: []const usermgr.RowFilterEntry,
    metadata_json: []const u8,
    roles: []const []const u8,
    role_settings: []const usermgr.RoleSetting,
    role_runtime_settings: []const usermgr.RoleSetting,
) !AuthenticatedIdentity {
    var identity = AuthenticatedIdentity{
        .username = try alloc.dupe(u8, username),
        .metadata_json = &.{},
    };
    errdefer identity.deinit(alloc);
    identity.permissions = try clonePermissions(alloc, permissions);
    identity.row_filter = try cloneRowFilters(alloc, row_filter);
    identity.metadata_json = try alloc.dupe(u8, if (metadata_json.len > 0) metadata_json else "{}");
    identity.roles = try cloneOwnedStrings(alloc, roles);
    identity.role_settings = try cloneRoleSettings(alloc, role_settings);
    identity.role_runtime_settings = try cloneRoleSettings(alloc, role_runtime_settings);
    return identity;
}

pub fn freeAuthSubjects(alloc: std.mem.Allocator, subjects: []const usermgr.AuthSubjectEntry) void {
    for (subjects) |entry| {
        var owned = entry;
        owned.deinit(alloc);
    }
    alloc.free(@constCast(subjects));
}

pub const AuthSubjectResponse = struct {
    subject: []const u8,
    kind: []const u8,
};

pub fn authSubjectsToResponse(
    alloc: std.mem.Allocator,
    subjects: []const usermgr.AuthSubjectEntry,
) ![]const AuthSubjectResponse {
    const out = try alloc.alloc(AuthSubjectResponse, subjects.len);
    for (subjects, 0..) |entry, i| {
        out[i] = .{
            .subject = entry.subject,
            .kind = entry.kind.slice(),
        };
    }
    return out;
}

pub fn effectiveRowFilterJson(identity: anytype, table_name: []const u8) ?[]const u8 {
    const row_filters = if (comptime @typeInfo(@TypeOf(identity)) == .optional)
        if (identity) |value| value.row_filter else return null
    else
        identity.row_filter;
    for (row_filters) |entry| {
        if (catalog_resources.tableResourceMatches(entry.table, table_name)) {
            if (std.mem.eql(u8, entry.filter, "null")) return null;
            return entry.filter;
        }
    }
    for (row_filters) |entry| {
        if (std.mem.eql(u8, entry.table, "*")) {
            if (std.mem.eql(u8, entry.filter, "null")) return null;
            return entry.filter;
        }
    }
    return null;
}

pub fn resolveEffectiveRowFilterJson(
    alloc: std.mem.Allocator,
    identity: anytype,
    table_name: []const u8,
) !?[]u8 {
    const raw = effectiveRowFilterJson(identity, table_name) orelse return null;
    if (comptime @typeInfo(@TypeOf(identity)) == .optional) {
        const active_identity = identity orelse return try alloc.dupe(u8, raw);
        return try resolveAuthRowFilterJson(alloc, active_identity, raw);
    }
    return try resolveAuthRowFilterJson(alloc, identity, raw);
}

pub fn resolveAuthRowFilterJson(
    alloc: std.mem.Allocator,
    identity: anytype,
    filter_json: []const u8,
) ![]u8 {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, filter_json, .{}) catch return error.InvalidQueryRequest;
    defer parsed.deinit();
    try validateAuthRowFilterValue(parsed.value);
    var remaining_nodes: usize = auth_filter_max_tree_nodes;

    var parsed_metadata: ?std.json.Parsed(std.json.Value) = null;
    defer if (parsed_metadata) |*metadata| metadata.deinit();
    if (authFilterUsesMetadataReference(parsed.value)) {
        parsed_metadata = std.json.parseFromSlice(
            std.json.Value,
            alloc,
            if (identity.metadata_json.len > 0) identity.metadata_json else "{}",
            .{},
        ) catch |err| switch (err) {
            error.OutOfMemory => return error.OutOfMemory,
            else => return try alloc.dupe(u8, "{\"match_none\":{}}"),
        };
    }
    const context = AuthRowFilterResolveContext{
        .identity = identity,
        .metadata = if (parsed_metadata) |metadata| metadata.value else null,
    };
    var resolved = resolveAuthRowFilterValue(
        alloc,
        context,
        parsed.value,
        .filter,
        &remaining_nodes,
    ) catch |err| switch (err) {
        // Identity metadata is allowed to vary independently of policy
        // admission. Missing or type-incompatible values must deny the whole
        // policy, never turn a protected read into a server error or weaken a
        // negative branch.
        error.AuthRowFilterNoMatch => return try alloc.dupe(u8, "{\"match_none\":{}}"),
        else => return err,
    };
    defer json_helpers.deinitJsonValue(alloc, &resolved);
    return try json_helpers.stringifyJsonValueAlloc(alloc, resolved);
}

pub fn validateAuthRowFilterJson(
    alloc: std.mem.Allocator,
    filter_json: []const u8,
) !void {
    var parsed = std.json.parseFromSlice(std.json.Value, alloc, filter_json, .{}) catch return error.InvalidQueryRequest;
    defer parsed.deinit();
    try validateAuthRowFilterValue(parsed.value);

    // Compile a type-correct representative of the policy before it can be
    // persisted. Dynamic auth references are restricted to the documented
    // scalar `term` and array `terms` positions; every other node is validated
    // by the same prepared Zig filter plan used during execution.
    var materialized = try materializeAuthFilterTemplateValue(
        alloc,
        parsed.value,
        .filter,
    );
    defer json_helpers.deinitJsonValue(alloc, &materialized);
    var prepared = try search_pattern_filter.PreparedPatternFilter.initValue(
        alloc,
        materialized,
    );
    prepared.deinit();
}

const AuthFilterTemplateExpectation = enum {
    filter,
    term_body,
    terms_body,
    scalar,
    array,
    static,
};

fn authFilterObjectChildExpectation(
    expectation: AuthFilterTemplateExpectation,
    object: std.json.ObjectMap,
    key: []const u8,
) !AuthFilterTemplateExpectation {
    return switch (expectation) {
        .filter => if (std.mem.eql(u8, key, "term"))
            .term_body
        else if (std.mem.eql(u8, key, "terms"))
            .terms_body
        else
            .filter,
        .term_body => if (object.count() == 1 or
            std.mem.eql(u8, key, "term") or
            std.mem.eql(u8, key, "value"))
            .scalar
        else
            .static,
        .terms_body => if (object.count() == 1 or
            std.mem.eql(u8, key, "terms") or
            std.mem.eql(u8, key, "values"))
            .array
        else
            .static,
        .static => .static,
        .scalar, .array => error.InvalidQueryRequest,
    };
}

fn authFilterArrayChildExpectation(
    expectation: AuthFilterTemplateExpectation,
) !AuthFilterTemplateExpectation {
    return switch (expectation) {
        .filter => .filter,
        .array, .static => .static,
        .term_body, .terms_body, .scalar => error.InvalidQueryRequest,
    };
}

fn materializeAuthFilterTemplateValue(
    alloc: std.mem.Allocator,
    value: std.json.Value,
    expectation: AuthFilterTemplateExpectation,
) !std.json.Value {
    return switch (value) {
        .object => |object| blk: {
            if (object.get("$auth")) |auth_ref| {
                if (object.count() != 1 or
                    (expectation != .scalar and expectation != .array))
                {
                    return error.InvalidQueryRequest;
                }
                const path = if (auth_ref == .string)
                    auth_ref.string
                else
                    return error.InvalidQueryRequest;
                if (!isSupportedAuthPath(path)) return error.InvalidQueryRequest;
                if (std.mem.eql(u8, path, "roles") and expectation != .array) {
                    return error.InvalidQueryRequest;
                }
                if (std.mem.eql(u8, path, "username") and expectation != .scalar) {
                    return error.InvalidQueryRequest;
                }
                if (expectation == .scalar) {
                    break :blk .{ .string = try alloc.dupe(u8, "__auth_validation__") };
                }
                var items = std.json.Array.init(alloc);
                errdefer {
                    for (items.items) |*item| json_helpers.deinitJsonValue(alloc, item);
                    items.deinit();
                }
                const sentinel = try alloc.dupe(u8, "__auth_validation__");
                errdefer alloc.free(sentinel);
                try items.append(.{ .string = sentinel });
                break :blk .{ .array = items };
            }
            if (expectation == .scalar or expectation == .array) {
                return error.InvalidQueryRequest;
            }

            var out = std.json.ObjectMap.empty;
            errdefer {
                var it = out.iterator();
                while (it.next()) |entry| {
                    alloc.free(@constCast(entry.key_ptr.*));
                    json_helpers.deinitJsonValue(alloc, entry.value_ptr);
                }
                out.deinit(alloc);
            }
            var it = object.iterator();
            while (it.next()) |entry| {
                const child_expectation = try authFilterObjectChildExpectation(
                    expectation,
                    object,
                    entry.key_ptr.*,
                );
                const key = try alloc.dupe(u8, entry.key_ptr.*);
                var key_transferred = false;
                errdefer if (!key_transferred) alloc.free(key);
                var child = try materializeAuthFilterTemplateValue(
                    alloc,
                    entry.value_ptr.*,
                    child_expectation,
                );
                var child_transferred = false;
                errdefer if (!child_transferred) {
                    json_helpers.deinitJsonValue(alloc, &child);
                };
                try out.put(alloc, key, child);
                key_transferred = true;
                child_transferred = true;
            }
            break :blk .{ .object = out };
        },
        .array => |array| blk: {
            const child_expectation = try authFilterArrayChildExpectation(expectation);
            var out = std.json.Array.init(alloc);
            errdefer {
                for (out.items) |*item| json_helpers.deinitJsonValue(alloc, item);
                out.deinit();
            }
            for (array.items) |item| {
                var child = try materializeAuthFilterTemplateValue(
                    alloc,
                    item,
                    child_expectation,
                );
                var child_transferred = false;
                errdefer if (!child_transferred) {
                    json_helpers.deinitJsonValue(alloc, &child);
                };
                try out.append(child);
                child_transferred = true;
            }
            break :blk .{ .array = out };
        },
        else => switch (expectation) {
            .array, .term_body, .terms_body => error.InvalidQueryRequest,
            .filter, .scalar, .static => try json_helpers.cloneJsonValue(alloc, value),
        },
    };
}

const auth_filter_max_tree_depth: u8 = 64;
const auth_filter_max_tree_nodes: usize = 16_384;

fn authFilterUsesMetadataReference(value: std.json.Value) bool {
    return switch (value) {
        .object => |object| blk: {
            if (object.get("$auth")) |auth_ref| {
                break :blk auth_ref == .string and
                    std.mem.startsWith(u8, auth_ref.string, "metadata.");
            }
            var it = object.iterator();
            while (it.next()) |entry| {
                if (authFilterUsesMetadataReference(entry.value_ptr.*)) {
                    break :blk true;
                }
            }
            break :blk false;
        },
        .array => |array| blk: {
            for (array.items) |item| {
                if (authFilterUsesMetadataReference(item)) break :blk true;
            }
            break :blk false;
        },
        else => false,
    };
}

fn validateAuthRowFilterValue(value: std.json.Value) !void {
    var remaining_nodes: usize = auth_filter_max_tree_nodes;
    return try validateAuthRowFilterValueBounded(value, 0, &remaining_nodes);
}

fn validateAuthRowFilterValueBounded(
    value: std.json.Value,
    depth: u8,
    remaining_nodes: *usize,
) !void {
    if (depth >= auth_filter_max_tree_depth or remaining_nodes.* == 0) {
        return error.InvalidQueryRequest;
    }
    remaining_nodes.* -= 1;
    switch (value) {
        .object => |object| {
            if (object.get("$auth")) |auth_ref| {
                if (object.count() != 1) return error.InvalidQueryRequest;
                const path = if (auth_ref == .string) auth_ref.string else return error.InvalidQueryRequest;
                if (!isSupportedAuthPath(path)) return error.InvalidQueryRequest;
                return;
            }

            var it = object.iterator();
            while (it.next()) |entry| {
                try validateAuthRowFilterValueBounded(
                    entry.value_ptr.*,
                    depth + 1,
                    remaining_nodes,
                );
            }
        },
        .array => |array| {
            for (array.items) |item| {
                try validateAuthRowFilterValueBounded(
                    item,
                    depth + 1,
                    remaining_nodes,
                );
            }
        },
        else => {},
    }
}

const AuthRowFilterResolveContext = struct {
    identity: AuthenticatedIdentity,
    metadata: ?std.json.Value,
};

fn resolveAuthRowFilterValue(
    alloc: std.mem.Allocator,
    context: AuthRowFilterResolveContext,
    value: std.json.Value,
    expectation: AuthFilterTemplateExpectation,
    remaining_nodes: *usize,
) !std.json.Value {
    return switch (value) {
        .object => |object| blk: {
            if (object.get("$auth")) |auth_ref| {
                if (object.count() != 1 or
                    (expectation != .scalar and expectation != .array))
                {
                    return error.InvalidQueryRequest;
                }
                const path = if (auth_ref == .string) auth_ref.string else return error.InvalidQueryRequest;
                if (!isSupportedAuthPath(path)) return error.InvalidQueryRequest;
                if (std.mem.eql(u8, path, "roles") and expectation != .array) {
                    return error.InvalidQueryRequest;
                }
                if (std.mem.eql(u8, path, "username") and expectation != .scalar) {
                    return error.InvalidQueryRequest;
                }
                const auth_value = authContextJsonValueBounded(
                    alloc,
                    context,
                    path,
                    remaining_nodes.*,
                ) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    else => return error.AuthRowFilterNoMatch,
                };
                var resolved = auth_value.value;
                errdefer json_helpers.deinitJsonValue(alloc, &resolved);
                if (!authFilterValueMatchesExpectation(resolved, expectation)) {
                    return error.AuthRowFilterNoMatch;
                }
                remaining_nodes.* -= auth_value.node_count;
                break :blk resolved;
            }
            if (remaining_nodes.* == 0) return error.AuthRowFilterNoMatch;
            remaining_nodes.* -= 1;
            if (expectation == .scalar or expectation == .array) {
                return error.InvalidQueryRequest;
            }

            var out = std.json.ObjectMap.empty;
            errdefer {
                var it = out.iterator();
                while (it.next()) |entry| {
                    alloc.free(@constCast(entry.key_ptr.*));
                    json_helpers.deinitJsonValue(alloc, entry.value_ptr);
                }
                out.deinit(alloc);
            }
            var it = object.iterator();
            while (it.next()) |entry| {
                const child_expectation = try authFilterObjectChildExpectation(
                    expectation,
                    object,
                    entry.key_ptr.*,
                );
                const key = try alloc.dupe(u8, entry.key_ptr.*);
                var key_transferred = false;
                errdefer if (!key_transferred) alloc.free(key);
                var resolved = try resolveAuthRowFilterValue(
                    alloc,
                    context,
                    entry.value_ptr.*,
                    child_expectation,
                    remaining_nodes,
                );
                var value_transferred = false;
                errdefer if (!value_transferred) json_helpers.deinitJsonValue(alloc, &resolved);
                try out.put(alloc, key, resolved);
                key_transferred = true;
                value_transferred = true;
            }
            break :blk .{ .object = out };
        },
        .array => |array| blk: {
            if (remaining_nodes.* == 0) return error.AuthRowFilterNoMatch;
            remaining_nodes.* -= 1;
            const child_expectation = try authFilterArrayChildExpectation(expectation);
            var out = std.json.Array.init(alloc);
            errdefer {
                for (out.items) |*item| json_helpers.deinitJsonValue(alloc, item);
                out.deinit();
            }
            for (array.items) |item| {
                var resolved = try resolveAuthRowFilterValue(
                    alloc,
                    context,
                    item,
                    child_expectation,
                    remaining_nodes,
                );
                var value_transferred = false;
                errdefer if (!value_transferred) json_helpers.deinitJsonValue(alloc, &resolved);
                try out.append(resolved);
                value_transferred = true;
            }
            break :blk .{ .array = out };
        },
        else => blk: {
            if (remaining_nodes.* == 0) return error.AuthRowFilterNoMatch;
            remaining_nodes.* -= 1;
            break :blk switch (expectation) {
                .array, .term_body, .terms_body => error.InvalidQueryRequest,
                .filter, .scalar, .static => try json_helpers.cloneJsonValue(alloc, value),
            };
        },
    };
}

fn authFilterValueMatchesExpectation(
    value: std.json.Value,
    expectation: AuthFilterTemplateExpectation,
) bool {
    return switch (expectation) {
        .scalar => switch (value) {
            .string, .integer, .float, .number_string, .bool, .null => true,
            else => false,
        },
        .array => switch (value) {
            .array => |array| blk: {
                if (array.items.len == 0 or
                    array.items.len > auth_filter_max_tree_nodes)
                {
                    break :blk false;
                }
                for (array.items) |item| {
                    if (!authFilterValueMatchesExpectation(item, .scalar)) {
                        break :blk false;
                    }
                }
                break :blk true;
            },
            else => false,
        },
        else => false,
    };
}

const BoundedAuthContextJsonValue = struct {
    value: std.json.Value,
    node_count: usize,
};

fn authContextJsonValueBounded(
    alloc: std.mem.Allocator,
    context: AuthRowFilterResolveContext,
    path: []const u8,
    max_nodes: usize,
) !BoundedAuthContextJsonValue {
    if (max_nodes == 0) return error.InvalidQueryRequest;
    if (isSupportedAuthPath(path)) {
        if (std.mem.eql(u8, path, "username")) {
            return .{
                .value = .{ .string = try alloc.dupe(u8, context.identity.username) },
                .node_count = 1,
            };
        }
        if (std.mem.eql(u8, path, "roles")) {
            if (context.identity.roles.len == 0 or context.identity.roles.len >= max_nodes) {
                return error.InvalidQueryRequest;
            }
            return .{
                .value = try rolesAuthJsonValue(alloc, context.identity.roles),
                .node_count = 1 + context.identity.roles.len,
            };
        }
        if (std.mem.startsWith(u8, path, "settings.")) {
            return .{
                .value = try roleSettingAuthJsonValue(alloc, context.identity.role_settings, path["settings.".len..]),
                .node_count = 1,
            };
        }
        return try metadataAuthJsonValueBounded(
            alloc,
            context.metadata orelse return error.InvalidQueryRequest,
            path["metadata.".len..],
            max_nodes,
        );
    }
    return error.InvalidQueryRequest;
}

fn isSupportedAuthPath(path: []const u8) bool {
    if (std.mem.eql(u8, path, "username")) return true;
    if (std.mem.eql(u8, path, "roles")) return true;
    if (std.mem.startsWith(u8, path, "settings.")) {
        usermgr.validateRoleSettingName(path["settings.".len..]) catch return false;
        return true;
    }
    if (!std.mem.startsWith(u8, path, "metadata.")) return false;
    var segments = std.mem.splitScalar(u8, path["metadata.".len..], '.');
    var seen = false;
    while (segments.next()) |segment| {
        if (segment.len == 0) return false;
        seen = true;
    }
    return seen;
}

fn rolesAuthJsonValue(
    alloc: std.mem.Allocator,
    roles: []const []const u8,
) !std.json.Value {
    var out = std.json.Array.init(alloc);
    errdefer {
        for (out.items) |*item| json_helpers.deinitJsonValue(alloc, item);
        out.deinit();
    }
    for (roles) |role| {
        try out.append(.{ .string = try alloc.dupe(u8, role) });
    }
    return .{ .array = out };
}

fn roleSettingAuthJsonValue(
    alloc: std.mem.Allocator,
    settings: []const usermgr.RoleSetting,
    name: []const u8,
) !std.json.Value {
    usermgr.validateRoleSettingName(name) catch return error.InvalidQueryRequest;
    for (settings) |setting| {
        if (std.mem.eql(u8, setting.name, name)) {
            return .{ .string = try alloc.dupe(u8, setting.value) };
        }
    }
    return error.InvalidQueryRequest;
}

fn metadataAuthJsonValueBounded(
    alloc: std.mem.Allocator,
    metadata: std.json.Value,
    path: []const u8,
    max_nodes: usize,
) !BoundedAuthContextJsonValue {
    var current = metadata;
    var segments = std.mem.splitScalar(u8, path, '.');
    while (segments.next()) |segment| {
        if (segment.len == 0 or current != .object) return error.InvalidQueryRequest;
        current = current.object.get(segment) orelse return error.InvalidQueryRequest;
    }
    var remaining_nodes = max_nodes;
    try consumeAuthContextJsonBudget(current, 0, &remaining_nodes);
    return .{
        .value = try json_helpers.cloneJsonValue(alloc, current),
        .node_count = max_nodes - remaining_nodes,
    };
}

fn consumeAuthContextJsonBudget(
    value: std.json.Value,
    depth: u8,
    remaining_nodes: *usize,
) !void {
    if (depth >= auth_filter_max_tree_depth or remaining_nodes.* == 0) {
        return error.InvalidQueryRequest;
    }
    remaining_nodes.* -= 1;
    switch (value) {
        .object => |object| {
            var it = object.iterator();
            while (it.next()) |entry| {
                try consumeAuthContextJsonBudget(
                    entry.value_ptr.*,
                    depth + 1,
                    remaining_nodes,
                );
            }
        },
        .array => |array| {
            for (array.items) |item| {
                try consumeAuthContextJsonBudget(
                    item,
                    depth + 1,
                    remaining_nodes,
                );
            }
        },
        else => {},
    }
}

test "auth row filter resolver expands username references" {
    const alloc = std.testing.allocator;
    var identity = AuthenticatedIdentity{
        .username = try alloc.dupe(u8, "alice"),
    };
    defer identity.deinit(alloc);

    const resolved = try resolveAuthRowFilterJson(
        alloc,
        identity,
        "{\"term\":{\"owner\":{\"$auth\":\"username\"}}}",
    );
    defer alloc.free(resolved);

    try std.testing.expectEqualStrings("{\"term\":{\"owner\":\"alice\"}}", resolved);
}

test "auth row filter resolver does not parse unused malformed metadata" {
    const alloc = std.testing.allocator;
    var identity = AuthenticatedIdentity{
        .username = try alloc.dupe(u8, "alice"),
        .metadata_json = try alloc.dupe(u8, "{"),
    };
    defer identity.deinit(alloc);

    const resolved = try resolveAuthRowFilterJson(
        alloc,
        identity,
        "{\"term\":{\"owner\":{\"$auth\":\"username\"}}}",
    );
    defer alloc.free(resolved);

    try std.testing.expectEqualStrings("{\"term\":{\"owner\":\"alice\"}}", resolved);
}

test "auth row filter resolver expands metadata references" {
    const alloc = std.testing.allocator;
    const role_settings = try alloc.alloc(usermgr.RoleSetting, 1);
    role_settings[0] = try usermgr.RoleSetting.initOwned(alloc, "app.tenant_id", "acme");
    var identity = AuthenticatedIdentity{
        .username = try alloc.dupe(u8, "alice"),
        .metadata_json = try alloc.dupe(u8, "{\"tenant_id\":\"acme\",\"limits\":{\"tier\":\"gold\"}}"),
        .role_settings = role_settings,
    };
    defer identity.deinit(alloc);

    const resolved = try resolveAuthRowFilterJson(
        alloc,
        identity,
        "{\"conjuncts\":[{\"term\":{\"tenant_id\":{\"$auth\":\"metadata.tenant_id\"}}},{\"term\":{\"setting_tenant\":{\"$auth\":\"settings.app.tenant_id\"}}},{\"term\":{\"tier\":{\"$auth\":\"metadata.limits.tier\"}}}]}",
    );
    defer alloc.free(resolved);

    try std.testing.expect(std.mem.indexOf(u8, resolved, "\"tenant_id\":\"acme\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, resolved, "\"setting_tenant\":\"acme\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, resolved, "\"tier\":\"gold\"") != null);
}

test "auth row filter resolver expands native role setting references" {
    const alloc = std.testing.allocator;
    const role_settings = try alloc.alloc(usermgr.RoleSetting, 1);
    role_settings[0] = try usermgr.RoleSetting.initOwned(alloc, "app.tenant_id", "acme");
    var identity = AuthenticatedIdentity{
        .username = try alloc.dupe(u8, "alice"),
        .role_settings = role_settings,
    };
    defer identity.deinit(alloc);

    const resolved = try resolveAuthRowFilterJson(
        alloc,
        identity,
        "{\"term\":{\"tenant_id\":{\"$auth\":\"settings.app.tenant_id\"}}}",
    );
    defer alloc.free(resolved);

    try std.testing.expectEqualStrings("{\"term\":{\"tenant_id\":\"acme\"}}", resolved);
    try std.testing.expectError(
        error.InvalidQueryRequest,
        resolveAuthRowFilterJson(alloc, identity, "{\"term\":{\"tenant_id\":{\"$auth\":\"settings.app.missing\"}}}"),
    );
}

