        \\{"regexp":{"field":"tenant","pattern":"acme-[0-9]+"}}
        ,
        \\{"numeric_range":{"path":"score","min":1,"max":10}}
        ,
    }) |filter| {
        try validateAuthRowFilterJson(alloc, filter);
    }

