    try std.testing.expectError(
        error.InvalidQueryRequest,
        validateAuthRowFilterJson(
            alloc,
            \\{"terms":{"owners":{"$auth":"username"}}}
            ,
        ),
    );
    try std.testing.expectError(
        error.InvalidQueryRequest,
        validateAuthRowFilterJson(
            alloc,
            \\{"term":{"path":{"$auth":"username"},"term":"acme"}}
