const TestQueryHitInput = struct {
    _id: []const u8,
    _score: f32 = 0,
    _source: ?std.json.Value = null,
};

const OwnedJsonValueSlice = struct {
    values: []std.json.Value,

    fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
        for (self.values) |*value| ApiHttpServer.deinitJsonValue(alloc, value);
        if (self.values.len > 0) alloc.free(self.values);
        self.* = undefined;
    }
};

fn parseTestQueryHitsAlloc(alloc: std.mem.Allocator, json: []const u8) !OwnedJsonValueSlice {
    var parsed = try std.json.parseFromSlice([]const TestQueryHitInput, alloc, json, .{});
    defer parsed.deinit();

    const values = try alloc.alloc(std.json.Value, parsed.value.len);
    var initialized: usize = 0;
    errdefer {
        for (values[0..initialized]) |*value| ApiHttpServer.deinitJsonValue(alloc, value);
        if (values.len > 0) alloc.free(values);
    }

    for (parsed.value, 0..) |item, idx| {
        var obj = std.json.ObjectMap.empty;
        errdefer {
            var owned = std.json.Value{ .object = obj };
            ApiHttpServer.deinitJsonValue(alloc, &owned);
        }
        try obj.put(alloc, try alloc.dupe(u8, "_id"), .{ .string = try alloc.dupe(u8, item._id) });
        try obj.put(alloc, try alloc.dupe(u8, "_score"), .{ .float = item._score });
        if (item._source) |source| {
            try obj.put(alloc, try alloc.dupe(u8, "_source"), try ApiHttpServer.cloneJsonValue(alloc, source));
        }
        values[idx] = .{ .object = obj };
        initialized = idx + 1;
    }

    return .{ .values = values };
}

fn parseTestStringValuesAlloc(alloc: std.mem.Allocator, json: []const u8) !OwnedJsonValueSlice {
    var parsed = try std.json.parseFromSlice([]const []const u8, alloc, json, .{});
    defer parsed.deinit();

    const values = try alloc.alloc(std.json.Value, parsed.value.len);
    errdefer if (values.len > 0) alloc.free(values);
    for (parsed.value, 0..) |item, idx| {
        values[idx] = .{ .string = try alloc.dupe(u8, item) };
    }
    return .{ .values = values };
}

fn testQueryHitSourcePathValue(hit: anytype, path: []const u8) ?std.json.Value {
    const source = hit._source orelse return null;
    return json_helpers.extractJsonPathValue(source, path);
}

fn testOwnedHitSourcePathValue(hit: std.json.Value, path: []const u8) ?std.json.Value {
    const source = hit.object.get("_source") orelse return null;
    return json_helpers.extractJsonPathValue(source, path);
}

pub fn freeApiKeys(alloc: std.mem.Allocator, api_keys: []const usermgr.ApiKey) void {
    for (api_keys) |api_key| {
        var owned = api_key;
        owned.deinit(alloc);
    }
    alloc.free(@constCast(api_keys));
}

pub const ListedUserEntry = struct { username: []const u8 };

pub fn makeListedUsers(alloc: std.mem.Allocator, users: []const []const u8) ![]ListedUserEntry {
    const listed = try alloc.alloc(ListedUserEntry, users.len);
    for (users, 0..) |username, i| {
        listed[i] = .{ .username = username };
    }
    return listed;
}

pub fn userToOpenApi(alloc: std.mem.Allocator, user: usermgr.User) !usermgr_openapi.User {
    return .{
        .username = user.username,
        .password_hash = user.password_hash,
        .metadata = if (user.metadata_json.len > 0) try parseOwnedJsonObjectMapAlloc(alloc, user.metadata_json) else null,
    };
}

pub fn makeCurrentUserResponse(
    alloc: std.mem.Allocator,
    username: []const u8,
    permissions: []const usermgr.Permission,
    metadata_json: []const u8,
) !struct {
    username: []const u8,
    permissions: []const usermgr_openapi.Permission,
    metadata: ?std.json.ArrayHashMap(std.json.Value) = null,
} {
    const generated_permissions = try clonePermissionsToOpenApi(alloc, permissions);
    return .{
        .username = username,
        .permissions = generated_permissions,
        .metadata = if (metadata_json.len > 0) try parseOwnedJsonObjectMapAlloc(alloc, metadata_json) else null,
    };
}

fn eventStreamResponse(alloc: std.mem.Allocator, status: u16, body: []const u8) !http_common.HttpResponse {
    return .{
        .status = status,
        .content_type = try alloc.dupe(u8, "text/event-stream"),
        .body = try alloc.dupe(u8, body),
    };
}

fn textResponse(alloc: std.mem.Allocator, status: u16, body: []const u8) !http_common.HttpResponse {
    return .{
        .status = status,
        .content_type = try alloc.dupe(u8, "text/plain"),
        .body = try alloc.dupe(u8, body),
    };
}

fn ownedHeader(alloc: std.mem.Allocator, name: []const u8, value: []const u8) !http_common.Header {
    const owned_name = try alloc.dupe(u8, name);
    errdefer alloc.free(owned_name);
    return .{ .name = owned_name, .value = try alloc.dupe(u8, value) };
}

fn retryableTextResponse(alloc: std.mem.Allocator, status: u16, body: []const u8) !http_common.HttpResponse {
    const headers = try alloc.alloc(http_common.Header, 1);
    errdefer alloc.free(headers);
    headers[0] = .{
        .name = try alloc.dupe(u8, "Retry-After"),
        .value = alloc.dupe(u8, "1") catch |err| {
            alloc.free(headers[0].name);
            return err;
        },
    };
    errdefer headers[0].deinit(alloc);

    const content_type = try alloc.dupe(u8, "text/plain");
    errdefer alloc.free(content_type);
    const owned_body = try alloc.dupe(u8, body);
    return .{
        .status = status,
        .content_type = content_type,
        .headers = headers,
        .body = owned_body,
    };
}

fn queryEmbeddingOperationalResponse(alloc: std.mem.Allocator, err: anyerror) !?http_common.HttpResponse {
    const normalized = normalizeQueryEmbeddingOperationalError(err) orelse return null;
    return switch (normalized) {
        error.QueryEmbeddingInputTooLarge => try textResponse(alloc, 413, "query embedding input too large"),
        error.QueryEmbeddingOverloaded => try retryableTextResponse(alloc, 429, "query embedding overloaded"),
        error.EmbedRateLimited => try retryableTextResponse(alloc, 429, "query embedding rate limited"),
        error.EmbedTransientFailure => try retryableTextResponse(alloc, 503, "query embedding temporarily unavailable"),
        error.EmbedUpstreamFailure => try textResponse(alloc, 502, "query embedding provider failed"),
        error.Timeout => try textResponse(alloc, 504, "query embedding timed out"),
        else => null,
    };
}

pub fn metadataNotLeaderResponse(alloc: std.mem.Allocator) !http_common.HttpResponse {
    const headers = try alloc.alloc(http_common.Header, 2);
    var initialized_headers: usize = 0;
    errdefer {
        for (headers[0..initialized_headers]) |*header| header.deinit(alloc);
        alloc.free(headers);
    }

    var retry_after_name: ?[]u8 = try alloc.dupe(u8, "Retry-After");
    errdefer if (retry_after_name) |value| alloc.free(value);
    var retry_after_value: ?[]u8 = try alloc.dupe(u8, "1");
    errdefer if (retry_after_value) |value| alloc.free(value);
    headers[0] = .{ .name = retry_after_name.?, .value = retry_after_value.? };
    retry_after_name = null;
    retry_after_value = null;
    initialized_headers += 1;

    var not_leader_name: ?[]u8 = try alloc.dupe(u8, http_common.metadata_not_leader_header);
    errdefer if (not_leader_name) |value| alloc.free(value);
    var not_leader_value: ?[]u8 = try alloc.dupe(u8, http_common.metadata_not_leader_value);
    errdefer if (not_leader_value) |value| alloc.free(value);
    headers[1] = .{ .name = not_leader_name.?, .value = not_leader_value.? };
    not_leader_name = null;
    not_leader_value = null;
    initialized_headers += 1;

    const content_type = try alloc.dupe(u8, "application/json");
    errdefer alloc.free(content_type);
    const body = try alloc.dupe(u8, "{\"error\":\"metadata leader unavailable\"}");
    errdefer alloc.free(body);
    return .{
        .status = 503,
        .content_type = content_type,
        .headers = headers,
        .body = body,
    };
}

fn restoreIdempotencyNamespaceAlloc(
    alloc: std.mem.Allocator,
    principal: ?[]const u8,
    scope: restore_jobs.Scope,
    table_name: ?[]const u8,
) ![]u8 {
    const canonical = try std.json.Stringify.valueAlloc(alloc, .{
        .principal = principal orelse "anonymous",
        .scope = scope,
        .table_name = table_name,
    }, .{ .emit_null_optional_fields = false });
    defer alloc.free(canonical);
    var digest: [std.crypto.hash.sha2.Sha256.digest_length]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(canonical, &digest, .{});
    const hex = std.fmt.bytesToHex(digest, .lower);
    return try alloc.dupe(u8, &hex);
}

fn metadataAccessFailure(err: anyerror) error{ NotLeader, InternalFailure } {
    if (metadata_authority.isRetryableError(err)) return error.NotLeader;
    return error.InternalFailure;
}

pub fn shouldRetryMetadataMutation(err: anyerror, elapsed_ns: u64, timeout_ns: u64) bool {
    return elapsed_ns < timeout_ns and
        (err == error.UnexpectedHttpStatus or metadata_authority.isRetryableError(err));
}

test "public metadata mutation retries transient authority loss only within its deadline" {
    const timeout_ns = default_metadata_mutation_retry_timeout_ns;
    try std.testing.expect(shouldRetryMetadataMutation(error.NotLeader, timeout_ns - 1, timeout_ns));
    try std.testing.expect(shouldRetryMetadataMutation(error.ProposalDropped, 0, timeout_ns));
    try std.testing.expect(shouldRetryMetadataMutation(error.UnexpectedHttpStatus, 0, timeout_ns));
    try std.testing.expect(!shouldRetryMetadataMutation(error.NotLeader, timeout_ns, timeout_ns));
    try std.testing.expect(!shouldRetryMetadataMutation(error.InvalidArguments, 0, timeout_ns));

    const bounded_attempts = MetadataMutationRetryPolicy{ .max_attempts = 3 };
    try std.testing.expect(bounded_attempts.shouldRetry(error.NotLeader, 0, 2));
    try std.testing.expect(!bounded_attempts.shouldRetry(error.NotLeader, 0, 3));
}

pub fn buildLocalSchemaUpdateStatus(alloc: std.mem.Allocator, table_name: []const u8, schema_json: []const u8) !struct {
    name: []const u8,
    schema: schema_openapi.TableSchema,
} {
    return .{
        .name = table_name,
        .schema = try std.json.parseFromSliceLeaky(schema_openapi.TableSchema, alloc, schema_json, .{
            .allocate = .alloc_always,
        }),
    };
}

pub fn stripApiPrefix(path: []const u8) []const u8 {
    const prefix = routes.Routes.db_v1_prefix;
    if (std.mem.startsWith(u8, path, prefix)) {
        const rest = path[prefix.len..];
        // "/db/v1" alone or "/db/v1/" → "/"
        if (rest.len == 0) return "/";
        return rest;
    }
    return path;
}

const UriParts = struct { path: []const u8, query: []const u8 };

fn splitTarget(target: []const u8) UriParts {
    const query_index = std.mem.indexOfScalar(u8, target, '?') orelse return .{
        .path = stripApiPrefix(target),
        .query = "",
    };
    return .{
        .path = stripApiPrefix(target[0..query_index]),
        .query = target[query_index + 1 ..],
    };
}

fn rawPathOnly(target: []const u8) []const u8 {
    const query_index = std.mem.indexOfScalar(u8, target, '?') orelse return target;
    return target[0..query_index];
}

fn decodeRequestPathParamAlloc(alloc: std.mem.Allocator, encoded: []const u8) ![]u8 {
    return http_route_helpers.decodePercentEncodedPathComponentAlloc(alloc, encoded) catch |err| switch (err) {
        error.InvalidArgument => return error.InvalidPathParameter,
        else => return err,
    };
}

fn parseSimpleQueryParam(query: []const u8, key: []const u8) ?[]const u8 {
    if (query.len == 0) return null;
    var it = std.mem.splitScalar(u8, query, '&');
    while (it.next()) |part| {
        if (!std.mem.startsWith(u8, part, key)) continue;
        if (part.len <= key.len or part[key.len] != '=') continue;
        return part[key.len + 1 ..];
    }
    return null;
}

fn parseSimpleQueryParamDecodedAlloc(alloc: std.mem.Allocator, query: []const u8, key: []const u8) !?[]u8 {
    const raw = parseSimpleQueryParam(query, key) orelse return null;
    return try http_route_helpers.decodePercentEncodedPathComponentAlloc(alloc, raw);
}

pub fn parseLookupReadConsistency(query: []const u8) !raft_mod.ReadConsistency {
    const value = parseSimpleQueryParam(query, "consistency") orelse
        parseSimpleQueryParam(query, "read_consistency") orelse
        return .read_index;
    if (std.mem.eql(u8, value, "stale")) return .stale;
    if (std.mem.eql(u8, value, "read_index") or std.mem.eql(u8, value, "read-index")) return .read_index;
    if (std.mem.eql(u8, value, "leader_lease") or std.mem.eql(u8, value, "leader-lease")) return .leader_lease;
    return error.InvalidReadConsistency;
}

pub fn runtimeSchemaDebugRequested(query: []const u8) bool {
    const value = parseSimpleQueryParam(query, "debug") orelse return false;
    return std.mem.eql(u8, value, "runtime_schema");
}

fn parseUnsignedQueryParam(query: []const u8, key: []const u8) !?u64 {
    const value = parseSimpleQueryParam(query, key) orelse return null;
    return try std.fmt.parseUnsigned(u64, value, 10);
}

test "artifact repair query params decode percent encoded values" {
    const alloc = std.testing.allocator;
    const index = (try parseSimpleQueryParamDecodedAlloc(alloc, "index=tenant%2Fembedding%20v1&cursor=7001%3Aabc%2Fdef", "index")).?;
    defer alloc.free(index);
    try std.testing.expectEqualStrings("tenant/embedding v1", index);

    const cursor = (try parseSimpleQueryParamDecodedAlloc(alloc, "index=tenant%2Fembedding%20v1&cursor=7001%3Aabc%2Fdef", "cursor")).?;
    defer alloc.free(cursor);
    try std.testing.expectEqualStrings("7001:abc/def", cursor);
}

