test "api http server authenticates trusted principal" {
    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 77, .metrics = .{} };
        }
    };

    const secret = "trusted-principal-test-secret";
    const now: i64 = @intCast(@divFloor(nowNs(), std.time.ns_per_s));
    const payload = try std.fmt.allocPrint(
        std.testing.allocator,
        \\{{"iss":"trusted-upstream","sub":"user:alice","tenant":"inst-1","tables":["docs"],"operations":["read"],"row_filter":{{"docs":{{"term":{{"tenant_id":"t1"}}}}}},"iat":{d},"exp":{d}}}
    ,
        .{ now, now + 60 },
    );
    defer std.testing.allocator.free(payload);
    const token = try encodeTrustedPrincipalToken(std.testing.allocator, secret, payload);
    defer std.testing.allocator.free(token);

    var source = FakeSource{};
    var server = ApiHttpServer.init(
        std.testing.allocator,
        .{ .trusted_principal_secret = secret, .trusted_principal_issuer = "trusted-upstream" },
        source.iface(),
        null,
        null,
    );
    defer server.deinit();
    try std.testing.expect(server.requiresAuthentication(routes.Routes.tables));

    var identity = try server.authenticateRequest(.{ .trusted_principal = token });
    defer identity.deinit(std.testing.allocator);
    try std.testing.expectEqualStrings("user:alice", identity.username);
    try std.testing.expectEqual(@as(usize, 1), identity.permissions.len);
    try std.testing.expectEqual(usermgr.ResourceType.table, identity.permissions[0].resource_type);
    try std.testing.expectEqualStrings("docs", identity.permissions[0].resource);
    try std.testing.expectEqual(usermgr.PermissionType.read, identity.permissions[0].type);
    try std.testing.expectEqual(@as(usize, 1), identity.row_filter.len);
    try std.testing.expectEqualStrings("docs", identity.row_filter[0].table);
    try std.testing.expect(std.mem.indexOf(u8, identity.row_filter[0].filter, "\"tenant_id\":\"t1\"") != null);
}

test "api http server hydrates trusted principal role settings from antfly user manager" {
    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 77, .metrics = .{} };
        }
    };

    var auth = try initTestAuthManager(std.testing.allocator);
    try bindTestAuthManager(std.testing.allocator, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();

    var user = try auth.manager.createUser("alice", "secret", &.{});
    defer user.deinit(std.testing.allocator);
    try auth.manager.createRoleSubject("role:app_writer");
    try auth.manager.setRoleSetting("role:app_writer", "app.tenant_id", "acme");
    try auth.manager.addRoleToUser("alice", "role:app_writer");

    const secret = "trusted-principal-role-setting-secret";
    const now: i64 = @intCast(@divFloor(nowNs(), std.time.ns_per_s));
    const payload = try std.fmt.allocPrint(
        std.testing.allocator,
        \\{{"iss":"trusted-upstream","sub":"alice","tables":["docs"],"operations":["read"],"row_filter":{{"docs":{{"term":{{"tenant_id":{{"$auth":"settings.app.tenant_id"}}}}}}}},"iat":{d},"exp":{d}}}
    ,
        .{ now, now + 60 },
    );
    defer std.testing.allocator.free(payload);
    const token = try encodeTrustedPrincipalToken(std.testing.allocator, secret, payload);
    defer std.testing.allocator.free(token);

    var source = FakeSource{};
    var server = ApiHttpServer.init(
        std.testing.allocator,
        .{
            .trusted_principal_secret = secret,
            .trusted_principal_issuer = "trusted-upstream",
            .user_manager = &auth.manager,
        },
        source.iface(),
        null,
        null,
    );
    defer server.deinit();

    var identity = try server.authenticateRequest(.{ .trusted_principal = token });
    defer identity.deinit(std.testing.allocator);
    try std.testing.expectEqualStrings("alice", identity.username);
    try std.testing.expectEqual(@as(usize, 1), identity.role_settings.len);
    try std.testing.expectEqualStrings("app.tenant_id", identity.role_settings[0].name);
    try std.testing.expectEqualStrings("acme", identity.role_settings[0].value);

    const resolved = try resolveEffectiveRowFilterJson(std.testing.allocator, @as(?AuthenticatedIdentity, identity), "docs");
    defer std.testing.allocator.free(resolved.?);
    try std.testing.expectEqualStrings("{\"term\":{\"tenant_id\":\"acme\"}}", resolved.?);
}

test "api http server resolves row filter role settings for target database" {
    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 77, .metrics = .{} };
        }
    };

    const alloc = std.testing.allocator;
    var auth = try initTestAuthManager(alloc);
    try bindTestAuthManager(alloc, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();

    var user = try auth.manager.createUser("alice", "secret", &.{});
    defer user.deinit(alloc);
    try auth.manager.createRoleSubject("role:app_writer");
    try auth.manager.setRoleSetting("role:app_writer", "app.tenant_id", "global-acme");
    try auth.manager.setRoleDatabaseSetting("role:app_writer", "tenant_ops", "app.tenant_id", "tenant-scoped-acme");
    try auth.manager.addRoleToUser("alice", "role:app_writer");

    var source = FakeSource{};
    var server = ApiHttpServer.init(
        alloc,
        .{ .user_manager = &auth.manager },
        source.iface(),
        null,
        null,
    );
    defer server.deinit();

    const role_settings = try auth.manager.getEffectiveRoleSettings("alice");
    const row_filters = try alloc.alloc(usermgr.RowFilterEntry, 1);
    row_filters[0] = try usermgr.RowFilterEntry.initOwned(alloc, "tenant_ops.public.docs", "{\"term\":{\"tenant_id\":{\"$auth\":\"settings.app.tenant_id\"}}}");
    var identity = AuthenticatedIdentity{
        .username = try alloc.dupe(u8, "alice"),
        .row_filter = row_filters,
        .role_settings = role_settings,
    };
    defer identity.deinit(alloc);

    const scoped = (try server.resolveEffectiveRowFilterJsonForDatabase(alloc, @as(?AuthenticatedIdentity, identity), "tenant_ops", "tenant_ops.public.docs")) orelse return error.TestExpectedEqual;
    defer alloc.free(scoped);
    try std.testing.expectEqualStrings("{\"term\":{\"tenant_id\":\"tenant-scoped-acme\"}}", scoped);

    const global = (try server.resolveEffectiveRowFilterJsonForDatabase(alloc, @as(?AuthenticatedIdentity, identity), tables_api.default_database_name, "tenant_ops.public.docs")) orelse return error.TestExpectedEqual;
    defer alloc.free(global);
    try std.testing.expectEqualStrings("{\"term\":{\"tenant_id\":\"global-acme\"}}", global);

    try auth.manager.createRoleSubject("role:app_reader");
    try auth.manager.setRoleDatabaseSetting("role:app_reader", "tenant_ops", "app.tenant_id", "conflicting-acme");
    try auth.manager.addRoleToUser("alice", "role:app_reader");
    try std.testing.expectError(
        error.InvalidQueryRequest,
        server.resolveEffectiveRowFilterJsonForDatabase(alloc, @as(?AuthenticatedIdentity, identity), "tenant_ops", "tenant_ops.public.docs"),
    );
}

