test "api http server enforces SQL row security WITH CHECK on row writes" {
    const alloc = std.testing.allocator;
    const usage_schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"tenant_id":{"type":"keyword"},"status":{"type":"keyword"}},"required":["id","tenant_id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const table_target: catalog_resources.TableTarget = .{
        .database_name = catalog_resources.default_database_name,
        .namespace_name = catalog_resources.default_namespace_name,
        .table_name = "usage_records",
    };
    const table_resource = "default.public.usage_records";
    const FakeSource = struct {
        tables: [1]metadata_table_manager.TableRecord = .{.{
            .table_id = 1,
            .name = "usage_records",
            .database_name = catalog_resources.default_database_name,
            .namespace_name = catalog_resources.default_namespace_name,
            .schema_json = usage_schema_json,
        }},

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = try status(ptr),
                .tables = self.tables[0..],
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };
    const FakeReads = struct {
        lookup_calls: usize = 0,

        fn source(self: *@This()) table_reads.TableReadSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .lookup = lookup,
                    .lookup_catalog = lookupCatalog,
                    .scan = scan,
                    .query = query,
                },
            };
        }

        fn lookup(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8, _: db_mod.types.LookupOptions, _: raft_mod.ReadConsistency) anyerror!?table_reads.LookupResponse {
            return error.UnsupportedOperation;
        }

        fn lookupCatalog(
            ptr: *anyopaque,
            allocator: std.mem.Allocator,
            target: catalog_resources.TableTarget,
            key: []const u8,
            _: db_mod.types.LookupOptions,
            consistency: raft_mod.ReadConsistency,
        ) anyerror!?table_reads.LookupResponse {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqual(raft_mod.ReadConsistency.read_index, consistency);
            try std.testing.expectEqualStrings(catalog_resources.default_database_name, target.database_name);
            try std.testing.expectEqualStrings(catalog_resources.default_namespace_name, target.namespace_name);
            try std.testing.expectEqualStrings("usage_records", target.table_name);
            self.lookup_calls += 1;
            if (std.mem.eql(u8, key, "missing")) return null;
            if (std.mem.eql(u8, key, "tenant-b-existing")) {
                return .{
                    .json = try allocator.dupe(u8, "{\"id\":\"tenant-b-existing\",\"tenant_id\":\"tenant-b\",\"status\":\"active\"}"),
                    .version = 7,
                };
            }
            return .{
                .json = try allocator.dupe(u8, "{\"id\":\"existing\",\"tenant_id\":\"tenant-a\",\"status\":\"archived\"}"),
                .version = 3,
            };
        }

        fn scan(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8, _: []const u8, _: db_mod.types.ScanOptions, _: raft_mod.ReadConsistency) anyerror!?table_reads.ScanResponse {
            return error.UnsupportedOperation;
        }

        fn query(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: db_mod.types.SearchRequest, _: raft_mod.ReadConsistency) anyerror!?query_api.QueryResponse {
            return error.UnsupportedOperation;
        }
    };
    const BatchHelper = struct {
        fn oneWrite(allocator: std.mem.Allocator, key: []const u8, json: []const u8) !relational_rows_api.OwnedRowsBatchRequest {
            const writes = try allocator.alloc(db_mod.types.BatchWrite, 1);
            errdefer allocator.free(writes);
            const owned_key = try allocator.dupe(u8, key);
            errdefer allocator.free(owned_key);
            const owned_value = try allocator.dupe(u8, json);
            errdefer allocator.free(owned_value);
            writes[0] = .{
                .key = owned_key,
                .value = owned_value,
            };
            return .{
                .writes = writes,
                .req = .{ .writes = writes },
                .inserted = 1,
            };
        }
    };

    var auth = try initTestAuthManager(alloc);
    try bindTestAuthManager(alloc, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();

    var user = try auth.manager.createUser("alice", "secret", &.{});
    defer user.deinit(alloc);

    var source = FakeSource{};
    var reads = FakeReads{};
    var server = ApiHttpServer.init(alloc, .{ .user_manager = &auth.manager }, source.iface(), reads.source(), null);
    defer server.deinit();

    var enabled = try server.applyRelationalSqlDdl("ALTER TABLE usage_records ENABLE ROW LEVEL SECURITY;");
    defer enabled.deinit(alloc);
    var policy = try server.applyRelationalSqlDdl("CREATE POLICY usage_records_write_policy ON usage_records USING (tenant_id = 'tenant-a') WITH CHECK (status = 'active');");
    defer policy.deinit(alloc);

    const read_filters = try auth.manager.getRowFilters("alice");
    var identity = AuthenticatedIdentity{
        .username = try alloc.dupe(u8, "alice"),
        .row_filter = read_filters,
    };
    defer identity.deinit(alloc);

    var accepted_insert = try BatchHelper.oneWrite(
        alloc,
        "missing",
        "{\"id\":\"missing\",\"tenant_id\":\"tenant-b\",\"status\":\"active\"}",
    );
    defer accepted_insert.deinit(alloc);
    try server.requireRowsBatchSatisfiesEffectiveFilterForDatabase(
        catalog_resources.default_database_name,
        table_resource,
        table_target,
        accepted_insert,
        identity,
    );

    var rejected_check = try BatchHelper.oneWrite(
        alloc,
        "existing",
        "{\"id\":\"existing\",\"tenant_id\":\"tenant-a\",\"status\":\"archived\"}",
    );
    defer rejected_check.deinit(alloc);
    try std.testing.expectError(
        error.PermissionDenied,
        server.requireRowsBatchSatisfiesEffectiveFilterForDatabase(
            catalog_resources.default_database_name,
            table_resource,
            table_target,
            rejected_check,
            identity,
        ),
    );

    var rejected_visibility = try BatchHelper.oneWrite(
        alloc,
        "tenant-b-existing",
        "{\"id\":\"tenant-b-existing\",\"tenant_id\":\"tenant-b\",\"status\":\"active\"}",
    );
    defer rejected_visibility.deinit(alloc);
    try std.testing.expectError(
        error.PermissionDenied,
        server.requireRowsBatchSatisfiesEffectiveFilterForDatabase(
            catalog_resources.default_database_name,
            table_resource,
            table_target,
            rejected_visibility,
            identity,
        ),
    );

    try std.testing.expect(reads.lookup_calls >= 3);
}

test "api http server derives public SQL DDL command tags from parsed statements" {
    const alloc = std.testing.allocator;
    const cases = [_]struct {
        sql: []const u8,
        tag: []const u8,
    }{
        .{ .sql = "CREATE TABLE events (id text PRIMARY KEY);", .tag = "CREATE TABLE" },
        .{ .sql = "CREATE INDEX events_status_idx ON events (status);", .tag = "CREATE INDEX" },
        .{ .sql = "CREATE UNIQUE INDEX events_id_idx ON events (id);", .tag = "CREATE INDEX" },
        .{ .sql = "DROP INDEX IF EXISTS events_status_idx;", .tag = "DROP INDEX" },
        .{ .sql = "ALTER TABLE events ADD COLUMN status text;", .tag = "ALTER TABLE" },
        .{ .sql = "CREATE SCHEMA analytics;", .tag = "CREATE SCHEMA" },
    };
    for (cases) |case| {
        var parsed_sql = try sql_adapter.ParsedSql.initAlloc(alloc, case.sql);
        defer parsed_sql.deinit(alloc);
        try std.testing.expectEqualStrings(case.tag, ApiHttpServer.publicSqlDdlCommandTag(&parsed_sql));
    }
}

test "api http server applies SQL DDL with explicit catalog session" {
    const alloc = std.testing.allocator;
    const events_schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const FakeSource = struct {
        saw_session_create: bool = false,
        saw_schema_create: bool = false,
        saw_schema_rename: bool = false,
        saw_schema_drop: bool = false,
        tables: [1]metadata_table_manager.TableRecord = .{.{
            .table_id = 10,
            .name = "events",
            .database_name = "tenant_ops",
            .namespace_name = "analytics",
            .schema_json = events_schema_json,
        }},

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                    .apply_relational_sql_ddl_plan_with_session = applyRelationalSqlDdlPlanWithSession,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = try status(ptr),
                .tables = self.tables[0..],
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}

        fn applyRelationalSqlDdlPlanWithSession(
            ptr: *anyopaque,
            alloc_arg: std.mem.Allocator,
            plan: *sql_adapter.DurableSqlPlan,
            session: catalog_resources.SqlCatalogSession,
        ) !tables_api.AppliedRelationalSqlDdlRecord {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const table_plan = switch (plan.*) {
                .table_ddl => |table| table,
                .catalog_ddl => |catalog| switch (catalog) {
                    .schema_namespace_catalog => |schema_plan| {
                        var applied = try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(alloc_arg);
                        errdefer applied.deinit(alloc_arg);
                        switch (schema_plan) {
                            .create => |create| {
                                const target = try session.namespaceTargetFromSchemaName(create.schema_name);
                                try std.testing.expectEqualStrings("tenant_ops", target.database_name);
                                try std.testing.expect(std.mem.eql(u8, target.namespace_name, "analytics") or std.mem.eql(u8, target.namespace_name, "reporting"));
                                self.saw_schema_create = true;
                                applied.created_namespace = true;
                            },
                            .rename => |rename| {
                                const old_target = try session.namespaceTargetFromSchemaName(rename.schema_name);
                                const new_target = try session.namespaceTargetFromSchemaName(rename.new_schema_name);
                                try std.testing.expectEqualStrings("tenant_ops", old_target.database_name);
                                try std.testing.expectEqualStrings("reporting", old_target.namespace_name);
                                try std.testing.expectEqualStrings("tenant_ops", new_target.database_name);
                                try std.testing.expectEqualStrings("archive", new_target.namespace_name);
                                self.saw_schema_rename = true;
                                applied.renamed_namespace = true;
                            },
                            .drop => |drop| {
                                const target = try session.namespaceTargetFromSchemaName(drop.schema_name);
                                try std.testing.expectEqualStrings("tenant_ops", target.database_name);
                                try std.testing.expectEqualStrings("archive", target.namespace_name);
                                self.saw_schema_drop = true;
                                applied.dropped_namespace = true;
                            },
                        }
                        return applied;
                    },
                    else => return error.TestUnexpectedResult,
                },
                else => return error.TestUnexpectedResult,
            };
            var target = try tables_api.relationalSqlDdlTargetForTablePlanWithSessionAlloc(alloc_arg, table_plan, session);
            defer target.deinit(alloc_arg);
            try std.testing.expect(target.createsTable());
            try std.testing.expectEqualStrings("tenant_ops", target.database_name);
            if (std.mem.eql(u8, target.table_name, "events")) {
                try std.testing.expectEqualStrings("analytics", target.namespace_name);
                self.saw_session_create = true;
            } else if (std.mem.eql(u8, target.table_name, "local_events")) {
                try std.testing.expectEqualStrings("public", target.namespace_name);
            } else {
                return error.TestUnexpectedResult;
            }
            return .{ .table = try metadata_table_manager.cloneTable(alloc_arg, .{
                .table_id = 0,
                .name = target.table_name,
                .database_name = target.database_name,
                .namespace_name = target.namespace_name,
            }) };
        }
    };

    var auth = try initTestAuthManager(alloc);
    try bindTestAuthManager(alloc, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();

    var user = try auth.manager.createUser("alice", "secret", &.{});
    defer user.deinit(alloc);

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{
        .user_manager = &auth.manager,
    }, source.iface(), null, null);

    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, .{
        .current_database_name = "tenant_ops",
        .search_path = &.{"public"},
    });
    defer session.deinit(alloc);

    var created_schema = try server.applyRelationalSqlDdlWithSession("CREATE SCHEMA analytics;", &session);
    defer created_schema.deinit(alloc);
    try std.testing.expect(created_schema.created_namespace);
    try std.testing.expect(source.saw_schema_create);

    var created_reporting_schema = try server.applyRelationalSqlDdlWithSession("CREATE SCHEMA reporting;", &session);
    defer created_reporting_schema.deinit(alloc);
    try std.testing.expect(created_reporting_schema.created_namespace);

    var renamed_schema = try server.applyRelationalSqlDdlWithSession("ALTER SCHEMA reporting RENAME TO archive;", &session);
    defer renamed_schema.deinit(alloc);
    try std.testing.expect(renamed_schema.renamed_namespace);
    try std.testing.expect(source.saw_schema_rename);

    var dropped_schema = try server.applyRelationalSqlDdlWithSession("DROP SCHEMA archive;", &session);
    defer dropped_schema.deinit(alloc);
    try std.testing.expect(dropped_schema.dropped_namespace);
    try std.testing.expect(source.saw_schema_drop);

    var created_role = try server.applyRelationalSqlDdlWithSession("CREATE ROLE app_reader;", &session);
    defer created_role.deinit(alloc);
    try auth.manager.addRoleToUser("alice", "role:app_reader");

    var set_tenant = try server.applyRelationalSqlDdlWithSession("SET app.tenant_id = 'tenant-a';", &session);
    defer set_tenant.deinit(alloc);
    try std.testing.expect(set_tenant.noop);
    try std.testing.expectEqualStrings("tenant-a", session.session().settingValue("app.tenant_id") orelse return error.TestUnexpectedResult);

    var stored_tenant = try server.applyRelationalSqlDdlWithSession("ALTER ROLE app_reader SET app.tenant_id = current_setting('app.tenant_id');", &session);
    defer stored_tenant.deinit(alloc);
    const role_tenant = try auth.manager.getRoleSetting("role:app_reader", "app.tenant_id");
    defer alloc.free(role_tenant);
    try std.testing.expectEqualStrings("tenant-a", role_tenant);

    var set_path = try server.applyRelationalSqlDdlWithSession("SET search_path TO analytics, public;", &session);
    defer set_path.deinit(alloc);
    try std.testing.expect(set_path.noop);
    try std.testing.expectEqualStrings("analytics", session.search_path[0]);
    try std.testing.expectEqualStrings("public", session.search_path[1]);
    try std.testing.expect(!session.transaction_local_search_path);

    var created_table = try server.applyRelationalSqlDdlWithSession("CREATE TABLE events (id text PRIMARY KEY);", &session);
    defer created_table.deinit(alloc);
    try std.testing.expect(source.saw_session_create);

    var granted = try server.applyRelationalSqlDdlWithSession("GRANT SELECT ON TABLE events TO app_reader;", &session);
    defer granted.deinit(alloc);
    try std.testing.expect(try auth.manager.enforce("alice", .table, "tenant_ops.analytics.events", .read));
    try std.testing.expect(!(try auth.manager.enforce("alice", .table, "default.public.events", .read)));

    var set_local = try server.applyRelationalSqlDdlWithSession("SET LOCAL search_path TO public;", &session);
    defer set_local.deinit(alloc);
    try std.testing.expect(set_local.noop);
    try std.testing.expectEqualStrings("public", session.search_path[0]);
    try std.testing.expect(session.transaction_local_search_path);

    var local_table = try server.applyRelationalSqlDdlWithSession("CREATE TABLE local_events (id text PRIMARY KEY);", &session);
    defer local_table.deinit(alloc);
    try std.testing.expectEqualStrings("public", local_table.table.namespace_name);

    var set_local_tenant = try server.applyRelationalSqlDdlWithSession("SET LOCAL app.tenant_id = 'tenant-b';", &session);
    defer set_local_tenant.deinit(alloc);
    try std.testing.expect(set_local_tenant.noop);
    try std.testing.expect(session.transaction_local_settings);
    try std.testing.expectEqualStrings("tenant-b", session.session().settingValue("app.tenant_id") orelse return error.TestUnexpectedResult);

    var committed = try server.applyRelationalSqlDdlWithSession("COMMIT;", &session);
    defer committed.deinit(alloc);
    try std.testing.expect(committed.noop);
    try std.testing.expect(!session.transaction_local_search_path);
    try std.testing.expect(session.transaction_local_search_path_base == null);
    try std.testing.expect(!session.transaction_local_settings);
    try std.testing.expect(session.transaction_local_settings_base == null);
    try std.testing.expectEqualStrings("analytics", session.search_path[0]);
    try std.testing.expectEqualStrings("public", session.search_path[1]);
    try std.testing.expectEqualStrings("tenant-a", session.session().settingValue("app.tenant_id") orelse return error.TestUnexpectedResult);
}

test "api http server classifies SQL transaction session cleanup from parsed statements" {
    const alloc = std.testing.allocator;
    const cases = [_]struct {
        sql: []const u8,
        clears: bool,
    }{
        .{ .sql = "COMMIT;", .clears = true },
        .{ .sql = "COMMIT WORK;", .clears = true },
        .{ .sql = "ROLLBACK;", .clears = true },
        .{ .sql = "ROLLBACK WORK;", .clears = true },
        .{ .sql = "COMMIT PREPARED 'usage_batch';", .clears = false },
        .{ .sql = "ROLLBACK PREPARED 'usage_batch';", .clears = false },
        .{ .sql = "ROLLBACK TO SAVEPOINT before_retry;", .clears = false },
        .{ .sql = "ROLLBACK TO before_retry;", .clears = false },
        .{ .sql = "BEGIN;", .clears = false },
        .{ .sql = "START TRANSACTION;", .clears = false },
    };
    for (cases) |case| {
        var parsed_sql = try sql_adapter.ParsedSql.initAlloc(alloc, case.sql);
        defer parsed_sql.deinit(alloc);
        try std.testing.expectEqual(case.clears, ApiHttpServer.parsedSqlTransactionBoundaryClearsLocalSession(&parsed_sql));
    }
}

test "api http server enforces SQL statement timeout on session-backed DDL" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        calls: usize = 0,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .apply_relational_sql_ddl_plan_with_session = applyRelationalSqlDdlPlanWithSession,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn applyRelationalSqlDdlPlanWithSession(
            ptr: *anyopaque,
            alloc_arg: std.mem.Allocator,
            _: *sql_adapter.DurableSqlPlan,
            session: catalog_resources.SqlCatalogSession,
        ) !tables_api.AppliedRelationalSqlDdlRecord {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            const expected_timeout: []const u8 = if (self.calls == 0) "100ms" else "0";
            try std.testing.expectEqualStrings(expected_timeout, session.settingValue("statement_timeout") orelse return error.TestUnexpectedResult);
            self.calls += 1;
            sleepNs(120 * std.time.ns_per_ms);
            return try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(alloc_arg);
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session.deinit(alloc);

    var set_timeout = try server.applyRelationalSqlDdlWithSession("SET statement_timeout = '100ms';", &session);
    defer set_timeout.deinit(alloc);
    try std.testing.expect(set_timeout.noop);
    try std.testing.expectEqualStrings("100ms", session.session().settingValue("statement_timeout") orelse return error.TestUnexpectedResult);

    try std.testing.expectError(
        error.StatementTimeout,
        server.applyRelationalSqlDdlWithSession("ALTER TABLE events DROP COLUMN IF EXISTS stale;", &session),
    );
    try std.testing.expectEqual(@as(usize, 1), source.calls);

    var disable_timeout = try server.applyRelationalSqlDdlWithSession("SET statement_timeout = '0';", &session);
    defer disable_timeout.deinit(alloc);
    var applied = try server.applyRelationalSqlDdlWithSession("ALTER TABLE events DROP COLUMN IF EXISTS stale;", &session);
    defer applied.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), source.calls);
}

test "api http server routes prepared transaction SQL DDL to coordinator recovery" {
    const alloc = std.testing.allocator;
    const mem_backend = @import("../storage/mem_backend.zig");
    const FakeSource = struct {
        backend: *mem_backend.Backend,
        applied: usize = 0,
        last_pending: bool = false,
        last_committed: bool = false,
        last_aborted: bool = false,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .apply_prepared_transaction_plan = applyPreparedTransactionPlan,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn applyPreparedTransactionPlan(
            ptr: *anyopaque,
            alloc_arg: std.mem.Allocator,
            plan: sql_adapter.PreparedTransactionPlan,
            timestamp_ns: u64,
        ) !sql_adapter.PreparedTransactionCoordinatorResult {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            var runtime_store = try self.backend.runtimeStore(alloc_arg, .{ .name = "sql-prepared-txn-server" });
            defer runtime_store.deinit();
            const result = try sql_adapter.executePreparedTransactionRecoveryPlan(alloc_arg, &runtime_store, plan, timestamp_ns);
            self.applied += 1;
            self.last_pending = result.status == .pending;
            self.last_committed = result.status == .committed;
            self.last_aborted = result.status == .aborted;
            return result;
        }
    };

    var backend = mem_backend.Backend.init(alloc, .{});
    defer backend.close();
    var source = FakeSource{ .backend = &backend };
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session.deinit(alloc);

    var set_path = try server.applyRelationalSqlDdlWithSession("SET search_path TO analytics, public;", &session);
    defer set_path.deinit(alloc);
    var set_local_path = try server.applyRelationalSqlDdlWithSession("SET LOCAL search_path TO public;", &session);
    defer set_local_path.deinit(alloc);
    var set_local_tenant = try server.applyRelationalSqlDdlWithSession("SET LOCAL app.tenant_id = 'tenant-b';", &session);
    defer set_local_tenant.deinit(alloc);
    try std.testing.expect(session.transaction_local_search_path);
    try std.testing.expect(session.transaction_local_settings);
    try std.testing.expectEqualStrings("public", session.search_path[0]);
    try std.testing.expectEqualStrings("tenant-b", session.session().settingValue("app.tenant_id") orelse return error.TestUnexpectedResult);

    var prepared = try server.applyRelationalSqlDdlWithSession("PREPARE TRANSACTION 'usage_batch';", &session);
    defer prepared.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), source.applied);
    try std.testing.expect(source.last_pending);
    try std.testing.expect(!session.transaction_local_search_path);
    try std.testing.expect(session.transaction_local_search_path_base == null);
    try std.testing.expect(!session.transaction_local_settings);
    try std.testing.expect(session.transaction_local_settings_base == null);
    try std.testing.expectEqualStrings("analytics", session.search_path[0]);
    try std.testing.expectEqualStrings("public", session.search_path[1]);
    try std.testing.expect(session.session().settingValue("app.tenant_id") == null);

    var committed = try server.applyRelationalSqlDdlWithSession("COMMIT PREPARED 'usage_batch';", &session);
    defer committed.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), source.applied);
    try std.testing.expect(source.last_committed);

    var committed_retry = try server.applyRelationalSqlDdlWithSession("COMMIT PREPARED 'usage_batch';", &session);
    defer committed_retry.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 3), source.applied);
    try std.testing.expect(source.last_committed);

    try std.testing.expectError(
        error.PreparedTransactionDecisionConflict,
        server.applyRelationalSqlDdlWithSession("ROLLBACK PREPARED 'usage_batch';", &session),
    );

    var abort_prepared = try server.applyRelationalSqlDdlWithSession("PREPARE TRANSACTION 'usage_abort';", &session);
    defer abort_prepared.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 4), source.applied);
    try std.testing.expect(source.last_pending);

    var aborted = try server.applyRelationalSqlDdlWithSession("ROLLBACK PREPARED 'usage_abort';", &session);
    defer aborted.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 5), source.applied);
    try std.testing.expect(source.last_aborted);

    var aborted_retry = try server.applyRelationalSqlDdlWithSession("ROLLBACK PREPARED 'usage_abort';", &session);
    defer aborted_retry.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 6), source.applied);
    try std.testing.expect(source.last_aborted);
}

test "api http server persists prepared transaction SQL DDL through durable session store fallback" {
    const alloc = std.testing.allocator;
    const session_path = try uniqueTestTmpPathAlloc(alloc, "antfly-api-http-prepared-transaction-fallback");
    defer alloc.free(session_path);
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    std.Io.Dir.cwd().deleteTree(io_impl.io(), session_path) catch {};
    defer std.Io.Dir.cwd().deleteTree(io_impl.io(), session_path) catch {};

    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }
    };

    var source = FakeSource{};
    {
        var server = try ApiHttpServer.initWithConfig(alloc, .{ .session_store_path = session_path }, source.iface(), null, null);
        defer server.deinit();
        var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
        defer session.deinit(alloc);

        var set_local = try server.applyRelationalSqlDdlWithSession("SET LOCAL search_path TO analytics;", &session);
        defer set_local.deinit(alloc);
        try std.testing.expect(session.transaction_local_search_path);

        var prepared = try server.applyRelationalSqlDdlWithSession("PREPARE TRANSACTION 'durable_usage_batch';", &session);
        defer prepared.deinit(alloc);
        try std.testing.expect(!session.transaction_local_search_path);
    }

    {
        var server = try ApiHttpServer.initWithConfig(alloc, .{ .session_store_path = session_path }, source.iface(), null, null);
        defer server.deinit();
        var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
        defer session.deinit(alloc);

        var committed = try server.applyRelationalSqlDdlWithSession("COMMIT PREPARED 'durable_usage_batch';", &session);
        defer committed.deinit(alloc);

        var committed_retry = try server.applyRelationalSqlDdlWithSession("COMMIT PREPARED 'durable_usage_batch';", &session);
        defer committed_retry.deinit(alloc);

        try std.testing.expectError(
            error.PreparedTransactionDecisionConflict,
            server.applyRelationalSqlDdlWithSession("ROLLBACK PREPARED 'durable_usage_batch';", &session),
        );
    }
}

test "api http server applies public SQL savepoints to session state" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }
    };
    const Request = struct {
        fn post(server: *ApiHttpServer, allocator: std.mem.Allocator, session_id: ?u64, sql: []const u8) !http_common.HttpResponse {
            const body = if (session_id) |id|
                try std.fmt.allocPrint(allocator, "{{\"session_id\":{d},\"sql\":\"{s}\"}}", .{ id, sql })
            else
                try std.fmt.allocPrint(allocator, "{{\"sql\":\"{s}\"}}", .{sql});
            defer allocator.free(body);
            return try server.handle(.{
                .method = .POST,
                .uri = "/db/v1/sql",
                .content_type = "application/json",
                .body = body,
            });
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();

    var begin_resp = try Request.post(&server, alloc, null, "BEGIN;");
    defer begin_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), begin_resp.status);
    var parsed_begin = try std.json.parseFromSlice(std.json.Value, alloc, begin_resp.body, .{ .allocate = .alloc_always });
    defer parsed_begin.deinit();
    const session_id = @as(u64, @intCast(parsed_begin.value.object.get("session_id").?.integer));
    try std.testing.expect(session_id != 0);

    var set_path_resp = try Request.post(&server, alloc, session_id, "SET search_path TO analytics, public;");
    defer set_path_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), set_path_resp.status);
    const stored_after_set = server.sql_catalog_session_runtime.sessions.getPtr(session_id) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 2), stored_after_set.search_path.len);
    try std.testing.expectEqualStrings("analytics", stored_after_set.search_path[0]);
    try std.testing.expectEqualStrings(catalog_resources.default_namespace_name, stored_after_set.search_path[1]);

    var savepoint_resp = try Request.post(&server, alloc, session_id, "SAVEPOINT before_local;");
    defer savepoint_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), savepoint_resp.status);
    try std.testing.expectEqual(@as(usize, 1), server.sql_savepoint_runtime.savepointCountForTest(session_id));

    var set_local_resp = try Request.post(&server, alloc, session_id, "SET LOCAL search_path TO reports;");
    defer set_local_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), set_local_resp.status);
    const stored_after_local = server.sql_catalog_session_runtime.sessions.getPtr(session_id) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 1), stored_after_local.search_path.len);
    try std.testing.expectEqualStrings("reports", stored_after_local.search_path[0]);
    try std.testing.expect(stored_after_local.transaction_local_search_path);

    var rollback_to_resp = try Request.post(&server, alloc, session_id, "ROLLBACK TO SAVEPOINT before_local;");
    defer rollback_to_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), rollback_to_resp.status);
    var parsed_rollback_to = try std.json.parseFromSlice(std.json.Value, alloc, rollback_to_resp.body, .{ .allocate = .alloc_always });
    defer parsed_rollback_to.deinit();
    try std.testing.expectEqualStrings("in_transaction", parsed_rollback_to.value.object.get("transaction_status").?.string);
    const stored_after_rollback = server.sql_catalog_session_runtime.sessions.getPtr(session_id) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(usize, 2), stored_after_rollback.search_path.len);
    try std.testing.expectEqualStrings("analytics", stored_after_rollback.search_path[0]);
    try std.testing.expectEqualStrings(catalog_resources.default_namespace_name, stored_after_rollback.search_path[1]);
    try std.testing.expect(!stored_after_rollback.transaction_local_search_path);
    try std.testing.expectEqual(@as(usize, 1), server.sql_savepoint_runtime.savepointCountForTest(session_id));

    var savepoint_release_resp = try Request.post(&server, alloc, session_id, "SAVEPOINT before_release;");
    defer savepoint_release_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), savepoint_release_resp.status);
    try std.testing.expectEqual(@as(usize, 2), server.sql_savepoint_runtime.savepointCountForTest(session_id));

    var release_resp = try Request.post(&server, alloc, session_id, "RELEASE SAVEPOINT before_release;");
    defer release_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), release_resp.status);
    try std.testing.expectEqual(@as(usize, 1), server.sql_savepoint_runtime.savepointCountForTest(session_id));

    var missing_resp = try Request.post(&server, alloc, session_id, "ROLLBACK TO SAVEPOINT missing_savepoint;");
    defer missing_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 400), missing_resp.status);
    try expectPublicSqlDiagnosticBody(alloc, missing_resp.body, "execute", "invalid_sql_request", "invalid sql request", null, null);

    var commit_resp = try Request.post(&server, alloc, session_id, "COMMIT;");
    defer commit_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), commit_resp.status);
    try std.testing.expectEqual(@as(usize, 0), server.sql_savepoint_runtime.savepointCountForTest(session_id));
}

test "api http server applies cursor SQL plans through DDL session helper" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();

    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
