fn expectPublicSqlDiagnosticBody(
    alloc: std.mem.Allocator,
    body: []const u8,
    expected_phase: []const u8,
    expected_code: []const u8,
    expected_message: []const u8,
    expected_span_start: ?i64,
    expected_span_end: ?i64,
) !void {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, body, .{ .allocate = .alloc_always });
    defer parsed.deinit();
    const err_obj = parsed.value.object.get("error") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(expected_phase, err_obj.object.get("phase").?.string);
    try std.testing.expectEqualStrings(expected_code, err_obj.object.get("code").?.string);
    try std.testing.expectEqualStrings(expected_message, err_obj.object.get("message").?.string);
    const span = err_obj.object.get("span").?.object;
    if (expected_span_start) |span_start| try std.testing.expectEqual(span_start, span.get("start").?.integer);
    if (expected_span_end) |span_end| try std.testing.expectEqual(span_end, span.get("end").?.integer);
}

fn expectPublicSqlDiagnosticMissingNativeModel(
    alloc: std.mem.Allocator,
    body: []const u8,
    expected_missing_native_model: []const u8,
) !void {
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, body, .{ .allocate = .alloc_always });
    defer parsed.deinit();
    const err_obj = parsed.value.object.get("error") orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings(expected_missing_native_model, err_obj.object.get("missing_native_model").?.string);
}

test "api http server surfaces public SQL parse diagnostics for generated malformed SQL" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();

    var execute_resp = try server.handlePublicSql(
        "{\"sql\":\"SELECT id FROM usage_records WHERE\"}",
        null,
    );
    defer execute_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 400), execute_resp.status);
    try expectPublicSqlDiagnosticBody(alloc, execute_resp.body, "parse", "invalid_sql_request", "invalid sql request", 34, 34);

    var describe_outcome = try server.handlePublicSqlDescribeRequestResult(.{
