        },
        .result => return error.TestUnexpectedResult,
    }
}

test "api http server generated read row claim diagnostics use retained AST metadata" {
    const alloc = std.testing.allocator;

    var aggregate_read = try sql_adapter.ParsedSql.initAlloc(alloc, "SELECT count(*) FROM usage_records FOR UPDATE");
    defer aggregate_read.deinit(alloc);
    try std.testing.expectEqualStrings(
        "lockable base-row source for aggregate row claim",
        ApiHttpServer.publicSqlGeneratedReadRowClaimMissingNativeModel(&aggregate_read) orelse return error.TestUnexpectedResult,
    );

    if (aggregate_read.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .read => |read_ast| read_ast.row_lock_tokens = null,
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expect(ApiHttpServer.publicSqlGeneratedReadRowClaimMissingNativeModel(&aggregate_read) == null);

    var cte_body_read = try sql_adapter.ParsedSql.initAlloc(alloc, "WITH source_rows AS (SELECT id FROM usage_records FOR UPDATE) SELECT id FROM source_rows");
    defer cte_body_read.deinit(alloc);
    try std.testing.expectEqualStrings(
        "lockable base-row source for materialized CTE row claim",
        ApiHttpServer.publicSqlGeneratedReadRowClaimMissingNativeModel(&cte_body_read) orelse return error.TestUnexpectedResult,
    );

    if (cte_body_read.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .read => |read_ast| read_ast.cte_items[0].body_row_lock_tokens = null,
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expect(ApiHttpServer.publicSqlGeneratedReadRowClaimMissingNativeModel(&cte_body_read) == null);
}

test "api http server binds public sql authorization to resolved statement targets" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
                .projected_tables = 1,
            };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            return .{
                .status = try status(ptr),
                .tables = @constCast((&[_]metadata_table_manager.TableRecord{.{
                    .table_id = 1,
                    .database_name = catalog_resources.default_database_name,
                    .namespace_name = catalog_resources.default_namespace_name,
                    .name = "docs",
                    .schema_json = schema_json,
                    .placement_role = "data",
                }})[0..]),
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    var auth = try initTestAuthManager(alloc);
    try bindTestAuthManager(alloc, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();

    var other_permission = [_]usermgr.Permission{
        try usermgr.Permission.initOwned(alloc, .table, "other", .read),
    };
    defer other_permission[0].deinit(alloc);
    var other_reader = try auth.manager.createUser("other_reader", "reader", &other_permission);
    defer other_reader.deinit(alloc);

    var docs_permission = [_]usermgr.Permission{
        try usermgr.Permission.initOwned(alloc, .table, "docs", .read),
    };
    defer docs_permission[0].deinit(alloc);
    var docs_reader = try auth.manager.createUser("docs_reader", "reader", &docs_permission);
    defer docs_reader.deinit(alloc);

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{
        .auth_enabled = true,
        .user_manager = &auth.manager,
    }, source.iface(), null, null);
    defer server.deinit();

    var unauthorized = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.db_v1_sql,
        .content_type = "application/json",
        .body = "{\"sql\":\"SELECT id FROM docs;\"}",
    });
    defer unauthorized.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 401), unauthorized.status);

    const other_auth = try encodeBasicAuthorization(alloc, "other_reader", "reader");
    defer alloc.free(other_auth);
    var denied_read = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.db_v1_sql,
        .authorization = other_auth,
        .content_type = "application/json",
        .body = "{\"sql\":\"SELECT id FROM docs;\"}",
    });
    defer denied_read.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 403), denied_read.status);
    try expectPublicSqlDiagnosticBody(alloc, denied_read.body, "bind", "permission_denied", "permission denied", null, null);

    const docs_auth = try encodeBasicAuthorization(alloc, "docs_reader", "reader");
    defer alloc.free(docs_auth);
    var allowed_past_route_and_bind = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.db_v1_sql,
        .authorization = docs_auth,
        .content_type = "application/json",
        .body = "{\"sql\":\"SELECT id FROM docs;\"}",
    });
    defer allowed_past_route_and_bind.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 404), allowed_past_route_and_bind.status);
    try expectPublicSqlDiagnosticBody(alloc, allowed_past_route_and_bind.body, "bind", "table_not_found", "table not found", null, null);

    var denied_ddl = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.db_v1_sql,
        .authorization = docs_auth,
        .content_type = "application/json",
        .body = "{\"sql\":\"CREATE TABLE new_docs (id text PRIMARY KEY);\"}",
    });
    defer denied_ddl.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 403), denied_ddl.status);
    try expectPublicSqlDiagnosticBody(alloc, denied_ddl.body, "bind", "permission_denied", "permission denied", null, null);
}

test "api http server exposes psql-style SQL session endpoint" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();

    var prepare_resp = try server.handle(.{
        .method = .POST,
        .uri = "/db/v1/sql",
        .content_type = "application/json",
        .body = "{\"read_only\":null,\"sql\":\"PREPARE usage_plan(text) AS SELECT $1 AS status;\"}",
    });
    defer prepare_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), prepare_resp.status);
    var parsed_prepare = try std.json.parseFromSlice(std.json.Value, alloc, prepare_resp.body, .{ .allocate = .alloc_always });
    defer parsed_prepare.deinit();
    const session_id = @as(u64, @intCast(parsed_prepare.value.object.get("session_id").?.integer));
    try std.testing.expect(session_id != 0);
    try std.testing.expectEqualStrings("ddl", parsed_prepare.value.object.get("kind").?.string);
    try std.testing.expectEqualStrings("prepared_statement", parsed_prepare.value.object.get("statement_kind").?.string);
    try std.testing.expect(parsed_prepare.value.object.get("noop").?.bool);
    try std.testing.expectEqual(
        @as(usize, 1),
        server.sql_prepared_statement_runtime.statementCountForTest(session_id),
    );

    var describe_prepare = try server.handlePublicSqlDescribeRequestResult(.{
        .session_id = session_id,
        .sql = "PREPARE describe_only AS SELECT 1;",
    }, null);
    defer describe_prepare.deinit(alloc);
    switch (describe_prepare) {
        .result => |result| {
            try std.testing.expectEqualStrings("prepared_statement", result.statement_kind);
            try std.testing.expect(!result.has_row_description);
        },
        .response => return error.TestUnexpectedResult,
    }
    try std.testing.expectEqual(
        @as(usize, 1),
        server.sql_prepared_statement_runtime.statementCountForTest(session_id),
    );

    const prepare_write_body = try std.fmt.allocPrint(
        alloc,
        "{{\"session_id\":{d},\"sql\":\"PREPARE write_plan(text) AS INSERT INTO usage_records(id, status) VALUES ($1, 'prepared');\"}}",
        .{session_id},
    );
    defer alloc.free(prepare_write_body);
    var prepare_write_resp = try server.handle(.{
        .method = .POST,
        .uri = "/db/v1/sql",
        .content_type = "application/json",
        .body = prepare_write_body,
    });
    defer prepare_write_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), prepare_write_resp.status);
    try std.testing.expectEqual(
        @as(usize, 2),
        server.sql_prepared_statement_runtime.statementCountForTest(session_id),
    );

    const execute_body = try std.fmt.allocPrint(
        alloc,
        "{{\"session_id\":{d},\"sql\":\"EXECUTE usage_plan('open');\"}}",
        .{session_id},
    );
    defer alloc.free(execute_body);
    var execute_resp = try server.handle(.{
        .method = .POST,
        .uri = "/db/v1/sql",
        .content_type = "application/json",
        .body = execute_body,
    });
    defer execute_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), execute_resp.status);
    var parsed_execute = try std.json.parseFromSlice(std.json.Value, alloc, execute_resp.body, .{ .allocate = .alloc_always });
    defer parsed_execute.deinit();
    try std.testing.expectEqual(@as(i64, @intCast(session_id)), parsed_execute.value.object.get("session_id").?.integer);
    try std.testing.expectEqualStrings("read", parsed_execute.value.object.get("kind").?.string);
    try std.testing.expectEqualStrings("query", parsed_execute.value.object.get("statement_kind").?.string);
    const prepared_execute_rows = parsed_execute.value.object.get("result").?.object.get("rows").?.array.items;
    try std.testing.expectEqual(@as(usize, 1), prepared_execute_rows.len);
    try std.testing.expectEqualStrings("open", prepared_execute_rows[0].object.get("status").?.string);

    const readonly_execute_read_body = try std.fmt.allocPrint(
