test "api http server exposes SQL routine bindings to catalog read planning" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .apply_relational_sql_ddl_plan_with_session = applyRelationalSqlDdlPlanWithSession,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn applyRelationalSqlDdlPlanWithSession(
            _: *anyopaque,
            _: std.mem.Allocator,
            _: *sql_adapter.DurableSqlPlan,
            _: catalog_resources.SqlCatalogSession,
        ) !tables_api.AppliedRelationalSqlDdlRecord {
            return error.TestUnexpectedResult;
        }
    };

    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"status_key":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed_schema = try schema_mod.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const schema = try schema_mod.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer runtime_schema_mod.freeSchema(alloc, schema);

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();
    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session.deinit(alloc);

    var created = try server.applyRelationalSqlDdlWithSession(
        "CREATE FUNCTION normalize_status(text) RETURNS text LANGUAGE sql AS 'SELECT lower($1)';",
        &session,
    );
    defer created.deinit(alloc);

    var lowered = try server.lowerRelationalSqlReadPlanWithRoutineBindingsAlloc(
        alloc,
        "SELECT id, normalize_status(status) AS status_key FROM usage_records WHERE id = $1",
        schema,
        &.{.{ .string = "u1" }},
        null,
    );
    defer lowered.deinit(alloc);

    const query = switch (lowered) {
        .query => |query| query,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 1), query.plan.query.expressions.len);
    const expression = query.plan.query.expressions[0].expression;
    try std.testing.expectEqual(runtime_schema_mod.RelationalRowsExpressionKind.lower, expression.kind);
    try std.testing.expectEqual(@as(usize, 1), expression.operands.len);
    try std.testing.expectEqual(runtime_schema_mod.RelationalRowsExpressionKind.field, expression.operands[0].kind);
    try std.testing.expectEqualStrings("status", expression.operands[0].field);
}

test "api http server freezes routine settings from current SQL session" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .apply_relational_sql_ddl_plan_with_session = applyRelationalSqlDdlPlanWithSession,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn applyRelationalSqlDdlPlanWithSession(
            _: *anyopaque,
            _: std.mem.Allocator,
            _: *sql_adapter.DurableSqlPlan,
            _: catalog_resources.SqlCatalogSession,
        ) !tables_api.AppliedRelationalSqlDdlRecord {
            return error.TestUnexpectedResult;
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();
    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session.deinit(alloc);

    var set_path = try server.applyRelationalSqlDdlWithSession("SET search_path TO tenant_schema, public;", &session);
    defer set_path.deinit(alloc);
    var set_timeout = try server.applyRelationalSqlDdlWithSession("SET statement_timeout = '5ms';", &session);
    defer set_timeout.deinit(alloc);

    var created = try server.applyRelationalSqlDdlWithSession(
        "CREATE FUNCTION freeze_current(text) RETURNS text LANGUAGE sql SET search_path FROM CURRENT SET statement_timeout FROM CURRENT AS 'SELECT lower($1)';",
        &session,
    );
    defer created.deinit(alloc);

    const settings = try server.sql_routine_runtime.routineSettingsForTestAlloc(alloc, .function, "freeze_current", 1);
    defer {
        for (settings) |*setting| setting.deinit(alloc);
        if (settings.len > 0) alloc.free(settings);
    }
    try std.testing.expectEqual(@as(usize, 2), settings.len);
    try std.testing.expectEqualStrings("search_path", settings[0].name);
    try std.testing.expect(!settings[0].from_current);
    try std.testing.expectEqual(@as(usize, 2), settings[0].values.len);
    try std.testing.expectEqualStrings("tenant_schema", settings[0].values[0]);
    try std.testing.expectEqualStrings("public", settings[0].values[1]);
    try std.testing.expectEqualStrings("statement_timeout", settings[1].name);
    try std.testing.expect(!settings[1].from_current);
    try std.testing.expectEqual(@as(usize, 1), settings[1].values.len);
    try std.testing.expectEqualStrings("5ms", settings[1].values[0]);

    try std.testing.expectError(
        error.RoleSettingNotFound,
        server.applyRelationalSqlDdlWithSession(
            "CREATE FUNCTION missing_current(text) RETURNS text LANGUAGE sql SET work_mem FROM CURRENT AS 'SELECT lower($1)';",
            &session,
        ),
    );
}

test "api http server passes SQL routine bindings to source-backed schema DDL" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        table: ?metadata_table_manager.TableRecord = null,
        binding_aware_calls: usize = 0,

        fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
            if (self.table) |record| metadata_table_manager.freeTable(allocator, record);
            self.* = undefined;
        }

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                    .apply_relational_sql_ddl_plan_with_session = applyRelationalSqlDdlPlanWithSession,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn tableSlice(self: *@This()) []metadata_table_manager.TableRecord {
            if (self.table) |*record| return @as([*]metadata_table_manager.TableRecord, @ptrCast(record))[0..1];
            return &.{};
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = try status(ptr),
                .tables = self.tableSlice(),
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}

        fn applyRelationalSqlDdlPlanWithSession(
            ptr: *anyopaque,
            allocator: std.mem.Allocator,
            plan: *sql_adapter.DurableSqlPlan,
            session: catalog_resources.SqlCatalogSession,
        ) !tables_api.AppliedRelationalSqlDdlRecord {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.binding_aware_calls += 1;

            const table_plan = switch (plan.*) {
                .table_ddl => |*table| table,
                else => return error.TestUnexpectedResult,
            };
            var target = try tables_api.relationalSqlDdlTargetForTablePlanWithSessionAlloc(allocator, table_plan.*, session);
            defer target.deinit(allocator);

            var base_table = tables_api.deriveRelationalSqlDdlTargetTableRecord(target);
            const source_table = if (self.table) |*record| record else &base_table;
            var applied = try tables_api.applyTableDdlPlanToTableRecordWithSessionAlloc(
                allocator,
                source_table,
                table_plan,
                session,
            );
            errdefer applied.deinit(allocator);

            const stored = try metadata_table_manager.cloneTable(allocator, applied.table);
            errdefer metadata_table_manager.freeTable(allocator, stored);
            if (self.table) |record| metadata_table_manager.freeTable(allocator, record);
            self.table = stored;
            return applied;
        }
    };

    var source = FakeSource{};
    defer source.deinit(alloc);
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();
    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session.deinit(alloc);

    var created_routine = try server.applyRelationalSqlDdlWithSession(
        "CREATE FUNCTION normalize_status(text) RETURNS text LANGUAGE sql AS 'SELECT lower($1)';",
        &session,
    );
    defer created_routine.deinit(alloc);

    var created_table = try server.applyRelationalSqlDdlWithSession(
        "CREATE TABLE usage_records (id text PRIMARY KEY, status text, status_key text GENERATED ALWAYS AS (normalize_status(status)) STORED, CONSTRAINT usage_records_status_check CHECK (normalize_status(status) != 'deleted'));",
        &session,
    );
    defer created_table.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), source.binding_aware_calls);
    try std.testing.expect(std.mem.indexOf(u8, created_table.table.schema_json, "\"generated\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, created_table.table.schema_json, "\"checks\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, created_table.table.schema_json, "usage_records_status_check") != null);
    try std.testing.expect(std.mem.indexOf(u8, created_table.table.schema_json, "\"op\":\"lower\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, created_table.table.schema_json, "\"field\":\"status\"") != null);
}

test "api http server refreshes SQL routine hooks from ready extension query functions" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        installed_ready: bool = false,
        installed_record: extension_domain.InstalledExtension = .{
            .name = "pgcrypto",
            .package_name = "pgcrypto",
            .package_version = "1.0.0",
            .package_digest = "sha256:pgcrypto",
            .scope = .{ .kind = .cluster },
            .status = .ready,
        },
        member_record: extension_domain.ExtensionMember = .{
            .extension_name = "pgcrypto",
            .scope = .{ .kind = .cluster },
            .object_kind = .query_function,
            .object_name = "gen_random_uuid",
            .owner_metadata_json = "{\"native_expression\":\"uuid_v4\",\"arity\":0,\"sql_names\":[\"gen_random_uuid\"]}",
        },

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                    .apply_relational_sql_ddl_plan_with_session = applyRelationalSqlDdlPlanWithSession,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
                .projected_installed_extensions = 1,
                .projected_extension_members = 1,
            };
        }

        fn installedSlice(self: *@This()) []extension_domain.InstalledExtension {
            if (!self.installed_ready) return &.{};
            return @as([*]extension_domain.InstalledExtension, @ptrCast(&self.installed_record))[0..1];
        }

        fn memberSlice(self: *@This()) []extension_domain.ExtensionMember {
            if (!self.installed_ready) return &.{};
            return @as([*]extension_domain.ExtensionMember, @ptrCast(&self.member_record))[0..1];
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = try status(ptr),
                .tables = &.{},
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .installed_extensions = self.installedSlice(),
                .extension_members = self.memberSlice(),
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}

        fn applyRelationalSqlDdlPlanWithSession(
            ptr: *anyopaque,
            alloc_arg: std.mem.Allocator,
            plan: *sql_adapter.DurableSqlPlan,
            _: catalog_resources.SqlCatalogSession,
        ) !tables_api.AppliedRelationalSqlDdlRecord {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            switch (plan.*) {
                .extension => |extension_plan| switch (extension_plan) {
                    .create => self.installed_ready = true,
                    .drop => self.installed_ready = false,
                    else => return error.TestUnexpectedResult,
                },
                else => return error.TestUnexpectedResult,
            }
            return try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(alloc_arg);
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();
    var session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, catalog_resources.SqlCatalogSession.default());
    defer session.deinit(alloc);

    var created = try server.applyRelationalSqlDdlWithSession("CREATE EXTENSION pgcrypto;", &session);
    defer created.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), server.sql_routine_runtime.routineCountForTest());
    const generated = try server.sql_routine_runtime.executeExpressionRoutineArgsAlloc(alloc, "gen_random_uuid", &.{});
    defer alloc.free(generated);
    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, generated, .{});
    defer parsed.deinit();
    switch (parsed.value) {
        .string => |value| try std.testing.expect(value.len > 0),
        else => return error.TestUnexpectedResult,
    }

    var dropped = try server.applyRelationalSqlDdlWithSession("DROP EXTENSION pgcrypto;", &session);
    defer dropped.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), server.sql_routine_runtime.routineCountForTest());
    try std.testing.expectError(error.RoutineNotFound, server.sql_routine_runtime.executeExpressionRoutineArgsAlloc(alloc, "gen_random_uuid", &.{}));
}

test "api http server executes SQL COPY FROM STDIN through catalog rows batch" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"status_key":{"type":"keyword","generated":{"op":"expression","expression":{"op":"lower","args":[{"field":"status"}]}}}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const FakeSource = struct {
        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 91,
                .metrics = .{},
                .projected_stores = 1,
            };
        }

        fn adminSnapshot(_: *anyopaque) !metadata_api.AdminSnapshot {
            return .{
                .status = .{ .metadata_group_id = 91, .metrics = .{} },
                .tables = @constCast((&[_]metadata_table_manager.TableRecord{.{
                    .table_id = 17,
                    .name = "events",
                    .database_name = "tenant_ops",
                    .namespace_name = "analytics",
                    .schema_json = schema_json,
                    .indexes_json = tables_api.default_indexes_json,
                    .placement_role = "data",
                }})[0..]),
                .ranges = @constCast((&[_]metadata_table_manager.RangeRecord{})[0..]),
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };
    const FakeWrites = struct {
        calls: usize = 0,
        last_row_count: usize = 0,
        first_row_json: []u8 = &.{},

        fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
            if (self.first_row_json.len > 0) allocator.free(self.first_row_json);
        }

        fn source(self: *@This()) table_writes.TableWriteSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .batch = batch,
                    .batch_catalog = batchCatalog,
                },
            };
        }

        fn batch(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: db_mod.types.BatchRequest) anyerror!?void {
            return error.UnsupportedOperation;
        }

        fn batchCatalog(ptr: *anyopaque, allocator: std.mem.Allocator, target: catalog_resources.TableTarget, req: db_mod.types.BatchRequest) anyerror!?void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("tenant_ops", target.database_name);
            try std.testing.expectEqualStrings("analytics", target.namespace_name);
            try std.testing.expectEqualStrings("events", target.table_name);
            try std.testing.expect(req.writes.len > 0);
            try std.testing.expectEqual(@as(usize, 0), req.deletes.len);
            if (self.first_row_json.len > 0) allocator.free(self.first_row_json);
            self.first_row_json = try allocator.dupe(u8, req.writes[0].value);
            self.last_row_count = req.writes.len;
            self.calls += 1;
            return {};
        }
    };
    const FakeReads = struct {
        calls: usize = 0,

        fn source(self: *@This()) table_reads.TableReadSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .lookup = lookup,
                    .scan = scan,
                    .query = query,
                    .rows_query_plan_catalog = rowsQueryPlanCatalog,
                },
            };
        }

        fn lookup(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8, _: db_mod.types.LookupOptions, _: raft_mod.ReadConsistency) anyerror!?table_reads.LookupResponse {
            return error.UnsupportedOperation;
        }

        fn scan(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8, _: []const u8, _: db_mod.types.ScanOptions, _: raft_mod.ReadConsistency) anyerror!?table_reads.ScanResponse {
            return error.UnsupportedOperation;
        }

        fn query(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: db_mod.types.SearchRequest, _: raft_mod.ReadConsistency) anyerror!?query_api.QueryResponse {
            return error.UnsupportedOperation;
        }

        fn rowsQueryPlanCatalog(
            ptr: *anyopaque,
            allocator: std.mem.Allocator,
            target: catalog_resources.TableTarget,
            runtime_schema: runtime_schema_mod.TableSchema,
            plan: db_mod.types.RelationalRowsQueryPlan,
            consistency: raft_mod.ReadConsistency,
        ) anyerror!?db_mod.types.RelationalRowsQueryResult {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqual(raft_mod.ReadConsistency.read_index, consistency);
            try std.testing.expectEqualStrings("tenant_ops", target.database_name);
            try std.testing.expectEqualStrings("analytics", target.namespace_name);
            try std.testing.expectEqualStrings("events", target.table_name);
            try std.testing.expectEqual(@as(usize, 3), runtime_schema.relational_columns.len);
            try std.testing.expect(!plan.query.select_all);
            try std.testing.expectEqual(@as(usize, 2), plan.query.select.len);
            try std.testing.expectEqualStrings("id", plan.query.select[0]);
            try std.testing.expectEqualStrings("status", plan.query.select[1]);
            try std.testing.expectEqual(@as(usize, 0), plan.query.predicates.len);
            try std.testing.expectEqual(@as(usize, 1), plan.query.expression_predicates.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, plan.query.expression_predicates[0].lhs.kind);
            try std.testing.expectEqualStrings("status", plan.query.expression_predicates[0].lhs.operands[0].field);
            try std.testing.expectEqual(runtime_schema_mod.RelationalCheckOp.eq, plan.query.expression_predicates[0].op);
            try std.testing.expectEqualStrings("\"ready\"", plan.query.expression_predicates[0].rhs[0].value_json);
            self.calls += 1;

            const rows = try allocator.alloc([]const u8, 1);
            errdefer allocator.free(rows);
            rows[0] = try allocator.dupe(u8, "{\"id\":\"u1\",\"status\":\"Ready\"}");
            return .{ .rows = rows, .total = 1 };
        }
    };
    const FakeAudit = struct {
        const Captured = struct {
            outcome: SqlBulkIoAuditOutcome,
            action: sql_adapter.BulkSqlIoAuditAction,
            operation: sql_adapter.BulkSqlIoOperation,
            native_route: sql_adapter.BulkSqlIoNativeRoute,
            stream: sql_adapter.BulkSqlIoStream,
            codec: sql_adapter.BulkSqlIoCodec,
            required_permission: usermgr.PermissionType,
            authenticated_subject: ?[]u8 = null,
            database_name: []u8,
            namespace_name: []u8,
            table_name: []u8,
            row_count: usize,
            error_name: ?[]u8 = null,

            fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
                if (self.authenticated_subject) |value| allocator.free(value);
                allocator.free(self.database_name);
                allocator.free(self.namespace_name);
                allocator.free(self.table_name);
                if (self.error_name) |value| allocator.free(value);
                self.* = undefined;
            }
        };

        alloc: std.mem.Allocator,
        events: [15]Captured = undefined,
        count: usize = 0,

        fn deinit(self: *@This()) void {
            for (self.events[0..self.count]) |*event| event.deinit(self.alloc);
        }

        fn sink(self: *@This()) SqlBulkIoAuditSink {
            return .{ .ptr = self, .record = record };
        }

        fn record(ptr: *anyopaque, event: SqlBulkIoAuditRecord) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (self.count >= self.events.len) return error.TestUnexpectedResult;
            self.events[self.count] = .{
                .outcome = event.outcome,
                .action = event.action,
                .operation = event.operation,
                .native_route = event.native_route,
                .stream = event.stream,
                .codec = event.codec,
                .required_permission = event.required_permission,
                .authenticated_subject = if (event.authenticated_subject) |subject| try self.alloc.dupe(u8, subject) else null,
                .database_name = try self.alloc.dupe(u8, event.target.database_name),
                .namespace_name = try self.alloc.dupe(u8, event.target.namespace_name),
                .table_name = try self.alloc.dupe(u8, event.target.table_name),
                .row_count = event.row_count,
                .error_name = if (event.error_name) |name| try self.alloc.dupe(u8, name) else null,
            };
            self.count += 1;
        }
    };
    const FakeFileIo = struct {
        import_payload: []const u8,
        last_export_path: []u8 = &.{},
        last_export_payload: []u8 = &.{},

        fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
            if (self.last_export_path.len > 0) allocator.free(self.last_export_path);
            if (self.last_export_payload.len > 0) allocator.free(self.last_export_payload);
        }

        fn iface(self: *@This()) SqlBulkIoFileIo {
            return .{
                .ptr = self,
                .read_import = readImport,
                .write_export = writeExport,
            };
        }

        fn readImport(ptr: *anyopaque, allocator: std.mem.Allocator, path: []const u8) ![]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("/tmp/events.csv", path);
            return try allocator.dupe(u8, self.import_payload);
        }

        fn writeExport(ptr: *anyopaque, path: []const u8, payload: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (self.last_export_path.len > 0) std.testing.allocator.free(self.last_export_path);
            if (self.last_export_payload.len > 0) std.testing.allocator.free(self.last_export_payload);
            self.last_export_path = try std.testing.allocator.dupe(u8, path);
            self.last_export_payload = try std.testing.allocator.dupe(u8, payload);
        }
    };
    const FakeProgramIo = struct {
        import_payload: []const u8,
        last_import_command: []u8 = &.{},
        last_export_command: []u8 = &.{},
        last_export_payload: []u8 = &.{},

        fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
            if (self.last_import_command.len > 0) allocator.free(self.last_import_command);
            if (self.last_export_command.len > 0) allocator.free(self.last_export_command);
            if (self.last_export_payload.len > 0) allocator.free(self.last_export_payload);
        }

        fn iface(self: *@This()) SqlBulkIoProgramIo {
            return .{
                .ptr = self,
                .read_import = readImport,
                .write_export = writeExport,
            };
        }

        fn readImport(ptr: *anyopaque, allocator: std.mem.Allocator, command: []const u8) ![]u8 {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (self.last_import_command.len > 0) allocator.free(self.last_import_command);
            self.last_import_command = try allocator.dupe(u8, command);
            return try allocator.dupe(u8, self.import_payload);
        }

        fn writeExport(ptr: *anyopaque, command: []const u8, payload: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (self.last_export_command.len > 0) std.testing.allocator.free(self.last_export_command);
            if (self.last_export_payload.len > 0) std.testing.allocator.free(self.last_export_payload);
            self.last_export_command = try std.testing.allocator.dupe(u8, command);
            self.last_export_payload = try std.testing.allocator.dupe(u8, payload);
        }
    };

