    try std.testing.expectEqual(sql_adapter.BulkSqlIoAuditAction.copy_from, audit.events[9].action);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoOperation.import_rows, audit.events[9].operation);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoStream.program, audit.events[9].stream);
    try std.testing.expectEqualStrings("UnsupportedOperation", audit.events[9].error_name orelse return error.TestUnexpectedResult);

    var copied_program_result = try server.executeBulkSqlWithSession(
        "COPY events (id, status) FROM PROGRAM 'cat /tmp/events.csv' WITH (FORMAT csv, HEADER true);",
        null,
        session,
        &identity,
    );
    defer copied_program_result.deinit(alloc);
    try std.testing.expectEqualStrings("cat /tmp/events.csv", program_io.last_import_command);
    try std.testing.expectEqual(@as(usize, 4), writes.calls);
    switch (copied_program_result) {
        .import_rows => |copied| try std.testing.expectEqual(@as(usize, 1), copied.writes.len),
        .export_stdout, .export_file => return error.TestUnexpectedResult,
    }
    try std.testing.expectEqual(@as(usize, 11), audit.count);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoAuditAction.copy_from, audit.events[10].action);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoOperation.import_rows, audit.events[10].operation);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoNativeRoute.rows_batch, audit.events[10].native_route);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoStream.program, audit.events[10].stream);
    try std.testing.expectEqual(usermgr.PermissionType.write, audit.events[10].required_permission);
    try std.testing.expectEqual(@as(usize, 1), audit.events[10].row_count);

    var exported_program_result = try server.executeBulkSqlWithSession(
        "COPY events (id, status) TO PROGRAM 'cat > /tmp/events.csv' WITH (FORMAT csv, HEADER true);",
        null,
        session,
        &identity,
    );
    defer exported_program_result.deinit(alloc);
    switch (exported_program_result) {
        .export_file => {},
        .import_rows, .export_stdout => return error.TestUnexpectedResult,
    }
    try std.testing.expectEqualStrings("cat > /tmp/events.csv", program_io.last_export_command);
    try std.testing.expectEqualStrings("id,status\nu1,Ready\n", program_io.last_export_payload);
    try std.testing.expectEqual(@as(usize, 12), audit.count);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoAuditAction.copy_to, audit.events[11].action);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoOperation.export_rows, audit.events[11].operation);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoNativeRoute.rows_query, audit.events[11].native_route);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoStream.program, audit.events[11].stream);
    try std.testing.expectEqual(usermgr.PermissionType.read, audit.events[11].required_permission);
    try std.testing.expectEqual(@as(usize, 1), audit.events[11].row_count);

    var routine_session = try sql_adapter.OwnedSqlCatalogSession.fromSessionAlloc(alloc, session);
    defer routine_session.deinit(alloc);
    var skip_copy_function = try server.applyRelationalSqlDdlWithSession(
        "CREATE FUNCTION skip_copy_insert() RETURNS trigger LANGUAGE plpgsql AS 'BEGIN RETURN NULL; END';",
        &routine_session,
    );
    defer skip_copy_function.deinit(alloc);
    var skip_copy_trigger = try server.applyRelationalSqlDdlWithSession(
        "CREATE TRIGGER skip_copy_insert BEFORE INSERT ON events FOR EACH ROW EXECUTE FUNCTION skip_copy_insert();",
        &routine_session,
    );
    defer skip_copy_trigger.deinit(alloc);

    const writes_before_skip = writes.calls;
    var skipped_copy_result = try server.executeBulkSqlWithSession(
        "COPY events (id, status) FROM STDIN WITH (FORMAT csv, HEADER true);",
        "id,status\nu_skipped,Ready\n",
        session,
        &identity,
    );
    defer skipped_copy_result.deinit(alloc);
    switch (skipped_copy_result) {
        .import_rows => |copied| try std.testing.expectEqual(@as(usize, 0), copied.writes.len),
        .export_stdout, .export_file => return error.TestUnexpectedResult,
    }
    try std.testing.expectEqual(writes_before_skip, writes.calls);
    try std.testing.expectEqual(@as(usize, 13), audit.count);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoAuditAction.copy_from, audit.events[12].action);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoOperation.import_rows, audit.events[12].operation);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoNativeRoute.rows_batch, audit.events[12].native_route);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoStream.stdin, audit.events[12].stream);
    try std.testing.expectEqual(usermgr.PermissionType.write, audit.events[12].required_permission);
    try std.testing.expectEqual(@as(usize, 0), audit.events[12].row_count);

    try std.testing.expectError(
        error.InvalidRowsRequest,
        server.executeBulkSqlWithSession(
            "COPY events (id, status) FROM STDIN WITH (FORMAT csv);",
            null,
            session,
            &identity,
        ),
    );
    try std.testing.expectError(
        error.InvalidRowsRequest,
        server.executeBulkSqlWithSession(
            "COPY events (id, status) TO STDOUT WITH (FORMAT csv);",
            "unexpected stdin",
            session,
            &identity,
        ),
    );

    try std.testing.expectError(
        error.UnsupportedSqlShape,
        server.executeBulkSqlCopyFromStdinWithSession(
            "COPY events TO STDOUT WITH (FORMAT csv);",
            "",
            session,
            &identity,
        ),
    );
    try std.testing.expectError(
        error.UnsupportedSqlShape,
        server.executeBulkSqlCopyToStdoutWithSession(
            "COPY events (id, status) FROM STDIN WITH (FORMAT csv);",
            session,
            &identity,
        ),
    );

    var read_only_permission = try usermgr.Permission.initOwned(alloc, .table, "tenant_ops.analytics.events", .read);
    var read_only_permission_transferred = false;
    errdefer if (!read_only_permission_transferred) read_only_permission.deinit(alloc);
    const read_only_permissions = try alloc.alloc(usermgr.Permission, 1);
    var read_only_permissions_transferred = false;
    errdefer if (!read_only_permissions_transferred) alloc.free(read_only_permissions);
    read_only_permissions[0] = read_only_permission;
    read_only_permission_transferred = true;
    const read_only_username = try alloc.dupe(u8, "read_only_bulk");
    var read_only_username_transferred = false;
    errdefer if (!read_only_username_transferred) alloc.free(read_only_username);
    var read_only_identity = AuthenticatedIdentity{
        .username = read_only_username,
        .permissions = read_only_permissions,
    };
    read_only_username_transferred = true;
    read_only_permissions_transferred = true;
    defer read_only_identity.deinit(alloc);

    const writes_before_read_only_denial = writes.calls;
    try std.testing.expectError(
        error.PermissionDenied,
        server.executeBulkSqlCopyFromStdinWithSession(
            "COPY events (id, status) FROM STDIN WITH (FORMAT csv, HEADER true);",
            "id,status\nu_denied,Ready\n",
            session,
            &read_only_identity,
        ),
    );
    try std.testing.expectEqual(writes_before_read_only_denial, writes.calls);
    try std.testing.expectEqual(@as(usize, 14), audit.count);
    try std.testing.expectEqual(SqlBulkIoAuditOutcome.denied, audit.events[13].outcome);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoAuditAction.copy_from, audit.events[13].action);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoOperation.import_rows, audit.events[13].operation);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoNativeRoute.rows_batch, audit.events[13].native_route);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoStream.stdin, audit.events[13].stream);
    try std.testing.expectEqual(usermgr.PermissionType.write, audit.events[13].required_permission);
    try std.testing.expectEqualStrings("read_only_bulk", audit.events[13].authenticated_subject orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings("PermissionDenied", audit.events[13].error_name orelse return error.TestUnexpectedResult);
    try std.testing.expectEqual(@as(usize, 0), audit.events[13].row_count);

    var write_only_permission = try usermgr.Permission.initOwned(alloc, .table, "tenant_ops.analytics.events", .write);
    var write_only_permission_transferred = false;
    errdefer if (!write_only_permission_transferred) write_only_permission.deinit(alloc);
    const write_only_permissions = try alloc.alloc(usermgr.Permission, 1);
    var write_only_permissions_transferred = false;
    errdefer if (!write_only_permissions_transferred) alloc.free(write_only_permissions);
    write_only_permissions[0] = write_only_permission;
    write_only_permission_transferred = true;
    const write_only_username = try alloc.dupe(u8, "write_only_bulk");
    var write_only_username_transferred = false;
    errdefer if (!write_only_username_transferred) alloc.free(write_only_username);
    var write_only_identity = AuthenticatedIdentity{
        .username = write_only_username,
        .permissions = write_only_permissions,
    };
    write_only_username_transferred = true;
    write_only_permissions_transferred = true;
    defer write_only_identity.deinit(alloc);

    const reads_before_write_only_denial = reads.calls;
    try std.testing.expectError(
        error.PermissionDenied,
        server.executeBulkSqlCopyToStdoutWithSession(
            "COPY events (id, status) TO STDOUT WITH (FORMAT csv, HEADER true);",
            session,
            &write_only_identity,
        ),
    );
    try std.testing.expectEqual(reads_before_write_only_denial, reads.calls);
    try std.testing.expectEqual(@as(usize, 15), audit.count);
    try std.testing.expectEqual(SqlBulkIoAuditOutcome.denied, audit.events[14].outcome);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoAuditAction.copy_to, audit.events[14].action);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoOperation.export_rows, audit.events[14].operation);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoNativeRoute.rows_query, audit.events[14].native_route);
    try std.testing.expectEqual(sql_adapter.BulkSqlIoStream.stdout, audit.events[14].stream);
    try std.testing.expectEqual(usermgr.PermissionType.read, audit.events[14].required_permission);
    try std.testing.expectEqualStrings("write_only_bulk", audit.events[14].authenticated_subject orelse return error.TestUnexpectedResult);
    try std.testing.expectEqualStrings("PermissionDenied", audit.events[14].error_name orelse return error.TestUnexpectedResult);
    try std.testing.expectEqual(@as(usize, 0), audit.events[14].row_count);
}

test "api http server serves api key and row filter routes" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }
    };

    var auth = try initTestAuthManager(alloc);
    try bindTestAuthManager(alloc, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();

    var admin_permission = [_]usermgr.Permission{
        try usermgr.Permission.initOwned(alloc, .@"*", "*", .admin),
    };
    defer admin_permission[0].deinit(alloc);
    var admin = try auth.manager.createUser("admin", "admin", &admin_permission);
    defer admin.deinit(alloc);

    var alice_permission = [_]usermgr.Permission{
        try usermgr.Permission.initOwned(alloc, .table, "docs", .read),
        try usermgr.Permission.initOwned(alloc, .table, "reports", .read),
    };
    defer {
        for (&alice_permission) |*permission| permission.deinit(alloc);
    }
    var alice = try auth.manager.createUser("alice", "secret", &alice_permission);
    defer alice.deinit(alloc);

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{
        .auth_enabled = true,
        .user_manager = &auth.manager,
    }, source.iface(), null, null);

    const admin_auth = try encodeBasicAuthorization(alloc, "admin", "admin");
    defer alloc.free(admin_auth);

    var api_key_resp = try server.handle(.{
        .method = .POST,
        .uri = "/auth/v1/users/alice/api-keys",
        .authorization = admin_auth,
        .body = "{\"name\":\"ci\",\"permissions\":[{\"resource\":\"docs\",\"resource_type\":\"table\",\"type\":\"read\"}],\"row_filter\":{\"docs\":{\"term\":{\"tier\":\"gold\"}}},\"expires_in\":\"1h\"}",
    });
    defer api_key_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 201), api_key_resp.status);
    try std.testing.expectEqualStrings("application/json", api_key_resp.content_type.?);

    var created = try std.json.parseFromSlice(usermgr_openapi.ApiKeyWithSecret, alloc, api_key_resp.body, .{});
    defer created.deinit();
    try std.testing.expect(created.value.key_secret.len > 0);
    try std.testing.expect(created.value.encoded.len > 0);

    var list_api_keys_resp = try server.handle(.{
        .method = .GET,
        .uri = "/auth/v1/users/alice/api-keys",
        .authorization = admin_auth,
    });
    defer list_api_keys_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), list_api_keys_resp.status);
    try std.testing.expectEqualStrings("application/json", list_api_keys_resp.content_type.?);

    var api_keys = try std.json.parseFromSlice([]usermgr_openapi.ApiKey, alloc, list_api_keys_resp.body, .{});
    defer api_keys.deinit();
    try std.testing.expectEqual(@as(usize, 1), api_keys.value.len);
    const created_key_id = created.value.key_id;
    const created_encoded = created.value.encoded;
    try std.testing.expectEqualStrings(created_key_id, api_keys.value[0].key_id);

    const bearer_auth = try std.fmt.allocPrint(alloc, "Bearer {s}", .{created_encoded});
    defer alloc.free(bearer_auth);
    var bearer_status = try server.handle(.{
        .method = .GET,
        .uri = routes.Routes.status,
        .authorization = bearer_auth,
    });
    defer bearer_status.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), bearer_status.status);

    var put_subject_row_filter_resp = try server.handle(.{
        .method = .PUT,
        .uri = "/auth/v1/subjects/role:tenant_reader/row-filters/docs",
        .authorization = admin_auth,
        .body = "{\"term\":{\"tenant_id\":{\"$auth\":\"metadata.tenant_id\"}}}",
    });
    defer put_subject_row_filter_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), put_subject_row_filter_resp.status);
    try std.testing.expectEqualStrings("application/json", put_subject_row_filter_resp.content_type.?);

    var subject_row_filters_resp = try server.handle(.{
        .method = .GET,
        .uri = "/auth/v1/subjects/role:tenant_reader/row-filters",
        .authorization = admin_auth,
    });
    defer subject_row_filters_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), subject_row_filters_resp.status);
    try std.testing.expectEqualStrings("application/json", subject_row_filters_resp.content_type.?);
    var subject_row_filters = try std.json.parseFromSlice([]usermgr_openapi.RowFilterEntry, alloc, subject_row_filters_resp.body, .{});
    defer subject_row_filters.deinit();
    try std.testing.expectEqual(@as(usize, 1), subject_row_filters.value.len);
    try std.testing.expectEqualStrings("docs", subject_row_filters.value[0].table);

    var put_row_filter_resp = try server.handle(.{
        .method = .PUT,
        .uri = "/auth/v1/users/alice/row-filters/docs",
        .authorization = admin_auth,
        .body = "{\"term\":{\"department\":\"eng\"}}",
    });
    defer put_row_filter_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), put_row_filter_resp.status);
    try std.testing.expectEqualStrings("application/json", put_row_filter_resp.content_type.?);
    var created_row_filter = try std.json.parseFromSlice(usermgr_openapi.RowFilterEntry, alloc, put_row_filter_resp.body, .{});
    defer created_row_filter.deinit();
    try std.testing.expectEqualStrings("docs", created_row_filter.value.table);

    var row_filters_resp = try server.handle(.{
        .method = .GET,
        .uri = "/auth/v1/users/alice/row-filters",
        .authorization = admin_auth,
    });
    defer row_filters_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), row_filters_resp.status);
    try std.testing.expectEqualStrings("application/json", row_filters_resp.content_type.?);

    var row_filters = try std.json.parseFromSlice([]usermgr_openapi.RowFilterEntry, alloc, row_filters_resp.body, .{});
    defer row_filters.deinit();
    try std.testing.expectEqual(@as(usize, 1), row_filters.value.len);
    try std.testing.expectEqualStrings("docs", row_filters.value[0].table);

    var single_row_filter_resp = try server.handle(.{
        .method = .GET,
        .uri = "/auth/v1/users/alice/row-filters/docs",
        .authorization = admin_auth,
    });
    defer single_row_filter_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), single_row_filter_resp.status);
    try std.testing.expectEqualStrings("application/json", single_row_filter_resp.content_type.?);
    var single_row_filter = try std.json.parseFromSlice(usermgr_openapi.RowFilterEntry, alloc, single_row_filter_resp.body, .{});
    defer single_row_filter.deinit();
    try std.testing.expectEqualStrings("docs", single_row_filter.value.table);

    var delete_row_filter_resp = try server.handle(.{
        .method = .DELETE,
        .uri = "/auth/v1/users/alice/row-filters/docs",
        .authorization = admin_auth,
    });
    defer delete_row_filter_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 204), delete_row_filter_resp.status);

    var delete_subject_row_filter_resp = try server.handle(.{
        .method = .DELETE,
        .uri = "/auth/v1/subjects/role:tenant_reader/row-filters/docs",
        .authorization = admin_auth,
    });
    defer delete_subject_row_filter_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 204), delete_subject_row_filter_resp.status);

    var delete_permission_resp = try server.handle(.{
        .method = .DELETE,
        .uri = "/auth/v1/users/alice/permissions?resource=docs&resourceType=table",
        .authorization = admin_auth,
    });
    defer delete_permission_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 204), delete_permission_resp.status);

    var empty_permissions_resp = try server.handle(.{
        .method = .GET,
        .uri = "/auth/v1/users/alice/permissions",
        .authorization = admin_auth,
    });
    defer empty_permissions_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), empty_permissions_resp.status);
    try std.testing.expectEqualStrings("application/json", empty_permissions_resp.content_type.?);

    var empty_permissions = try std.json.parseFromSlice([]usermgr_openapi.Permission, alloc, empty_permissions_resp.body, .{});
    defer empty_permissions.deinit();
    try std.testing.expectEqual(@as(usize, 1), empty_permissions.value.len);
    try std.testing.expectEqualStrings("reports", empty_permissions.value[0].resource);

    const delete_api_key_uri = try std.fmt.allocPrint(alloc, "/auth/v1/users/alice/api-keys/{s}", .{created_key_id});
    defer alloc.free(delete_api_key_uri);
    var delete_api_key_resp = try server.handle(.{
        .method = .DELETE,
        .uri = delete_api_key_uri,
        .authorization = admin_auth,
    });
    defer delete_api_key_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 204), delete_api_key_resp.status);

    var empty_api_keys_resp = try server.handle(.{
        .method = .GET,
        .uri = "/auth/v1/users/alice/api-keys",
        .authorization = admin_auth,
    });
    defer empty_api_keys_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), empty_api_keys_resp.status);
    try std.testing.expectEqualStrings("application/json", empty_api_keys_resp.content_type.?);

    var empty_api_keys = try std.json.parseFromSlice([]usermgr_openapi.ApiKey, alloc, empty_api_keys_resp.body, .{});
    defer empty_api_keys.deinit();
    try std.testing.expectEqual(@as(usize, 0), empty_api_keys.value.len);
}

test "api http server returns json user auth errors" {
    const alloc = std.testing.allocator;
    const ErrorResponse = struct {
        @"error": []const u8,
    };
    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 1,
            };
        }
    };

    var auth = try initTestAuthManager(alloc);
    try bindTestAuthManager(alloc, &auth);
    defer auth.manager.deinit();
    defer auth.policy_store.deinit();
    defer auth.store.deinit();

    var admin_permission = [_]usermgr.Permission{
        try usermgr.Permission.initOwned(alloc, .@"*", "*", .admin),
    };
    defer admin_permission[0].deinit(alloc);
    var admin = try auth.manager.createUser("admin", "admin", &admin_permission);
    defer admin.deinit(alloc);

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{
        .auth_enabled = true,
        .user_manager = &auth.manager,
    }, source.iface(), null, null);

    const admin_auth = try encodeBasicAuthorization(alloc, "admin", "admin");
    defer alloc.free(admin_auth);

    var bad_delete_resp = try server.handle(.{
        .method = .DELETE,
        .uri = "/auth/v1/users/alice/permissions?resource=docs&resource_type=table",
        .authorization = admin_auth,
    });
    defer bad_delete_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 400), bad_delete_resp.status);
    try std.testing.expectEqualStrings("application/json", bad_delete_resp.content_type.?);

    var bad_delete_body = try std.json.parseFromSlice(ErrorResponse, alloc, bad_delete_resp.body, .{});
    defer bad_delete_body.deinit();
    try std.testing.expectEqualStrings("missing resourceType", bad_delete_body.value.@"error");

    var bad_row_filter_resp = try server.handle(.{
        .method = .PUT,
        .uri = "/auth/v1/users/alice/row-filters/docs",
        .authorization = admin_auth,
        .body = "[]",
    });
    defer bad_row_filter_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 400), bad_row_filter_resp.status);
    try std.testing.expectEqualStrings("application/json", bad_row_filter_resp.content_type.?);

    var bad_row_filter_body = try std.json.parseFromSlice(ErrorResponse, alloc, bad_row_filter_resp.body, .{});
    defer bad_row_filter_body.deinit();
    try std.testing.expectEqualStrings("invalid row filter", bad_row_filter_body.value.@"error");
}

test "api http server rejects secret writes without a local secret store" {
    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .status = status,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{
                .metadata_group_id = 77,
                .metrics = .{},
                .projected_stores = 2,
            };
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(std.testing.allocator, .{}, source.iface(), null, null);
    var resp = try server.handle(.{
        .method = .PUT,
        .uri = "/secrets/openai.api_key",
        .body = "{\"value\":\"sk-test\"}",
    });
    defer resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 503), resp.status);
    try std.testing.expectEqualStrings("text/plain", resp.content_type.?);
    try std.testing.expectEqualStrings("secret management not available in multi-node mode", resp.body);
}

