        .body = "{\"table\":\"docs_multi\",\"intent\":\"find raft architecture\",\"mode\":\"tree\",\"interactive\":true,\"max_user_clarifications\":1,\"decisions\":[{\"question_id\":\"select_tree_index\",\"answer\":\"topic_graph\"}]}",
