            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn adminSnapshot(_: *anyopaque) !metadata_api.AdminSnapshot {
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = @constCast((&[_]metadata_table_manager.TableRecord{.{
                    .table_id = 1,
                    .name = "docs",
                    .schema_json = "{\"version\":1}",
                    .read_schema_json = "{\"version\":0}",
                    .indexes_json = "{\"full_text_index_v0\":{\"type\":\"full_text\"},\"full_text_index_v1\":{\"type\":\"full_text\"}}",
                    .placement_role = "data",
                }})[0..]),
                .ranges = @constCast((&[_]metadata_table_manager.RangeRecord{.{ .group_id = 10, .table_id = 1, .start_key = "doc:a", .end_key = "doc:z" }})[0..]),
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    const FakeReads = struct {
        fn source(_: *@This()) table_reads.TableReadSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .lookup = lookup,
                    .scan = scan,
                    .query = query,
                },
            };
        }

        fn lookup(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8, _: db_mod.types.LookupOptions, _: raft_mod.ReadConsistency) !?table_reads.LookupResponse {
            return null;
        }

        fn scan(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8, _: []const u8, _: db_mod.types.ScanOptions, _: raft_mod.ReadConsistency) !?table_reads.ScanResponse {
            return null;
        }

        fn query(_: *anyopaque, inner_alloc: std.mem.Allocator, table_name: []const u8, req: db_mod.types.SearchRequest, _: raft_mod.ReadConsistency) !?query_api.QueryResponse {
            try std.testing.expectEqualStrings("docs", table_name);
            try std.testing.expect(req.index_name != null);
            try std.testing.expectEqualStrings("full_text_index_v0", req.index_name.?);
            return .{
                .json = try inner_alloc.dupe(u8, "{\"responses\":[]}"),
            };
        }
    };

    var source = FakeSource{};
    var reads = FakeReads{};
    var server = ApiHttpServer.init(std.testing.allocator, .{}, source.iface(), reads.source(), null);
    const query_body = try test_contract_helpers.encodeMatchQueryRequest(std.testing.allocator, "body", "hello", &.{}, 5);
    defer std.testing.allocator.free(query_body);

    var resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/query",
        .content_type = "application/json",
        .body = query_body,
    });
    defer resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), resp.status);
    try std.testing.expectEqualStrings("application/json", resp.content_type.?);
    var parsed = try std.json.parseFromSlice(metadata_openapi.QueryResponses, std.testing.allocator, resp.body, .{});
    defer parsed.deinit();
    try std.testing.expectEqual(@as(usize, 0), parsed.value.responses.?.len);
}

test "api http server serves table batch writes" {
    const alloc = std.testing.allocator;
    const StoredTitle = struct {
        title: []const u8,
    };
    const path = try uniqueTestTmpPathAlloc(alloc, "antfly-api-http-batch");
    defer alloc.free(path);
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch {};

    var db = try db_mod.DB.open(alloc, path, .{});
    defer {
        db.close();
        std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch {};
    }

    var table_source = table_writes.BoundTableWriteSource.init("docs", &db);

    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .status = status,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(std.testing.allocator, .{}, source.iface(), null, table_source.source());
    const batch_body = try test_contract_helpers.normalizeBatchRequest(std.testing.allocator, "{\"inserts\":{\"doc:a\":{\"title\":\"alpha\"}},\"deletes\":[\"doc:gone\"]}");
    defer std.testing.allocator.free(batch_body);
    var resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/batch",
        .content_type = "application/json",
        .body = batch_body,
    });
    defer resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 201), resp.status);
    try std.testing.expectEqualStrings("application/json", resp.content_type.?);
    var parsed_batch = try std.json.parseFromSlice(metadata_openapi.BatchResponse, std.testing.allocator, resp.body, .{});
    defer parsed_batch.deinit();
    try std.testing.expectEqual(@as(i64, 1), parsed_batch.value.inserted.?);
    try std.testing.expectEqual(@as(i64, 1), parsed_batch.value.deleted.?);

    var lookup = (try db.lookup(alloc, "doc:a", .{})).?;
    defer lookup.deinit(alloc);
    var parsed_stored = try std.json.parseFromSlice(StoredTitle, alloc, lookup.json, .{
        .allocate = .alloc_always,
        .ignore_unknown_fields = true,
    });
    defer parsed_stored.deinit();
    const stored = parsed_stored.value;
    try std.testing.expectEqualStrings("alpha", stored.title);

    var compact_batch: std.Io.Writer.Allocating = .init(alloc);
    defer compact_batch.deinit();
    const compact_writer = &compact_batch.writer;
    try compact_writer.writeAll("{\"inserts\":{");
    for (0..500) |i| {
        if (i != 0) try compact_writer.writeByte(',');
        try compact_writer.print(
            "\"key:{d}\":{{\"id\":{d},\"metadata\":{{\"source\":\"vdbbench\",\"ordinal\":{d}}},\"vec_data\":[0.1,0.2,0.3],\"_embeddings\":{{\"vec\":[0.1,0.2,0.3]}}}}",
            .{ i, i, i },
        );
    }
    try compact_writer.writeAll("},\"sync_level\":\"write\"}");
    var compact_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/batch",
        .content_type = "application/json",
        .body = compact_batch.written(),
    });
    defer compact_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 201), compact_resp.status);
    var parsed_compact = try std.json.parseFromSlice(metadata_openapi.BatchResponse, std.testing.allocator, compact_resp.body, .{});
    defer parsed_compact.deinit();
    try std.testing.expectEqual(@as(i64, 500), parsed_compact.value.inserted.?);

    var compact_lookup = (try db.lookup(alloc, "key:0", .{})).?;
    defer compact_lookup.deinit(alloc);
    try std.testing.expect(std.mem.indexOf(u8, compact_lookup.json, "\"vec_data\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, compact_lookup.json, "_embeddings") == null);
}

test "api http server exposes relational foreign key integrity repair" {
    const alloc = std.testing.allocator;
    const path = try uniqueTestTmpPathAlloc(alloc, "antfly-api-http-fk-integrity");
    defer alloc.free(path);
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch {};

    var db = try db_mod.DB.open(alloc, path, .{});
    defer {
        db.close();
        std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch {};
    }
    try db.applyTableSchemaJson(
        alloc,
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"customer_id":{"type":"keyword"},"account_id":{"type":"keyword"},"region_id":{"type":"keyword"}},"additionalProperties":false}}},"foreign_keys":[{"name":"orders_customer_id_fkey","columns":["customer_id"],"references":{"table":"customers","columns":["_id"]},"on_delete":"restrict"},{"name":"orders_account_id_fkey","columns":["account_id"],"references":{"table":"accounts","columns":["_id"]},"on_delete":"restrict"},{"name":"orders_region_id_fkey","columns":["region_id"],"references":{"table":"regions","columns":["_id"]},"on_delete":"restrict","validation_state":"unvalidated"}]}
    ,
        .{},
    );
    try db.batch(.{
        .writes = &.{
            .{ .key = "customer:a", .value = "{\"_type\":\"customers\"}" },
            .{ .key = "account:a", .value = "{\"_type\":\"accounts\"}" },
            .{ .key = "region:a", .value = "{\"_type\":\"regions\"}" },
            .{ .key = "order:1", .value = "{\"customer_id\":\"customer:a\",\"account_id\":\"account:a\",\"region_id\":\"region:a\"}" },
        },
        .sync_level = .write,
    });

    const ref_key = try db_mod.internal_keys.relationalForeignKeyRefKeyAlloc(alloc, "orders_customer_id_fkey", "customers", "customer:a", "row", "order:1");
    defer alloc.free(ref_key);
    try db.core.store.delete(ref_key);

    var table_source = table_writes.BoundTableWriteSource.init("docs", &db);

    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .status = status,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }
    };

    const IntegrityResponse = struct {
        job_id: ?[]const u8 = null,
        valid: bool,
        complete: bool = true,
        report: struct {
            missing_ref_rows: u64,
            repaired_ref_rows: u64,
        },
        progress: []const struct {
            group_id: u64,
            mode: []const u8,
            constraint_name: ?[]const u8 = null,
            lower_doc_key: []const u8,
            upper_doc_key: []const u8,
            completed: bool,
            valid: bool,
            report: struct {
                missing_ref_rows: u64,
                repaired_ref_rows: u64,
            },
        },
        work_units: []const struct {
            group_id: u64,
            phase: []const u8,
            planned_action: []const u8,
            constraint_name: ?[]const u8 = null,
            lower_doc_key: []const u8,
            upper_doc_key: []const u8,
        } = &.{},
        work_statuses: []const struct {
            group_id: u64,
            phase: []const u8,
            planned_action: []const u8,
            constraint_name: ?[]const u8 = null,
            lower_doc_key: []const u8,
            upper_doc_key: []const u8,
            claim_key: []const u8,
            state: []const u8,
            claim_worker_id: ?[]const u8 = null,
            claim_lease_until_ns: ?u64 = null,
            progress_updated_at_ns: ?u64 = null,
        } = &.{},
        work_claims: []const struct {
            group_id: u64,
            claim_key: []const u8,
            worker_id: []const u8,
            phase: []const u8,
            planned_action: []const u8,
            constraint_name: ?[]const u8 = null,
            lower_doc_key: []const u8,
            upper_doc_key: []const u8,
            lease_until_ns: u64,
            attempts: u32,
        } = &.{},
        violations: []const struct {
            kind: []const u8,
            constraint_name: []const u8,
            child_key: []const u8,
            parent_key: []const u8,
        },
    };
    const DeleteExplainResponse = struct {
        valid: bool,
        delete_plan: struct {
            exists: bool,
            allowed: bool,
            block_reason: []const u8,
            planned_set_null_updates: u64,
            planned_cascade_deletes: u64,
        },
    };
    const ActionJobResponse = struct {
        complete: bool,
        groups: []const struct {
            group_id: u64,
            job_id: []const u8,
            action: []const u8,
            worker_id: []const u8,
            constraint_name: []const u8,
            parent_table: []const u8,
            parent_key: []const u8,
            page_limit: usize,
            status: []const u8,
            claimed_at_ns: u64,
            lease_until_ns: u64,
            attempts: u32,
            completed: bool,
            applied_children: u64,
            failure_count: u64 = 0,
            first_failed_at_ns: ?u64 = null,
            last_failed_at_ns: ?u64 = null,
            requeue_count: u64 = 0,
            last_requeued_at_ns: ?u64 = null,
            cascade_depth: u32 = 0,
            cascade_max_depth: u32 = 64,
            next_child_table: ?[]const u8 = null,
            next_child_key: ?[]const u8 = null,
            last_error: ?[]const u8 = null,
        },
    };
    const ActionScheduleResponse = struct {
        group_id: u64,
        schedule_id: []const u8,
        action_job_id: []const u8,
        action: []const u8,
        worker_id: []const u8,
        constraint_name: []const u8,
        parent_table: []const u8,
        parent_key: []const u8,
        page_limit: usize,
        status: []const u8,
        completed: bool,
        scheduled_groups: u64 = 0,
        cascade_depth: u32 = 0,
        cascade_max_depth: u32 = 64,
        requeue_count: u64 = 0,
        last_requeued_at_ns: ?u64 = null,
        last_error: ?[]const u8 = null,
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, table_source.source());

    const scheduled_action = try db.scheduleForeignKeyActionJobAt(
        "fk-action:http-requeue",
        "set_null",
        "worker:http-action-scheduler",
        "orders_customer_id_fkey",
        "customers",
        "customer:a",
        8,
        14_000,
    );
    defer db.freeForeignKeyActionJobRecord(scheduled_action);
    const claimed_action = try db.claimForeignKeyActionJobPageAt(
        "fk-action:http-requeue",
        "set_null",
        "worker:http-action-failed",
        "orders_customer_id_fkey",
        "customers",
        "customer:a",
        8,
        60_000,
        14_100,
    );
    defer db.freeForeignKeyActionJobRecord(claimed_action);
    const failed_action = try db.finishClaimedForeignKeyActionJobPageAt(
        claimed_action,
        2,
        false,
        "row",
        "order:action:cursor",
        "OperatorPaused",
        14_200,
    );
    defer db.freeForeignKeyActionJobRecord(failed_action);
    try std.testing.expectEqualStrings("invalid", failed_action.status);

    var requeue_action_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/foreign-key-integrity",
        .content_type = "application/json",
        .body = "{\"action\":\"REQUEUE ACTION JOB\",\"job_id\":\"fk-action:http-requeue\",\"action_job_action\":\"SET NULL\",\"worker_id\":\"worker:http-action-retry\",\"constraint_name\":\"orders_customer_id_fkey\",\"parent_table\":\"customers\",\"parent_key\":\"customer:a\",\"page_limit\":4}",
    });
    defer requeue_action_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), requeue_action_resp.status);
    var requeue_action_body = try std.json.parseFromSlice(ActionJobResponse, alloc, requeue_action_resp.body, .{ .ignore_unknown_fields = true });
    defer requeue_action_body.deinit();
    try std.testing.expect(!requeue_action_body.value.complete);
    try std.testing.expectEqual(@as(usize, 1), requeue_action_body.value.groups.len);
    try std.testing.expectEqualStrings("fk-action:http-requeue", requeue_action_body.value.groups[0].job_id);
    try std.testing.expectEqualStrings("set_null", requeue_action_body.value.groups[0].action);
    try std.testing.expectEqualStrings("worker:http-action-retry", requeue_action_body.value.groups[0].worker_id);
    try std.testing.expectEqualStrings("orders_customer_id_fkey", requeue_action_body.value.groups[0].constraint_name);
    try std.testing.expectEqualStrings("customers", requeue_action_body.value.groups[0].parent_table);
    try std.testing.expectEqualStrings("customer:a", requeue_action_body.value.groups[0].parent_key);
    try std.testing.expectEqual(@as(usize, 4), requeue_action_body.value.groups[0].page_limit);
    try std.testing.expectEqualStrings("pending", requeue_action_body.value.groups[0].status);
    try std.testing.expectEqual(@as(u64, 0), requeue_action_body.value.groups[0].claimed_at_ns);
    try std.testing.expectEqual(@as(u64, 0), requeue_action_body.value.groups[0].lease_until_ns);
    try std.testing.expectEqual(@as(u32, 1), requeue_action_body.value.groups[0].attempts);
    try std.testing.expect(!requeue_action_body.value.groups[0].completed);
    try std.testing.expectEqual(@as(u64, 2), requeue_action_body.value.groups[0].applied_children);
    try std.testing.expectEqual(@as(u64, 1), requeue_action_body.value.groups[0].failure_count);
    try std.testing.expectEqual(@as(u64, 14_200), requeue_action_body.value.groups[0].first_failed_at_ns.?);
    try std.testing.expectEqual(@as(u64, 14_200), requeue_action_body.value.groups[0].last_failed_at_ns.?);
    try std.testing.expectEqual(@as(u64, 1), requeue_action_body.value.groups[0].requeue_count);
    try std.testing.expect(requeue_action_body.value.groups[0].last_requeued_at_ns != null);
    try std.testing.expectEqual(@as(u32, 0), requeue_action_body.value.groups[0].cascade_depth);
    try std.testing.expectEqual(@as(u32, 64), requeue_action_body.value.groups[0].cascade_max_depth);
    try std.testing.expectEqualStrings("row", requeue_action_body.value.groups[0].next_child_table.?);
    try std.testing.expectEqualStrings("order:action:cursor", requeue_action_body.value.groups[0].next_child_key.?);
    try std.testing.expect(requeue_action_body.value.groups[0].last_error == null);

    const scheduled_action_schedule = try db.scheduleForeignKeyActionScheduleWithUpdatedParentKeyAt(
        "fk-action-schedule:http-requeue",
        "fk-action:http-schedule-requeue",
        "set_null",
        "worker:http-schedule-seed",
        "orders_customer_id_fkey",
        "customers",
        "customer:a",
        null,
        8,
        15_000,
    );
    defer db.freeForeignKeyActionScheduleRecord(scheduled_action_schedule);
    const failed_action_schedule = try db.markForeignKeyActionScheduleSeededAt(
        "fk-action-schedule:http-requeue",
        0,
        15_100,
    );
    defer db.freeForeignKeyActionScheduleRecord(failed_action_schedule);
    try std.testing.expectEqualStrings("invalid", failed_action_schedule.status);

    var requeue_schedule_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/foreign-key-integrity",
        .content_type = "application/json",
        .body = "{\"action\":\"REQUEUE ACTION SCHEDULE\",\"schedule_id\":\"fk-action-schedule:http-requeue\",\"action_schedule_action_job_id\":\"fk-action:http-schedule-requeue\",\"action_schedule_action\":\"ON DELETE SET NULL\",\"worker_id\":\"worker:http-schedule-retry\",\"constraint_name\":\"orders_customer_id_fkey\",\"parent_table\":\"customers\",\"parent_key\":\"customer:a\",\"page_limit\":6}",
    });
    defer requeue_schedule_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), requeue_schedule_resp.status);
    var requeue_schedule_body = try std.json.parseFromSlice(ActionScheduleResponse, alloc, requeue_schedule_resp.body, .{ .ignore_unknown_fields = true });
    defer requeue_schedule_body.deinit();
    try std.testing.expectEqual(@as(u64, 0), requeue_schedule_body.value.group_id);
    try std.testing.expectEqualStrings("fk-action-schedule:http-requeue", requeue_schedule_body.value.schedule_id);
    try std.testing.expectEqualStrings("fk-action:http-schedule-requeue", requeue_schedule_body.value.action_job_id);
    try std.testing.expectEqualStrings("set_null", requeue_schedule_body.value.action);
    try std.testing.expectEqualStrings("worker:http-schedule-retry", requeue_schedule_body.value.worker_id);
    try std.testing.expectEqualStrings("orders_customer_id_fkey", requeue_schedule_body.value.constraint_name);
    try std.testing.expectEqualStrings("customers", requeue_schedule_body.value.parent_table);
    try std.testing.expectEqualStrings("customer:a", requeue_schedule_body.value.parent_key);
    try std.testing.expectEqual(@as(usize, 6), requeue_schedule_body.value.page_limit);
    try std.testing.expectEqualStrings("pending", requeue_schedule_body.value.status);
    try std.testing.expect(!requeue_schedule_body.value.completed);
    try std.testing.expectEqual(@as(u64, 0), requeue_schedule_body.value.scheduled_groups);
    try std.testing.expectEqual(@as(u64, 1), requeue_schedule_body.value.requeue_count);
    try std.testing.expect(requeue_schedule_body.value.last_requeued_at_ns != null);
    try std.testing.expect(requeue_schedule_body.value.last_error == null);

    var missing_action_schedule_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/foreign-key-integrity",
        .content_type = "application/json",
        .body = "{\"action\":\"requeue_action_schedule\",\"schedule_id\":\"fk-action-schedule:missing\",\"action_schedule_action_job_id\":\"fk-action:http-schedule-requeue\",\"action_schedule_action\":\"set_null\",\"worker_id\":\"worker:http-schedule-retry\",\"constraint_name\":\"orders_customer_id_fkey\",\"parent_table\":\"customers\",\"parent_key\":\"customer:a\"}",
    });
    defer missing_action_schedule_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 404), missing_action_schedule_resp.status);
    try std.testing.expectEqualStrings("foreign key action schedule not found", missing_action_schedule_resp.body);

    var missing_action_job_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/foreign-key-integrity",
        .content_type = "application/json",
        .body = "{\"action\":\"requeue_action_job\",\"job_id\":\"fk-action:missing\",\"action_job_action\":\"set_null\",\"worker_id\":\"worker:http-action-retry\",\"constraint_name\":\"orders_customer_id_fkey\",\"parent_table\":\"customers\",\"parent_key\":\"customer:a\"}",
    });
    defer missing_action_job_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 404), missing_action_job_resp.status);
    try std.testing.expectEqualStrings("foreign key action job not found", missing_action_job_resp.body);

    var plan_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/foreign-key-integrity",
        .content_type = "application/json",
        .body = "{\"action\":\"plan\",\"constraint_name\":\"orders_customer_id_fkey\"}",
    });
    defer plan_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), plan_resp.status);
    var plan_body = try std.json.parseFromSlice(IntegrityResponse, alloc, plan_resp.body, .{ .ignore_unknown_fields = true });
    defer plan_body.deinit();
    try std.testing.expect(plan_body.value.valid);
    try std.testing.expectEqual(@as(u64, 0), plan_body.value.report.missing_ref_rows);
    try std.testing.expectEqual(@as(usize, 0), plan_body.value.progress.len);
    try std.testing.expectEqual(@as(usize, 1), plan_body.value.work_units.len);
    try std.testing.expectEqual(@as(u64, 0), plan_body.value.work_units[0].group_id);
