test "api http server exposes relational unique integrity repair" {
    const alloc = std.testing.allocator;
    const path = try uniqueTestTmpPathAlloc(alloc, "antfly-api-http-unique-integrity");
    defer alloc.free(path);
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch {};

    var db = try db_mod.DB.open(alloc, path, .{});
    defer {
        db.close();
        std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch {};
    }
    try db.applyTableSchemaJson(
        alloc,
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"email":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"unique_constraints":[{"name":"users_email_key","columns":["email"]}]}
    ,
        .{},
    );
    try db.batch(.{
        .writes = &.{
            .{ .key = "user:ada", .value = "{\"id\":\"user:ada\",\"email\":\"ada@example.test\"}" },
            .{ .key = "user:grace", .value = "{\"id\":\"user:grace\",\"email\":\"grace@example.test\"}" },
            .{ .key = "user:stale", .value = "{\"id\":\"user:stale\",\"email\":\"stale@example.test\"}" },
        },
        .sync_level = .write,
    });

    const runtime_schema = db.core.schema orelse return error.TestUnexpectedResult;
    const unique_constraint = runtime_schema.unique_constraints[0];
    const ada_row = (try db_mod.relational_store.getRawAlloc(alloc, db.core.store, "user:ada")) orelse return error.TestUnexpectedResult;
    defer alloc.free(ada_row);
    const grace_row = (try db_mod.relational_store.getRawAlloc(alloc, db.core.store, "user:grace")) orelse return error.TestUnexpectedResult;
    defer alloc.free(grace_row);
    const stale_row = (try db_mod.relational_store.getRawAlloc(alloc, db.core.store, "user:stale")) orelse return error.TestUnexpectedResult;
    defer alloc.free(stale_row);
    const ada_value = (try db_mod.relational_store.uniqueConstraintTupleValueAlloc(alloc, ada_row, unique_constraint)) orelse return error.TestUnexpectedResult;
    defer alloc.free(ada_value);
    const grace_value = (try db_mod.relational_store.uniqueConstraintTupleValueAlloc(alloc, grace_row, unique_constraint)) orelse return error.TestUnexpectedResult;
    defer alloc.free(grace_value);
    const stale_value = (try db_mod.relational_store.uniqueConstraintTupleValueAlloc(alloc, stale_row, unique_constraint)) orelse return error.TestUnexpectedResult;
    defer alloc.free(stale_value);
    const ada_key = try db_mod.internal_keys.relationalUniqueKeyAlloc(alloc, "users_email_key", ada_value);
    defer alloc.free(ada_key);
    const grace_key = try db_mod.internal_keys.relationalUniqueKeyAlloc(alloc, "users_email_key", grace_value);
    defer alloc.free(grace_key);
    const stale_key = try db_mod.internal_keys.relationalUniqueKeyAlloc(alloc, "users_email_key", stale_value);
    defer alloc.free(stale_key);
    try db.batch(.{ .deletes = &.{"user:stale"}, .sync_level = .write });
    try db.core.store.putBatch(&.{
        .{ .key = grace_key, .value = "user:wrong" },
        .{ .key = stale_key, .value = "user:ghost" },
    }, &.{ada_key});

    var table_source = table_writes.BoundTableWriteSource.init("docs", &db);
    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{ .ptr = undefined, .vtable = &.{ .status = status } };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }
    };
    const UniqueIntegrityResponse = struct {
        valid: bool,
        complete: bool,
        report: struct {
            scanned_rows: u64,
            expected_unique_rows: u64,
            scanned_unique_rows: u64,
            missing_unique_rows: u64,
            stale_unique_rows: u64,
            repaired_unique_rows: u64,
            deleted_stale_unique_rows: u64,
        },
        groups: []const struct {
            group_id: u64,
            report: struct {
                repaired_unique_rows: u64,
            },
        },
        progress: []const struct {
            group_id: u64,
            mode: []const u8,
            valid: bool,
            report: struct {
                repaired_unique_rows: u64,
                scanned_unique_rows: u64,
            },
        } = &.{},
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, table_source.source());
    var validate_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/unique-integrity",
        .content_type = "application/json",
        .body = "{\"action\":\"validate\"}",
    });
    defer validate_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), validate_resp.status);
    var validate_body = try std.json.parseFromSlice(UniqueIntegrityResponse, alloc, validate_resp.body, .{ .ignore_unknown_fields = true });
    defer validate_body.deinit();
    try std.testing.expect(!validate_body.value.valid);
    try std.testing.expect(validate_body.value.complete);
    try std.testing.expectEqual(@as(u64, 2), validate_body.value.report.scanned_rows);
    try std.testing.expectEqual(@as(u64, 2), validate_body.value.report.expected_unique_rows);
    try std.testing.expectEqual(@as(u64, 1), validate_body.value.report.missing_unique_rows);
    try std.testing.expectEqual(@as(u64, 2), validate_body.value.report.stale_unique_rows);

    var dry_run_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/unique-integrity",
        .content_type = "application/json",
        .body = "{\"action\":\"dry-run\"}",
    });
    defer dry_run_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), dry_run_resp.status);
    var dry_run_body = try std.json.parseFromSlice(UniqueIntegrityResponse, alloc, dry_run_resp.body, .{ .ignore_unknown_fields = true });
    defer dry_run_body.deinit();
    try std.testing.expect(!dry_run_body.value.valid);
    try std.testing.expectEqual(@as(u64, 2), dry_run_body.value.report.repaired_unique_rows);
    try std.testing.expectEqual(@as(u64, 1), dry_run_body.value.report.deleted_stale_unique_rows);
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, ada_key));

    var repair_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/unique-integrity",
        .content_type = "application/json",
        .body = "{\"action\":\"repair\"}",
    });
    defer repair_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), repair_resp.status);
    var repair_body = try std.json.parseFromSlice(UniqueIntegrityResponse, alloc, repair_resp.body, .{ .ignore_unknown_fields = true });
    defer repair_body.deinit();
    try std.testing.expect(!repair_body.value.valid);
    try std.testing.expectEqual(@as(usize, 1), repair_body.value.groups.len);
    try std.testing.expectEqual(@as(u64, 0), repair_body.value.groups[0].group_id);
    try std.testing.expectEqual(@as(u64, 2), repair_body.value.groups[0].report.repaired_unique_rows);

    var after_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/unique-integrity",
        .content_type = "application/json",
        .body = "{\"action\":\"validate\"}",
    });
    defer after_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), after_resp.status);
    var after_body = try std.json.parseFromSlice(UniqueIntegrityResponse, alloc, after_resp.body, .{ .ignore_unknown_fields = true });
    defer after_body.deinit();
    try std.testing.expect(after_body.value.valid);
    try std.testing.expectEqual(@as(u64, 2), after_body.value.report.scanned_unique_rows);
    const ada_owner = try db.core.store.get(alloc, ada_key);
    defer alloc.free(ada_owner);
    try std.testing.expectEqualStrings("user:ada", ada_owner);
    try std.testing.expectError(error.NotFound, db.core.store.get(alloc, stale_key));

    var progress_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/unique-integrity",
        .content_type = "application/json",
        .body = "{\"action\":\"progress\"}",
    });
    defer progress_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), progress_resp.status);
    var progress_body = try std.json.parseFromSlice(UniqueIntegrityResponse, alloc, progress_resp.body, .{ .ignore_unknown_fields = true });
    defer progress_body.deinit();
    try std.testing.expectEqual(@as(usize, 3), progress_body.value.progress.len);
    var saw_validate = false;
    var saw_dry_run = false;
    var saw_repair = false;
    for (progress_body.value.progress) |entry| {
        try std.testing.expectEqual(@as(u64, 0), entry.group_id);
        if (std.mem.eql(u8, entry.mode, "validate")) {
            saw_validate = true;
            try std.testing.expect(entry.valid);
            try std.testing.expectEqual(@as(u64, 2), entry.report.scanned_unique_rows);
        }
        if (std.mem.eql(u8, entry.mode, "dry_run")) {
            saw_dry_run = true;
            try std.testing.expect(!entry.valid);
            try std.testing.expectEqual(@as(u64, 2), entry.report.repaired_unique_rows);
        }
        if (std.mem.eql(u8, entry.mode, "repair")) {
            saw_repair = true;
            try std.testing.expect(entry.valid);
            try std.testing.expectEqual(@as(u64, 2), entry.report.repaired_unique_rows);
        }
    }
    try std.testing.expect(saw_validate);
    try std.testing.expect(saw_dry_run);
    try std.testing.expect(saw_repair);

    var invalid_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/unique-integrity",
        .content_type = "application/json",
        .body = "{\"action\":\"bogus\"}",
    });
    defer invalid_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 400), invalid_resp.status);
    try std.testing.expectEqualStrings("invalid unique integrity request", invalid_resp.body);
}

test "api http server exposes relational column backed index repair worker pass" {
    const alloc = std.testing.allocator;

    const FakeStatus = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }
    };

    const FakeWrites = struct {
        calls: usize = 0,
        begin_calls: usize = 0,
        record_calls: usize = 0,
        database_name: []const u8 = "",
        namespace_name: []const u8 = "",
        table_name: []const u8 = "",
        worker_id: []const u8 = "",
        job_id: []const u8 = "",
        recorded_complete: bool = false,
        recorded_next_upper_doc_key: []const u8 = "",
        lease_ms: u64 = 0,
        max_work_units: usize = 0,

        fn deinit(self: *@This(), alloc_inner: std.mem.Allocator) void {
            if (self.database_name.len != 0) alloc_inner.free(self.database_name);
            if (self.namespace_name.len != 0) alloc_inner.free(self.namespace_name);
            if (self.table_name.len != 0) alloc_inner.free(self.table_name);
            if (self.worker_id.len != 0) alloc_inner.free(self.worker_id);
            if (self.job_id.len != 0) alloc_inner.free(self.job_id);
            if (self.recorded_next_upper_doc_key.len != 0) alloc_inner.free(self.recorded_next_upper_doc_key);
            self.* = .{};
        }

        fn remember(_: *@This(), alloc_inner: std.mem.Allocator, field: *[]const u8, value: []const u8) !void {
            if (field.*.len != 0) alloc_inner.free(field.*);
            field.* = try alloc_inner.dupe(u8, value);
        }

        fn source(self: *@This()) table_writes.TableWriteSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .batch = batch,
                    .relational_column_backed_index_repair_worker_pass_catalog = repairWorkerPassCatalog,
                    .relational_index_repair_job_begin_catalog = repairJobBeginCatalog,
                    .relational_index_repair_job_record_pass_catalog = repairJobRecordPassCatalog,
                    .relational_index_repair_job_load_catalog = repairJobLoadCatalog,
                },
            };
        }

        fn batch(
            _: *anyopaque,
            _: std.mem.Allocator,
            _: []const u8,
            _: db_mod.types.BatchRequest,
        ) anyerror!?void {
            return error.UnsupportedOperation;
        }

        fn repairJobBeginCatalog(
            ptr: *anyopaque,
            alloc_inner: std.mem.Allocator,
            target: catalog_resources.TableTarget,
            job_id: []const u8,
            worker_id: []const u8,
            lease_ms: u64,
            max_work_units: usize,
        ) anyerror!?void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.begin_calls += 1;
            try self.remember(alloc_inner, &self.database_name, target.database_name);
            try self.remember(alloc_inner, &self.namespace_name, target.namespace_name);
            try self.remember(alloc_inner, &self.table_name, target.table_name);
            try self.remember(alloc_inner, &self.job_id, job_id);
            try self.remember(alloc_inner, &self.worker_id, worker_id);
            self.lease_ms = lease_ms;
            self.max_work_units = max_work_units;
            return {};
        }

        fn repairJobRecordPassCatalog(
            ptr: *anyopaque,
            alloc_inner: std.mem.Allocator,
            target: catalog_resources.TableTarget,
            job_id: []const u8,
            result: table_writes.RelationalColumnBackedIndexRepairWorkerPassResult,
        ) anyerror!?void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.record_calls += 1;
            try self.remember(alloc_inner, &self.database_name, target.database_name);
            try self.remember(alloc_inner, &self.namespace_name, target.namespace_name);
            try self.remember(alloc_inner, &self.table_name, target.table_name);
            try self.remember(alloc_inner, &self.job_id, job_id);
            self.recorded_complete = result.complete;
            try self.remember(alloc_inner, &self.recorded_next_upper_doc_key, if (result.groups.len == 0) "" else result.groups[result.groups.len - 1].upper_doc_key);
            return {};
        }

        fn repairJobLoadCatalog(
            ptr: *anyopaque,
            alloc_inner: std.mem.Allocator,
            target: catalog_resources.TableTarget,
            job_id: []const u8,
        ) anyerror!?table_writes.RelationalIndexRepairJobRecord {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try self.remember(alloc_inner, &self.database_name, target.database_name);
            try self.remember(alloc_inner, &self.namespace_name, target.namespace_name);
            try self.remember(alloc_inner, &self.table_name, target.table_name);
            try self.remember(alloc_inner, &self.job_id, job_id);
            const record_table_name = if (std.mem.eql(u8, job_id, "repair:other")) "other" else target.table_name;
            return .{
                .job_id = try alloc_inner.dupe(u8, job_id),
                .database_name = try alloc_inner.dupe(u8, target.database_name),
                .namespace_name = try alloc_inner.dupe(u8, target.namespace_name),
                .table_name = try alloc_inner.dupe(u8, record_table_name),
                .access_method = try alloc_inner.dupe(u8, "ordered_tuple"),
                .worker_id = try alloc_inner.dupe(u8, "worker:repair"),
                .lease_ms = 60_000,
                .max_work_units = 1024,
                .status = try alloc_inner.dupe(u8, "running"),
                .created_at_ns = 1,
                .updated_at_ns = 2,
                .attempts = 1,
                .completed = false,
                .next_lower_doc_key = try alloc_inner.dupe(u8, "row:m"),
                .last_ranges_scanned = 2,
                .last_ranges_repaired = 1,
                .last_ranges_missing = 0,
                .total_ranges_scanned = 2,
                .total_ranges_repaired = 1,
                .total_ranges_missing = 0,
                .last_report = .{
                    .scanned_rows = 3,
                    .indexed_rows = 2,
                    .deleted_orphan_entries = 1,
                    .written_entries = 2,
                },
                .aggregate_report = .{
                    .scanned_rows = 3,
                    .indexed_rows = 2,
                    .deleted_orphan_entries = 1,
                    .written_entries = 2,
                },
            };
        }

        fn repairWorkerPassCatalog(
            ptr: *anyopaque,
            alloc_inner: std.mem.Allocator,
            target: catalog_resources.TableTarget,
            worker_id: []const u8,
            lease_ms: u64,
            max_work_units: usize,
        ) anyerror!?table_writes.RelationalColumnBackedIndexRepairWorkerPassResult {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.calls += 1;
            try self.remember(alloc_inner, &self.database_name, target.database_name);
            try self.remember(alloc_inner, &self.namespace_name, target.namespace_name);
            try self.remember(alloc_inner, &self.table_name, target.table_name);
            try self.remember(alloc_inner, &self.worker_id, worker_id);
            self.lease_ms = lease_ms;
            self.max_work_units = max_work_units;

            const groups = try alloc_inner.alloc(table_writes.RelationalColumnBackedIndexRepairWorkerResult, 1);
            errdefer alloc_inner.free(groups);
            groups[0] = .{
                .group_id = 7001,
                .table_id = 7,
                .range_id = 7101,
                .lower_doc_key = "",
                .upper_doc_key = try alloc_inner.dupe(u8, "row:m"),
                .repaired = true,
                .report = .{
                    .scanned_rows = 3,
                    .indexed_rows = 2,
                    .deleted_orphan_entries = 1,
                    .written_entries = 2,
                },
            };
            return .{
                .complete = false,
                .ranges_scanned = 2,
                .ranges_repaired = 1,
                .ranges_missing = 0,
                .report = groups[0].report,
                .groups = groups,
            };
        }
    };

    const RepairResponse = struct {
        complete: bool,
        ranges_scanned: u64,
        ranges_repaired: u64,
        ranges_missing: u64,
        report: struct {
            scanned_rows: u64,
            indexed_rows: u64,
            deleted_orphan_entries: u64,
            written_entries: u64,
        },
        groups: []const struct {
            group_id: u64,
            table_id: u64,
            range_id: u64,
            lower_doc_key: []const u8,
            upper_doc_key: []const u8,
            repaired: bool,
            report: struct {
                scanned_rows: u64,
                indexed_rows: u64,
                deleted_orphan_entries: u64,
                written_entries: u64,
            },
        },
    };

    const RepairJobResponse = struct {
        job_id: []const u8,
        database_name: []const u8,
        namespace_name: []const u8,
        table_name: []const u8,
        worker_id: []const u8,
        lease_ms: u64,
        max_work_units: usize,
        status: []const u8,
        attempts: u32,
        completed: bool,
        next_lower_doc_key: []const u8,
        last_ranges_scanned: u64,
        total_ranges_scanned: u64,
        aggregate_report: struct {
            scanned_rows: u64,
            indexed_rows: u64,
            deleted_orphan_entries: u64,
            written_entries: u64,
        },
    };

    var status = FakeStatus{};
    var writes = FakeWrites{};
    defer writes.deinit(alloc);
    var server = ApiHttpServer.init(alloc, .{}, status.iface(), null, writes.source());

    var resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/relational-column-backed-index-repair",
        .content_type = "application/json",
        .body = "{\"worker_id\":\"worker:repair\",\"job_id\":\"repair:docs:1\",\"lease_ms\":60000,\"max_work_units\":9999}",
    });
    defer resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), resp.status);
    try std.testing.expectEqual(@as(usize, 1), writes.calls);
    try std.testing.expectEqual(@as(usize, 1), writes.begin_calls);
    try std.testing.expectEqual(@as(usize, 1), writes.record_calls);
    try std.testing.expectEqualStrings(catalog_resources.default_database_name, writes.database_name);
    try std.testing.expectEqualStrings(catalog_resources.default_namespace_name, writes.namespace_name);
    try std.testing.expectEqualStrings("docs", writes.table_name);
    try std.testing.expectEqualStrings("worker:repair", writes.worker_id);
    try std.testing.expectEqualStrings("repair:docs:1", writes.job_id);
    try std.testing.expect(!writes.recorded_complete);
    try std.testing.expectEqualStrings("row:m", writes.recorded_next_upper_doc_key);
    try std.testing.expectEqual(@as(u64, 60_000), writes.lease_ms);
    try std.testing.expectEqual(@as(usize, 1024), writes.max_work_units);

    var parsed = try std.json.parseFromSlice(RepairResponse, alloc, resp.body, .{ .ignore_unknown_fields = true });
    defer parsed.deinit();
    try std.testing.expect(!parsed.value.complete);
    try std.testing.expectEqual(@as(u64, 2), parsed.value.ranges_scanned);
    try std.testing.expectEqual(@as(u64, 1), parsed.value.ranges_repaired);
    try std.testing.expectEqual(@as(u64, 0), parsed.value.ranges_missing);
    try std.testing.expectEqual(@as(u64, 3), parsed.value.report.scanned_rows);
    try std.testing.expectEqual(@as(u64, 1), parsed.value.report.deleted_orphan_entries);
    try std.testing.expectEqual(@as(usize, 1), parsed.value.groups.len);
    try std.testing.expectEqual(@as(u64, 7001), parsed.value.groups[0].group_id);
    try std.testing.expectEqualStrings("row:m", parsed.value.groups[0].upper_doc_key);
    try std.testing.expect(parsed.value.groups[0].repaired);

    var job_resp = try server.handle(.{
        .method = .GET,
        .uri = "/tables/docs/relational-column-backed-index-repair/jobs/repair:docs:1",
    });
    defer job_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), job_resp.status);
    var parsed_job = try std.json.parseFromSlice(RepairJobResponse, alloc, job_resp.body, .{ .ignore_unknown_fields = true });
    defer parsed_job.deinit();
    try std.testing.expectEqualStrings("repair:docs:1", parsed_job.value.job_id);
    try std.testing.expectEqualStrings(catalog_resources.default_database_name, parsed_job.value.database_name);
    try std.testing.expectEqualStrings(catalog_resources.default_namespace_name, parsed_job.value.namespace_name);
    try std.testing.expectEqualStrings("docs", parsed_job.value.table_name);
    try std.testing.expectEqualStrings("worker:repair", parsed_job.value.worker_id);
    try std.testing.expectEqualStrings("running", parsed_job.value.status);
    try std.testing.expectEqual(@as(u32, 1), parsed_job.value.attempts);
    try std.testing.expect(!parsed_job.value.completed);
    try std.testing.expectEqualStrings("row:m", parsed_job.value.next_lower_doc_key);
    try std.testing.expectEqual(@as(u64, 2), parsed_job.value.total_ranges_scanned);
    try std.testing.expectEqual(@as(u64, 3), parsed_job.value.aggregate_report.scanned_rows);
    var wrong_table_job_resp = try server.handle(.{
        .method = .GET,
        .uri = "/tables/docs/relational-column-backed-index-repair/jobs/repair:other",
    });
    defer wrong_table_job_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 404), wrong_table_job_resp.status);
    try std.testing.expectEqualStrings("relational index repair job not found", wrong_table_job_resp.body);

    var namespace_resp = try server.handlePublicCatalogTableRelationalColumnBackedIndexRepair(.{
        .database_name = "tenant_ops",
        .namespace_name = "analytics",
        .table_name = "docs",
    }, "{\"worker_id\":\"worker:tenant\",\"lease_ms\":70000,\"max_work_units\":2}");
    defer namespace_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), namespace_resp.status);
    try std.testing.expectEqual(@as(usize, 2), writes.calls);
    try std.testing.expectEqualStrings("tenant_ops", writes.database_name);
    try std.testing.expectEqualStrings("analytics", writes.namespace_name);
    try std.testing.expectEqualStrings("docs", writes.table_name);
    try std.testing.expectEqualStrings("worker:tenant", writes.worker_id);
    try std.testing.expectEqual(@as(u64, 70_000), writes.lease_ms);
    try std.testing.expectEqual(@as(usize, 2), writes.max_work_units);

    var invalid_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/relational-column-backed-index-repair",
        .content_type = "application/json",
        .body = "{\"worker_id\":\"worker:repair\",\"max_work_units\":0}",
    });
    defer invalid_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 400), invalid_resp.status);
    try std.testing.expectEqualStrings("invalid relational index repair request", invalid_resp.body);
}

test "api http server routes table batches through the batch commit hook" {
    const FakeStatus = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }
    };

    const FakeWrites = struct {
        batch_calls: usize = 0,
        transaction_calls: usize = 0,
        batch_commit_calls: usize = 0,

        fn source(self: *@This()) table_writes.TableWriteSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .batch = batch,
                    .commit_transaction = commitTransaction,
                    .commit_batch = commitBatch,
                },
            };
        }

        fn batch(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            _: []const u8,
            _: db_mod.types.BatchRequest,
        ) anyerror!?void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.batch_calls += 1;
            return error.TestUnexpectedResult;
        }

        fn commitTransaction(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            _: []const distributed_txn.TableCommitRequest,
            _: db_mod.types.SyncLevel,
        ) anyerror!?distributed_txn.CommitOutcome {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.transaction_calls += 1;
            return error.TestUnexpectedResult;
        }

        fn commitBatch(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            tables: []const distributed_txn.TableCommitRequest,
            sync_level: db_mod.types.SyncLevel,
        ) anyerror!?distributed_txn.CommitOutcome {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.batch_commit_calls += 1;
            try std.testing.expectEqual(@as(usize, 1), tables.len);
            try std.testing.expectEqualStrings("docs", tables[0].table_name);
            try std.testing.expectEqual(@as(usize, 1), tables[0].writes.len);
            try std.testing.expectEqualStrings("doc:a", tables[0].writes[0].key);
            try std.testing.expectEqualStrings("{\"title\":\"alpha\"}", tables[0].writes[0].value);
            try std.testing.expectEqual(@as(usize, 1), tables[0].deletes.len);
            try std.testing.expectEqualStrings("doc:gone", tables[0].deletes[0]);
            try std.testing.expectEqual(db_mod.types.SyncLevel.write, sync_level);
            return .{ .committed = .{ .participant_count = 2 } };
        }
    };

    var status = FakeStatus{};
    var writes = FakeWrites{};
    var server = ApiHttpServer.init(std.testing.allocator, .{}, status.iface(), null, writes.source());
    const batch_body = try test_contract_helpers.normalizeBatchRequest(
        std.testing.allocator,
        "{\"inserts\":{\"doc:a\":{\"title\":\"alpha\"}},\"deletes\":[\"doc:gone\"],\"sync_level\":\"write\"}",
    );
    defer std.testing.allocator.free(batch_body);

    var resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/batch",
        .content_type = "application/json",
        .body = batch_body,
    });
    defer resp.deinit(std.testing.allocator);

    try std.testing.expectEqual(@as(u16, 201), resp.status);
    var parsed = try std.json.parseFromSlice(metadata_openapi.BatchResponse, std.testing.allocator, resp.body, .{});
    defer parsed.deinit();
    try std.testing.expectEqual(@as(i64, 1), parsed.value.inserted.?);
    try std.testing.expectEqual(@as(i64, 1), parsed.value.deleted.?);
    try std.testing.expectEqual(@as(usize, 1), writes.batch_commit_calls);
    try std.testing.expectEqual(@as(usize, 0), writes.transaction_calls);
    try std.testing.expectEqual(@as(usize, 0), writes.batch_calls);
}
test "api http server serves table batch transforms" {
    const alloc = std.testing.allocator;
    const StoredTransform = struct {
        status: []const u8,
        version: i64,
    };
    const path = try uniqueTestTmpPathAlloc(alloc, "antfly-api-http-batch-transform");
    defer alloc.free(path);
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch {};

    var db = try db_mod.DB.open(alloc, path, .{});
    defer {
        db.close();
        std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch {};
    }

    var table_source = table_writes.BoundTableWriteSource.init("docs", &db);

    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .status = status,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(std.testing.allocator, .{}, source.iface(), null, table_source.source());

    const insert_body = try test_contract_helpers.normalizeBatchRequest(
        std.testing.allocator,
        "{\"inserts\":{\"doc:a\":{\"title\":\"alpha\",\"version\":1}}}",
    );
    defer std.testing.allocator.free(insert_body);
    var insert_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/batch",
        .content_type = "application/json",
        .body = insert_body,
    });
    defer insert_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 201), insert_resp.status);
    try std.testing.expectEqualStrings("application/json", insert_resp.content_type.?);
    var parsed_insert = try std.json.parseFromSlice(metadata_openapi.BatchResponse, std.testing.allocator, insert_resp.body, .{});
    defer parsed_insert.deinit();
    try std.testing.expectEqual(@as(i64, 1), parsed_insert.value.inserted.?);

    const transform_body = try test_contract_helpers.normalizeBatchRequest(
        std.testing.allocator,
        "{\"transforms\":[{\"key\":\"doc:a\",\"operations\":[{\"op\":\"$set\",\"path\":\"status\",\"value\":\"updated\"},{\"op\":\"$max\",\"path\":\"version\",\"value\":3}]}]}",
    );
    defer std.testing.allocator.free(transform_body);
    var transform_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/batch",
        .content_type = "application/json",
        .body = transform_body,
    });
    defer transform_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 201), transform_resp.status);
    try std.testing.expectEqualStrings("application/json", transform_resp.content_type.?);

    var parsed_batch = try std.json.parseFromSlice(metadata_openapi.BatchResponse, std.testing.allocator, transform_resp.body, .{});
    defer parsed_batch.deinit();
    try std.testing.expectEqual(@as(i64, 1), parsed_batch.value.transformed.?);

    var lookup = (try db.lookup(alloc, "doc:a", .{})).?;
    defer lookup.deinit(alloc);
    var parsed_stored = try std.json.parseFromSlice(StoredTransform, alloc, lookup.json, .{
        .allocate = .alloc_always,
        .ignore_unknown_fields = true,
    });
    defer parsed_stored.deinit();
    const stored = parsed_stored.value;
    try std.testing.expectEqualStrings("updated", stored.status);
    try std.testing.expectEqual(@as(i64, 3), stored.version);
}

test "api http graph push preserves projected edges across restart" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/graph-push-restart", .{tmp.sub_path});
    defer alloc.free(path);

    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }
    };

    {
        var db = try db_mod.DB.open(alloc, path, .{});
        defer db.close();
        var table_source = table_writes.BoundTableWriteSource.init("docs", &db);
        var create_req = tables_api.CreateTableRequest{
            .indexes_json = try alloc.dupe(u8, "{\"graph\":{\"type\":\"graph\"}}"),
        };
        defer create_req.deinit(alloc);
        _ = try table_source.source().createTable(alloc, "docs", create_req);

        var source = FakeSource{};
        var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, table_source.source());

        const insert_body = try test_contract_helpers.normalizeBatchRequest(alloc,
            \\{"inserts":{"a":{"title":"A","_edges":{"graph":{"FRIEND":[{"target":"b","weight":2,"metadata":{"since":2024}}]}}},"b":{"title":"B"},"c":{"title":"C"}},"sync_level":"full_index"}
        );
        defer alloc.free(insert_body);
        var insert_resp = try server.handle(.{
            .method = .POST,
            .uri = "/tables/docs/batch",
            .content_type = "application/json",
            .body = insert_body,
        });
        defer insert_resp.deinit(alloc);
        try std.testing.expectEqual(@as(u16, 201), insert_resp.status);

        const transform_body = try test_contract_helpers.normalizeBatchRequest(alloc,
            \\{"transforms":[{"key":"a","operations":[{"op":"$push","path":"$._edges.graph.FRIEND","value":{"target":"c","weight":3}}]}],"sync_level":"full_index"}
        );
        defer alloc.free(transform_body);
        var transform_resp = try server.handle(.{
            .method = .POST,
            .uri = "/tables/docs/batch",
            .content_type = "application/json",
            .body = transform_body,
        });
        defer transform_resp.deinit(alloc);
        try std.testing.expectEqual(@as(u16, 201), transform_resp.status);

        const invalid_transforms = [_][]const u8{
            \\{"transforms":[{"key":"a","operations":[{"op":"$set","path":"title","value":"must-not-commit"},{"op":"$set","path":"$._edges.graph.FRIEND","value":[]}]}],"sync_level":"full_index"}
            ,
            \\{"transforms":[{"key":"a","operations":[{"op":"$set","path":"title","value":"must-not-commit"},{"op":"$inc","path":"$._edges.graph.FRIEND","value":1}]}],"sync_level":"full_index"}
            ,
            \\{"transforms":[{"key":"a","operations":[{"op":"$set","path":"title","value":"must-not-commit"},{"op":"$push","path":"$._edges.graph.FRIEND","value":{"weight":4}}]}],"sync_level":"full_index"}
            ,
            \\{"transforms":[{"key":"a","operations":[{"op":"$set","path":"title","value":"must-not-commit"},{"op":"$push","path":"$._edges.graph","value":{"target":"d"}}]}],"sync_level":"full_index"}
            ,
        };
        for (invalid_transforms) |invalid_body_json| {
            const invalid_body = try test_contract_helpers.normalizeBatchRequest(alloc, invalid_body_json);
            defer alloc.free(invalid_body);
            var invalid_resp = try server.handle(.{
                .method = .POST,
                .uri = "/tables/docs/batch",
                .content_type = "application/json",
                .body = invalid_body,
            });
            defer invalid_resp.deinit(alloc);
            try std.testing.expectEqual(@as(u16, 400), invalid_resp.status);
        }

        const invalid_txn_batch = try test_contract_helpers.normalizeBatchRequest(alloc,
            \\{"transforms":[{"key":"a","operations":[{"op":"$set","path":"title","value":"must-not-commit"},{"op":"$set","path":"$._edges.graph.FRIEND","value":[]}]}],"sync_level":"full_index"}
        );
        defer alloc.free(invalid_txn_batch);
        const invalid_txn_body = try test_contract_helpers.encodeTransactionCommitRequest(
            alloc,
            &.{},
            &.{.{ .table_name = "docs", .batch_json = invalid_txn_batch }},
            "full_index",
        );
        defer alloc.free(invalid_txn_body);
        var invalid_txn_resp = try server.handle(.{
            .method = .POST,
            .uri = routes.Routes.transactions_commit,
            .content_type = "application/json",
            .body = invalid_txn_body,
        });
        defer invalid_txn_resp.deinit(alloc);
        try std.testing.expectEqual(@as(u16, 400), invalid_txn_resp.status);

        const stored = (try db.get(alloc, "a")) orelse return error.TestExpectedEqual;
        defer alloc.free(stored);
        try std.testing.expect(std.mem.indexOf(u8, stored, "must-not-commit") == null);
        const edges = try db.getEdges(alloc, "graph", "a", "FRIEND", .out);
        defer graph_mod.GraphIndex.freeEdges(alloc, edges);
        try std.testing.expectEqual(@as(usize, 2), edges.len);
    }

    var reopened = try db_mod.DB.open(alloc, path, .{});
    defer reopened.close();
    const reopened_edges = try reopened.getEdges(alloc, "graph", "a", "FRIEND", .out);
    defer graph_mod.GraphIndex.freeEdges(alloc, reopened_edges);
    try std.testing.expectEqual(@as(usize, 2), reopened_edges.len);
    var saw_b = false;
    var saw_c = false;
    for (reopened_edges) |edge| {
        if (std.mem.eql(u8, edge.target, "b")) saw_b = true;
        if (std.mem.eql(u8, edge.target, "c")) saw_c = true;
    }
    try std.testing.expect(saw_b and saw_c);
}

test "api http server updates local table schema through bound write source" {
    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/local-schema", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();

    var table_source = table_writes.BoundTableWriteSource.init("docs", &db);

    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .status = status,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(std.testing.allocator, .{}, source.iface(), null, table_source.source());

    var managed_version_resp = try server.handle(.{
        .method = .PUT,
        .uri = "/tables/docs/schema",
        .content_type = "application/json",
        .body = "{\"version\":7}",
    });
    defer managed_version_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 400), managed_version_resp.status);
    try std.testing.expectEqualStrings("schema.version is managed by Antfly; omit it", managed_version_resp.body);

    const schema_body = "{\"default_type\":\"doc\",\"enforce_types\":true,\"document_schemas\":{\"doc\":{\"schema\":{\"type\":\"object\",\"properties\":{\"title\":{\"type\":\"text\"},\"status\":{\"type\":\"keyword\"}}}}}}";
    var update_resp = try server.handle(.{
        .method = .PUT,
        .uri = "/tables/docs/schema",
        .content_type = "application/json",
        .body = schema_body,
    });
    defer update_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), update_resp.status);
    try std.testing.expectEqualStrings("application/json", update_resp.content_type.?);
    var parsed_update = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, update_resp.body, .{
        .allocate = .alloc_always,
    });
    defer parsed_update.deinit();
    try std.testing.expect(parsed_update.value == .object);
    try std.testing.expectEqualStrings("docs", parsed_update.value.object.get("name").?.string);
    try std.testing.expect(parsed_update.value.object.get("schema") != null);

    const batch_body = try test_contract_helpers.normalizeBatchRequest(std.testing.allocator, "{\"inserts\":{\"doc:a\":{\"title\":\"alpha\",\"body\":\"unexpected\"}}}");
    defer std.testing.allocator.free(batch_body);
    var batch_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/batch",
        .content_type = "application/json",
        .body = batch_body,
    });
    defer batch_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 400), batch_resp.status);
}

test "api http server resolves relational rows by unique selector" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"email":{"type":"keyword"},"status":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]},"unique_constraints":[{"name":"users_email_key","columns":["email"]}]}
    ;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/rows-unique-selector", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();
    try db.applyTableSchemaJson(alloc, schema_json, .{});

    var read_source = table_reads.BoundTableReadSource.init("users", 1, &db, raft_mod.read_gate.noopReadableLeaseRequester());
    var write_source = table_writes.BoundTableWriteSource.init("users", &db);

    const FakeSource = struct {
        tables: [1]metadata_table_manager.TableRecord,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = try status(ptr),
                .tables = self.tables[0..],
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    var source = FakeSource{ .tables = .{.{
        .table_id = 1,
        .name = "users",
        .schema_json = schema_json,
        .desired_replica_count = 1,
    }} };
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), read_source.source(), write_source.source());

    var insert_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/users/rows/batch",
        .content_type = "application/json",
        .body = "{\"operations\":[{\"op\":\"insert\",\"row\":{\"id\":\"user:ada\",\"email\":\"ada@example.test\",\"status\":\"new\"}},{\"op\":\"insert\",\"row\":{\"id\":\"user:grace\",\"email\":\"grace@example.test\",\"status\":\"new\"}}]}",
    });
    defer insert_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 201), insert_resp.status);

    var get_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/users/rows/get",
        .content_type = "application/json",
        .body = "{\"keys\":[{\"unique\":{\"name\":\"users_email_key\",\"values\":{\"email\":\"ada@example.test\"}}}],\"include_physical_key\":true}",
    });
    defer get_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), get_resp.status);
    var parsed_get = try std.json.parseFromSlice(std.json.Value, alloc, get_resp.body, .{ .allocate = .alloc_always });
    defer parsed_get.deinit();
    const first_get = parsed_get.value.object.get("rows").?.array.items[0].object;
    try std.testing.expect(first_get.get("found").?.bool);
    try std.testing.expectEqualStrings("ada@example.test", first_get.get("row").?.object.get("email").?.string);
    try std.testing.expect(first_get.get("physical_key").? == .string);
    const original_version = first_get.get("version").?.integer;

    const update_body = try std.fmt.allocPrint(
        alloc,
        "{{\"operations\":[{{\"op\":\"update\",\"where\":{{\"unique\":{{\"name\":\"users_email_key\",\"values\":{{\"email\":\"ada@example.test\"}}}}}},\"expected_version\":{d},\"patch\":{{\"status\":\"active\"}}}}]}}",
        .{original_version},
    );
    defer alloc.free(update_body);
    var update_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/users/rows/batch",
        .content_type = "application/json",
        .body = update_body,
    });
    defer update_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 201), update_resp.status);

    var updated_get_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/users/rows/get",
        .content_type = "application/json",
        .body = "{\"keys\":[{\"primary\":{\"id\":\"user:ada\"}}]}",
    });
    defer updated_get_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), updated_get_resp.status);
    var parsed_updated = try std.json.parseFromSlice(std.json.Value, alloc, updated_get_resp.body, .{ .allocate = .alloc_always });
    defer parsed_updated.deinit();
    const updated = parsed_updated.value.object.get("rows").?.array.items[0].object;
    try std.testing.expect(updated.get("found").?.bool);
    try std.testing.expectEqualStrings("active", updated.get("row").?.object.get("status").?.string);
    const updated_version = updated.get("version").?.integer;

    const stale_delete_body = try std.fmt.allocPrint(
        alloc,
        "{{\"operations\":[{{\"op\":\"delete\",\"where\":{{\"unique\":{{\"name\":\"users_email_key\",\"values\":{{\"email\":\"ada@example.test\"}}}}}},\"expected_version\":{d}}}]}}",
        .{original_version},
    );
    defer alloc.free(stale_delete_body);
    var stale_delete_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/users/rows/batch",
        .content_type = "application/json",
        .body = stale_delete_body,
    });
    defer stale_delete_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 409), stale_delete_resp.status);

    const delete_body = try std.fmt.allocPrint(
        alloc,
        "{{\"operations\":[{{\"op\":\"delete\",\"where\":{{\"unique\":{{\"name\":\"users_email_key\",\"values\":{{\"email\":\"ada@example.test\"}}}}}},\"expected_version\":{d}}}]}}",
        .{updated_version},
    );
    defer alloc.free(delete_body);
    var delete_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/users/rows/batch",
        .content_type = "application/json",
        .body = delete_body,
    });
    defer delete_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 201), delete_resp.status);

    var missing_get_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/users/rows/get",
        .content_type = "application/json",
        .body = "{\"keys\":[{\"unique\":{\"name\":\"users_email_key\",\"values\":{\"email\":\"ada@example.test\"}}}],\"include_physical_key\":true}",
    });
    defer missing_get_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), missing_get_resp.status);
    var parsed_missing = try std.json.parseFromSlice(std.json.Value, alloc, missing_get_resp.body, .{ .allocate = .alloc_always });
    defer parsed_missing.deinit();
    const missing = parsed_missing.value.object.get("rows").?.array.items[0].object;
    try std.testing.expect(!missing.get("found").?.bool);
    try std.testing.expect(missing.get("physical_key").? == .null);
}

test "api http server resolves temporal relational rows by period-qualified primary selector" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"sku":{"type":"keyword"},"valid_from":{"type":"numeric"},"valid_to":{"type":"numeric"},"price":{"type":"numeric"}},"required":["sku","valid_from"],"additionalProperties":false}}},"periods":[{"name":"valid_time","start_column":"valid_from","end_column":"valid_to"}],"primary_key":{"columns":["sku"],"without_overlaps_period":"valid_time"}}
    ;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/rows-temporal-primary-selector", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();
    try db.applyTableSchemaJson(alloc, schema_json, .{});
    try db.batch(.{
        .writes = &.{
            .{ .key = "price:a:v1", .value = "{\"sku\":\"sku:a\",\"valid_from\":0,\"valid_to\":10,\"price\":10}" },
            .{ .key = "price:a:v2", .value = "{\"sku\":\"sku:a\",\"valid_from\":10,\"valid_to\":20,\"price\":12}" },
            .{ .key = "price:a:current", .value = "{\"sku\":\"sku:a\",\"valid_from\":20,\"price\":14}" },
        },
    });

    var read_source = table_reads.BoundTableReadSource.init("prices", 1, &db, raft_mod.read_gate.noopReadableLeaseRequester());
    var write_source = table_writes.BoundTableWriteSource.init("prices", &db);

    const FakeSource = struct {
        tables: [1]metadata_table_manager.TableRecord,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = try status(ptr),
                .tables = self.tables[0..],
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    var source = FakeSource{ .tables = .{.{
        .table_id = 1,
        .name = "prices",
        .schema_json = schema_json,
        .desired_replica_count = 1,
    }} };
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), read_source.source(), write_source.source());

    var get_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/prices/rows/get",
        .content_type = "application/json",
        .body = "{\"keys\":[{\"primary\":{\"values\":{\"sku\":\"sku:a\"},\"period\":{\"name\":\"valid_time\",\"at\":25}}}],\"include_physical_key\":true}",
    });
    defer get_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), get_resp.status);
    var parsed_get = try std.json.parseFromSlice(std.json.Value, alloc, get_resp.body, .{ .allocate = .alloc_always });
    defer parsed_get.deinit();
    const current = parsed_get.value.object.get("rows").?.array.items[0].object;
    try std.testing.expect(current.get("found").?.bool);
    try std.testing.expectEqualStrings("price:a:current", current.get("physical_key").?.string);
    try std.testing.expectEqual(@as(i64, 14), current.get("row").?.object.get("price").?.integer);

    var missing_get_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/prices/rows/get",
        .content_type = "application/json",
        .body = "{\"keys\":[{\"primary\":{\"values\":{\"sku\":\"sku:missing\"},\"period\":{\"name\":\"valid_time\",\"at\":25}}}]}",
    });
    defer missing_get_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), missing_get_resp.status);
    var parsed_missing_temporal = try std.json.parseFromSlice(std.json.Value, alloc, missing_get_resp.body, .{ .allocate = .alloc_always });
    defer parsed_missing_temporal.deinit();
    try std.testing.expect(!parsed_missing_temporal.value.object.get("rows").?.array.items[0].object.get("found").?.bool);
}

fn expectRowsResultSchemaColumn(
    result: std.json.Value,
    name: []const u8,
    field_type: []const u8,
    nullable: bool,
    array_item_type: ?[]const u8,
) !void {
    const schema = result.object.get("result_schema") orelse return error.TestUnexpectedResult;
    if (schema != .array) return error.TestUnexpectedResult;
    for (schema.array.items) |item| {
        if (item != .object) return error.TestUnexpectedResult;
        const column_name = item.object.get("name") orelse return error.TestUnexpectedResult;
        if (column_name != .string or !std.mem.eql(u8, column_name.string, name)) continue;
        const column_path = item.object.get("path") orelse return error.TestUnexpectedResult;
        if (column_path != .string) return error.TestUnexpectedResult;
        const column_type = item.object.get("type") orelse return error.TestUnexpectedResult;
        if (column_type != .string) return error.TestUnexpectedResult;
        try std.testing.expectEqualStrings(field_type, column_type.string);
        const column_nullable = item.object.get("nullable") orelse return error.TestUnexpectedResult;
        if (column_nullable != .bool) return error.TestUnexpectedResult;
        try std.testing.expectEqual(nullable, column_nullable.bool);
        if (array_item_type) |expected| {
            const actual = item.object.get("array_item_type") orelse return error.TestUnexpectedResult;
            if (actual != .string) return error.TestUnexpectedResult;
            try std.testing.expectEqualStrings(expected, actual.string);
        } else {
            try std.testing.expect(item.object.get("array_item_type") == null);
        }
        return;
    }
    return error.TestUnexpectedResult;
}

fn expectRowsResultSchemaColumnCollation(
    result: std.json.Value,
    name: []const u8,
    expected: ?[]const u8,
) !void {
    const schema = result.object.get("result_schema") orelse return error.TestUnexpectedResult;
    if (schema != .array) return error.TestUnexpectedResult;
    for (schema.array.items) |item| {
        if (item != .object) return error.TestUnexpectedResult;
        const column_name = item.object.get("name") orelse return error.TestUnexpectedResult;
        if (column_name != .string or !std.mem.eql(u8, column_name.string, name)) continue;
        if (expected) |value| {
            const actual = item.object.get("collation") orelse return error.TestUnexpectedResult;
            if (actual != .string) return error.TestUnexpectedResult;
            try std.testing.expectEqualStrings(value, actual.string);
        } else {
            try std.testing.expect(item.object.get("collation") == null);
        }
        return;
    }
    return error.TestUnexpectedResult;
}

test "api http server executes public relational row plan endpoints" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"kind":{"type":"keyword"},"tenant":{"type":"keyword"},"id":{"type":"keyword","collation":"C"},"customer_id":{"type":"keyword"},"name":{"type":"keyword","collation":"name_collation"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"created_at":{"type":"numeric"}},"required":["kind","tenant","id"],"additionalProperties":false}}},"primary_key":{"columns":["kind","tenant","id"]}}
    ;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/rows-plan-endpoints", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();
    try db.applyTableSchemaJson(alloc, schema_json, .{});

    var read_source = table_reads.BoundTableReadSource.init("records", 1, &db, raft_mod.read_gate.noopReadableLeaseRequester());
    var write_source = table_writes.BoundTableWriteSource.init("records", &db);

    const FakeSource = struct {
        tables: [1]metadata_table_manager.TableRecord,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = try status(ptr),
                .tables = self.tables[0..],
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    var source = FakeSource{ .tables = .{.{
        .table_id = 1,
        .name = "records",
        .schema_json = schema_json,
        .desired_replica_count = 1,
    }} };
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), read_source.source(), write_source.source());

    var insert_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/records/rows/batch",
        .content_type = "application/json",
        .body = "{\"operations\":[{\"op\":\"insert\",\"row\":{\"kind\":\"customer\",\"tenant\":\"t1\",\"id\":\"c1\",\"name\":\"Alice\"}},{\"op\":\"insert\",\"row\":{\"kind\":\"customer\",\"tenant\":\"t1\",\"id\":\"c2\",\"name\":\"Bob\"}},{\"op\":\"insert\",\"row\":{\"kind\":\"order\",\"tenant\":\"t1\",\"id\":\"o1\",\"customer_id\":\"c1\",\"status\":\"open\",\"amount\":10,\"created_at\":10}},{\"op\":\"insert\",\"row\":{\"kind\":\"order\",\"tenant\":\"t1\",\"id\":\"o2\",\"customer_id\":\"c1\",\"status\":\"open\",\"amount\":20,\"created_at\":20}},{\"op\":\"insert\",\"row\":{\"kind\":\"order\",\"tenant\":\"t1\",\"id\":\"o3\",\"customer_id\":\"c2\",\"status\":\"closed\",\"amount\":30,\"created_at\":30}}]}",
    });
    defer insert_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 201), insert_resp.status);

    var query_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/records/rows/query",
        .content_type = "application/json",
        .body = "{\"query\":{\"where\":{\"all\":[{\"field\":\"kind\",\"op\":\"eq\",\"value\":\"order\"},{\"field\":\"status\",\"op\":\"eq\",\"value\":\"open\"}]},\"select\":[\"id\",\"amount\"],\"order_by\":[{\"field\":\"amount\",\"direction\":\"desc\"}]}}",
    });
    defer query_resp.deinit(alloc);
