    try std.testing.expectEqual(@as(i64, 2), or_text_query_candidates.get("supplied_ref_count").?.integer);
    try std.testing.expectEqual(@as(i64, 1), or_text_query_candidates.get("usable_set_count").?.integer);
    try std.testing.expectEqual(@as(i64, 2), or_text_query_candidates.get("usable_ref_count").?.integer);
    try std.testing.expectEqual(@as(i64, 2), or_text_query_candidates.get("intersected_ref_count").?.integer);
    try std.testing.expect(or_text_query_candidates.get("hydration_possible").?.bool);

    var multi_token_prefix_sidecar_response = try server.handlePublicTableRowsQuery("events", "{\"query\":{\"select\":[\"amount\"],\"where\":{\"field\":\"category\",\"op\":\"text_pattern\",\"pattern\":\"news ro%\"}}}", null);
    defer multi_token_prefix_sidecar_response.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), multi_token_prefix_sidecar_response.status);
    try std.testing.expectEqual(@as(u32, 15), resolver.open_count);
    try std.testing.expectEqual(@as(u32, 0), base_reads.rows_query_count);

    var parsed_multi_token_prefix_sidecar = try std.json.parseFromSlice(std.json.Value, alloc, multi_token_prefix_sidecar_response.body, .{ .allocate = .alloc_always });
    defer parsed_multi_token_prefix_sidecar.deinit();
    try std.testing.expectEqual(@as(i64, 1), parsed_multi_token_prefix_sidecar.value.object.get("total").?.integer);
    const multi_token_prefix_sidecar_rows = parsed_multi_token_prefix_sidecar.value.object.get("rows").?.array.items;
    try std.testing.expectEqual(@as(usize, 1), multi_token_prefix_sidecar_rows.len);
    try std.testing.expectEqual(@as(i64, 30), multi_token_prefix_sidecar_rows[0].object.get("amount").?.integer);

    var multi_token_prefix_query_explain_response = try server.handle(.{
        .method = .POST,
        .uri = "/tables/events/rows/explain",
        .body = "{\"query\":{\"select\":[\"amount\"],\"where\":{\"field\":\"category\",\"op\":\"text_pattern\",\"pattern\":\"news ro%\"}}}",
    });
    defer multi_token_prefix_query_explain_response.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), multi_token_prefix_query_explain_response.status);
    try std.testing.expectEqual(@as(u32, 16), resolver.open_count);
    try std.testing.expectEqual(@as(u32, 0), base_reads.rows_query_count);

    var parsed_multi_token_prefix_query_explain = try std.json.parseFromSlice(std.json.Value, alloc, multi_token_prefix_query_explain_response.body, .{ .allocate = .alloc_always });
    defer parsed_multi_token_prefix_query_explain.deinit();
    const multi_token_prefix_query_explain_plan = parsed_multi_token_prefix_query_explain.value.object.get("plan").?.object;
    const multi_token_prefix_query_candidates = multi_token_prefix_query_explain_plan.get("sidecar_candidates").?.object;
    try std.testing.expectEqual(@as(i64, 1), multi_token_prefix_query_candidates.get("supplied_set_count").?.integer);
    try std.testing.expectEqual(@as(i64, 1), multi_token_prefix_query_candidates.get("supplied_ref_count").?.integer);
    try std.testing.expectEqual(@as(i64, 1), multi_token_prefix_query_candidates.get("usable_set_count").?.integer);
    try std.testing.expectEqual(@as(i64, 1), multi_token_prefix_query_candidates.get("usable_ref_count").?.integer);
    try std.testing.expectEqual(@as(i64, 1), multi_token_prefix_query_candidates.get("intersected_ref_count").?.integer);
    try std.testing.expect(multi_token_prefix_query_candidates.get("hydration_possible").?.bool);

    var gcs_response = try server.handlePublicTableRowsQuery("events_gcs", "{\"query\":{\"select\":[\"amount\"],\"where\":{\"field\":\"tenant\",\"op\":\"eq\",\"value\":7}}}", null);
    defer gcs_response.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), gcs_response.status);
    try std.testing.expectEqual(@as(u32, 17), resolver.open_count);
    try std.testing.expectEqual(@as(u32, 16), resolver.s3_open_count);
    try std.testing.expectEqual(@as(u32, 1), resolver.gcs_open_count);
    try std.testing.expectEqual(@as(u32, 0), base_reads.rows_query_count);

    var parsed_gcs = try std.json.parseFromSlice(std.json.Value, alloc, gcs_response.body, .{ .allocate = .alloc_always });
    defer parsed_gcs.deinit();
    try std.testing.expectEqual(@as(i64, 1), parsed_gcs.value.object.get("total").?.integer);
    const gcs_rows = parsed_gcs.value.object.get("rows").?.array.items;
    try std.testing.expectEqual(@as(usize, 1), gcs_rows.len);
    try std.testing.expectEqual(@as(i64, 10), gcs_rows[0].object.get("amount").?.integer);
}

test "api http server resolves credentialed external lake rows from node config" {
    const alloc = std.testing.allocator;
    const object_storage_api = @import("../storage/object_storage.zig");
    const schema_template =
        \\{{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"base_source":{{"kind":"external","table_id":"events","format":"parquet","uri":"file://{s}","credentials":{{"ref":"prod-lake-read","scope":"events"}},"schema_fingerprint":"schema-v1"}},"document_schemas":{{"row":{{"schema":{{"type":"object","properties":{{"amount":{{"type":"numeric"}},"tenant":{{"type":"numeric"}}}},"required":["amount","tenant"],"additionalProperties":false}}}}}},"primary_key":{{"columns":["amount"]}}}}
    ;

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const lake_root = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/lake", .{tmp.sub_path});
    defer alloc.free(lake_root);
    const events_path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/lake/events", .{tmp.sub_path});
    defer alloc.free(events_path);
    const parquet_columns = [_]serverless_query.LakeParquetTestPlainI64Column{
        .{ .column_id = "amount", .values = &[_]i64{ 40, 50, 60 } },
        .{ .column_id = "tenant", .values = &[_]i64{ 1, 2, 2 } },
    };
    const parquet_object = try serverless_query.buildLakeParquetTestPlainI64ObjectAlloc(alloc, &parquet_columns);
    defer alloc.free(parquet_object);
    var fs_store = try object_storage_api.FilesystemObjectStorage.init(alloc, events_path);
    defer fs_store.deinit();
    var fs_client = fs_store.client();
    var put = try fs_client.putObject("external-lake", "part-a.parquet", parquet_object, .{});
    defer put.deinit(alloc);

    const schema_json = try std.fmt.allocPrint(alloc, schema_template, .{events_path});
    defer alloc.free(schema_json);
    const cfg_json = try std.fmt.allocPrint(alloc,
        \\{{
        \\  "connections": {{
        \\    "prod-lake-read": {{
        \\      "kind": "external_io",
        \\      "capabilities": ["lake_read"],
        \\      "external_io": {{
        \\        "protocol": "filesystem",
        \\        "prefix": "{s}"
        \\      }}
        \\    }}
        \\  }}
        \\}}
    , .{lake_root});
    defer alloc.free(cfg_json);
    var cfg = try common_config.Config.parseFromSlice(alloc, cfg_json);
    defer cfg.deinit();

    const FakeSource = struct {
        tables: [1]metadata_table_manager.TableRecord,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            return .{
                .status = try status(ptr),
                .tables = self.tables[0..],
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    const FakeBaseReads = struct {
        rows_query_count: u32 = 0,

        fn source(self: *@This()) table_reads.TableReadSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .lookup = lookup,
                    .scan = scan,
                    .query = query,
                    .rows_query_plan = rowsQueryPlan,
                },
            };
        }

        fn lookup(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8, _: db_mod.types.LookupOptions, _: raft_mod.ReadConsistency) !?table_reads.LookupResponse {
            return error.UnexpectedBaseLookup;
        }

        fn scan(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: []const u8, _: []const u8, _: db_mod.types.ScanOptions, _: raft_mod.ReadConsistency) !?table_reads.ScanResponse {
            return error.UnexpectedBaseScan;
        }

        fn query(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: db_mod.types.SearchRequest, _: raft_mod.ReadConsistency) !?query_api.QueryResponse {
            return error.UnexpectedBaseQuery;
        }

        fn rowsQueryPlan(ptr: *anyopaque, _: std.mem.Allocator, _: []const u8, _: runtime_schema_mod.TableSchema, _: db_mod.types.RelationalRowsQueryPlan, _: raft_mod.ReadConsistency) !?db_mod.types.RelationalRowsQueryResult {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.rows_query_count += 1;
            return error.BaseRowsQueryReached;
        }
    };

    var source = FakeSource{ .tables = .{.{
        .table_id = 1,
        .name = "events",
        .schema_json = schema_json,
        .desired_replica_count = 1,
    }} };
    var base_reads = FakeBaseReads{};
    var server = ApiHttpServer.init(
        alloc,
        .{ .node_config = &cfg },
        source.iface(),
        base_reads.source(),
        null,
    );
    defer server.deinit();

    var response = try server.handlePublicTableRowsQuery("events", "{\"query\":{\"select\":[\"amount\"],\"where\":{\"field\":\"tenant\",\"op\":\"eq\",\"value\":2}}}", null);
    defer response.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), response.status);
    try std.testing.expectEqual(@as(u32, 0), base_reads.rows_query_count);

    var parsed = try std.json.parseFromSlice(std.json.Value, alloc, response.body, .{ .allocate = .alloc_always });
    defer parsed.deinit();
    try std.testing.expectEqual(@as(i64, 2), parsed.value.object.get("total").?.integer);
    const rows = parsed.value.object.get("rows").?.array.items;
    try std.testing.expectEqual(@as(usize, 2), rows.len);
    try std.testing.expectEqual(@as(i64, 50), rows[0].object.get("amount").?.integer);
    try std.testing.expectEqual(@as(i64, 60), rows[1].object.get("amount").?.integer);
    try std.testing.expect(rows[0].object.get("tenant") == null);
}

test "api http server serves public transaction commit route" {
    const alloc = std.testing.allocator;
    const StoredTitle = struct {
        title: []const u8,
    };
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/public-txn", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();
    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"alpha\"}" }},
        .timestamp_ns = 7,
    });

    var read_source = table_reads.BoundTableReadSource.init("docs", 1, &db, raft_mod.read_gate.noopReadableLeaseRequester());
    var table_source = table_writes.BoundTableWriteSource.init("docs", &db);

    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .status = status,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(std.testing.allocator, .{}, source.iface(), read_source.source(), table_source.source());

    const commit_batch = try test_contract_helpers.normalizeBatchRequest(std.testing.allocator, "{\"inserts\":{\"doc:a\":{\"title\":\"beta\"}}}");
    defer std.testing.allocator.free(commit_batch);
    const commit_body = try test_contract_helpers.encodeTransactionCommitRequest(
        std.testing.allocator,
        &.{.{ .table_name = "docs", .key = "doc:a", .version = "7" }},
        &.{.{ .table_name = "docs", .batch_json = commit_batch }},
        "write",
    );
    defer std.testing.allocator.free(commit_body);

    var commit_resp = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.transactions_commit,
        .content_type = "application/json",
        .body = commit_body,
    });
    defer commit_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), commit_resp.status);
    try std.testing.expectEqualStrings("application/json", commit_resp.content_type.?);
    var parsed_commit = try std.json.parseFromSlice(transactions_api.CommitResponse, std.testing.allocator, commit_resp.body, .{});
    defer parsed_commit.deinit();
    try std.testing.expectEqualStrings("committed", parsed_commit.value.status);
    try std.testing.expect(parsed_commit.value.tables != null);

    var updated = (try db.lookup(alloc, "doc:a", .{})).?;
    defer updated.deinit(alloc);
    var parsed_stored = try std.json.parseFromSlice(StoredTitle, alloc, updated.json, .{
        .allocate = .alloc_always,
        .ignore_unknown_fields = true,
    });
    defer parsed_stored.deinit();
    const stored = parsed_stored.value;
    try std.testing.expectEqualStrings("beta", stored.title);

    const stale_body = try test_contract_helpers.encodeTransactionCommitRequest(
        std.testing.allocator,
        &.{.{ .table_name = "docs", .key = "doc:a", .version = "7" }},
        &.{.{ .table_name = "docs", .batch_json = commit_batch }},
        null,
    );
    defer std.testing.allocator.free(stale_body);

    var stale_resp = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.transactions_commit,
        .content_type = "application/json",
        .body = stale_body,
    });
    defer stale_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 409), stale_resp.status);
    try std.testing.expectEqualStrings("application/json", stale_resp.content_type.?);
    var parsed_conflict = try std.json.parseFromSlice(transactions_api.CommitResponse, std.testing.allocator, stale_resp.body, .{});
    defer parsed_conflict.deinit();
    try std.testing.expectEqualStrings("aborted", parsed_conflict.value.status);
    const conflict = parsed_conflict.value.conflict.?;
    try std.testing.expectEqualStrings("docs", conflict.table);
    try std.testing.expectEqualStrings("doc:a", conflict.key);
    try std.testing.expectEqual(@as(?u64, 7), conflict.expected_version);
    try std.testing.expect(conflict.current_version.? >= 8);
    try std.testing.expectEqualStrings("version_conflict", conflict.kind);
    try std.testing.expectEqualStrings("prepare", conflict.participant.?.phase.?);
}

test "api http server surfaces structured participant diagnostics for unavailable transaction commits" {
    const alloc = std.testing.allocator;

    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .status = status,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }
    };

    const FakeWrites = struct {
        fn source(_: *@This()) table_writes.TableWriteSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .batch = batch,
                    .commit_transaction = commitTransaction,
                    .commit_transaction_with_id = commitTransactionWithId,
                    .txn_begin_group_local = beginGroup,
                    .txn_prepare_group_local = prepareGroup,
                    .txn_resolve_group_local = resolveGroup,
                    .txn_status_group_local = statusGroup,
                },
            };
        }

        fn batch(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: db_mod.types.BatchRequest) anyerror!?void {
            return error.UnsupportedOperation;
        }

        fn commitTransaction(
            _: *anyopaque,
            _: std.mem.Allocator,
            _: []const distributed_txn.TableCommitRequest,
            _: db_mod.types.SyncLevel,
        ) anyerror!?distributed_txn.CommitOutcome {
            return .{
                .conflict = .{
                    .table_name = "docs",
                    .key = "",
                    .message = "participant unavailable",
                    .group_id = 7001,
                    .phase = .prepare,
                },
            };
        }

        fn commitTransactionWithId(
            ptr: *anyopaque,
            txn_alloc: std.mem.Allocator,
            _: db_mod.types.TxnId,
            _: u64,
            tables: []const distributed_txn.TableCommitRequest,
            sync_level: db_mod.types.SyncLevel,
        ) anyerror!?distributed_txn.CommitOutcome {
            return commitTransaction(ptr, txn_alloc, tables, sync_level);
        }

        fn beginGroup(_: *anyopaque, _: std.mem.Allocator, _: u64, _: []const u8, _: db_mod.types.TxnId, _: u64, _: u64, _: bool, _: []const []const u8) anyerror!?void {
            return error.UnsupportedOperation;
        }

        fn prepareGroup(_: *anyopaque, _: std.mem.Allocator, _: u64, _: []const u8, _: db_mod.types.TxnId, _: u64, _: db_mod.types.TransactionIntentRequest) anyerror!?void {
            return error.UnsupportedOperation;
        }

        fn resolveGroup(_: *anyopaque, _: std.mem.Allocator, _: u64, _: []const u8, _: db_mod.types.TxnId, _: db_mod.types.TxnStatus, _: u64, _: u64, _: db_mod.types.SyncLevel) anyerror!?void {
            return error.UnsupportedOperation;
        }

        fn statusGroup(_: *anyopaque, _: std.mem.Allocator, _: u64, _: []const u8, _: db_mod.types.TxnId) anyerror!?db_mod.types.TxnStatus {
            return error.UnsupportedOperation;
        }
    };

    var source = FakeSource{};
    var writes = FakeWrites{};
    var server = ApiHttpServer.init(std.testing.allocator, .{}, source.iface(), null, writes.source());

    const commit_body = try test_contract_helpers.encodeTransactionCommitRequest(
        alloc,
        &.{},
        &.{.{ .table_name = "docs", .batch_json = "{\"inserts\":{}}" }},
        null,
    );
    defer alloc.free(commit_body);

    var resp = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.transactions_commit,
        .content_type = "application/json",
        .body = commit_body,
    });
    defer resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 409), resp.status);
    try std.testing.expectEqualStrings("application/json", resp.content_type.?);
    var parsed = try std.json.parseFromSlice(transactions_api.CommitResponse, alloc, resp.body, .{});
    defer parsed.deinit();
    const conflict = parsed.value.conflict.?;
    try std.testing.expectEqualStrings("participant_unavailable", conflict.kind);
    try std.testing.expectEqual(true, conflict.retryable);
    try std.testing.expectEqual(@as(?u32, 50), conflict.retry_after_ms);
    try std.testing.expectEqualStrings("participant", conflict.retry_scope.?);
    try std.testing.expect(conflict.participant != null);
    try std.testing.expectEqual(@as(?u64, 7001), conflict.participant.?.group_id);
    try std.testing.expectEqualStrings("prepare", conflict.participant.?.phase.?);
}

