    const alloc = std.testing.allocator;
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();
    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/api-transaction-auth", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();
    try db.batch(.{
        .writes = &.{
            .{ .key = "doc:visible", .value = "{\"tenant_id\":\"t1\",\"title\":\"visible\"}" },
            .{ .key = "doc:hidden", .value = "{\"tenant_id\":\"t2\",\"title\":\"hidden\"}" },
        },
        .timestamp_ns = 7,
    });
    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }
    };

    var read_source = table_reads.BoundTableReadSource.init("docs", 1, &db, raft_mod.read_gate.noopReadableLeaseRequester());
    var source = FakeSource{};
    const secret = "transaction-principal-secret";
    var server = ApiHttpServer.init(alloc, .{
        .auth_enabled = true,
        .trusted_principal_secret = secret,
        .trusted_principal_issuer = "trusted-upstream",
    }, source.iface(), read_source.source(), null);
    defer server.deinit();

    const now: i64 = @intCast(@divFloor(nowNs(), std.time.ns_per_s));
    const alice_payload = try std.fmt.allocPrint(
        alloc,
        \\{{"iss":"trusted-upstream","sub":"user:alice","tables":["docs"],"operations":["read"],"row_filter":{{"docs":{{"term":{{"tenant_id":"t1"}}}}}},"iat":{d},"exp":{d}}}
    ,
        .{ now, now + 60 },
    );
    defer alloc.free(alice_payload);
    const alice_token = try encodeTrustedPrincipalToken(alloc, secret, alice_payload);
    defer alloc.free(alice_token);
    const alice_headers = [_]http_common.RequestHeader{
        .{ .name = trusted_principal_header, .value = alice_token },
    };

    const bob_payload = try std.fmt.allocPrint(
        alloc,
        \\{{"iss":"trusted-upstream","sub":"user:bob","tables":["docs"],"operations":["read","write"],"iat":{d},"exp":{d}}}
    ,
        .{ now, now + 60 },
    );
    defer alloc.free(bob_payload);
    const bob_token = try encodeTrustedPrincipalToken(alloc, secret, bob_payload);
    defer alloc.free(bob_token);
    const bob_headers = [_]http_common.RequestHeader{
        .{ .name = trusted_principal_header, .value = bob_token },
    };

    var begin_resp = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.transactions_begin,
        .headers = &alice_headers,
        .content_type = "application/json",
        .body = "{}",
    });
    defer begin_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 201), begin_resp.status);
    var parsed_begin = try std.json.parseFromSlice(transactions_api.BeginResponse, alloc, begin_resp.body, .{});
    defer parsed_begin.deinit();
    const session_uri = try std.fmt.allocPrint(alloc, "{s}{s}", .{
        routes.Routes.transactions_prefix,
        parsed_begin.value.transaction_id,
    });
    defer alloc.free(session_uri);
    var cross_principal = try server.handle(.{
        .method = .GET,
        .uri = session_uri,
        .headers = &bob_headers,
    });
    defer cross_principal.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 404), cross_principal.status);

    const write_uri = try std.fmt.allocPrint(alloc, "{s}{s}", .{
        session_uri,
        routes.Routes.transactions_write_suffix,
    });
    defer alloc.free(write_uri);
    var denied_write = try server.handle(.{
        .method = .POST,
        .uri = write_uri,
        .headers = &alice_headers,
        .content_type = "application/json",
        .body = "{\"table\":\"docs\",\"key\":\"doc:new\",\"document\":{\"tenant_id\":\"t1\"}}",
    });
    defer denied_write.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 403), denied_write.status);

    const read_uri = try std.fmt.allocPrint(alloc, "{s}{s}", .{
        session_uri,
        routes.Routes.transactions_read_suffix,
    });
    defer alloc.free(read_uri);
    var hidden_read = try server.handle(.{
        .method = .POST,
        .uri = read_uri,
        .headers = &alice_headers,
        .content_type = "application/json",
        .body = "{\"table\":\"docs\",\"key\":\"doc:hidden\",\"version\":\"0\"}",
    });
    defer hidden_read.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), hidden_read.status);
    var parsed_hidden = try std.json.parseFromSlice(transactions_api.StageReadResponse, alloc, hidden_read.body, .{});
    defer parsed_hidden.deinit();
    try std.testing.expectEqualStrings("0", parsed_hidden.value.snapshot.version);
    try std.testing.expect(parsed_hidden.value.snapshot.document == .null);

    var denied_table_read = try server.handle(.{
        .method = .POST,
        .uri = read_uri,
        .headers = &alice_headers,
        .content_type = "application/json",
        .body = "{\"table\":\"secrets\",\"key\":\"doc:a\",\"version\":\"0\"}",
    });
    defer denied_table_read.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 403), denied_table_read.status);

    var alice_list = try server.handle(.{
        .method = .GET,
        .uri = routes.Routes.transactions,
        .headers = &alice_headers,
    });
    defer alice_list.deinit(alloc);
    var parsed_alice_list = try std.json.parseFromSlice(transactions_api.SessionListResponse, alloc, alice_list.body, .{});
    defer parsed_alice_list.deinit();
    try std.testing.expectEqual(@as(usize, 1), parsed_alice_list.value.session_count);

    var bob_list = try server.handle(.{
        .method = .GET,
        .uri = routes.Routes.transactions,
        .headers = &bob_headers,
    });
    defer bob_list.deinit(alloc);
    var parsed_bob_list = try std.json.parseFromSlice(transactions_api.SessionListResponse, alloc, bob_list.body, .{});
    defer parsed_bob_list.deinit();
    try std.testing.expectEqual(@as(usize, 0), parsed_bob_list.value.session_count);

    var denied_cleanup = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.transactions_cleanup,
        .headers = &alice_headers,
    });
    defer denied_cleanup.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 403), denied_cleanup.status);
}

test "api http server persists SQL catalog session state through transaction session routes" {
    const alloc = std.testing.allocator;
    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{ .status = status },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(alloc, .{}, source.iface(), null, null);
    defer server.deinit();

    var begin_resp = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.transactions_begin,
        .content_type = "application/json",
        .body = "{}",
    });
    defer begin_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 201), begin_resp.status);
    var parsed_begin = try std.json.parseFromSlice(transactions_api.BeginResponse, alloc, begin_resp.body, .{});
    defer parsed_begin.deinit();
    const txn_id_hex = parsed_begin.value.transaction_id;
    const txn_id = try distributed_txn.parseTxnIdHex(txn_id_hex);

    var set_path = try server.applyRelationalSqlDdlInTransactionSession(txn_id, "SET search_path TO analytics, public;");
    defer set_path.deinit(alloc);
    try std.testing.expect(set_path.noop);

    const info_uri = try std.fmt.allocPrint(alloc, "{s}{s}", .{ routes.Routes.transactions_prefix, txn_id_hex });
    defer alloc.free(info_uri);
    var info_after_set = try server.handle(.{ .method = .GET, .uri = info_uri });
    defer info_after_set.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), info_after_set.status);
    var parsed_info_after_set = try std.json.parseFromSlice(transactions_api.SessionDetailsResponse, alloc, info_after_set.body, .{});
    defer parsed_info_after_set.deinit();
    const base_sql_session = parsed_info_after_set.value.sql_session orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("default", base_sql_session.current_database_name);
    try std.testing.expectEqual(@as(usize, 2), base_sql_session.search_path.len);
    try std.testing.expectEqualStrings("analytics", base_sql_session.search_path[0]);
    try std.testing.expectEqualStrings("public", base_sql_session.search_path[1]);
    try std.testing.expect(!base_sql_session.transaction_local_search_path);

    const savepoint_uri = try std.fmt.allocPrint(alloc, "{s}{s}{s}", .{ routes.Routes.transactions_prefix, txn_id_hex, routes.Routes.transactions_savepoints_suffix });
    defer alloc.free(savepoint_uri);
    var savepoint_resp = try server.handle(.{ .method = .POST, .uri = savepoint_uri, .body = "" });
    defer savepoint_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), savepoint_resp.status);
    var parsed_savepoint = try std.json.parseFromSlice(transactions_api.SavepointStatusResponse, alloc, savepoint_resp.body, .{});
    defer parsed_savepoint.deinit();

    var set_local_path = try server.applyRelationalSqlDdlInTransactionSession(txn_id, "SET LOCAL search_path TO tenant_schema, public;");
    defer set_local_path.deinit(alloc);
    try std.testing.expect(set_local_path.noop);
    var set_local_setting = try server.applyRelationalSqlDdlInTransactionSession(txn_id, "SET LOCAL app.tenant_id = 'tenant-b';");
    defer set_local_setting.deinit(alloc);
    try std.testing.expect(set_local_setting.noop);

    var info_after_local = try server.handle(.{ .method = .GET, .uri = info_uri });
    defer info_after_local.deinit(alloc);
    var parsed_info_after_local = try std.json.parseFromSlice(transactions_api.SessionDetailsResponse, alloc, info_after_local.body, .{});
    defer parsed_info_after_local.deinit();
    const local_sql_session = parsed_info_after_local.value.sql_session orelse return error.TestUnexpectedResult;
    try std.testing.expect(local_sql_session.transaction_local_search_path);
    try std.testing.expect(local_sql_session.transaction_local_settings);
    try std.testing.expectEqualStrings("tenant_schema", local_sql_session.search_path[0]);
    try std.testing.expect(local_sql_session.transaction_local_search_path_base != null);
    try std.testing.expectEqualStrings("analytics", local_sql_session.transaction_local_search_path_base.?[0]);
    try std.testing.expect(local_sql_session.transaction_local_settings_base != null);
    try std.testing.expectEqual(@as(usize, 0), local_sql_session.transaction_local_settings_base.?.len);
    try std.testing.expectEqual(@as(usize, 1), local_sql_session.settings.len);
    try std.testing.expectEqualStrings("app.tenant_id", local_sql_session.settings[0].name);
    try std.testing.expectEqualStrings("tenant-b", local_sql_session.settings[0].value);

    const rollback_uri = try std.fmt.allocPrint(alloc, "{s}{s}{s}/{d}{s}", .{ routes.Routes.transactions_prefix, txn_id_hex, routes.Routes.transactions_savepoints_suffix, parsed_savepoint.value.savepoint_id, routes.Routes.transactions_rollback_suffix });
    defer alloc.free(rollback_uri);
    var rollback_resp = try server.handle(.{ .method = .POST, .uri = rollback_uri, .body = "" });
    defer rollback_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), rollback_resp.status);

    var info_after_rollback = try server.handle(.{ .method = .GET, .uri = info_uri });
    defer info_after_rollback.deinit(alloc);
    var parsed_info_after_rollback = try std.json.parseFromSlice(transactions_api.SessionDetailsResponse, alloc, info_after_rollback.body, .{});
    defer parsed_info_after_rollback.deinit();
    const restored_sql_session = parsed_info_after_rollback.value.sql_session orelse return error.TestUnexpectedResult;
    try std.testing.expect(!restored_sql_session.transaction_local_search_path);
    try std.testing.expect(!restored_sql_session.transaction_local_settings);
    try std.testing.expectEqualStrings("analytics", restored_sql_session.search_path[0]);
    try std.testing.expectEqualStrings("public", restored_sql_session.search_path[1]);
    try std.testing.expectEqual(@as(usize, 0), restored_sql_session.settings.len);
}

