test "api session maintenance recovers crash window after durable 2pc commit" {
    const alloc = std.testing.allocator;
    const session_path = "/tmp/antfly-api-http-session-post-commit-recovery";
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    std.Io.Dir.cwd().deleteTree(io_impl.io(), session_path) catch {};
    defer std.Io.Dir.cwd().deleteTree(io_impl.io(), session_path) catch {};

    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{ .ptr = undefined, .vtable = &.{ .status = status } };
        }
        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }
    };
    const FakeWrites = struct {
        durable: ?*transactions_api.DurableSessionStore = null,
        commit_calls: usize = 0,
        acknowledge_calls: usize = 0,

        fn source(self: *@This()) table_writes.TableWriteSource {
            return .{ .ptr = self, .vtable = &.{
                .batch = batch,
                .commit_transaction_with_id = commitTransactionWithId,
                .acknowledge_transaction_commit = acknowledgeTransactionCommit,
            } };
        }
        fn batch(_: *anyopaque, _: std.mem.Allocator, _: []const u8, _: db_mod.types.BatchRequest) anyerror!?void {
            return error.TestUnexpectedResult;
        }
        fn commitTransactionWithId(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            _: db_mod.types.TxnId,
            _: u64,
            _: []const distributed_txn.TableCommitRequest,
            _: db_mod.types.SyncLevel,
        ) anyerror!?distributed_txn.CommitOutcome {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.commit_calls += 1;
            if (self.commit_calls == 1) self.durable.?.fail_writes_for_test = true;
            return .{ .committed = .{
                .participant_count = 1,
                .coordinator_group_id = 7001,
                .coordinator_table_name = "docs",
            } };
        }
        fn acknowledgeTransactionCommit(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            _: db_mod.types.TxnId,
            _: u64,
            _: []const u8,
        ) anyerror!?void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.acknowledge_calls += 1;
            return {};
        }
    };

    var source = FakeSource{};
    var writes = FakeWrites{};
    var server = try ApiHttpServer.initWithConfig(alloc, .{ .session_store_path = session_path }, source.iface(), null, writes.source());
    defer server.deinit();
    writes.durable = server.opened_session_store.?.durableStore();

    var begin = try server.handle(.{ .method = .POST, .uri = routes.Routes.transactions_begin, .content_type = "application/json", .body = "{}" });
    defer begin.deinit(alloc);
    var parsed_begin = try std.json.parseFromSlice(transactions_api.BeginResponse, alloc, begin.body, .{});
    defer parsed_begin.deinit();
    const commit_uri = try std.fmt.allocPrint(alloc, "{s}{s}{s}", .{
        routes.Routes.transactions_prefix,
        parsed_begin.value.transaction_id,
        routes.Routes.transactions_commit_suffix,
    });
    defer alloc.free(commit_uri);
    const batch_body = try test_contract_helpers.normalizeBatchRequest(alloc, "{\"inserts\":{\"counter\":{\"value\":1}}}");
    defer alloc.free(batch_body);
    const body = try test_contract_helpers.encodeTransactionCommitRequest(
        alloc,
        &.{},
        &.{.{ .table_name = "docs", .batch_json = batch_body }},
        null,
    );
    defer alloc.free(body);

    var first = try server.handle(.{ .method = .POST, .uri = commit_uri, .content_type = "application/json", .body = body });
    defer first.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 503), first.status);
    try std.testing.expectEqual(@as(usize, 1), writes.commit_calls);
    try std.testing.expectEqual(@as(usize, 0), writes.acknowledge_calls);

    writes.durable.?.fail_writes_for_test = false;
    try server.runSessionMaintenanceOnce();
    try std.testing.expectEqual(@as(usize, 2), writes.commit_calls);
    try std.testing.expectEqual(@as(usize, 1), writes.acknowledge_calls);

    var retry = try server.handle(.{ .method = .POST, .uri = commit_uri, .content_type = "application/json", .body = body });
    defer retry.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), retry.status);
    try std.testing.expectEqual(@as(usize, 2), writes.commit_calls);
}

test "api http server enforces configured savepoint limits and exposes remaining capacity" {
    const alloc = std.testing.allocator;
    const path = try uniqueTestTmpPathAlloc(alloc, "antfly-api-http-session-savepoint-limit");
    defer alloc.free(path);
    const session_path = try uniqueTestTmpPathAlloc(alloc, "antfly-api-http-session-savepoint-limit-sessions");
    defer alloc.free(session_path);
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch {};
    std.Io.Dir.cwd().deleteTree(io_impl.io(), session_path) catch {};

    var db = try db_mod.DB.open(alloc, path, .{});
    defer {
        db.close();
        std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch {};
    }
    defer std.Io.Dir.cwd().deleteTree(io_impl.io(), session_path) catch {};

    try db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"alpha\"}" }},
        .timestamp_ns = 7,
    });
    var table_source = table_writes.BoundTableWriteSource.init("docs", &db);

    const FakeSource = struct {
        fn iface(_: *@This()) StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .status = status,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }
    };

    var source = FakeSource{};
    var server = try ApiHttpServer.initWithConfig(
        alloc,
        .{
            .session_store_path = session_path,
            .session_savepoint_limit = 1,
        },
        source.iface(),
        null,
        table_source.source(),
    );
    defer server.deinit();

    var begin_resp = try server.handle(.{
        .method = .POST,
        .uri = routes.Routes.transactions_begin,
        .content_type = "application/json",
        .body = "{}",
    });
    defer begin_resp.deinit(alloc);
    var parsed_begin = try std.json.parseFromSlice(transactions_api.BeginResponse, alloc, begin_resp.body, .{});
    defer parsed_begin.deinit();
    const txn_id_hex = parsed_begin.value.transaction_id;

    const info_uri = try std.fmt.allocPrint(alloc, "{s}{s}", .{ routes.Routes.transactions_prefix, txn_id_hex });
    defer alloc.free(info_uri);
    var info_before = try server.handle(.{
        .method = .GET,
        .uri = info_uri,
    });
    defer info_before.deinit(alloc);
    var parsed_info_before = try std.json.parseFromSlice(transactions_api.SessionStatusResponse, alloc, info_before.body, .{ .ignore_unknown_fields = true });
    defer parsed_info_before.deinit();
    try std.testing.expectEqual(@as(?usize, 1), parsed_info_before.value.savepoint_limit);
    try std.testing.expectEqual(@as(?usize, 1), parsed_info_before.value.remaining_savepoints);

    const savepoint_uri = try std.fmt.allocPrint(alloc, "{s}{s}{s}", .{
        routes.Routes.transactions_prefix,
        txn_id_hex,
        routes.Routes.transactions_savepoints_suffix,
    });
    defer alloc.free(savepoint_uri);
    var savepoint_resp = try server.handle(.{
        .method = .POST,
        .uri = savepoint_uri,
        .body = "",
    });
    defer savepoint_resp.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 200), savepoint_resp.status);

    var info_after = try server.handle(.{
        .method = .GET,
        .uri = info_uri,
    });
    defer info_after.deinit(alloc);
    var parsed_info_after = try std.json.parseFromSlice(transactions_api.SessionStatusResponse, alloc, info_after.body, .{ .ignore_unknown_fields = true });
    defer parsed_info_after.deinit();
    try std.testing.expectEqual(@as(?usize, 1), parsed_info_after.value.savepoint_limit);
    try std.testing.expectEqual(@as(?usize, 0), parsed_info_after.value.remaining_savepoints);

    var savepoint_again = try server.handle(.{
        .method = .POST,
        .uri = savepoint_uri,
        .body = "",
    });
    defer savepoint_again.deinit(alloc);
    try std.testing.expectEqual(@as(u16, 409), savepoint_again.status);
    try std.testing.expect(std.mem.indexOf(u8, savepoint_again.body, "savepoint limit exceeded") != null);
}

