        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(
        alloc,
        .{},
        source.iface(),
        null,
        null,
    );

    var resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/indexes/manual_alg",
        .content_type = "application/json",
        .body = "{\"name\":\"manual_alg\",\"type\":\"algebraic\",\"derive_from_schema\":true,\"materializations\":[]}",
    });
    defer resp.deinit(alloc);

    try std.testing.expectEqual(@as(u16, 400), resp.status);
    try std.testing.expectEqual(@as(u32, 0), source.create_index_calls.load(.monotonic));
    try std.testing.expectEqual(@as(u32, 0), source.projection_wait_calls.load(.monotonic));
}

test "api http server serves provisioned index runtime backfill status across shards" {
    const alloc = std.testing.allocator;
    const ProvisionedIndexStatusResponse = struct {
        const Stats = struct {
            rebuilding: ?bool = null,
            backfill_active: ?bool = null,
            doc_count: ?u64 = null,
            total_indexed: ?u64 = null,
        };

        config: std.json.Value,
        status: Stats,
        shard_status: struct {
            @"7001": ?Stats = null,
            @"7002": ?Stats = null,
            local: ?Stats = null,
        },
    };
    const path = try uniqueTestTmpPathAlloc(alloc, "antfly-api-http-provisioned-index-status");
    defer alloc.free(path);
    var io_impl = std.Io.Threaded.init(std.heap.page_allocator, .{});
    defer io_impl.deinit();
    std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch {};
    defer std.Io.Dir.cwd().deleteTree(io_impl.io(), path) catch {};

    const left_path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, path, 7001);
    defer alloc.free(left_path);
    const right_path = try metadata_mod.groupDbPathFromReplicaRoot(alloc, path, 7002);
    defer alloc.free(right_path);

    var left_db = try db_mod.DB.open(alloc, left_path, .{
        .start_index_workers = false,
        .identity_namespace = .{ .table_id = 7, .shard_id = 7001, .range_id = 7001 },
    });
    var right_db = try db_mod.DB.open(alloc, right_path, .{
        .start_index_workers = false,
        .identity_namespace = .{ .table_id = 7, .shard_id = 7002, .range_id = 7002 },
    });
    try left_db.updateRange(.{ .start = "", .end = "doc:m" });
    try right_db.updateRange(.{ .start = "doc:m", .end = "" });

    try left_db.batch(.{
        .writes = &.{.{ .key = "doc:a", .value = "{\"title\":\"alpha\"}" }},
    });
    try right_db.batch(.{
        .writes = &.{.{ .key = "doc:z", .value = "{\"title\":\"zeta\"}" }},
    });
    try left_db.addIndex(.{
        .name = "search_idx",
        .kind = .full_text,
        .config_json = "{}",
    });
    try right_db.addIndex(.{
        .name = "search_idx",
        .kind = .full_text,
        .config_json = "{}",
    });

    const left_index_entry = left_db.core.index_manager.textIndexEntry("search_idx") orelse return error.TestUnexpectedResult;
    const left_rebuild_state = db_mod.backfill_state.RebuildState.init(left_index_entry.rebuild_root_path);
    try left_rebuild_state.update("doc:h");
    const right_index_entry = right_db.core.index_manager.textIndexEntry("search_idx") orelse return error.TestUnexpectedResult;
    const right_rebuild_state = db_mod.backfill_state.RebuildState.init(right_index_entry.rebuild_root_path);
    try right_rebuild_state.update("doc:z");
    right_db.close();
    left_db.close();
    const FakeCatalog = struct {
        fn iface() table_catalog.CatalogSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn adminSnapshot(_: *anyopaque) !metadata_api.AdminSnapshot {
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = @constCast((&[_]metadata_table_manager.TableRecord{.{
                    .table_id = 7,
                    .name = "docs",
                    .placement_role = "data",
                }})[0..]),
                .ranges = @constCast((&[_]metadata_table_manager.RangeRecord{
                    .{ .group_id = 7001, .table_id = 7, .start_key = "", .end_key = "doc:m" },
                    .{ .group_id = 7002, .table_id = 7, .start_key = "doc:m", .end_key = null },
                })[0..]),
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    const FakeSource = struct {
        fn iface() StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .cached_admin_snapshot = cachedAdminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn adminSnapshot(_: *anyopaque) !metadata_api.AdminSnapshot {
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = @constCast((&[_]metadata_table_manager.TableRecord{.{
                    .table_id = 7,
                    .name = "docs",
                    .indexes_json = "{\"search_idx\":{\"type\":\"full_text\"}}",
                    .placement_role = "data",
                }})[0..]),
                .ranges = @constCast((&[_]metadata_table_manager.RangeRecord{
                    .{ .group_id = 7001, .table_id = 7, .start_key = "", .end_key = "doc:m" },
                    .{ .group_id = 7002, .table_id = 7, .start_key = "doc:m", .end_key = null },
                })[0..]),
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn cachedAdminSnapshot(ptr: *anyopaque) !?metadata_api.AdminSnapshot {
            return try adminSnapshot(ptr);
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    var read_source = table_reads.ProvisionedTableReadSource.init(path, FakeCatalog.iface(), raft_mod.read_gate.noopReadableLeaseRequester());
    var server = ApiHttpServer.init(std.testing.allocator, .{}, FakeSource.iface(), read_source.source(), null);

    var detail_resp = try server.handle(.{
        .method = .GET,
        .uri = "/tables/docs/indexes/search_idx",
    });
    defer detail_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), detail_resp.status);
    try std.testing.expectEqualStrings("application/json", detail_resp.content_type.?);
    var parsed_contract_detail = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, detail_resp.body, .{
        .allocate = .alloc_always,
    });
    defer parsed_contract_detail.deinit();
    try std.testing.expectEqualStrings("search_idx", parsed_contract_detail.value.object.get("config").?.object.get("name").?.string);
    var parsed_detail = try std.json.parseFromSlice(ProvisionedIndexStatusResponse, std.testing.allocator, detail_resp.body, .{
        .ignore_unknown_fields = true,
    });
    defer parsed_detail.deinit();
    try std.testing.expectEqualStrings("search_idx", parsed_detail.value.config.object.get("name").?.string);
    // Provisioned runtime status reopens shard DBs, so pending backfill is either
    // visible as active or already reflected in indexed document counts.
    if (parsed_detail.value.status.backfill_active) |active| {
        if (!active) try std.testing.expect((parsed_detail.value.status.total_indexed orelse 0) >= 1);
    }
    if (parsed_detail.value.status.rebuilding) |rebuilding| {
        if (!rebuilding) try std.testing.expect((parsed_detail.value.status.total_indexed orelse 0) >= 1);
    }
    if (parsed_detail.value.status.doc_count) |doc_count| try std.testing.expect(doc_count >= 1);
    if (parsed_detail.value.status.total_indexed) |total_indexed| try std.testing.expect(total_indexed >= 1);
    if (parsed_detail.value.shard_status.@"7001" orelse parsed_detail.value.shard_status.local) |provisioned_left_shard| {
        try std.testing.expectEqual(@as(?u64, 1), provisioned_left_shard.doc_count);
        if (provisioned_left_shard.backfill_active) |active| {
            if (!active) try std.testing.expectEqual(@as(?u64, 1), provisioned_left_shard.total_indexed);
        }
    }
    if (parsed_detail.value.shard_status.@"7002") |right_shard| {
        try std.testing.expectEqual(@as(?u64, 1), right_shard.doc_count);
        if (right_shard.backfill_active) |active| {
            if (!active) try std.testing.expectEqual(@as(?u64, 1), right_shard.total_indexed);
        }
    }
}

test "api http server serves database and namespace catalog routes" {
    const FakeSource = struct {
        tenant_created: bool = false,
        analytics_created: bool = false,
        ad_hoc_table_created: bool = false,
        default_database: metadata_table_manager.DatabaseRecord = .{
            .database_id = metadata_table_manager.deriveDatabaseId("default"),
            .name = "default",
            .settings_json = "{}",
        },
        tenant_database: metadata_table_manager.DatabaseRecord = .{
            .database_id = metadata_table_manager.deriveDatabaseId("tenant_ops"),
            .name = "tenant_ops",
            .settings_json = "{}",
        },
        public_namespace: metadata_table_manager.NamespaceRecord = .{
            .namespace_id = metadata_table_manager.deriveNamespaceId(metadata_table_manager.deriveDatabaseId("default"), "public"),
            .database_id = metadata_table_manager.deriveDatabaseId("default"),
            .name = "public",
        },
        analytics_namespace: metadata_table_manager.NamespaceRecord = .{
            .namespace_id = metadata_table_manager.deriveNamespaceId(metadata_table_manager.deriveDatabaseId("tenant_ops"), "analytics"),
            .database_id = metadata_table_manager.deriveDatabaseId("tenant_ops"),
            .name = "analytics",
        },
        docs_table: metadata_table_manager.TableRecord = .{
            .table_id = tables_api.deriveQualifiedTableId("default", "public", "docs"),
            .name = "docs",
            .database_name = "default",
            .namespace_name = "public",
            .indexes_json = "{}",
        },
        events_table: metadata_table_manager.TableRecord = .{
            .table_id = tables_api.deriveQualifiedTableId("tenant_ops", "analytics", "events"),
            .name = "events",
            .database_name = "tenant_ops",
            .namespace_name = "analytics",
            .indexes_json = "{\"search_idx\":{\"type\":\"full_text\"}}",
        },
        ad_hoc_table: metadata_table_manager.TableRecord = .{
            .table_id = tables_api.deriveQualifiedTableId("tenant_ops", "analytics", "new_events"),
            .name = "new_events",
            .database_name = "tenant_ops",
            .namespace_name = "analytics",
            .indexes_json = "{}",
        },
        database_buf: [2]metadata_table_manager.DatabaseRecord = undefined,
        namespace_buf: [2]metadata_table_manager.NamespaceRecord = undefined,
        table_buf: [3]metadata_table_manager.TableRecord = undefined,

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                    .apply_database_catalog_plan = applyDatabaseCatalogPlan,
                    .create_namespace = createNamespace,
                    .drop_namespace = dropNamespace,
                    .create_catalog_table = createCatalogTable,
                    .drop_catalog_table = dropCatalogTable,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.database_buf[0] = self.default_database;
            var database_len: usize = 1;
            if (self.tenant_created) {
                self.database_buf[database_len] = self.tenant_database;
                database_len += 1;
            }
            self.namespace_buf[0] = self.public_namespace;
            var namespace_len: usize = 1;
            if (self.analytics_created) {
                self.namespace_buf[namespace_len] = self.analytics_namespace;
                namespace_len += 1;
            }
            self.table_buf[0] = self.docs_table;
            var table_len: usize = 1;
            if (self.analytics_created) {
                self.table_buf[table_len] = self.events_table;
                table_len += 1;
            }
            if (self.analytics_created and self.ad_hoc_table_created) {
                self.table_buf[table_len] = self.ad_hoc_table;
                table_len += 1;
            }
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .databases = self.database_buf[0..database_len],
                .namespaces = self.namespace_buf[0..namespace_len],
                .tables = self.table_buf[0..table_len],
                .ranges = &.{},
                .stores = &.{},
                .placement_intents = &.{},
                .split_transitions = &.{},
                .merge_transitions = &.{},
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}

        fn applyRelationalSqlDdl(ptr: *anyopaque, alloc: std.mem.Allocator, sql: []const u8) !tables_api.AppliedRelationalSqlDdlRecord {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            if (std.mem.eql(u8, sql, "CREATE DATABASE tenant_ops;")) {
                if (self.tenant_created) return error.DatabaseAlreadyExists;
                self.tenant_created = true;
                var applied = try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(alloc);
                applied.created_database = true;
                return applied;
            }
            if (std.mem.eql(u8, sql, "DROP DATABASE tenant_ops;")) {
                if (!self.tenant_created) return error.DatabaseNotFound;
                if (self.analytics_created) return error.DatabaseNotEmpty;
                self.tenant_created = false;
                var applied = try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(alloc);
                applied.dropped_database = true;
                return applied;
            }
            return error.UnsupportedSqlShape;
        }

        fn applyDatabaseCatalogPlan(ptr: *anyopaque, alloc: std.mem.Allocator, plan: sql_adapter.DatabaseCatalogPlan) !tables_api.AppliedRelationalSqlDdlRecord {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            switch (plan) {
                .create => |create| {
                    try std.testing.expectEqualStrings("tenant_ops", create.database_name);
                    if (self.tenant_created) return error.DatabaseAlreadyExists;
                    self.tenant_created = true;
                    var applied = try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(alloc);
                    applied.created_database = true;
                    return applied;
                },
                .drop => |drop| {
                    try std.testing.expectEqualStrings("tenant_ops", drop.database_name);
                    if (!self.tenant_created) return error.DatabaseNotFound;
                    if (self.analytics_created) return error.DatabaseNotEmpty;
                    self.tenant_created = false;
                    var applied = try tables_api.emptyAppliedRelationalSqlDdlRecordAlloc(alloc);
                    applied.dropped_database = true;
                    return applied;
                },
                .alter => return error.UnsupportedSqlShape,
            }
        }

        fn createNamespace(ptr: *anyopaque, database_name: []const u8, namespace_name: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("tenant_ops", database_name);
            try std.testing.expectEqualStrings("analytics", namespace_name);
            if (!self.tenant_created) return error.DatabaseNotFound;
            if (self.analytics_created) return error.NamespaceAlreadyExists;
            self.analytics_created = true;
        }

        fn dropNamespace(ptr: *anyopaque, database_name: []const u8, namespace_name: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("tenant_ops", database_name);
            try std.testing.expectEqualStrings("analytics", namespace_name);
            if (!self.tenant_created) return error.DatabaseNotFound;
            if (!self.analytics_created) return error.NamespaceNotFound;
            if (self.ad_hoc_table_created) return error.NamespaceNotEmpty;
            self.analytics_created = false;
        }

        fn createCatalogTable(ptr: *anyopaque, _: std.mem.Allocator, target: catalog_resources.TableTarget, _: tables_api.CreateTableRequest) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("tenant_ops", target.database_name);
            try std.testing.expectEqualStrings("analytics", target.namespace_name);
            try std.testing.expectEqualStrings("new_events", target.table_name);
            if (!self.tenant_created or !self.analytics_created) return error.NamespaceNotFound;
            if (self.ad_hoc_table_created) return error.TableAlreadyExists;
            self.ad_hoc_table_created = true;
        }

        fn dropCatalogTable(ptr: *anyopaque, _: std.mem.Allocator, target: catalog_resources.TableTarget) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("tenant_ops", target.database_name);
            try std.testing.expectEqualStrings("analytics", target.namespace_name);
            try std.testing.expectEqualStrings("new_events", target.table_name);
            if (!self.ad_hoc_table_created) return error.TableNotFound;
            self.ad_hoc_table_created = false;
        }
    };

    var source = FakeSource{};
    var server = ApiHttpServer.init(std.testing.allocator, .{}, source.iface(), null, null);

    var create_db = try server.handle(.{
        .method = .POST,
        .uri = "/databases/tenant_ops",
    });
    defer create_db.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 201), create_db.status);
    try std.testing.expect(std.mem.indexOf(u8, create_db.body, "\"name\":\"tenant_ops\"") != null);

    var list_db = try server.handle(.{
        .method = .GET,
        .uri = "/databases",
    });
    defer list_db.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), list_db.status);
    try std.testing.expect(std.mem.indexOf(u8, list_db.body, "\"name\":\"default\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, list_db.body, "\"name\":\"tenant_ops\"") != null);

    var create_namespace = try server.handle(.{
        .method = .POST,
        .uri = "/databases/tenant_ops/namespaces/analytics",
    });
    defer create_namespace.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 201), create_namespace.status);
    try std.testing.expect(std.mem.indexOf(u8, create_namespace.body, "\"database_name\":\"tenant_ops\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, create_namespace.body, "\"name\":\"analytics\"") != null);

    var list_namespaces = try server.handle(.{
        .method = .GET,
        .uri = "/databases/tenant_ops/namespaces",
    });
    defer list_namespaces.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), list_namespaces.status);
    try std.testing.expect(std.mem.indexOf(u8, list_namespaces.body, "\"name\":\"analytics\"") != null);

    var list_namespace_tables = try server.handle(.{
        .method = .GET,
        .uri = "/databases/tenant_ops/namespaces/analytics/tables",
    });
    defer list_namespace_tables.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), list_namespace_tables.status);
    try std.testing.expect(std.mem.indexOf(u8, list_namespace_tables.body, "\"name\":\"events\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, list_namespace_tables.body, "\"name\":\"docs\"") == null);

    var default_public_table = try server.handle(.{
        .method = .GET,
        .uri = "/databases/default/namespaces/public/tables/docs",
    });
    defer default_public_table.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), default_public_table.status);
    try std.testing.expect(std.mem.indexOf(u8, default_public_table.body, "\"name\":\"docs\"") != null);

    var non_default_table = try server.handle(.{
        .method = .GET,
        .uri = "/databases/tenant_ops/namespaces/analytics/tables/events",
    });
    defer non_default_table.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), non_default_table.status);
    try std.testing.expect(std.mem.indexOf(u8, non_default_table.body, "\"name\":\"events\"") != null);

    var non_default_table_subroute = try server.handle(.{
        .method = .GET,
        .uri = "/databases/tenant_ops/namespaces/analytics/tables/events/indexes",
    });
    defer non_default_table_subroute.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), non_default_table_subroute.status);

    var create_non_default_table = try server.handle(.{
        .method = .POST,
        .uri = "/databases/tenant_ops/namespaces/analytics/tables/new_events",
        .content_type = "application/json",
        .body = "{}",
    });
    defer create_non_default_table.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), create_non_default_table.status);
    try std.testing.expect(std.mem.indexOf(u8, create_non_default_table.body, "\"name\":\"new_events\"") != null);

    var drop_non_default_table = try server.handle(.{
        .method = .DELETE,
        .uri = "/databases/tenant_ops/namespaces/analytics/tables/new_events",
    });
    defer drop_non_default_table.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 204), drop_non_default_table.status);

    var drop_namespace = try server.handle(.{
        .method = .DELETE,
        .uri = "/databases/tenant_ops/namespaces/analytics",
    });
    defer drop_namespace.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 204), drop_namespace.status);

    var drop_db = try server.handle(.{
        .method = .DELETE,
        .uri = "/databases/tenant_ops",
    });
    defer drop_db.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 204), drop_db.status);
}

test "api http server serves table create and drop" {
    const FakeSource = struct {
        const default_indexes_json = "{\"full_text_index_v0\":{}}";
        const default_schema_json = "{\"kind\":\"demo\"}";

        created: bool = false,
        projection_wait_calls: std.atomic.Value(u32) = .init(0),
        schema_json: []const u8,
        owns_schema_json: bool = false,
        indexes_json: []const u8,
        owns_indexes_json: bool = false,
        table_record: metadata_table_manager.TableRecord = .{
            .table_id = 1,
            .name = "docs",
            .description = "docs table",
            .schema_json = default_schema_json,
            .indexes_json = default_indexes_json,
            .replication_sources_json = "[]",
            .placement_role = "data",
        },
        range_record: metadata_table_manager.RangeRecord = .{
            .group_id = 10,
            .table_id = 1,
            .start_key = "",
            .end_key = null,
        },
        empty_tables: [0]metadata_table_manager.TableRecord = .{},
        empty_ranges: [0]metadata_table_manager.RangeRecord = .{},
        empty_stores: [0]metadata_table_manager.StoreRecord = .{},
        empty_placements: [0]raft_reconciler.PlacementIntent = .{},
        empty_splits: [0]metadata_transition_state.SplitTransitionRecord = .{},
        empty_merges: [0]metadata_transition_state.MergeTransitionRecord = .{},

        pub fn init() @This() {
            return .{
                .schema_json = default_schema_json,
                .indexes_json = default_indexes_json,
            };
        }

        fn deinit(self: *@This(), alloc: std.mem.Allocator) void {
            if (self.owns_schema_json) alloc.free(self.schema_json);
            if (self.owns_indexes_json) alloc.free(self.indexes_json);
        }

        fn replaceSchemaJson(self: *@This(), alloc: std.mem.Allocator, next: []const u8, owns_next: bool) void {
            if (self.owns_schema_json) alloc.free(self.schema_json);
            self.schema_json = next;
            self.owns_schema_json = owns_next;
            self.table_record.schema_json = self.schema_json;
        }

        fn replaceIndexesJson(self: *@This(), alloc: std.mem.Allocator, next: []const u8, owns_next: bool) void {
            if (self.owns_indexes_json) alloc.free(self.indexes_json);
            self.indexes_json = next;
            self.owns_indexes_json = owns_next;
            self.table_record.indexes_json = self.indexes_json;
        }

        fn tableSlice(self: *@This()) []metadata_table_manager.TableRecord {
            return @as([*]metadata_table_manager.TableRecord, @ptrCast(&self.table_record))[0..1];
        }

        fn rangeSlice(self: *@This()) []metadata_table_manager.RangeRecord {
            return @as([*]metadata_table_manager.RangeRecord, @ptrCast(&self.range_record))[0..1];
        }

        fn iface(self: *@This()) StatusSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                    .create_table = createTable,
                    .drop_table = dropTable,
                    .update_schema = updateSchema,
                    .create_index = createIndex,
                    .drop_index = dropIndex,
                    .wait_table_projection = waitTableProjection,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn adminSnapshot(ptr: *anyopaque) !metadata_api.AdminSnapshot {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.table_record.schema_json = self.schema_json;
            self.table_record.indexes_json = self.indexes_json;
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = if (self.created)
                    @constCast(self.tableSlice())
                else
                    @constCast(self.empty_tables[0..]),
                .ranges = if (self.created)
                    @constCast(self.rangeSlice())
                else
                    @constCast(self.empty_ranges[0..]),
                .stores = @constCast(self.empty_stores[0..]),
                .placement_intents = @constCast(self.empty_placements[0..]),
                .split_transitions = @constCast(self.empty_splits[0..]),
                .merge_transitions = @constCast(self.empty_merges[0..]),
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}

        fn createTable(ptr: *anyopaque, inner_alloc: std.mem.Allocator, table_name: []const u8, req: tables_api.CreateTableRequest) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("docs", table_name);
            if (self.created) return error.TableAlreadyExists;
            try std.testing.expectEqual(@as(?u32, 1), req.num_shards);
            try std.testing.expectEqualStrings("docs table", req.description.?);
            try std.testing.expect(req.schema_json == null);
            try std.testing.expect(try indexes_api.equivalentIndexConfigJson(std.testing.allocator, tables_api.default_indexes_json, req.indexes_json.?));
            try std.testing.expect(req.replication_sources_json == null);
            self.created = true;
            self.replaceIndexesJson(inner_alloc, try inner_alloc.dupe(u8, req.indexes_json.?), true);
        }

        fn dropTable(ptr: *anyopaque, inner_alloc: std.mem.Allocator, table_name: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("docs", table_name);
            self.replaceSchemaJson(inner_alloc, default_schema_json, false);
            self.replaceIndexesJson(inner_alloc, default_indexes_json, false);
            self.created = false;
        }

        fn updateSchema(ptr: *anyopaque, inner_alloc: std.mem.Allocator, table_name: []const u8, schema_json: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("docs", table_name);
            try std.testing.expect(std.mem.indexOf(u8, schema_json, "\"document_schemas\"") != null);
            self.created = true;
            self.replaceSchemaJson(inner_alloc, try inner_alloc.dupe(u8, schema_json), true);
        }

        fn createIndex(ptr: *anyopaque, inner_alloc: std.mem.Allocator, table_name: []const u8, index_name: []const u8, index_json: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("docs", table_name);
            const next = try indexes_api.addIndexToTableIndexesJson(inner_alloc, self.indexes_json, index_name, index_json);
            self.replaceIndexesJson(inner_alloc, next, true);
        }

        fn dropIndex(ptr: *anyopaque, inner_alloc: std.mem.Allocator, table_name: []const u8, index_name: []const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("docs", table_name);
            const next = (try indexes_api.removeIndexFromTableIndexesJson(inner_alloc, self.indexes_json, index_name)) orelse return error.IndexNotFound;
            self.replaceIndexesJson(inner_alloc, next, true);
        }

        fn waitTableProjection(ptr: *anyopaque, table_name: []const u8, schema_json: ?[]const u8, indexes_json: ?[]const u8) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("docs", table_name);
            _ = self.projection_wait_calls.fetchAdd(1, .monotonic);
            if (schema_json) |expected| {
                try std.testing.expect(std.mem.eql(u8, self.table_record.schema_json, expected));
            }
            if (indexes_json) |expected| {
                try std.testing.expect(try indexes_api.equivalentIndexConfigJson(std.testing.allocator, self.indexes_json, expected));
            }
        }
    };

    var source = FakeSource.init();
    defer source.deinit(std.testing.allocator);
    var server = ApiHttpServer.init(std.testing.allocator, .{}, source.iface(), null, null);

    const create_body = try test_contract_helpers.encodeCreateTableRequest(std.testing.allocator, "docs table");
    defer std.testing.allocator.free(create_body);
    var create_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs",
        .content_type = "application/json",
        .body = create_body,
    });
    defer create_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), create_resp.status);
    try std.testing.expectEqualStrings("application/json", create_resp.content_type.?);
    var parsed_create = try std.json.parseFromSlice(metadata_openapi.Table, std.testing.allocator, create_resp.body, .{
        .ignore_unknown_fields = true,
    });
    defer parsed_create.deinit();
    try std.testing.expectEqualStrings("docs", parsed_create.value.name);
    try std.testing.expectEqualStrings("docs table", parsed_create.value.description.?);

    var duplicate_create_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs",
        .content_type = "application/json",
        .body = create_body,
    });
    defer duplicate_create_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 409), duplicate_create_resp.status);
    try std.testing.expectEqualStrings("text/plain", duplicate_create_resp.content_type.?);
    try std.testing.expectEqualStrings("table already exists", duplicate_create_resp.body);

    var drop_resp = try server.handle(.{
        .method = .DELETE,
        .uri = "/tables/docs",
    });
    defer drop_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 204), drop_resp.status);

    const update_schema_body = try test_contract_helpers.encodeSchemaUpdateRequest(std.testing.allocator);
    defer std.testing.allocator.free(update_schema_body);
    var update_resp = try server.handle(.{
        .method = .PUT,
        .uri = "/tables/docs/schema",
        .content_type = "application/json",
        .body = update_schema_body,
    });
    defer update_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), update_resp.status);
    try std.testing.expectEqualStrings("application/json", update_resp.content_type.?);
    var parsed_update = try std.json.parseFromSlice(std.json.Value, std.testing.allocator, update_resp.body, .{
        .allocate = .alloc_always,
    });
    defer parsed_update.deinit();
    try std.testing.expectEqualStrings("docs", parsed_update.value.object.get("name").?.string);
    try std.testing.expect(parsed_update.value.object.get("schema") != null);

    const create_index_body = try test_contract_helpers.encodeCreateIndexRequest(std.testing.allocator, "embed_idx");
    defer std.testing.allocator.free(create_index_body);
    var create_index_resp = try server.handle(.{
        .method = .POST,
        .uri = "/tables/docs/indexes/embed_idx",
        .content_type = "application/json",
        .body = create_index_body,
    });
    defer create_index_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 201), create_index_resp.status);
    try std.testing.expectEqualStrings("application/json", create_index_resp.content_type.?);
    try std.testing.expectEqualStrings("{}", create_index_resp.body);
    try std.testing.expect(std.mem.indexOf(u8, source.indexes_json, "\"embed_idx\"") != null);

    var detail_resp = try server.handle(.{
        .method = .GET,
        .uri = "/tables/docs/indexes/embed_idx",
    });
    defer detail_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 200), detail_resp.status);
    try std.testing.expectEqualStrings("application/json", detail_resp.content_type.?);
    var parsed_index = try std.json.parseFromSlice(struct {
        config: struct {
            name: []const u8,
        },
    }, std.testing.allocator, detail_resp.body, .{
        .ignore_unknown_fields = true,
    });
    defer parsed_index.deinit();
    try std.testing.expectEqualStrings("embed_idx", parsed_index.value.config.name);

    var drop_index_resp = try server.handle(.{
        .method = .DELETE,
        .uri = "/tables/docs/indexes/embed_idx",
    });
    defer drop_index_resp.deinit(std.testing.allocator);
    try std.testing.expectEqual(@as(u16, 201), drop_index_resp.status);
    try std.testing.expectEqualStrings("application/json", drop_index_resp.content_type.?);
    try std.testing.expectEqualStrings("{}", drop_index_resp.body);
    try std.testing.expectEqual(@as(u32, 1), source.projection_wait_calls.load(.monotonic));
}

