        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}

        fn restoreTable(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            table_name: []const u8,
            location_uri_arg: []const u8,
            connection: []const u8,
            artifact_backup_id: []const u8,
            manifest: *const backups_api.TableBackupManifest,
