            try std.testing.expectEqualStrings("docs", table_name);
            try std.testing.expect(location_uri_arg.len > 0);
            try std.testing.expectEqualStrings("test-backups", connection);
            try std.testing.expectEqualStrings("docs-snap-cluster", artifact_backup_id);
            try std.testing.expectEqualStrings("docs-snap-cluster", manifest.backup_id);
            try std.testing.expectEqualStrings("docs", manifest.table_name);
            self.state.ranges[0].completed_restore_fingerprint =
                metadata_table_manager.restoreCompletionFingerprint(
                    manifest.backup_id,
                    artifact_backup_id,
                    location_uri_arg,
                );
            self.state.table_restored = true;
        }

        fn restoreExtensions(
            ptr: *anyopaque,
            _: std.mem.Allocator,
            restored_installed: []const extension_domain.InstalledExtension,
            restored_members: []const extension_domain.ExtensionMember,
            restored_dependencies: []const extension_domain.ExtensionDependency,
        ) !void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            self.state.installed_count = restored_installed.len;
            self.state.member_count = restored_members.len;
            self.state.dependency_count = restored_dependencies.len;
        }
    };

    var state = State{
        .restore_progresses = .{.{
            .table_id = 1,
            .node_id = 1,
            .group_id = 7001,
            .backup_id = "docs-snap-cluster",
            .artifact_backup_id = "docs-snap-cluster",
            .location = location_uri,
            .snapshot_path = "artifacts/groups/7001.afb",
            .artifact_sha256 = "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855",
            .primary_restored = true,
            .runtime_repair_complete = true,
            .phase = "complete",
        }},
    };
    var source = FakeSource{ .state = &state };
    var node_config = try testBackupNodeConfig(alloc);
    defer node_config.deinit();
    var backend_runtime = try db_mod.background_runtime.BackendRuntime.init(alloc, .{});
    defer backend_runtime.deinit();
    var server = ApiHttpServer.init(alloc, .{ .node_config = &node_config, .backend_runtime = &backend_runtime }, source.iface(), null, null);
    defer server.deinit();
    try attachTestRestoreJobStore(alloc, &server, &tmp.sub_path, "restore-jobs");

    const restore_body = try std.fmt.allocPrint(
        alloc,
        "{{\"backup_id\":\"snap-cluster\",\"location\":\"{s}\",\"connection\":\"test-backups\"}}",
        .{location_uri},
    );
    defer alloc.free(restore_body);
    var restore_resp = try server.handle(.{
        .method = .POST,
        .uri = "/restore",
        .body = restore_body,
        .content_type = "application/json",
    });
    defer restore_resp.deinit(alloc);

    try std.testing.expectEqual(@as(u16, 202), restore_resp.status);
    const terminal_restore = try waitForTerminalRestoreJobAlloc(alloc, &server, restore_resp.body);
    defer alloc.free(terminal_restore);
    try std.testing.expect(state.table_restored);
    try std.testing.expectEqual(@as(usize, 1), state.installed_count);
    try std.testing.expectEqual(@as(usize, 1), state.member_count);
