            return error.UnsupportedOperation;
        }
        fn unsupportedTxnBeginGroupLocal(_: *anyopaque, _: std.mem.Allocator, _: u64, _: []const u8, _: db_mod.types.TxnId, _: u64, _: u64, _: bool, _: []const []const u8) anyerror!?void {
            return error.UnsupportedOperation;
        }
