    defer server.deinit();

    var parsed_hits = try parseTestQueryHitsAlloc(std.testing.allocator,
        \\[
        \\  {"_id":"doc:1","_source":{"customer_id":"cust:a","title":"Alpha"}}
        \\]
    );
    defer parsed_hits.deinit(std.testing.allocator);
