    };

    const FakeReads = struct {
        attempts_201: usize = 0,
        attempts_202: usize = 0,
        call_order: [2]u64 = .{ 0, 0 },
        call_count: usize = 0,

        fn source(self: *@This()) table_reads.TableReadSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .lookup = lookup,
                    .scan = scan,
                    .query = query,
                    .join_finalize_group_local = joinFinalizeGroupLocal,
