        .ptr = &fake_source,
        .vtable = &.{
            .status = FakeSource.status,
            .admin_snapshot = FakeSource.adminSnapshot,
            .free_admin_snapshot = FakeSource.freeAdminSnapshot,
        },
    }, null, null);
