}

test "api http server executes foreign right join query through registry" {
    const alloc = std.testing.allocator;

    const DummyForeign = struct {
        var saw_no_deadline = false;
        var saw_cancellation = false;

        fn destroy(ptr: *anyopaque, inner_alloc: std.mem.Allocator) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            inner_alloc.destroy(self);
        }

        fn query(_: *anyopaque, inner_alloc: std.mem.Allocator, params: foreign_mod.QueryParams) !foreign_mod.QueryResult {
            saw_no_deadline = params.execution_deadline_ns == null;
            saw_cancellation = params.cancellation != null;
            const rows = try inner_alloc.alloc(std.json.Value, 2);
            rows[0] = try parseOwnedJsonValueAlloc(inner_alloc, "{\"id\":\"cust:a\",\"name\":\"Alice\"}");
            rows[1] = try parseOwnedJsonValueAlloc(inner_alloc, "{\"id\":\"cust:b\",\"name\":\"Bob\"}");
            return .{ .rows = rows, .total = 2 };
        }

        fn statistics(_: *anyopaque, _: []const u8) !foreign_mod.TableStatistics {
            return .{ .row_count = 2, .size_bytes = 128 };
        }

        fn factory(inner_alloc: std.mem.Allocator, config: foreign_mod.Config) !foreign_mod.Source {
            var owned = config;
            defer owned.deinit(inner_alloc);
            const self = try inner_alloc.create(@This());
            return .{
                .ptr = self,
                .vtable = &.{
                    .deinit = destroy,
                    .query = query,
                    .statistics = statistics,
                },
            };
        }
    };

    var registry = foreign_mod.Registry{};
    defer registry.deinit(alloc);
    try registry.register(alloc, .postgres, DummyForeign.factory);

    const DummyStatus = struct {
        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{} };
        }
    };

    var server = ApiHttpServer.init(alloc, .{}, .{
        .ptr = undefined,
        .vtable = &.{ .status = DummyStatus.status },
    }, null, null);
    defer server.deinit();
    server.setForeignRegistry(&registry);
    var parsed_hits = try parseTestQueryHitsAlloc(alloc,
        \\[
        \\  {"_id":"order:1","_source":{"customer_id":"cust:a"}}
        \\]
    );
    defer parsed_hits.deinit(alloc);

    const join: ApiHttpServer.SupportedJoinRequest = .{
        .right_table = try alloc.dupe(u8, "pg_customers"),
        .join_type = .inner,
        .left_field = try alloc.dupe(u8, "customer_id"),
        .right_field = try alloc.dupe(u8, "id"),
    };
    defer {
        var owned = join;
        owned.deinit(alloc);
    }

    var foreign_config: foreign_mod.PostgresConfig = .{
        .dsn = try alloc.dupe(u8, "postgres://db"),
        .postgres_table = try alloc.dupe(u8, "customers"),
        .columns = &.{},
    };
    defer foreign_config.deinit(alloc);

    const dummy_source: table_reads.TableReadSource = .{
        .ptr = undefined,
        .vtable = undefined,
    };
    var cancellation = std.atomic.Value(bool).init(false);
    var right = try distributed_join.executeForeignRightJoinQuery(
        server.joinContext().withCancellation(&cancellation),
        &server.join_job_store,
        alloc,
        dummy_source,
        foreign_config,
        join,
        parsed_hits.values,
        .{},
    );
    defer right.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), right.hits.len);
    try std.testing.expectEqualStrings("cust:a", right.hits[0].object.get("_id").?.string);
    try std.testing.expectEqualStrings("Alice", testOwnedHitSourcePathValue(right.hits[0], "name").?.string);
    try std.testing.expect(DummyForeign.saw_no_deadline);
    try std.testing.expect(DummyForeign.saw_cancellation);
}

test "api http server executes direct foreign table query through registry" {
    const alloc = std.testing.allocator;
    const c = @cImport(@cInclude("stdlib.h"));
    try std.testing.expectEqual(@as(c_int, 0), c.setenv("PG_DSN", "postgres://resolved", 1));
    defer _ = c.unsetenv("PG_DSN");

    const DummyForeign = struct {
        var last_dsn: ?[]u8 = null;
        var saw_no_deadline = false;
        var saw_cancellation = false;
        var cancel_when_observed = false;

        fn destroy(ptr: *anyopaque, inner_alloc: std.mem.Allocator) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            inner_alloc.destroy(self);
        }

        fn query(_: *anyopaque, inner_alloc: std.mem.Allocator, params: foreign_mod.QueryParams) !foreign_mod.QueryResult {
            saw_no_deadline = params.execution_deadline_ns == null;
            saw_cancellation = params.cancellation != null;
            if (cancel_when_observed) {
                _ = params.cancellation orelse return error.ForeignQueryFailed;
                return error.Cancelled;
            }
            const rows = try inner_alloc.alloc(std.json.Value, 2);
            rows[0] = try parseOwnedJsonValueAlloc(inner_alloc, "{\"id\":\"cust:a\",\"name\":\"Alice\"}");
            rows[1] = try parseOwnedJsonValueAlloc(inner_alloc, "{\"id\":\"cust:b\",\"name\":\"Bob\"}");
            return .{ .rows = rows, .total = 2 };
        }

        fn statistics(_: *anyopaque, _: []const u8) !foreign_mod.TableStatistics {
            return .{ .row_count = 2, .size_bytes = 128 };
        }

        fn factory(inner_alloc: std.mem.Allocator, config: foreign_mod.Config) !foreign_mod.Source {
            if (last_dsn) |value| inner_alloc.free(value);
            last_dsn = try inner_alloc.dupe(u8, config.dsn);
            var owned = config;
            defer owned.deinit(inner_alloc);
            const self = try inner_alloc.create(@This());
            return .{
                .ptr = self,
                .vtable = &.{
                    .deinit = destroy,
                    .query = query,
                    .statistics = statistics,
                },
            };
        }
    };

    var registry = foreign_mod.Registry{};
    defer {
        if (DummyForeign.last_dsn) |value| alloc.free(value);
        registry.deinit(alloc);
    }
    try registry.register(alloc, .postgres, DummyForeign.factory);

    const DummyStatus = struct {
        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{} };
        }
    };

    var server = ApiHttpServer.init(alloc, .{}, .{
        .ptr = undefined,
        .vtable = &.{ .status = DummyStatus.status },
    }, null, null);
    defer server.deinit();
    server.setForeignRegistry(&registry);
    const dummy_source: table_reads.TableReadSource = .{
        .ptr = undefined,
        .vtable = undefined,
    };

    const body =
        \\{"fields":["name"],"limit":1,"offset":2,"order_by":[{"field":"name"}],"filter_query":{"term":"active","field":"status"},"foreign_sources":{"pg_customers":{"type":"postgres","dsn":"${secret:pg_dsn}","postgres_table":"customers","columns":[{"name":"status","type":"text"}]}}}
    ;

    try std.testing.expectError(
        error.Timeout,
        server.executeForeignPublicTableQueryIfAny(alloc, dummy_source, "pg_customers", body, null, null, 0, null),
    );
    try std.testing.expect(DummyForeign.last_dsn == null);

    var cancellation = std.atomic.Value(bool).init(false);
    const json = (try server.executeForeignPublicTableQueryIfAny(alloc, dummy_source, "pg_customers", body, null, null, null, &cancellation)).?;
    defer alloc.free(json);

    var parsed = try std.json.parseFromSlice(metadata_openapi.QueryResponses, alloc, json, .{});
    defer parsed.deinit();
    try std.testing.expectEqual(@as(usize, 1), parsed.value.responses.?.len);
    const response = parsed.value.responses.?[0];
    try std.testing.expectEqual(@as(i64, 2), response.hits.?.total.?.value);
    try std.testing.expectEqual(metadata_openapi.QueryHitsTotalRelation.exact, response.hits.?.total.?.relation);
    try std.testing.expectEqual(@as(usize, 2), response.hits.?.hits.?.len);
    try std.testing.expectEqualStrings("cust:a", response.hits.?.hits.?[0]._id);
    try std.testing.expectEqualStrings("Alice", testQueryHitSourcePathValue(response.hits.?.hits.?[0], "name").?.string);
    try std.testing.expectEqualStrings("postgres://resolved", DummyForeign.last_dsn.?);
    try std.testing.expect(DummyForeign.saw_no_deadline);
    try std.testing.expect(DummyForeign.saw_cancellation);

    DummyForeign.cancel_when_observed = true;
    defer DummyForeign.cancel_when_observed = false;
    cancellation.store(false, .release);
    try std.testing.expectError(
        error.Cancelled,
        server.executeForeignPublicTableQueryIfAny(
            alloc,
            dummy_source,
            "pg_customers",
            body,
            null,
            null,
            null,
            &cancellation,
        ),
    );
}

test "api http server executes direct foreign table aggregations through registry" {
    const alloc = std.testing.allocator;

    const DummyForeign = struct {
        var query_saw_no_deadline = false;
        var query_saw_cancellation = false;
        var aggregate_saw_no_deadline = false;
        var aggregate_saw_cancellation = false;

        fn destroy(ptr: *anyopaque, inner_alloc: std.mem.Allocator) void {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            inner_alloc.destroy(self);
        }

        fn query(ptr: *anyopaque, inner_alloc: std.mem.Allocator, params: foreign_mod.QueryParams) !foreign_mod.QueryResult {
            _ = ptr;
            query_saw_no_deadline = params.execution_deadline_ns == null;
            query_saw_cancellation = params.cancellation != null;
            const rows = try inner_alloc.alloc(std.json.Value, 1);
            rows[0] = try parseOwnedJsonValueAlloc(inner_alloc, "{\"id\":\"cust:a\",\"name\":\"Alice\",\"version\":1}");
            return .{ .rows = rows, .total = 1 };
        }

        fn aggregate(ptr: *anyopaque, inner_alloc: std.mem.Allocator, params: foreign_mod.AggregateParams) !foreign_mod.AggregateResult {
            _ = ptr;
            aggregate_saw_no_deadline = params.execution_deadline_ns == null;
            aggregate_saw_cancellation = params.cancellation != null;
            const results = try inner_alloc.alloc(foreign_mod.NamedValue, 2);
            results[0] = .{
                .name = try inner_alloc.dupe(u8, "version_stats"),
                .value = try parseOwnedJsonValueAlloc(inner_alloc, "{\"count\":2,\"min\":1,\"max\":2,\"avg\":1.5,\"sum\":3}"),
            };
            results[1] = .{
                .name = try inner_alloc.dupe(u8, "name_terms"),
                .value = try parseOwnedJsonValueAlloc(inner_alloc, "[{\"key\":\"Alice\",\"doc_count\":1},{\"key\":\"Bob\",\"doc_count\":1}]"),
            };
            return .{ .results = results };
        }

        fn statistics(_: *anyopaque, _: []const u8) !foreign_mod.TableStatistics {
            return .{ .row_count = 2, .size_bytes = 128 };
        }

        fn factory(inner_alloc: std.mem.Allocator, config: foreign_mod.Config) !foreign_mod.Source {
            var owned = config;
            defer owned.deinit(inner_alloc);
            const self = try inner_alloc.create(@This());
            return .{
                .ptr = self,
                .vtable = &.{
                    .deinit = destroy,
                    .query = query,
                    .aggregate = aggregate,
                    .statistics = statistics,
                },
            };
        }
    };

    var registry = foreign_mod.Registry{};
    defer registry.deinit(alloc);
    try registry.register(alloc, .postgres, DummyForeign.factory);

    const DummyStatus = struct {
        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{} };
        }
    };

    var server = ApiHttpServer.init(alloc, .{}, .{
        .ptr = undefined,
        .vtable = &.{ .status = DummyStatus.status },
    }, null, null);
    defer server.deinit();
    server.setForeignRegistry(&registry);
    const dummy_source: table_reads.TableReadSource = .{
        .ptr = undefined,
        .vtable = undefined,
    };

    const body =
        \\{"fields":["name"],"aggregations":{"version_stats":{"type":"stats","field":"version"},"name_terms":{"type":"terms","field":"name","size":5}},"foreign_sources":{"pg_customers":{"type":"postgres","dsn":"postgres://db","postgres_table":"customers","columns":[{"name":"version","type":"bigint"},{"name":"name","type":"text"}]}}}
    ;

    var cancellation = std.atomic.Value(bool).init(false);
    const json = (try server.executeForeignPublicTableQueryIfAny(alloc, dummy_source, "pg_customers", body, null, null, null, &cancellation)).?;
    defer alloc.free(json);

    var parsed = try std.json.parseFromSlice(metadata_openapi.QueryResponses, alloc, json, .{});
    defer parsed.deinit();
    try std.testing.expectEqual(@as(usize, 1), parsed.value.responses.?.len);
    const aggregations = parsed.value.responses.?[0].aggregations.?;
    try std.testing.expectEqual(@as(usize, 2), aggregations.map.count());
    const version_stats = aggregations.map.get("version_stats").?;
    try std.testing.expectEqual(@as(?i64, 2), version_stats.count);
    try std.testing.expectEqual(@as(?f32, 1), version_stats.min);
    try std.testing.expectEqual(@as(?f32, 2), version_stats.max);
    try std.testing.expectEqual(@as(?f32, 1.5), version_stats.avg);
    try std.testing.expectEqual(@as(?f32, 3), version_stats.sum);
    const name_terms = aggregations.map.get("name_terms").?;
    try std.testing.expectEqual(@as(usize, 2), name_terms.buckets.?.len);
    try std.testing.expectEqualStrings("Alice", name_terms.buckets.?[0].key);
    try std.testing.expectEqual(@as(i64, 1), name_terms.buckets.?[0].doc_count);
    try std.testing.expect(DummyForeign.query_saw_no_deadline);
    try std.testing.expect(DummyForeign.query_saw_cancellation);
    try std.testing.expect(DummyForeign.aggregate_saw_no_deadline);
    try std.testing.expect(DummyForeign.aggregate_saw_cancellation);
}

// Restored origin/main HTTP merge audit tests.
test "api http invalid query with sort diagnostic returns exact sort response" {
    const alloc = std.testing.allocator;
    db_mod.resetLastSortRejectionDiagnostic();
    db_mod.testing.recordSortRejectionDiagnostic(
        "_score",
        "invalid_sort_tuple",
        "non_numeric_score",
    );
    var resp = try invalidPublicQueryRequestResponse(alloc);
    defer resp.deinit(alloc);

    try std.testing.expectEqual(@as(u16, 422), resp.status);
    try std.testing.expectEqualStrings("application/json", resp.content_type.?);

    var parsed = try std.json.parseFromSlice(struct {
        status: u16,
        @"error": []const u8,
        message: []const u8,
        reason: []const u8,
        sort_rejection_reason: []const u8,
        sort_rejection_detail: []const u8,
        sort_rejection_field: []const u8,
    }, alloc, resp.body, .{});
    defer parsed.deinit();

    try std.testing.expectEqual(@as(u16, 422), parsed.value.status);
    try std.testing.expectEqualStrings("unsupported_exact_sort", parsed.value.@"error");
    try std.testing.expectEqualStrings("exact sort is unsupported for this query", parsed.value.message);
    try std.testing.expectEqualStrings("invalid_sort_tuple", parsed.value.reason);
    try std.testing.expectEqualStrings("invalid_sort_tuple", parsed.value.sort_rejection_reason);
    try std.testing.expectEqualStrings("invalid_sort_tuple", parsed.value.sort_rejection_detail);
    try std.testing.expectEqualStrings("_score", parsed.value.sort_rejection_field);
}

test "api http plain public query preserves outer absolute request deadline" {
    const alloc = std.testing.allocator;
    const outer_deadline_ns = platform_time.monotonicNs() + 10 * std.time.ns_per_s;

    const FakeSource = struct {
        fn iface() StatusSource {
            return .{
                .ptr = undefined,
                .vtable = &.{
                    .status = status,
                    .admin_snapshot = adminSnapshot,
                    .free_admin_snapshot = freeAdminSnapshot,
                },
            };
        }

        fn status(_: *anyopaque) !metadata_api.MetadataStatus {
            return .{ .metadata_group_id = 1, .metrics = .{}, .projected_stores = 1 };
        }

        fn adminSnapshot(_: *anyopaque) !metadata_api.AdminSnapshot {
            return .{
                .status = .{ .metadata_group_id = 1, .metrics = .{} },
                .tables = @constCast((&[_]metadata_table_manager.TableRecord{.{
                    .table_id = 1,
                    .name = "docs",
                    .schema_json = "{\"default_type\":\"doc\",\"document_schemas\":{\"doc\":{\"schema\":{\"type\":\"object\",\"properties\":{\"body\":{\"type\":\"text\"}}}}}}",
                    .indexes_json = "{}",
                    .placement_role = "data",
                }})[0..]),
                .ranges = @constCast((&[_]metadata_table_manager.RangeRecord{.{ .group_id = 10, .table_id = 1, .start_key = "", .end_key = null }})[0..]),
                .stores = @constCast((&[_]metadata_table_manager.StoreRecord{})[0..]),
                .placement_intents = @constCast((&[_]raft_reconciler.PlacementIntent{})[0..]),
                .split_transitions = @constCast((&[_]metadata_transition_state.SplitTransitionRecord{})[0..]),
                .merge_transitions = @constCast((&[_]metadata_transition_state.MergeTransitionRecord{})[0..]),
            };
        }

        fn freeAdminSnapshot(_: *anyopaque, _: *metadata_api.AdminSnapshot) void {}
    };

    const FakeReads = struct {
        expected_deadline_ns: u64,

        fn source(self: *@This()) table_reads.TableReadSource {
            return .{
                .ptr = self,
                .vtable = &.{
                    .lookup = lookup,
                    .scan = scan,
                    .query = query,
                },
            };
        }

        fn lookup(
            _: *anyopaque,
            _: std.mem.Allocator,
            _: []const u8,
            _: []const u8,
            _: db_mod.types.LookupOptions,
            _: raft_mod.ReadConsistency,
        ) anyerror!?table_reads.LookupResponse {
            return error.UnsupportedOperation;
        }

        fn scan(
            _: *anyopaque,
            _: std.mem.Allocator,
            _: []const u8,
            _: []const u8,
            _: []const u8,
            _: db_mod.types.ScanOptions,
            _: raft_mod.ReadConsistency,
        ) anyerror!?table_reads.ScanResponse {
            return error.UnsupportedOperation;
        }

        fn query(
            ptr: *anyopaque,
            inner_alloc: std.mem.Allocator,
            table_name: []const u8,
            req: db_mod.types.SearchRequest,
            consistency: raft_mod.ReadConsistency,
        ) anyerror!?query_api.QueryResponse {
            const self: *@This() = @ptrCast(@alignCast(ptr));
            try std.testing.expectEqualStrings("docs", table_name);
            try std.testing.expectEqual(raft_mod.ReadConsistency.read_index, consistency);
            try std.testing.expectEqual(self.expected_deadline_ns, req.execution_deadline_ns.?);
            return .{ .json = try inner_alloc.dupe(u8, "{\"hits\":[],\"total\":0}") };
        }
    };

    var reads = FakeReads{ .expected_deadline_ns = outer_deadline_ns };
    var server = ApiHttpServer.init(alloc, .{}, FakeSource.iface(), reads.source(), null);
    const body =
        \\{"query":{"match_all":{}},"timeout_ms":999999}
    ;
    var response = try server.executePlainPublicTableQuery(
        alloc,
        reads.source(),
        "docs",
        body,
        null,
        null,
        outer_deadline_ns,
        .{ .domain = .internal, .value = "" },
        null,
    );
    defer response.deinit(alloc);
    try std.testing.expectEqualStrings("{\"hits\":[],\"total\":0}", response.json);
}

test "api http public sort capability gate fails closed for uncovered observed dynamic fields" {
    const runtime_schema = storage_schema.TableSchema{};
    var covered = storage_schema.observedDynamicFieldCapability(null, "price", .{
        .field_type = .numeric,
        .doc_values = true,
        .sortable = true,
        .analyzer = "keyword",
    });
    covered.doc_value_coverage = "covered";
    covered.queryability_state = "queryable";
    storage_schema.refreshSortLifecycleState(&covered);
    const covered_set = table_reads.ObservedDynamicFieldCapabilitySet{
        .index_name = @constCast("full_text_index_v0"),
        .field_capabilities = @constCast((&[_]storage_schema.FieldCapability{covered})[0..]),
    };
    const price_order = [_]db_mod.types.SortField{.{ .field = "price" }};
    try validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &price_order,
        .primary_text_index_name = "full_text_index_v0",
    }, runtime_schema, &.{covered_set});

    const declared = storage_schema.observedDynamicFieldCapability(null, "price", .{
        .field_type = .numeric,
        .doc_values = true,
        .sortable = true,
        .analyzer = "keyword",
    });
    const declared_set = table_reads.ObservedDynamicFieldCapabilitySet{
        .index_name = @constCast("full_text_index_v0"),
        .field_capabilities = @constCast((&[_]storage_schema.FieldCapability{declared})[0..]),
    };
    db_mod.resetLastSortRejectionDiagnostic();
    try std.testing.expectError(error.UnsupportedExactSort, validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &price_order,
        .primary_text_index_name = "full_text_index_v0",
    }, runtime_schema, &.{declared_set}));
    var diagnostic = db_mod.takeLastSortRejectionDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("price", diagnostic.field);
    try std.testing.expectEqualStrings("missing_doc_values_coverage", diagnostic.reason);
    try std.testing.expectEqualStrings("observed_declared", diagnostic.detail);

    db_mod.resetLastSortRejectionDiagnostic();
    try std.testing.expectError(error.UnsupportedExactSort, validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &price_order,
        .primary_text_index_name = "full_text_index_v0",
    }, runtime_schema, &.{ covered_set, declared_set }));
    diagnostic = db_mod.takeLastSortRejectionDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("price", diagnostic.field);
    try std.testing.expectEqualStrings("missing_doc_values_coverage", diagnostic.reason);
    try std.testing.expectEqualStrings("observed_declared", diagnostic.detail);

    const declared_other_index = storage_schema.observedDynamicFieldCapability(null, "price", .{
        .field_type = .numeric,
        .doc_values = true,
        .sortable = true,
        .analyzer = "keyword",
    });
    const declared_other_index_set = table_reads.ObservedDynamicFieldCapabilitySet{
        .index_name = @constCast("full_text_index_v1"),
        .field_capabilities = @constCast((&[_]storage_schema.FieldCapability{declared_other_index})[0..]),
    };
    try validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &price_order,
        .primary_text_index_name = "full_text_index_v0",
    }, runtime_schema, &.{ covered_set, declared_other_index_set });

    db_mod.resetLastSortRejectionDiagnostic();
    try std.testing.expectError(error.UnsupportedExactSort, validatePublicQuerySortCapabilitiesAgainstRuntime(.{
        .order_by = &price_order,
    }, runtime_schema, &.{ covered_set, declared_other_index_set }));
    diagnostic = db_mod.takeLastSortRejectionDiagnostic() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("price", diagnostic.field);
    try std.testing.expectEqualStrings("missing_doc_values_coverage", diagnostic.reason);
    try std.testing.expectEqualStrings("observed_declared", diagnostic.detail);
}

